    private readonly IWebhookService? _webhooks;

    /// <summary>Fire an outbound webhook. Wrapped in try/catch so a
    /// slow / failed delivery NEVER blocks the parent API call from
    /// returning. WebhookService handles retry-with-backoff internally.</summary>
    private async Task FireWebhookAsync(Guid companyId, string eventType, object payload)
    {
        if (_webhooks == null) return;
        try { await _webhooks.TriggerAsync(companyId, eventType, payload); }
        catch (Exception ex) { _logger.LogWarning(ex, "Webhook {Event} fire-and-forget failed", eventType); }
    }

    /// <summary>บันทึก "ภาษีที่เราถูกหัก" ลงทะเบียนเครดิต ภ.ง.ด.50/51 อัตโนมัติ
    ///
    /// <para><b>ยึด GL เป็นตัวตัดสิน</b> — ดูว่า JE ของเอกสารนี้ Dr 11910 จริงหรือไม่
    /// แทนการไล่ hook ทีละจุดที่ post WHT (มี 5 จุด: accrual ตอนออกใบ, เกณฑ์เงินสด
    /// ตอนรับเงิน, ใบเสร็จ, มัดจำ, per-payment) — วิธีนี้ครอบทุกเส้นทางรวมถึงเส้นทาง
    /// ที่จะเพิ่มในอนาคต และตัวเลขตรงกับบัญชีเสมอ</para>
    ///
    /// <para>สร้างเป็นสถานะ <b>Pending</b> (ถูกหักแล้วแต่ยังไม่ได้รับหนังสือรับรอง)
    /// — กฎหมายให้เครดิตเฉพาะเมื่อมีใบจริง ผู้ใช้ต้องตามทวงแล้วมาแนบใบทีหลัง</para>
    ///
    /// <para>ไม่ throw — ทะเบียนภาษีล้มเหลวต้องไม่ทำให้อนุมัติเอกสารพัง</para></summary>
    private async Task SyncWhtCreditReceivedAsync(Guid companyId, Document doc)
    {
        try
        {
            // ฝั่งซื้อ = เราหักเขา (หนี้ที่ต้องนำส่ง) — คนละเรื่องกับเครดิตของเรา
            if (doc.DocumentType is DocumentType.PurchaseInvoice or DocumentType.Expense
                or DocumentType.PaymentVoucher or DocumentType.CertificateInLieu
                or DocumentType.PurchaseOrder or DocumentType.PurchaseRequisition
                or DocumentType.GoodsReceiptNote) return;

            // ยอดที่ Dr 11910 จริงจาก JE ของเอกสารนี้ (ตัด JE ที่ถูกกลับรายการแล้ว)
            var whtDebit = await (from l in _db.JournalEntryLines.AsNoTracking()
                                  join j in _db.JournalEntries.AsNoTracking() on l.JournalEntryId equals j.Id
                                  join a in _db.ChartOfAccounts.AsNoTracking() on l.AccountId equals a.Id
                                  where j.CompanyId == companyId && j.SourceDocumentId == doc.Id
                                        && !j.IsDeleted && !l.IsDeleted
                                        && j.Status == JournalEntryStatus.Posted
                                        && j.ReversedByEntryId == null
                                        && a.AccountCode.StartsWith("11910")
                                  select l.DebitAmount - l.CreditAmount).ToListAsync();
            var amount = whtDebit.Sum();

            var existing = await _db.WhtCreditsReceived
                .FirstOrDefaultAsync(w => w.CompanyId == companyId && w.DocumentId == doc.Id);

            // ⚠️ ห้ามแตะแถวที่มาจาก "หนังสือรับรอง 50 ทวิ ตัวจริง" —
            // `EnsureWhtCreditFromCertAsync` (สแกนใบ 50 ทวิ) ผูกแถวไว้กับ
            // ReceiptVoucher ใบใหม่ที่มันสร้าง ⇒ พอ RV ใบนั้นถูก approve
            // เมธอดนี้จะเจอแถวเดียวกันแล้ว:
            //   • ถ้า JE ของ RV ไม่มี Dr 11910 → amount ≤ 0.005 →
            //     **soft-delete เครดิตที่ลงทะเบียนจากใบจริงทิ้งเงียบ ๆ**
            //   • ถ้ามี → เขียนทับยอด/อัตรา/ปีภาษี ด้วยค่าที่ derive จาก RV
            //     แทนตัวเลขที่พิมพ์อยู่บนกระดาษ
            // แถวที่ GL สร้างเองไม่เคยมีเลขที่ใบรับรอง จึงใช้เป็นตัวแยกได้
            if (existing != null && !string.IsNullOrWhiteSpace(existing.CertificateNumber))
            {
                _logger.LogInformation(
                    "ข้าม SyncWhtCreditReceived ของ {Doc} — แถวนี้มาจากใบ 50 ทวิ {Cert} (ตัวเลขบนกระดาษชนะ GL)",
                    doc.Id, existing.CertificateNumber);
                return;
            }

            if (amount <= 0.005m)
            {
                // WHT ถูกกลับ/แก้เป็นศูนย์ → ลบแถวที่ยังไม่ได้ใช้เครดิตทิ้ง
                if (existing != null && existing.Status is WhtCreditStatus.Pending or WhtCreditStatus.Received)
                {
                    existing.IsDeleted = true;
                    existing.UpdatedAt = DateTime.UtcNow;
                    await _db.SaveChangesAsync();
                }
                return;
            }

            // ปีภาษี = ปีของ "รอบบัญชี" ที่เอกสารตกอยู่ (รองรับรอบไม่ตรงปีปฏิทิน)
            var startMonth = await _db.Companies.AsNoTracking()
                .Where(c => c.Id == companyId).Select(c => c.FiscalYearStartMonth).FirstOrDefaultAsync();
            if (startMonth is < 1 or > 12) startMonth = 1;
            var taxYear = doc.DocumentDate.Month >= startMonth
                ? doc.DocumentDate.Year : doc.DocumentDate.Year - 1;

            var baseAmount = doc.SubTotal > 0 ? doc.SubTotal : amount;
            var rate = baseAmount > 0 ? Math.Round(amount / baseAmount * 100m, 2) : 0m;

            if (existing != null)
            {
                // ใช้เครดิตไปแล้ว = ห้ามแก้ยอดเงียบ ๆ (แบบยื่นอ้างตัวเลขนี้ไปแล้ว)
                if (existing.Status is WhtCreditStatus.Claimed or WhtCreditStatus.Expired) return;
                existing.WhtAmount = amount;
                existing.IncomeAmount = baseAmount;
                existing.WhtRate = rate;
                existing.TaxYear = taxYear;
                existing.UpdatedAt = DateTime.UtcNow;
            }
            else
            {
                _db.WhtCreditsReceived.Add(new WhtCreditReceived
                {
                    CompanyId = companyId,
                    TaxYear = taxYear,
                    PayerContactId = doc.ContactId,
                    PayerName = doc.Contact?.Name ?? "",
                    PayerTaxId = doc.Contact?.TaxId,
                    PayerFormType = WhtPayerFormType.Pnd53,
                    IncomeAmount = baseAmount,
                    WhtRate = rate,
                    WhtAmount = amount,
                    Status = WhtCreditStatus.Pending,
                    DocumentId = doc.Id,
                    Notes = $"สร้างอัตโนมัติจาก {doc.DocumentNumber}",
                });
            }
            await _db.SaveChangesAsync();
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "SyncWhtCreditReceived ล้มเหลวสำหรับเอกสาร {Doc}", doc.Id);
        }
    }

    /// <summary>Auto-populate ProjectCostEntry from an approved
    /// expense-side document. Cost-bearing types only — Sales-side
    /// docs feed Project.ActualRevenue separately. Idempotent on
    /// DocumentLineId so re-running on the same doc doesn't
    /// duplicate.</summary>
    private async Task SyncProjectCostEntriesAsync(Guid companyId, Document doc)
    {
        var costTypes = new[] {
            DocumentType.PurchaseInvoice, DocumentType.Expense,
            DocumentType.PaymentVoucher, DocumentType.CertificateInLieu,
        };
        if (!costTypes.Contains(doc.DocumentType)) return;
        if (doc.Lines == null || doc.Lines.Count == 0) return;

        // จำแนกหมวดต้นทุนโครงการจากคำในรายการ (keyword ไทย/อังกฤษ) — ผู้ใช้แก้
        // หมวดเองได้ทีหลังในแท็บต้นทุนของโครงการ ค่านี้เป็นแค่ default ที่ฉลาดขึ้น
        static string ClassifyProjectCostType(string? desc)
        {
            var d = (desc ?? "").ToLowerInvariant();
            if (d.Contains("จ้างเหมา") || d.Contains("ผู้รับเหมา") || d.Contains("subcontract"))
                return "Subcontract";
            if (d.Contains("ค่าแรง") || d.Contains("แรงงาน") || d.Contains("ค่าจ้าง")
                || d.Contains("เงินเดือน") || d.Contains("โอที") || d.Contains("labor") || d.Contains("labour") || d.Contains("wage"))
                return "Labor";
            if (d.Contains("เดินทาง") || d.Contains("น้ำมันรถ") || d.Contains("ที่พัก")
                || d.Contains("โรงแรม") || d.Contains("ตั๋ว") || d.Contains("travel"))
                return "Travel";
            if (d.Contains("ค่าเช่า") || d.Contains("ค่าไฟ") || d.Contains("ค่าน้ำ")
                || d.Contains("ประกัน") || d.Contains("ค่าธรรมเนียม") || d.Contains("overhead"))
                return "Overhead";
            return "Material";   // ค่า default เดิม — วัสดุ/อุปกรณ์/สินค้า
        }

        // Snapshot the lines that already have a PCE so we skip them
        // in O(1) rather than running an exists-query per line.
        var lineIds = doc.Lines.Select(l => l.Id).ToList();
        var alreadyBookedLineIds = await _db.ProjectCostEntries
            .Where(c => c.CompanyId == companyId
                && !c.IsDeleted
                && c.DocumentLineId.HasValue
                && lineIds.Contains(c.DocumentLineId.Value))
            .Select(c => c.DocumentLineId!.Value)
            .ToListAsync();

        // Cache projects we touch so we update each one's ActualCost
        // exactly once across the doc's lines (some PIs split a single
        // project across many lines; we'd otherwise hit the DB per line).
        var touchedProjects = new Dictionary<Guid, decimal>();

        foreach (var line in doc.Lines)
        {
            // Per-line projectId wins; header is the fallback so users
            // can tag the doc once and still have individual lines
            // override (e.g. one PO with 90% Project A + 10% Project B).
            var projectId = line.ProjectId ?? doc.ProjectId;
            if (!projectId.HasValue) continue;
            if (alreadyBookedLineIds.Contains(line.Id)) continue;
            _db.ProjectCostEntries.Add(new ProjectCostEntry
            {
                CompanyId = companyId,
                ProjectId = projectId.Value,
                EntryDate = doc.DocumentDate,
                // จำแนกหมวดต้นทุนจากคำในรายการ (เดิม hardcode "Material" หมด →
                // ค่าแรง/จ้างเหมาจากใบซื้อกองผิดหมวด สัดส่วนต้นทุนโครงการเพี้ยน)
                CostType = ClassifyProjectCostType(line.Description),
                Description = $"{line.Description} [auto from {doc.DocumentNumber}]",
                Quantity = line.Quantity,
                UnitCost = line.UnitPrice,
                Amount = line.Amount,
                DocumentId = doc.Id,
                DocumentLineId = line.Id,
                IsBillable = false,
            });
            touchedProjects[projectId.Value] = touchedProjects.GetValueOrDefault(projectId.Value) + line.Amount;
        }
        if (touchedProjects.Count > 0)
        {
            var ids = touchedProjects.Keys.ToList();
            var projects = await _db.Projects
                .Where(p => p.CompanyId == companyId && ids.Contains(p.Id))
                .ToListAsync();
            foreach (var p in projects)
                p.ActualCost += touchedProjects[p.Id];
        }
        await _db.SaveChangesAsync();
    }

    /// <summary>Mirror of <see cref="SyncProjectCostEntriesAsync"/> for a
    /// void / un-approve: soft-delete the auto-spawned ProjectCostEntry rows
    /// for this document and back their amounts out of each Project.ActualCost.
    /// Without this, voiding a cost document left the project's actual cost
    /// permanently inflated. Idempotent — rows already soft-deleted are skipped
    /// so a re-void never double-subtracts. Uses the stored entry.Amount (what
    /// was actually booked) rather than re-deriving from lines. Caller owns the
    /// SaveChanges (runs inside the void transaction).</summary>
    private async Task ReverseProjectCostEntriesAsync(Guid companyId, Document doc)
    {
        var lineIds = doc.Lines?.Select(l => l.Id).ToList() ?? new List<Guid>();
        var entries = await _db.ProjectCostEntries
            .Where(c => c.CompanyId == companyId && !c.IsDeleted
                && (c.DocumentId == doc.Id
                    || (c.DocumentLineId.HasValue && lineIds.Contains(c.DocumentLineId.Value))))
            .ToListAsync();
        if (entries.Count == 0) return;

        var perProject = new Dictionary<Guid, decimal>();
        foreach (var e in entries)
        {
            e.IsDeleted = true;
            e.UpdatedAt = DateTime.UtcNow;
            perProject[e.ProjectId] = perProject.GetValueOrDefault(e.ProjectId) + e.Amount;
        }
        var ids = perProject.Keys.ToList();
        var projects = await _db.Projects
            .Where(p => p.CompanyId == companyId && ids.Contains(p.Id))
            .ToListAsync();
        foreach (var p in projects)
            p.ActualCost = Math.Max(0, p.ActualCost - perProject[p.Id]);
    }

    // ชนิดเอกสารที่อยู่ฝั่งเดียวแน่นอน — ใช้ตรวจว่าผังบัญชีรายบรรทัดอยู่ถูกฝั่ง.
    // CreditNote/DebitNote จงใจไม่อยู่ทั้งสอง list (เป็นได้ทั้งฝั่งขายและซื้อ
    // ตามใบต้นทาง — ดู resolver ใน AutoPostToJournalAsync)
    private static readonly DocumentType[] PureSalesSideTypes = {
        DocumentType.Quotation, DocumentType.Invoice, DocumentType.TaxInvoice,
        DocumentType.Receipt, DocumentType.ReceiptVoucher,
        DocumentType.BillingNote, DocumentType.DeliveryNote,
    };
    private static readonly DocumentType[] PurePurchaseSideTypes = {
        DocumentType.PurchaseRequisition, DocumentType.PurchaseOrder,
        DocumentType.GoodsReceiptNote, DocumentType.PurchaseInvoice,
        DocumentType.Expense, DocumentType.PaymentVoucher,
        DocumentType.CertificateInLieu,
    };

    /// <summary>ล้างเทอมเครดิต/วันครบกำหนดที่ไม่มีความหมายกับชนิดเอกสารนั้น —
    /// เรียกทั้งตอน create และ update (ฟอร์มซ่อนช่องเหล่านี้ตามชนิดแล้ว แต่
    /// API ภายนอก/OCR/เอกสารเก่ายุคฟอร์มเหมารวม ยังยัดค่าเข้ามาได้)
    ///
    /// <para>หลักคิด: เครดิตเทอมมีได้เฉพาะใบที่ก่อ "หนี้ใหม่รอเก็บ/รอจ่าย".
    /// ใบเสร็จ/ใบสำคัญรับ = เงินรับแล้ว · ใบลดหนี้ = ปรับหนี้ของใบเดิม (เทอม
    /// เป็นของใบเดิม ไม่ใช่ของใบลด) · ใบส่งของ/GRN = โลจิสติกส์ · ใบแทน
    /// ใบเสร็จ = จ่ายไปแล้วถึงต้องออกใบแทน. ส่วน PV คงวันครบกำหนดไว้ได้
    /// (โหมดเครดิตตัดหนี้ใบตั้งหนี้) และ PR คงไว้เป็น "วันที่ต้องการรับของ"
    /// — สองชนิดนี้ล้างเฉพาะเครดิตเทอม.</para></summary>
    private static void NormalizeCreditTermFields(Document doc)
    {
        switch (doc.DocumentType)
        {
            case DocumentType.CreditNote:
            case DocumentType.Receipt:
            case DocumentType.ReceiptVoucher:
            case DocumentType.CertificateInLieu:
            case DocumentType.DeliveryNote:
            case DocumentType.GoodsReceiptNote:
                doc.CreditDays = null;
                doc.PaymentTerms = null;
                doc.DueDate = null;
                break;
            case DocumentType.PaymentVoucher:
            case DocumentType.PurchaseRequisition:
                doc.CreditDays = null;
                doc.PaymentTerms = null;
                break;
        }
    }

    /// <summary>กันผังบัญชีรายบรรทัดข้ามฝั่ง: เอกสารขายที่ผูกผังหมวด "ค่าใช้จ่าย"
    /// จะทำให้ JE ตอนอนุมัติ (หรือหลังแปลงเป็นใบแจ้งหนี้) Cr รายได้เข้าบัญชี
    /// 5xxxx — งบกำไรขาดทุนเพี้ยนทั้งสองขา. ฝั่งซื้อผูกผังหมวด "รายได้" ก็ผิด
    /// สมมาตรกัน (Dr ค่าใช้จ่ายเข้าบัญชี 4xxxx). โยน error ภาษาไทยชัด ๆ ตั้งแต่
    /// ตอนบันทึก — ดีกว่าปล่อยผ่านแล้วไปพังใน GL. ฝั่งขายยังใช้ผังหนี้สิน/
    /// สินทรัพย์ได้ (มัดจำ, รับล่วงหน้า) — บล็อกเฉพาะหมวดค่าใช้จ่าย.</summary>
    /// <param name="cnDnIsPurchase">ฝั่งของใบลดหนี้/ใบเพิ่มหนี้ (<c>null</c> = ยังไม่รู้)
    ///   — ชนิดอื่นไม่ใช้ค่านี้. **CN/DN เคยถูกยกเว้นจากด่านนี้ทั้งด่าน** (ดูคอมเมนต์ที่
    ///   <c>PureSalesSideTypes</c>) ⇒ ผังหมวดรายได้บนใบลดหนี้ฝั่งซื้อ Cr เข้า 4xxxx เงียบ ๆ
    ///   · กติกาอยู่ที่ <c>Helpers/AdjustmentNoteAccount.SideViolation</c> ตัวเดียว</param>
    private static void EnsureLineAccountMatchesDocSide(
        DocumentType docType, string? lineDescription, ChartOfAccount acct,
        bool? cnDnIsPurchase = null)
    {
        if (docType is DocumentType.CreditNote or DocumentType.DebitNote)
        {
            var violation = Accounting.Helpers.AdjustmentNoteAccount.SideViolation(
                cnDnIsPurchase, docType == DocumentType.CreditNote,
                acct.AccountType, acct.AccountCode, acct.AccountName, lineDescription);
            if (violation != null) throw new InvalidOperationException(violation);
            return;
        }
        if (PureSalesSideTypes.Contains(docType) && acct.AccountType == AccountType.Expense)
            throw new InvalidOperationException(
                $"รายการ '{lineDescription}' เลือกผังบัญชี {acct.AccountCode} {acct.AccountName} (หมวดค่าใช้จ่าย) " +
                "ซึ่งใช้กับเอกสารฝั่งขายไม่ได้ — กรุณาเลือกผังหมวดรายได้ (4xxxx) " +
                "หรือเว้นว่างเพื่อใช้บัญชีรายได้มาตรฐานของระบบ");
        if (PurePurchaseSideTypes.Contains(docType) && acct.AccountType == AccountType.Revenue)
            throw new InvalidOperationException(
                $"รายการ '{lineDescription}' เลือกผังบัญชี {acct.AccountCode} {acct.AccountName} (หมวดรายได้) " +
                "ซึ่งใช้กับเอกสารฝั่งซื้อไม่ได้ — กรุณาเลือกผังหมวดค่าใช้จ่าย/สินทรัพย์/หนี้สิน " +
                "หรือเว้นว่างเพื่อใช้บัญชีตั้งต้นของระบบ");
    }

    /// <summary>Resolve THB exchange rate for a document. THB → 1. Explicit
    /// override wins; otherwise auto-fetch the BoT mid-rate at DocumentDate.
    /// Throws if BoT lookup fails — silent fallback to 1 on non-THB would
    /// corrupt the GL.</summary>
    private async Task<decimal> ResolveExchangeRateAsync(string? currency, decimal? overrideRate, DateTime documentDate)
    {
        var cur = (currency ?? "THB").ToUpperInvariant();
        if (cur == "THB") return 1m;
        if (overrideRate is decimal r)
        {
            if (r <= 0m) throw new InvalidOperationException("อัตราแลกเปลี่ยนต้องมากกว่า 0");
            return r;
        }
        if (_fxRates == null)
            throw new InvalidOperationException(
                $"เอกสารสกุล {cur} ต้องระบุ ExchangeRate (ไม่ได้กำหนดบริการอัตรา ธ.ปท.)");
        var rate = await _fxRates.GetRateAsync(cur, documentDate);
        if (rate == null || rate.MidRate <= 0m)
            throw new InvalidOperationException(
                $"ไม่พบอัตราแลกเปลี่ยน {cur} ของวันที่ {documentDate:yyyy-MM-dd} จาก ธ.ปท. " +
                "กรุณาระบุ ExchangeRate ในคำขอ");
        return rate.MidRate;
    }

    /// <summary>Validate the line items on a create OR update. Same guards in
    /// one place so an edit can't slip past the create-time checks (qty &gt; 0,
    /// non-negative price, discount 0-100%, VAT ∈ {0,7,-1}, WHT 0-15%, valid
    /// active account). Throws InvalidOperationException on the first failure.</summary>
    private async Task ValidateDocumentLinesAsync(Guid companyId, List<DocumentLineRequest>? lines)
    {
        if (lines == null || lines.Count == 0)
            throw new InvalidOperationException("ต้องมีรายการสินค้าอย่างน้อย 1 รายการ");

        // P7 (N+1): ตรวจว่ารหัสบัญชีของทุกบรรทัดมีจริง — เดิม AnyAsync **ต่อบรรทัด**
        // ⇒ เอกสาร 50 บรรทัด = 50 query ทุกครั้งที่สร้าง/แก้ (และ import ที่ยิงหลาย
        // ใบพร้อมกันคูณเข้าไปอีก). ดึงชุด id ที่ใช้ได้ทีเดียวก่อนลูป
        var lineAccountIds = lines.Where(l => l.AccountId.HasValue)
            .Select(l => l.AccountId!.Value).Distinct().ToList();
        var validLineAccountIds = lineAccountIds.Count == 0
            ? new HashSet<Guid>()
            : (await _db.ChartOfAccounts.AsNoTracking()
                .Where(a => a.CompanyId == companyId && a.IsActive
                    && lineAccountIds.Contains(a.Id))
                .Select(a => a.Id)
                .ToListAsync())
                .ToHashSet();

        // รหัสผัง (AccountCode) ที่ resolve ไม่ได้ต้อง**ล้มดัง** — เดิม resolver คืน null เงียบ ⇒
        // AccountId=null ⇒ JE ตกไปใช้ผัง default/หมวดหัวเอกสารเดิม ⇒ ผู้ใช้เห็นว่า “แก้ผังแล้ว
        // กดบันทึกอนุมัติ ระบบไม่เปลี่ยน” โดยไม่มี error (ผลตรวจ 2026-09-10)
        var codesToCheck = lines
            .Where(l => !l.AccountId.HasValue && !string.IsNullOrWhiteSpace(l.AccountCode))
            .Select(l => l.AccountCode!.Trim()).Distinct().ToList();
        if (codesToCheck.Count > 0)
        {
            var known = (await _db.ChartOfAccounts.AsNoTracking()
                .Where(a => a.CompanyId == companyId && a.IsActive && codesToCheck.Contains(a.AccountCode))
                .Select(a => a.AccountCode).ToListAsync()).ToHashSet();
            var bad = lines.FirstOrDefault(l => !l.AccountId.HasValue
                && !string.IsNullOrWhiteSpace(l.AccountCode) && !known.Contains(l.AccountCode!.Trim()));
            if (bad != null)
                throw new Accounting.Helpers.BusinessRuleException(
                    $"รหัสบัญชี “{bad.AccountCode}” ในรายการ “{bad.Description}” ไม่พบในผังบัญชีของบริษัท หรือถูกปิดใช้งาน "
                    + "— เลือกรหัสจากรายการ (พิมพ์รหัสหรือชื่อบัญชี) แล้วบันทึกใหม่");
        }

        foreach (var line in lines)
        {
            // เครื่องหมายบนบรรทัด (จำนวน/ราคาต่อหน่วย/ส่วนลด) ตัดสินที่ **ตัวตั้งตัวเดียว**
            // `Helpers/DocumentLineKind` — เดิมกติกา "ห้ามติดลบ" อยู่ที่นี่ที่เดียว ส่วน
            // CMS/POS สร้างบรรทัดติดลบของตัวเองคนละแบบ (CMS โดนโยนทุกใบ · POS เลี่ยง
            // validator ทั้งหมดเพราะประกอบ Document เอง) = กฎสองชุดที่เถียงกันเอง
            var sign = DocumentLineKind.Judge(line.Quantity, line.UnitPrice, line.DiscountAmount ?? 0m);
            if (!sign.Ok)
                throw new BusinessRuleException(
                    $"รายการ \u201c{line.Description}\u201d: {sign.Reason}",
                    DocumentLineKind.SignRuleCode);
            if (line.DiscountPercent < 0 || line.DiscountPercent > 100)
                throw new BusinessRuleException(
                    $"รายการ \u201c{line.Description}\u201d: ส่วนลดต้องอยู่ระหว่าง 0-100% "
                    + "— ถ้าต้องการหักเป็นยอดเงิน ให้กรอกที่ช่องส่วนลด (บาท) แทน",
                    DocumentLineKind.SignRuleCode);
            if (line.VatRate != 0 && line.VatRate != 7 && line.VatRate != -1)
                throw new InvalidOperationException("อัตราภาษีมูลค่าเพิ่มต้องเป็น 0, 7 หรือ -1 (ยกเว้น)");
            if (line.WithholdingTaxRate < 0 || line.WithholdingTaxRate > 15)
                throw new InvalidOperationException("อัตราภาษีหัก ณ ที่จ่ายต้องอยู่ระหว่าง 0-15%");
            if (line.AccountId.HasValue && !validLineAccountIds.Contains(line.AccountId.Value))
                throw new InvalidOperationException(
                    $"รหัสบัญชีที่ระบุในรายการ '{line.Description}' ไม่พบในผังบัญชี หรือถูกปิดใช้งาน");
        }
    }

    /// <summary>Computed money fields for one document line, shared by create
    /// + update so the math (incl. VAT-inclusive back-out) never diverges.
    /// <c>NetAmount</c> is the ex-VAT, after-discount base that posts to
    /// revenue/expense.</summary>
    private readonly record struct LineAmounts(decimal NetAmount, decimal DiscountAmount, decimal VatAmount, decimal WhtAmount);

    /// <param name="extraDiscount">ส่วนลด "ท้ายบิล" (จากยอดรวม) ที่เฉลี่ยลงบรรทัดนี้
    /// แบบ pro-rata — เป็นยอด **ex-VAT** ที่หักออกจาก net ของบรรทัดหลังคิดส่วนลด
    /// รายบรรทัดแล้ว → VAT/WHT คิดใหม่บนฐานที่ลดลง (mixed-rate ถูกต้อง). 0 = ไม่มี.
    /// DiscountAmount ที่คืนยังเป็น "ส่วนลดรายบรรทัด" ล้วน ไม่รวมท้ายบิล (กัน
    /// double-count ตอน edit round-trip; ท้ายบิลเก็บแยกที่ Document.BillDiscountAmount).</param>
    /// <summary>ตรวจว่า BrandId / DocumentTemplateId ที่ส่งมา **เป็นของบริษัทนี้จริง**
    /// — ทั้งสอง field มาจาก client ตรง ๆ ถ้าไม่ตรวจ ผู้ใช้บริษัท A ยิง guid ของ
    /// บริษัท B เข้ามาได้ แล้วเอกสารบริษัท A จะพิมพ์ชื่อ/โลโก้/ที่อยู่ของบริษัท B
    /// ลงหัวกระดาษ (ผลตรวจทีมเส้นทางข้อมูล ข้อ 2 — ผิด invariant M "ทุก query
    /// ต้องมี CompanyId")
    ///
    /// <para>คืน null เมื่อค่าเป็น null หรือ <c>Guid.Empty</c> (= "ใช้ค่าปกติ")
    /// และ **throw** เมื่อ id มีค่าแต่ไม่ใช่ของบริษัทนี้ — ต่างจากการ fallback
    /// เงียบ ๆ เพราะนี่คือค่าที่ผู้ใช้เพิ่งเลือกเอง ผิดแปลว่ามีอะไรผิดจริง</para></summary>
    private async Task<Guid?> ResolveOwnedBrandIdAsync(Guid companyId, Guid? brandId)
    {
        if (!brandId.HasValue || brandId.Value == Guid.Empty) return null;
        var ok = await _db.DocumentBrands
            .AnyAsync(b => b.Id == brandId.Value && b.CompanyId == companyId && !b.IsDeleted);
        if (!ok) throw new InvalidOperationException("ไม่พบชื่อทางการค้าที่เลือก หรือไม่ใช่ของบริษัทนี้");
        return brandId.Value;
    }

    /// <summary>ตรวจว่า BranchId ที่ส่งมาเป็นสาขาของบริษัทนี้จริง (invariant M)
    /// — สาขาผิดบริษัท = ใบกำกับพิมพ์ที่อยู่/รหัสสาขาของคนอื่น §86/4
    ///
    /// <para>คืน null เมื่อ null/<c>Guid.Empty</c> = "ใช้ค่าบริษัทตามเดิม"
    /// (กิจการสาขาเดียวเดินเส้นนี้เสมอ — พฤติกรรมเดิมทุกประการ)</para>
    ///
    /// <para>สาขาที่ **ปิดใช้งาน** ยังผูกได้ตอนแก้ใบเก่า — ปิดสาขาไม่ควรทำให้
    /// เอกสารที่ออกไปแล้วแก้ไม่ได้ (รายการเลือกตอนออกใบใหม่กรองให้อยู่แล้ว)</para></summary>
    private async Task<Guid?> ResolveOwnedBranchIdAsync(Guid companyId, Guid? branchId)
    {
        if (!branchId.HasValue || branchId.Value == Guid.Empty) return null;
        var ok = await _db.Set<Branch>()
            .AnyAsync(b => b.Id == branchId.Value && b.CompanyId == companyId && !b.IsDeleted);
        if (!ok) throw new InvalidOperationException("ไม่พบสาขาที่เลือก หรือไม่ใช่ของบริษัทนี้");
        return branchId.Value;
    }

    private async Task<Guid?> ResolveOwnedTemplateIdAsync(Guid companyId, Guid? templateId)
    {
        if (!templateId.HasValue || templateId.Value == Guid.Empty) return null;
        var ok = await _db.DocumentTemplates
            .AnyAsync(t => t.Id == templateId.Value && t.CompanyId == companyId);
        if (!ok) throw new InvalidOperationException("ไม่พบรูปแบบเอกสารที่เลือก หรือไม่ใช่ของบริษัทนี้");
        return templateId.Value;
    }

    private static LineAmounts ComputeLineAmounts(DocumentLineRequest line, bool pricesIncludeVat, decimal extraDiscount = 0m)
    {
        const MidpointRounding R = MidpointRounding.AwayFromZero;
        var gross = Math.Round(line.Quantity * line.UnitPrice, 2, R);
        // ส่วนลด: ถ้าระบุเป็นยอดเงิน (DiscountAmount > 0) ใช้ตรง ๆ (มาตรฐานสากล
        // — ใบกำกับระบุส่วนลดเป็นบาท); ไม่งั้นคิดจาก %. clamp ไม่ให้เกิน gross.
        var discountAmt = line.DiscountAmount is > 0m
            ? Math.Min(Math.Round(line.DiscountAmount.Value, 2, R), gross)
            : Math.Round(gross * line.DiscountPercent / 100, 2, R);
        var afterDiscount = gross - discountAmt;

        decimal net, vatAmt;
        if (line.VatAmountOverride.HasValue)
        {
            // External/integration ส่ง VAT ที่คำนวณเองมาแล้ว (บรรทัดปนของ
            // เสียภาษี + ยกเว้น) → honor ตรง ๆ ไม่คิดใหม่. pricesIncludeVat
            // = true หมายถึง afterDiscount รวม VAT แล้ว → net = ส่วนต่าง.
            vatAmt = Math.Round(line.VatAmountOverride.Value, 2, R);
            net = pricesIncludeVat ? afterDiscount - vatAmt : afterDiscount;
        }
        else if (pricesIncludeVat && line.VatRate > 0)
        {
            // Entered price already contains VAT → strip it out.
            // net = incl × 100/(100+rate); vat = incl − net.
            net = Math.Round(afterDiscount * 100m / (100m + line.VatRate), 2, R);
            vatAmt = afterDiscount - net;
        }
        else
        {
            net = afterDiscount;
            vatAmt = line.VatRate > 0 ? Math.Round(net * line.VatRate / 100, 2, R) : 0m;
        }
        // ส่วนลดท้ายบิล (เฉลี่ย pro-rata) — หักจาก net (ex-VAT) แล้วคิด VAT/WHT ใหม่
        // บนฐานที่ลดลง → รวมทั้งบิลถูกต้องแม้ VAT คนละอัตรากัน. ถ้ามี VatAmountOverride
        // (integration คิด VAT เอง) คง VAT เดิม (best-effort — เคสรวมกันแทบไม่มี).
        if (extraDiscount > 0m && net > 0m)
        {
            var reduce = Math.Min(Math.Round(extraDiscount, 2, R), net);
            net -= reduce;
            if (!line.VatAmountOverride.HasValue)
                vatAmt = line.VatRate > 0 ? Math.Round(net * line.VatRate / 100, 2, R) : 0m;
        }
        // WHT is always computed on the ex-VAT base (Thai rule).
        var whtAmt = Math.Round(net * line.WithholdingTaxRate / 100, 2, R);
        return new LineAmounts(net, discountAmt, vatAmt, whtAmt);
    }

    /// <summary>เฉลี่ยส่วนลด "ท้ายบิล" (จากยอดรวม) ลงแต่ละบรรทัดแบบ pro-rata ตาม
    /// สัดส่วน net (ex-VAT) ก่อนหักท้ายบิล. คืน array ยอดส่วนลด ex-VAT ต่อบรรทัด
    /// (index ตรงกับ request.Lines). billPercent > 0 = คิดเป็น % ของยอดรวม;
    /// ไม่งั้นใช้ billAmount (บาท) clamp ไม่ให้เกินยอดรวม. remainder ปัดเศษลง
    /// บรรทัดสุดท้ายที่มียอด เพื่อให้ผลรวม = ส่วนลดที่ตั้งใจเป๊ะ.</summary>
    private static decimal[] AllocateBillDiscount(
        IReadOnlyList<DocumentLineRequest> lines, bool pricesIncludeVat,
        decimal billPercent, decimal billAmount)
    {
        const MidpointRounding R = MidpointRounding.AwayFromZero;
        var alloc = new decimal[lines.Count];
        var baseNet = new decimal[lines.Count];
        decimal totalBase = 0m;
        for (int i = 0; i < lines.Count; i++)
        {
            baseNet[i] = ComputeLineAmounts(lines[i], pricesIncludeVat).NetAmount;
            if (baseNet[i] > 0m) totalBase += baseNet[i];
        }
        if (totalBase <= 0m) return alloc;

        decimal billDisc = billPercent > 0m
            ? Math.Round(totalBase * billPercent / 100m, 2, R)
            : Math.Round(billAmount, 2, R);
        billDisc = Math.Min(Math.Max(billDisc, 0m), totalBase);
        if (billDisc <= 0m) return alloc;

        decimal running = 0m;
        int lastIdx = -1;
        for (int i = 0; i < lines.Count; i++)
        {
            if (baseNet[i] <= 0m) continue;
            alloc[i] = Math.Round(billDisc * baseNet[i] / totalBase, 2, R);
            running += alloc[i];
            lastIdx = i;
        }
        if (lastIdx >= 0 && running != billDisc)
            alloc[lastIdx] += billDisc - running;   // เก็บเศษปัดที่บรรทัดสุดท้าย

        // เศษที่ยัดบรรทัดสุดท้ายอาจ "ล้น" ยอดบรรทัด (บรรทัดจิ๋ว) — ComputeLineAmounts
        // จะ clamp ทิ้งเงียบ ทำให้ Σหักจริง < BillDiscountAmount ที่บันทึก →
        // "รวมก่อนหักท้ายบิล" บน PDF เกินจริง. เกลี่ยส่วนล้นไปบรรทัดที่ยังรับได้
        // (billDisc ≤ totalBase เสมอ → เกลี่ยลงได้หมดแน่นอน)
        for (int guard = 0; guard < lines.Count; guard++)
        {
            int overIdx = -1;
            for (int i = 0; i < lines.Count; i++)
                if (alloc[i] > baseNet[i]) { overIdx = i; break; }
            if (overIdx < 0) break;
            var overflow = alloc[overIdx] - baseNet[overIdx];
            alloc[overIdx] = baseNet[overIdx];
            for (int i = 0; i < lines.Count && overflow > 0m; i++)
            {
                if (i == overIdx || baseNet[i] <= 0m) continue;
                var capacity = baseNet[i] - alloc[i];
                if (capacity <= 0m) continue;
                var take = Math.Min(capacity, overflow);
                alloc[i] += take;
                overflow -= take;
            }
        }
        return alloc;
    }

    /// <summary>ปรับเศษสตางค์ VAT/WHT รายบรรทัดให้ผลรวม "ต่อกลุ่มอัตรา" เท่ากับการ
    /// คิดตรงจากฐานรวมของกลุ่ม (round(Σ net × rate/100)) — วิธีเดียวกับที่ผู้ใช้/
    /// สรรพากรดีดเครื่องคิดเลขตรวจ. การปัดรายบรรทัดแล้วค่อยรวม (เช่นหลังเฉลี่ยส่วนลด
    /// ท้ายบิล หลายบรรทัดลงท้าย .875 ถูกปัดขึ้นซ้ำกัน) สะสมเป็น ±สตางค์ ทำให้ VAT 7%
    /// ของฐาน 42,000.00 กลายเป็น 2,940.01 แทน 2,940.00 → ยอดบนใบ/ภ.พ.30 ไม่ตรง
    /// ใบกำกับจริง. เศษถูกเกลี่ยเข้าบรรทัดฐานสูงสุดของกลุ่ม (largest-remainder).
    /// บรรทัดที่ integration ส่ง VatAmountOverride มาไม่แตะ (external คิดเองแล้ว).
    /// โหมดราคารวม VAT: ขยับ net สวนทาง VAT เท่ากัน เพื่อคงยอด gross ที่ผู้ใช้กรอก.</summary>
    private static void ReconcileTaxRounding(
        IReadOnlyList<DocumentLineRequest> lines, LineAmounts[] amts, bool pricesIncludeVat)
    {
        const MidpointRounding R = MidpointRounding.AwayFromZero;
        // --- VAT: กลุ่มตาม VatRate (รองรับ mixed-rate — คนละอัตรากระทบยอดแยกกัน) ---
        foreach (var g in Enumerable.Range(0, lines.Count)
                     .Where(i => !lines[i].VatAmountOverride.HasValue
                                 && lines[i].VatRate > 0 && amts[i].NetAmount != 0m)
                     .GroupBy(i => lines[i].VatRate))
        {
            var target = Math.Round(g.Sum(i => amts[i].NetAmount) * g.Key / 100m, 2, R);
            var diff = target - g.Sum(i => amts[i].VatAmount);
            // เศษปัดจริงมีขนาดระดับสตางค์ — ถ้าห่างเกิน ฿1 แปลว่าไม่ใช่เศษปัด (ข้อมูล
            // ผิดทางอื่น) ไม่เขียนทับเงียบ ๆ
            if (diff == 0m || Math.Abs(diff) > 1m) continue;
            var j = g.OrderByDescending(i => Math.Abs(amts[i].NetAmount)).First();
            amts[j] = amts[j] with
            {
                VatAmount = amts[j].VatAmount + diff,
                // ราคารวม VAT: gross ต่อบรรทัด (net+VAT) คือค่าที่ผู้ใช้กรอก — คงไว้
                NetAmount = pricesIncludeVat ? amts[j].NetAmount - diff : amts[j].NetAmount,
            };
        }
        // --- WHT: ฐาน ex-VAT เสมอ — ทำหลัง VAT เพราะโหมดราคารวม VAT อาจขยับ net ---
        foreach (var g in Enumerable.Range(0, lines.Count)
                     .Where(i => lines[i].WithholdingTaxRate > 0 && amts[i].NetAmount != 0m)
                     .GroupBy(i => lines[i].WithholdingTaxRate))
        {
            var target = Math.Round(g.Sum(i => amts[i].NetAmount) * g.Key / 100m, 2, R);
            var diff = target - g.Sum(i => amts[i].WhtAmount);
            if (diff == 0m || Math.Abs(diff) > 1m) continue;
            var j = g.OrderByDescending(i => Math.Abs(amts[i].NetAmount)).First();
            amts[j] = amts[j] with { WhtAmount = amts[j].WhtAmount + diff };
        }
    }

    /// <summary>ยุบ VAT-split phantom lines — choke point สุดท้ายครอบคลุมทุก
    /// path (frontend form / integration / OCR handoff ที่เข้าทาง POST /documents).
    /// เคส: external OCR แตกสินค้า 1 ตัวเป็น "...(ส่วนมีภาษี)" + "...(ส่วนไม่มีภาษี)"
    /// + เศษ ≤฿1 (VAT/0.07 rounding). Gate ด้วย "มี marker ส่วน(ไม่)มีภาษี"
    /// — ถ้าไม่มี marker ไม่แตะ (กันเอกสารปกติที่มี line ≤฿1 จริง). DocumentLineRequest
    /// เป็น immutable record → rebuild list. คืน list ใหม่; caller replace
    /// request.Lines contents.</summary>
    internal static List<DocumentLineRequest> CleanVatSplitLines(List<DocumentLineRequest>? lines)
    {
        if (lines == null || lines.Count < 2) return lines ?? new();

        string[] markers =
        {
            "ส่วนมีภาษี", "ส่วนที่มีภาษี", "ส่วนคิดภาษี",
            "ส่วนไม่มีภาษี", "ส่วนที่ไม่มีภาษี", "ส่วนยกเว้นภาษี",
            "vatable", "non-vat", "non vat", "nonvat",
            "vat included", "vat-included", "incl. vat", "incl vat",
            "vat excluded", "vat-excluded", "excl. vat", "excl vat",
            "with vat", "without vat", "มีภาษี", "ไม่มีภาษี",
        };

        // ตรวจว่ามี line ที่มี VAT-split marker ไหม — gate: ไม่มี = ไม่แตะ
        static (bool Had, string Cleaned) TrimMarker(string? desc, string[] mk)
        {
            if (string.IsNullOrWhiteSpace(desc)) return (false, desc ?? "");
            var s = desc.TrimEnd();
            var had = false;
            for (var safety = 0; safety < 3; safety++)
            {
                if (!s.EndsWith(")")) break;
                var open = s.LastIndexOf('(');
                if (open < 0) break;
                var inside = s.Substring(open + 1, s.Length - open - 2).Trim().ToLowerInvariant();
                var match = false;
                foreach (var m in mk) if (inside.Contains(m.ToLowerInvariant())) { match = true; break; }
                if (!match) break;
                s = s.Substring(0, open).TrimEnd();
                had = true;
            }
            return (had, s);
        }

        var anyMarker = lines.Any(l => TrimMarker(l.Description, markers).Had);
        if (!anyMarker) return lines;   // เอกสารปกติ — ไม่แตะ

        // 1) trim suffix (rebuild — record immutable)
        var trimmed = lines.Select(l => l with { Description = TrimMarker(l.Description, markers).Cleaned }).ToList();

        const decimal TOL = 1m;
        decimal Amt(DocumentLineRequest l) => l.Quantity * l.UnitPrice;

        // 2) fold phantom (≤฿1) เข้าบรรทัด amount ใหญ่สุด — รักษายอดรวมเป๊ะ
        var phantoms = trimmed.Where(l => Amt(l) > 0m && Amt(l) <= TOL && l.UnitPrice <= TOL).ToList();
        var reals = trimmed.Where(l => !phantoms.Contains(l)).ToList();
        if (phantoms.Count > 0 && reals.Count > 0)
        {
            var foldAmt = phantoms.Sum(Amt);
            var main = reals.OrderByDescending(Amt).First();
            var idx = reals.IndexOf(main);
            var newAmt = Amt(main) + foldAmt;
            var newUnit = main.Quantity > 0m ? Math.Round(newAmt / main.Quantity, 2) : newAmt;
            reals[idx] = main with { UnitPrice = newUnit };
            trimmed = reals;
        }

        // 3) merge true duplicates (desc + account เดียวกัน) — เคส split เท่า ๆ กัน
        var outList = new List<DocumentLineRequest>();
        var seen = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var l in trimmed)
        {
            var key = $"{(l.Description ?? "").Trim()}|{l.AccountId}|{l.AccountCode}";
            if (seen.TryGetValue(key, out var oi))
            {
                var ex = outList[oi];
                var newQty = ex.Quantity + l.Quantity;
                // amount รวม = ex.Amt + l.Amt; unit price = amount/qty
                var totAmt = Amt(ex) + Amt(l);
                var unit = newQty > 0m ? Math.Round(totAmt / newQty, 2) : ex.UnitPrice;
                outList[oi] = ex with { Quantity = newQty, UnitPrice = unit };
            }
            else
            {
                seen[key] = outList.Count;
                outList.Add(l);
            }
        }
        return outList;
    }

    public async Task<DocumentResponse> CreateDocumentAsync(Guid companyId, CreateDocumentRequest request, string createdBy,
        string? originModule = null, bool isFullTaxInvoiceReplacement = false)
    {
        // ── ธง "ใบแจ้งหนี้/ใบกำกับภาษี ใบเดียว" ต้องมาคู่กับชนิด TaxInvoice ──
        // เดิมชนิดไม่ตรง = **ดรอปธงเงียบ ๆ** ⇒ integration/recurring ที่ส่ง
        // Invoice + combined:true ได้ใบแจ้งหนี้เปล่ากลับไปโดยไม่มีอะไรบอก
        // (silent no-op). ตอนนี้:
        //   • Invoice + combined → ยกชนิดเป็น TaxInvoice ให้ — ตรงกับที่หน้าเว็บ
        //     ทำอยู่แล้วฝั่ง client (checkbox force type ตอน save) เจตนาผู้เรียก
        //     ชัดเจนว่าต้องการใบรวม
        //   • ชนิดอื่น + combined → ปฏิเสธพร้อมบอกทางแก้ (ห้ามเดาเจตนา)
        if (request.CombinedInvoiceTaxInvoice
            && request.DocumentType != DocumentType.TaxInvoice)
        {
            if (request.DocumentType == DocumentType.Invoice)
                request = request with { DocumentType = DocumentType.TaxInvoice };
            else
                throw new Accounting.Helpers.BusinessRuleException(
                    "combinedInvoiceTaxInvoice (ใบแจ้งหนี้/ใบกำกับภาษี ใบเดียว) ใช้ได้เฉพาะ "
                    + "documentType = TaxInvoice หรือ Invoice เท่านั้น — "
                    + $"ส่งมาเป็น {request.DocumentType}");
        }

        // ⭐ ยุบ VAT-split phantom lines ก่อนทุกอย่าง (choke point ครอบคลุมทุก path)
        if (request.Lines is { Count: > 1 })
        {
            var cleaned = CleanVatSplitLines(request.Lines);
            if (!ReferenceEquals(cleaned, request.Lines))
            {
                request.Lines.Clear();
                request.Lines.AddRange(cleaned);
            }
        }

        // ── โควตาเอกสาร: แยก "นับ" ออกจาก "บล็อก" (Helpers/DocumentQuotaPolicy) ──
        // ⚠️ เดิมบรรทัดนี้ throw ทุกชนิดเอกสารเมื่อเกินโควตา ⇒ ใบกำกับภาษีตอนแขก
        // เช็คเอาต์/ใบเสร็จของเงินที่รับมาแล้ว ออกไม่ได้กลางคัน = ลูกค้าผิด §86/4
        // และเราเป็นสาเหตุ (LODGING_LICENSING_PLAN §5 · ทีม CPA)
        // ตอนนี้: ใบที่กฎหมายบังคับ → ออกได้เสมอ แล้วคิด overage · ใบที่รอได้ → บล็อกตามเดิม
        var quotaClass = DocumentQuotaPolicy.Classify(
            request.DocumentType, request.IsDeposit, IsLodgingOrigin(originModule),
            // ใบกำกับที่ออก "แทน" ใบเสร็จ = การขายเดิมที่นับโควตาไปแล้ว —
            // นับอีกครั้งคือคิดเงินลูกค้าสองเด้งจากงานเดียว
            isReplacement: isFullTaxInvoiceReplacement);
        var withinQuota = await _subscriptionService.CheckUsageLimitAsync(companyId, "document");
        if (!withinQuota && DocumentQuotaPolicy.CanRefuseWhenOverQuota(quotaClass))
        {
            var (used, limit) = await GetDocumentQuotaAsync(companyId);
            throw new BusinessRuleException(
                DocumentQuotaPolicy.BlockedMessage(used, limit), "QUOTA-DOCUMENTS");
        }

        // Check feature access
        if (!await _subscriptionService.CheckFeatureAccessAsync(companyId, FeatureFlags.DocumentEngine))
            throw new InvalidOperationException("ไม่มีสิทธิ์ใช้ระบบเอกสาร");

        // Validate ContactId exists and has correct type for document
        var contact = await _db.Contacts.FirstOrDefaultAsync(c => c.Id == request.ContactId && c.CompanyId == companyId);
        if (contact == null)
            throw new InvalidOperationException("ไม่พบผู้ติดต่อในบริษัทนี้");

        // Duplicate-document soft check — เปรียบเอกสารที่กำลังสร้าง vs เอกสารใน
        // 60 วันล่าสุดของ vendor/customer คนเดียวกัน + ยอดใกล้เคียง (±0.5%)
        // ไม่ throw — แค่ log warning ลง ProcessingNotes (จะเห็นในหน้า detail) +
        // เรียกใช้ local DuplicateDocumentDistillationModel ตาม กฎเหล็ก #1
        // (กันลูกค้า upload OCR ซ้ำ / integration ส่งซ้ำ / user คลิก save 2 ครั้ง)
        var totalAmt = request.Lines.Sum(l => l.Quantity * l.UnitPrice);
        if (totalAmt > 0)
        {
            var since = request.DocumentDate.AddDays(-60);
            var likelyDupes = await _db.Documents.AsNoTracking()
                .Where(d => d.CompanyId == companyId
                    && d.ContactId == request.ContactId
                    && d.DocumentType == request.DocumentType
                    && d.Status != DocumentStatus.Voided && !d.IsDeleted
                    && d.DocumentDate >= since
                    && d.DocumentDate <= request.DocumentDate.AddDays(30)
                    && Math.Abs(d.TotalAmount - totalAmt) < totalAmt * 0.005m)
                .Select(d => new { d.Id, d.DocumentNumber, d.DocumentDate, d.TotalAmount })
                .Take(3).ToListAsync();
            if (likelyDupes.Count > 0)
            {
                var msg = string.Join("; ", likelyDupes.Select(x =>
                    $"{x.DocumentNumber} ({x.DocumentDate:yyyy-MM-dd} ฿{x.TotalAmount:N2})"));
                _logger.LogWarning("Possible duplicate document for company {Co} contact {Ct} amount {Amt}: {Dupes}",
                    companyId, request.ContactId, totalAmt, msg);
                // ส่งสัญญาณกลับ frontend ผ่าน throw แบบ structured? ใช้ approach
                // เหมือน OcrService — log warning + ฝัง ProcessingNotes ของ doc ที่
                // สร้างเสร็จเพื่อให้ user เห็น banner ใน detail. กัน "false positive"
                // มาก็ block ไม่ได้ — vendor อาจขายของซ้ำเดิมจริง
            }
        }

        var revenueDocTypes = new[] {
            DocumentType.Quotation, DocumentType.Invoice, DocumentType.TaxInvoice,
            DocumentType.Receipt, DocumentType.ReceiptVoucher,
            DocumentType.DeliveryNote, DocumentType.BillingNote
        };
        var purchaseDocTypes = new[] {
            DocumentType.PurchaseRequisition, DocumentType.PurchaseOrder,
            DocumentType.GoodsReceiptNote,
            DocumentType.PurchaseInvoice, DocumentType.Expense, DocumentType.PaymentVoucher,
            DocumentType.CertificateInLieu
        };
        // ⚠️ CN/DN เป็นเอกสาร "สองฝั่ง" — เดิมถูกใส่ไว้ใน revenueDocTypes ตายตัว
        // ทำให้ใบลดหนี้ฝั่งซื้อ (ผู้ขายลดหนี้ให้เรา) ถูกปฏิเสธด้วยข้อความว่า
        // "ผู้ติดต่อไม่ได้ตั้งค่าเป็นลูกค้า" ทั้งที่คู่ค้ารายนั้นคือผู้ขาย ไม่ใช่ลูกค้า
        // → ตรวจตามฝั่งที่ผู้ใช้เลือกจริง
        var isTwoSidedAdj = request.DocumentType is DocumentType.CreditNote or DocumentType.DebitNote;
        // ฝั่งของใบลดหนี้/เพิ่มหนี้ต้องดู **ใบต้นทาง** ด้วย ไม่ใช่แต่ override ที่ผู้ใช้ติ๊ก:
        // `ConvertCoreAsync` ส่ง `RelatedDocumentId` มาแต่ **ไม่เคยส่ง**
        // `CnDnPurchaseSideOverride` (ไล่พารามิเตอร์ครบแล้วที่ `:9378-9421`) ⇒ การแปลง
        // "ใบแจ้งหนี้ซื้อ → ใบลดหนี้" ซึ่งเป็นเส้น**เดียว**ที่คัดลอกผังบัญชีรายบรรทัด
        // มาให้ครบ (`:9359 s.Line.AccountId`) ตกด่านข้างล่างนี้ด้วยข้อความ "ไม่ได้ตั้งค่า
        // เป็นลูกค้า" ทุกครั้ง (คู่ค้าของใบซื้อเป็น supplier ไม่ใช่ลูกค้า) ⇒ ผู้ใช้ถูกบีบ
        // ไปคีย์มือแล้วไปเจอผังที่ค้างฝั่งขาย — นี่คือรากร่วมของบั๊กที่ผู้ใช้รายงาน
        //
        // ตัวตัดสินฝั่งที่ถูกต้องมีอยู่แล้วที่ `:1118-1125` แต่อยู่**หลัง**ด่านนี้ ~200 บรรทัด
        // (R4 "สองด่านในเมธอดเดียวที่เรียงผิดลำดับ") — ที่นี่ใช้ตัวตัดสินเดียวกันผ่าน
        // `Helpers/AdjustmentNoteAccount.ResolveSide` เพื่อไม่ให้มีสำเนากติกาชุดที่สอง
        DocumentType? adjSourceType = null;
        if (isTwoSidedAdj && request.RelatedDocumentId.HasValue)
            adjSourceType = await _db.Documents.AsNoTracking()
                .Where(x => x.Id == request.RelatedDocumentId.Value && x.CompanyId == companyId)
                .Select(x => (DocumentType?)x.DocumentType)
                .FirstOrDefaultAsync();
        var adjSideResolved = isTwoSidedAdj
            ? Accounting.Helpers.AdjustmentNoteAccount.ResolveSide(
                adjSourceType, request.CnDnPurchaseSideOverride)
            : null;
        var adjIsPurchase = adjSideResolved == true;
        if ((revenueDocTypes.Contains(request.DocumentType) || (isTwoSidedAdj && !adjIsPurchase))
            && !contact.IsCustomer)
            throw new InvalidOperationException($"ผู้ติดต่อ '{contact.Name}' ไม่ได้ตั้งค่าเป็นลูกค้า — กรุณาเปิดสถานะ 'ลูกค้า' ก่อนออกเอกสารขาย");
        if ((purchaseDocTypes.Contains(request.DocumentType) || adjIsPurchase)
            && !contact.IsSupplier)
            throw new InvalidOperationException($"ผู้ติดต่อ '{contact.Name}' ไม่ได้ตั้งค่าเป็นผู้จำหน่าย — กรุณาเปิดสถานะ 'ผู้จำหน่าย' ก่อนออกเอกสารซื้อ");

        // Validate project tags belong to this company (security: prevent cross-tenant tagging)
        if (request.ProjectId.HasValue)
        {
            var projectOk = await _db.Projects.AnyAsync(p =>
                p.Id == request.ProjectId.Value && p.CompanyId == companyId);
            if (!projectOk)
                throw new InvalidOperationException("ไม่พบโครงการในบริษัทนี้");
        }
        var lineProjectIds = request.Lines?.Where(l => l.ProjectId.HasValue)
            .Select(l => l.ProjectId!.Value).Distinct().ToList() ?? new List<Guid>();
        if (lineProjectIds.Count > 0)
        {
            var validCount = await _db.Projects
                .CountAsync(p => p.CompanyId == companyId && lineProjectIds.Contains(p.Id));
            if (validCount != lineProjectIds.Count)
                throw new InvalidOperationException("รหัสโครงการในรายการบางบรรทัดไม่ถูกต้อง");
        }

        // CertificateInLieu requires reason and certifier
        if (request.DocumentType == DocumentType.CertificateInLieu)
        {
            if (string.IsNullOrWhiteSpace(request.CertificateReason))
                throw new InvalidOperationException("ใบรับรองแทนใบเสร็จต้องระบุเหตุผลที่ไม่ได้รับใบเสร็จ");
            if (string.IsNullOrWhiteSpace(request.CertifierName))
                throw new InvalidOperationException("ใบรับรองแทนใบเสร็จต้องระบุชื่อผู้รับรอง");
        }

        // Validate the line items (shared with UpdateDocumentAsync so an edit
        // can't bypass the same accounting guards a create enforces).
        await ValidateDocumentLinesAsync(companyId, request.Lines);

        // Fiscal-period lock at CREATE — don't even let a document be drafted
        // into a closed/locked period (previously only blocked at approval,
        // which let a doc be created then fail later). Keeps the books tidy.
        var createPeriod = await _db.FiscalPeriods.AsNoTracking().FirstOrDefaultAsync(f =>
            f.CompanyId == companyId && f.StartDate <= request.DocumentDate && f.EndDate >= request.DocumentDate);
        if (createPeriod != null && createPeriod.Status != FiscalPeriodStatus.Open)
            throw new InvalidOperationException(
                $"ไม่สามารถสร้างเอกสารที่มีวันที่ในงวด {createPeriod.Name} ได้ เนื่องจากงวดดังกล่าวมีสถานะ {createPeriod.Status} (ปิดงวดแล้ว)");

        await using var transaction = await _db.Database.BeginTransactionAsync();
        try
        {
            // Defer real sequence number to Approve — Draft uses a temporary
            // placeholder ("DRAFT-{guid8}") instead of pulling from the
            // company's running counter. That eliminates the gap-on-delete
            // problem entirely: deleting a Draft never leaves a missing
            // sequence number because none was issued. The real number is
            // assigned atomically inside ApproveDocumentAsync. Indexes built
            // on DocumentNumber stay valid because placeholders are unique
            // (guid suffix). Compliance for TaxInvoice/Receipt is satisfied
            // since they only get a real number when they enter the books.
            var draftMarker = $"DRAFT-{Guid.NewGuid():N}".Substring(0, 14);
            var docNumber = draftMarker;

            // Resolve FX up front so the rate the user sees on the document
            // is exactly what posts to the GL on Approve. THB → always 1.
            // Non-THB: caller's override wins; otherwise auto-fetch BoT mid-rate
            // at DocumentDate. If BoT lookup fails, refuse — silent fallback to
            // 1 would corrupt the GL.
            var fxRate = await ResolveExchangeRateAsync(request.Currency, request.ExchangeRate, request.DocumentDate);

            // ใบมัดจำต้อง standalone (audit #10): ใบเสร็จที่อ้างเอกสารต้นทางจะ post
            // เป็น "ตัดชำระลูกหนี้" (Cr 113) ไม่แตะ 217xx → ติดธง IsDeposit ไป
            // ก็จะโชว์คงค้างบนหน้ามัดจำทั้งที่ GL ไม่มีหนี้สินมัดจำ + ทำให้ void-
            // restore นับ 113 เพี้ยน
            if (request.IsDeposit && request.RelatedDocumentId.HasValue)
                throw new InvalidOperationException(
                    "ใบมัดจำต้องเป็นเอกสาร standalone — ห้ามอ้างเอกสารต้นทาง " +
                    "(ใบเสร็จที่อ้างใบแจ้งหนี้ = การตัดชำระ ไม่ใช่การรับมัดจำ)");

            // P0-1 รอบ 193: ธง "หักมัดจำแบบขับ JE" บนชนิดที่ AutoPost ไม่อ่าน = silent no-op (ลูกหนี้เต็ม · มัดจำค้าง)
            if ((request.DepositAppliedDrivesJournal ?? false)
                && !Accounting.Helpers.DepositPolicyResolver.DrivesJournalSupported(request.DocumentType, request.IssuedAsCashReceipt ?? false))
                throw new Accounting.Helpers.BusinessRuleException(
                    Accounting.Helpers.DepositPolicyResolver.DrivesUnsupportedMessage, "DEPOSIT-DRIVES-UNSUPPORTED");

            var doc = new Document
            {
                CompanyId = companyId,
                DocumentNumber = docNumber,
                DocumentType = request.DocumentType,
                // Normalize เป็น "วันที่ไทย ณ 00:00 UTC" — กัน timestamptz shift
                // (02/06 ส่งมา → ห้ามเก็บ 01/06 17:00 UTC ที่ทำเลข/ภพ.30 ผิดวัน)
                DocumentDate = Accounting.Helpers.ThaiDate.CalendarDateUtc(request.DocumentDate),
                Currency = string.IsNullOrWhiteSpace(request.Currency) ? "THB" : request.Currency.ToUpperInvariant(),
                ExchangeRate = fxRate,
                DueDate = Accounting.Helpers.ThaiDate.CalendarDateUtc(request.DueDate),
                ContactId = request.ContactId,
                Reference = request.Reference,
                Notes = request.Notes,
                Sensitivity = request.Sensitivity,
                ProjectId = request.ProjectId,
                DimensionId = request.DimensionId,
                BankAccountId = request.BankAccountId,
                PaymentAccountId = request.PaymentAccountId,
                ExpenseCategoryId = request.ExpenseCategoryId,
                CustomAppendix = request.CustomAppendix,
                CustomFooterNotes = request.CustomFooterNotes,
                CustomTermsAndConditions = request.CustomTermsAndConditions,
                RevenueContractId = request.RevenueContractId,
                PerformanceObligationId = request.PerformanceObligationId,
                CertificateReason = request.CertificateReason,
                CertifierName = request.CertifierName,
                CertifierPosition = request.CertifierPosition,
                WitnessName = request.WitnessName,
                WitnessPosition = request.WitnessPosition,
                PaymentDate = request.PaymentDate,
                // Required for CreditNote. Save only when actually a CN —
                // ignored on other types so a stale UI value can't leak
                // through. Approval-time validator (below) bounces a CN
                // missing this.
                CreditNoteReason = request.DocumentType == DocumentType.CreditNote
                    ? request.CreditNoteReason
                    : null,
                // เหตุผลใบเพิ่มหนี้ (§86/9) — เก็บเฉพาะตอนเป็น DN จริง ๆ เหมือนฝั่ง CN
                DebitNoteReason = request.DocumentType == DocumentType.DebitNote
                    ? request.DebitNoteReason
                    : null,
                // Counterparty tax-invoice metadata — only meaningful for
                // supplier-issued doc types (PurchaseInvoice, CertificateInLieu).
                // Stored unconditionally though so partner sync can round-trip.
                SupplierInvoiceNumber = request.SupplierInvoiceNumber,
                SupplierTaxInvoiceDate = request.SupplierTaxInvoiceDate,
                // PV: "ใช้งานใบกำกับภาษี" checkbox + supplier branch snapshot.
                // Branch defaults to "00000" (สำนักงานใหญ่) when flag is on but
                // user didn't fill it — covers the >95% case + matches the RD form.
                HasTaxInvoiceReference = request.HasTaxInvoiceReference,
                SupplierBranchCode = request.HasTaxInvoiceReference
                    ? (request.SupplierBranchCode ?? contact.BranchCode ?? "00000")
                    : request.SupplierBranchCode,
                CreditDays = request.CreditDays,
                PaymentTerms = request.PaymentTerms,
                DocumentLanguage = request.DocumentLanguage?.Trim().ToLowerInvariant() is "th" or "en"
                    ? request.DocumentLanguage!.Trim().ToLowerInvariant() : null,
                // เงินมัดจำ/รับล่วงหน้า — เฉพาะใบเสร็จ/ใบสำคัญรับ
                IsDeposit = request.IsDeposit
                    && (request.DocumentType == DocumentType.Receipt
                        || request.DocumentType == DocumentType.ReceiptVoucher),
                DepositDeferredAccountCode = request.DepositDeferredAccountCode,
                DepositOutputVatDeferred = request.DepositOutputVatDeferred,
                // Tax Point §78 inputs (optional)
                DeliveryDate = request.DeliveryDate,
                OwnershipTransferDate = request.OwnershipTransferDate,
                ServiceUsedDate = request.ServiceUsedDate,
                BookingNumber = string.IsNullOrWhiteSpace(request.BookingNumber) ? null : request.BookingNumber.Trim(),
                InputVatAccountCodeOverride = string.IsNullOrWhiteSpace(request.InputVatAccountCodeOverride) ? null : request.InputVatAccountCodeOverride.Trim(),
                // ใบแจ้งหนี้/ใบกำกับภาษี (combined) — ยอมรับ flag เฉพาะเมื่อ type เป็น
                // TaxInvoice จริง (frontend force type=TaxInvoice ตอนติ๊ก) เพื่อกัน
                // เอกสารประเภทอื่นมาตั้ง flag แล้วหัวกระดาษเพี้ยน.
                CombinedInvoiceTaxInvoice = request.CombinedInvoiceTaxInvoice
                    && request.DocumentType == DocumentType.TaxInvoice,
                DepositAppliedAmount = request.DepositAppliedAmount ?? 0m,
                DepositAppliedRef = string.IsNullOrWhiteSpace(request.DepositAppliedRef) ? null : request.DepositAppliedRef.Trim(),
                OriginModule = string.IsNullOrWhiteSpace(originModule) ? null : originModule.Trim(),
                DepositAppliedDrivesJournal = request.DepositAppliedDrivesJournal ?? false,
                BuyerDeclinedTaxInvoice = request.BuyerDeclinedTaxInvoice ?? false,
                // ขายเงินสด ใบเดียว (เฉพาะ TaxInvoice ฝั่งขาย) — AutoPost ลงแบบเงินสด
                // ไม่ตั้งลูกหนี้ + ไม่ออกใบเสร็จแยก, e-Tax T03. approve ปิดยอด Paid
                IssuedAsCashReceipt = (request.IssuedAsCashReceipt ?? false)
                    && request.DocumentType == DocumentType.TaxInvoice,
                // เจตนา "รับเงินครบแล้ว ณ วันออก" (โหมด tax_paid) — เก็บลงเอกสาร
                // ให้ echo กลับฟอร์ม + หัวใบร่างพิมพ์รวมตรงกับที่เลือก
                PaidOnIssue = (request.PaidOnIssue ?? false)
                    && request.DocumentType is DocumentType.TaxInvoice or DocumentType.Invoice,
                // ผู้จัดทำจากระบบต้นทาง (คนทำจริง) → ช่อง "ผู้จัดทำ/ผู้รับเงิน" บน PDF
                // แทน CreatedBy user (เหมือน integration PV/invoice)
                PreparerName = string.IsNullOrWhiteSpace(request.PreparerName) ? null : request.PreparerName.Trim(),
                PreparerSignatureBase64 = string.IsNullOrWhiteSpace(request.PreparerSignatureBase64) ? null : request.PreparerSignatureBase64.Trim(),
                CreatedBy = createdBy
            };

            // ===== Settlement basis + ROLE SEPARATION (หลักบัญชีไทย) =====
            // ใบบันทึกค่าใช้จ่าย (Expense)   = "คำขอ/ตั้งหนี้" — บันทึกภาระ
            //   ค่าใช้จ่ายเข้าเจ้าหนี้ ไม่มีเงินออก (GL: Dr ค่าใช้จ่าย / Cr เจ้าหนี้)
            // ใบสำคัญจ่าย (PaymentVoucher)  = "การดำเนินการจ่ายเงินจริง" —
            //   เงินออกเสมอ (GL: Cr เงินสด/ธนาคาร; ถ้าอ้างอิงเอกสารตั้งหนี้
            //   จะตัดเจ้าหนี้ให้ด้วย) จึงห้ามเป็น "เครดิต" แบบลอย ๆ
            // ลิงก์เอกสารต้นทาง (จาก ConvertCoreAsync) — ต้องเซ็ตก่อน infer
            // PaymentType/cash-settle/auto-approve เพราะทั้งหมดแยก "PV ตั้งต้น"
            // กับ "PV settle เอกสารตั้งหนี้" ด้วย field นี้. เดิมเซ็ตหลังสร้าง →
            // PV แปลงจากใบแจ้งหนี้ซื้อถูก auto-approve เป็น standalone cash
            // ก่อนมีลิงก์ → settlement ไม่ทำงาน (PI ค้างชำระ) + JE ลงค่าใช้จ่าย
            // ซ้ำแทนตัดเจ้าหนี้
            if (request.RelatedDocumentId.HasValue)
                doc.RelatedDocumentId = request.RelatedDocumentId;

            // ฝั่งภาษีของ CN/DN ที่ผู้ใช้เลือกไว้บนฟอร์ม — เก็บตั้งแต่สร้าง
            // AutoPost/รายงานภาษีอ่านค่านี้เป็นชั้นแรก จึงไม่ต้องเดาอีกต่อไป
            if (request.CnDnPurchaseSideOverride.HasValue
                && doc.DocumentType is DocumentType.CreditNote or DocumentType.DebitNote)
                doc.CnDnPurchaseSideOverride = request.CnDnPurchaseSideOverride;

            // ── กันเอกสารที่ขัดแย้งกันเอง ──────────────────────────────
            // ใบลดหนี้ "ฝั่งขาย" ห้ามอ้างใบกำกับ "ซื้อ" และกลับกัน — ถ้าปล่อยผ่าน
            // JE จะลงฝั่งหนึ่งแต่ใบต้นทางอยู่อีกฝั่ง → ภ.พ.30 หักยอดผิดฝั่ง และ
            // กระดาษอ้างใบที่ไม่เกี่ยวกัน (§86/9-10 ต้องอ้างใบกำกับ "ของรายการนั้น")
            if (doc.DocumentType is DocumentType.CreditNote or DocumentType.DebitNote
                && doc.RelatedDocumentId.HasValue)
            {
                var srcType = await _db.Documents.AsNoTracking()
                    .Where(x => x.Id == doc.RelatedDocumentId.Value && x.CompanyId == companyId)
                    .Select(x => (DocumentType?)x.DocumentType)
                    .FirstOrDefaultAsync();
                if (srcType.HasValue)
                {
                    // ชุดชนิด "ใบต้นทางฝั่งซื้อ" อ่านจาก OWNER file ตัวเดียว —
                    // เดิมพิมพ์มือซ้ำ 6 ที่ (F2 ข้อ 4)
                    var srcIsPurchase =
                        Accounting.Helpers.AdjustmentNoteAccount.SourceIsPurchaseSide(srcType.Value);
                    // ไม่ได้ระบุฝั่งมา → ยึดฝั่งของใบต้นทาง (ชัดเจนที่สุด ไม่ต้องเดา)
                    if (!doc.CnDnPurchaseSideOverride.HasValue)
                        doc.CnDnPurchaseSideOverride = srcIsPurchase;
                    else if (doc.CnDnPurchaseSideOverride.Value != srcIsPurchase)
                        throw new InvalidOperationException(
                            $"ฝั่งของเอกสารไม่ตรงกับใบต้นทาง — เลือกไว้เป็นฝั่ง"
                            + $"{(doc.CnDnPurchaseSideOverride.Value ? "ซื้อ" : "ขาย")} "
                            + $"แต่ใบที่อ้างอิงเป็นเอกสารฝั่ง{(srcIsPurchase ? "ซื้อ" : "ขาย")} "
                            + "— เลือกใบต้นทางให้ตรงฝั่ง หรือเปลี่ยนฝั่งของใบนี้ให้ตรงกับใบต้นทาง");
                }
            }

            // CN/DN สกุลต่างประเทศที่อ้างใบเดิม: ใช้เรทของใบเดิม (ไม่ใช่เรท BOT
            // วันออก CN) — ตัด AR/AP ต้องเท่ายอดที่ตั้งไว้เป๊ะ ไม่งั้นเศษเรทค้าง
            // ในลูกหนี้/เจ้าหนี้ถาวรโดยไม่มีขา FX gain/loss (convert flow copy
            // เรทมาให้อยู่แล้ว — เส้นนี้ครอบเคสสร้างตรง/เลือกจาก dropdown)
            if ((request.DocumentType == DocumentType.CreditNote
                    || request.DocumentType == DocumentType.DebitNote)
                && doc.RelatedDocumentId.HasValue
                && !string.Equals(doc.Currency, "THB", StringComparison.OrdinalIgnoreCase))
            {
                var srcFxInfo = await _db.Documents.AsNoTracking()
                    .Where(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId)
                    .Select(d => new { d.Currency, d.ExchangeRate })
                    .FirstOrDefaultAsync();
                if (srcFxInfo != null
                    && string.Equals(srcFxInfo.Currency, doc.Currency, StringComparison.OrdinalIgnoreCase)
                    && srcFxInfo.ExchangeRate > 0)
                    doc.ExchangeRate = srcFxInfo.ExchangeRate;
            }

            if (request.DocumentType == DocumentType.PaymentVoucher)
            {
                // A standalone PV must represent real cash leaving the company.
                // "Credit" is only meaningful when this PV SETTLES a prior
                // liability doc (PI/Expense via RelatedDocumentId from the
                // conversion path). An unpaid obligation belongs on an
                // Expense (ตั้งหนี้) instead.
                if (!doc.RelatedDocumentId.HasValue
                    && request.PaymentType == Models.Enums.PaymentType.Credit)
                    throw new InvalidOperationException(
                        "ใบสำคัญจ่ายคือเอกสารการจ่ายเงินจริง (เงินออกทันที) — " +
                        "หากยังไม่ได้จ่าย/ต้องการตั้งหนี้ไว้ก่อน กรุณาใช้ \"ใบบันทึกค่าใช้จ่าย\" " +
                        "แล้วแปลงเป็นใบสำคัญจ่ายเมื่อจ่ายเงินจริง");
                doc.PaymentType = request.PaymentType
                    ?? (doc.RelatedDocumentId.HasValue ? Models.Enums.PaymentType.Credit
                                                       : Models.Enums.PaymentType.Cash);
            }
            else if (request.DocumentType == DocumentType.Expense)
            {
                // The request/accrual document never moves cash by itself —
                // marking it "จ่ายทันที" would flag it paid while its GL
                // posting still credits AP, leaving a payable nobody clears.
                if (request.PaymentType == Models.Enums.PaymentType.Cash)
                    throw new InvalidOperationException(
                        "ใบบันทึกค่าใช้จ่ายคือเอกสารตั้งหนี้/คำขอ (ยังไม่จ่ายเงิน) — " +
                        "ถ้าจ่ายเงินสดทันทีให้ใช้ \"ใบสำคัญจ่าย\" หรือบันทึกใบนี้เป็นตั้งหนี้ " +
                        "แล้วแปลงเป็นใบสำคัญจ่าย/บันทึกการชำระเมื่อจ่ายจริง");
                doc.PaymentType = Models.Enums.PaymentType.Credit;
            }
            else if (request.DocumentType == DocumentType.CertificateInLieu)
            {
                // ใบรับรองแทนใบเสร็จ is always an immediate cash payment — no
                // payable, no outstanding balance (its JE credits Cash).
                doc.PaymentType = Models.Enums.PaymentType.Cash;
            }
            else if (request.DocumentType == DocumentType.Receipt
                     || request.DocumentType == DocumentType.ReceiptVoucher)
            {
                // ใบเสร็จ/ใบสำคัญรับ = หลักฐาน "รับเงินแล้วจริง" — JE ตอนอนุมัติ
                // Dr เงินสด/ธนาคารเสมอ. "เครดิต" ไม่มีความหมายกับเอกสารนี้:
                // ถ้าปล่อยเป็น Credit เอกสารจะค้าง BalanceDue ทั้งที่เงินเข้า GL
                // ไปแล้ว → โผล่ใน aging ผิด ๆ และถูก "รับชำระ" ซ้ำได้ (เงินสด
                // เบิ้ลสองรอบ). ยังไม่รับเงิน → ใช้ใบแจ้งหนี้/ใบกำกับแทน
                doc.PaymentType = Models.Enums.PaymentType.Cash;
            }
            else
            {
                doc.PaymentType = request.PaymentType;
            }
            var isCashSettled = doc.PaymentType == Models.Enums.PaymentType.Cash;

            // เทอมเครดิตที่ตั้งไว้กับคู่ค้า — ชั้น fallback ของ **ฝั่ง server**
            //
            // เดิมลำดับ "ผู้ใช้ > คู่ค้า > เทมเพลต" อยู่บนหน้าจออย่างเดียว ⇒ เอกสาร
            // ที่สร้างผ่าน API/integration/งาน recurring ที่ไม่ได้ส่ง CreditDays มา
            // จะไม่ได้เครดิตของคู่ค้าเลย (ใบเดียวกันสร้างคนละทางได้เทอมไม่เท่ากัน)
            // ที่นี่เติมเฉพาะตอน caller ไม่ได้ระบุมา — ผู้เรียกยังชนะเสมอ
            // (เงื่อนไขครอบขยาย: ภาษาเอกสารต่อผู้ติดต่อใช้ fallback ก้อนเดียวกัน —
            // ต้องรันแม้ CreditDays ถูกระบุมาแล้ว)
            if ((!doc.CreditDays.HasValue || doc.DocumentLanguage == null) && doc.ContactId != Guid.Empty)
            {
                var partner = await _db.Contacts.AsNoTracking()
                    .Where(c => c.Id == doc.ContactId && c.CompanyId == companyId)
                    .Select(c => new { c.PaymentDueDays, c.PaymentTerms, c.DocumentLanguage })
                    .FirstOrDefaultAsync();
                if (!doc.CreditDays.HasValue)
                {
                    if (partner?.PaymentDueDays is > 0) doc.CreditDays = partner.PaymentDueDays;
                    if (string.IsNullOrWhiteSpace(doc.PaymentTerms)
                        && !string.IsNullOrWhiteSpace(partner?.PaymentTerms))
                        doc.PaymentTerms = partner!.PaymentTerms;
                }
                // ภาษาเริ่มต้นของผู้ติดต่อ — เติมเฉพาะตอน caller ไม่ได้ระบุ (ผู้เรียก
                // ชนะเสมอ) เพื่อให้ใบที่สร้างผ่าน API/recurring ได้ภาษาเดียวกับใบ
                // ที่สร้างผ่านฟอร์ม (กติกาเดียวกับเครดิตเทอมข้างบน)
                if (doc.DocumentLanguage == null && partner?.DocumentLanguage is "th" or "en")
                    doc.DocumentLanguage = partner.DocumentLanguage;
            }

            // เทอมเครดิตมีความหมายเฉพาะชนิดที่ก่อ "หนี้ใหม่รอเก็บ/รอจ่าย" —
            // ชนิดอื่นล้างทิ้งก่อน (กันค่าหลุดจาก API ภายนอก/OCR/ค่าค้างบนฟอร์ม
            // ไปโผล่บน PDF และทำรายงาน DSO/DPO เพี้ยน)
            NormalizeCreditTermFields(doc);

            // Auto-fill DueDate from CreditDays when caller didn't provide one
            // explicitly. Keeps DSO/DPO reports working even when the partner
            // API only sends credit terms. Cash-settled documents never carry a
            // due date (the money already moved).
            if (isCashSettled)
                doc.DueDate = null;
            // เครดิต 0 วัน = "จ่ายทันที" ไม่ใช่ "ไม่ระบุ" ⇒ ครบกำหนด = วันที่เอกสาร
            // (เดิมเงื่อนไข `> 0` ทำให้ 0 ตกไปเหมือนไม่ได้กรอก แล้ววันครบกำหนดว่าง
            // ทั้งที่ผู้ใช้ระบุมาชัดเจน — คู่กับบั๊ก `|| null` ฝั่งฟอร์มที่ทำให้ 0
            // ไม่เคยเดินทางมาถึงที่นี่เลย)
            else if (doc.DueDate == null && doc.CreditDays.HasValue && doc.CreditDays.Value >= 0)
                doc.DueDate = doc.DocumentDate.AddDays(doc.CreditDays.Value);

            // Auto-link Revenue Contract via Project when not explicitly provided.
            // If document is tagged to a project that has exactly one active
            // RevenueContract, link this doc to that contract automatically.
            if (request.ProjectId.HasValue && !request.RevenueContractId.HasValue)
            {
                var contracts = await _db.Set<RevenueContract>()
                    .Where(rc => rc.CompanyId == companyId
                        && rc.ProjectId == request.ProjectId.Value
                        && !rc.IsDeleted)
                    .Select(rc => rc.Id)
                    .Take(2)
                    .ToListAsync();
                if (contracts.Count == 1)
                    doc.RevenueContractId = contracts[0];
            }

            // เจตนางวดเคลมภาษีซื้อ (push) — validate §82/3 ตั้งแต่สร้าง
            // (ใบใหม่ยังไม่มีบรรทัดรายงาน กติกา 1 ผ่านแน่ ส่วน undue ถ้า
            // ภายหลังลงเป็น 11640 ตอนอนุมัติ เจตนาจะถูกล้างที่จุด post)
            if (!string.IsNullOrWhiteSpace(request.InputVatClaimPeriod))
                await ApplyInputVatClaimPeriodAsync(companyId, doc, request.InputVatClaimPeriod);

            // รอบ 193 (เจ้าของข้อ 1/4/8): ยอดชำระจริง + ผลต่างปัดเศษ — ค่าที่ client ส่งมาต้องผ่านตัวตรวจกลาง
            if (request.ActualPaidAmount is decimal createActualPaid)
            {
                if (createActualPaid < 0m)
                    throw new Accounting.Helpers.BusinessRuleException(
                        "ยอดชำระจริงต้องไม่ติดลบ — เว้นว่างเมื่อจ่ายเต็มตามยอดเอกสาร",
                        Accounting.Helpers.PaymentSettlementAdjustment.RuleCode);
                doc.ActualPaidAmount = createActualPaid == 0m ? null : createActualPaid;
            }
            if (request.RoundingAdjustment is decimal createRounding && createRounding != 0m)
            {
                if (Accounting.Helpers.DocumentRounding.Validate(createRounding) is string createRoundErr)
                    throw new Accounting.Helpers.BusinessRuleException(createRoundErr, Accounting.Helpers.DocumentRounding.RuleCode);
                doc.RoundingAdjustment = createRounding;
            }

            _db.Documents.Add(doc);

            decimal subTotal = 0, totalDiscount = 0, totalVat = 0, totalWht = 0;
            var order = 1;

            // โหลด InputVatClaimable flag ของทุกบัญชีที่ line ใช้ — รอบเดียว
            // ไว้บังคับ IsVatClaimable=false เมื่อบัญชีเป็นภาษีซื้อต้องห้าม.
            // resolve AccountCode → AccountId ก่อน (AI suggestion + integration
            // ส่งมาเป็น code) ภายในผังของบริษัท
            var codeCache = new Dictionary<string, Guid?>(StringComparer.OrdinalIgnoreCase);
            foreach (var line in request.Lines ?? [])
            {
                if (!line.AccountId.HasValue && !string.IsNullOrWhiteSpace(line.AccountCode))
                {
                    var resolved = await ResolveAccountCodeAsync(companyId, line.AccountCode, codeCache);
                    if (resolved.HasValue)
                    {
                        // mutate via reflection-free pattern: rebuild line tuple
                        // (DocumentLineRequest is a record). Instead, store in a
                        // side map and read at construction below.
                    }
                }
            }
            // build a side map LineIndex → resolved AccountId so we don't mutate the record list
            var resolvedAccountIds = new Dictionary<int, Guid>();
            for (int i = 0; i < (request.Lines?.Count ?? 0); i++)
            {
                var l = request.Lines![i];
                if (l.AccountId.HasValue) { resolvedAccountIds[i] = l.AccountId.Value; continue; }
                if (!string.IsNullOrWhiteSpace(l.AccountCode))
                {
                    var rid = await ResolveAccountCodeAsync(companyId, l.AccountCode, codeCache);
                    if (rid.HasValue) resolvedAccountIds[i] = rid.Value;
                }
            }
            var accountIds = resolvedAccountIds.Values.Distinct().ToList();
            var accountMeta = accountIds.Count == 0
                ? new Dictionary<Guid, ChartOfAccount>()
                : await _db.ChartOfAccounts.AsNoTracking()
                    .Where(a => a.CompanyId == companyId && accountIds.Contains(a.Id))
                    .ToDictionaryAsync(a => a.Id);
            var accountFlags = accountMeta.ToDictionary(kv => kv.Key, kv => kv.Value.InputVatClaimable);

            // บริษัทไม่จด VAT → เคลมภาษีซื้อไม่ได้ทุกบรรทัด — VAT ที่จ่ายผู้ขาย
            // รวมเป็นต้นทุน/ค่าใช้จ่าย ไม่เข้า 11610/11640 (เช็คครั้งเดียว)
            // ไม่มีแถวค่าตั้ง → ธงบริษัท (เดิม `?? true` = "จด" เสมอ · S-01) — ตัวอ่านตัวเดียว
            var companyVatReg = await Accounting.Helpers.CompanyVatStatus.IsRegisteredAsync(_db, companyId);

            doc.PricesIncludeVat = request.PricesIncludeVat;
            // ต้องเป็นของบริษัทนี้เท่านั้น + Guid.Empty = ไม่เลือก (normalize ที่นี่
            // ด้วย ไม่ใช่เฉพาะตอน update — caller อื่นส่ง Empty มาตอน create ได้)
            doc.BrandId = await ResolveOwnedBrandIdAsync(companyId, request.BrandId);
            // สาขาผู้ออกใบ — null/Empty = ใช้ค่าบริษัทตามเดิม (กิจการสาขาเดียว)
            doc.BranchId = await ResolveOwnedBranchIdAsync(companyId, request.BranchId);
            doc.DocumentTemplateId = await ResolveOwnedTemplateIdAsync(companyId, request.DocumentTemplateId);
            doc.IsForeignService = request.IsForeignService;
            // ส่วนลด "ท้ายบิล" (จากยอดรวม) — เฉลี่ย pro-rata ลงแต่ละบรรทัด (ex-VAT)
            // ก่อนคิด VAT รายบรรทัด → รวมทั้งบิลถูกต้องแม้ VAT คนละอัตรา (§86/4)
            var createLines = request.Lines ?? [];
            var billAlloc = AllocateBillDiscount(createLines, request.PricesIncludeVat,
                request.BillDiscountPercent ?? 0m, request.BillDiscountAmount ?? 0m);
            // คิดยอดครบทุกบรรทัดก่อน แล้วกระทบยอดเศษสตางค์ต่อกลุ่มอัตรา — ให้
            // ΣVAT/WHT ตรงกับการคิดจากฐานรวม (เครื่องคิดเลข) ก่อนค่อยเขียนบรรทัด
            var createAmts = new LineAmounts[createLines.Count];
            for (int i = 0; i < createLines.Count; i++)
                createAmts[i] = ComputeLineAmounts(createLines[i], request.PricesIncludeVat, billAlloc[i]);
            ReconcileTaxRounding(createLines, createAmts, request.PricesIncludeVat);
            int lineIdx = -1;
            foreach (var line in createLines)
            {
                lineIdx++;
                var amt = createAmts[lineIdx];

                subTotal += amt.NetAmount;
                totalDiscount += amt.DiscountAmount;
                totalVat += amt.VatAmount;
                totalWht += amt.WhtAmount;

                var lineAccountId = resolvedAccountIds.TryGetValue(lineIdx, out var rid) ? (Guid?)rid : null;
                // ผังรายบรรทัดต้องอยู่ฝั่งเดียวกับเอกสาร (กัน JE Cr รายได้เข้า 5xxxx)
                if (lineAccountId.HasValue && accountMeta.TryGetValue(lineAccountId.Value, out var lineAcct))
                    EnsureLineAccountMatchesDocSide(doc.DocumentType, line.Description, lineAcct,
                        doc.CnDnPurchaseSideOverride);
                // ภาษีซื้อต้องห้าม: ถ้าบัญชีตั้งเป็น InputVatClaimable=false
                // (เช่น ค่ารับรอง) → บังคับ line.IsVatClaimable=false
                // ไม่ว่า request จะส่งอะไรมา — รักษา consistency กับ chart
                // ของบริษัท. User ที่ต้องการเคลม VAT ต้องเปลี่ยน account
                // หรือเปลี่ยน flag ของบัญชีที่ผังบัญชี.
                var enforcedClaimable = line.IsVatClaimable;
                string? enforcedReason = line.VatNonClaimableReason;
                if (lineAccountId.HasValue && accountFlags.TryGetValue(lineAccountId.Value, out var acctClaimable) && !acctClaimable)
                {
                    enforcedClaimable = false;
                    enforcedReason ??= "บัญชีนี้ตั้งเป็นภาษีซื้อต้องห้ามในผังบัญชี";
                }
                if (!companyVatReg && amt.VatAmount > 0)
                {
                    enforcedClaimable = false;
                    enforcedReason ??= "บริษัทไม่ได้จดทะเบียน VAT — เคลมภาษีซื้อไม่ได้ (รวมเป็นต้นทุน)";
                }
                // ไม่มี VAT บนบรรทัด = ไม่มีอะไรให้เคลม → บังคับ false เสมอ
                // ตัวเลขไม่เปลี่ยน (ทุกสูตรคูณ/บวกกับ VatAmount ซึ่งเป็น 0 อยู่แล้ว)
                // แต่ **ห้ามเก็บ state ที่เป็นไปไม่ได้ลงฐาน**: แถวที่
                // IsVatClaimable=true แต่ VatAmount=0 ทำให้ UI โชว์ "✓ เคลม VAT"
                // ทั้งที่ไม่มีภาษีให้เคลม (ผู้ใช้เข้าใจผิด) และถ้าวันหนึ่งมีโค้ด
                // ใหม่นับ "จำนวนบรรทัดที่เคลมได้" แทนผลรวมยอด จะได้ตัวเลขผิดทันที
                // เหตุผล = null โดยตั้งใจ — นี่ไม่ใช่ภาษีซื้อต้องห้าม §82/5
                // จึงไม่ควรขึ้นป้ายเตือนสีแดงให้ผู้ใช้ตกใจ
                if (amt.VatAmount <= 0)
                {
                    enforcedClaimable = false;
                    enforcedReason = null;
                }
                _db.DocumentLines.Add(new DocumentLine
                {
                    DocumentId = doc.Id,
                    LineOrder = order++,
                    Description = line.Description,
                    Quantity = line.Quantity,
                    Unit = line.Unit ?? "ชิ้น",
                    UnitPrice = line.UnitPrice,
                    DiscountPercent = line.DiscountPercent,
                    DiscountAmount = amt.DiscountAmount,
                    Amount = amt.NetAmount,
                    VatRate = line.VatRate,
                    VatAmount = amt.VatAmount,
                    WithholdingTaxRate = line.WithholdingTaxRate,
                    WithholdingTaxAmount = amt.WhtAmount,
                    AccountId = lineAccountId,
                    ProjectId = line.ProjectId,
                    ProductCode = string.IsNullOrWhiteSpace(line.ProductCode) ? null : line.ProductCode.Trim(),
                    SourceLineId = line.SourceLineId,
                    IsVatClaimable = enforcedClaimable,
                    IsLandedCost = line.IsLandedCost,
                    VatNonClaimableReason = enforcedClaimable ? null : enforcedReason,
                    GlAccountAiFeedbackId = line.GlAccountAiFeedbackId,
                });
            }

            // รอบ 193: SubTotal = Σ บรรทัด + ผลต่างปัดเศษ (0 = สูตรเดิมทุกประการ — Helpers/DocumentRounding)
            doc.SubTotal = subTotal + doc.RoundingAdjustment;
            doc.DiscountAmount = totalDiscount;
            // ส่วนลดท้ายบิล: เก็บ % ที่กรอก + ยอด ex-VAT ที่หักจริง (Σ ที่เฉลี่ยลงบรรทัด)
            // subTotal เป็น "หลังหักท้ายบิลแล้ว" (= Σ line.Amount คงตัว invariant) →
            // PDF แสดง "รวมก่อนหักท้ายบิล" = SubTotal + BillDiscountAmount
            doc.BillDiscountPercent = request.BillDiscountPercent ?? 0m;
            doc.BillDiscountAmount = billAlloc.Sum();
            doc.VatAmount = totalVat;
            doc.WithholdingTaxAmount = totalWht;
            doc.TotalAmount = doc.SubTotal + totalVat - totalWht;
            // Cash-settled documents carry no outstanding balance — the cash
            // already moved, so PaidAmount = Total and BalanceDue = 0. This is
            // what keeps a จ่ายทันที voucher out of the aging / ค้างชำระ report
            // (the aging query keys on PaidAmount < TotalAmount).
            if (isCashSettled)
            {
                doc.PaidAmount = doc.TotalAmount;
                doc.BalanceDue = 0m;
            }
            else
            {
                doc.BalanceDue = doc.TotalAmount;
            }

            await _db.SaveChangesAsync();

            // นับเข้าโควตาเฉพาะใบที่ "แทนการขาย 1 ครั้ง" — ใบลดหนี้/ใบเสร็จรับชำระ/
            // เอกสารฝั่งซื้อ/เอกสารที่โมดูลที่พักออกให้ ไม่นับซ้ำ (มิเตอร์ของที่พัก
            // คือ lodging.stay ที่นับตอนปิดการเข้าพัก — DocumentQuotaPolicy)
            if (DocumentQuotaPolicy.Counts(quotaClass))
            {
                await _subscriptionService.IncrementUsageAsync(companyId, "document");
                // เกินโควตาแต่เป็นใบที่ห้ามปฏิเสธ → เกิดหนี้แทนการบล็อก
                if (!withinQuota) await RecordDocumentOverageAsync(companyId, doc);
            }

            await transaction.CommitAsync();

            // ใบสำคัญจ่าย (Cash) standalone — auto-approve ทันทีทุก channel
            // (UI/OCR/API). เงินจ่ายไปจริงแล้ว BalanceDue=0 ตั้งแต่ create
            // ไม่มีเหตุผลค้าง Draft ให้ผู้ใช้ต้องคลิก "อนุมัติ" อีกขั้น.
            // กรณี approve ล้มเหลว (§65 ตรี ไม่ระบุผู้รับ / period closed /
            // RequireApprovalForDocuments threshold) → log + คงค้าง Draft
            // ให้ผู้ใช้แก้แล้ว approve เอง.
            if (doc.DocumentType == DocumentType.PaymentVoucher
                && doc.PaymentType == Models.Enums.PaymentType.Cash
                && !doc.RelatedDocumentId.HasValue
                && doc.BalanceDue <= 0.005m)
            {
                try
                {
                    await ApproveDocumentAsync(companyId, doc.Id, createdBy, acknowledgeWarnings: true);
                }
                catch (Exception ex)
                {
                    _logger.LogInformation(ex,
                        "PV Cash auto-approve skipped for {DocId} — staying Draft for manual fix", doc.Id);
                }
            }

            var created = await GetDocumentAsync(companyId, doc.Id);
            await FireWebhookAsync(companyId, "document.created", created);
            return created;
        }
        catch
        {
            await transaction.RollbackAsync();
            throw;
        }
    }

    public async Task<DocumentResponse> GetDocumentAsync(Guid companyId, Guid documentId)
    {
        var doc = await _db.Documents
            .Include(d => d.Lines).ThenInclude(l => l.Project)
            .Include(d => d.Lines).ThenInclude(l => l.Account)
            .Include(d => d.Project)
            .Include(d => d.BankAccount)
            .Include(d => d.PaymentAccount)
            .Include(d => d.ExpenseCategory)
            // BrandName ใน DocumentResponse อ่านจาก nav ตัวนี้ — ไม่ Include =
            // null เสมอ ทั้งที่ DTO ประกาศว่า "echo กลับเพื่อ hydrate" (ผลตรวจข้อ 6)
            .Include(d => d.Brand)
            // BranchId/BranchName ใน DocumentResponse อ่านจาก nav ตัวนี้
            .Include(d => d.Branch)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");
        await _db.HydrateContactAsync(companyId, doc);  // กัน INNER JOIN ตัดใบที่ contact ถูกลบ

        var etax = await GetLatestEtaxAsync(companyId, new[] { documentId });

        // Conversion lineage — populate both directions so the detail
        // modal can show "แปลงมาจาก X" + "เอกสารต่อเนื่อง: Y, Z".
        DocumentBrief? upstream = null;
        if (doc.RelatedDocumentId.HasValue)
        {
            upstream = await _db.Documents
                .Where(p => p.Id == doc.RelatedDocumentId.Value && p.CompanyId == companyId)
                .Select(p => new DocumentBrief(p.Id, p.DocumentNumber, p.DocumentType,
                    p.Status, p.DocumentDate, p.TotalAmount))
                .FirstOrDefaultAsync();
        }
        var downstream = await _db.Documents
            .Where(c => c.RelatedDocumentId == documentId && c.CompanyId == companyId)
            .OrderBy(c => c.DocumentDate).ThenBy(c => c.CreatedAt)
            .Select(c => new DocumentBrief(c.Id, c.DocumentNumber, c.DocumentType,
                c.Status, c.DocumentDate, c.TotalAmount))
            .ToListAsync();

        var (pct, status) = await ComputeConversionStatusAsync(companyId, doc);

        // Project-cost booking summary — pull every PCE auto-spawned from
        // this doc (DocumentId or per-line DocumentLineId) and aggregate
        // by project so the UI can flag the doc "🏗️ ลงโครงการแล้ว 3 รายการ".
        var lineIds = doc.Lines.Select(l => l.Id).ToList();
        var pceRows = await _db.ProjectCostEntries
            .Where(c => c.CompanyId == companyId
                && !c.IsDeleted
                && (c.DocumentId == documentId
                    || (c.DocumentLineId.HasValue && lineIds.Contains(c.DocumentLineId.Value))))
            .Select(c => new {
                c.Id, c.ProjectId, c.DocumentLineId, c.Amount,
                ProjectCode = c.Project.Code,
                ProjectName = c.Project.Name,
            })
            .ToListAsync();

        var bookedByProject = pceRows
            .GroupBy(r => r.ProjectId)
            .Select(g => new ProjectCostBrief(
                g.Key, g.First().ProjectCode, g.First().ProjectName,
                g.Count(), g.Sum(r => r.Amount)))
            .OrderByDescending(b => b.Amount)
            .ToList();
        var pceByLine = pceRows
            .Where(r => r.DocumentLineId.HasValue)
            .GroupBy(r => r.DocumentLineId!.Value)
            .ToDictionary(g => g.Key, g => g.First().Id);

        // สถานะเคลมภาษีซื้อจาก "รายงาน ภ.พ.30 จริง" — badge บน UI ต้องตรงกับ
        // รายงาน ไม่ใช่เดาจาก flag บนเอกสาร. เอาบรรทัดฝั่งซื้อที่ active ล่าสุด
        // (ใบหนึ่งอยู่ได้งวดเดียวเพราะ dedup claimedElsewhere แต่กันเคสข้อมูลเก่า
        // ด้วย OrderByDescending)
        var pp30 = doc.VatAmount == 0 ? null
            : await _db.TaxReportLines.AsNoTracking()
                .Where(l => l.DocumentId == documentId && !l.IsExcluded
                    && (l.IncomeTypeCode == "INPUT" || l.IncomeTypeCode == "JE_INPUT")
                    && l.TaxReport.CompanyId == companyId
                    && l.TaxReport.TaxType == TaxType.VAT)
                .OrderByDescending(l => l.TaxReport.Year).ThenByDescending(l => l.TaxReport.Month)
                .Select(l => new { l.TaxReport.Month, l.TaxReport.Year, l.TaxReport.Status })
                .FirstOrDefaultAsync();

        // ใบเสร็จแยกที่อ้างใบนี้ (จาก downstream ที่โหลดไว้แล้ว) → ตัดสิน
        // ServedAsReceipt ให้ UI ตั้งป้ายหัวเอกสารตรงกับที่จะพิมพ์
        var hasSeparateReceiptDoc = (downstream ?? new List<DocumentBrief>()).Any(x =>
            (x.DocumentType == DocumentType.Receipt || x.DocumentType == DocumentType.ReceiptVoucher)
            && x.Status != DocumentStatus.Voided && x.Status != DocumentStatus.Draft
            && x.Status != DocumentStatus.Rejected);
        var resp = MapDocumentToResponse(doc, etax.GetValueOrDefault(documentId),
            upstream, downstream, pct, status,
            pceRows.Count > 0, pceRows.Count, pceRows.Sum(r => r.Amount), bookedByProject,
            pceByLine,
            servedAsReceipt: ComputeServedAsReceipt(doc, hasSeparateReceiptDoc,
                await GetReceiptIssueModeAsync(companyId),
                (await LoadSettlementDatesAsync(_db, companyId, new[] { documentId }))
                    .TryGetValue(documentId, out var settledOnDoc) ? settledOnDoc : null));
        if (pp30 != null)
            resp = resp with
            {
                InputVatPp30Month = pp30.Month,
                InputVatPp30Year = pp30.Year,
                InputVatPp30ReportStatus = pp30.Status.ToString(),
            };

        // หัวเอกสาร "ที่จะพิมพ์จริง" — คำนวณด้วยตัวเดียวกับ renderer แทนที่จะให้
        // หน้าเว็บเดาเอง (เดิม Layout.docHeaderLabel เป็นสำเนามือที่รู้จักแค่ 3 ธง
        // ⇒ เพี้ยนจากกระดาษ 5 เคส — ดู ResolveDocumentTitleAsync)
        // ServedAsReceipt ต้องเซ็ตให้ก่อน (ตัวคำนวณหัวอ่านจาก entity) —
        // SettlesTaxInvoiceSource ตัว resolver เติมเอง
        doc.ServedAsReceipt = resp.ServedAsReceipt;
        resp = resp with
        {
            DocumentTitle = await PdfGenerationService.ResolveDocumentTitleAsync(_db, companyId, doc),
        };

        // หัวถูกลดจากใบกำกับอย่างย่อเป็นใบเสร็จเพราะยังไม่มีสิทธิ์ §86/6 → บอกบนจอ (รอบ 191 — เดิมเงียบ)
        // ตัวตัดสินสิทธิ์ตัวเดียว AbbreviatedTaxInvoiceRule · ไม่พบแถว SiteSettings = บังคับ (ทิศเข้ม)
        if (doc.VatAmount > 0 && doc.DocumentType is DocumentType.TaxInvoice
                or DocumentType.Receipt or DocumentType.ReceiptVoucher)
        {
            var issuer = await _db.Companies.AsNoTracking()
                .Where(c => c.Id == companyId)
                .Select(c => new { c.IsVatRegistered, c.IsRetailApproved, c.PhoR06ApprovedDate })
                .FirstOrDefaultAsync();
            if (issuer != null)
            {
                var requirePhoR06 = await _db.SiteSettings.AsNoTracking()
                    .Select(x => (bool?)x.RequirePhoR06ForAbbreviatedTaxInvoice)
                    .FirstOrDefaultAsync() ?? true;
                var reason = Accounting.Helpers.AbbreviatedTaxInvoiceRule.Judge(
                    issuer.IsVatRegistered, issuer.IsRetailApproved, issuer.PhoR06ApprovedDate,
                    doc.DocumentDate, requirePhoR06);
                resp = resp with
                {
                    TaxInvoiceTitleNotice = PdfGenerationService.AbbreviatedDowngradeNotice(doc, reason),
                };
            }
        }

        // ── ใบกำกับภาษีเต็มรูปที่ออก "แทน" (§86/6 → §86/4) ──
        // ปุ่ม/ป้ายบนหน้าเว็บต้องอ่านค่าที่**เซิร์ฟเวอร์คำนวณ**เท่านั้น
        // (กติกาอยู่ใน FullTaxInvoiceReplacement.Check ตัวเดียวกับ endpoint)
        if (doc.DocumentType is DocumentType.Receipt or DocumentType.ReceiptVoucher)
        {
            var elig = await EvaluateFullTaxInvoiceReplacementAsync(companyId, doc);
            resp = resp with
            {
                CanIssueFullTaxInvoice = elig.Allowed,
                FullTaxInvoiceBlockedReason = elig.Allowed ? null : elig.Message,
            };
        }
        // เลขที่ของใบที่ผูกกัน — โชว์ให้ผู้ใช้กดไปดูได้ (ห้ามให้เขาไปค้นเองจาก id)
        var replacementLinkIds = new[] { doc.ReplacedByDocumentId, doc.ReplacesDocumentId }
            .Where(id => id.HasValue).Select(id => id!.Value).Distinct().ToList();
        if (replacementLinkIds.Count > 0)
        {
            var numbers = await _db.Documents.AsNoTracking()
                .Where(d => d.CompanyId == companyId && replacementLinkIds.Contains(d.Id))
                .Select(d => new { d.Id, d.DocumentNumber })
                .ToDictionaryAsync(x => x.Id, x => x.DocumentNumber);
            resp = resp with
            {
                ReplacedByDocumentNumber = doc.ReplacedByDocumentId.HasValue
                    && numbers.TryGetValue(doc.ReplacedByDocumentId.Value, out var byNo) ? byNo : null,
                ReplacesDocumentNumber = doc.ReplacesDocumentId.HasValue
                    && numbers.TryGetValue(doc.ReplacesDocumentId.Value, out var ofNo) ? ofNo : null,
            };
        }
        return resp;
    }

    /// <summary>Compute completion percent across child docs for the
    /// source doc passed in. Returns null when the doc has no source
    /// lines (i.e. nothing consumable) so the UI can hide the badge.
    /// </summary>
    /// <summary>
    /// ตั้ง "งวดที่ตั้งใจเคลมภาษีซื้อ" จากตัวเอกสาร (push) — เขียนลง
    /// InputVatBecameClaimableAt ซึ่ง GenerateVatReport มีกลไก "นับเฉพาะงวด
    /// ที่กำหนด" รองรับครบอยู่แล้ว (query OR-include + skip งวดอื่น)
    ///
    /// **ลำดับใครชนะใคร (ตัดสินใจแล้ว — ห้ามเปลี่ยนเงียบ ๆ):**
    ///   1. บรรทัดในรายงานจริง (non-excluded) ชนะเสมอ — รายงานคือสิ่งที่ยื่น
    ///      สรรพากร การแก้เอกสารห้ามไปย้ายบรรทัดของรายงานเงียบ ๆ (งวดนั้น
    ///      อาจยื่นแล้ว) → block พร้อมบอกงวด/สถานะ ให้ไปติ๊กออกจากรายงานก่อน
    ///   2. flow ใบกำกับไม่ครบ (11640/undue) ชนะเจตนา — งวดถูกกำหนดโดยการ
    ///      "เติมใบกำกับครบ §86/4" เท่านั้น
    ///   3. เจตนาบนเอกสาร = ค่าเริ่มต้นให้ generation หยิบเข้างวดที่เลือก
    ///
    /// ทำไมไม่ใช่ "action ล่าสุดชนะ": สอง action มีน้ำหนักไม่เท่ากัน —
    /// การดึงเข้ารายงานสร้างหลักฐานที่ยื่นจริง ส่วนช่องนี้เป็นแค่คำสั่งให้
    /// generation ถ้าล่าสุดชนะ การแก้เอกสารธรรมดาจะ mutate รายงานงวดอื่น
    /// โดยผู้ใช้ไม่รู้ตัว และทำไม่ได้เลยเมื่องวดนั้น Filed แล้ว
    /// </summary>
    /// <summary>ตั้ง/ย้ายงวดเคลมภาษีซื้อ — <b>ทางเดียวที่ผู้ใช้เปลี่ยนค่านี้ได้</b>
    /// (เรียกจากทั้ง 3 ทางเข้า: สร้างเอกสาร · แก้ไขเอกสาร · แผงภาษีซื้อในหน้าดู
    /// เอกสาร) ตัวตัดสินอยู่ที่ <see cref="InputVatClaimPeriodRules"/> ซึ่งเป็น
    /// pure function มีเทสต์ครอบ — เมธอดนี้ทำแค่ "หาข้อมูลให้กติกา แล้วลงมือทำ
    /// ตามที่กติกาบอก" จึงไม่มีทางที่ทางเข้าไหนจะได้ตารางตัดสินใจต่างกัน</summary>
    /// <summary>ตั้ง/ย้ายงวดเคลมภาษีซื้อของใบเดียว — ทางเข้าสาธารณะสำหรับหน้า
    /// นำส่งภาษี (ใบ ภ.พ.36 ที่รับรู้แล้ว ย้ายเดือนเคลมจากตรงนั้นได้เลย).
    /// ห่อตัวตรวจกลาง ApplyInputVatClaimPeriodAsync — กติกาครบทุกด่านเหมือน
    /// เส้นทางฟอร์ม (รายงานร่างย้ายให้+recalc · งวดยื่นแล้ว block · §82/3 ·
    /// ใบ undue ล้างงวดไม่ได้) ไม่มี logic ใหม่ที่นี่</summary>
    public async Task<DocumentResponse> SetInputVatClaimPeriodAsync(
        Guid companyId, Guid documentId, string? period, string actor)
    {
        var doc = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");
        await ApplyInputVatClaimPeriodAsync(companyId, doc, period);
        _db.AuditLogs.Add(new AuditLog
        {
            CompanyId = companyId,
            Action = AuditAction.Update,
            EntityType = "Document",
            EntityId = documentId.ToString(),
            NewValues = System.Text.Json.JsonSerializer.Serialize(new
            {
                action = "SetInputVatClaimPeriod",
                documentNumber = doc.DocumentNumber,
                period,
                by = actor,
            }),
        });
        await _db.SaveChangesAsync();
        return await GetDocumentAsync(companyId, documentId);
    }

    private async Task ApplyInputVatClaimPeriodAsync(Guid companyId, Document doc, string? raw)
    {
        // ── ขั้นที่ 1: ตัดสินจากตัวเอกสาร (ไม่แตะ DB — เคสส่วนใหญ่จบตรงนี้) ──
        var pre = InputVatClaimPeriodRules.DecideFromDocument(
            raw, doc.DocumentType, doc.InputVatBecameClaimableAt, doc.InputVatPostedAsUndue);
        if (pre.Outcome == InputVatClaimPeriodOutcome.NoChange) return;
        if (pre.Outcome == InputVatClaimPeriodOutcome.Blocked)
            throw new InvalidOperationException(pre.BlockReason!);

        // ── ขั้นที่ 2: ใบอยู่ในรายงาน ภ.พ.30 งวดไหนแล้วบ้าง ──
        // งวดร่างย้ายให้อัตโนมัติ (ติ๊กบรรทัดออก + recalc ด้วยกลไกเดียวกับหน้า
        // รายงาน) ส่วนงวดที่ยื่นแล้ว block — ที่มา: เดิม block ทุกกรณีแล้วสั่งให้
        // ไปติ๊กใบออกเองที่หน้ารายงาน ทั้งที่ปุ่ม "เลิกเคลม" บนหน้าเดียวกัน
        // (UnclaimInputVatAsync) ติ๊กบรรทัดงวดร่างออกให้เงียบ ๆ อยู่แล้ว ⇒ การ
        // กระทำแบบเดียวกันบนข้อมูลชุดเดียวกัน ได้คำตอบคนละอย่างแล้วแต่ทางเข้า
        var claimedLines = await _db.TaxReportLines
            .Include(l => l.TaxReport)
            .Where(l => l.DocumentId == doc.Id && !l.IsExcluded && !l.IsDeleted
                && l.TaxReport.CompanyId == companyId
                && l.TaxReport.TaxType == TaxType.VAT
                && l.IncomeTypeCode == "INPUT")
            .ToListAsync();
        var filedLine = claimedLines
            .FirstOrDefault(l => l.TaxReport.Status != TaxReportStatus.Draft);

        var post = InputVatClaimPeriodRules.DecideAgainstReports(
            pre.Period,
            doc.SupplierTaxInvoiceDate ?? doc.DocumentDate,
            filedLine == null ? null : (filedLine.TaxReport.Month, filedLine.TaxReport.Year));
        if (post.Outcome == InputVatClaimPeriodOutcome.Blocked)
            throw new InvalidOperationException(post.BlockReason!);

        // ⚠️ ติ๊กออกจากงวดเดิม **หลัง** validate ครบทุกข้อ — ถ้าย้ายก่อนแล้ว
        // §82/3 ไม่ผ่าน ใบจะหลุดจากงวดเดิมไปโดยไม่ได้งวดใหม่ (แม้ transaction
        // rollback ให้ แต่ลำดับนี้ทำให้ถูกต้องโดยไม่ต้องพึ่ง rollback)
        await ExcludeVatReportLinesAsync(claimedLines,
            InputVatClaimPeriodRules.MoveAuditReason(post.Period));

        doc.InputVatBecameClaimableAt = post.Period;
    }

    private async Task<(decimal? Pct, string? Status)> ComputeConversionStatusAsync(Guid companyId, Document source)
    {
        if (source.Lines == null || source.Lines.Count == 0) return (null, null);
        var sourceLineIds = source.Lines.Select(l => l.Id).ToList();
        var totalSourceQty = source.Lines.Sum(l => l.Quantity);
        if (totalSourceQty <= 0) return (null, null);
        var consumed = await _db.DocumentLines
            .Where(l => l.SourceLineId.HasValue && sourceLineIds.Contains(l.SourceLineId.Value))
            .Where(l => !l.Document.IsDeleted
                && l.Document.Status != DocumentStatus.Voided
                && l.Document.Status != DocumentStatus.Rejected)
            .SumAsync(l => (decimal?)l.Quantity) ?? 0;
        var pct = Math.Min(100, Math.Round((consumed / totalSourceQty) * 100, 1, MidpointRounding.AwayFromZero));
        var status = pct switch
        {
            >= 100 => "Full",
            > 0 => "Partial",
            _ => "None",
        };
        return (pct, status);
    }

    public async Task<DocumentResponse> GetDocumentForUserAsync(Guid companyId, Guid documentId, Guid userId)
    {
        var full = await GetDocumentAsync(companyId, documentId);
        if (full.Sensitivity == SensitivityKind.None || _sensitivity == null) return full;
        var allowed = await _sensitivity.CanViewAsync(companyId, userId, full.Sensitivity);
        if (allowed) return full;
        // Fetch only the bare-minimum metadata needed for the stub.
        var stub = await _db.Documents.AsNoTracking()
            .Where(d => d.Id == documentId && d.CompanyId == companyId)
            .Select(d => new { d.Id, d.DocumentNumber, d.DocumentType, d.Status, d.DocumentDate, d.DueDate, d.CreatedAt, d.Sensitivity, d.CreditNoteReason })
            .FirstAsync();
        return new DocumentResponse(stub.Id, stub.DocumentNumber, stub.DocumentType, stub.Status,
            stub.DocumentDate, stub.DueDate,
            new ContactBrief(Guid.Empty, "[ซ่อน]", null),
            0, 0, 0, 0, 0, 0, 0, 0, 0, null, null,
            new List<DocumentLineResponse>(), stub.CreatedAt,
            Sensitivity: stub.Sensitivity,
            IsRedacted: true,
            RedactedReason: SensitivityRedactReason(stub.Sensitivity),
            CreditNoteReason: stub.CreditNoteReason);
    }

    public async Task<List<DocumentPeriod>> GetDocumentPeriodsAsync(Guid companyId, IReadOnlyList<DocumentType>? types = null)
    {
        // global query filter ตัด IsDeleted ให้แล้ว
        var q = _db.Documents.Where(d => d.CompanyId == companyId);
        if (types != null && types.Count > 0)
            q = q.Where(d => types.Contains(d.DocumentType));
        var groups = await q
            .GroupBy(d => new { d.DocumentDate.Year, d.DocumentDate.Month })
            .Select(g => new { g.Key.Year, g.Key.Month, Count = g.Count() })
            .ToListAsync();
        return groups
            .OrderByDescending(g => g.Year).ThenByDescending(g => g.Month)
            .Select(g => new DocumentPeriod(g.Year, g.Month, g.Count))
            .ToList();
    }

    public async Task<PagedResponse<DocumentResponse>> GetDocumentsForUserAsync(Guid companyId, Guid userId, DocumentType? type, PagedRequest request, Guid? projectId = null, Guid? contactId = null, string? status = null, DateTime? fromDate = null, DateTime? toDate = null, Guid? relatedDocumentId = null, Guid? revenueContractId = null, bool staleOnly = false, IReadOnlyList<DocumentType>? types = null)
    {
        var page = await GetDocumentsAsync(companyId, type, request, projectId, contactId, status, fromDate, toDate, relatedDocumentId, revenueContractId, staleOnly, types);
        if (_sensitivity == null) return page;
        var visible = await _sensitivity.GetVisibleKindsAsync(companyId, userId);

        // Replace any item the user can't see with a redacted stub. We keep
        // the row in the list (don't filter out) so paging counts stay stable
        // and integration targets see "row N is hidden" rather than "row N
        // missing" — the latter is impossible to distinguish from a delete.
        var redactedItems = page.Items.Select(it =>
            it.Sensitivity == SensitivityKind.None || visible.Contains(it.Sensitivity)
                ? it
                : new DocumentResponse(it.Id, it.DocumentNumber, it.DocumentType, it.Status,
                    it.DocumentDate, it.DueDate,
                    new ContactBrief(Guid.Empty, "[ซ่อน]", null),
                    0, 0, 0, 0, 0, 0, 0, 0, 0, null, null,
                    new List<DocumentLineResponse>(), it.CreatedAt,
                    Sensitivity: it.Sensitivity,
                    IsRedacted: true,
                    RedactedReason: SensitivityRedactReason(it.Sensitivity),
                    CreditNoteReason: it.CreditNoteReason)
        ).ToList();
        return new PagedResponse<DocumentResponse>(redactedItems, page.TotalCount, page.Page, page.PageSize, page.TotalPages);
    }

    private static string SensitivityRedactReason(SensitivityKind kind) => kind switch
    {
        SensitivityKind.Payroll      => "ต้องมีสิทธิ์ดูข้อมูลเงินเดือน (perm:Payroll.View)",
        SensitivityKind.ExecutivePay => "ต้องมีสิทธิ์ดูข้อมูลค่าตอบแทนผู้บริหาร",
        SensitivityKind.HrPersonal   => "ต้องมีสิทธิ์ดูข้อมูลบุคลากร",
        SensitivityKind.Confidential => "ต้องมีสิทธิ์ดูเอกสารลับ (perm:SensitiveDocs.View)",
        _                            => "ต้องมีสิทธิ์เพิ่มเติม"
    };

    public async Task<PagedResponse<DocumentResponse>> GetDocumentsAsync(Guid companyId, DocumentType? type, PagedRequest request, Guid? projectId = null, Guid? contactId = null, string? status = null, DateTime? fromDate = null, DateTime? toDate = null, Guid? relatedDocumentId = null, Guid? revenueContractId = null, bool staleOnly = false, IReadOnlyList<DocumentType>? types = null)
    {
        var query = _db.Documents
            .Include(d => d.Lines)
            .Include(d => d.Project)
            .Include(d => d.BankAccount)
            .Include(d => d.PaymentAccount)
            .Include(d => d.ExpenseCategory)
            .Where(d => d.CompanyId == companyId);

        if (type.HasValue)
            query = query.Where(d => d.DocumentType == type.Value);
        // กรองหลายประเภทพร้อมกัน (ฝั่งรายรับ/รายจ่าย) — ต้องทำที่ server เพื่อให้
        // pagination ถูกต้อง. เดิม UI ส่ง types[] มาแต่ server อ่านแค่ type เดียว →
        // server แบ่งหน้ารวมทุกประเภท แล้วค่อยกรองฝั่งที่ client → เอกสารฝั่ง
        // รายจ่ายที่เก่ากว่า 20 อันดับแรก (รวมทุกประเภท) หลุดหน้า ไม่ขึ้นเลย.
        else if (types != null && types.Count > 0)
            query = query.Where(d => types.Contains(d.DocumentType));

        if (projectId.HasValue)
            query = query.Where(d => d.ProjectId == projectId.Value
                || d.Lines.Any(l => l.ProjectId == projectId.Value));

        if (contactId.HasValue)
            query = query.Where(d => d.ContactId == contactId.Value);

        if (relatedDocumentId.HasValue)
            query = query.Where(d => d.RelatedDocumentId == relatedDocumentId.Value);

        if (revenueContractId.HasValue)
            query = query.Where(d => d.RevenueContractId == revenueContractId.Value);

        if (!string.IsNullOrEmpty(status) && Enum.TryParse<DocumentStatus>(status, true, out var statusEnum))
            query = query.Where(d => d.Status == statusEnum);

        // Stale = parked in a non-terminal status past the threshold.
        if (staleOnly)
        {
            var staleCutoff = DateTime.UtcNow.Date.AddDays(-StaleThresholdDays);
            query = query.Where(d => d.DocumentDate < staleCutoff
                && d.Status != DocumentStatus.Paid
                && d.Status != DocumentStatus.Voided
                && d.Status != DocumentStatus.Rejected);
        }

        if (fromDate.HasValue)
            query = query.Where(d => d.DocumentDate >= fromDate.Value);

        if (toDate.HasValue)
            query = query.Where(d => d.DocumentDate <= toDate.Value);

        if (!string.IsNullOrEmpty(request.Search))
        {
            var search = $"%{request.Search}%";
            query = query.Where(d => EF.Functions.ILike(d.DocumentNumber, search)
                || (d.Contact != null && EF.Functions.ILike(d.Contact.Name, search)));
        }

        var total = await query.CountAsync();

        // เรียงลำดับ — รองรับกดหัวคอลัมน์ (เลขที่/วันที่/ยอดรวม/สถานะ) + tiebreaker
        // คงที่ (เลขที่ + Id) เพื่อผลลัพธ์ deterministic. เดิม order แค่ DocumentDate
        // → เอกสารวันเดียวกันเรียงมั่ว (ตามลำดับ insert). ไม่ sort ด้วย Contact.Name
        // (required nav + filter !IsDeleted → INNER JOIN ตัดใบที่ contact ถูกลบ).
        IOrderedQueryable<Document> ordered;
        if (string.IsNullOrWhiteSpace(request.SortBy))
        {
            // default: ล่าสุดก่อน + เลขที่มาก→น้อยในวันเดียวกัน
            ordered = query.OrderByDescending(d => d.DocumentDate)
                           .ThenByDescending(d => d.DocumentNumber);
        }
        else
        {
            var desc = request.SortDesc;
            ordered = request.SortBy.Trim().ToLowerInvariant() switch
            {
                "number" or "documentnumber" or "docnumber" =>
                    desc ? query.OrderByDescending(d => d.DocumentNumber) : query.OrderBy(d => d.DocumentNumber),
                "amount" or "total" or "totalamount" =>
                    desc ? query.OrderByDescending(d => d.TotalAmount) : query.OrderBy(d => d.TotalAmount),
                "status" =>
                    desc ? query.OrderByDescending(d => d.Status) : query.OrderBy(d => d.Status),
                "duedate" =>
                    desc ? query.OrderByDescending(d => d.DueDate) : query.OrderBy(d => d.DueDate),
                _ => // "date" หรือค่าที่ไม่รู้จัก → วันที่เอกสาร
                    desc ? query.OrderByDescending(d => d.DocumentDate) : query.OrderBy(d => d.DocumentDate),
            };
            ordered = ordered.ThenByDescending(d => d.DocumentNumber).ThenBy(d => d.Id);
        }

        var items = await ordered
            .Skip((request.Page - 1) * request.PageSize)
            .Take(request.PageSize)
            .ToListAsync();
        await _db.HydrateContactsAsync(companyId, items);  // กัน INNER JOIN ตัดใบที่ contact ถูกลบ

        var etaxByDoc = await GetLatestEtaxAsync(companyId, items.Select(i => i.Id));

        // Batch-flag "ลงโครงการแล้ว" so the list view can show a 🏗️
        // badge without per-row roundtrips. Only top-level counts +
        // amount; the per-line + per-project breakdown is rendered
        // only on detail-view to keep the list payload small.
        var ids = items.Select(i => i.Id).ToList();
        var pceSummary = await _db.ProjectCostEntries
            .Where(c => c.CompanyId == companyId
                && !c.IsDeleted
                && c.DocumentId.HasValue
                && ids.Contains(c.DocumentId!.Value))
            .GroupBy(c => c.DocumentId!.Value)
            .Select(g => new { DocId = g.Key, Count = g.Count(), Amount = g.Sum(c => c.Amount) })
            .ToDictionaryAsync(g => g.DocId, g => (g.Count, g.Amount));

        // ใบกำกับในหน้านี้ที่มี "ใบเสร็จแยก" อ้างอยู่ — batch เดียวต่อหน้า
        // (ไม่ใช่ N+1) เพื่อให้ป้ายประเภทเอกสารบน list ตรงกับหัวที่พิมพ์จริง
        var tivIdsOnPage = items.Where(d => d.DocumentType == DocumentType.TaxInvoice)
            .Select(d => d.Id).ToList();
        var tivWithReceipt = await LoadDocIdsWithSeparateReceiptAsync(_db, companyId, tivIdsOnPage);

        // หัวเอกสารที่จะพิมพ์จริงของทั้งหน้า — resolver ตัวเดียวกับตอนออก PDF
        // (query คงที่ 3 ครั้ง/หน้า ไม่ใช่ N+1) เพื่อให้ป้ายบนตารางตรงกับกระดาษ
        // ทุกเคส รวมชื่อหัวที่ผู้ใช้ตั้งเอง/CustomTitle/§86/6 อย่างย่อ
        var receiptModeForPage = await GetReceiptIssueModeAsync(companyId);
        // วันรับเงินจริงของใบกำกับในหน้านี้ (batch เดียว) — ใบที่รับเงินคนละวัน
        // กับวันที่บนใบ ยกหัวเป็นใบเสร็จไม่ได้ ต้องมี REC แยก (ม.105)
        var settledOnPage = await LoadSettlementDatesAsync(_db, companyId, tivIdsOnPage);
        foreach (var d in items)
            d.ServedAsReceipt = ComputeServedAsReceipt(d, tivWithReceipt.Contains(d.Id), receiptModeForPage,
                settledOnPage.TryGetValue(d.Id, out var paidOn) ? paidOn : null);
        var titles = await PdfGenerationService.ResolveDocumentTitlesAsync(_db, companyId, items);

        return new PagedResponse<DocumentResponse>(
            items.Select(d => {
                var (pceCount, pceAmount) = pceSummary.GetValueOrDefault(d.Id);
                return MapDocumentToResponse(d, etaxByDoc.GetValueOrDefault(d.Id),
                    hasPce: pceCount > 0, pceCount: pceCount, pceAmount: pceAmount,
                    servedAsReceipt: d.ServedAsReceipt) with
                {
                    DocumentTitle = titles.GetValueOrDefault(d.Id),
                };
            }).ToList(),
            total, request.Page, request.PageSize,
            (int)Math.Ceiling(total / (double)request.PageSize));
    }

    /// <summary>
    /// Batch-load the latest e-Tax invoice per document. Picks the highest-status
    /// (Accepted &gt; Submitted &gt; Signed &gt; Generated) so the UI shows the most
    /// "advanced" eTax record that exists. Used to surface the download button on
    /// docs whose XML has been embedded in a PDF/A-3.
    /// </summary>
    private async Task<Dictionary<Guid, (Guid EtaxId, EtaxStatus Status)>> GetLatestEtaxAsync(
        Guid companyId, IEnumerable<Guid> docIds)
    {
        var ids = docIds.Distinct().ToList();
        if (ids.Count == 0) return new();

        var rows = await _db.EtaxInvoices
            .AsNoTracking()
            .Where(e => e.CompanyId == companyId && ids.Contains(e.DocumentId))
            .Select(e => new { e.Id, e.DocumentId, e.Status, e.CreatedAt })
            .ToListAsync();

        return rows
            .GroupBy(r => r.DocumentId)
            .ToDictionary(
                g => g.Key,
                g => g
                    .OrderByDescending(r => (int)r.Status)
                    .ThenByDescending(r => r.CreatedAt)
                    .Select(r => (r.Id, r.Status))
                    .First());
    }

    /// <summary>ใบนี้แปลงมาจากเอกสาร "ขายเครดิต" (ใบแจ้งหนี้/วางบิล) หรือไม่ —
    /// ใช้บล็อกโหมดขายเงินสด (IssuedAsCashReceipt) ที่จะลง Dr เงินสดเต็มทั้งที่
    /// ยังไม่รับเงินจริง</summary>
    private async Task<bool> IsConvertedFromCreditSaleAsync(Guid companyId, Document doc)
    {
        if (!doc.RelatedDocumentId.HasValue) return false;
        var srcType = await _db.Documents.AsNoTracking()
            .Where(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId)
            .Select(d => (DocumentType?)d.DocumentType)
            .FirstOrDefaultAsync();
        return srcType is DocumentType.Invoice or DocumentType.BillingNote;
    }

    public async Task<DocumentResponse> UpdateDocumentAsync(Guid companyId, Guid documentId, UpdateDocumentRequest request)
    {
        var doc = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        // ── Document revision: เอกสาร operational ที่อนุมัติ/ส่งแล้ว "แก้ได้" ──
        // เกณฑ์เดียว: เอกสารที่ **ไม่มี JE / ไม่ขยับสต๊อก / ไม่เข้ารายงานภาษี**
        // แก้หลังอนุมัติได้โดยไม่กระทบบัญชี ตามธรรมเนียมการค้า (เลขที่คงเดิม +
        // Rev เพิ่มทีละ 1) — เอกสารภาษี §86/4 และเอกสารที่ลงบัญชีแล้วยังห้ามแก้
        // ย้อนหลังตามเดิม (ต้องยกเลิก/ออกใบลดหนี้)
        var isDocRevision = RevisableTypes.Contains(doc.DocumentType)
            && doc.Status is DocumentStatus.Approved or DocumentStatus.Sent;

        // Rejected แก้ได้เหมือน Draft — ใบที่ถูกตีกลับยังไม่ posted (ไม่มี JE/เลขจริง)
        // เดิมห้ามแก้ ⇒ ทางตัน: ถูกตีกลับแล้วทำได้แค่ "ส่งใบเดิมซ้ำ" โดยแก้เหตุ
        // ที่โดนตีกลับไม่ได้เลย (พบใน UX audit — ผู้อนุมัติตีกลับก็เพื่อให้แก้)
        if (doc.Status is not (DocumentStatus.Draft or DocumentStatus.Rejected) && !isDocRevision)
            throw new InvalidOperationException(
                RevisableTypes.Contains(doc.DocumentType)
                    ? $"{DocTypeLabel(doc.DocumentType)}สถานะนี้แก้ไขไม่ได้ (แก้ได้เฉพาะ ร่าง/ถูกตีกลับ หรือออก Rev ใหม่จาก Approved/Sent)"
                    : "แก้ไขได้เฉพาะเอกสารร่างหรือใบที่ถูกตีกลับเท่านั้น");

        if (isDocRevision)
        {
            var label = DocTypeLabel(doc.DocumentType);

            // (1) มีเอกสารปลายทางแล้ว = ขั้นถัดไปเดินไปตามเงื่อนไขเดิม — แก้
            //     ย้อนหลังจะทำให้ต้นทางไม่ตรงกับเอกสารจริงที่ออกไปแล้ว
            //     (PO ที่รับของแล้ว / QT ที่แปลงเป็นใบแจ้งหนี้ ฯลฯ)
            var converted = await _db.Documents.AsNoTracking()
                .Where(d => d.CompanyId == companyId && d.RelatedDocumentId == documentId
                    && !d.IsDeleted && d.Status != DocumentStatus.Voided)
                .Select(d => d.DocumentNumber).FirstOrDefaultAsync();
            if (converted != null)
                throw new InvalidOperationException(
                    $"{label}นี้ถูกใช้ออกเอกสาร {converted} แล้ว — แก้ไขย้อนหลังไม่ได้ "
                    + $"(เงื่อนไขใหม่ให้สร้าง{label}ใบใหม่)");

            // (2) มีหลักฐานที่คู่ค้า "ผูกพันกับฉบับเดิม" แล้ว — การแก้ทำให้
            //     หลักฐานนั้นใช้ไม่ได้ ต้องยืนยันรับทราบชัดเจน. ทุกหลักฐานถูก
            //     เก็บลง snapshot ก่อน reset เสมอ (ไม่มีวันหาย)
            //       • ใบเสนอราคา — ลูกค้ากดยอมรับออนไลน์
            //       • ใบส่งของ — ลูกค้าเซ็นรับของออนไลน์ (POD)
            string? bindingEvidence = null;
            if (doc.QuotationAcceptedAt.HasValue)
                bindingEvidence = $"ลูกค้า ({doc.QuotationAcceptedBy}) กดยอมรับแล้วเมื่อ "
                    + $"{doc.QuotationAcceptedAt:dd/MM/yyyy HH:mm}";
            else if (doc.DeliverySignedAt.HasValue)
                bindingEvidence = $"ลูกค้า ({doc.DeliverySignedBy}) เซ็นรับของแล้วเมื่อ "
                    + $"{doc.DeliverySignedAt:dd/MM/yyyy HH:mm}";
            if (bindingEvidence != null && request.AcknowledgeRevisionResetsAcceptance != true)
                throw new InvalidOperationException(
                    $"{bindingEvidence} — การแก้ไขจะทำให้หลักฐานเดิมใช้ไม่ได้ "
                    + "และคู่ค้าต้องยืนยัน Rev ใหม่อีกครั้ง. "
                    + "ยืนยันการแก้ไขโดยส่ง acknowledgeRevisionResetsAcceptance = true "
                    + "(หลักฐานเดิมถูกเก็บไว้ในประวัติ revision)");

            // (3) snapshot สภาพปัจจุบัน "ก่อนแก้" — commit พร้อมการแก้ใน
            //     SaveChanges เดียว (apply ล้มเหลว = ไม่มีอะไรถูกบันทึกเลย)
            _db.DocumentRevisions.Add(new DocumentRevision
            {
                CompanyId = companyId,
                DocumentId = doc.Id,
                RevisionNumber = doc.RevisionNumber,
                TotalAmount = doc.TotalAmount,
                Reason = string.IsNullOrWhiteSpace(request.RevisionReason)
                    ? null : request.RevisionReason.Trim(),
                SnapshotJson = BuildDocumentSnapshot(doc),
            });
            doc.RevisionNumber++;

            // (4) reset หลักฐาน + ลิงก์ของ Rev เก่า — ข้อเสนอ/รายการเปลี่ยนแล้ว
            //     ลิงก์เดิมต้องใช้ต่อไม่ได้ (ขอลิงก์ใหม่ให้คู่ค้ายืนยัน Rev ปัจจุบัน)
            doc.QuotationAcceptedAt = null;
            doc.QuotationAcceptedBy = null;
            doc.QuotationAcceptToken = null;
            doc.QuotationAcceptTokenExpiresAt = null;
            doc.DeliverySignedAt = null;
            doc.DeliverySignedBy = null;
            doc.DeliverySignToken = null;
            doc.DeliverySignTokenExpiresAt = null;
            doc.DeliverySignatureBase64 = null;
        }

        // §86/4: เอกสารที่ "ออกเลขจริงไปแล้ว" ห้ามแก้ย้อนหลัง — ต้องออกใบยกเลิก +
        // ใบใหม่. Draft ปกติถือเลข placeholder "DRAFT-{guid}" แต่ใบที่ถูก restore
        // จาก Voided กลับมาเป็น Draft ทั้งที่ยัง "ถือเลขจริงเดิม" (re-approve คงเลข)
        // → ถ้าไม่กันตรงนี้ ผู้ใช้แก้ยอด/วันที่/คู่ค้า แล้วอนุมัติใหม่ด้วยเลขเดิมได้
        // = แก้ใบกำกับภาษีที่เคยออกไปแล้ว. อนุญาตเฉพาะ field ที่ไม่กระทบเงิน/ภาษี
        // — เอกสาร operational ไม่ใช่เอกสารภาษี §86/4 → เส้นทาง revision ข้าม
        // block นี้ (เลขจริงคงเดิมโดยเจตนา นั่นคือหัวใจของ Rev)
        var isRestoredWithRealNumber = !doc.DocumentNumber.StartsWith("DRAFT-", StringComparison.Ordinal)
            && !isDocRevision
            && !RevisableTypes.Contains(doc.DocumentType);
        if (isRestoredWithRealNumber)
        {
            // ⚠️ ต้องเทียบ "ค่าที่เปลี่ยนจริง" ไม่ใช่ "ส่งฟิลด์มาไหม"
            // ที่มา: ฟอร์มแก้ไขเป็น PUT ก้อนเดียว ส่ง lines/ส่วนลดท้ายบิล/
            // PricesIncludeVat มาทุกครั้งอยู่แล้ว ⇒ เช็ค `.HasValue`/`!= null`
            // เท่ากับบล็อกทุกการกดบันทึก **แม้ไม่ได้แก้อะไรเลย** ⇒ ปุ่ม
            // "บันทึกและอนุมัติ" ล้มที่ขั้น update ก่อนถึง approve ⇒ ใบที่กู้คืน
            // มาอนุมัติไม่ได้เลยสักใบ (ทางตัน: กู้คืนได้แต่ใช้งานต่อไม่ได้)
            // §86/4 ห้าม "แก้ย้อนหลัง" — การส่งค่าเดิมกลับมาไม่ใช่การแก้
            var blocked = new List<string>();
            if (request.DocumentDate.HasValue && request.DocumentDate.Value.Date != doc.DocumentDate.Date)
                blocked.Add("วันที่เอกสาร");
            if (request.ContactId.HasValue && request.ContactId.Value != doc.ContactId) blocked.Add("ผู้ติดต่อ");
            if (request.Lines != null && PrintedLinesChanged(request.Lines, doc.Lines))
                blocked.Add("รายการสินค้า/บริการ");
            if (request.BillDiscountPercent.HasValue
                && request.BillDiscountPercent.Value != doc.BillDiscountPercent) blocked.Add("ส่วนลดท้ายบิล");
            if (request.BillDiscountAmount.HasValue
                && request.BillDiscountAmount.Value != doc.BillDiscountAmount) blocked.Add("ส่วนลดท้ายบิล");
            if (request.PricesIncludeVat.HasValue
                && request.PricesIncludeVat.Value != doc.PricesIncludeVat) blocked.Add("รูปแบบราคารวม VAT");
            if (blocked.Count > 0)
                throw new InvalidOperationException(
                    $"เอกสาร {doc.DocumentNumber} เคยออกเลขจริงแล้ว (กู้คืนจากการยกเลิก) — "
                    + $"ห้ามแก้ {string.Join(", ", blocked.Distinct())} ย้อนหลังตามมาตรา 86/4. "
                    + "หากต้องแก้ยอด/วันที่ ให้ยกเลิกใบนี้ถาวรแล้วออกใบใหม่ (หรือออกใบลดหนี้/เพิ่มหนี้). "
                    + "ถ้าต้องการแค่อนุมัติใบนี้กลับเข้าบัญชี ให้กดอนุมัติโดยไม่แก้ตัวเลขบนใบ");
        }

        if (request.DocumentDate.HasValue) doc.DocumentDate = Accounting.Helpers.ThaiDate.CalendarDateUtc(request.DocumentDate.Value);
        // วันครบกำหนด: DateTime.MinValue = **ล้างทิ้ง** (เดิมล้างไม่ได้เลย —
        // ลบช่องว่างแล้วบันทึก วันเดิมเด้งกลับ ใบยังโผล่ในรายงานค้างชำระ/อีเมล
        // ทวงตามวันเก่า) — sentinel ตามตระกูล convention ล้างค่าของเรพ:
        // string ใช้ "" · Guid ใช้ Guid.Empty · int ใช้ -1 · DateTime ใช้ MinValue
        if (request.DueDate.HasValue)
            doc.DueDate = request.DueDate.Value == DateTime.MinValue
                ? null
                : Accounting.Helpers.ThaiDate.CalendarDateUtc(request.DueDate.Value);
        if (request.ContactId.HasValue) doc.ContactId = request.ContactId.Value;
        if (request.Reference != null) doc.Reference = request.Reference;
        if (request.Notes != null) doc.Notes = request.Notes;
        if (request.CustomAppendix != null) doc.CustomAppendix = request.CustomAppendix;
        if (request.CustomFooterNotes != null) doc.CustomFooterNotes = request.CustomFooterNotes;
        if (request.CustomTermsAndConditions != null) doc.CustomTermsAndConditions = request.CustomTermsAndConditions;
        if (request.RevenueContractId.HasValue) doc.RevenueContractId = request.RevenueContractId.Value;
        if (request.PerformanceObligationId.HasValue) doc.PerformanceObligationId = request.PerformanceObligationId.Value;
        if (request.SupplierInvoiceNumber != null) doc.SupplierInvoiceNumber = request.SupplierInvoiceNumber;
        if (request.SupplierTaxInvoiceDate.HasValue) doc.SupplierTaxInvoiceDate = request.SupplierTaxInvoiceDate.Value;
        await ApplyInputVatClaimPeriodAsync(companyId, doc, request.InputVatClaimPeriod);
        if (request.HasTaxInvoiceReference.HasValue) doc.HasTaxInvoiceReference = request.HasTaxInvoiceReference.Value;
        if (request.SupplierBranchCode != null) doc.SupplierBranchCode = request.SupplierBranchCode;
        if (request.CreditDays.HasValue)
        {
            // -1 = ล้างกลับเป็น "ไม่ระบุ" (ให้ resolver ใช้ค่าตั้งต้นของผู้ขาย
            // ครั้งถัดไป) — convention เดียวกับ UpdateContactAsync ที่
            // PaymentDueDays < 0 → null
            doc.CreditDays = request.CreditDays.Value < 0 ? null : request.CreditDays.Value;
            // ผู้เรียกที่ไม่ส่ง DueDate มาเอง (เช่น API/integration) ต้องได้วัน
            // ครบกำหนดที่สอดคล้องกับเครดิตใหม่ — ไม่งั้นสองช่องขัดกันในฐานข้อมูล
            // (ฟอร์มบนเว็บส่ง DueDate มาด้วยเสมอ จึงไม่ถูกกระทบ)
            if (!request.DueDate.HasValue && doc.CreditDays is >= 0)
                doc.DueDate = doc.DocumentDate.AddDays(doc.CreditDays.Value);
        }
        if (request.PaymentTerms != null) doc.PaymentTerms = request.PaymentTerms;
        // ภาษาเอกสาร — รับเฉพาะ th/en; "" = ล้างกลับไปใช้ค่าตั้งต้นของบริษัท
        if (request.DocumentLanguage != null)
        {
            var dl = request.DocumentLanguage.Trim().ToLowerInvariant();
            doc.DocumentLanguage = dl is "th" or "en" ? dl : null;
        }

        // Tax Point §78 inputs (Draft edit)
        if (request.DeliveryDate.HasValue) doc.DeliveryDate = request.DeliveryDate.Value;
        if (request.OwnershipTransferDate.HasValue) doc.OwnershipTransferDate = request.OwnershipTransferDate.Value;
        if (request.ServiceUsedDate.HasValue) doc.ServiceUsedDate = request.ServiceUsedDate.Value;
        if (request.BookingNumber != null) doc.BookingNumber = string.IsNullOrWhiteSpace(request.BookingNumber) ? null : request.BookingNumber.Trim();
        if (request.InputVatAccountCodeOverride != null) doc.InputVatAccountCodeOverride = string.IsNullOrWhiteSpace(request.InputVatAccountCodeOverride) ? null : request.InputVatAccountCodeOverride.Trim();
        // ล้างเทอมเครดิต/วันครบกำหนดที่ไม่เข้ากับชนิดเอกสาร — สำคัญตอน update
        // เป็นพิเศษ เพราะ semantics "omit = คงค่าเดิม" ทำให้ client ที่ซ่อนช่อง
        // แล้วส่ง null มา **ไม่สามารถ** ล้างค่าเก่าที่เคยหลุดเข้าไปได้เอง
        // (เช่น ใบลดหนี้เก่าที่มี CreditDays=30 ค้างจากยุคฟอร์มเหมารวม)
        NormalizeCreditTermFields(doc);

        // ===== Fields ที่เดิม "เงียบหาย" ตอนแก้ Draft (เคยมีเฉพาะตอน Create) =====
        // CreditNoteReason (§86/10), IsForeignService (ภ.พ.36/ภ.ง.ด.54), และชุดเงินมัดจำ.
        // ทุก field ใช้ HasValue / != null → omit = คงค่าเดิม.
        if (request.CreditNoteReason.HasValue) doc.CreditNoteReason = request.CreditNoteReason.Value;
        if (request.DebitNoteReason.HasValue) doc.DebitNoteReason = request.DebitNoteReason.Value;
        // ฝั่งภาษี CN/DN — แก้ได้ระหว่างยังเป็นร่าง (หลังอนุมัติต้องใช้ "ย้ายฝั่ง"
        // ที่กลับ JE ให้ด้วย ไม่ใช่แก้ field เฉย ๆ ซึ่งจะทำให้ GL กับรายงานไม่ตรงกัน)
        if (request.CnDnPurchaseSideOverride.HasValue
            && doc.DocumentType is DocumentType.CreditNote or DocumentType.DebitNote
            && doc.Status == DocumentStatus.Draft)
            doc.CnDnPurchaseSideOverride = request.CnDnPurchaseSideOverride;
        if (request.IsForeignService.HasValue) doc.IsForeignService = request.IsForeignService.Value;
        if (request.IsDeposit.HasValue) doc.IsDeposit = request.IsDeposit.Value;
        if (request.DepositDeferredAccountCode != null) doc.DepositDeferredAccountCode = string.IsNullOrWhiteSpace(request.DepositDeferredAccountCode) ? null : request.DepositDeferredAccountCode.Trim();
        if (request.DepositOutputVatDeferred.HasValue) doc.DepositOutputVatDeferred = request.DepositOutputVatDeferred.Value;
        if (request.DepositAppliedAmount.HasValue) doc.DepositAppliedAmount = request.DepositAppliedAmount.Value;
        if (request.DepositAppliedRef != null) doc.DepositAppliedRef = string.IsNullOrWhiteSpace(request.DepositAppliedRef) ? null : request.DepositAppliedRef.Trim();
        if (request.DepositAppliedDrivesJournal.HasValue)
        {
            // P0-1 รอบ 193 — ด่านเดียวกับตอนสร้าง (ห้ามให้ทางแก้ไขเลี่ยงด่านได้)
            if (request.DepositAppliedDrivesJournal.Value
                && !Accounting.Helpers.DepositPolicyResolver.DrivesJournalSupported(doc.DocumentType, request.IssuedAsCashReceipt ?? doc.IssuedAsCashReceipt))
                throw new Accounting.Helpers.BusinessRuleException(
                    Accounting.Helpers.DepositPolicyResolver.DrivesUnsupportedMessage, "DEPOSIT-DRIVES-UNSUPPORTED");
            doc.DepositAppliedDrivesJournal = request.DepositAppliedDrivesJournal.Value;
        }
        if (request.BuyerDeclinedTaxInvoice.HasValue) doc.BuyerDeclinedTaxInvoice = request.BuyerDeclinedTaxInvoice.Value;
        // ใบแจ้งหนี้/ใบกำกับภาษี (combined) — ใช้ได้เฉพาะ doc ชนิด TaxInvoice.
        // เดิมชนิดไม่ตรง = ดรอปธงเงียบ ๆ (silent no-op): ผู้ใช้ติ๊กบนใบแจ้งหนี้
        // Draft ตอนแก้ไข → บันทึกสำเร็จแต่ไม่มีอะไรเปลี่ยน. update เปลี่ยนชนิด
        // เอกสารไม่ได้ (เลข/JE ผูกกับชนิด) จึงต้องบอกทางไปต่อแทน
        if (request.CombinedInvoiceTaxInvoice.HasValue)
        {
            if (request.CombinedInvoiceTaxInvoice.Value
                && doc.DocumentType != DocumentType.TaxInvoice)
                throw new Accounting.Helpers.BusinessRuleException(
                    "ติ๊ก \"ใบแจ้งหนี้/ใบกำกับภาษี ใบเดียว\" ตอนแก้ไขไม่ได้ — ใบนี้ถูกสร้างเป็น"
                    + $"ชนิด {doc.DocumentType} แล้ว เปลี่ยนชนิดตอนแก้ไขไม่ได้. ทางแก้: "
                    + "ใช้ปุ่ม \"แปลงเอกสาร\" เป็นใบกำกับภาษี หรือสร้างใหม่โดยเลือกประเภท "
                    + "\"ใบแจ้งหนี้/ใบกำกับภาษี\" ตั้งแต่ต้น");
            doc.CombinedInvoiceTaxInvoice = request.CombinedInvoiceTaxInvoice.Value
                && doc.DocumentType == DocumentType.TaxInvoice;
        }
        // IssuedAsCashReceipt — เดิม update ไม่รับ ⇒ ติ๊ก "ออกใบกำกับภาษี/ใบเสร็จ
        // รับเงิน ใบเดียว (ขายเงินสด)" ตอนแก้ไขแล้วไม่มีผลเงียบ ๆ (silent no-op)
        // โดยเฉพาะเคสแปลง INV→TaxInvoice แล้วมาติ๊กภายหลัง (convert ไม่ตั้ง flag นี้)
        if (request.IssuedAsCashReceipt.HasValue)
            doc.IssuedAsCashReceipt = request.IssuedAsCashReceipt.Value
                && doc.DocumentType == DocumentType.TaxInvoice
                // guard: ใบที่แปลงมาจากใบแจ้งหนี้/วางบิล (ขายเครดิต) ห้ามลงแบบขาย
                // เงินสด — จะได้ Dr เงินสดเต็มทั้งที่ยังไม่รับเงินจริง (เงินสดปลอม
                // + ไม่มีลูกหนี้). ต้องรับเงินผ่าน "บันทึกชำระเงิน" ตามปกติ
                && !await IsConvertedFromCreditSaleAsync(companyId, doc);
        // เจตนา "รับเงินครบแล้ว" (tax_paid) — ใบแปลงเกิดเป็นร่างเสมอ ผู้ใช้เลือก
        // โหมดตอนเปิดแก้ไข จึงต้องรับที่ update; null = ไม่แตะ (กันทับค่าเดิม)
        if (request.PaidOnIssue.HasValue)
            doc.PaidOnIssue = request.PaidOnIssue.Value
                && doc.DocumentType is DocumentType.TaxInvoice or DocumentType.Invoice;
        // ผู้จัดทำจริงจากระบบต้นทาง (เคส OCR PV: NextAcc สร้าง Draft เอง → partner
        // ยัดผู้จัดทำผ่าน PUT). null = ไม่แตะ; "" = ล้าง; ค่า = ตั้ง. PDF slot 0
        // (ผู้จัดทำ/ผู้รับเงิน) จะ priority ค่านี้เหนือ CreatedBy (ResolveSignersAsync)
        if (request.PreparerName != null)
            doc.PreparerName = string.IsNullOrWhiteSpace(request.PreparerName) ? null : request.PreparerName.Trim();
        if (request.PreparerSignatureBase64 != null)
            doc.PreparerSignatureBase64 = string.IsNullOrWhiteSpace(request.PreparerSignatureBase64) ? null : request.PreparerSignatureBase64.Trim();

        // Project re-assignment (only allowed while Draft, which is enforced above)
        if (request.ProjectId.HasValue)
        {
            // Guid.Empty = **ปลดโครงการออก** — เดิมเลือก "— ไม่ระบุโครงการ —"
            // แล้วบันทึก โครงการเดิมยังผูกอยู่ (ต้นทุนโครงการนับใบผิดต่อไป)
            if (request.ProjectId.Value == Guid.Empty)
                doc.ProjectId = null;
            else
            {
                var projectOk = await _db.Projects.AnyAsync(p =>
                    p.Id == request.ProjectId.Value && p.CompanyId == companyId);
                if (!projectOk)
                    throw new InvalidOperationException("ไม่พบโครงการในบริษัทนี้");
                doc.ProjectId = request.ProjectId.Value;
            }
        }
        // DimensionId เป็นเงื่อนไขอิสระ — เดิมซ้อนใน block ProjectId ทำให้แก้
        // dimension โดยไม่ส่ง project = ค่าหายเงียบ
        if (request.DimensionId.HasValue)
            doc.DimensionId = request.DimensionId.Value == Guid.Empty ? null : request.DimensionId.Value;

        // Guid.Empty = ปลดค่า (กติกาเดียวกับ DimensionId/BrandId ข้างบน —
        // ทุก dropdown ที่มี option "— ไม่ระบุ —" ต้องปลดได้จริง ไม่ใช่ silent no-op)
        if (request.BankAccountId.HasValue)
            doc.BankAccountId = request.BankAccountId.Value == Guid.Empty ? null : request.BankAccountId.Value;
        if (request.PaymentAccountId.HasValue)
            doc.PaymentAccountId = request.PaymentAccountId.Value == Guid.Empty ? null : request.PaymentAccountId.Value;
        if (request.ExpenseCategoryId.HasValue)
            doc.ExpenseCategoryId = request.ExpenseCategoryId.Value == Guid.Empty ? null : request.ExpenseCategoryId.Value;

        // CertificateInLieu fields
        if (request.CertificateReason != null) doc.CertificateReason = request.CertificateReason;
        if (request.CertifierName != null) doc.CertifierName = request.CertifierName;
        if (request.CertifierPosition != null) doc.CertifierPosition = request.CertifierPosition;
        if (request.WitnessName != null) doc.WitnessName = request.WitnessName;
        if (request.WitnessPosition != null) doc.WitnessPosition = request.WitnessPosition;
        if (request.PaymentDate.HasValue) doc.PaymentDate = request.PaymentDate.Value;

        // ── รอบ 193 (คำตัดสินเจ้าของข้อ 1/4/8) — ยอดชำระจริง + ผลต่างจากการปัดเศษ ──
        // ยอดชำระจริง: null = ไม่แตะ · 0 = ล้าง (จ่ายเต็มตามยอด) · > 0 = ตั้ง — ตัวตัดสินขา JE คือ Helpers/PaymentSettlementAdjustment
        if (request.ActualPaidAmount is decimal updActualPaid)
        {
            if (updActualPaid < 0m)
                throw new Accounting.Helpers.BusinessRuleException(
                    "ยอดชำระจริงต้องไม่ติดลบ — เว้นว่าง/0 เมื่อจ่ายเต็มตามยอดเอกสาร",
                    Accounting.Helpers.PaymentSettlementAdjustment.RuleCode);
            doc.ActualPaidAmount = updActualPaid == 0m ? null : updActualPaid;
        }
        // ผลต่างปัดเศษ: null = ไม่แตะ (ค่าเดิมยังอยู่) · สัญญา SubTotal = Σ บรรทัด + ค่านี้ (Helpers/DocumentRounding)
        var roundingBefore = doc.RoundingAdjustment;
        if (request.RoundingAdjustment is decimal updRounding)
        {
            if (Accounting.Helpers.DocumentRounding.Validate(updRounding) is string roundErr)
                throw new Accounting.Helpers.BusinessRuleException(roundErr, Accounting.Helpers.DocumentRounding.RuleCode);
            doc.RoundingAdjustment = updRounding;
        }
        if (request.Lines == null && doc.RoundingAdjustment != roundingBefore)
        {
            // ไม่ได้ส่งบรรทัดมา แต่เปลี่ยนผลต่างปัดเศษ ⇒ หัวเอกสารขยับตามส่วนต่าง (บรรทัดเดิมไม่แตะ)
            var roundingDelta = doc.RoundingAdjustment - roundingBefore;
            doc.SubTotal += roundingDelta;
            doc.TotalAmount += roundingDelta;
            if (doc.PaymentType == Models.Enums.PaymentType.Cash) { doc.PaidAmount = doc.TotalAmount; doc.BalanceDue = 0m; }
            else doc.BalanceDue = doc.TotalAmount - doc.PaidAmount;
        }

        if (request.Lines != null)
        {
            // Re-validate on edit — the create path's guards must hold here too
            // (previously an edit could set qty=0 / VatRate=-99 unchecked).
            await ValidateDocumentLinesAsync(companyId, request.Lines);

            _db.DocumentLines.RemoveRange(doc.Lines);

            if (request.PricesIncludeVat.HasValue) doc.PricesIncludeVat = request.PricesIncludeVat.Value;
            // ไม่ส่งมา = คงของเดิม · Guid.Empty = ปลดกลับไปใช้ค่าปกติ · id ที่ส่งมา
            // ต้องเป็นของบริษัทนี้ (กันข้าม tenant — ดู ResolveOwnedBrandIdAsync)
            if (request.BrandId.HasValue)
                doc.BrandId = await ResolveOwnedBrandIdAsync(companyId, request.BrandId);
            if (request.BranchId.HasValue)
                doc.BranchId = await ResolveOwnedBranchIdAsync(companyId, request.BranchId);
            if (request.DocumentTemplateId.HasValue)
                doc.DocumentTemplateId = await ResolveOwnedTemplateIdAsync(companyId, request.DocumentTemplateId);

            decimal subTotal = 0, totalDiscount = 0, totalVat = 0, totalWht = 0;
            var order = 1;

            // resolve AccountCode → AccountId per line ก่อน (รองรับ AI suggestion)
            var updCodeCache = new Dictionary<string, Guid?>(StringComparer.OrdinalIgnoreCase);
            var updResolvedAccountIds = new Dictionary<int, Guid>();
            for (int i = 0; i < request.Lines.Count; i++)
            {
                var l = request.Lines[i];
                if (l.AccountId.HasValue) { updResolvedAccountIds[i] = l.AccountId.Value; continue; }
                if (!string.IsNullOrWhiteSpace(l.AccountCode))
                {
                    var rid = await ResolveAccountCodeAsync(companyId, l.AccountCode, updCodeCache);
                    if (rid.HasValue) updResolvedAccountIds[i] = rid.Value;
                }
            }

            // VAT-claimability enforcement ตามผังบัญชี (เหมือนใน Create)
            var updAccountIds = updResolvedAccountIds.Values.Distinct().ToList();
            var updAccountMeta = updAccountIds.Count == 0
                ? new Dictionary<Guid, ChartOfAccount>()
                : await _db.ChartOfAccounts.AsNoTracking()
                    .Where(a => a.CompanyId == companyId && updAccountIds.Contains(a.Id))
                    .ToDictionaryAsync(a => a.Id);
            var accountFlags = updAccountMeta.ToDictionary(kv => kv.Key, kv => kv.Value.InputVatClaimable);

            var companyVatReg = await Accounting.Helpers.CompanyVatStatus.IsRegisteredAsync(_db, companyId);

            // ส่วนลดท้ายบิล (จากยอดรวม) — เฉลี่ย pro-rata เหมือนตอน create.
            // request ไม่ส่งค่ามา (null) = คงค่าเดิมของเอกสาร
            var updBillPct = request.BillDiscountPercent ?? doc.BillDiscountPercent;
            var updBillAmt = request.BillDiscountAmount
                ?? (request.BillDiscountPercent.HasValue ? 0m : doc.BillDiscountAmount);
            var updBillAlloc = AllocateBillDiscount(request.Lines, doc.PricesIncludeVat, updBillPct, updBillAmt);
            // กระทบยอดเศษสตางค์ต่อกลุ่มอัตรา — เหมือน create path (แก้แล้วต้องไม่เพี้ยนกลับ)
            var updAmts = new LineAmounts[request.Lines.Count];
            for (int i = 0; i < request.Lines.Count; i++)
                updAmts[i] = ComputeLineAmounts(request.Lines[i], doc.PricesIncludeVat, updBillAlloc[i]);
            ReconcileTaxRounding(request.Lines, updAmts, doc.PricesIncludeVat);
            int updLineIdx = -1;
            foreach (var line in request.Lines)
            {
                updLineIdx++;
                var amt = updAmts[updLineIdx];

                subTotal += amt.NetAmount;
                totalDiscount += amt.DiscountAmount;
                totalVat += amt.VatAmount;
                totalWht += amt.WhtAmount;

                var lineAccountId = updResolvedAccountIds.TryGetValue(updLineIdx, out var rid2) ? (Guid?)rid2 : null;
                // ผังรายบรรทัดต้องอยู่ฝั่งเดียวกับเอกสาร (กัน JE Cr รายได้เข้า 5xxxx)
                if (lineAccountId.HasValue && updAccountMeta.TryGetValue(lineAccountId.Value, out var updLineAcct))
                    EnsureLineAccountMatchesDocSide(doc.DocumentType, line.Description, updLineAcct,
                        doc.CnDnPurchaseSideOverride);
                var enforcedClaimable = line.IsVatClaimable;
                string? enforcedReason = line.VatNonClaimableReason;
                if (lineAccountId.HasValue && accountFlags.TryGetValue(lineAccountId.Value, out var acctClaimable) && !acctClaimable)
                {
                    enforcedClaimable = false;
                    enforcedReason ??= "บัญชีนี้ตั้งเป็นภาษีซื้อต้องห้ามในผังบัญชี";
                }
                if (!companyVatReg && amt.VatAmount > 0)
                {
                    enforcedClaimable = false;
                    enforcedReason ??= "บริษัทไม่ได้จดทะเบียน VAT — เคลมภาษีซื้อไม่ได้ (รวมเป็นต้นทุน)";
                }
                // ไม่มี VAT บนบรรทัด = ไม่มีอะไรให้เคลม → บังคับ false เสมอ
                // ตัวเลขไม่เปลี่ยน (ทุกสูตรคูณ/บวกกับ VatAmount ซึ่งเป็น 0 อยู่แล้ว)
                // แต่ **ห้ามเก็บ state ที่เป็นไปไม่ได้ลงฐาน**: แถวที่
                // IsVatClaimable=true แต่ VatAmount=0 ทำให้ UI โชว์ "✓ เคลม VAT"
                // ทั้งที่ไม่มีภาษีให้เคลม (ผู้ใช้เข้าใจผิด) และถ้าวันหนึ่งมีโค้ด
                // ใหม่นับ "จำนวนบรรทัดที่เคลมได้" แทนผลรวมยอด จะได้ตัวเลขผิดทันที
                // เหตุผล = null โดยตั้งใจ — นี่ไม่ใช่ภาษีซื้อต้องห้าม §82/5
                // จึงไม่ควรขึ้นป้ายเตือนสีแดงให้ผู้ใช้ตกใจ
                if (amt.VatAmount <= 0)
                {
                    enforcedClaimable = false;
                    enforcedReason = null;
                }
                _db.DocumentLines.Add(new DocumentLine
                {
                    DocumentId = doc.Id,
                    LineOrder = order++,
                    Description = line.Description,
                    Quantity = line.Quantity,
                    Unit = line.Unit ?? "ชิ้น",
                    UnitPrice = line.UnitPrice,
                    DiscountPercent = line.DiscountPercent,
                    DiscountAmount = amt.DiscountAmount,
                    Amount = amt.NetAmount,
                    VatRate = line.VatRate,
                    VatAmount = amt.VatAmount,
                    WithholdingTaxRate = line.WithholdingTaxRate,
                    WithholdingTaxAmount = amt.WhtAmount,
                    AccountId = lineAccountId,
                    ProjectId = line.ProjectId,
                    ProductCode = string.IsNullOrWhiteSpace(line.ProductCode) ? null : line.ProductCode.Trim(),
                    // Preserve the conversion-traceability link across edits —
                    // the edit form round-trips SourceLineId per line, so a
                    // converted document keeps its fulfilment accounting intact.
                    SourceLineId = line.SourceLineId,
                    IsVatClaimable = enforcedClaimable,
                    IsLandedCost = line.IsLandedCost,
                    VatNonClaimableReason = enforcedClaimable ? null : enforcedReason,
                    GlAccountAiFeedbackId = line.GlAccountAiFeedbackId,
                });
            }

            // รอบ 193: SubTotal = Σ บรรทัด + ผลต่างปัดเศษ (0 = สูตรเดิมทุกประการ)
            doc.SubTotal = subTotal + doc.RoundingAdjustment;
            doc.DiscountAmount = totalDiscount;
            doc.BillDiscountPercent = updBillPct;
            doc.BillDiscountAmount = updBillAlloc.Sum();
            doc.VatAmount = totalVat;
            doc.WithholdingTaxAmount = totalWht;
            doc.TotalAmount = doc.SubTotal + totalVat - totalWht;

            // Preserve / apply the settlement basis on edit. A cash-settled
            // voucher must stay fully paid (BalanceDue = 0, no due date) even
            // after its lines/total change — otherwise editing it would
            // re-introduce a phantom outstanding balance.
            // ROLE SEPARATION (same rules as create): an Expense is the
            // request/accrual side — it can never become "จ่ายทันที"; a
            // standalone PV is the disbursement side — it can never become
            // an unpaid "เครดิต" liability.
            if (request.PaymentType.HasValue)
            {
                if (doc.DocumentType == DocumentType.Expense
                    && request.PaymentType == Models.Enums.PaymentType.Cash)
                    throw new InvalidOperationException(
                        "ใบบันทึกค่าใช้จ่ายคือเอกสารตั้งหนี้/คำขอ (ยังไม่จ่ายเงิน) — " +
                        "การจ่ายให้ทำผ่าน \"ใบสำคัญจ่าย\" หรือบันทึกการชำระเงิน");
                if (doc.DocumentType == DocumentType.PaymentVoucher
                    && !doc.RelatedDocumentId.HasValue
                    && request.PaymentType == Models.Enums.PaymentType.Credit)
                    throw new InvalidOperationException(
                        "ใบสำคัญจ่ายคือเอกสารการจ่ายเงินจริง — หากยังไม่ได้จ่าย " +
                        "กรุณาใช้ \"ใบบันทึกค่าใช้จ่าย\" (ตั้งหนี้) แทน");
                doc.PaymentType = request.PaymentType;
            }
            if (doc.PaymentType == Models.Enums.PaymentType.Cash)
            {
                doc.PaidAmount = doc.TotalAmount;
                doc.BalanceDue = 0m;
                doc.DueDate = null;
            }
            else
            {
                doc.BalanceDue = doc.TotalAmount - doc.PaidAmount;
            }
        }

        // ===== PO revision: ตรวจวงเงินงบประมาณซ้ำก่อนบันทึก =====
        // CheckBudgetCommitmentAsync เดิมรันเฉพาะตอน "อนุมัติ" — ถ้าไม่ตรวจซ้ำ
        // ตรงนี้ ผู้ใช้จะอนุมัติ PO 100,000 (ผ่านงบ) แล้วแก้เป็น 500,000 ผ่าน
        // เส้นทาง Rev เพื่อเลี่ยงการบล็อกได้ (committed คำนวณสดจาก line ของ PO
        // ที่เปิดค้าง → ยอดใหม่มีผลทันทีโดยไม่มีอะไรมาทัก). ตรวจหลัง lines/totals
        // ถูก apply ลง ChangeTracker แล้วแต่ก่อน SaveChanges → เกินงบ = ไม่บันทึก
        if (isDocRevision && doc.DocumentType == DocumentType.PurchaseOrder)
        {
            var poSettings = await _db.CompanySettings.AsNoTracking()
                .FirstOrDefaultAsync(s => s.CompanyId == companyId);
            if (poSettings?.BudgetCommitmentMode is "Warn" or "Block")
            {
                // ใช้ "บรรทัดที่จะถูกบันทึกจริง" จาก ChangeTracker ไม่ใช่ doc.Lines
                // — ตอนแก้รายการ โค้ดทำ RemoveRange(doc.Lines) แล้ว Add ชุดใหม่
                // ผ่าน DbSet ทำให้ navigation อาจคาบเกี่ยวทั้งชุดเก่า(Deleted)และ
                // ชุดใหม่ → รวมยอดเบิ้ล. กรองด้วย EntityState ได้ยอดที่ถูกเสมอ
                var poDoc = new Document
                {
                    Id = doc.Id,
                    CompanyId = doc.CompanyId,
                    DocumentNumber = doc.DocumentNumber,
                    DocumentDate = doc.DocumentDate,
                    Lines = _db.ChangeTracker.Entries<DocumentLine>()
                        .Where(e => e.State != EntityState.Deleted
                            && e.State != EntityState.Detached
                            && e.Entity.DocumentId == doc.Id
                            && !e.Entity.IsDeleted)
                        .Select(e => e.Entity).ToList(),
                };
                var overMsg = await CheckBudgetCommitmentAsync(companyId, poDoc);
                if (overMsg != null)
                {
                    if (poSettings.BudgetCommitmentMode == "Block")
                        throw new InvalidOperationException(
                            overMsg + " — ลดยอดใบสั่งซื้อ หรือขอเพิ่มงบก่อนแก้ไข");
                    _logger.LogWarning("Budget commitment warning on PO revision {DocNo}: {Msg}",
                        doc.DocumentNumber, overMsg);
                }
            }
        }

        await _db.SaveChangesAsync();
        // ปิดลูปการสอน local model — บรรทัดที่มี FeedbackId + AccountId สุดท้าย
        // จะถูกบันทึก choice ทันที (กฎเหล็ก #1: เก็บ feedback ทุกครั้งที่ user
        // ตัดสินใจ — accept หรือ override)
        var savedLines = await _db.DocumentLines.AsNoTracking()
            .Where(l => l.DocumentId == doc.Id).ToListAsync();
        await RecordLineAccountFeedbackAsync(savedLines);
        var updated = await GetDocumentAsync(companyId, documentId);
        await FireWebhookAsync(companyId, "document.updated", updated);
        return updated;
    }

    public async Task<DocumentResponse> CompleteSupplierTaxInvoiceAsync(
        Guid companyId, Guid documentId, CompleteSupplierTaxInvoiceRequest request, string actor)
    {
        var doc = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");
        await _db.HydrateContactAsync(companyId, doc);  // กัน INNER JOIN ตัดใบที่ contact ถูกลบ

        // method นี้สำหรับเอกสาร approved ที่ค้าง 11640 — Draft ใช้ UpdateDocumentAsync
        if (doc.Status == DocumentStatus.Draft)
            throw new InvalidOperationException(
                "เอกสารยังเป็น Draft — แก้ใบกำกับผ่านการแก้ไขปกติ (ยังไม่ได้ลงบัญชี)");
        if (doc.Status == DocumentStatus.Voided)
            throw new InvalidOperationException("เอกสารถูกยกเลิกแล้ว — แก้ไขไม่ได้");

        // §83/6 บริการต่างประเทศ (ภ.พ.36): บล็อกชัด ๆ — เส้นนี้เป็น §86/4 (เติม
        // ใบกำกับผู้ขายไทย → ย้าย 11640→11610). ภ.พ.36 ผู้ขาย ตปท. ไม่มีใบกำกับไทย
        // ต้องเคลมผ่าน "นำส่ง ภ.พ.36 → รับรู้ภาษีซื้อ" ที่หน้านำส่งภาษี (§77/2).
        // ไม่ให้ save metadata ใบกำกับผิดเส้น + ไม่แตะ JE (ตอบคำถาม: ไม่ต้องลง JE
        // กลับ เพราะไม่ยอมให้เกิด action ผิด flow ตั้งแต่แรก)
        if (doc.IsForeignService)
            throw new InvalidOperationException(
                "เอกสารนี้เป็นบริการต่างประเทศ (ภ.พ.36 §83/6) — เคลมภาษีซื้อผ่านหน้า "
                + "\"นำส่งภาษี\": นำส่ง ภ.พ.36 แล้วกด \"รับรู้ภาษีซื้อ\" เมื่อได้ใบเสร็จ "
                + "กรมสรรพากร (ไม่ใช่การเติมใบกำกับ §86/4)");

        // เติม/แก้เฉพาะ field ที่ส่งมา (null = คงค่าเดิม)
        if (request.SupplierInvoiceNumber != null)
            doc.SupplierInvoiceNumber = request.SupplierInvoiceNumber;
        if (request.SupplierTaxInvoiceDate.HasValue)
            doc.SupplierTaxInvoiceDate = request.SupplierTaxInvoiceDate.Value;
        if (request.SupplierBranchCode != null)
            doc.SupplierBranchCode = request.SupplierBranchCode;
        // override: "" = ล้าง (กลับ default 11610/11640); null = ไม่แตะ; ค่าอื่น = pin
        if (request.InputVatAccountCodeOverride != null)
        {
            // ล้าง override บนใบที่ VAT ลงผัง override ไปแล้วตอน approve
            // (PostedAsUndue=false — ไม่มี JE 11640 ให้ reclassify): การล้างเฉย ๆ
            // = ร่องรอยหาย + ภ.พ.30 อาจนับเป็นเคลมได้ทั้งที่ GL ลงต้นทุนไปแล้ว
            // → ต้อง void แล้วออกใหม่เท่านั้น
            if (request.InputVatAccountCodeOverride.Length == 0
                && !string.IsNullOrWhiteSpace(doc.InputVatAccountCodeOverride)
                && !doc.InputVatPostedAsUndue)
                throw new InvalidOperationException(
                    $"เอกสารนี้ลงภาษีซื้อเข้าผัง {doc.InputVatAccountCodeOverride} (override) ตั้งแต่อนุมัติแล้ว — "
                    + "ล้าง override ไม่ได้เพราะไม่มียอดพักใน 11640 ให้ย้าย. หากต้องการเคลม ภ.พ.30 "
                    + "ให้ยกเลิกเอกสารแล้วบันทึกใหม่โดยไม่ตั้ง override");
            doc.InputVatAccountCodeOverride =
                request.InputVatAccountCodeOverride.Length == 0
                    ? null
                    : request.InputVatAccountCodeOverride;
        }

        // ===== ติ๊กเคลมเข้า/ออกหลังอนุมัติ (ดุลพินิจผู้กรอก) =====
        if (request.ClaimInputVat == false)
            await UnclaimInputVatAsync(companyId, doc, actor);
        else if (request.ClaimInputVat == true
                 && !string.IsNullOrWhiteSpace(doc.InputVatAccountCodeOverride)
                 && !doc.InputVatAccountCodeOverride.StartsWith("116"))
            await ReclaimInputVatAsync(companyId, doc, actor);

        // ถ้าข้อมูลครบแล้ว + เดิมค้าง 11640 → gen adjusting JE 11640→11610
        // (รวมเคส ClaimInputVat=true บนใบที่ยังพัก 11640 — เส้นเดิมจัดการให้)
        var reclassified = request.ClaimInputVat == false
            ? false
            : await ReclassifyUndueInputVatAsync(companyId, doc, actor);

        // PV ที่ VAT อยู่ 11610 แล้วแต่ธง "ใช้งานใบกำกับภาษี" ยังปิด (เช่นอนุมัติ
        // โดยไม่ติ๊ก) — ติ๊กเคลม = เปิดธงให้ ภ.พ.30 นับ (ไม่ต้องมี JE เพิ่ม)
        if (request.ClaimInputVat == true
            && doc.DocumentType == DocumentType.PaymentVoucher
            && (string.IsNullOrWhiteSpace(doc.InputVatAccountCodeOverride)
                || doc.InputVatAccountCodeOverride.StartsWith("116")))
            doc.HasTaxInvoiceReference = true;

        // งวดที่เคลม ภ.พ.30 — ตั้งจากหน้าดูเอกสารได้เลย ผ่านตัวตรวจกลางตัว
        // เดียวกับฟอร์ม (รายงานชนะ · งวดยื่นแล้วห้ามย้าย · กรอบ §82/3).
        // ต้องอยู่ **หลัง** ReclassifyUndueInputVatAsync — ใบที่เพิ่งเติมใบกำกับ
        // ครบในคลิกเดียวกันจะพ้นสถานะ "พัก 11640" แล้ว จึงเลือกงวดต่อได้ทันที
        // (ก่อน reclassify ตัวตรวจกลางบล็อกใบพักไว้ตามกติกา undue-ชนะ).
        // ข้ามเมื่อกำลังเลิกเคลม — งวดของใบที่ไม่เคลมไม่มีความหมาย
        if (request.ClaimInputVat != false)
            await ApplyInputVatClaimPeriodAsync(companyId, doc, request.InputVatClaimPeriod);

        await _db.SaveChangesAsync();
        var updated = await GetDocumentAsync(companyId, documentId);
        await FireWebhookAsync(companyId,
            reclassified ? "document.input_vat_reclassified" : "document.updated", updated);
        return updated;
    }

    /// <summary>ผังปลายทางของ "ภาษีซื้อที่ไม่เคลม" — หลักภาษี/บัญชี: VAT ที่เคลม
    /// ไม่ได้ **เป็นต้นทุนของรายการนั้น** (ตามก้อนเงิน) ไม่ใช่ค่าใช้จ่ายลอย ๆ.
    /// ลำดับ: (1) บัญชีของบรรทัดที่มี VAT (บรรทัด VAT มากสุดชนะเมื่อหลายบัญชี;
    /// รับทั้ง Expense และ Asset — VAT บนสินค้า/ทรัพย์สิน capitalize เข้าต้นทุน)
    /// (2) ผังชื่อ "ภาษีซื้อ/ขอคืนไม่ได้" (3) null ให้ caller ตัดสิน.
    /// ⚠️ เดิม fallback = "บัญชี 53xx ตัวแรกที่เจอ" ⇒ VAT ไปโผล่ 53120
    /// "ค่าโฆษณาและส่งเสริมการขาย" ทั้งที่ก้อนเงินคือ 54123 สวัสดิการพนักงาน
    /// (บั๊กคลาสเดียวกับ 21510-WHT: หยิบบัญชีจากเลขนำหน้าโดยไม่ดูความหมาย)</summary>
    private async Task<ChartOfAccount?> ResolveNonClaimableVatExpenseAccountAsync(
        Guid companyId, Document doc)
    {
        // (1) ตามก้อนเงิน — บัญชีของบรรทัดที่ VAT เกาะอยู่
        var dominant = (doc.Lines ?? new List<DocumentLine>())
            .Where(l => l.VatAmount > 0)
            .GroupBy(l => l.AccountId ?? doc.ExpenseCategoryId)
            .Where(g => g.Key.HasValue)
            .OrderByDescending(g => g.Sum(l => l.VatAmount))
            .FirstOrDefault();
        if (dominant?.Key is Guid accId)
        {
            var acc = await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
                a.Id == accId && a.CompanyId == companyId && a.IsActive && !a.IsDeleted
                && (a.AccountType == AccountType.Expense || a.AccountType == AccountType.Asset));
            if (acc != null) return acc;
        }
        // (2) ผังเฉพาะ "ภาษีซื้อขอคืนไม่ได้" ถ้าบริษัทตั้งไว้
        return await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
            a.CompanyId == companyId && a.IsActive && !a.IsDeleted && a.Level >= 4
            && a.AccountCode.StartsWith("5")
            && (a.AccountName.Contains("ภาษีซื้อ") || a.AccountName.Contains("ขอคืนไม่ได้")));
    }

    /// <summary>ติ๊ก "ไม่เคลม" ภาษีซื้อหลังอนุมัติ — ย้าย VAT จากที่พัก/เคลมอยู่
    /// (11640 หรือ 11610) เข้า "ต้นทุนของก้อนเงินเดิม" (ResolveNonClaimableVat
    /// ExpenseAccountAsync) + ตั้ง InputVatAccountCodeOverride เป็นผังนั้น
    /// (marker เดียวที่ ภ.พ.30/blockers รู้จักอยู่แล้ว → ใบหลุดจากรายงานถูกต้อง;
    /// ReclaimInputVatAsync กลับรายการจากผังเดียวกัน = สมมาตร). PV ปิดธง
    /// HasTaxInvoiceReference ด้วย. Idempotent — ไม่เคลมอยู่แล้ว = no-op.</summary>
    private async Task UnclaimInputVatAsync(Guid companyId, Document doc, string actor)
    {
        if (doc.VatAmount <= 0) return;
        if (doc.IsForeignService)
            throw new InvalidOperationException(
                "บริการต่างประเทศ (ภ.พ.36 §83/6) — จัดการการเคลมที่หน้านำส่งภาษีเท่านั้น");
        // ไม่เคลมอยู่แล้ว (override นอก 116) → no-op
        if (!string.IsNullOrWhiteSpace(doc.InputVatAccountCodeOverride)
            && !doc.InputVatAccountCodeOverride.StartsWith("116")) return;

        // ห้ามถอนเคลมจากงวดที่ "ยื่นแล้ว" — ต้องยื่น ภ.พ.30 เพิ่มเติมของงวดนั้น
        var filedIn = await _db.TaxReportLines.AsNoTracking()
            .Where(l => l.DocumentId == doc.Id && !l.IsExcluded
                && l.TaxReport.CompanyId == companyId
                && l.TaxReport.TaxType == TaxType.VAT
                // ★ รอบ 183 — "ยื่นแล้ว" รวม `Submitted` (ผู้ใช้ประกาศว่ายื่น ยังไม่มีเลขรับ)
                // ด้วย: ถอนการเคลมออกจากงวดที่ประกาศไปแล้วทำให้ยอดบนแบบที่ยื่นกับ GL
                // ไม่ตรงกันเหมือนกัน — ตัวตัดสินตัวเดียวคือ `TaxFilingLockPolicy`
                && Accounting.Helpers.TaxFilingLockPolicy.DeclaredOrFiledStatuses.Contains(l.TaxReport.Status))
            .Select(l => new { l.TaxReport.Year, l.TaxReport.Month })
            .FirstOrDefaultAsync();
        if (filedIn != null)
            throw new InvalidOperationException(
                $"ภาษีซื้อใบนี้ถูกเคลมในงวด {filedIn.Month:D2}/{filedIn.Year} ที่ยื่นแล้ว — เลิกเคลมในระบบ"
                + "ไม่ได้ ต้องยื่น ภ.พ.30 เพิ่มเติมของงวดนั้นกับสรรพากรก่อน");

        var vatMove = doc.Lines?.Where(l => l.IsVatClaimable).Sum(l => l.VatAmount) ?? 0m;
        if (vatMove <= 0) vatMove = doc.VatAmount;

        // ปลายทาง = ต้นทุนของก้อนเงินเดิม (บัญชีบรรทัดที่ VAT เกาะ) — ห้าม
        // เดาจากเลขนำหน้า (เคยได้ 53120 ค่าโฆษณา ทั้งที่ก้อนเงินคือสวัสดิการพนักงาน)
        var expenseAcc = await ResolveNonClaimableVatExpenseAccountAsync(companyId, doc)
            ?? throw new InvalidOperationException(
                "ไม่พบผังปลายทางสำหรับภาษีซื้อที่ไม่เคลม — กำหนดผังบัญชีให้บรรทัด"
                + "ค่าใช้จ่ายของเอกสารก่อน (VAT ที่ไม่เคลมจะบวกเข้าต้นทุนบัญชีเดียวกับก้อนเงิน)");

        // VAT อยู่ที่ไหนตอนนี้: พัก 11640 (undue ยังไม่ reclass) หรือ 11610 (เคลมได้)
        var pendingUndue = doc.InputVatPostedAsUndue && doc.InputVatBecameClaimableAt == null;
        var srcAcc = pendingUndue
            ? (await FindAccountAsync(companyId, "11640") ?? await FindAccountAsync(companyId, "11630"))
            : (await FindAccountAsync(companyId, "11610") ?? await FindAccountAsync(companyId, "116"));
        if (srcAcc == null)
            throw new InvalidOperationException("ไม่พบผังภาษีซื้อ (11610/11640) ในผังบัญชี");

        var now = DateTime.UtcNow;
        var entryNumber = await GetNextJournalEntryNumberAsync(companyId, "JV");
        var period = await RequireOpenFiscalPeriodAsync(companyId, now, "รายการล้างภาษีซื้อ");
        var je = new JournalEntry
        {
            CompanyId = companyId, EntryNumber = entryNumber, EntryDate = now,
            JournalType = JournalType.General,
            Description = $"เลิกเคลมภาษีซื้อ (ดุลพินิจผู้บันทึก) - {doc.DocumentNumber}",
            Reference = doc.DocumentNumber, Status = JournalEntryStatus.Posted,
            TotalDebit = vatMove, TotalCredit = vatMove,
            CreatedBy = actor, IsAutoGenerated = true, SourceDocumentId = doc.Id,
            FiscalPeriodId = period?.Id, ProjectId = doc.ProjectId,
        };
        _db.JournalEntries.Add(je);
        _db.JournalEntryLines.Add(new JournalEntryLine
        {
            JournalEntryId = je.Id, AccountId = expenseAcc.Id,
            DebitAmount = vatMove, CreditAmount = 0,
            Description = "ภาษีซื้อขอคืนไม่ได้ (เลือกไม่เคลม)", LineOrder = 1,
        });
        _db.JournalEntryLines.Add(new JournalEntryLine
        {
            JournalEntryId = je.Id, AccountId = srcAcc.Id,
            DebitAmount = 0, CreditAmount = vatMove,
            Description = pendingUndue ? "ล้างภาษีซื้อยังไม่ถึงกำหนด" : "กลับภาษีซื้อ ภ.พ.30", LineOrder = 2,
        });

        doc.InputVatAccountCodeOverride = expenseAcc.AccountCode;   // marker "ไม่เคลม"
        if (doc.DocumentType == DocumentType.PaymentVoucher)
            doc.HasTaxInvoiceReference = false;

        // บรรทัดในรายงานงวด Draft ที่ยัง active → ติ๊กออก + recalc (เหมือนตอน void)
        var draftLines = await _db.TaxReportLines
            .Include(l => l.TaxReport)
            .Where(l => l.DocumentId == doc.Id && !l.IsExcluded
                && l.TaxReport.CompanyId == companyId
                && l.TaxReport.TaxType == TaxType.VAT
                // ★ รอบ 183 — ติ๊กบรรทัดออกได้เฉพาะรายงานที่ยัง**เป็นร่างจริง ๆ**
                && !Accounting.Helpers.TaxFilingLockPolicy.DeclaredOrFiledStatuses.Contains(l.TaxReport.Status))
            .ToListAsync();
        await ExcludeVatReportLinesAsync(draftLines, "ผู้ใช้เลิกเคลม");
    }

    /// <summary>ติ๊กบรรทัดออกจากรายงาน ภ.พ.30 + recalc ยอดหัวรายงาน — กลไก
    /// เดียวกับที่หน้ารายงานทำเมื่อนักบัญชีติ๊กออกเอง (<c>IsExcluded=true</c>
    /// เก็บบรรทัดไว้เป็น audit ไม่ลบ) และใช้สูตรรวมยอดตัวเดียวกัน
    /// (<c>TaxService.RecalcVatTotals</c>) จึงไม่มีวัน drift จากหน้ารายงาน
    ///
    /// <para>⚠️ ถ้าติ๊กออกแล้วไม่ recalc หัวรายงานจะค้างยอดเดิม = ยอดบนจอ/ไฟล์
    /// ยื่นไม่ตรงกับบรรทัดที่เหลือ. รวมมาไว้ที่เดียวเพราะมีผู้เรียก 2 ทางแล้ว
    /// (เลิกเคลม · ย้ายงวดเคลม) และทั้งคู่ต้องทำครบทั้งสองขั้นเสมอ</para>
    ///
    /// <param name="reason">เหตุผลสั้น ๆ ต่อหน้า Description เป็นร่องรอยว่า
    /// บรรทัดหลุดจากงวดนี้เพราะอะไร (นักบัญชีเปิดรายงานเก่าแล้วเห็นได้ทันที)</param>
    /// </summary>
    private async Task ExcludeVatReportLinesAsync(List<TaxReportLine> lines, string reason)
    {
        if (lines.Count == 0) return;
        foreach (var l in lines)
        {
            l.IsExcluded = true;
            l.Description = $"⚠️ [{reason}] " + (l.Description ?? "");
            l.UpdatedAt = DateTime.UtcNow;
        }
        foreach (var rid in lines.Select(l => l.TaxReportId).Distinct())
        {
            var rep = await _db.TaxReports.Include(r => r.Lines).FirstOrDefaultAsync(r => r.Id == rid);
            if (rep != null) { TaxService.RecalcVatTotals(rep); rep.UpdatedAt = DateTime.UtcNow; }
        }
    }

    /// <summary>ติ๊ก "กลับมาเคลม" หลังเคยเลิกเคลม (override เป็นผังค่าใช้จ่าย) —
    /// ต้องครบ §86/4 + อยู่ในกรอบ 6 เดือน §82/3. JE ย้อน: Dr 11610 / Cr ผัง
    /// ค่าใช้จ่ายเดิม แล้วล้าง override + เปิดธง PV + stamp BecameClaimableAt
    /// (ภ.พ.30 นับงวดปัจจุบัน — งวดเดิมอาจยื่นไปแล้ว).</summary>
    private async Task ReclaimInputVatAsync(Guid companyId, Document doc, string actor)
    {
        if (doc.VatAmount <= 0) return;
        if (doc.IsForeignService)
            throw new InvalidOperationException(
                "บริการต่างประเทศ (ภ.พ.36 §83/6) — จัดการการเคลมที่หน้านำส่งภาษีเท่านั้น");
        var overrideCode = doc.InputVatAccountCodeOverride!;
        // §82/3 กรอบ 6 เดือน
        var baseDate = doc.SupplierTaxInvoiceDate ?? doc.DocumentDate;
        var windowEnd = new DateTime(baseDate.Year, baseDate.Month, 1).AddMonths(7).AddDays(-1);
        if (DateTime.UtcNow.AddHours(7).Date > windowEnd)
            throw new InvalidOperationException(
                $"ใบกำกับลงวันที่ {baseDate:dd/MM/yyyy} พ้นกรอบ 6 เดือน §82/3 แล้ว — กลับมาเคลมไม่ได้");
        // §86/4 ต้องครบ
        if (doc.Contact == null)
            doc.Contact = await _db.Contacts.FirstOrDefaultAsync(c =>
                c.Id == doc.ContactId && c.CompanyId == companyId) ?? doc.Contact!;
        var completeness = TaxInvoiceCompletenessChecker.Evaluate(doc, doc.Contact);
        if (!completeness.IsClaimable)
            throw new InvalidOperationException(
                $"กลับมาเคลมไม่ได้ — ใบกำกับยังไม่ครบ §86/4: {completeness.MissingSummary}");

        var prevExpenseAcc = await FindAccountAsync(companyId, overrideCode)
            ?? throw new InvalidOperationException($"ไม่พบผัง {overrideCode} ที่เคยพักภาษีซื้อไว้");
        var claimAcc = await FindAccountAsync(companyId, "11610")
            ?? await FindAccountAsync(companyId, "116")
            ?? throw new InvalidOperationException("ไม่พบผังภาษีซื้อ (11610) ในผังบัญชี");

        var vatMove = doc.Lines?.Where(l => l.IsVatClaimable).Sum(l => l.VatAmount) ?? 0m;
        if (vatMove <= 0) vatMove = doc.VatAmount;

        var now = DateTime.UtcNow;
        var entryNumber = await GetNextJournalEntryNumberAsync(companyId, "JV");
        var period = await RequireOpenFiscalPeriodAsync(companyId, now, "รายการคืนภาษีซื้อ");
        var je = new JournalEntry
        {
            CompanyId = companyId, EntryNumber = entryNumber, EntryDate = now,
            JournalType = JournalType.General,
            Description = $"กลับมาเคลมภาษีซื้อ - {doc.DocumentNumber}",
            Reference = doc.DocumentNumber, Status = JournalEntryStatus.Posted,
            TotalDebit = vatMove, TotalCredit = vatMove,
            CreatedBy = actor, IsAutoGenerated = true, SourceDocumentId = doc.Id,
            FiscalPeriodId = period?.Id, ProjectId = doc.ProjectId,
        };
        _db.JournalEntries.Add(je);
        _db.JournalEntryLines.Add(new JournalEntryLine
        {
            JournalEntryId = je.Id, AccountId = claimAcc.Id,
            DebitAmount = vatMove, CreditAmount = 0,
            Description = "ภาษีซื้อ ภ.พ.30 (กลับมาเคลม)", LineOrder = 1,
        });
        _db.JournalEntryLines.Add(new JournalEntryLine
        {
            JournalEntryId = je.Id, AccountId = prevExpenseAcc.Id,
            DebitAmount = 0, CreditAmount = vatMove,
            Description = "กลับรายการภาษีซื้อขอคืนไม่ได้", LineOrder = 2,
        });

        doc.InputVatAccountCodeOverride = null;
        // งวด ภ.พ.30 = เดือนที่กลับมาเคลม (งวดใบเดิมอาจยื่นแล้ว) — ใช้กลไก
        // BecameClaimableAt เดิม: query หลักดึงใบเข้างวดนี้ให้เอง
        doc.InputVatPostedAsUndue = true;
        doc.InputVatBecameClaimableAt = now;
        if (doc.DocumentType == DocumentType.PaymentVoucher)
            doc.HasTaxInvoiceReference = true;
    }

    /// <summary>หาผัง "หนี้สินมัดจำ" ที่ใบมัดจำนี้ Cr ไว้จริง (215/217 ยอด Cr สูงสุด
    /// จาก JE จริง) — ใช้แทนการเดา DepositDeferredAccountCode ?? "21712" ที่ Dr ผิด
    /// ผังเมื่อมัดจำลง 21510/21610 (native หรือ integration) → ผังเดิมค้าง Cr ถาวร +
    /// 21712 ติดลบ. null = ใบไม่มีขา 215/217 (ให้ caller fallback field/217).</summary>
    /// <summary>ชนิดเอกสารที่แก้ไขหลังอนุมัติได้แบบออก Rev ใหม่ — เกณฑ์เดียว:
    /// **ไม่มี JE (AutoPostToJournalAsync ข้าม) + ไม่ขยับสต๊อก + ไม่เข้ารายงาน
    /// ภาษี**. เอกสารเหล่านี้เป็นข้อตกลง/เอกสารดำเนินงาน การแก้จึงไม่ทำให้
    /// GL/ภาษีเพี้ยน. เพิ่มชนิดใหม่ที่นี่ต้องตรวจ 3 เงื่อนไขข้างต้นให้ครบก่อน.</summary>
    internal static readonly HashSet<DocumentType> RevisableTypes = new()
    {
        DocumentType.Quotation,            // ใบเสนอราคา — ต่อรองราคา
        DocumentType.PurchaseOrder,        // ใบสั่งซื้อ — vendor แก้ราคา/ของขาด
        DocumentType.PurchaseRequisition,  // ใบขอซื้อ — ผู้อนุมัติสั่งลดจำนวน
        DocumentType.BillingNote,          // ใบวางบิล — ลูกค้าทักว่ามีใบไม่ใช่ของตน
        DocumentType.DeliveryNote,         // ใบส่งของ — แก้รายการ/จำนวนก่อนส่งจริง
    };

    private static string DocTypeLabel(DocumentType t) => t switch
    {
        DocumentType.Quotation => "ใบเสนอราคา",
        DocumentType.PurchaseOrder => "ใบสั่งซื้อ",
        DocumentType.PurchaseRequisition => "ใบขอซื้อ",
        DocumentType.BillingNote => "ใบวางบิล",
        DocumentType.DeliveryNote => "ใบส่งของ",
        _ => "เอกสาร",
    };

    /// <summary>snapshot สภาพเอกสารทั้งใบเป็น JSON โครงคงที่ — เก็บลง
    /// DocumentRevisions ก่อน apply การแก้ทุกครั้ง. รวมหลักฐานที่ผูกพันกับฉบับ
    /// เดิม (ยอมรับออนไลน์ / เซ็นรับของ) เพราะกำลังจะถูก reset — หลักฐานทาง
    /// การค้าห้ามหาย.</summary>
    internal static string BuildDocumentSnapshot(Document doc)
        => System.Text.Json.JsonSerializer.Serialize(new
        {
            documentNumber = doc.DocumentNumber,
            revisionNumber = doc.RevisionNumber,
            documentDate = doc.DocumentDate,
            dueDate = doc.DueDate,
            contactId = doc.ContactId,
            contactName = doc.Contact?.Name,
            reference = doc.Reference,
            notes = doc.Notes,
            customTermsAndConditions = doc.CustomTermsAndConditions,
            customFooterNotes = doc.CustomFooterNotes,
            pricesIncludeVat = doc.PricesIncludeVat,
            subTotal = doc.SubTotal,
            discountAmount = doc.DiscountAmount,
            billDiscountPercent = doc.BillDiscountPercent,
            billDiscountAmount = doc.BillDiscountAmount,
            vatAmount = doc.VatAmount,
            withholdingTaxAmount = doc.WithholdingTaxAmount,
            totalAmount = doc.TotalAmount,
            currency = doc.Currency,
            documentType = doc.DocumentType.ToString(),
            // หลักฐานที่ผูกพันกับ revision นี้ (กำลังถูก reset — เก็บไว้ที่นี่)
            acceptedAt = doc.QuotationAcceptedAt,
            acceptedBy = doc.QuotationAcceptedBy,
            deliverySignedAt = doc.DeliverySignedAt,
            deliverySignedBy = doc.DeliverySignedBy,
            lines = doc.Lines.Where(l => !l.IsDeleted).OrderBy(l => l.LineOrder).Select(l => new
            {
                l.LineOrder, l.ProductCode, l.Description, l.Quantity, l.Unit,
                l.UnitPrice, l.DiscountPercent, l.DiscountAmount, l.Amount,
                l.VatRate, l.VatAmount,
                whtRate = l.WithholdingTaxRate,
            }),
        });

    /// <summary>ประวัติ revision ของใบเสนอราคา (ใหม่→เก่า). RevisedBy/At ของแถว
    /// snapshot = ใครแก้และเมื่อไร (คนที่สร้าง Rev ถัดไป).</summary>
    /// <summary>
    /// สายการแปลงทั้งเส้นของเอกสาร — ต้นน้ำถึงปลายน้ำ เรียงพร้อมความลึก
    ///
    /// วิธีเดิน:
    ///   1. ขึ้น: ตาม RelatedDocumentId จนสุด (จำกัด 15 ชั้น + กัน cycle —
    ///      ข้อมูลที่ import มาอาจชี้วนกันได้ ห้าม loop ตาย)
    ///   2. ลง: BFS หาใบที่ RelatedDocumentId ชี้มาหาใบในสาย (จำกัดรวม 60 ใบ —
    ///      ใบวางบิลใบเดียวแตกเป็น settlement ได้หลายสิบใบ ต้องมีเพดาน)
    ///
    /// ใบ Voided ยังอยู่ในสาย — ผู้ใช้ต้องเห็นว่าเคยแปลงไปแล้วถูกยกเลิก
    /// ไม่ใช่หายไปเฉย ๆ (UI แสดงขีดฆ่า)
    /// </summary>
    public async Task<List<DocumentChainNode>> GetDocumentChainAsync(Guid companyId, Guid documentId)
    {
        // ── ขึ้นหาราก ──
        var current = await _db.Documents.AsNoTracking()
            .Where(d => d.CompanyId == companyId && d.Id == documentId)
            .Select(d => new { d.Id, d.RelatedDocumentId })
            .FirstOrDefaultAsync();
        if (current == null) return new List<DocumentChainNode>();

        var visited = new HashSet<Guid> { current.Id };
        var rootId = current.Id;
        var parentId = current.RelatedDocumentId;
        for (var hop = 0; parentId.HasValue && hop < 15; hop++)
        {
            if (!visited.Add(parentId.Value)) break;   // cycle — หยุดตรงนี้
            var parent = await _db.Documents.AsNoTracking()
                .Where(d => d.CompanyId == companyId && d.Id == parentId.Value)
                .Select(d => new { d.Id, d.RelatedDocumentId })
                .FirstOrDefaultAsync();
            if (parent == null) break;                  // FK ชี้ไปใบที่ถูกลบ
            rootId = parent.Id;
            parentId = parent.RelatedDocumentId;
        }

        // ── ลงจากราก (BFS ทีละชั้น — query ต่อชั้น ไม่ใช่ต่อใบ) ──
        var nodes = new List<DocumentChainNode>();
        var frontier = new List<Guid> { rootId };
        var seen = new HashSet<Guid> { rootId };
        var parentOf = new Dictionary<Guid, Guid?> { [rootId] = null };
        var depthOf = new Dictionary<Guid, int> { [rootId] = 0 };

        for (var depth = 0; frontier.Count > 0 && depth < 10 && seen.Count < 60; depth++)
        {
            var layer = frontier;
            frontier = new List<Guid>();
            var children = await _db.Documents.AsNoTracking()
                .Where(d => d.CompanyId == companyId && !d.IsDeleted
                    && d.RelatedDocumentId.HasValue && layer.Contains(d.RelatedDocumentId.Value))
                .Select(d => new { d.Id, ParentId = d.RelatedDocumentId!.Value })
                .ToListAsync();
            foreach (var c in children)
            {
                if (!seen.Add(c.Id)) continue;
                parentOf[c.Id] = c.ParentId;
                depthOf[c.Id] = depthOf[c.ParentId] + 1;
                frontier.Add(c.Id);
            }
        }

        var ids = seen.ToList();
        var docs = await _db.Documents.AsNoTracking()
            .Where(d => d.CompanyId == companyId && ids.Contains(d.Id))
            .Select(d => new
            {
                d.Id, d.DocumentNumber, d.DocumentType, d.Status,
                d.DocumentDate, d.TotalAmount, d.PaidAmount,
            })
            .ToListAsync();

        foreach (var d in docs)
            nodes.Add(new DocumentChainNode(
                d.Id, d.DocumentNumber, d.DocumentType, d.Status,
                d.DocumentDate, d.TotalAmount, d.PaidAmount,
                depthOf.GetValueOrDefault(d.Id),
                parentOf.GetValueOrDefault(d.Id),
                d.Id == documentId));

        // เรียง: ตามลึกก่อน แล้ววันที่/เลขที่ — อ่านเป็นเส้นเวลาได้ทันที
        return nodes.OrderBy(n => n.Depth).ThenBy(n => n.DocumentDate)
            .ThenBy(n => n.DocumentNumber, StringComparer.Ordinal).ToList();
    }

    public async Task<List<DocumentRevisionListItem>> GetDocumentRevisionsAsync(Guid companyId, Guid documentId)
    {
        var rows = await _db.DocumentRevisions.AsNoTracking()
            .Where(r => r.CompanyId == companyId && r.DocumentId == documentId && !r.IsDeleted)
            .OrderByDescending(r => r.RevisionNumber)
            .Select(r => new { r.RevisionNumber, r.TotalAmount, r.Reason, r.CreatedBy, r.CreatedAt, r.SnapshotJson })
            .ToListAsync();
        return rows.Select(r => new DocumentRevisionListItem(
            r.RevisionNumber, r.TotalAmount, r.Reason, r.CreatedBy, r.CreatedAt,
            // WasAccepted อ่านจาก snapshot — ไม่ต้อง parse ทั้งก้อน แค่เช็ค key.
            // นับทั้งการยอมรับใบเสนอราคาและการเซ็นรับของ (POD) เพราะทั้งคู่คือ
            // "คู่ค้าผูกพันกับ revision นั้นแล้ว" ซึ่งเป็นสิ่งที่ UI ต้องเตือน
            WasAccepted: r.SnapshotJson.Contains("\"acceptedAt\":\"", StringComparison.Ordinal)
                || r.SnapshotJson.Contains("\"deliverySignedAt\":\"", StringComparison.Ordinal)
        )).ToList();
    }

    /// <summary>snapshot เต็มของ revision หนึ่ง (JSON) — ให้ UI เปิดดูว่า Rev นั้น
    /// เสนออะไรไป. null = ไม่พบ.</summary>
    public async Task<string?> GetDocumentRevisionSnapshotAsync(Guid companyId, Guid documentId, int revisionNumber)
        => await _db.DocumentRevisions.AsNoTracking()
            .Where(r => r.CompanyId == companyId && r.DocumentId == documentId
                && r.RevisionNumber == revisionNumber && !r.IsDeleted)
            .Select(r => r.SnapshotJson)
            .FirstOrDefaultAsync();

    /// <summary>รับรู้ภาษีขายรอเรียกเก็บของใบมัดจำ (21913 → 21911) โดยไม่แตะรายได้
    /// — ดู doc ที่ IDocumentService. GL-critical: JE สมดุลเสมอ (Dr 21913 / Cr 21911)
    /// idempotent ผ่าน DepositOutputVatRecognizedAt (เรียกซ้ำ = ปฏิเสธ).</summary>
    public async Task<DocumentResponse> RecognizeDepositOutputVatAsync(
        Guid companyId, Guid depositId, DateTime? recognizeDate, string actor)
    {
        var strategy = _db.Database.CreateExecutionStrategy();
        return await strategy.ExecuteAsync(async () =>
        {
            await using var tx = await _db.Database.BeginTransactionAsync();
            try
            {
                var doc = await _db.Documents.FirstOrDefaultAsync(
                    d => d.Id == depositId && d.CompanyId == companyId && !d.IsDeleted)
                    ?? throw new KeyNotFoundException("ไม่พบเอกสารมัดจำ");
                await _db.HydrateContactAsync(companyId, doc);

                if (!doc.IsDeposit)
                    throw new InvalidOperationException("เอกสารนี้ไม่ใช่เงินมัดจำ");
                if (doc.Status is DocumentStatus.Draft or DocumentStatus.Voided)
                    throw new InvalidOperationException("ใบมัดจำต้องอนุมัติแล้วและยังไม่ถูกยกเลิก");
                if (!doc.DepositOutputVatDeferred || doc.VatAmount <= 0.005m)
                    throw new InvalidOperationException(
                        "ใบนี้ไม่ได้ตั้งเป็น \"VAT รอเรียกเก็บ\" — ภาษีขายเข้า ภ.พ.30 ตั้งแต่วันรับเงินแล้ว");
                if (doc.DepositOutputVatRecognizedAt.HasValue)
                    throw new InvalidOperationException(
                        $"ภาษีขายของใบนี้ถูกรับรู้เข้า ภ.พ.30 ไปแล้วเมื่อ {doc.DepositOutputVatRecognizedAt:dd/MM/yyyy}");
                if (doc.DepositAppliedToDocumentId.HasValue)
                    throw new InvalidOperationException(
                        "มัดจำใบนี้ถูกนำไปหักในใบกำกับปลายทางแล้ว — ใบปลายทางรายงาน VAT ให้ทั้งก้อน "
                        + "ไม่ต้องรับรู้ที่ใบมัดจำอีก (จะกลายเป็นรายงานซ้ำ)");

                // วันที่รับรู้ = วันที่ tax point เกิดจริง (default วันนี้). งวดต้องยัง
                // เปิดอยู่ — ไม่งั้น VAT จะตกไปอยู่งวดที่ยื่นไปแล้ว
                var when = (recognizeDate ?? DateTime.UtcNow).Date;
                var openPeriod = await ResolveFiscalPeriodAsync(companyId, when);
                if (openPeriod != null && openPeriod.Status != FiscalPeriodStatus.Open)
                    throw new InvalidOperationException(
                        $"งวดบัญชี {openPeriod.StartDate:dd/MM/yyyy}–{openPeriod.EndDate:dd/MM/yyyy} "
                        + $"สถานะ {openPeriod.Status} — เลือกวันที่รับรู้ในงวดที่ยังเปิดอยู่");
                var filed = await _db.TaxReports.AsNoTracking().AnyAsync(t =>
                    t.CompanyId == companyId && !t.IsDeleted && t.TaxType == TaxType.VAT
                    // ★ รอบ 183 — งวดที่ประกาศว่ายื่นแล้วก็เลือกวันรับรู้เข้าไปไม่ได้
                    && Accounting.Helpers.TaxFilingLockPolicy.DeclaredOrFiledStatuses.Contains(t.Status)
                    && t.Year == when.Year && t.Month == when.Month);
                if (filed)
                    throw new InvalidOperationException(
                        $"งวด {when:MM/yyyy} ยื่น ภ.พ.30 ไปแล้ว — เลือกวันที่รับรู้ในงวดที่ยังไม่ยื่น "
                        + "(หรือยื่นเพิ่มเติมงวดนั้นแล้วปลดล็อกรายงานก่อน)");

                var deferredVatAcc = await FindAccountAsync(companyId, "21913")
                    ?? throw new InvalidOperationException("ไม่พบผังบัญชี 21913 (ภาษีขายรอเรียกเก็บ)");
                var outputVatAcc = await FindAccountAsync(companyId, "21911")
                    ?? throw new InvalidOperationException("ไม่พบผังบัญชี 21911 (ภาษีขาย)");

                var period = await RequireOpenFiscalPeriodAsync(companyId, when, "รายการรับรู้ภาษีขาย");
                var je = new JournalEntry
                {
                    CompanyId = companyId,
                    EntryNumber = await GetNextJournalEntryNumberAsync(companyId, "JV"),
                    EntryDate = when,
                    JournalType = JournalType.General,
                    Description = $"รับรู้ภาษีขายรอเรียกเก็บ (จุดรับผิด §78 เกิด) - {doc.DocumentNumber}",
                    Reference = doc.DocumentNumber,
                    Status = JournalEntryStatus.Posted,
                    TotalDebit = doc.VatAmount,
                    TotalCredit = doc.VatAmount,
                    CreatedBy = actor,
                    IsAutoGenerated = true,
                    SourceDocumentId = doc.Id,
                    FiscalPeriodId = period?.Id,
                    ProjectId = doc.ProjectId,
                };
                _db.JournalEntries.Add(je);
                _db.JournalEntryLines.Add(new JournalEntryLine
                {
                    JournalEntryId = je.Id, AccountId = deferredVatAcc.Id,
                    DebitAmount = doc.VatAmount, CreditAmount = 0,
                    Description = "ตัดภาษีขายรอเรียกเก็บ (tax point เกิด)", LineOrder = 1,
                });
                _db.JournalEntryLines.Add(new JournalEntryLine
                {
                    JournalEntryId = je.Id, AccountId = outputVatAcc.Id,
                    DebitAmount = 0, CreditAmount = doc.VatAmount,
                    Description = "ภาษีขาย ภ.พ.30 (มัดจำถึงกำหนด)", LineOrder = 2,
                });

                doc.DepositOutputVatRecognizedAt = when;   // → เข้า ภ.พ.30 งวดนี้ + หัว upgrade
                doc.UpdatedAt = DateTime.UtcNow;
                doc.UpdatedBy = actor;
                await _db.SaveChangesAsync();
                await tx.CommitAsync();

                _logger.LogInformation(
                    "Recognized deferred output VAT {Vat:N2} for deposit {Doc} on {When:yyyy-MM-dd}",
                    doc.VatAmount, doc.DocumentNumber, when);
                return await GetDocumentAsync(companyId, depositId);
            }
            catch { await tx.RollbackAsync(); throw; }
        });
    }

    /// <summary>โควตาเอกสารเดือนนี้ (ใช้แล้ว, เพดาน) — อ่านจาก resolver เดียวกับที่บังคับ
    /// เพื่อให้ข้อความที่ผู้ใช้เห็นตรงกับตัวเลขที่ระบบใช้ตัดสินจริง</summary>
    private async Task<(int Used, int Limit)> GetDocumentQuotaAsync(Guid companyId)
    {
        var eff = await _subscriptionService.GetEffectivePlanAsync(companyId);
        var sub = await _db.Subscriptions.AsNoTracking()
            .Where(s => s.CompanyId == companyId && !s.IsDeleted)
            .Select(s => new { s.CurrentMonthDocuments, s.DocumentBonusQuota, s.DocumentBonusExpiresAt })
            .FirstOrDefaultAsync();
        // โบนัส (top-up/แอดมินให้/ภารกิจ) ต้องบวกที่นี่ด้วย ไม่ใช่แค่ใน
        // CheckUsageLimitAsync — ไม่งั้นข้อความปฏิเสธจะบอกเพดานผิดจากที่ระบบใช้จริง
        return (sub?.CurrentMonthDocuments ?? 0,
            DocumentQuotaPolicy.EffectiveLimit(eff?.MaxDocumentsPerMonth ?? 0,
                sub?.DocumentBonusQuota ?? 0, sub?.DocumentBonusExpiresAt, DateTime.UtcNow));
    }

    /// <summary>เอกสารเกินโควตา 1 ฉบับ = 1 UsageEvent (documents.overage)
    ///
    /// **ห้าม throw** — งานหลักคือเอกสารที่กฎหมายบังคับให้ออก บันทึกมิเตอร์ไม่ได้
    /// ก็ต้องออกเอกสารสำเร็จอยู่ดี (หลักเดียวกับที่ UsageMeteringService ประกาศไว้)
    /// idempotent ด้วย DocumentId — สร้างเอกสารใบเดิมซ้ำไม่ได้อยู่แล้ว แต่กัน retry</summary>
    private async Task RecordDocumentOverageAsync(Guid companyId, Document doc)
    {
        if (_metering == null) return;
        try
        {
            await _metering.RecordAsync(new UsageRecordRequest(
                CompanyId: companyId,
                FeatureCode: Models.Constants.AddOnCodes.DocumentsOverage,
                Quantity: 1,
                IdempotencyKey: $"doc-overage:{doc.Id:N}",
                RefEntityType: "Document",
                RefEntityId: doc.Id));
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "บันทึก overage เอกสาร {DocId} ไม่สำเร็จ — เอกสารออกแล้วตามปกติ", doc.Id);
        }
    }

    /// <summary>เอกสารนี้มาจากโมดูลที่พักไหม (ไม่นับโควตาซ้ำ — มิเตอร์คือ lodging.stay)</summary>
    private static bool IsLodgingOrigin(string? originModule)
        => string.Equals(originModule, "Lodging", StringComparison.OrdinalIgnoreCase);

    /// <summary>ผนวกเลขมัดจำเข้า DepositAppliedRef แบบ comma-separated + dedup —
    /// หักหลายใบเข้าใบเดียว → เก็บเลขครบทุกใบ (เดิมเก็บแค่ใบแรก → PDF/รายงานโชว์
    /// "หักเงินมัดจำ (ใบแรก)" ทั้งที่หักหลายใบ). driveDeposit resolution + PDF
    /// อ่านโดย split comma อยู่แล้ว.</summary>
    private static string MergeDepositRef(string? existing, string add)
    {
        var refs = string.IsNullOrWhiteSpace(existing)
            ? new List<string>()
            : existing.Split(',').Select(s => s.Trim()).Where(s => s.Length > 0).ToList();
        if (!string.IsNullOrWhiteSpace(add) && !refs.Contains(add.Trim())) refs.Add(add.Trim());
        return string.Join(", ", refs);
    }

    private async Task<ChartOfAccount?> ResolveDepositBaseAccountAsync(Guid companyId, Guid depositId)
    {
        var legs = await (from l in _db.JournalEntryLines.AsNoTracking()
                          join j in _db.JournalEntries.AsNoTracking() on l.JournalEntryId equals j.Id
                          join a in _db.ChartOfAccounts.AsNoTracking() on l.AccountId equals a.Id
                          where j.CompanyId == companyId && j.SourceDocumentId == depositId
                                && !j.IsDeleted && !l.IsDeleted
                                && j.OriginalEntryId == null && j.ReversedByEntryId == null
                                && j.Status == JournalEntryStatus.Posted
                                && (a.AccountCode.StartsWith("215") || a.AccountCode.StartsWith("217"))
                          select new { l.AccountId, Net = l.CreditAmount - l.DebitAmount })
            .ToListAsync();
        var best = legs.GroupBy(x => x.AccountId)
            .Select(g => new { AccountId = g.Key, Net = g.Sum(x => x.Net) })
            .Where(x => x.Net > 0.005m)
            .OrderByDescending(x => x.Net)
            .FirstOrDefault();
        return best == null ? null
            : await _db.ChartOfAccounts.FirstOrDefaultAsync(a => a.Id == best.AccountId && a.CompanyId == companyId);
    }

    public async Task<DocumentResponse> RealizeDepositAsync(
        Guid companyId, Guid documentId, RealizeDepositRequest request, string actor)
    {
        var doc = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");
        await _db.HydrateContactAsync(companyId, doc);  // กัน INNER JOIN ตัดใบที่ contact ถูกลบ

        if (!doc.IsDeposit)
            throw new InvalidOperationException("เอกสารนี้ไม่ใช่เงินมัดจำ/รับล่วงหน้า");
        if (doc.Status == DocumentStatus.Draft || doc.Status == DocumentStatus.Voided)
            throw new InvalidOperationException("รับรู้รายได้ได้เฉพาะมัดจำที่อนุมัติแล้ว");

        // ฐาน (ไม่รวม VAT) คงค้างที่ยังรับรู้ไม่ได้ — ต้องหัก "ส่วนที่คืนลูกค้าไปแล้ว"
        // ด้วย (สูตรเดียวกับ RefundDepositAsync/ApplyDepositToInvoiceAsync): เดิมหัก
        // แค่ DepositRealizedAmount → มัดจำที่คืนครบแล้ว (217xx = 0) ยังรับรู้รายได้
        // ได้อีกรอบ → 217xx ติดลบ, รายได้+ภาษีขายเกินจริงใน ภ.พ.30
        var realizeVatPortion = doc.TotalAmount > 0 ? doc.VatAmount / doc.TotalAmount : 0m;
        var realizeRefundedBase = Math.Round(
            doc.DepositRefundedAmount * (1 - realizeVatPortion), 2, MidpointRounding.AwayFromZero);
        var outstanding = doc.SubTotal - doc.DepositRealizedAmount - realizeRefundedBase;
        if (request.Amount <= 0)
            throw new InvalidOperationException("จำนวนเงินที่รับรู้ต้องมากกว่า 0");
        if (request.Amount > outstanding + 0.005m)
            throw new InvalidOperationException(
                $"รับรู้เกินยอดมัดจำคงค้าง (คงค้าง {Math.Max(0, outstanding):N2}, ขอรับรู้ {request.Amount:N2}) — "
                + $"รับรู้แล้ว {doc.DepositRealizedAmount:N2}, คืนแล้ว {realizeRefundedBase:N2}");

        // GL-driven: Dr ผังหนี้สินมัดจำจริงที่ใบนี้ Cr ไว้ (เช่น 21510) — ไม่เดา 21712
        var deferredAcc = await ResolveDepositBaseAccountAsync(companyId, doc.Id)
            ?? await FindAccountAsync(companyId, doc.DepositDeferredAccountCode ?? "21712")
            ?? await FindAccountAsync(companyId, "217")
            ?? throw new InvalidOperationException("ไม่พบบัญชีขายรอรับรู้ (217xx) ในผังบัญชี");
        var revenueAcc = await FindAccountAsync(companyId, request.RevenueAccountCode ?? "41000")
            ?? await FindAccountAsync(companyId, "42000")
            ?? await _db.ChartOfAccounts
                .Where(a => a.CompanyId == companyId && a.AccountType == AccountType.Revenue && a.Level >= 4 && a.IsActive)
                .OrderBy(a => a.AccountCode).FirstOrDefaultAsync()
            ?? throw new InvalidOperationException("ไม่พบบัญชีรายได้ในผังบัญชี");

        var when = request.RealizeDate ?? DateTime.UtcNow;
        // เคส Deferred output VAT: การรับรู้รายได้ (ส่งมอบ/ให้บริการ) = tax point
        // เกิดจริง → ย้ายภาษีขายรอเรียกเก็บ 21913 → ภาษีขาย ภ.พ.30 21911 เต็มจำนวน
        // ครั้งแรกที่ realize (จุดรับผิดเกิดทันทีที่เริ่มส่งมอบ — บันทึกเชิงระวัง).
        var recognizeDeferredVat = doc.DepositOutputVatDeferred
            && doc.DepositOutputVatRecognizedAt == null
            && doc.VatAmount > 0;
        ChartOfAccount? deferredVatAcc = null, outputVatAcc = null;
        if (recognizeDeferredVat)
        {
            deferredVatAcc = await FindAccountAsync(companyId, "21913");
            outputVatAcc = await FindAccountAsync(companyId, "21911");
            if (deferredVatAcc == null || outputVatAcc == null)
            {
                recognizeDeferredVat = false;   // ผังไม่รองรับ → คงไว้ที่เดิม
                // ห้ามเงียบ (audit #13): ถ้าไม่ log VAT จะค้าง 21913 + RecognizedAt
                // ไม่ถูก stamp → ภ.พ.30 ข้ามใบนี้ตลอดไปโดยไม่มีใครรู้
                _logger.LogWarning(
                    "RealizeDeposit {Doc}: ผังบัญชีไม่มี 21913/21911 — ข้ามการรับรู้ VAT รอเรียกเก็บ (VAT {Vat:N2} ค้างที่ 21913 และจะไม่เข้า ภ.พ.30 จนกว่าจะเพิ่มบัญชี)",
                    doc.DocumentNumber, doc.VatAmount);
            }
        }
        var vatMove = recognizeDeferredVat ? doc.VatAmount : 0m;

        var entryNumber = await GetNextJournalEntryNumberAsync(companyId, "JV");
        var period = await RequireOpenFiscalPeriodAsync(companyId, when, "รายการรับรู้มัดจำ");
        var je = new JournalEntry
        {
            CompanyId = companyId,
            EntryNumber = entryNumber,
            EntryDate = when,
            JournalType = JournalType.General,
            Description = $"รับรู้รายได้จากมัดจำ - {doc.DocumentNumber}",
            Reference = doc.DocumentNumber,
            Status = JournalEntryStatus.Posted,
            TotalDebit = request.Amount + vatMove,
            TotalCredit = request.Amount + vatMove,
            CreatedBy = actor,
            IsAutoGenerated = true,
            SourceDocumentId = doc.Id,
            FiscalPeriodId = period?.Id,
            ProjectId = doc.ProjectId,
        };
        _db.JournalEntries.Add(je);
        var lineNo = 1;
        _db.JournalEntryLines.Add(new JournalEntryLine
        {
            JournalEntryId = je.Id, AccountId = deferredAcc.Id,
            DebitAmount = request.Amount, CreditAmount = 0,
            Description = "ตัดขายรอรับรู้ (มัดจำ)", LineOrder = lineNo++,
        });
        _db.JournalEntryLines.Add(new JournalEntryLine
        {
            JournalEntryId = je.Id, AccountId = revenueAcc.Id,
            DebitAmount = 0, CreditAmount = request.Amount,
            Description = "รับรู้รายได้", LineOrder = lineNo++,
        });
        if (recognizeDeferredVat)
        {
            _db.JournalEntryLines.Add(new JournalEntryLine
            {
                JournalEntryId = je.Id, AccountId = deferredVatAcc!.Id,
                DebitAmount = vatMove, CreditAmount = 0,
                Description = "ตัดภาษีขายรอเรียกเก็บ (tax point เกิด)", LineOrder = lineNo++,
            });
            _db.JournalEntryLines.Add(new JournalEntryLine
            {
                JournalEntryId = je.Id, AccountId = outputVatAcc!.Id,
                DebitAmount = 0, CreditAmount = vatMove,
                Description = "ภาษีขาย ภ.พ.30 (มัดจำถึงกำหนด)", LineOrder = lineNo++,
            });
            doc.DepositOutputVatRecognizedAt = when;   // เข้า ภ.พ.30 เดือนนี้
        }

        doc.DepositRealizedAmount += request.Amount;
        if (doc.SubTotal - doc.DepositRealizedAmount <= 0.005m)
            doc.DepositRealizedAt = when;   // ปิดมัดจำ (รับรู้ครบ)

        await _db.SaveChangesAsync();
        var updated = await GetDocumentAsync(companyId, documentId);
        await FireWebhookAsync(companyId, "deposit.realized", updated);
        return updated;
    }

    public async Task<List<DepositSummary>> GetDepositsAsync(Guid companyId, string? status = null)
    {
        // (1) เอกสารมัดจำ native — ติดธง IsDeposit ตอนสร้างในระบบ
        //     ⚠️ ห้าม .Include(d => d.Contact): Document.Contact เป็น required
        //     relationship + Contact มี HasQueryFilter(!IsDeleted) → EF แปลง
        //     Include เป็น INNER JOIN + filter → เอกสารมัดจำที่ contact ถูกลบ/ปิด
        //     (IsDeleted=true, เช่น vendor ที่ deactivate) จะถูก "ตัดทิ้งเงียบ" ทั้งใบ
        //     → dashboard โชว์ 0 ทั้งที่มีมัดจำจริง. โหลดชื่อ contact แยก (ด้านล่าง)
        var rows = await _db.Documents.AsNoTracking()
            .Where(d => d.CompanyId == companyId && d.IsDeposit
                && d.Status != DocumentStatus.Draft && d.Status != DocumentStatus.Voided)
            .ToListAsync();

        // (2) เอกสารที่ "เป็นมัดจำจริงตาม GL" แต่ไม่ได้ติดธง IsDeposit — เช่นใบเสร็จ
        //     ที่สร้างผ่าน integration (ระบบภายนอกลง JE เอง Cr 215xx/217xx ผ่าน
        //     account mapping DEPOSIT_RECEIVED โดยไม่ set IsDeposit) → dashboard เดิม
        //     กรอง IsDeposit=true จึงพลาด. ตรวจจากการลงบัญชีจริง (Cr เงินมัดจำ/ขายรอ
        //     รับรู้) เพื่อให้ dashboard สะท้อนความจริงทางบัญชี ไม่พึ่งแค่ธง.
        // ยอด Cr สุทธิในบัญชีมัดจำต่อเอกสาร (สำหรับ doc ที่ integration ลง แต่
        // SubTotal อาจเป็น 0 — ใช้ยอด GL จริงเป็นฐานแทน) + ยอดมัดจำที่เป็น JE
        // ล้วนไม่มีเอกสารผูก (SourceDocumentId == null) เพื่อไม่ให้ KPI ขึ้น 0
        // ทั้งที่งบดุลมีหนี้สินมัดจำจริง
        var glNetByDoc = new Dictionary<Guid, decimal>();
        var glAllNetByDoc = new Dictionary<Guid, decimal>();
        decimal docLessDepositNet = 0m;
        try
        {
            // หา "บัญชีหนี้สินมัดจำ/รับล่วงหน้า" ของบริษัทนี้ก่อน — จับด้วย **ชื่อบัญชี**
            // (มัดจำ/รับล่วงหน้า/รอรับรู้) หรือรหัส 215xx/217xx เพื่อให้ครอบคลุมทุกผัง
            // ไม่ว่าจะตั้งเลขบัญชีแบบไหน (เช่น 21510 "เงินมัดจำ/ชำระล่วงหน้าค่าห้องพัก")
            var depAcctIds = await _db.ChartOfAccounts.AsNoTracking()
                .Where(a => a.CompanyId == companyId && !a.IsDeleted
                    && (a.AccountCode.StartsWith("215") || a.AccountCode.StartsWith("217")
                        || a.AccountName.Contains("มัดจำ")
                        || a.AccountName.Contains("รับล่วงหน้า")
                        || a.AccountName.Contains("รอรับรู้")))
                .Select(a => a.Id)
                .ToListAsync();

            if (depAcctIds.Count > 0)
            {
                // ดึงบรรทัด JE ทุกบรรทัดที่แตะบัญชีมัดจำ (Posted, ไม่ reverse) —
                // ทั้ง Cr (รับมัดจำ = เพิ่มหนี้สิน) และ Dr (ตัด/คืนมัดจำ = ลดหนี้สิน)
                // เพื่อคำนวณ "ยอดคงค้างสุทธิ" = ΣCr − ΣDr ต่อเอกสาร
                var depLines = await _db.JournalEntryLines.AsNoTracking()
                    .Where(l => !l.IsDeleted
                        && depAcctIds.Contains(l.AccountId)
                        && l.JournalEntry.CompanyId == companyId
                        && l.JournalEntry.Status == JournalEntryStatus.Posted
                        && l.JournalEntry.ReversedByEntryId == null)
                    .Select(l => new
                    {
                        Net = l.CreditAmount - l.DebitAmount,
                        DocId = l.JournalEntry.SourceDocumentId
                    })
                    .ToListAsync();

                var nativeIds = rows.Select(r => r.Id).ToHashSet();

                // GL net ต่อเอกสาร "ทุกใบ" (รวม native) — ใช้เป็น fallback ให้ native
                // ที่ field ไม่ถูกตั้ง (SubTotal=0 จาก integration) แสดงยอดจริงจาก GL
                glAllNetByDoc = depLines
                    .Where(x => x.DocId.HasValue)
                    .GroupBy(x => x.DocId!.Value)
                    .Select(g => new { DocId = g.Key, Net = g.Sum(x => x.Net) })
                    .ToDictionary(g => g.DocId, g => g.Net);

                // (2a) เอกสารที่ยังไม่ติดธง IsDeposit แต่มียอด Cr สุทธิในบัญชีมัดจำ
                //      — ครอบคลุม "ทุก doc type" (integration/POS/receipt/invoice)
                //      ไม่จำกัดแค่ Receipt เพราะการ Cr บัญชีมัดจำคือสัญญาณ "รับมัดจำ"
                //      อยู่แล้ว ไม่ว่าเอกสารจะถูกจัดประเภทเป็นอะไร
                glNetByDoc = glAllNetByDoc
                    .Where(kv => !nativeIds.Contains(kv.Key) && kv.Value > 0.005m)
                    .ToDictionary(kv => kv.Key, kv => kv.Value);

                if (glNetByDoc.Count > 0)
                {
                    var extraIds = glNetByDoc.Keys.ToList();
                    var extra = await _db.Documents.AsNoTracking()
                        // ไม่ Include Contact (เหตุผลเดียวกับ step 1 — กัน INNER JOIN ตัดทิ้ง)
                        .Where(d => d.CompanyId == companyId && extraIds.Contains(d.Id)
                            && !d.IsDeposit   // native ถูกดึงไปแล้วในชุดแรก
                            && d.Status != DocumentStatus.Draft && d.Status != DocumentStatus.Voided)
                        .ToListAsync();
                    rows.AddRange(extra);
                    // ถ้าเอกสารถูกลบ/ไม่พบ แต่ยังมียอด GL → โยนเข้า docless เพื่อไม่หายจาก KPI
                    var foundIds = extra.Select(e => e.Id).ToHashSet();
                    foreach (var kv in glNetByDoc)
                        if (!foundIds.Contains(kv.Key)) docLessDepositNet += kv.Value;
                }

                // (2b) มัดจำที่ลงเป็น JE ล้วน ไม่มีเอกสารผูก (SourceDocumentId == null)
                //      — งบดุลมีหนี้สินมัดจำแต่ไม่มี Document ให้แสดงเป็นแถว →
                //      รวมยอดสุทธิเป็นแถวสรุป (ไม่มีปุ่มรับรู้/คืน เพราะไม่มี doc อ้างอิง)
                docLessDepositNet += depLines
                    .Where(x => !x.DocId.HasValue)
                    .Sum(x => x.Net);
            }
        }
        catch (Exception ex)
        {
            // GL-detection ล้ม → ไม่ทำให้หน้าเงินมัดจำพัง (แสดง native อย่างเดียว)
            _logger.LogWarning(ex, "GetDepositsAsync GL-based deposit detection failed — native-only");
        }
        rows = rows.OrderByDescending(d => d.DocumentDate).ToList();

        // โหลดชื่อ/เลขภาษี contact แยก แบบ IgnoreQueryFilters เพื่อให้ contact ที่
        // ถูกลบ/ปิด (IsDeleted=true) ยังโชว์ชื่อได้ และ **ไม่ทำให้เอกสารหายทั้งใบ**
        // (ต่างจาก .Include ที่ทำ INNER JOIN + filter → ตัดทิ้ง)
        var contactIds = rows.Select(d => d.ContactId).Where(id => id != Guid.Empty).Distinct().ToList();
        var contactMap = new Dictionary<Guid, (string Name, string? TaxId)>();
        if (contactIds.Count > 0)
        {
            try
            {
                contactMap = await _db.Contacts.AsNoTracking().IgnoreQueryFilters()
                    .Where(c => c.CompanyId == companyId && contactIds.Contains(c.Id))
                    .Select(c => new { c.Id, c.Name, c.TaxId })
                    .ToDictionaryAsync(c => c.Id, c => (c.Name, c.TaxId));
            }
            catch (Exception ex)
            {
                // โหลดชื่อ contact ล้ม → รายการต้องยังแสดง (ชื่อว่างดีกว่าหน้าว่าง)
                _logger.LogWarning(ex, "GetDepositsAsync contact-name lookup failed — degrade to blank names");
            }
        }

        var now = DateTime.UtcNow;
        var list = rows.Select(d =>
        {
            // doc ที่ตรวจจับจาก GL (ไม่ใช่ native): ใช้ยอด Cr สุทธิใน GL เป็นฐาน
            // เพราะ SubTotal/DepositRealizedAmount ของ integration doc อาจไม่ถูกตั้ง
            // (ทำให้เดิมคำนวณ outstanding = 0 → KPI ขึ้น 0 ทั้งที่มีมัดจำจริง)
            var isGlDetected = glNetByDoc.TryGetValue(d.Id, out var glNet);
            decimal baseAmt, outstanding, realized;
            // ฐานส่วนที่ "คืนเงิน" ไปแล้ว (gross → base ตามสัดส่วน VAT ของใบ) —
            // ต้องหักออกจาก outstanding (audit #7: เดิมไม่หัก → หน้าโชว์คงค้าง
            // ทั้งที่ GL 217xx = 0 หลังคืนครบ)
            var refundVatPortion = d.TotalAmount > 0 ? d.VatAmount / d.TotalAmount : 0m;
            var refundedBase = Math.Round(d.DepositRefundedAmount * (1 - refundVatPortion), 2, MidpointRounding.AwayFromZero);
            if (isGlDetected)
            {
                // GL net = ยอดหนี้สินมัดจำคงเหลือจริง (ΣCr − ΣDr) → คือ outstanding
                // ฐานเต็ม = ยอดที่เคยรับ ≈ base จากเอกสารถ้ามี ไม่งั้นใช้ GL net
                baseAmt = d.SubTotal > 0.005m ? d.SubTotal : glNet;
                outstanding = glNet;
                realized = baseAmt - outstanding;
                if (realized < 0) { realized = 0; baseAmt = outstanding; }
            }
            else if (d.SubTotal <= 0.005m && glAllNetByDoc.TryGetValue(d.Id, out var nativeGlNet) && nativeGlNet > 0.005m)
            {
                // native ที่ field ไม่ถูกตั้ง (SubTotal=0 จาก integration) แต่ GL มี
                // หนี้สินจริง → fallback GL net (audit #9: เดิมโชว์ 0/"Realized"
                // ทั้งที่ GL ค้าง)
                baseAmt = nativeGlNet;
                outstanding = nativeGlNet;
                realized = 0m;
            }
            else
            {
                baseAmt = d.SubTotal;
                realized = d.DepositRealizedAmount;
                // clamp ≥ 0 (audit #8: มัดจำ book แบบ gross ถูก drives หักเต็ม
                // gross → Realized > SubTotal → เดิมโชว์คงค้างติดลบ)
                outstanding = Math.Max(0m, d.SubTotal - d.DepositRealizedAmount - refundedBase);
            }
            var st = outstanding <= 0.005m ? "Realized"
                : realized > 0.005m ? "Partial" : "Outstanding";
            var ct = contactMap.TryGetValue(d.ContactId, out var cInfo) ? cInfo : ("", (string?)null);
            return new DepositSummary(
                d.Id, d.DocumentNumber, d.DocumentDate,
                ct.Item1, ct.Item2,
                baseAmt, d.VatAmount, d.TotalAmount,
                realized, outstanding,
                d.DepositRealizedAt,
                (int)(now.Date - d.DocumentDate.Date).TotalDays,
                st, d.DepositDeferredAccountCode,
                d.Reference, d.DepositOutputVatDeferred, d.DepositOutputVatRecognizedAt,
                d.BookingNumber, d.DepositRefundedAmount);
        }).ToList();

        // แถวสรุปมัดจำที่เป็น JE ล้วน (ไม่มีเอกสารผูก) — งบดุลมีหนี้สินมัดจำ
        // แต่ไม่มี Document ให้แสดง → รวมยอดสุทธิเป็น 1 แถว (id ว่าง = ไม่มีปุ่ม
        // รับรู้/คืน) เพื่อ KPI สะท้อนยอดจริง ไม่ขึ้น 0
        if (docLessDepositNet > 0.005m)
        {
            list.Insert(0, new DepositSummary(
                Guid.Empty, "— (จาก GL / ระบบภายนอก)", now,
                "มัดจำที่ยังไม่ผูกเอกสาร", null,
                docLessDepositNet, 0m, docLessDepositNet,
                0m, docLessDepositNet,
                null, 0, "Outstanding", null,
                null, false, null, null));
        }

        if (!string.IsNullOrWhiteSpace(status))
            list = list.Where(x => string.Equals(x.Status, status, StringComparison.OrdinalIgnoreCase)).ToList();
        return list;
    }

    /// <summary>วินิจฉัยหน้าเงินมัดจำ — ตอบว่าระบบเห็นบัญชีมัดจำ/JE เครดิต/
    /// เอกสารกี่รายการ เพื่อบอกสาเหตุเมื่อ dashboard โชว์ 0.</summary>
    public async Task<DepositDiagnostics> GetDepositDiagnosticsAsync(Guid companyId)
    {
        var depAccts = await _db.ChartOfAccounts.AsNoTracking()
            .Where(a => a.CompanyId == companyId && !a.IsDeleted
                && (a.AccountCode.StartsWith("215") || a.AccountCode.StartsWith("217")
                    || a.AccountName.Contains("มัดจำ")
                    || a.AccountName.Contains("รับล่วงหน้า")
                    || a.AccountName.Contains("รอรับรู้")))
            .Select(a => new { a.Id, a.AccountCode, a.AccountName })
            .ToListAsync();
        var depAcctIds = depAccts.Select(a => a.Id).ToList();

        var nativeCount = await _db.Documents.AsNoTracking()
            .CountAsync(d => d.CompanyId == companyId && d.IsDeposit
                && d.Status != DocumentStatus.Draft && d.Status != DocumentStatus.Voided);

        var lines = depAcctIds.Count == 0
            ? new List<(Guid AccountId, decimal Net, bool HasDoc, bool IsCredit)>()
            : (await _db.JournalEntryLines.AsNoTracking()
                .Where(l => !l.IsDeleted
                    && depAcctIds.Contains(l.AccountId)
                    && l.JournalEntry.CompanyId == companyId
                    && l.JournalEntry.Status == JournalEntryStatus.Posted
                    && l.JournalEntry.ReversedByEntryId == null)
                .Select(l => new
                {
                    l.AccountId,
                    Net = l.CreditAmount - l.DebitAmount,
                    HasDoc = l.JournalEntry.SourceDocumentId != null,
                    IsCredit = l.CreditAmount > 0
                })
                .ToListAsync())
                .Select(x => (x.AccountId, x.Net, x.HasDoc, x.IsCredit)).ToList();

        var creditLines = lines.Where(l => l.IsCredit).ToList();
        var totalNet = lines.Sum(l => l.Net);
        var perAcct = depAccts.Select(a => new DepositAccountInfo(
            a.AccountCode, a.AccountName,
            lines.Where(l => l.AccountId == a.Id).Sum(l => l.Net))).ToList();

        // ── self-probe: รัน GetDepositsAsync (โค้ดเดียวกับ endpoint หน้า list) ใน
        //    build นี้จริง — ฟันธงว่า "backend คืนข้อมูลไหม" แยกจาก "หน้าเห็นอะไร".
        //    probe > 0 แต่หน้า list ว่าง = response หน้า list โดน cache (SW/browser/
        //    CDN) 100%; probe = 0 ทั้งที่ native > 0 = บั๊กใน list builder → โชว์
        //    error message ตรง ๆ
        var listCount = 0;
        string? listError = null;
        try { listCount = (await GetDepositsAsync(companyId)).Count; }
        catch (Exception ex) { listError = ex.Message; }

        string hint;
        if (depAcctIds.Count == 0)
            hint = "ไม่พบ 'บัญชีมัดจำ/รับล่วงหน้า' ในผังบัญชี — ต้องมีบัญชีรหัส 215xx/217xx หรือชื่อมีคำว่า 'มัดจำ/รับล่วงหน้า/รอรับรู้' ก่อน (ไปที่ผังบัญชี → เพิ่มบัญชีหนี้สิน เช่น 21710 'เงินรับล่วงหน้า/มัดจำ')";
        else if (listError != null)
            hint = $"พบสาเหตุแล้ว: endpoint รายการมัดจำ error — {listError}";
        else if (listCount > 0)
            hint = $"backend คืนรายการมัดจำ {listCount} แถวปกติ — ที่หน้าเห็นว่าง = response เก่าถูก cache (service worker/browser/CDN). เวอร์ชันนี้ใส่ตัวกันแคช (_t) ให้ทุก API แล้ว: กด Ctrl+Shift+R หนึ่งครั้ง แล้วรายการจะขึ้นและไม่ค้างอีก (ถ้ายังไม่หาย: DevTools → Application → Service Workers → Unregister แล้วโหลดใหม่)";
        else if (creditLines.Count == 0)
            hint = $"พบบัญชีมัดจำ {depAcctIds.Count} บัญชี แต่ยังไม่มีการลงบัญชี (JE) เครดิตเข้าบัญชีเหล่านี้เลย — เงินมัดจำที่รับมาอาจถูกลงบัญชีอื่น (เช่น รายได้/ลูกหนี้) ตรวจการตั้งค่า mapping ตอนรับเงิน หรือลงรายการมัดจำผ่านเมนูขาย (ติ๊ก 'เงินมัดจำ')";
        else if (totalNet <= 0.005m && nativeCount == 0)
            hint = $"พบเครดิตมัดจำ {creditLines.Count} บรรทัด แต่ยอดสุทธิ (เครดิต−เดบิต) = {totalNet:N2} — มัดจำถูกรับรู้/คืนไปหมดแล้ว (ไม่มีคงค้าง) จึงแสดง 0 ถูกต้อง";
        else
            hint = $"ระบบเห็นมัดจำ (เอกสารติดธง {nativeCount} ใบ · คงค้างสุทธิ {totalNet:N2}) แต่ list builder คืน 0 แถวใน build เดียวกัน — เป็นบั๊กใน GetDepositsAsync ที่ไม่ throw กรุณาส่งภาพหน้านี้ให้ผู้พัฒนา (ระบุ: nativeCount={nativeCount}, probe=0)";

        return new DepositDiagnostics(
            depAcctIds.Count, perAcct, nativeCount,
            creditLines.Count, totalNet,
            creditLines.Count(l => l.HasDoc), creditLines.Count(l => !l.HasDoc),
            hint, listCount, listError);
    }

    /// <summary>Deposit Center — endpoint เดียวจบสำหรับหน้าเงินมัดจำ redesign:
    /// รายการ + KPI + GL tie-out + แหล่งที่มา ใน payload เดียว (atomic — หน้า
    /// ไม่มีวันโชว์ list ว่างพร้อม GL มียอดโดยไม่ฟ้อง). URL ใหม่ = ไม่เคยถูก
    /// cache ที่ชั้นไหน (ปิดปัญหา "แก้แล้วยังขึ้น 0" จาก SW/browser/CDN เดิม).</summary>
    public async Task<DepositCenterResponse> GetDepositCenterAsync(Guid companyId)
    {
        List<DepositSummary> rows;
        string? warning = null;
        try { rows = await GetDepositsAsync(companyId); }
        catch (Exception ex)
        {
            rows = new List<DepositSummary>();
            warning = $"โหลดรายการมัดจำล้มเหลว: {ex.Message}";
            _logger.LogError(ex, "GetDepositCenterAsync: list failed for {Company}", companyId);
        }

        // GL side — คำนวณตรงจากบัญชีมัดจำ (โค้ดเดียวกับ diagnostics แต่ไม่ self-probe
        // ซ้ำ เพราะ rows ข้างบนคือผลจริงอยู่แล้ว)
        var depAcctList = await _db.ChartOfAccounts.AsNoTracking()
            .Where(a => a.CompanyId == companyId && !a.IsDeleted
                && (a.AccountCode.StartsWith("215") || a.AccountCode.StartsWith("217")
                    || a.AccountName.Contains("มัดจำ")
                    || a.AccountName.Contains("รับล่วงหน้า")
                    || a.AccountName.Contains("รอรับรู้")))
            .Select(a => new { a.Id, a.AccountCode, a.AccountName })
            .ToListAsync();
        var depAcctIdSet = depAcctList.Select(a => a.Id).ToList();
        var glLines = depAcctIdSet.Count == 0
            ? new List<(Guid AccountId, decimal Net, bool HasDoc)>()
            : (await _db.JournalEntryLines.AsNoTracking()
                .Where(l => !l.IsDeleted
                    && depAcctIdSet.Contains(l.AccountId)
                    && l.JournalEntry.CompanyId == companyId
                    && l.JournalEntry.Status == JournalEntryStatus.Posted
                    && l.JournalEntry.ReversedByEntryId == null)
                .Select(l => new { l.AccountId, Net = l.CreditAmount - l.DebitAmount, HasDoc = l.JournalEntry.SourceDocumentId != null })
                .ToListAsync())
                .Select(x => (x.AccountId, x.Net, x.HasDoc)).ToList();
        var glNet = glLines.Sum(l => l.Net);
        var accounts = depAcctList.Select(a => new DepositAccountInfo(
            a.AccountCode, a.AccountName,
            glLines.Where(l => l.AccountId == a.Id).Sum(l => l.Net))).ToList();

        // KPIs จาก rows (แถว docless id=Guid.Empty นับรวมใน outstanding — เป็นหนี้สินจริง)
        var outstanding = rows.Sum(r => r.OutstandingAmount);
        var realized = rows.Where(r => r.Id != Guid.Empty).Sum(r => r.RealizedAmount);
        var refunded = rows.Where(r => r.Id != Guid.Empty).Sum(r => r.RefundedAmount);
        var deferredParked = rows.Where(r => r.OutputVatDeferred && r.OutputVatRecognizedAt == null)
            .Sum(r => r.VatAmount);
        var vatReported = rows.Where(r => r.Id != Guid.Empty && (!r.OutputVatDeferred || r.OutputVatRecognizedAt != null))
            .Sum(r => r.VatAmount);
        var openCount = rows.Count(r => r.Status != "Realized");

        var diff = Math.Round(glNet - outstanding, 2);
        // tolerance 1 บาท — เศษปัดสะสมจากการเฉลี่ยฐาน/VAT ต่อใบ
        var tieOk = Math.Abs(diff) <= 1.00m;
        if (warning == null && rows.Count == 0 && glNet > 0.005m)
            warning = $"บัญชีแยกประเภทมีหนี้สินมัดจำคงค้าง {glNet:N2} บาท แต่ระบบแสดงรายการไม่ได้ — กรุณาส่งภาพหน้านี้ให้ผู้ดูแล";

        var nativeDocs = rows.Count(r => r.Id != Guid.Empty);
        var doclessNet = rows.Where(r => r.Id == Guid.Empty).Sum(r => r.OutstandingAmount);

        return new DepositCenterResponse(
            DateTime.UtcNow,
            "deposit-center v1",
            new DepositCenterKpis(outstanding, realized, refunded, deferredParked, vatReported, openCount, rows.Count),
            rows,
            new DepositCenterTieOut(glNet, outstanding, diff, tieOk),
            new DepositCenterSources(nativeDocs, 0, doclessNet, depAcctList.Count, accounts),
            warning);
    }

    public async Task<List<DocumentResponse>> GetDocumentsByBookingAsync(Guid companyId, string bookingNumber)
    {
        if (string.IsNullOrWhiteSpace(bookingNumber)) return new List<DocumentResponse>();
        var key = bookingNumber.Trim();
        var ids = await _db.Documents.AsNoTracking()
            .Where(d => d.CompanyId == companyId && d.BookingNumber == key
                && d.Status != DocumentStatus.Voided)
            .OrderBy(d => d.DocumentDate)
            .Select(d => d.Id)
            .ToListAsync();
        var result = new List<DocumentResponse>(ids.Count);
        foreach (var id in ids) result.Add(await GetDocumentAsync(companyId, id));
        return result;
    }

    public async Task<ContactDepositSummary> GetContactDepositSummaryAsync(Guid companyId, Guid contactId)
    {
        var all = await GetDepositsAsync(companyId);
        var forContact = await _db.Documents.AsNoTracking()
            .Where(d => d.CompanyId == companyId && d.IsDeposit && d.ContactId == contactId
                && d.Status != DocumentStatus.Draft && d.Status != DocumentStatus.Voided)
            .Select(d => d.Id).ToListAsync();
        var ids = forContact.ToHashSet();
        var deposits = all.Where(d => ids.Contains(d.Id) && d.OutstandingAmount > 0.005m).ToList();
        return new ContactDepositSummary(
            contactId,
            deposits.Sum(d => d.OutstandingAmount),
            deposits.Count,
            deposits);
    }

    public async Task<DocumentResponse> RefundDepositAsync(
        Guid companyId, Guid documentId, RefundDepositRequest request, string actor)
    {
        var doc = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");
        await _db.HydrateContactAsync(companyId, doc);  // กัน INNER JOIN ตัดใบที่ contact ถูกลบ
        if (!doc.IsDeposit)
            throw new InvalidOperationException("เอกสารนี้ไม่ใช่เงินมัดจำ");
        if (doc.Status == DocumentStatus.Draft || doc.Status == DocumentStatus.Voided)
            throw new InvalidOperationException("คืนมัดจำได้เฉพาะมัดจำที่อนุมัติแล้ว");

        if (request.Amount <= 0)
            throw new InvalidOperationException("จำนวนเงินคืนต้องมากกว่า 0");

        // กัน double-click/2 requests พร้อมกัน: เดิมไม่มี transaction เลย —
        // (1) guard "คืนเกินคงเหลือ" อ่านค่าเก่าพร้อมกันผ่านทั้งคู่ → คืนเกิน +
        //     JE/CN สองชุด, (2) pg_advisory_xact_lock ของ generator เลข CN หลุด
        //     ทันทีที่ statement จบ (auto-commit) → เลข CN ซ้ำได้.
        // lock แถวมัดจำ + reload ยอดใต้ lock แล้วทำทั้งหมดใน transaction เดียว
        await using var refundTx = await _db.Database.BeginTransactionAsync();
        await _db.Database.ExecuteSqlRawAsync(
            "SELECT 1 FROM \"Documents\" WHERE \"Id\" = {0} AND \"CompanyId\" = {1} FOR UPDATE",
            documentId, companyId);
        await _db.Entry(doc).ReloadAsync();   // DepositRefunded/Realized ล่าสุดใต้ lock

        // แยกฐาน + VAT จากยอด gross ที่จะคืน (ตามสัดส่วนเดิมของใบ)
        var vatPortion = doc.TotalAmount > 0 ? doc.VatAmount / doc.TotalAmount : 0m;
        var refundVat = Math.Round(request.Amount * vatPortion, 2, MidpointRounding.AwayFromZero);
        var refundBase = request.Amount - refundVat;

        // guard คืนเกิน "มัดจำคงเหลือจริง" (audit #4): ต้องหักส่วนที่รับรู้/ตัดชำระ
        // ไปแล้วด้วย ไม่ใช่แค่ที่คืนไปแล้ว — ไม่งั้นมัดจำ 1,070 รับรู้ 500 ยังคืน
        // 1,070 ได้ → 217xx ติดลบ ~500
        var refundedBaseSoFar = Math.Round(doc.DepositRefundedAmount * (1 - vatPortion), 2, MidpointRounding.AwayFromZero);
        var remainingBase = doc.SubTotal - doc.DepositRealizedAmount - refundedBaseSoFar;
        if (refundBase > remainingBase + 0.005m)
            throw new InvalidOperationException(
                $"คืนเกินมัดจำคงเหลือ (ฐานคงเหลือ {Math.Max(0, remainingBase):N2} — " +
                $"รับรู้/ตัดชำระแล้ว {doc.DepositRealizedAmount:N2}, คืนแล้ว {refundedBaseSoFar:N2})");

        // GL-driven: Dr ผังหนี้สินมัดจำจริง (เช่น 21510) ไม่เดา 21712
        var deferredAcc = await ResolveDepositBaseAccountAsync(companyId, doc.Id)
            ?? await FindAccountAsync(companyId, doc.DepositDeferredAccountCode ?? "21712")
            ?? await FindAccountAsync(companyId, "217");
        var outVatAcc = doc.DepositOutputVatDeferred && doc.DepositOutputVatRecognizedAt == null
            ? await FindAccountAsync(companyId, "21913")
            : await FindAccountAsync(companyId, "21911");
        // บัญชีที่เงินออกจริง (F-03 รอบ 193) — ผู้เรียกระบุได้ (ต้องเป็นผังของบริษัทนี้) · ไม่ระบุ = 111 ตามเดิม
        var moneyAcc = request.MoneyAccountId is Guid moneyAccId
            ? await _db.ChartOfAccounts.FirstOrDefaultAsync(a => a.Id == moneyAccId && a.CompanyId == companyId)
                ?? throw new Accounting.Helpers.BusinessRuleException(
                    "ไม่พบบัญชีเงินที่เลือกสำหรับคืนมัดจำ หรือไม่ใช่ของบริษัทนี้ — เลือกบัญชีใหม่", "DEPOSIT-REFUND-MONEY-ACCOUNT")
            : await FindAccountAsync(companyId, "111");
        if (deferredAcc == null || moneyAcc == null)
            throw new InvalidOperationException("ไม่พบผังบัญชีขายรอรับรู้/เงินสดสำหรับคืนมัดจำ");
        // ⚠️ ผลตรวจทีม C · C-01: บรรทัดภาษีขายถูกใส่แบบมีเงื่อนไข
        // (`if (refundVat > 0 && outVatAcc != null)`) แต่หัว JE ประกาศ
        // `TotalDebit = request.Amount` (ฐาน + VAT) เสมอ ⇒ ผังที่ไม่มี 21911/21913
        // จะได้ JE ที่ **Dr ขาดไปเท่ากับ VAT** โดยหัวบอกว่าบาลานซ์ — งบไม่ลงตัว
        // เงียบ ๆ · ต้องล้มดังพร้อมบอกทางไปต่อ (กติกา "ห้าม silent no-op")
        if (refundVat > 0 && outVatAcc == null)
            throw new Accounting.Helpers.BusinessRuleException(
                "ไม่พบผังบัญชีภาษีขาย (21911/21913) สำหรับคืนมัดจำที่มี VAT — "
                + "กรุณาเพิ่มผังบัญชีภาษีขายก่อน แล้วทำรายการคืนมัดจำใหม่",
                "DEPOSIT-REFUND-NO-OUTVAT");

        var when = request.RefundDate ?? DateTime.UtcNow;
        var entryNumber = await GetNextJournalEntryNumberAsync(companyId, "JV");
        var period = await RequireOpenFiscalPeriodAsync(companyId, when, "รายการคืนมัดจำ");
        var je = new JournalEntry
        {
            CompanyId = companyId, EntryNumber = entryNumber, EntryDate = when,
            JournalType = JournalType.General,
            Description = $"คืนเงินมัดจำ - {doc.DocumentNumber}" + (string.IsNullOrWhiteSpace(request.Reason) ? "" : $" ({request.Reason})"),
            Reference = doc.DocumentNumber, Status = JournalEntryStatus.Posted,
            TotalDebit = request.Amount, TotalCredit = request.Amount,
            CreatedBy = actor, IsAutoGenerated = true, SourceDocumentId = doc.Id,
            FiscalPeriodId = period?.Id, ProjectId = doc.ProjectId,
        };
        _db.JournalEntries.Add(je);
        var ln = 1;
        // Dr ขายรอรับรู้ (กลับรายการรายได้รับล่วงหน้า)
        _db.JournalEntryLines.Add(new JournalEntryLine {
            JournalEntryId = je.Id, AccountId = deferredAcc.Id,
            DebitAmount = refundBase, CreditAmount = 0,
            Description = "คืนมัดจำ - กลับขายรอรับรู้", LineOrder = ln++ });
        // Dr ภาษีขาย (ใบลดหนี้ — กลับ output VAT ที่เคยรับ)
        if (refundVat > 0 && outVatAcc != null)
            _db.JournalEntryLines.Add(new JournalEntryLine {
                JournalEntryId = je.Id, AccountId = outVatAcc.Id,
                DebitAmount = refundVat, CreditAmount = 0,
                Description = "คืนมัดจำ - กลับภาษีขาย (ใบลดหนี้)", LineOrder = ln++ });
        // Cr เงินสด/ธนาคาร
        _db.JournalEntryLines.Add(new JournalEntryLine {
            JournalEntryId = je.Id, AccountId = moneyAcc.Id,
            DebitAmount = 0, CreditAmount = request.Amount,
            Description = "คืนเงินมัดจำให้ลูกค้า", LineOrder = ln++ });

        doc.DepositRefundedAmount += request.Amount;
        doc.DepositRefundedAt = when;
        doc.DepositRefundReason = request.Reason;

        // ── ออก "ใบลดหนี้" จริงเป็นเอกสาร (audit #5, §86/10) ──
        // เดิมคืนมัดจำเป็นแค่ JE เปล่า → ภ.พ.30 ไม่เคยถูกลดยอด (รายงานสแกนจาก
        // Documents) = ภาษีขายค้างสูงถาวร. ออก CN เฉพาะเมื่อ VAT ของมัดจำ "เคย
        // ถูกรายงาน" แล้ว (ขา 21911) — เคส deferred ที่ยังไม่ recognize (Dr 21913)
        // VAT ไม่เคยเข้า ภ.พ.30 จึงไม่มีอะไรให้ลด (JE reversal พอ).
        // CN สร้างแบบ Approved ตรง ๆ ไม่ผ่าน ApproveDocumentAsync — การลงบัญชี
        // อยู่ใน JE คืนมัดจำข้างบนแล้ว (Dr 21911/217xx / Cr เงินสด) ห้าม post ซ้ำ.
        var vatWasReported = !(doc.DepositOutputVatDeferred && doc.DepositOutputVatRecognizedAt == null);
        if (vatWasReported && refundVat > 0)
        {
            var cnNumber = await Accounting.Helpers.DocumentNumberGenerator.NextAsync(
                _db, companyId, DocumentType.CreditNote, when);
            var cnVatRate = doc.Lines.Any(l => l.VatRate > 0) ? doc.Lines.Where(l => l.VatRate > 0).Max(l => l.VatRate) : 7m;
            var cn = new Document
            {
                CompanyId = companyId,
                DocumentNumber = cnNumber,
                DocumentType = DocumentType.CreditNote,
                Status = DocumentStatus.Approved,
                DocumentDate = when,
                ContactId = doc.ContactId,
                RelatedDocumentId = doc.Id,
                CreditNoteReason = CreditNoteReason.Adjustment,   // คืนเงินมัดจำ/ยกเลิกจอง — ไม่กระทบสต๊อก
                Reference = doc.DocumentNumber,
                // CN คืนมัดจำออกให้ลูกค้าคนเดิม — ภาษาตามใบเสร็จมัดจำต้นทาง
                DocumentLanguage = doc.DocumentLanguage,
                // หน้าตาเอกสารต้องตามใบต้นทาง (กฎ "เอกสารลูกต้องสืบทอด")
                BrandId = doc.BrandId,
                BranchId = doc.BranchId,   // และสาขาที่ออกใบเดิม (§87)
                DocumentTemplateId = doc.DocumentTemplateId,
                SubTotal = refundBase,
                VatAmount = refundVat,
                TotalAmount = request.Amount,
                BalanceDue = 0,
                PaidAmount = 0,
                Notes = $"ใบลดหนี้คืนเงินมัดจำ {doc.DocumentNumber}" +
                        (string.IsNullOrWhiteSpace(request.Reason) ? "" : $" — {request.Reason}") +
                        $" (ลงบัญชีแล้วใน JE {entryNumber})",
                CreatedBy = actor,
                Lines = new List<DocumentLine>
                {
                    new DocumentLine
                    {
                        Description = $"คืนเงินมัดจำตามใบเสร็จ {doc.DocumentNumber}",
                        Quantity = 1, UnitPrice = refundBase, Amount = refundBase,
                        VatRate = cnVatRate, VatAmount = refundVat,
                        WithholdingTaxRate = 0, LineOrder = 1
                    }
                }
            };
            _db.Documents.Add(cn);
        }

        await _db.SaveChangesAsync();
        await refundTx.CommitAsync();
        var updated = await GetDocumentAsync(companyId, documentId);
        await FireWebhookAsync(companyId, "deposit.refunded", updated);
        return updated;
    }

    /// <summary>นำมัดจำมาตัดชำระใบแจ้งหนี้ — ห่อ transaction + ล็อกแถวทั้งใบมัดจำและ
    /// ใบแจ้งหนี้ก่อนอ่านยอด: guard over-apply อ่าน DepositRealizedAmount/BalanceDue
    /// แล้วเขียนทีหลัง ถ้าไม่ล็อก สองคำขอพร้อมกัน (กดปุ่มซ้ำ/สองแท็บ) จะผ่าน guard
    /// ทั้งคู่ → 217xx ติดลบ + PaidAmount เกินยอดใบ. อีกทั้ง GetNextJournalEntryNumberAsync
    /// ใช้ pg_advisory_xact_lock ซึ่งปล่อยทันทีเมื่อไม่มี transaction → เลข JV ซ้ำ</summary>
    public async Task<DocumentResponse> ApplyDepositToInvoiceAsync(
        Guid companyId, Guid invoiceId, ApplyDepositRequest request, string actor)
    {
        var strategy = _db.Database.CreateExecutionStrategy();
        return await strategy.ExecuteAsync(async () =>
        {
            await using var tx = await _db.Database.BeginTransactionAsync();
            try
            {
                // ล็อกทั้งสองแถวเรียงตาม Id คงที่ (กัน deadlock เมื่อสองคำขอสลับคู่กัน)
                var lockIds = new[] { invoiceId, request.DepositDocumentId }
                    .OrderBy(x => x).ToArray();
                foreach (var lid in lockIds)
                {
                    await _db.Database.ExecuteSqlRawAsync(
                        "SELECT 1 FROM \"Documents\" WHERE \"Id\" = {0} AND \"CompanyId\" = {1} FOR UPDATE",
                        lid, companyId);
                }

                var result = await ApplyDepositToInvoiceCoreAsync(companyId, invoiceId, request, actor);
                await tx.CommitAsync();
                return result;
            }
            catch
            {
                await tx.RollbackAsync();
                throw;
            }
        });
    }

    private async Task<DocumentResponse> ApplyDepositToInvoiceCoreAsync(
        Guid companyId, Guid invoiceId, ApplyDepositRequest request, string actor)
    {
        var invoice = await _db.Documents
            .FirstOrDefaultAsync(d => d.Id == invoiceId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบใบแจ้งหนี้");
        // อ่านค่าล่าสุดใต้ lock — entity อาจถูก track ไว้ก่อนเปิด transaction
        await _db.Entry(invoice).ReloadAsync();
        await _db.HydrateContactAsync(companyId, invoice);  // กัน INNER JOIN ตัดใบที่ contact ถูกลบ
        var deposit = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == request.DepositDocumentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสารมัดจำ");
        await _db.Entry(deposit).ReloadAsync();   // ยอด Realized/Refunded ล่าสุดใต้ lock
        await _db.HydrateContactAsync(companyId, deposit);  // กัน INNER JOIN ตัดใบที่ contact ถูกลบ
        if (!deposit.IsDeposit)
            throw new InvalidOperationException("เอกสารที่อ้างไม่ใช่เงินมัดจำ");
        if (deposit.ContactId != invoice.ContactId)
            throw new InvalidOperationException("มัดจำกับใบแจ้งหนี้ต้องเป็นลูกค้ารายเดียวกัน");

        // ── กัน VAT ซ้ำ: มัดจำที่ "ออกใบกำกับแล้ว" (VAT ทันที) ห้ามหักเข้าใบกำกับเต็มจำนวน ──
        // P0-3 รอบ 193 (คำตัดสินเจ้าของ #34): เดิมบล็อกเฉพาะเมื่อ "งวดของใบมัดจำยื่นแล้ว" — งวดที่ยังไม่ยื่น
        // ก็ผิดเหมือนกัน: การหักลง Dr 21911 ของมัดจำ + ใบปลายทางรายงาน VAT เต็ม + รายงานภาษีขายข้ามแถวมัดจำ
        // ⇒ VAT มัดจำย้ายไปเดือนของใบปลายทาง (§78/1 ช้า) และผู้ซื้อถือใบกำกับสองใบสำหรับภาษีก้อนเดียว
        // ตัวตัดสิน/ข้อความอยู่ที่ Helpers/DepositPolicyResolver ตัวเดียว (ใช้ร่วมกับเส้นขับ JE ใน AutoPost)
        if (Accounting.Helpers.DepositPolicyResolver.GrossApplyBlocked(deposit.VatAmount,
                deposit.DepositOutputVatDeferred && deposit.DepositOutputVatRecognizedAt == null))
            throw new Accounting.Helpers.BusinessRuleException(
                Accounting.Helpers.DepositPolicyResolver.GrossApplyBlockedMessage(deposit.DocumentNumber),
                Accounting.Helpers.DepositPolicyResolver.ImmediateVatGrossApplyRuleCode);

        // Multi-currency guard — IAS 21: ถ้าสกุล/rate ของมัดจำกับใบแจ้งหนี้
        // ต่างกัน ต้องคำนวณกำไรขาดทุนอัตราแลกเปลี่ยน. ระบบนี้ยังไม่ post FX
        // gain/loss JE อัตโนมัติ → block ไว้ก่อน + แนะนำให้บันทึก JE manual
        // (กัน GL เพี้ยนเงียบ ๆ ตอน user เปิด multi-currency)
        if (!string.Equals(invoice.Currency, deposit.Currency, StringComparison.OrdinalIgnoreCase)
            || Math.Abs(invoice.ExchangeRate - deposit.ExchangeRate) > 0.0001m)
        {
            throw new InvalidOperationException(
                $"สกุล/อัตราแลกเปลี่ยนของมัดจำ ({deposit.Currency} @ {deposit.ExchangeRate:F4}) " +
                $"ต่างกับใบแจ้งหนี้ ({invoice.Currency} @ {invoice.ExchangeRate:F4}) — " +
                "ระบบยังไม่รองรับการรับรู้กำไร/ขาดทุน FX อัตโนมัติ ตาม IAS 21. " +
                "กรุณาบันทึก JE manual หรือใช้มัดจำที่สกุลเงินเดียวกัน");
        }

        // นำมัดจำ (prepayment) มา "ตัดชำระ" ใบแจ้งหนี้ที่ลงบัญชีแล้ว: ใบแจ้งหนี้
        // รับรู้รายได้+ภาษีขายไปแล้ว (Dr ลูกหนี้/Cr รายได้+VAT) จึง **ห้ามรับรู้
        // รายได้ซ้ำ** — แค่ล้างหนี้สินมัดจำ (217xx + VAT รอเรียกเก็บ/ที่รับรู้แล้ว)
        // ไปตัดลูกหนี้: Dr 217xx(ฐาน) + Dr [21913|21911](VAT) / Cr ลูกหนี้ (gross).
        // เดิมเรียก RealizeDepositAsync (Cr รายได้) → รับรู้รายได้/VAT ซ้ำ + ไม่ตัด AR
        // (รายได้ 2 เท่า, AR ค้างตลอด). SourceDocumentId=มัดจำ → void มัดจำ reverse ได้.
        var vatPortion = deposit.TotalAmount > 0 ? deposit.VatAmount / deposit.TotalAmount : 0m;
        var baseAmt = Math.Round(request.Amount * (1 - vatPortion), 2, MidpointRounding.AwayFromZero);
        var vatAmt = Math.Round(request.Amount - baseAmt, 2, MidpointRounding.AwayFromZero);

        // ── Over-apply guards (audit #1) ──
        if (request.Amount <= 0)
            throw new InvalidOperationException("ยอดที่นำมาตัดชำระต้องมากกว่า 0");
        // (1) ห้ามหักเกินมัดจำคงเหลือ (ฐาน = SubTotal − รับรู้แล้ว − คืนแล้ว):
        //     กัน 217xx ติดลบ + DepositRealizedAmount > SubTotal
        var refundedBase = Math.Round(deposit.DepositRefundedAmount * (1 - vatPortion), 2, MidpointRounding.AwayFromZero);
        var availableBase = deposit.SubTotal - deposit.DepositRealizedAmount - refundedBase;
        if (baseAmt > availableBase + 0.005m)
            throw new InvalidOperationException(
                $"ยอดที่ตัดชำระ (ฐาน {baseAmt:N2}) เกินมัดจำคงเหลือ ({Math.Max(0, availableBase):N2}) — " +
                $"มัดจำ {deposit.DocumentNumber} รับรู้แล้ว {deposit.DepositRealizedAmount:N2} คืนแล้ว {refundedBase:N2}");
        // (2) ห้ามหักเกินยอดค้างของใบแจ้งหนี้: กัน PaidAmount > TotalAmount
        if (request.Amount > invoice.BalanceDue + 0.005m)
            throw new InvalidOperationException(
                $"ยอดที่ตัดชำระ ({request.Amount:N2}) เกินยอดค้างของใบแจ้งหนี้ ({invoice.BalanceDue:N2})");
        // (3) One-shot: 1 ใบมัดจำ → 1 ใบปลายทาง (สอดคล้อง void-restore 7b ที่คืน
        //     ยอดให้ใบเดียว — apply ข้ามหลายใบจะทำ restore เพี้ยน audit #2/#3).
        //     ทยอยหักซ้ำกับ "ใบเดิม" ได้; ใบอื่นต้องรอใบเดิมถูก void/ลบ (มาร์คโมฆะ
        //     → self-heal เหมือน drives)
        if (deposit.DepositAppliedToDocumentId.HasValue && deposit.DepositAppliedToDocumentId.Value != invoiceId)
        {
            var prior = await _db.Documents.AsNoTracking().FirstOrDefaultAsync(d =>
                d.Id == deposit.DepositAppliedToDocumentId.Value && d.CompanyId == companyId);
            if (prior != null && prior.Status != DocumentStatus.Voided)
                throw new InvalidOperationException(
                    $"มัดจำ {deposit.DocumentNumber} ถูกนำไปตัดชำระกับ {prior.DocumentNumber} แล้ว — " +
                    "หากต้องการย้ายไปใบอื่น ให้ยกเลิกใบนั้นก่อน (ระบบจะปลดมาร์คให้อัตโนมัติ)");
            // ใบเดิมถูกลบ/ยกเลิกแล้ว → มาร์คโมฆะ → apply ใหม่ได้ (ทับมาร์คด้านล่าง)
        }

        var arAcc = await FindAccountAsync(companyId, "113", invoice.Contact)
            ?? throw new InvalidOperationException("ไม่พบบัญชีลูกหนี้การค้า (113) ในผังบัญชี");

        // ── GL-driven: อ่าน "ขาจริง" จาก JE ของใบมัดจำ (แบบเดียวกับ JV apply) ──
        // เดิม field-driven (DepositDeferredAccountCode ?? 21712 + flag เดา VAT)
        // → ใบมัดจำที่ลง Cr ผังอื่นจริง (เช่น integration ลง 21510/21610) จะถูก
        // Dr 21712 ผิดผัง: ผังเดิมค้าง Cr ถาวร + 21712 ติดลบ. family-net = Cr−Dr
        // ต่อผังรวม "ทุก JE forward ของใบมัดจำ" (JE ต้นทาง + apply ก่อนหน้า ซึ่ง
        // ผูก SourceDocumentId = ใบมัดจำเหมือนกัน) → เหลือเท่าไรกลับเท่านั้น.
        // ตัดผัง 1xxxx ออก (เงินสด Dr ของ JE ต้นทาง / ลูกหนี้ Cr ของ apply เดิม)
        var famLines = await (from l in _db.JournalEntryLines.AsNoTracking()
                              join j in _db.JournalEntries.AsNoTracking() on l.JournalEntryId equals j.Id
                              join a in _db.ChartOfAccounts.AsNoTracking() on l.AccountId equals a.Id
                              where j.CompanyId == companyId && j.SourceDocumentId == deposit.Id
                                    && !j.IsDeleted && !l.IsDeleted
                                    && j.OriginalEntryId == null && j.ReversedByEntryId == null
                                    && j.Status == JournalEntryStatus.Posted
                              select new
                              {
                                  l.JournalEntryId, l.AccountId, a.AccountCode, a.AccountName,
                                  l.DebitAmount, l.CreditAmount,
                              })
            .ToListAsync();

        // ⚠️ นับ "ขา Cr" เฉพาะจาก JE ที่ **สร้างหนี้สินมัดจำ** (ใบเสร็จมัดจำ:
        // Cr 217xx/21913 หรือ Cr 21911 กรณีไม่ deferred) — ส่วนขา Dr นับจากทุก JE
        // ที่มา (M-1): มัดจำที่ถูก "รับรู้รายได้บางส่วน" (RealizeDeposit) มี JE
        //   Dr 217xx / Cr 41xxx  +  Dr 21913 / Cr 21911
        // ผูก SourceDocumentId = ใบมัดจำเหมือนกัน. ตัวกรองเดิมตัดแค่ผัง 1xxxx ⇒
        // Cr 41xxx (รายได้ที่รับรู้ไปแล้ว) และ Cr 21911 ของ realize ถูกนับเป็น
        // "มัดจำคงเหลือ" ⇒ ตอนเอาส่วนที่เหลือไปตัดใบแจ้งหนี้ ระบบลง **Dr 41000
        // ล้างรายได้ที่รับรู้ถูกต้องไปแล้ว** — งบกำไรขาดทุนหายรายได้เงียบ ๆ
        // (Dr=Cr ยังสมดุล จึงไม่มี guard ตัวไหนจับ)
        // 21911 ยังต้องนับได้เมื่อมาจากใบเสร็จมัดจำเอง (มัดจำที่รับรู้ VAT ทันที)
        // จึงแยกด้วย "JE นี้เครดิตบัญชีมัดจำหรือไม่" ไม่ใช่ด้วยรหัสบัญชี
        static bool IsDepositLiability(string code, string name)
            => code.StartsWith("215", StringComparison.Ordinal)
            || code.StartsWith("217", StringComparison.Ordinal)
            || name.Contains("มัดจำ") || name.Contains("รับล่วงหน้า") || name.Contains("รอรับรู้");

        var creatingJeIds = famLines
            .Where(x => x.CreditAmount > 0.005m && IsDepositLiability(x.AccountCode, x.AccountName))
            .Select(x => x.JournalEntryId)
            .ToHashSet();

        var famLegs = famLines
            .GroupBy(x => new { x.AccountId, x.AccountCode })
            .Select(g => (g.Key.AccountId, g.Key.AccountCode,
                Net: g.Where(x => creatingJeIds.Contains(x.JournalEntryId)).Sum(x => x.CreditAmount)
                     - g.Sum(x => x.DebitAmount)))
            .Where(x => x.Net > 0.005m && !x.AccountCode.StartsWith("1"))
            .OrderByDescending(x => x.Net)
            .ToList();

        bool depositVatDeferredPending;
        var when = request.ApplyDate ?? DateTime.UtcNow;
        var je = new JournalEntry
        {
            CompanyId = companyId,
            EntryNumber = await GetNextJournalEntryNumberAsync(companyId, "JV"),
            EntryDate = when,
            JournalType = JournalType.General,
            Description = $"นำมัดจำ {deposit.DocumentNumber} ตัดชำระ {invoice.DocumentNumber}",
            Reference = invoice.DocumentNumber,
            Status = JournalEntryStatus.Posted,
            TotalDebit = request.Amount, TotalCredit = request.Amount,
            CreatedBy = actor, IsAutoGenerated = true, SourceDocumentId = deposit.Id,
            FiscalPeriodId = (await RequireOpenFiscalPeriodAsync(companyId, when, "รายการมัดจำ"))?.Id,
            ProjectId = deposit.ProjectId,
        };
        _db.JournalEntries.Add(je);
        var ln = 1;
        if (famLegs.Count > 0)
        {
            // แบ่ง request.Amount (gross) ตามสัดส่วนขาจริงคงเหลือ — เศษปัดเข้า
            // ขาแรก (ใหญ่สุด) ให้รวม Dr = Cr ลูกหนี้พอดี
            var grossRemaining = famLegs.Sum(x => x.Net);
            if (request.Amount > grossRemaining + 0.01m)
                throw new InvalidOperationException(
                    $"ยอดที่ตัดชำระ ({request.Amount:N2}) เกินมัดจำคงเหลือตามบัญชีจริง ({grossRemaining:N2}) — " +
                    $"มัดจำ {deposit.DocumentNumber} อาจถูกหัก/คืนไปแล้วบางส่วน");
            var factor = request.Amount / grossRemaining;
            var debits = famLegs.Select(x => (x.AccountId, x.AccountCode,
                Amt: Math.Round(x.Net * factor, 2, MidpointRounding.AwayFromZero))).ToList();
            var rounding = request.Amount - debits.Sum(d => d.Amt);
            if (rounding != 0m && debits.Count > 0)
                debits[0] = (debits[0].AccountId, debits[0].AccountCode, debits[0].Amt + rounding);

            // แยกฐาน/VAT ตามผังจริง (ไม่ใช่ ratio field) → subledger ตรง GL
            baseAmt = debits.Where(d => d.AccountCode != "21913" && d.AccountCode != "21911").Sum(d => d.Amt);
            vatAmt = request.Amount - baseAmt;
            depositVatDeferredPending = debits.Any(d => d.AccountCode == "21913" && d.Amt > 0m);

            foreach (var d in debits.Where(d => d.Amt > 0m))
            {
                var isVat = d.AccountCode == "21913" || d.AccountCode == "21911";
                _db.JournalEntryLines.Add(new JournalEntryLine { JournalEntryId = je.Id, AccountId = d.AccountId,
                    DebitAmount = d.Amt, CreditAmount = 0,
                    Description = isVat
                        ? (d.AccountCode == "21913" ? "ตัดภาษีขายรอเรียกเก็บ (มัดจำ→ใบกำกับ)" : "ล้าง VAT มัดจำ (รับรู้ที่ใบกำกับแล้ว)")
                        : $"ตัดมัดจำ {deposit.DocumentNumber} (ตามผังที่ลงจริง)",
                    LineOrder = ln++ });
            }
        }
        else
        {
            // Fallback (ใบมัดจำไม่มี JE forward — ไม่ควรเกิดกับใบ approved ปกติ):
            // ใช้วิธี field-driven เดิม
            var deferredAcc = await FindAccountAsync(companyId, deposit.DepositDeferredAccountCode ?? "21712")
                ?? await FindAccountAsync(companyId, "217")
                ?? throw new InvalidOperationException("ไม่พบบัญชีขายรอรับรู้ (217xx) ในผังบัญชี");
            depositVatDeferredPending = deposit.DepositOutputVatDeferred
                && deposit.DepositOutputVatRecognizedAt == null && vatAmt > 0;
            ChartOfAccount? vatAcc = null;
            if (vatAmt > 0)
            {
                vatAcc = depositVatDeferredPending
                    ? await FindAccountAsync(companyId, "21913")
                    : await FindAccountAsync(companyId, "21911");
                if (vatAcc == null)
                    throw new InvalidOperationException("ไม่พบบัญชีภาษีขาย (21911/21913) — ไม่สามารถนำมัดจำมาตัดชำระได้");
            }
            _db.JournalEntryLines.Add(new JournalEntryLine { JournalEntryId = je.Id, AccountId = deferredAcc.Id,
                DebitAmount = baseAmt, CreditAmount = 0, Description = "ตัดขายรอรับรู้ (มัดจำ)", LineOrder = ln++ });
            if (vatAmt > 0 && vatAcc != null)
                _db.JournalEntryLines.Add(new JournalEntryLine { JournalEntryId = je.Id, AccountId = vatAcc.Id,
                    DebitAmount = vatAmt, CreditAmount = 0,
                    Description = depositVatDeferredPending ? "ตัดภาษีขายรอเรียกเก็บ (มัดจำ→ใบกำกับ)" : "ล้าง VAT มัดจำ (รับรู้ที่ใบกำกับแล้ว)",
                    LineOrder = ln++ });
        }
        _db.JournalEntryLines.Add(new JournalEntryLine { JournalEntryId = je.Id, AccountId = arAcc.Id,
            DebitAmount = 0, CreditAmount = request.Amount,
            Description = $"ตัดลูกหนี้ด้วยมัดจำ - {deposit.DocumentNumber}", LineOrder = ln++ });

        // มัดจำถูกใช้ไป (consumed ฐาน) + ปิด VAT รอเรียกเก็บถ้ามี
        deposit.DepositRealizedAmount += baseAmt;
        if (deposit.SubTotal - deposit.DepositRealizedAmount <= 0.005m)
            deposit.DepositRealizedAt = when;
        // stamp RecognizedAt เฉพาะเมื่อ "ใช้มัดจำครบ" (audit #6): ถ้า stamp ตั้งแต่
        // partial แรก apply ถัดไปจะเห็น RecognizedAt != null → หันไป Dr 21911 ทั้งที่
        // 21913 ยังเหลือค้าง (ghost) — ทยอย Dr 21913 ตามสัดส่วนจนครบแล้วค่อย stamp
        if (depositVatDeferredPending && deposit.SubTotal - deposit.DepositRealizedAmount <= 0.005m)
            deposit.DepositOutputVatRecognizedAt = when;

        // ตัดยอดค้างใบแจ้งหนี้ (gross)
        // S-7 + D4-3: ยอดค้าง/สถานะมาจาก `DocumentSettlementState` ตัวเดียวของระบบ
        // (เดิมตรรกะสามบรรทัดนี้ถูกคัดลอกด้วยมือ 7 ที่ ด้วยเกณฑ์ปัดเศษ 3 แบบ)
        invoice.PaidAmount += request.Amount;
        var depSettle = Accounting.Helpers.DocumentSettlementState.Apply(
            invoice.TotalAmount, invoice.PaidAmount, invoice.Status);
        invoice.BalanceDue = depSettle.BalanceDue;
        invoice.Status = depSettle.Status;
        // stamp ยอดหักมัดจำลงใบแจ้งหนี้ (audit E2): list/PDF โชว์ "หักมัดจำ/รับสุทธิ"
        // + API consumers เห็นยอดจริง (เดิมตั้งเฉพาะตอน create — apply ทีหลังไม่ตั้ง)
        invoice.DepositAppliedAmount += request.Amount;
        invoice.DepositAppliedRef = MergeDepositRef(invoice.DepositAppliedRef, deposit.DocumentNumber);
        deposit.DepositAppliedToDocumentId = invoiceId;

        // ── tax point §78/1: หักมัดจำ = "ได้รับชำระ" เช่นกัน (S-1) ────────────
        // ใบแจ้งหนี้บริการที่ VAT พักไว้ 21913 ถ้าปิดยอดด้วยมัดจำ (ไม่ผ่าน
        // CreatePaymentAsync) จะไม่มีใครย้าย VAT → 21911 ⇒ ใบหายจาก ภ.พ.30
        // ถาวรทั้งที่รับเงินครบแล้ว (นำส่งภาษีขายขาด). hook นี้ idempotent
        // ด้วย OutputVatDueAt และเป็น best-effort (ไม่ทำให้การหักมัดจำพัง)
        await TryReclassifyUndueOutputVatAsync(companyId, invoiceId, DateTime.UtcNow.Date, actor);

        await _db.SaveChangesAsync();

        // ── WHT ที่ค้างในลูกหนี้เมื่อมัดจำปิดยอดจนหมด (S-2) ─────────────────
        // เกณฑ์เงินสด (ค่า default): ตอนอนุมัติใบขาย GL ตั้ง Dr ลูกหนี้ **gross**
        // (TotalAmount + WHT) ส่วน BalanceDue ของ subledger ใช้ TotalAmount ที่
        // สุทธิจาก WHT แล้ว ⇒ ปิดยอดด้วยมัดจำจนครบ subledger ว่า "ชำระแล้ว"
        // แต่ลูกหนี้ใน GL ยังค้างเท่ายอด WHT **ตลอดไป** และไม่มีใครลง 11910
        // ⇒ เสียเครดิตภาษีทั้งก้อนตอนยื่น ภ.ง.ด.50 + งบดุลมีลูกหนี้ผี
        // (เส้นรับชำระเงินสดทำถูกอยู่แล้วผ่าน postPerPaymentWht — ขาดเส้นนี้เส้นเดียว)
        if (invoice.BalanceDue <= 0.005m && invoice.WithholdingTaxAmount > 0.005m)
            await TryRecognizeSalesWhtOnSettlementAsync(companyId, invoice, when, actor);

        var updated = await GetDocumentAsync(companyId, invoiceId);
        await FireWebhookAsync(companyId, "deposit.applied", updated);
        return updated;
    }

    /// <summary>ปิดยอดใบขายจนครบโดยไม่ผ่านการรับเงินสด (หักมัดจำ) → รับรู้
    /// "ภาษีถูกหัก ณ ที่จ่าย" ส่วนที่ยังไม่เคยลง: Dr 11910 / Cr ลูกหนี้.
    /// GL-first + idempotent: อ่านยอดที่ Dr 11910 ไปแล้วจริงของเอกสารนี้ แล้วลง
    /// เฉพาะส่วนต่าง ⇒ เรียกซ้ำ/ทยอยหักมัดจำหลายรอบไม่ทำให้เกิน. best-effort —
    /// การหักมัดจำที่สำเร็จแล้วต้องไม่ถูก rollback เพราะขั้นนี้</summary>
    private async Task TryRecognizeSalesWhtOnSettlementAsync(
        Guid companyId, Document invoice, DateTime when, string actor)
    {
        try
        {
            var whtBasis = (await _db.CompanySettings.AsNoTracking()
                .Where(s => s.CompanyId == companyId)
                .Select(s => (Models.Enums.WhtRecognitionBasis?)s.WhtRecognitionBasis)
                .FirstOrDefaultAsync()) ?? Models.Enums.WhtRecognitionBasis.Cash;
            // เกณฑ์คงค้าง: 11910 ลงตั้งแต่ตอนอนุมัติใบแล้ว และลูกหนี้ตั้งไว้สุทธิ
            // อยู่แล้ว — ไม่มีอะไรค้าง
            if (whtBasis != Models.Enums.WhtRecognitionBasis.Cash) return;

            var alreadyRecognized = (await (
                from l in _db.JournalEntryLines.AsNoTracking()
                join j in _db.JournalEntries.AsNoTracking() on l.JournalEntryId equals j.Id
                join a in _db.ChartOfAccounts.AsNoTracking() on l.AccountId equals a.Id
                where j.CompanyId == companyId && j.SourceDocumentId == invoice.Id
                      && !j.IsDeleted && !l.IsDeleted
                      && j.Status == JournalEntryStatus.Posted
                      && j.ReversedByEntryId == null
                      && a.AccountCode.StartsWith("11910")
                select l.DebitAmount - l.CreditAmount).ToListAsync()).Sum();

            var target = ToGlAmount(invoice, invoice.WithholdingTaxAmount);
            var remaining = Math.Round(target - alreadyRecognized, 2, MidpointRounding.AwayFromZero);
            if (remaining <= 0.005m) return;

            var whtAccount = await FindAccountAsync(companyId, "11910");
            var arAccount = await FindAccountAsync(companyId, "113", invoice.Contact);
            if (whtAccount == null || arAccount == null)
            {
                _logger.LogWarning(
                    "ปิดยอด {Doc} ด้วยมัดจำแล้วแต่ไม่พบผัง 11910/113 — ลูกหนี้ค้าง {Amount} เท่ายอด WHT",
                    invoice.DocumentNumber, remaining);
                return;
            }

            await Journal.JournalEntryBuilder
                .For(_db, companyId, when.Date)
                .Description($"ภาษีถูกหัก ณ ที่จ่าย (ปิดยอดด้วยมัดจำ) - {invoice.DocumentNumber}")
                .Reference(invoice.DocumentNumber)
                .SourceDocument(invoice.Id)
                .Project(invoice.ProjectId)
                .Debit(whtAccount.Id, remaining, "ภาษีถูกหัก ณ ที่จ่าย (ถูกหัก)")
                .Credit(arAccount.Id, remaining, $"ตัดลูกหนี้ส่วน WHT - {invoice.DocumentNumber}")
                .PostAsync(actor);

            // ทะเบียนเครดิตอ่านจาก GL 11910 จริง — เรียกหลัง post ให้แถวตรงยอด
            await SyncWhtCreditReceivedAsync(companyId, invoice);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex,
                "รับรู้ WHT ตอนปิดยอดด้วยมัดจำของ {Doc} ไม่สำเร็จ — " +
                "ตรวจลูกหนี้คงค้างและทะเบียนเครดิตภาษีของใบนี้ด้วยมือ", invoice.DocumentNumber);
        }
    }

    /// <summary>ค้น "JV มัดจำที่ไม่มีเอกสาร" — สมุดรายวันที่ integration post ตรง
    /// (/integration/journals) หรือลงมือ Cr บัญชีรับล่วงหน้า (215xx/217xx) โดยไม่มี
    /// SourceDocumentId + ยังไม่ถูกนำไปตัดชำระ (DepositAppliedToDocumentId == null).
    /// filter ด้วย query (ตรงกับ EntryNumber/Reference/Description แบบ contains) —
    /// ถ้าใส่เลขอ้างอิง/booking จะหาที่เกี่ยวข้อง; ไม่ใส่ = list ทั้งหมดที่เปิดอยู่.</summary>
    public async Task<List<JournalDepositCandidate>> SearchJournalDepositsAsync(
        Guid companyId, string? query)
    {
        var q = (query ?? "").Trim();
        // บัญชีมัดจำ/รับล่วงหน้า
        var depAcctIds = await _db.ChartOfAccounts.AsNoTracking()
            .Where(a => a.CompanyId == companyId
                && (a.AccountCode.StartsWith("215") || a.AccountCode.StartsWith("217")))
            .Select(a => a.Id).ToListAsync();
        if (depAcctIds.Count == 0) return new();

        // JE ที่ Posted, ไม่มี source doc, ยังไม่ถูก apply, มีขา Cr บนบัญชีมัดจำ
        var jeQuery = _db.JournalEntries.AsNoTracking()
            .Where(j => j.CompanyId == companyId && !j.IsDeleted
                && j.Status == JournalEntryStatus.Posted
                && j.SourceDocumentId == null
                && j.DepositAppliedToDocumentId == null
                && j.Lines.Any(l => !l.IsDeleted && l.CreditAmount > 0 && depAcctIds.Contains(l.AccountId)));
        if (q.Length > 0)
            jeQuery = jeQuery.Where(j => j.EntryNumber.Contains(q)
                || (j.Reference != null && j.Reference.Contains(q))
                || (j.Description != null && j.Description.Contains(q)));

        var jes = await jeQuery
            .OrderByDescending(j => j.EntryDate)
            .Take(50)
            .Select(j => new
            {
                j.Id, j.EntryNumber, j.EntryDate, j.Description, j.Reference,
                DeferredNet = j.Lines.Where(l => !l.IsDeleted && depAcctIds.Contains(l.AccountId))
                    .Sum(l => l.CreditAmount - l.DebitAmount),
                Gross = j.Lines.Where(l => !l.IsDeleted
                        && (depAcctIds.Contains(l.AccountId)
                            || l.Account.AccountCode == "21913" || l.Account.AccountCode == "21911"))
                    .Sum(l => l.CreditAmount - l.DebitAmount),
            })
            .ToListAsync();

        return jes.Where(j => j.DeferredNet > 0.005m)
            .Select(j => new JournalDepositCandidate(
                j.EntryNumber, j.EntryDate, j.Description, j.Reference,
                j.DeferredNet, System.Math.Max(0m, j.Gross)))
            .ToList();
    }

    /// <summary>นำ "JV มัดจำที่ไม่มีเอกสาร" (case B) มาตัดชำระใบแจ้งหนี้/ใบกำกับ —
    /// analogous กับ ApplyDepositToInvoiceAsync แต่ต้นทางเป็นสมุดรายวัน ไม่ใช่เอกสาร.
    /// อ่านขา Cr จริงของ JV (บัญชี 215/217 + VAT 21913/21911) → post JV ตัดชำระ:
    /// Dr บัญชีเดิม (base) + Dr VAT / Cr ลูกหนี้ (gross) + ลด BalanceDue. **one-shot
    /// เต็ม JV** (v1 ไม่รองรับ partial — มัดจำมากกว่ายอดใบ = block). mark
    /// JV.DepositAppliedToDocumentId กัน apply ซ้ำ. GL-critical — verify Windows.</summary>
    public async Task<DocumentResponse> ApplyJournalDepositToInvoiceAsync(
        Guid companyId, Guid invoiceId, string journalEntryNumber, string actor, DateTime? applyDate = null)
    {
        var invoice = await _db.Documents.FirstOrDefaultAsync(d => d.Id == invoiceId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบใบแจ้งหนี้");
        await _db.HydrateContactAsync(companyId, invoice);
        if (invoice.Status != DocumentStatus.Approved && invoice.Status != DocumentStatus.PartiallyPaid
            && invoice.Status != DocumentStatus.Sent && invoice.Status != DocumentStatus.Overdue)
            throw new InvalidOperationException("นำมัดจำมาตัดชำระได้เฉพาะใบที่อนุมัติแล้ว/ชำระบางส่วน/เกินกำหนด");

        var jv = await _db.JournalEntries.Include(j => j.Lines)
            .FirstOrDefaultAsync(j => j.CompanyId == companyId && j.EntryNumber == journalEntryNumber
                && j.Status == JournalEntryStatus.Posted && !j.IsDeleted)
            ?? throw new KeyNotFoundException($"ไม่พบสมุดรายวัน {journalEntryNumber} (Posted)");
        // row-lock กัน apply ซ้อน + re-read mark
        await _db.Database.ExecuteSqlRawAsync(
            @"SELECT ""Id"" FROM ""JournalEntries"" WHERE ""Id"" = {0} AND ""CompanyId"" = {1} FOR UPDATE", jv.Id, companyId);
        await _db.Entry(jv).ReloadAsync();
        if (jv.DepositAppliedToDocumentId.HasValue)
        {
            if (jv.DepositAppliedToDocumentId.Value != invoiceId)
                throw new InvalidOperationException($"JV {journalEntryNumber} ถูกนำไปตัดชำระเอกสารอื่นแล้ว");
            // == invoiceId: หักเข้าใบนี้ไปแล้ว. JV เป็น one-shot เต็มจำนวน (ไม่มี
            // partial/remaining tracking แบบมัดจำเอกสารที่มี DepositRealizedAmount)
            // → apply ซ้ำใบเดิม = โพสต์ Dr 21510/Cr ลูกหนี้ ซ้ำเต็มจำนวน (root cause
            // ที่เห็น Dr 21510 เกิน + Cr ลูกหนี้ค้าง). บล็อก idempotent
            throw new InvalidOperationException(
                $"JV {journalEntryNumber} ถูกนำมาตัดชำระใบ {invoice.DocumentNumber} แล้ว — หักซ้ำไม่ได้ " +
                "(ถ้าต้องแก้ยอด ให้ยกเลิก/ลบใบนี้แล้วสร้างใหม่)");
        }

        var acctIds = jv.Lines.Where(l => !l.IsDeleted).Select(l => l.AccountId).Distinct().ToList();
        var codes = await _db.ChartOfAccounts.AsNoTracking()
            .Where(a => a.CompanyId == companyId && acctIds.Contains(a.Id))
            .Select(a => new { a.Id, a.AccountCode }).ToListAsync();
        string CodeOf(Guid id) => codes.FirstOrDefault(a => a.Id == id)?.AccountCode ?? "";

        var defLine = jv.Lines.Where(l => !l.IsDeleted
                && (CodeOf(l.AccountId).StartsWith("217") || CodeOf(l.AccountId).StartsWith("215")))
            .GroupBy(l => l.AccountId)
            .Select(g => new { AccountId = g.Key, Net = g.Sum(x => x.CreditAmount - x.DebitAmount) })
            .Where(x => x.Net > 0.005m).OrderByDescending(x => x.Net).FirstOrDefault();
        if (defLine == null)
            throw new InvalidOperationException(
                $"JV {journalEntryNumber} ไม่มีขาเครดิตบัญชีมัดจำ/รับล่วงหน้า (215xx/217xx) — ไม่ใช่ JV มัดจำ");
        var vat13Line = jv.Lines.Where(l => !l.IsDeleted && CodeOf(l.AccountId) == "21913")
            .GroupBy(l => l.AccountId).Select(g => new { AccountId = g.Key, Net = g.Sum(x => x.CreditAmount - x.DebitAmount) })
            .FirstOrDefault(x => x.Net > 0.005m);
        var vat11Line = jv.Lines.Where(l => !l.IsDeleted && CodeOf(l.AccountId) == "21911")
            .GroupBy(l => l.AccountId).Select(g => new { AccountId = g.Key, Net = g.Sum(x => x.CreditAmount - x.DebitAmount) })
            .FirstOrDefault(x => x.Net > 0.005m);
        var vatLine = vat13Line ?? vat11Line;

        var deferredNet = defLine.Net;
        var vatNet = vatLine?.Net ?? 0m;
        var gross = deferredNet + vatNet;
        if (gross <= 0.005m)
            throw new InvalidOperationException($"JV {journalEntryNumber} ไม่มียอดมัดจำคงเหลือ");
        if (gross > invoice.BalanceDue + 0.01m)
            throw new InvalidOperationException(
                $"ยอดมัดจำใน JV ({gross:N2}) มากกว่ายอดคงค้างของใบ ({invoice.BalanceDue:N2}) — " +
                "รุ่นแรกรองรับหักเต็ม JV เท่านั้น เลือกใบที่ยอดมากพอ หรือหักบางส่วนผ่านมัดจำเอกสาร");

        var arAcc = await FindAccountAsync(companyId, "113", invoice.Contact)
            ?? throw new InvalidOperationException("ไม่พบบัญชีลูกหนี้การค้า (113)");

        // วันที่ลง JE ตัดชำระ — ควรตรงวันที่เอกสารปลายทาง (VAT ตกเดือนภาษีเดียว
        // กับ tax point ของใบ §78); เดิม hardcode UtcNow → backdate ใบข้ามเดือน
        // แล้ว VAT recognition หลุดไปเดือนปัจจุบัน
        var when = applyDate ?? DateTime.UtcNow;
        var apply = new JournalEntry
        {
            CompanyId = companyId,
            EntryNumber = await GetNextJournalEntryNumberAsync(companyId, "JV"),
            EntryDate = when, JournalType = JournalType.General,
            Description = $"นำมัดจำ (JV {jv.EntryNumber}) ตัดชำระ {invoice.DocumentNumber}",
            Reference = invoice.DocumentNumber, Status = JournalEntryStatus.Posted,
            TotalDebit = gross, TotalCredit = gross, CreatedBy = actor, IsAutoGenerated = true,
            FiscalPeriodId = (await RequireOpenFiscalPeriodAsync(companyId, when, "รายการนำมัดจำตัดชำระ"))?.Id, ProjectId = invoice.ProjectId,
        };
        _db.JournalEntries.Add(apply);
        var ln = 1;
        _db.JournalEntryLines.Add(new JournalEntryLine { JournalEntryId = apply.Id, AccountId = defLine.AccountId,
            DebitAmount = deferredNet, CreditAmount = 0, Description = $"ตัดขายรอรับรู้ (JV {jv.EntryNumber})", LineOrder = ln++ });
        if (vatNet > 0 && vatLine != null)
            _db.JournalEntryLines.Add(new JournalEntryLine { JournalEntryId = apply.Id, AccountId = vatLine.AccountId,
                DebitAmount = vatNet, CreditAmount = 0,
                Description = vat13Line != null ? "ตัดภาษีขายรอเรียกเก็บ (มัดจำ→ใบกำกับ)" : "ล้าง VAT มัดจำ", LineOrder = ln++ });
        _db.JournalEntryLines.Add(new JournalEntryLine { JournalEntryId = apply.Id, AccountId = arAcc.Id,
            DebitAmount = 0, CreditAmount = gross, Description = $"ตัดลูกหนี้ด้วยมัดจำ (JV {jv.EntryNumber})", LineOrder = ln++ });

        jv.DepositAppliedToDocumentId = invoiceId;   // one-shot

        invoice.PaidAmount += gross;
        var jvSettle = Accounting.Helpers.DocumentSettlementState.Apply(
            invoice.TotalAmount, invoice.PaidAmount, invoice.Status);
        invoice.BalanceDue = jvSettle.BalanceDue;
        invoice.Status = jvSettle.Status;
        invoice.DepositAppliedAmount += gross;
        invoice.DepositAppliedRef = MergeDepositRef(invoice.DepositAppliedRef, jv.EntryNumber);

        // ── tax point §78/1: หักมัดจำ = "ได้รับชำระ" เช่นกัน (S-1) ────────────
        // ใบแจ้งหนี้บริการที่ VAT พักไว้ 21913 ถ้าปิดยอดด้วยมัดจำ (ไม่ผ่าน
        // CreatePaymentAsync) จะไม่มีใครย้าย VAT → 21911 ⇒ ใบหายจาก ภ.พ.30
        // ถาวรทั้งที่รับเงินครบแล้ว (นำส่งภาษีขายขาด). hook นี้ idempotent
        // ด้วย OutputVatDueAt และเป็น best-effort (ไม่ทำให้การหักมัดจำพัง)
        await TryReclassifyUndueOutputVatAsync(companyId, invoiceId, DateTime.UtcNow.Date, actor);

        await _db.SaveChangesAsync();

        // S-2 (เส้น JV): เหมือนหักมัดจำจากเอกสาร — ปิดยอดครบแล้วลูกหนี้ใน GL
        // ยังค้างเท่ายอด WHT เพราะตั้งไว้ gross ตามเกณฑ์เงินสด
        if (invoice.BalanceDue <= 0.005m && invoice.WithholdingTaxAmount > 0.005m)
            await TryRecognizeSalesWhtOnSettlementAsync(companyId, invoice, when, actor);

        var updated = await GetDocumentAsync(companyId, invoiceId);
        await FireWebhookAsync(companyId, "deposit.applied", updated);
        return updated;
    }

    public async Task<SuggestPvAccountingResponse> SuggestPaymentVoucherAccountingAsync(
        Guid companyId, SuggestPvAccountingRequest request, CancellationToken ct = default)
    {
        // AI ปิดอยู่/inject ไม่ได้ → คืนผลว่าง (เคารพ kill-switch กฎเหล็ก #1)
        if (_aiAugmenter == null || request.Lines.Count == 0)
            return new SuggestPvAccountingResponse(
                request.Lines.Select(l => new SuggestPvAccountingLineResult(
                    l.TempId, l.CurrentAccountCode, null,
                    Array.Empty<string>(), null, false, null)).ToList(),
                Array.Empty<string>(), UsedAi: false);

        // map tempId → temp Guid (augmenter signature ใช้ LineId เป็น Guid)
        var tempMap = request.Lines.ToDictionary(_ => Guid.NewGuid(), l => l);
        var lineInputs = tempMap.Select(kv =>
            (LineId: kv.Key, kv.Value.Description, kv.Value.Amount, kv.Value.CurrentAccountCode)
        ).ToList();

        var bulk = await _aiAugmenter.SuggestAllPaymentVoucherAccountingAsync(
            companyId,
            request.SourceInvoiceId ?? Guid.Empty,
            request.VendorName, request.VendorTaxId, request.VendorIndustry,
            lineInputs,
            string.IsNullOrWhiteSpace(request.Currency) ? "THB" : request.Currency,
            ct);

        // Validate ผังที่แนะนำว่ามีจริงในผังของบริษัท (anti-hallucination guard
        // ตามกฎเหล็ก #1) — ถ้าไม่มี ไม่ส่งกลับเป็น answer
        var allCodes = (await _db.ChartOfAccounts.AsNoTracking()
            .Where(a => a.CompanyId == companyId && a.IsActive && !a.IsDeleted)
            .Select(a => a.AccountCode).ToListAsync(ct)).ToHashSet();

        var results = tempMap.Select(kv =>
        {
            var line = kv.Value;
            if (!bulk.ByLineId.TryGetValue(kv.Key, out var sugg))
                return new SuggestPvAccountingLineResult(
                    line.TempId, line.CurrentAccountCode, null,
                    Array.Empty<string>(), null, false, null);
            var ans = !string.IsNullOrWhiteSpace(sugg.Answer) && allCodes.Contains(sugg.Answer!)
                ? sugg.Answer
                : line.CurrentAccountCode;
            return new SuggestPvAccountingLineResult(
                line.TempId, ans, sugg.Confidence,
                sugg.Alternatives, sugg.Reasoning, sugg.UsedAi, sugg.FeedbackId);
        }).ToList();

        return new SuggestPvAccountingResponse(results, bulk.CrossLineObservations, bulk.UsedAi);
    }

    public async Task<SupplierTaxInvoiceCheckResponse> CheckSupplierTaxInvoiceAsync(Guid companyId, Guid? contactId,
        string? supplierBranchCode, string? supplierInvoiceNumber, DateTime? supplierTaxInvoiceDate)
    {
        // ผู้ติดต่ออ่านจาก**ฐานข้อมูล** (แหล่งเดียวกับที่ตัวลงบัญชีใช้ตอนอนุมัติ) ไม่ใช่จากช่อง
        // บนหน้าจอ — ช่องบนจออาจมาจากสแกน/แคช/ค่าค้างของใบก่อน (รอบ 190 ทีม C ข้อ 3)
        Contact? contact = null;
        if (contactId is Guid cid)
            contact = await _db.Contacts.AsNoTracking()
                .FirstOrDefaultAsync(c => c.Id == cid && c.CompanyId == companyId && !c.IsDeleted);

        // สาขาที่จะถูกบันทึก: ลำดับเดียวกับ CreateDocumentAsync (ช่องบนฟอร์ม → ผู้ติดต่อ → 00000)
        var typedBranch = string.IsNullOrWhiteSpace(supplierBranchCode) ? null : supplierBranchCode.Trim();
        string? branchError = null;
        if (typedBranch != null
            && !Accounting.Helpers.TaxBranchCode.TryNormalize(typedBranch, out _, out branchError))
        { /* branchError ถูกตั้งแล้ว — แสดงคู่กับผลตรวจ ไม่ใช่ throw (ผู้ใช้กำลังพิมพ์) */ }
        var effectiveBranch = typedBranch ?? contact?.BranchCode ?? Accounting.Helpers.TaxBranchCode.HeadOffice;

        var probe = new Document
        {
            CompanyId = companyId,
            ContactId = contact?.Id ?? Guid.Empty,
            HasTaxInvoiceReference = true,
            SupplierBranchCode = effectiveBranch,
            SupplierInvoiceNumber = string.IsNullOrWhiteSpace(supplierInvoiceNumber) ? null : supplierInvoiceNumber.Trim(),
            SupplierTaxInvoiceDate = supplierTaxInvoiceDate,
        };
        var result = TaxInvoiceCompletenessChecker.Evaluate(probe, contact);
        // ยังไม่ได้เลือกผู้ติดต่อ: บอกเรื่องเดียวที่ต้องทำก่อน (ไม่ไล่ชื่อ/เลข/ที่อยู่ผู้ขายทีละช่อง)
        var missing = contact != null
            ? result.MissingFields.ToList()
            : new[] { "ผู้ติดต่อ (ผู้ขาย) — ยังไม่ได้เลือก" }
                .Concat(result.MissingFields.Except(result.MissingContactFields)).ToList();

        return new SupplierTaxInvoiceCheckResponse(
            IsClaimable: result.IsClaimable && contact != null,
            MissingFields: missing,
            MissingContactFields: contact != null ? result.MissingContactFields.ToList() : new List<string>(),
            ContactTaxId: contact?.TaxId,
            ContactBranchCode: contact?.BranchCode,
            EffectiveBranchCode: effectiveBranch,
            EffectiveBranchLabel: Accounting.Helpers.TaxBranchCode.Label(effectiveBranch),
            BranchCodeError: branchError);
    }

    public async Task<List<UndueInputVatSummary>> GetUndueInputVatAsync(Guid companyId)
    {
        // เอกสารที่ VAT ค้าง 11640 รอใบกำกับครบ (ยังไม่ reclassify)
        var rows = await _db.Documents
            .Include(d => d.Lines)
            .Where(d => d.CompanyId == companyId
                && d.InputVatPostedAsUndue
                && d.InputVatBecameClaimableAt == null
                && d.InputVatExpiredAt == null
                && d.Status != DocumentStatus.Draft && d.Status != DocumentStatus.Voided)
            .OrderBy(d => d.DocumentDate)
            .ToListAsync();
        await _db.HydrateContactsAsync(companyId, rows);  // กัน INNER JOIN ตัดใบที่ contact ถูกลบ

        var today = DateTime.UtcNow.Date;
        return rows.Select(d =>
        {
            // §82/3: เคลมได้ภายใน 6 เดือนนับจากเดือนของใบกำกับ (ใช้ SupplierTaxInvoiceDate
            // ถ้ามี ไม่งั้น DocumentDate). หมดสิทธิเมื่อพ้นสิ้นเดือนที่ 6.
            var baseDate = d.SupplierTaxInvoiceDate ?? d.DocumentDate;
            var windowEnd = new DateTime(baseDate.Year, baseDate.Month, 1).AddMonths(7).AddDays(-1);
            var isExpired = today > windowEnd;
            var monthsLeft = ((windowEnd.Year - today.Year) * 12 + windowEnd.Month - today.Month);
            if (monthsLeft < 0) monthsLeft = 0;
            var completeness = TaxInvoiceCompletenessChecker.Evaluate(d, d.Contact);
            // ⚠️ ต้องแปลงเป็นเงินบาทด้วย `ToGlAmount` — บรรทัดเอกสารเก็บยอดใน
            // **สกุลของเอกสาร** ส่วน GL/ผัง 11640 เก็บเป็นบาท (`:11787` ของเส้นย้าย
            // 11640→11610 แปลงอยู่แล้ว) ⇒ เดิมหน้านี้รวมยอดดิบ: ใบซื้อ USD ที่ FX 36
            // โชว์ "VAT รอเคลม 70" ทั้งที่ GL ถือ 2,520 บาท — เงียบสนิทเพราะเลขที่ได้
            // ก็เป็นจำนวนเงินที่ดูปกติ
            var vat = ToGlAmount(d, d.Lines.Where(l => l.IsVatClaimable).Sum(l => l.VatAmount));
            // ใบ ภ.พ.36: "ขาดข้อมูล" ตาม checklist §86/4 ไม่มีความหมาย (ผู้ขาย
            // ตปท. ไม่มีเลขภาษีไทย/ใบกำกับไทยให้เติม) — ทางออกจริงคือวงจรนำส่ง
            return new UndueInputVatSummary(
                d.Id, d.DocumentNumber, d.DocumentDate,
                d.Contact?.Name ?? "", d.Contact?.TaxId,
                vat,
                (int)(today - d.DocumentDate.Date).TotalDays,
                monthsLeft, isExpired,
                d.IsForeignService
                    ? new[] { "นำส่ง ภ.พ.36 แล้วกด \"รับรู้ภาษีซื้อ\" ที่หน้านำส่งภาษี (§77/2)" }
                    : completeness.MissingFields,
                d.IsForeignService);
        }).ToList();
    }

    public Task<DocumentResponse> ApproveDocumentAsync(Guid companyId, Guid documentId, string approvedBy)
        => ApproveDocumentAsync(companyId, documentId, approvedBy, acknowledgeWarnings: false);

    public async Task<DocumentResponse> ApproveDocumentAsync(Guid companyId, Guid documentId, string approvedBy, bool acknowledgeWarnings)
    {
        var doc = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");
        await _db.HydrateContactAsync(companyId, doc);  // กัน INNER JOIN ตัดใบที่ contact ถูกลบ

        if (doc.Status != DocumentStatus.Draft && doc.Status != DocumentStatus.WaitingApproval)
            throw new InvalidOperationException("อนุมัติได้เฉพาะเอกสาร Draft หรือ WaitingApproval เท่านั้น");

        await EnsureCashSaleStockPolicyAllowsAsync(companyId, doc);   // นโยบาย Block (ERP_REVIEW A-06) — ก่อนออกเลข

        // ── ซ่อมบรรทัดที่เก็บ "ยอดรวม VAT" ลง Amount (ผิด convention) ─────────
        // เอกสารที่ OCR สร้างไว้ก่อน 2026-08-14 เก็บ Line.Amount เป็นยอดรวม VAT
        // ⇒ JE ลง Dr ค่าใช้จ่าย(รวม VAT) + Dr ภาษีซื้อ(VAT ซ้ำ) = เดบิตเกินเครดิต
        // เท่ายอด VAT พอดี ⇒ อนุมัติไม่ได้ตลอดกาล และผู้ใช้ไม่มีทางรู้ว่าต้องทำอะไร
        // ต้นทางแก้แล้ว แต่แถวเก่าไม่มีใครซ่อม → ซ่อมตรงนี้ตอนหยิบมาใช้จริง
        // (เงื่อนไขแคบมาก + idempotent ดู DocumentLineVatConvention; ยอดหัวเอกสาร
        // SubTotal/VatAmount/TotalAmount ไม่ขยับ — เปลี่ยนแค่ส่วนแบ่งในบรรทัด)
        if (doc.Lines is { Count: > 0 } && DocumentLineVatConvention.LinesStoredGross(
                doc.PricesIncludeVat, doc.SubTotal, doc.VatAmount,
                doc.Lines.Where(l => !l.IsDeleted).Sum(l => l.Amount),
                doc.Lines.Where(l => !l.IsDeleted).Sum(l => l.VatAmount)))
        {
            foreach (var l in doc.Lines.Where(l => !l.IsDeleted))
                l.Amount = DocumentLineVatConvention.RepairedAmount(l.Amount, l.VatAmount);
            await _db.SaveChangesAsync();
            _logger.LogWarning(
                "ซ่อมยอดรายบรรทัดของเอกสาร {DocumentId} ({Number}): Line.Amount เคยเก็บยอดรวม VAT "
                + "→ หัก VAT ออกให้เป็นยอดก่อน VAT (SubTotal {SubTotal:N2} + VAT {Vat:N2} = {Total:N2} เท่าเดิม)",
                doc.Id, doc.DocumentNumber, doc.SubTotal, doc.VatAmount, doc.TotalAmount);
        }

        // Soft warnings — legal/correct but unusual patterns the operator
        // should eyeball before approving. Hard errors still throw below.
        // When AcknowledgeWarnings is false and warnings exist, throw a
        // typed exception the controller turns into a 422 with the list
        // so the UI can prompt for explicit confirmation.
        var warnings = await CollectApprovalWarningsAsync(companyId, doc);
        if (warnings.Count > 0 && !acknowledgeWarnings)
        {
            // Enrich each warning with an AI-suggested fix when augmenter
            // is wired AND online. Done in parallel with a short overall
            // budget (8s) so the approval dialog isn't laggy. Each call
            // falls back to local on its own — overall request still
            // throws the 422 regardless of whether AI ran.
            IReadOnlyList<DocumentApprovalAiHint>? hints = null;
            if (_aiAugmenter != null && warnings.Count > 0)
            {
                try
                {
                    using var aiCts = new CancellationTokenSource(TimeSpan.FromSeconds(8));
                    var snapshot = new
                    {
                        doc.Id, doc.DocumentNumber, doc.DocumentType, doc.DocumentDate,
                        doc.TotalAmount, doc.SubTotal, doc.VatAmount,
                        WhtAmount = doc.WithholdingTaxAmount,
                        doc.Currency, doc.BalanceDue, doc.ContactId,
                        ContactName = doc.Contact?.Name,
                        ContactTaxId = doc.Contact?.TaxId,
                        LineCount = doc.Lines?.Count ?? 0,
                    };
                    // Single BULK call covering every warning — AI can
                    // see "warning 1 + warning 2 share a root cause"
                    // patterns the previous per-warning fan-out missed.
                    // Cost drops from N× to 1×.
                    var bulk = await _aiAugmenter.SuggestApprovalWarningFixesBulkAsync(
                        companyId, doc.Id, warnings, snapshot, null, aiCts.Token);
                    // ⚠️ ห้ามเติม `?? "Acknowledge"` กลับมาอีก (ผลตรวจ D1-11):
                    // เมื่อ**ไม่มีใครตอบ** (provider ปิด/ล่ม + นักเรียนยังไม่มีคลัง)
                    // คำตอบต้องเดินทางถึงหน้าจอในสภาพ "ว่าง" ไม่ใช่ถูกแปลงเป็น
                    // คำแนะนำเขียว ๆ ที่ผู้ใช้กดยอมรับแล้วกลายเป็นแถว acceptedAi=true
                    // ⇒ นักเรียนเรียนจากคำพูดที่ตัวเองไม่เคยพูด
                    hints = bulk.Hints.Select(r => new DocumentApprovalAiHint(
                        Primary: Accounting.Helpers.AiHintAnswer.ForTransport(r.Answer),
                        Confidence: Accounting.Helpers.AiHintAnswer.ConfidenceFor(r.Answer, r.Confidence),
                        Reasoning: r.Reasoning,
                        SuggestedActions: r.SuggestedActions,
                        Risks: r.Risks,
                        ComplianceFlags: r.ComplianceFlags,
                        FeedbackId: Accounting.Helpers.AiHintAnswer.FeedbackIdFor(r.Answer, r.FeedbackId),
                        UsedAi: r.UsedAi)).ToList();
                }
                catch (Exception aiEx)
                {
                    // AI failure must not block the warning surfacing.
                    _logger.LogWarning(aiEx, "Approval-warning AI augmentation failed; surfacing raw warnings");
                }
            }
            throw new DocumentApprovalWarningsException(warnings, hints);
        }

        // ── ผู้ใช้กด "อนุมัติทั้งที่มีคำเตือน" — ต้องมีร่องรอย ──
        // เดิมคำเตือนที่ถูก acknowledge หายไปเฉย ๆ: ใบที่อนุมัติแบบ "รู้แล้วว่าผิด
        // §86 แต่ยืนยัน" หน้าตาเหมือนใบที่ไม่เคยมีคำเตือนเลย ⇒ ผู้สอบบัญชี/
        // สรรพากรถามว่า "ทำไมออกใบแจ้งหนี้ทั้งที่มีสินค้า" แล้วไม่มีอะไรตอบได้
        // ต้องดังทั้งบน **ตัวเอกสาร** (ผู้ใช้เปิดดูเห็น) และใน **audit** (hash chain)
        if (warnings.Count > 0 && acknowledgeWarnings)
        {
            // ⚠️ ต้องลง **InternalNotes** ไม่ใช่ Notes — Notes ถูกพิมพ์ลงกระดาษ
            // (PdfGenerationService.SanitizeNotesForPrint) ⇒ คำเตือนภายในจะไป
            // โผล่บนใบที่ส่งให้ลูกค้า
            var ackNote = "— รับทราบคำเตือนตอนอนุมัติ —\n"
                + string.Join("\n", warnings.Select(w => "• " + w))
                + $"\n(ยืนยันโดย {approvedBy} เมื่อ "
                + $"{DateTime.UtcNow.AddHours(7).ToString("yyyy-MM-dd HH:mm", System.Globalization.CultureInfo.InvariantCulture)} น. เวลาไทย)";
            AppendInternalNote(doc, ackNote);

            _db.AuditLogs.Add(new AuditLog
            {
                CompanyId = companyId,
                Action = AuditAction.Update,
                EntityType = "Document",
                EntityId = doc.Id.ToString(),
                NewValues = System.Text.Json.JsonSerializer.Serialize(new
                {
                    action = "ApproveWithAcknowledgedWarnings",
                    documentNumber = doc.DocumentNumber,
                    documentType = doc.DocumentType.ToString(),
                    warnings,
                    by = approvedBy,
                    ruleCode = "APPROVE-ACK-WARNINGS",
                    legalReference = "RD-86 / RD-82/5(1)",
                }),
            });
        }

        // CreditNote must declare its reason — per ประมวลรัษฎากร §82/10 the
        // CN reason distinguishes whether goods physically returned (restocks)
        // from a pure financial adjustment (no stock impact). Without it the
        // stock cascade can't decide and the e-Tax label would be wrong.
        if (doc.DocumentType == DocumentType.CreditNote && doc.CreditNoteReason == null)
            throw new InvalidOperationException(
                "ใบลดหนี้ต้องระบุเหตุผล (คืนสินค้า / ส่วนลด / ปรับยอด / ตัดยอด) ก่อนอนุมัติ");

        // ใบเพิ่มหนี้ก็ต้องระบุสาเหตุเช่นกัน — §86/9 บังคับคู่ขนานกับ §86/10
        // ของใบลดหนี้ (เดิมมีแต่ฝั่ง CN ⇒ ใบเพิ่มหนี้ออกได้โดยไม่มีสาเหตุบนกระดาษ
        // = รายการไม่ครบตามกฎหมาย และผู้ซื้อใช้เป็นหลักฐานภาษีซื้อไม่ได้)
        if (doc.DocumentType == DocumentType.DebitNote && doc.DebitNoteReason == null)
            throw new InvalidOperationException(
                "ใบเพิ่มหนี้ต้องระบุเหตุผล (ราคาเพิ่มขึ้น / ส่งสินค้าเกิน / ค่าใช้จ่ายเพิ่มเติม / ปรับยอด) ก่อนอนุมัติ");

        // §86/9-10: CN/DN ที่มี VAT = เอกสารภาษี — กระดาษต้องระบุ เลขที่+วันที่
        // ใบกำกับภาษีเดิม (รายการบังคับตามกฎหมาย ไม่ใช่ optional). ไม่มีทั้ง ref
        // ในระบบและเลขใบเดิมในช่อง "อ้างอิง" = ใบไม่ครบรายการ + ภ.พ.30 ตรวจย้อน
        // ไม่ได้ → hard block. ใบเดิมอยู่นอกระบบ (ก่อน migrate) กรอกเลขที่ช่อง
        // อ้างอิงแทนได้ (กล่องมูลค่าเดิมบนกระดาษจะไม่มี — ผู้ใช้แนบใบเดิมเอง)
        if (doc.DocumentType is DocumentType.CreditNote or DocumentType.DebitNote
            && doc.VatAmount > 0.005m
            && doc.RelatedDocumentId == null
            && string.IsNullOrWhiteSpace(doc.Reference))
            throw new InvalidOperationException(
                (doc.DocumentType == DocumentType.CreditNote ? "ใบลดหนี้" : "ใบเพิ่มหนี้")
                + "ที่มี VAT ต้องอ้างอิงใบกำกับภาษีเดิม (§86/9-10) — เลือกเอกสารต้นทางในระบบ"
                + " หรือกรอกเลขที่ใบกำกับเดิมในช่อง \"อ้างอิง\" (กรณีใบเดิมออกนอกระบบ/ก่อนย้ายข้อมูล)");

        // ===== §90/2 — บริษัทไม่จดทะเบียน VAT ห้ามออกใบกำกับภาษี/เรียกเก็บ =====
        // VAT ขาย (hard block — เดิมเป็นแค่ warning กด acknowledge ผ่านได้).
        // สถานะจาก CompanyVatStatus ตัวเดียว: มีแถวค่าตั้ง = ธงค่าตั้ง (เดิม) · ไม่มีแถว = ธงบริษัท
        // (เดิม `?? true` ⇒ บริษัทที่สร้างโดยไม่ติ๊ก "จด VAT" แต่ยังไม่มีแถวค่าตั้ง ผ่านด่านนี้ได้ · S-01).
        // CN/DN ฝั่งซื้อ (supplier ออกให้เรา — related doc เป็น PI/Expense/GRN) ไม่ใช่การออกใบกำกับ
        // ของเรา → ไม่ block.
        var companyVatRegistered = await Accounting.Helpers.CompanyVatStatus.IsRegisteredAsync(_db, companyId);
        if (!companyVatRegistered)
        {
            var purchaseSideCnDn = false;
            if (doc.DocumentType is DocumentType.CreditNote or DocumentType.DebitNote
                && doc.RelatedDocumentId.HasValue)
            {
                var relType = await _db.Documents.AsNoTracking()
                    .Where(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId)
                    .Select(d => (DocumentType?)d.DocumentType)
                    .FirstOrDefaultAsync();
                purchaseSideCnDn = relType is DocumentType.PurchaseInvoice
                    or DocumentType.Expense or DocumentType.GoodsReceiptNote;
            }
            var isSalesVatIssuance = doc.DocumentType == DocumentType.TaxInvoice
                || (doc.VatAmount > 0 && !purchaseSideCnDn
                    && doc.DocumentType is DocumentType.Invoice or DocumentType.Receipt
                        or DocumentType.ReceiptVoucher or DocumentType.BillingNote
                        or DocumentType.CreditNote or DocumentType.DebitNote);
            if (isSalesVatIssuance)
                throw new InvalidOperationException(
                    "⛔ บริษัทยังไม่ได้จดทะเบียนภาษีมูลค่าเพิ่ม — ออกใบกำกับภาษี/เรียกเก็บ VAT ขายไม่ได้ (§90/2). " +
                    "ถ้าจดทะเบียนแล้ว เปิด \"จดทะเบียนภาษีมูลค่าเพิ่ม\" ในหน้าตั้งค่าระบบบัญชี; " +
                    "ถ้ายังไม่จด ให้ตั้ง VAT = 0 และใช้ใบแจ้งหนี้/ใบเสร็จแทนใบกำกับภาษี");
        }

        // 🛡️ ภาษีซื้อ (input VAT / ภ.พ.30) — ใบที่ "ขอเครดิตภาษีซื้อ"
        // (HasTaxInvoiceReference) ต้องอ้างใบกำกับภาษีเต็มรูปของผู้ขายที่ระบุ
        // "เลขผู้เสียภาษีผู้ขาย 13 หลัก" (§86/4); ขาด/ไม่ถูกต้อง = เคลมภาษีซื้อไม่ได้
        // (§82/5(1)(5)). ระบบเคลมด้วยเลขภาษีของ Contact ผู้ขายจริง จึงบังคับให้
        // Contact มีเลขภาษี 13 หลักก่อนอนุมัติ — **hard block ไม่มี acknowledge bypass**
        // (ห้ามปล่อยผ่าน: เคลมภาษีซื้อผิด/ไม่มีใบกำกับ = ลูกค้าโดนสรรพากรประเมินคืน+เบี้ยปรับ)
        if (doc.HasTaxInvoiceReference == true && doc.VatAmount > 0 && doc.Contact != null)
        {
            var supTid = new string((doc.Contact.TaxId ?? "").Where(char.IsDigit).ToArray());
            if (supTid.Length != 13)
                throw new InvalidOperationException(
                    $"ผู้ขาย \"{doc.Contact.Name}\" ยังไม่มีเลขผู้เสียภาษี 13 หลัก — ขอเครดิตภาษีซื้อ (ภ.พ.30) " +
                    "ไม่ได้ตาม §86/4/§82/5 กรุณาเพิ่มเลขผู้เสียภาษีของผู้ขายในข้อมูลผู้ติดต่อก่อน " +
                    "หรือเอาการติ๊ก \"ขอเครดิตภาษีซื้อ\" ออก (บันทึกเป็นค่าใช้จ่ายที่เคลม VAT ไม่ได้)");
        }

        // §86/4 hard-block (opt-in via CompanySettings.EnforceFullTaxInvoiceFields).
        // เมื่อบริษัทเปิด flag นี้ → block approval ของใบกำกับ/ใบเสร็จ/CN/DN
        // ที่ขาด field บังคับ (BuyerTaxId 13 หลัก + BuyerAddress + BuyerBranchCode 5 หลัก).
        // กัน operator-error: ตอนนี้ระบบเตือนแล้ว user กด acknowledge ผ่านได้ →
        // ใบกำกับที่ไม่ครบ §86/4 หลุดเข้า GL → ลูกค้ารับใบไปใช้ภาษีซื้อไม่ได้.
        var rd864Types = new[] { DocumentType.TaxInvoice, DocumentType.Receipt,
            DocumentType.DebitNote, DocumentType.CreditNote };
        // default = บังคับ (เดิม opt-in default off → ใบกำกับไม่ครบหลุดเข้า GL).
        var enforce864 = await _db.CompanySettings.AsNoTracking()
            .Where(c => c.CompanyId == companyId && !c.IsDeleted)
            .Select(c => (bool?)c.EnforceFullTaxInvoiceFields)
            .FirstOrDefaultAsync() ?? true;
        // ใบกำกับภาษี (TaxInvoice) เป็นเอกสาร §86/4 ตามกฎหมาย → บังคับ field ผู้ซื้อ
        // เสมอ ไม่ว่า flag. **ใบเสร็จ/ใบสำคัญรับที่เก็บ VAT จริง (ไม่ใช่มัดจำพักรอ)
        // ก็เป็นใบกำกับภาษีโดยสภาพเช่นกัน** → บังคับเสมอไม่ขึ้นกับ opt-in flag ด้วย:
        // กันเคสหัวเอกสารขัดกับเนื้อ (โชว์ VAT 7% แต่หัวไม่ขึ้น "ใบกำกับภาษี" เพราะ
        // ข้อมูลผู้ซื้อไม่ครบ). ถ้าผู้ซื้อครบ → หัว upgrade เป็นใบกำกับ/ใบเสร็จ; ถ้า
        // ไม่ครบ (นิติบุคคล) → block ให้เติมข้อมูล หรือติ๊กไม่ประสงค์ใบกำกับ (→ ใบเสร็จล้วน).
        // opt-out ผ่าน flag ยังใช้กับ CN/DN. ใบที่ไม่ครบ = ลูกค้าเคลมภาษีซื้อไม่ได้.
        var vatBearingReceipt = doc.DocumentType is DocumentType.Receipt or DocumentType.ReceiptVoucher
            && doc.VatAmount > 0;
        var mustEnforce864 = doc.DocumentType == DocumentType.TaxInvoice
            || vatBearingReceipt
            || (enforce864 && rd864Types.Contains(doc.DocumentType));
        // ── §83/6: ติ๊ก "บริการต่างประเทศ ภ.พ.36" แต่ VAT = 0 ──
        // self-assess VAT คือหัวใจของ ภ.พ.36 — VAT 0 = ใบนี้ไม่เข้า dashboard
        // นำส่ง ไม่มีอะไรให้รับรู้ ไม่มีภาษีซื้อเข้า ภ.พ.30 = หายทั้งวงจรเงียบ ๆ
        // (ฟอร์มตั้ง 7% ให้ตอนติ๊กแล้ว แต่ API/integration ยังยิงข้ามฟอร์มได้)
        // block พร้อมทางแก้สองทาง — ผู้ใช้ไม่ตัน
        if (doc.IsForeignService && doc.VatAmount <= 0)
            throw new InvalidOperationException(
                "ใบนี้ติ๊ก \"บริการต่างประเทศ (§83/6)\" แต่ไม่มี VAT — ภ.พ.36 ต้องประเมิน "
                + "VAT 7% จากยอดจ่ายเสมอ (ผู้ขายต่างประเทศไม่คิด VAT มา เราประเมินเองเพื่อนำส่ง). "
                + "ตั้ง VAT 7% ที่บรรทัดรายการ หรือถ้าไม่ใช่บริการต่างประเทศจริง เอาติ๊กออก");

        // §83/6: ฐาน ภ.พ.36 = ยอดที่จ่ายจริง (ไม่มี VAT ไทยปน) → โหมด "ราคารวม
        // ภาษี" ใช้กับใบต่างประเทศไม่ได้ — มันถอด 7/107 ออกจากยอดจ่าย ⇒ ฐานหด
        // นำส่งขาด (จ่าย 11,009.25 → นำส่ง 720.23 แทน 770.65) + เจ้าหนี้ผู้ขาย
        // ตั้งขาดเท่า VAT. ฟอร์มล็อกให้แล้ว guard นี้กันทางเข้าอื่น (API/integration)
        if (doc.IsForeignService && doc.PricesIncludeVat)
            throw new InvalidOperationException(
                "ใบบริการต่างประเทศ (§83/6) ใช้โหมด \"ราคารวมภาษี\" ไม่ได้ — ยอดที่จ่ายให้"
                + "ผู้ขายต่างประเทศไม่มี VAT ไทยปนอยู่ ฐานภาษีคือยอดจ่ายเต็มจำนวน "
                + "แล้วประเมิน VAT 7% บวกทับ. ปลดติ๊ก \"ราคารวมภาษี\" แล้วกรอกยอดจ่ายจริง"
                + "เป็นราคาต่อหน่วยตรง ๆ");

        // ── ใบเสร็จ "ลอย" ที่มี VAT ทั้งที่ลูกค้ามีใบกำกับ/ใบแจ้งหนี้ค้างอยู่ ──
        //
        // ใบเสร็จ/ใบสำคัญรับที่ **ไม่ผูกใบต้นทาง** (RelatedDocumentId = null) ถูก
        // ตีความว่าเป็น "ขายสด standalone" ทุกที่ในระบบ ⇒
        //   • ภ.พ.30 นับ VAT ที่ใบนี้ (TaxService: `!doc.RelatedDocumentId.HasValue`)
        //     ทั้งที่ใบกำกับต้นทางนับไปแล้ว = **นำส่ง VAT ซ้ำ**
        //   • JE เดินเส้น standalone (Dr เงินสด / Cr รายได้ + Cr 21911) = รายได้
        //     เบิ้ล และ AR ของใบกำกับเดิมไม่ถูกล้าง
        // ทั้งสองอย่างเงียบสนิท — ยอดแต่ละใบ "ดูสมเหตุสมผล" ไม่มีใครเอาไปเทียบกัน
        //
        // เกิดง่ายมากในโหมดแยกใบ: ผู้ใช้ที่เคยชินกับโปรแกรมอื่นจะเปิดฟอร์ม "สร้าง
        // ใบเสร็จ" แล้วพิมพ์เองแทนที่จะกด "บันทึกชำระเงิน" บนใบกำกับ. เส้นทางที่
        // ถูกคือ payment/convert ซึ่งผูก RelatedDocumentId ให้อัตโนมัติ
        //
        // block ที่ approve (ไม่ใช่ตอนสร้าง) — ร่างยังลองผิดลองถูกได้ และข้อความ
        // ต้องบอก **เลขใบที่ควรผูก** ไม่ใช่แค่ปฏิเสธ (ห้ามให้ผู้ใช้ตัน)
        if (doc.DocumentType is DocumentType.Receipt or DocumentType.ReceiptVoucher
            && doc.VatAmount > 0 && !doc.RelatedDocumentId.HasValue
            // ⚠️ Document.ContactId เป็น Guid (ไม่ใช่ Guid?) — "ไม่มีคู่ค้า"
            // แทนด้วย Guid.Empty ไม่ใช่ null
            && !doc.IsDeposit && doc.ContactId != Guid.Empty)
        {
            var openBills = await _db.Documents.AsNoTracking()
                .Where(d => d.CompanyId == companyId && !d.IsDeleted
                    && d.ContactId == doc.ContactId
                    && (d.DocumentType == DocumentType.TaxInvoice
                        || d.DocumentType == DocumentType.Invoice
                        || d.DocumentType == DocumentType.DebitNote)
                    && d.BalanceDue > 0.01m
                    && d.Status != DocumentStatus.Draft && d.Status != DocumentStatus.Voided
                    && d.Status != DocumentStatus.Rejected)
                .OrderBy(d => d.DocumentDate)
                .Select(d => d.DocumentNumber)
                .Take(5)
                .ToListAsync();
            if (openBills.Count > 0)
                throw new InvalidOperationException(
                    $"ใบนี้เป็นใบเสร็จที่มี VAT แต่ไม่ได้ผูกกับใบต้นทาง ขณะที่ลูกค้ารายนี้ยังมีใบค้างชำระอยู่ "
                    + $"({string.Join(", ", openBills)}) — อนุมัติแบบนี้ระบบจะนับ VAT ขายซ้ำใน ภ.พ.30 "
                    + "และบันทึกรายได้เบิ้ล. วิธีที่ถูก: เปิดใบค้างชำระใบนั้นแล้วกด \"💰 บันทึกชำระเงิน\" "
                    + "(ระบบออกใบเสร็จผูกให้อัตโนมัติ) หรือถ้าตั้งใจออกใบเสร็จใบนี้จริง ให้เลือก "
                    + "\"ใบต้นทาง\" ในฟอร์มก่อนอนุมัติ");
        }

                // ยกเว้นลูกค้าเงินสด "ไม่ประสงค์รับใบกำกับภาษี" — ประกาศอธิบดีฯ ฉบับ 199
        // บังคับเลขผู้เสียภาษี/สาขาผู้ซื้อเฉพาะเมื่อผู้ซื้อเป็นผู้ประกอบการจด VAT;
        // ผู้ซื้อบุคคลธรรมดาที่ไม่แจ้งข้อมูล → ออกใบกำกับได้ (เคลมภาษีซื้อไม่ได้เอง)
        // VAT ขายยังลงรายงาน/นำส่ง ภ.พ.30 ครบตามปกติ
        // มัดจำที่ VAT ยังพักรอ (21913) ยังไม่ใช่ใบกำกับภาษี → ไม่บังคับ field
        // ผู้ซื้อ §86/4 (ใบกำกับจริงออกตอนใช้บริการ/ชำระครบ ค่อยบังคับ)
        var isDeferredVatDeposit = doc.IsDeposit && doc.DepositOutputVatDeferred
            && doc.DocumentType is DocumentType.Receipt or DocumentType.ReceiptVoucher;
        if (mustEnforce864 && doc.VatAmount > 0 && doc.Contact != null
            && !doc.Contact.IsWalkInCustomer && !isDeferredVatDeposit
            && !doc.BuyerDeclinedTaxInvoice)
        {
            // เกณฑ์กลาง (แหล่งเดียวกับที่ PdfGenerationService ใช้ตัดสินหัวเอกสาร
            // — เดิมเป็นโค้ดคนละชุดจึง drift ได้): §86/4(3) บังคับแค่ชื่อ+ที่อยู่
            // ผู้ซื้อ; เลขภาษี + สาขา บังคับเฉพาะผู้ซื้อที่เป็นผู้ประกอบการจด
            // ทะเบียน (ประกาศอธิบดีฯ 194/199) — บุคคลธรรมดาที่ให้ชื่อ+ที่อยู่ครบ
            // **ออกใบกำกับภาษีเต็มรูปให้ได้** ไม่ต้อง downgrade เป็นใบเสร็จ
            var missing = Tax.TaxInvoiceCompletenessChecker
                .MissingBuyerFields(doc.Contact).ToList();
            var isJuristicBuyer = Tax.TaxInvoiceCompletenessChecker.IsJuristicBuyer(doc.Contact);
            if (missing.Count > 0)
            {
                // หลักบัญชี: "เอกสารที่ §86/4 ไม่ครบ = ไม่ใช่ใบกำกับภาษีเต็มรูป จึง
                // ไม่ควรมีหัวว่า 'ใบกำกับภาษี'" — แต่การจัดการต่างกันตามชนิดผู้ซื้อ:
                //
                //  • ผู้ซื้อ "นิติบุคคล" (จด VAT) → ตั้งใจจะเอาไปเคลมภาษีซื้อ การ
                //    downgrade เป็นใบเสร็จเงียบ ๆ จะทำให้ผู้ซื้อเสียสิทธิเคลม →
                //    block + ชี้ทางออกชัดเจน (เติมข้อมูล หรือ ติ๊กไม่ประสงค์รับ)
                //    ผู้ใช้ไม่ตัน มีทางไปต่อเสมอ
                //  • ผู้ซื้อ "บุคคลธรรมดา/ไม่มีเลขภาษี" (ขายปลีก) → ไม่ต้องใช้ใบกำกับ
                //    เต็มรูปอยู่แล้ว → ไม่ block. หัวเอกสารเปลี่ยนเป็น "ใบเสร็จรับเงิน/
                //    ใบกำกับภาษีอย่างย่อ" (§86/6) เองอยู่แล้วโดย**ไม่ต้องประทับธง**
                //    VAT ขายยังลง ภ.พ.30 ครบ (ภาระภาษีไม่ขึ้นกับหัวเอกสาร)
                //    ผู้ซื้อเคลมภาษีซื้อไม่ได้ §82/5(2)
                //
                // ⚠️ **ห้ามเขียน `doc.BuyerDeclinedTaxInvoice = true` กลับมาอีก**
                // (คำตัดสินรอบ 181): ธงนั้นแปลว่า "**ผู้ซื้อ**แจ้งว่าไม่ประสงค์รับ
                // ใบกำกับ" = เจตนาของมนุษย์ ระบบแต่งขึ้นแทนไม่ได้ — และเมื่อ persist
                // แล้วมันจะถูก clone ต่อไปเอกสารลูก + โผล่ในข้อความ e-Tax ราวกับ
                // ลูกค้าเคยปฏิเสธจริง. ผู้อ่านธงนี้ทุกตัวตรวจ "ผู้ซื้อ §86/4 ไม่ครบ"
                // ด้วยตัวเองอยู่แล้ว (PdfGenerationService `buyerDeclined` /
                // `IsAbbreviatedTaxInvoiceDoc` · TaxService `NotFullTaxInvoice`)
                // ⇒ หัวเอกสาร/รายงานภาษีเหมือนเดิมทุกใบ
                if (isJuristicBuyer)
                    throw new InvalidOperationException(
                        $"⛔ §86/4: ใบกำกับภาษีเต็มรูปต้องมี {string.Join(", ", missing)} " +
                        "(ผู้ซื้อนิติบุคคล). เติมข้อมูลผู้ซื้อให้ครบ หรือ ติ๊ก " +
                        "'☑ ผู้ซื้อไม่ประสงค์รับใบกำกับภาษี' เพื่อออกเป็น " +
                        "ใบเสร็จรับเงิน/ใบกำกับภาษีอย่างย่อ §86/6 " +
                        "(VAT ยังนำส่ง ภ.พ.30 ครบ — ผู้ซื้อเคลมภาษีซื้อไม่ได้ §82/5(2))");
            }
        }

        // Enforce CompanySettings.RequireApprovalForDocuments: เกินวงเงิน →
        // ห้ามอนุมัติตรง ต้องผ่าน flow ลายเซ็นหลายขั้นก่อน. เมื่อลายเซ็นครบ
        // SignatureApprovalService จะเรียกกลับเข้า method นี้ (pipeline เต็ม:
        // JE/สต๊อก/ออกเลข) — จึงยกเว้น block ให้เอกสารที่ "เซ็นครบทุกคนแล้ว"
        // มิฉะนั้น flow ที่ setting นี้บังคับใช้เองจะโดน block ตัวเอง (deadlock).
        var settings = await _db.CompanySettings.AsNoTracking()
            .FirstOrDefaultAsync(s => s.CompanyId == companyId);
        if (settings is { RequireApprovalForDocuments: true })
        {
            var threshold = settings.ApprovalThresholdAmount ?? 0m;
            if (doc.TotalAmount >= threshold)
            {
                var sigRows = await _db.Set<DocumentApproval>().AsNoTracking()
                    .Where(a => a.DocumentId == documentId && !a.IsDeleted)
                    .Select(a => a.Status)
                    .ToListAsync();
                var fullySigned = sigRows.Count > 0 && sigRows.All(s => s == ApprovalStatus.Approved);
                if (!fullySigned)
                    throw new InvalidOperationException(
                        $"เอกสารยอด {doc.TotalAmount:N2} บาท เกินวงเงินอนุมัติตรง ({threshold:N2}) — " +
                        "ส่งเข้ากระบวนการเซ็นอนุมัติหลายขั้นก่อน: เปิดเอกสาร → \"ส่งขออนุมัติ\" " +
                        "(ตั้งผู้เซ็นในเมนู ตั้งค่า & ผู้ใช้ → ลายเซ็นและอนุมัติ)");
            }
        }

        // ===== SoD (Segregation of Duties): maker ≠ checker =====
        // มาตรฐาน internal control ระดับ ERP — ผู้สร้างเอกสารห้ามอนุมัติ
        // เอกสารของตัวเอง (opt-in ผ่าน settings; default ปิดเพื่อไม่ block
        // เจ้าของกิจการคนเดียวที่ทำทุกหน้าที่)
        if (settings is { SodBlockSelfApproval: true }
            && !string.IsNullOrEmpty(doc.CreatedBy)
            && string.Equals(doc.CreatedBy, approvedBy, StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException(
                "SoD: ผู้สร้างเอกสารห้ามอนุมัติเอกสารของตัวเอง (การแบ่งแยกหน้าที่เปิดอยู่) — " +
                "ให้ผู้มีสิทธิ์อนุมัติคนอื่นเป็นผู้อนุมัติ");

        // ===== Commitment control: PO กันวงเงินงบประมาณ =====
        // actual (GL ปีนี้) + committed (PO เปิดค้าง) + ใบนี้ ต้องไม่เกิน
        // budget ต่อบัญชี — Block โยน error (override ได้ด้วย acknowledge),
        // Warn แค่ log
        if (doc.DocumentType == DocumentType.PurchaseOrder
            && settings?.BudgetCommitmentMode is "Warn" or "Block")
        {
            var overMsg = await CheckBudgetCommitmentAsync(companyId, doc);
            if (overMsg != null)
            {
                if (settings.BudgetCommitmentMode == "Block" && !acknowledgeWarnings)
                    throw new InvalidOperationException(
                        overMsg + " — หากยืนยันจะสั่งซื้อ กด \"อนุมัติพร้อม override\"");
                _logger.LogWarning("Budget commitment warning {DocNo}: {Msg}", doc.DocumentNumber, overMsg);
            }
        }

        var period = await _db.FiscalPeriods.FirstOrDefaultAsync(f =>
            f.CompanyId == companyId &&
            f.StartDate <= doc.DocumentDate &&
            f.EndDate >= doc.DocumentDate);
        if (period != null && period.Status != FiscalPeriodStatus.Open)
            throw new InvalidOperationException(
                $"ไม่สามารถอนุมัติเอกสารที่มีวันที่ในงวด {period.Name} ได้ เนื่องจากงวดดังกล่าวมีสถานะ {period.Status}");

        var strategy = _db.Database.CreateExecutionStrategy();
        await strategy.ExecuteAsync(async () =>
        {
            await using var transaction = await _db.Database.BeginTransactionAsync();
            try
            {
                // Pessimistic lock — two simultaneous Approve calls both saw
                // Status=Draft and hasExistingJournal=false before, so both
                // happily auto-posted, producing duplicate JEs and double-counting
                // revenue/expense. FOR UPDATE serialises them on the document row.
                await _db.Database.ExecuteSqlRawAsync(
                    "SELECT 1 FROM \"Documents\" WHERE \"Id\" = {0} AND \"CompanyId\" = {1} FOR UPDATE",
                    documentId, companyId);

                // Re-read status under the lock — the prior reader may have
                // already moved this Document past Draft.
                var lockedStatus = await _db.Documents
                    .Where(d => d.Id == documentId && d.CompanyId == companyId)
                    .Select(d => d.Status)
                    .FirstAsync();
                if (lockedStatus != DocumentStatus.Draft && lockedStatus != DocumentStatus.WaitingApproval)
                    throw new InvalidOperationException("เอกสารถูกอนุมัติไปแล้วโดยผู้ใช้งานคนอื่น กรุณารีเฟรชหน้านี้");

                // Multi-level approval gate. ถ้า ApprovalRule match doc นี้ →
                // ต้องผ่าน workflow ก่อน. user ที่ submit direct approve
                // โดยไม่ผ่าน workflow จะถูก block ที่นี่. Workflow service
                // เป็น opt-in (DI nullable) — ถ้าบริษัทไม่ได้ตั้งค่า approval
                // rule เลย FindMatchingRule คืน null → gate ปล่อยผ่าน.
                if (_approval != null)
                {
                    var matchingRule = await _approval.FindMatchingRuleAsync(
                        companyId, doc.DocumentType, doc.TotalAmount, doc.ProjectId);
                    if (matchingRule != null)
                    {
                        var gate = await _approval.CheckGateAsync(companyId, documentId);
                        if (!gate.CanApprove)
                            throw new InvalidOperationException(gate.BlockReason
                                ?? "เอกสารต้องผ่าน multi-level approval workflow ก่อน");
                    }
                }

                // F20 — 3-way match block over-bill. ถ้า PurchaseInvoice/
                // Expense อ้างถึง GRN (RelatedDocumentId) → ตรวจ qty/amount
                // ของแต่ละบรรทัด invoice ต้องไม่เกิน GRN ที่รับจริง. ป้องกัน
                // supplier ออกบิลเกินสินค้าที่ส่ง — ตรงกับมาตรฐาน 3-way match
                // (PO ↔ GRN ↔ PI). Linked via DocumentLine.SourceLineId.
                if ((doc.DocumentType == DocumentType.PurchaseInvoice || doc.DocumentType == DocumentType.Expense)
                    && doc.RelatedDocumentId.HasValue)
                {
                    var srcDoc = await _db.Documents.AsNoTracking()
                        .FirstOrDefaultAsync(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId);
                    if (srcDoc != null && srcDoc.DocumentType == DocumentType.GoodsReceiptNote)
                    {
                        var grnLines = await _db.DocumentLines.AsNoTracking()
                            .Where(l => l.DocumentId == srcDoc.Id)
                            .ToDictionaryAsync(l => l.Id, l => new { l.Quantity, l.Amount, l.Description });
                        var overBill = new List<string>();
                        foreach (var line in doc.Lines.Where(l => l.SourceLineId.HasValue))
                        {
                            if (!grnLines.TryGetValue(line.SourceLineId!.Value, out var grn)) continue;
                            // คำนวณยอด invoice อื่นๆ ที่อ้าง grn line นี้ไปแล้ว
                            var alreadyBilled = await _db.DocumentLines.AsNoTracking()
                                .Where(l => l.SourceLineId == line.SourceLineId.Value
                                            && l.DocumentId != doc.Id
                                            && !l.Document.IsDeleted
                                            && l.Document.Status != DocumentStatus.Voided
                                            && l.Document.Status != DocumentStatus.Draft
                                            && l.Document.Status != DocumentStatus.Rejected)
                                .Select(l => new { l.Quantity, l.Amount })
                                .ToListAsync();
                            var billedQty = alreadyBilled.Sum(b => b.Quantity);
                            var billedAmt = alreadyBilled.Sum(b => b.Amount);
                            if (line.Quantity + billedQty > grn.Quantity + 0.0001m)
                                overBill.Add($"\"{grn.Description}\": รับจริง {grn.Quantity:N2} บิลแล้ว {billedQty:N2} ใบนี้ {line.Quantity:N2} → เกิน");
                            if (line.Amount + billedAmt > grn.Amount + 0.01m)
                                overBill.Add($"\"{grn.Description}\": ยอด GRN {grn.Amount:N2} บิลแล้ว {billedAmt:N2} ใบนี้ {line.Amount:N2} → เกิน");
                        }
                        if (overBill.Count > 0 && !acknowledgeWarnings)
                            throw new InvalidOperationException(
                                "บิลเกินจำนวน/ยอด GRN ที่รับจริง (3-way match):\n• " + string.Join("\n• ", overBill)
                                + "\n\nกดรับทราบเพื่อบังคับอนุมัติ");
                    }
                }

                // Idempotency guard INSIDE transaction to prevent race condition.
                // นับเฉพาะ JE ที่ "ยังมีผลจริง": ไม่ใช่ reversal (OriginalEntryId
                // null) และยังไม่ถูกกลับรายการ (ReversedByEntryId null) — เดิมนับ
                // ทุก Posted ทำให้ void → restore → re-approve เจอคู่ JE เดิม+
                // reversal (net ศูนย์) แล้วข้ามการ post ใหม่: เอกสาร Approved
                // แต่ GL ไม่มี AR/รายได้/VAT เลย ขณะที่ stock ถูกตัดซ้ำ
                var hasExistingJournal = await _db.JournalEntries.AnyAsync(j =>
                    j.SourceDocumentId == documentId
                    && j.CompanyId == companyId
                    && j.Status == JournalEntryStatus.Posted
                    && j.OriginalEntryId == null
                    && j.ReversedByEntryId == null);

                // Credit-limit enforcement on sales-side credit documents —
                // blocks approval if customer is over their ContactCreditSetting
                // limit OR on hold. acknowledgeWarnings=true lets the operator
                // override (recorded in ProcessingNotes). Cash-settled sales
                // never consume credit (money came in immediately).
                var creditCheckTypes = new[] {
                    DocumentType.Invoice, DocumentType.TaxInvoice, DocumentType.BillingNote
                };
                if (_advancedArAp != null
                    && creditCheckTypes.Contains(doc.DocumentType)
                    && doc.PaymentType != Models.Enums.PaymentType.Cash
                    && doc.ContactId != Guid.Empty)
                {
                    try
                    {
                        var credit = await _advancedArAp.CheckCreditAsync(companyId, doc.ContactId, doc.TotalAmount);
                        if (!credit.IsApproved)
                        {
                            if (!acknowledgeWarnings)
                                throw new InvalidOperationException(
                                    $"ปฏิเสธอนุมัติ: {credit.Reason}. กรุณาตรวจ ContactCreditSetting หรือกด \"อนุมัติพร้อม override\"");
                            doc.Notes = (doc.Notes ?? "")
                                + $"\n[Credit override] {credit.Reason} — อนุมัติโดย {approvedBy}";
                        }
                    }
                    catch (InvalidOperationException) { throw; }
                    catch (Exception ex)
                    {
                        _logger.LogWarning(ex, "Credit check failed Doc={Doc} — proceeding without block", documentId);
                    }
                }

                // Issue the real running number NOW (transition Draft → Approved).
                // Draft sat with a "DRAFT-xxx" placeholder so deleting it never
                // created a sequence gap. We're inside the approve transaction
                // and DocumentNumberGenerator.NextAsync takes a pg_advisory_xact_
                // _lock per (company, prefix) so concurrent approves can't issue
                // duplicates. Documents that already carry a real number (idem-
                // potent re-approve, or those created by OCR/integration with a
                // number already stamped) keep the existing number.
                // ── ตรึง "บทบาททางกฎหมาย" ก่อนออกเลข ──
                // หัวกระดาษกับเลขที่เอกสารเป็นคนละแกน: ใบที่หัวพิมพ์ "ใบกำกับภาษี/
                // ใบเสร็จรับเงิน" เหมือนกันเป๊ะ เดิมได้เลขคนละชุด (TIV-/REC-) แล้วแต่
                // ทางที่กดเข้า ⇒ รายงานภาษีขาย §87 มีเลขปนกันหลายชุดทั้งที่เป็น
                // รายการใบกำกับล้วน ๆ. ตัดสินจากหัวที่ resolver **ตัวเดียวกับกระดาษ**
                // คำนวณให้ (ไม่ใช่กติกาสำเนาที่สอง) แล้วตรึงลงเอกสารพร้อมเลขที่
                // — เลขออกไปแล้วเปลี่ยนย้อนหลังไม่ได้ (§86/4) ค่าที่ใช้ตัดสินจึง
                // ต้องหยุดนิ่งเท่ากัน
                if (doc.IsTaxInvoiceByLaw == null)
                {
                    string? resolvedTitle = null;
                    try
                    {
                        resolvedTitle = await PdfGenerationService.ResolveDocumentTitleAsync(
                            _db, companyId, doc);
                    }
                    catch (Exception ex)
                    {
                        // resolver ล้ม → ตกกลับไปใช้ชนิดเอกสารตามเดิม (พฤติกรรมก่อน
                        // มีฟีเจอร์นี้) ห้ามล้มการอนุมัติทั้งใบเพราะ "ป้ายบทบาท"
                        _logger.LogWarning(ex,
                            "ตรึงบทบาททางกฎหมายไม่สำเร็จ Doc={Doc} — ใช้ชนิดเอกสารเลือกเลขตามเดิม",
                            documentId);
                    }

                    // ด่าน: "ใบแจ้งหนี้" ที่หัวถูกตั้งให้มีคำว่า "ใบกำกับภาษี" —
                    // ถ้าปล่อยผ่าน จะได้กระดาษที่ประกาศตัวเป็นใบกำกับ แต่ถือเลข
                    // INV- นอกเล่ม TIV / ไม่ผ่าน §86/4 / ออก e-Tax ไม่ได้
                    // (throw **นอก** try ข้างบน — ห้ามให้ catch ที่กันเรื่อง
                    // resolver ล้ม กลืนด่านนี้ไปด้วย)
                    // resolver ล้ม (resolvedTitle == null) บนใบแจ้งหนี้ = **ปฏิเสธ**
                    // ไม่ใช่ปล่อยผ่าน — ไม่งั้นด่าน compliance หายไปเงียบ ๆ ทุกครั้ง
                    // ที่ resolver มีปัญหา (fail-closed สำหรับชนิดที่มีความเสี่ยง)
                    if (resolvedTitle == null && doc.DocumentType == DocumentType.Invoice)
                        throw new Accounting.Helpers.BusinessRuleException(
                            "ตรวจหัวเอกสารไม่สำเร็จ จึงยืนยันไม่ได้ว่าใบแจ้งหนี้ใบนี้ไม่ได้"
                            + "ประกาศตัวเป็นใบกำกับภาษี — ลองอนุมัติอีกครั้ง "
                            + "หากยังไม่ได้ให้แจ้งผู้ดูแลระบบ (ตรวจการตั้งค่าหัวเอกสาร/เทมเพลต)",
                            "RD-86/4-INV-TITLE-UNKNOWN");

                    if (Accounting.Helpers.TaxInvoiceSeriesPolicy
                            .IsTaxTitleOnPlainInvoice(doc.DocumentType, resolvedTitle))
                        throw new Accounting.Helpers.BusinessRuleException(
                            Accounting.Helpers.TaxInvoiceSeriesPolicy.PlainInvoiceTaxTitleBlockedMessage,
                            "RD-86/4-INV-TITLE");

                    if (resolvedTitle != null)
                        doc.IsTaxInvoiceByLaw = Accounting.Helpers.TaxInvoiceSeriesPolicy
                            .CarriesTaxInvoiceRole(doc, resolvedTitle);
                }

                if (doc.DocumentNumber.StartsWith("DRAFT-", StringComparison.Ordinal))
                {
                    // ใช้เดือนของ DocumentDate (ไม่ใช่ "วันที่ approve") เพื่อให้
                    // เลขกับวันที่สอดคล้องกัน: ใบ 28/05 ที่ approve 01/06 ต้องได้
                    // "PV-202605-NNNN" ไม่ใช่ "PV-202606-..."
                    //
                    // ชนิดที่ใช้ "เลือกตัวย่อ" อาจไม่ใช่ชนิดจริงของเอกสาร เมื่อบริษัท
                    // เปิดกติกา "หัวมีคำว่าใบกำกับภาษี → เลขชุด TIV เสมอ" — เปลี่ยน
                    // แค่ตัวย่อ ไม่แตะ DocumentType (ซึ่งคุม JE / การนับ ภ.พ.30 /
                    // สายแปลงเอกสาร) และตัวนับเลขนับจาก prefix อยู่แล้วจึงยังเรียง
                    // ไม่ขาดช่วงต่อ prefix ตาม §86/4
                    var seriesType = doc.DocumentType;
                    if (doc.IsTaxInvoiceByLaw.HasValue)
                    {
                        // null (ยังไม่เคยตั้ง) = เปิด — ดู TaxInvoiceSeriesPolicy
                        // .IsUnifiedSeriesEnabled ห้ามเขียน `?? false` เองที่นี่
                        var unify = Accounting.Helpers.TaxInvoiceSeriesPolicy.IsUnifiedSeriesEnabled(
                            await _db.CompanySettings.AsNoTracking()
                                .Where(s => s.CompanyId == companyId)
                                .Select(s => s.UnifyTaxInvoiceNumberSeries)
                                .FirstOrDefaultAsync());
                        if (unify)
                            seriesType = Accounting.Helpers.TaxInvoiceSeriesPolicy
                                .SeriesTypeOverride(doc, doc.IsTaxInvoiceByLaw.Value) ?? doc.DocumentType;
                    }
                    doc.DocumentNumber = await Accounting.Helpers.DocumentNumberGenerator.NextAsync(
                        _db, companyId, seriesType, doc.DocumentDate);
                }

                // ===== §86/4 — ตรึงรหัสสาขาที่พิมพ์ลงกระดาษ =====
                // ตรึงพร้อมเลขที่เอกสาร: หลังจากนี้แก้ทะเบียนสาขา (พิมพ์รหัสผิดตอน
                // ตั้งค่า / ย้ายสถานะสำนักงานใหญ่) ต้องไม่ย้อนไปเปลี่ยนใบที่ออกไปแล้ว
                // — ใบกำกับพิมพ์ซ้ำปีหน้าต้องได้เลขสาขาเดิมเป๊ะ
                // กิจการสาขาเดียว: BranchId = null ⇒ ได้ Company.BranchCode เหมือนเดิม
                if (string.IsNullOrWhiteSpace(doc.IssuerBranchCode))
                {
                    var companyBranchCode = await _db.Companies
                        .Where(c => c.Id == companyId).Select(c => c.BranchCode).FirstOrDefaultAsync();
                    var docBranchCode = doc.BranchId.HasValue
                        ? await _db.Set<Branch>()
                            .Where(b => b.Id == doc.BranchId.Value && b.CompanyId == companyId)
                            .Select(b => b.TaxBranchCode).FirstOrDefaultAsync()
                        : null;
                    doc.IssuerBranchCode = Accounting.Helpers.DocumentIssuerBranch.ResolveCode(
                        null, docBranchCode, companyBranchCode);
                }

                // A cash-settled document (จ่ายทันที) is already fully paid the
                // moment it's approved — the JE moves real cash, not a payable.
                // Mark it Paid so it lands in the right bucket and never shows
                // as outstanding/ค้างชำระ; everything else goes to Approved.
                doc.Status = (doc.PaymentType == Models.Enums.PaymentType.Cash && doc.BalanceDue <= 0)
                    ? DocumentStatus.Paid
                    : DocumentStatus.Approved;
                doc.UpdatedBy = approvedBy;
                doc.UpdatedAt = DateTime.UtcNow;

                // ── ปิดวงจรเรียนรู้เรื่องหัก ณ ที่จ่าย (กฎเหล็ก #1 ขั้น CAPTURE) ──
                // การกดอนุมัติ = การตัดสินใจจริงของคน ⇒ เป็นคำตอบที่เอาไปสอนได้
                await RecordWhtDecisionFeedbackAsync(doc);

                // ===== Tax Point §78/§78/1 — snapshot จุดความรับผิด VAT =====
                // VAT period ของ ภ.พ.30 ใช้เดือนของ TaxPointDate. คำนวณเฉพาะ
                // เอกสารที่มี VAT (มิฉะนั้นไม่เกี่ยว).
                if (doc.VatAmount != 0)
                    doc.TaxPointDate = TaxPointResolver.Resolve(doc);

                // ===== Retention §87/3 + พ.ร.บ.บัญชี ม.10 — เก็บ 5 ปี =====
                //
                // นับจาก **วันสิ้นรอบบัญชี**ที่เอกสารอยู่ ไม่ใช่วันที่เอกสาร
                // (ผลตรวจ C-T11): §87/3 นับจากวันยื่นแบบ · ม.10 นับจากวันสิ้นรอบ
                // ⇒ ใบลงวันที่ 5 ม.ค. ของรอบ ม.ค.–ธ.ค. ต้องเก็บถึงสิ้นปีที่ 5
                // **นับจาก 31 ธ.ค.** ไม่ใช่จาก 5 ม.ค. — สูตรเดิมสั้นไปเกือบ 12 เดือน
                // และถ้ารอบบัญชีไม่ตรงปีปฏิทินจะสั้นได้ถึง ~14 เดือน
                //
                // ⚠️ กติกา retention ของเรพนี้คือ **MAX ของทุกกฎที่ครอบ** — สั้นไป
                // แปลว่าอาจลบเอกสารที่สรรพากรยังเรียกดูได้ (เรื่องกฎหมาย ไม่ใช่พื้นที่)
                if (doc.RetentionUntil == null)
                {
                    var startMonth = await _db.Companies.AsNoTracking()
                        .Where(c => c.Id == companyId)
                        .Select(c => (int?)c.FiscalYearStartMonth).FirstOrDefaultAsync() ?? 1;
                    var fy = Accounting.Helpers.FiscalYear.FiscalYearOf(doc.DocumentDate.Date, startMonth);
                    var fyEnd = Accounting.Helpers.FiscalYear.RangeFor(fy, startMonth).EndInclusive;
                    var basis = fyEnd > doc.DocumentDate.Date ? fyEnd : doc.DocumentDate.Date;
                    doc.RetentionUntil = basis.AddYears(5);
                }

                // ===== §65 ตรี — รายจ่ายต้องห้าม (บวกกลับ ภ.ง.ด.50) =====
                // เฉพาะเอกสารฝั่งซื้อ/ค่าใช้จ่ายที่กระทบกำไรสุทธิ.
                // ใบรับรองแทนใบเสร็จ (CIL) เป็นรายจ่ายที่กระทบกำไรสุทธิเหมือนกัน และ
                // เป็นเคสที่ §65 ตรี(9)/(18) เล็งตรงที่สุด (ผู้รับเงินออกใบเสร็จไม่ได้)
                // — ตัว validator รองรับ CIL อยู่แล้ว ขาดแค่ call site นี้ (P-7).
                // ยกเว้น CIL ที่แปลงมาจากใบตั้งหนี้: ใบต้นทางบวกกลับไปแล้ว ถ้าเรียกซ้ำ
                // จะบวกกลับสองรอบใน ภ.ง.ด.50
                if (doc.DocumentType is DocumentType.PurchaseInvoice
                        or DocumentType.Expense or DocumentType.PaymentVoucher
                    || (doc.DocumentType == DocumentType.CertificateInLieu
                        && doc.RelatedDocumentId == null))
                {
                    await ApplySection65TerAsync(companyId, doc);
                }

                // ชนิดที่ลงบัญชีอัตโนมัติ — ย้ายไป Helpers/DocumentJournalExpectation
                // เพื่อให้ "พรีวิว GL" ถามคำถามเดียวกันได้ว่า "ใบนี้ควรมี JE ไหม"
                // (เดิมลิสต์นี้เป็น local ⇒ ฝั่งแสดงผลไม่มีทางรู้ เลยติดป้าย
                // "ก่อนอนุมัติ" ให้ทุกใบที่หา JE ไม่เจอ แม้ใบที่อนุมัติไปแล้ว)
                // ใบเสร็จหลักฐานรับเงิน (settlement, สร้างเป็น Draft เมื่อผู้กด
                // บันทึกไม่มีสิทธิ์อนุมัติ): การเงินทั้งหมดอยู่ที่ Payment แล้ว
                // (JE Dr เงินสด/Cr ลูกหนี้ + PaidAmount) — อนุมัติใบนี้ = ออกเลขจริง
                // + ประทับผู้อนุมัติ (ลายเซ็น) เท่านั้น ห้าม post JE/บวกยอดซ้ำ
                // ใบกำกับภาษีเต็มรูปที่ออก "แทน" ใบเสร็จ/ใบกำกับอย่างย่อ: เศรษฐกิจ
                // ของรายการไม่เปลี่ยนเลย — เงินรับแล้ว รายได้รับรู้แล้ว ภาษีขายลง
                // 21911 แล้วตั้งแต่ใบเดิม เปลี่ยนแค่ "กระดาษที่ผู้ซื้อถือ" ⇒ post JE
                // ซ้ำ = รายได้/ภาษีขายเบิ้ล (และ ภ.พ.30 ก็สลับไปนับใบแทนแล้ว)
                var isFullTaxInvoiceReplacement = doc.ReplacesDocumentId.HasValue;

                if (!hasExistingJournal
                    && Accounting.Helpers.DocumentJournalExpectation.PostsToJournal(doc.DocumentType)
                    && !doc.IsSettlementReceipt && !isFullTaxInvoiceReplacement)
                {
                    await AutoPostToJournalAsync(companyId, doc, approvedBy);
                }

                if (!doc.IsSettlementReceipt && !isFullTaxInvoiceReplacement)
                    await ApplySourceDocumentAdjustmentsAsync(companyId, doc);

                // เอกสาร settle ที่อ้างเอกสารตั้งหนี้ (PV/Receipt/RV/CIL แปลงมา)
                // = การจ่าย/รับเงินจริง — JE ของมันแตะเงินสด/ธนาคารแล้ว ตัวมันเอง
                // ต้องไม่ค้างชำระ (กันใบสำคัญจ่ายโชว์ "ค้าง" ทั้งที่จ่ายไปแล้ว)
                if (doc.RelatedDocumentId.HasValue
                    && doc.DocumentType is DocumentType.PaymentVoucher or DocumentType.Receipt
                        or DocumentType.ReceiptVoucher or DocumentType.CertificateInLieu)
                {
                    doc.PaidAmount = doc.TotalAmount;
                    doc.BalanceDue = 0m;
                    doc.Status = DocumentStatus.Paid;
                }

                // tax point §78/1: ใบเสร็จรับชำระใบแจ้งหนี้บริการ → VAT ที่พัก 21913
                // ถึงกำหนด → reclass เข้า 21911 + stamp ใบแจ้งหนี้เข้า ภ.พ.30 งวดนี้
                // (no-op สำหรับใบที่ลง 21911 ตรง/reclass ไปแล้ว — GL-driven)
                if (doc.RelatedDocumentId.HasValue
                    && doc.DocumentType is DocumentType.Receipt or DocumentType.ReceiptVoucher)
                    await TryReclassifyUndueOutputVatAsync(companyId,
                        doc.RelatedDocumentId.Value, doc.DocumentDate, approvedBy);

                // ขายเงินสด ใบเดียว (ใบกำกับภาษี/ใบเสร็จรับเงิน) — AutoPost ลง Dr เงินสด
                // เต็ม (+ กลับมัดจำถ้ามี) แล้ว → รับเงินจบในตัว ปิดยอด Paid ทันที
                // (mirror integration PostCashSaleJournal). ไม่มี Payment row / ไม่ออก
                // ใบเสร็จหลักฐานแยก (frontend ข้าม paidOnIssue chain)
                if (doc.IssuedAsCashReceipt && doc.DocumentType == DocumentType.TaxInvoice)
                {
                    doc.PaidAmount = doc.TotalAmount;
                    doc.BalanceDue = 0m;
                    doc.Status = DocumentStatus.Paid;
                }

                // ===== 50 ทวิ สำหรับเอกสารจ่ายที่ "จ่ายจบตอน approve" (audit F12) =====
                // PV เงินสด standalone / เอกสาร settle แปลงมา → ไม่มี Payment row
                // เลย → hook auto-gen ใน CreatePaymentAsync ไม่เคยยิง → ไม่มี 50 ทวิ
                // ทั้งที่หักภาษีแล้วจ่ายเงินแล้ว (ต้องออกให้ผู้ถูกหักในวันจ่าย)
                // "จ่ายจบตอน approve" = Status Paid หรือ จ่ายเต็มแล้ว (BalanceDue<=0 +
                // PaidAmount>0) แม้ label ยังเป็น Approved — ครอบใบ PV จ่ายแล้วที่สร้าง
                // เป็น Draft (เช่น integration AutoApprove=false) แล้วมาอนุมัติทีหลัง
                // ให้ออก 50 ทวิ ครบ. guard cert-exists ใน AutoGenerate กันออกซ้ำอยู่แล้ว.
                // รอบ 170 (นโยบายเจ้าของ): autoIssue = true — ท.ป.4/2528 ให้ออกหนังสือรับรอง **ในวันจ่าย**
                // เดิมสร้างเป็น Draft ⇒ ไม่เข้า ภ.ง.ด.3/53 · ไม่เข้าไฟล์ยื่น · หน้านำส่ง (นับจาก Documents) จึงได้
                // ยอดคนละก้อนกับไฟล์ (นับจาก certs Issued/Printed) จนกว่าผู้ใช้จะกด "ออกใบ" ทีละใบ
                var whtPaidOnApprove = doc.Status == DocumentStatus.Paid
                    || (doc.BalanceDue <= 0.005m && doc.PaidAmount > 0.005m);
                if (whtPaidOnApprove
                    && doc.WithholdingTaxAmount > 0
                    && _whtService != null
                    && doc.DocumentType is DocumentType.PaymentVoucher or DocumentType.Expense
                        or DocumentType.PurchaseInvoice or DocumentType.CertificateInLieu)
                {
                    try
                    {
                        await _whtService.AutoGenerateFromDocumentAsync(
                            companyId, doc.Id, autoIssue: true, approvedBy,
                            doc.PaymentDate ?? doc.DocumentDate);
                    }
                    catch (Exception ex)
                    {
                        _logger.LogWarning(ex, "Auto-gen 50 ทวิ ตอน approve {Doc} ไม่สำเร็จ (ไม่ block)", doc.DocumentNumber);
                    }
                }

                if (!doc.IsSettlementReceipt && !isFullTaxInvoiceReplacement)
                {
                    await ApplyProjectBillingAsync(companyId, doc, +1);
                    await ApplyStockMovementsAsync(companyId, doc, +1, approvedBy);
                }

                // supersede ใบแจ้งหนี้ต้นทาง: TaxInvoice ที่แปลงจากใบแจ้งหนี้ (approved,
                // ยังไม่ชำระ) เมื่ออนุมัติ → ล้างใบแจ้งหนี้เดิม (reverse JE + คืน stock +
                // กลับ project) กัน GL/รายได้/สต๊อกซ้ำ (ภพ.30 นับเฉพาะ TaxInvoice อยู่แล้ว).
                if (doc.DocumentType == DocumentType.TaxInvoice && doc.RelatedDocumentId.HasValue
                    && !isFullTaxInvoiceReplacement)
                    await SupersedeSourceInvoiceAsync(companyId, doc, approvedBy);

                // ── ตราประทับ "ใบเดิมถูกแทนที่แล้ว" (§86/4) ──
                // ลง ณ **ตอนอนุมัติ** ไม่ใช่ตอนสร้าง: ถ้าประทับตั้งแต่ยังเป็นร่าง
                // ใบเดิมจะหลุดจากรายงานภาษีขายทันทีทั้งที่ใบแทนยังไม่มีเลข ⇒
                // ภาษีขายนำส่งขาดทั้งใบโดยไม่มีอะไรเตือน (ช่วงครึ่ง ๆ ที่ห้ามมี)
                if (isFullTaxInvoiceReplacement)
                {
                    var replaced = await _db.Documents.FirstOrDefaultAsync(d =>
                        d.Id == doc.ReplacesDocumentId!.Value && d.CompanyId == companyId);
                    if (replaced == null)
                        throw new Accounting.Helpers.BusinessRuleException(
                            "ไม่พบใบต้นทางที่ใบนี้ออกมาแทน — ยกเลิกใบนี้แล้วออกใหม่จากใบเสร็จโดยตรง",
                            "RD-86/4-REPLACE-SOURCE-MISSING");

                    replaced.ReplacedByDocumentId = doc.Id;
                    replaced.ReplacedAt = DateTime.UtcNow;
                    // หมายเหตุ**ภายใน** (ไม่พิมพ์ลงกระดาษ) — ผู้สอบบัญชีต้องเห็นว่า
                    // ทำไมใบนี้หายจากรายงานภาษีขายทั้งที่ยอดยังอยู่ใน GL
                    replaced.InternalNotes = string.Join(" · ", new[]
                    {
                        replaced.InternalNotes?.Trim(),
                        Accounting.Helpers.FullTaxInvoiceReplacement.OriginalRecalledNote(
                            doc.DocumentNumber, doc.ReplacementReason),
                    }.Where(s => !string.IsNullOrWhiteSpace(s)));
                    replaced.UpdatedAt = DateTime.UtcNow;
                    replaced.UpdatedBy = approvedBy;

                    // ใบแทนต้องไม่โผล่ในรายการค้างรับ — เงินรับครบตั้งแต่ใบเดิม
                    doc.PaidAmount = doc.TotalAmount;
                    doc.BalanceDue = 0m;
                    doc.Status = DocumentStatus.Paid;
                }

                // บังคับลงทะเบียนสินทรัพย์ — บรรทัดที่ลงผัง PPE (12xxx) ต้องมี
                // ทะเบียนสินทรัพย์ + ตารางค่าเสื่อม (TFRS บทที่ 10 + §65 ตรี (5)).
                // auto-create ด้วยค่า default (อายุ/วิธีตามประเภท) NeedsReview=true
                await AutoRegisterFixedAssetsAsync(companyId, doc, approvedBy);

                await _db.SaveChangesAsync();
                await transaction.CommitAsync();
            }
            catch
            {
                await transaction.RollbackAsync();
                throw;
            }
        });

        // Best-effort: train vendor intelligence cache for OCR self-learning.
        // Failures are logged inside the helper — training is a derived side-effect
        // that can always be rebuilt via BackfillFromHistoryAsync.
        await _vendorIntel.TryTrainAsync(companyId, doc.Id);

        // Best-effort: cross-tenant routing. If the recipient Contact maps to a
        // partner Company we have an Accepted partnership with, the document
        // shows up in their inbox automatically. Failures are logged and don't
        // unwind the approval.
        try { await _crossTenantWorkflow.OnDocumentSentAsync(doc); }
        catch (Exception ex)
        { _logger.LogWarning(ex, "Cross-tenant routing failed for doc {Id}", doc.Id); }

        // Best-effort auto-generate e-Tax record for eligible types when the
        // company has e-Tax enabled. Runs OUTSIDE the approval transaction so
        // an e-Tax failure (cert not configured, RD API down, etc.) doesn't
        // roll back the approval. Failures are stamped on the document
        // ([ETAX-AUTO-FAILED] in InternalNotes) + logged; the user can still
        // generate the e-Tax manually from the detail modal.
        // จุดเดียวกับ POS/Integration/CMS — IssuedDocumentHooks (รอบ 193 · S-02)
        await _issuedHooks.RunAsync(companyId, doc);

        // LINE notification (best-effort) — keeps the legacy broadcast room
        // hook for companies wired to a single LINE Notify channel.
        var contactName = await _db.Contacts.Where(c => c.Id == doc.ContactId).Select(c => c.Name).FirstOrDefaultAsync() ?? "";
        try
        {
            await _lineNotify.NotifyDocumentApprovedAsync(companyId, doc.DocumentNumber, contactName, doc.TotalAmount);
        }
        catch (Exception ex) { _logger.LogWarning(ex, "LINE notification failed for document {DocNum}", doc.DocumentNumber); }

        // แจ้งกลับ "ผู้ส่งบิลทางไลน์" — เอกสารที่เกิดจากโยนรูปเข้า LINE bot ฝัง
        // lineUserId ไว้ใน scan metadata ตอน intake. ผู้ส่ง (มักเป็นพนักงาน
        // หน้างาน) ควรรู้ว่านักบัญชีอนุมัติแล้วโดยไม่ต้องเปิดแอปมาเช็คเอง.
        // ข้ามเมื่อผู้อนุมัติคือผู้ส่งเอง (เพิ่งกดปุ่มในแชท — ได้คำตอบจาก
        // postback อยู่แล้ว). ใช้ companyId=null → token ของบอท (ผู้ใช้แชทกับ
        // ช่องบอท ส่งจาก OA อื่นของบริษัทจะไม่ถึง). best-effort เสมอ.
        try
        {
            var lineScanMeta = await _db.Set<OcrScanResult>().AsNoTracking()
                .Where(s => s.CompanyId == companyId && s.CreatedDocumentId == doc.Id
                    && s.ExternalMetadataJson != null && s.ExternalMetadataJson.Contains("lineUserId"))
                .Select(s => s.ExternalMetadataJson)
                .FirstOrDefaultAsync();
            if (!string.IsNullOrEmpty(lineScanMeta))
            {
                using var metaJson = System.Text.Json.JsonDocument.Parse(lineScanMeta);
                var submitterLineId = metaJson.RootElement.TryGetProperty("lineUserId", out var lu)
                    ? lu.GetString() : null;
                if (!string.IsNullOrEmpty(submitterLineId))
                {
                    var approverLineId = await _db.Users.AsNoTracking()
                        .Where(u => u.Email == approvedBy)
                        .Select(u => u.LineUserId)
                        .FirstOrDefaultAsync();
                    if (approverLineId != submitterLineId)
                        await _lineNotify.PushToUserAsync(null, submitterLineId,
                            $"✅ บิลที่คุณส่งเข้าไลน์ได้รับการอนุมัติแล้ว\n"
                            + $"📄 {doc.DocumentNumber} · {contactName}\n"
                            + $"💰 {doc.TotalAmount:N2} บาท — ลงบัญชีเรียบร้อย");
                }
            }
        }
        catch (Exception ex)
        { _logger.LogWarning(ex, "LINE submitter notify failed for doc {DocId}", doc.Id); }

        // New per-user / per-channel dispatch via the notification engine —
        // resolves Accounting / Owner recipients per the configured matrix.
        if (_notify != null)
        {
            await _notify.DispatchAsync(companyId, NotificationEvents.DocumentApproved, new NotificationContext
            {
                Title = $"อนุมัติเอกสาร {doc.DocumentNumber}",
                Message = $"{doc.DocumentType} · {contactName} · ยอดรวม {doc.TotalAmount:N2} บาท",
                ActionUrl = $"/pages/documents.html?id={doc.Id}",
                EntityType = "Document", EntityId = doc.Id,
            });

            // PaymentVoucher is a specialised approved-document subtype — fire
            // its dedicated event so accounting can have a separate matrix row.
            if (doc.DocumentType == DocumentType.PaymentVoucher)
            {
                await _notify.DispatchAsync(companyId, NotificationEvents.PaymentVoucherGenerated, new NotificationContext
                {
                    Title = $"ใบสำคัญจ่าย {doc.DocumentNumber}",
                    Message = $"{contactName} · ยอดรวม {doc.TotalAmount:N2} บาท",
                    ActionUrl = $"/pages/documents.html?id={doc.Id}",
                    EntityType = "Document", EntityId = doc.Id,
                });
            }
        }

        // ปิดลูปการสอน — final choice ตอนอนุมัติ: ทุกบรรทัดที่มี FeedbackId
        // + AccountId → บันทึก choice (acceptedAi=true ถ้าตรง AI's answer,
        // false ถ้า user แก้). RecordLineAccountFeedbackAsync เป็น idempotent
        // (ข้ามถ้า UserChosenAnswer เคย set แล้ว) → ปลอดภัย ถ้า Update เคย fire
        var approvedLines = await _db.DocumentLines.AsNoTracking()
            .Where(l => l.DocumentId == doc.Id).ToListAsync();
        await RecordLineAccountFeedbackAsync(approvedLines);

        // ปิดลูปที่ "เอกสารที่ลงจริง" ไม่ใช่ "ช่องบนสแกน" (สถาปัตยกรรมเป้าหมาย D3)
        // — ผู้ใช้เปิด Draft แล้วแก้ชื่อผู้ขาย/วันที่/ยอด/รหัสสาขาก่อนอนุมัติได้
        // เดิมไม่มีใครบอกนักเรียนเลย ⇒ เรียนจากคำตอบที่ผู้ใช้ปฏิเสธไปแล้ว
        await SyncScanToPostedDocumentAsync(companyId, doc, approvedLines);

        var approved = await GetDocumentAsync(companyId, documentId);

        // Auto-feed ProjectCostEntry when an approved EXPENSE-side
        // document carries a ProjectId. Closes the loop the audit
        // flagged: ProjectCostEntry was manual-only, so approved cost
        // documents bypassed the project P&L roll-up. Each ProjectId-
        // bearing line becomes a ProjectCostEntry row, idempotent on
        // (DocumentLineId) — re-approving the same doc doesn't
        // duplicate entries.
        try
        {
            await SyncProjectCostEntriesAsync(companyId, doc);
            // ภาษีที่ถูกหักจากใบนี้ → ลงทะเบียนเครดิต ภ.ง.ด.50/51 (อ่านจาก GL จริง)
            await SyncWhtCreditReceivedAsync(companyId, doc);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Project cost entry sync failed for doc {DocId}", documentId);
        }

        await FireWebhookAsync(companyId, "document.status_changed",
            new { document = approved, from = "Draft", to = approved.Status });

        // Auto-email schedule hook — เช็คกฎใน EmailScheduleRules ที่ตรง
        // กับ DocumentApproved + DocumentType แล้ว enqueue. Fail-safe:
        // ส่งอีเมลไม่สำเร็จต้องไม่ทำให้ approve ล้ม.
        if (_emailSchedule != null)
        {
            try { await _emailSchedule.OnDocumentApprovedAsync(companyId, documentId); }
            catch (Exception ex) { _logger.LogWarning(ex, "Email schedule enqueue failed Doc={Doc}", documentId); }
        }

        return approved;
    }

    /// <summary>เปลี่ยนผังบัญชี (line.AccountId) ของเอกสารที่ approved แล้ว
    /// แบบ "reclassify" — ไม่แก้เอกสารต้นฉบับ. ระบบ post JE คู่ใหม่
    /// Dr ผังใหม่ / Cr ผังเก่า (ด้วยยอด line.Amount = ฐานก่อน VAT) ลงงวด
    /// เดียวกับ doc.DocumentDate เพื่อให้ trial balance ก่อน–หลังตรงทุกบัญชี
    /// แล้วอัปเดต line.AccountId เพื่อให้รายงานต่อจากนี้ key ตามผังใหม่.
    /// VAT/WHT อยู่บัญชีแยก (11610/21915/21911) ไม่กระทบ.
    ///
    /// Gate (ทั้งหมดต้องผ่าน):
    /// - DocumentType ∈ {Expense, PurchaseInvoice, PaymentVoucher} เท่านั้น
    ///   (TaxInvoice/Receipt/CN/DN ห้ามตาม §86/4)
    /// - Status ∈ {Approved, Sent, PartiallyPaid, Paid} (Draft = แก้ได้
    ///   ปกติผ่าน UpdateDocument)
    /// - FiscalPeriod ของ doc.DocumentDate ยัง Open
    /// - ไม่มีเอกสารปลายทางอ้าง (RelatedDocumentId → docId)
    /// - ไม่มี Payment ลงแล้ว
    /// - ไม่อยู่ใน TaxReport ที่ Status=Submitted หรือ Filed (ภพ.30 ยื่นแล้ว)
    /// - ไม่ได้ submit e-Tax (EtaxInvoice.SubmittedAt != null)</summary>
    /// <summary>บัญชีคุมที่ห้ามย้ายเข้า/ออกด้วยเครื่องมือ reclassify รายบรรทัด —
    /// ระบบอื่นอ่านยอดของบัญชีเหล่านี้เป็นความจริง (ภ.พ.30 อ่านภาษีซื้อ/ขาย,
    /// รายงานอายุหนี้อ่านลูกหนี้/เจ้าหนี้, หน้ามัดจำอ่าน 215xx/217xx/21913)</summary>
    /// เทียบแบบ **ตรงรหัส** ไม่ใช่ prefix — prefix กว้างเกินจะเผลอล็อกบัญชี
    /// ค้างจ่ายธรรมดาที่อยู่ช่วงเดียวกัน (เช่น "215" กิน 21511 ค่าไฟฟ้าค้างจ่าย,
    /// "217" กิน 21714 ดอกเบี้ยค้างจ่าย ซึ่งเป็นผังปกติที่ควรย้ายได้)
    private static readonly HashSet<string> ReclassifyProtectedCodes = new(StringComparer.Ordinal)
    {
        "11310",                    // ลูกหนี้การค้า (รายงานอายุหนี้/ยอดค้างรับ)
        "11610", "11640",           // ภาษีซื้อ ภ.พ.30 / ภาษีซื้อยังไม่ถึงกำหนด
        "21210",                    // เจ้าหนี้การค้า (ยอดค้างจ่าย)
        "21510", "21520", "21610",  // มัดจำรับล่วงหน้า / รายได้รับล่วงหน้า / เงินมัดจำรับ
        "21711", "21712", "21713",  // ค่าเช่า/สินค้า/บริการ รับล่วงหน้า (วงจรมัดจำ)
        "21911", "21912", "21913",  // ภาษีขาย ภ.พ.30 / ภ.พ.36 / ภาษีขายรอเรียกเก็บ
        "21916", "21917", "21918",  // ภาษีหัก ณ ที่จ่ายค้างจ่าย (ภ.ง.ด.3/53/54)
    };

    private static bool IsReclassifyProtectedAccount(string? accountCode)
        => !string.IsNullOrWhiteSpace(accountCode)
           && ReclassifyProtectedCodes.Contains(accountCode!.Trim());

    /// <summary>
    /// หา "ใบเดียวกันที่บันทึกไปแล้ว" ก่อนสร้างเอกสารจากสแกน — สแกนใบเดิมซ้ำ
    /// (ส่งไลน์ซ้ำ / ถ่ายสองครั้ง / คนละคนอัปโหลด) = ค่าใช้จ่ายและภาษีซื้อเบิ้ล
    /// แบบเงียบ ๆ เพราะเลขเอกสารของเราต่างกันทุกใบ
    ///
    /// สองระดับความมั่นใจ:
    ///   • <b>แน่นอน</b> — เลขใบกำกับของผู้ขายตรงกัน + คู่ค้าเดียวกัน
    ///     (เลขนี้ไม่ซ้ำในระบบผู้ขาย ⇒ ตรงกัน = ใบเดียวกันแทบ 100%)
    ///   • <b>น่าสงสัย</b> — คู่ค้า+ยอดเท่ากัน (±0.5%) ในช่วง ±60 วัน
    ///     (ผู้ขายอาจขายของชุดเดิมซ้ำจริง ⇒ เตือนอย่างเดียว ห้ามบล็อก)
    ///
    /// อ่านอย่างเดียว ไม่แก้ข้อมูล — ผู้เรียกตัดสินใจเอง (กฎ "ห้าม block
    /// สิ่งที่อาจถูกต้อง" — false positive ที่บล็อกแรงกว่าปัญหาที่กัน)
    /// </summary>
    public async Task<DuplicateCheckResult> CheckDuplicateAsync(
        Guid companyId, Guid? contactId, string? supplierInvoiceNumber,
        DocumentType? documentType, decimal amount, DateTime documentDate,
        Guid? excludeDocumentId = null)
    {
        var candidates = new List<DuplicateDocumentCandidate>();
        var seen = new HashSet<Guid>();
        if (excludeDocumentId.HasValue) seen.Add(excludeDocumentId.Value);

        var baseQuery = _db.Documents.AsNoTracking()
            .Where(d => d.CompanyId == companyId && !d.IsDeleted
                && d.Status != DocumentStatus.Voided && d.Status != DocumentStatus.Rejected);

        // ── ระดับ "แน่นอน": เลขใบกำกับผู้ขายตรงกัน ─────────────────────────
        var sin = supplierInvoiceNumber?.Trim();
        if (!string.IsNullOrWhiteSpace(sin))
        {
            var sinLower = sin.ToLowerInvariant();
            var strong = await baseQuery
                .Where(d => d.SupplierInvoiceNumber != null
                    && d.SupplierInvoiceNumber.ToLower() == sinLower
                    && (contactId == null || d.ContactId == contactId))
                .OrderByDescending(d => d.DocumentDate)
                .Select(d => new
                {
                    d.Id, d.DocumentNumber, d.DocumentType, d.DocumentDate,
                    d.TotalAmount, d.Status, d.SupplierInvoiceNumber,
                    ContactName = d.Contact != null ? d.Contact.Name : null,
                })
                .Take(5).ToListAsync();
            foreach (var d in strong)
            {
                if (!seen.Add(d.Id)) continue;
                candidates.Add(new DuplicateDocumentCandidate(
                    d.Id, d.DocumentNumber, d.DocumentType.ToString(), d.DocumentDate.Date,
                    d.TotalAmount, d.Status.ToString(), d.SupplierInvoiceNumber,
                    d.ContactName, "SupplierInvoiceNumber", IsStrong: true));
            }
        }

        // ── ระดับ "น่าสงสัย": คู่ค้า + ยอด + ช่วงวัน ────────────────────────
        if (contactId.HasValue && amount > 0.01m)
        {
            var from = documentDate.AddDays(-60);
            var to = documentDate.AddDays(60);
            var tol = amount * 0.005m;
            var weak = await baseQuery
                .Where(d => d.ContactId == contactId.Value
                    && d.DocumentDate >= from && d.DocumentDate <= to
                    && (documentType == null || d.DocumentType == documentType)
                    && d.TotalAmount >= amount - tol && d.TotalAmount <= amount + tol)
                .OrderByDescending(d => d.DocumentDate)
                .Select(d => new
                {
                    d.Id, d.DocumentNumber, d.DocumentType, d.DocumentDate,
                    d.TotalAmount, d.Status, d.SupplierInvoiceNumber,
                    ContactName = d.Contact != null ? d.Contact.Name : null,
                })
                .Take(5).ToListAsync();
            foreach (var d in weak)
            {
                if (!seen.Add(d.Id)) continue;
                candidates.Add(new DuplicateDocumentCandidate(
                    d.Id, d.DocumentNumber, d.DocumentType.ToString(), d.DocumentDate.Date,
                    d.TotalAmount, d.Status.ToString(), d.SupplierInvoiceNumber,
                    d.ContactName, "SameContactAndAmount", IsStrong: false));
            }
        }

        return new DuplicateCheckResult(candidates.Any(c => c.IsStrong), candidates);
    }

    /// <summary>รายการบัญชี (JE) ทั้งหมดของเอกสาร พร้อมบรรทัดจริงจาก GL และ
    /// สิทธิ์ว่า "ปรับปรุงได้ไหม" — ใช้ในแผงตรวจสอบ/แก้ไข JE บนหน้าเอกสาร
    /// (คำถามผู้ใช้: "ยังไม่เจอปุ่มให้แก้ผังบัญชีที่ลง JE")</summary>
    public async Task<List<DocumentJournalEntryDto>> GetDocumentJournalEntriesAsync(
        Guid companyId, Guid documentId)
    {
        var doc = await _db.Documents.AsNoTracking()
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        var entries = await _db.JournalEntries.AsNoTracking()
            .Include(j => j.Lines).ThenInclude(l => l.Account)
            .Where(j => j.CompanyId == companyId && j.SourceDocumentId == documentId && !j.IsDeleted)
            .OrderBy(j => j.EntryDate).ThenBy(j => j.EntryNumber)
            .ToListAsync();

        // เหตุผลที่ปรับปรุงไม่ได้ — คำนวณครั้งเดียวต่อเอกสาร (ทุกใบใช้ร่วมกัน)
        var docBlock = await ResolveJournalAdjustBlockAsync(companyId, doc);

        return entries.Select(j =>
        {
            var block = docBlock;
            if (block == null && j.Status != JournalEntryStatus.Posted)
                block = $"ใบสำคัญสถานะ {j.Status} — ปรับปรุงได้เฉพาะใบที่ผ่านรายการแล้ว";
            if (block == null && j.OriginalEntryId != null)
                block = "ใบนี้เป็น 'ตัวกลับ' — ปรับปรุงที่ใบต้นฉบับแทน";
            if (block == null && j.ReversedByEntryId != null)
                block = "ใบนี้ถูกกลับรายการไปแล้ว";

            return new DocumentJournalEntryDto(
                j.Id, j.EntryNumber, j.EntryDate.Date, j.JournalType.ToString(),
                j.Status.ToString(), j.TotalDebit, j.TotalCredit,
                IsReversalEntry: j.OriginalEntryId != null,
                CanAdjust: block == null,
                BlockReason: block,
                Lines: j.Lines.OrderBy(l => l.LineOrder).Select(l => new DocumentJournalLineDto(
                    l.AccountId, l.Account.AccountCode, l.Account.AccountName,
                    l.DebitAmount, l.CreditAmount, l.Description,
                    IsReclassifyProtectedAccount(l.Account.AccountCode))).ToList());
        }).ToList();
    }

    /// <summary>gate ระดับเอกสารสำหรับการปรับปรุง JE — ชุดเดียวกับ reclassify
    /// (คืน null = ทำได้)</summary>
    private async Task<string?> ResolveJournalAdjustBlockAsync(Guid companyId, Document doc)
    {
        if (doc.Status == DocumentStatus.Voided)
            return "เอกสารถูกยกเลิกแล้ว — รายการบัญชีถูกกลับไปหมดแล้ว";

        var inSubmittedReport = await _db.TaxReportLines.AsNoTracking().AnyAsync(l =>
            l.DocumentId == doc.Id && l.TaxReport.CompanyId == companyId
            && (l.TaxReport.Status == TaxReportStatus.Submitted
                || l.TaxReport.Status == TaxReportStatus.Filed));
        if (inSubmittedReport)
            return "เอกสารอยู่ในรายงานภาษีที่ยื่นสรรพากรแล้ว — ต้องยื่นแบบเพิ่มเติมแทน";

        var etaxSubmitted = await _db.EtaxInvoices.AsNoTracking()
            .AnyAsync(e => e.DocumentId == doc.Id && e.SubmittedAt != null);
        if (etaxSubmitted)
            return "เอกสารนี้ส่ง e-Tax XML ไปสรรพากรแล้ว";

        return null;
    }

    /// <summary>
    /// ปรับปรุงรายการบัญชีของเอกสาร — ผู้ใช้ส่ง "สถานะปลายทาง" ของใบสำคัญมา
    /// (ผังบัญชีที่ถูก + เพิ่ม/ลดบรรทัดได้) ระบบคำนวณผลต่างแล้วลง **ใบปรับปรุงใหม่**
    /// ไม่แก้ใบเดิม — audit trail ครบ (ใบเดิม + ใบปรับปรุง อ่านคู่กันได้)
    ///
    /// กติกาที่บังคับ (ทำให้เครื่องมือนี้ปลอดภัยพอจะเปิดให้แก้อิสระ):
    ///   1. Dr = Cr ในสถานะปลายทาง (บัญชีคู่)
    ///   2. **ยอดรวมแต่ละฝั่งต้องตรงกับเอกสาร** — Σ Dr ปลายทาง = Σ Dr ใบเดิม
    ///      (= ยอดเอกสาร); ยอดของเอกสารต้องแก้ที่เอกสาร ไม่ใช่แอบแก้ผ่าน GL
    ///   3. บัญชีคุม (ลูกหนี้/เจ้าหนี้/ภาษี/มัดจำ/WHT) **แก้ได้** — เปิดตามคำขอ
    ///      ผู้ใช้ (เดิมบล็อก) แต่ทุกการขยับถูกจดลง audit เป็น
    ///      controlAccountsMoved (ก่อน→หลัง) เพราะรายงานที่อ่านบัญชีพวกนี้จะ
    ///      เห็นยอดต่างจาก GL — เครื่องมือกระทบยอด GL↔ภาษี ใช้ไล่ drift ได้
    ///   4. งวดของวันที่ลงใบปรับปรุงต้องเปิด · เอกสารต้องไม่อยู่ในแบบที่ยื่นแล้ว
    ///      และไม่ได้ส่ง e-Tax (gate เดิมยังครบ)
    /// </summary>
    public async Task<List<DocumentJournalEntryDto>> AdjustDocumentJournalEntryAsync(
        Guid companyId, Guid documentId, Guid journalEntryId,
        AdjustDocumentJournalRequest request, string actor)
    {
        var doc = await _db.Documents.AsNoTracking()
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        var blocked = await ResolveJournalAdjustBlockAsync(companyId, doc);
        if (blocked != null) throw new InvalidOperationException(blocked);

        var original = await _db.JournalEntries.AsNoTracking()
            .Include(j => j.Lines).ThenInclude(l => l.Account)
            .FirstOrDefaultAsync(j => j.Id == journalEntryId && j.CompanyId == companyId
                && j.SourceDocumentId == documentId && !j.IsDeleted)
            ?? throw new KeyNotFoundException("ไม่พบใบสำคัญของเอกสารนี้");

        if (original.Status != JournalEntryStatus.Posted)
            throw new InvalidOperationException("ปรับปรุงได้เฉพาะใบสำคัญที่ผ่านรายการแล้ว");
        if (original.OriginalEntryId != null)
            throw new InvalidOperationException("ใบนี้เป็น 'ตัวกลับ' — ปรับปรุงที่ใบต้นฉบับแทน");
        if (original.ReversedByEntryId != null)
            throw new InvalidOperationException("ใบนี้ถูกกลับรายการไปแล้ว");

        // ⚠️ X-3: กันปรับปรุง "ซ้อน" บนใบหลักใบเดิม — Adjust ไม่แก้ใบเดิมเลย
        // (ลงใบปรับปรุงใหม่แทน) ⇒ เปิดแผงอีกครั้งยังเห็นผังเดิม แล้วคำนวณผลต่าง
        // จากใบเดิมอีกรอบ. ปรับสองครั้งบนใบเดียว = ผังเก่าติดลบ + ผังใหม่สองตัว
        // ต่างเต็มจำนวน (ยอดรวมยังตรง Dr=Cr ยังสมดุล ⇒ ไม่มีด่านไหนจับ)
        // ต้องกลับใบปรับปรุงเดิมก่อน แล้วค่อยปรับใหม่จากสถานะจริง
        var priorAdjustment = await _db.JournalEntries.AsNoTracking()
            .Where(j => j.CompanyId == companyId && j.SourceDocumentId == documentId
                && j.Status == JournalEntryStatus.Posted
                && j.OriginalEntryId == null && j.ReversedByEntryId == null
                && !j.IsDeleted
                && j.Description != null && j.Description.Contains("ปรับปรุงผังบัญชีของ"))
            .Select(j => j.EntryNumber)
            .FirstOrDefaultAsync();
        if (priorAdjustment != null)
            throw new InvalidOperationException(
                $"เอกสารนี้มีใบสำคัญปรับปรุงค้างอยู่แล้ว ({priorAdjustment}) — " +
                "ปรับซ้อนจะทำให้ผังบัญชีเพี้ยน (ผังเดิมติดลบ ผังใหม่ซ้ำสองตัว) " +
                "กรุณากลับรายการใบปรับปรุงนั้นก่อน แล้วค่อยปรับใหม่จากสถานะปัจจุบัน");

        // ⚠️ X-4: gate ให้ครบชุดเดียวกับ reclassify (คอมเมนต์เดิมอ้างว่า "ชุด
        // เดียวกัน" แต่จริง ๆ แคบกว่า) — เอกสารที่มีใบปลายทางแล้ว การ supersede
        // /convert จะกลับ "ทุก JE ที่ OriginalEntryId == null" ซึ่งรวมใบปรับปรุง
        // ด้วย แล้วลง JE ใหม่จาก doc.Lines ⇒ เจตนาปรับปรุงหายเงียบ
        var adjHasDownstream = await _db.Documents.AsNoTracking().AnyAsync(d =>
            d.CompanyId == companyId && d.RelatedDocumentId == documentId
            && d.Status != DocumentStatus.Voided && !d.IsDeleted
            && !d.IsSettlementReceipt);
        if (adjHasDownstream)
            throw new InvalidOperationException(
                "มีเอกสารปลายทางอ้างเอกสารนี้แล้ว — การแปลง/แทนที่จะกลับใบปรับปรุงทิ้ง " +
                "ทำให้ผังที่แก้ไว้หายไปเงียบ ๆ กรุณาแก้ที่เอกสารปลายทางแทน");
        if (doc.IsDeposit)
            throw new InvalidOperationException(
                "ใบมัดจำมีวงจรบัญชีของตัวเอง (รับ → ตัด/คืน) — ปรับปรุงผังบัญชีตรง ๆ ไม่ได้");

        var wanted = request.Lines ?? new List<AdjustJournalLineDto>();
        if (wanted.Count < 2)
            throw new InvalidOperationException("ต้องมีอย่างน้อย 2 บรรทัด (เดบิต + เครดิต)");

        const MidpointRounding R = MidpointRounding.AwayFromZero;
        foreach (var l in wanted)
        {
            if (l.DebitAmount < 0 || l.CreditAmount < 0)
                throw new InvalidOperationException("ยอดเดบิต/เครดิตต้องไม่ติดลบ");
            if (l.DebitAmount > 0 && l.CreditAmount > 0)
                throw new InvalidOperationException("แต่ละบรรทัดใส่ได้ด้านเดียว (เดบิต หรือ เครดิต)");
        }

        var accountIds = wanted.Select(l => l.AccountId).Distinct().ToList();
        var accounts = await _db.ChartOfAccounts.AsNoTracking()
            .Where(a => a.CompanyId == companyId && accountIds.Contains(a.Id))
            .ToDictionaryAsync(a => a.Id);
        foreach (var id in accountIds)
        {
            if (!accounts.TryGetValue(id, out var acc))
                throw new InvalidOperationException("มีผังบัญชีที่ไม่อยู่ในผังของบริษัทนี้");
            if (!acc.IsActive)
                throw new InvalidOperationException($"ผังบัญชี {acc.AccountCode} ถูกปิดใช้งาน");
        }

        var wantDr = Math.Round(wanted.Sum(l => l.DebitAmount), 2, R);
        var wantCr = Math.Round(wanted.Sum(l => l.CreditAmount), 2, R);
        if (wantDr != wantCr)
            throw new InvalidOperationException(
                $"ยอดเดบิต ({wantDr:N2}) ไม่เท่ากับยอดเครดิต ({wantCr:N2})");

        var origDr = Math.Round(original.Lines.Sum(l => l.DebitAmount), 2, R);
        if (wantDr != origDr)
            throw new InvalidOperationException(
                $"ยอดรวมต้องเท่าเดิม ({origDr:N2}) — เครื่องมือนี้ใช้ย้าย/จัดผังบัญชีเท่านั้น " +
                "ถ้ายอดผิดต้องแก้ที่ตัวเอกสาร (หรือยกเลิกแล้วออกใหม่)");

        // ยอดสุทธิ (Dr − Cr) ต่อบัญชี ทั้งของเดิมและที่ต้องการ
        static Dictionary<Guid, decimal> NetBy<T>(IEnumerable<T> src,
            Func<T, Guid> id, Func<T, decimal> dr, Func<T, decimal> cr)
        {
            var m = new Dictionary<Guid, decimal>();
            foreach (var x in src)
                m[id(x)] = m.GetValueOrDefault(id(x)) + dr(x) - cr(x);
            return m;
        }
        var origNet = NetBy(original.Lines, l => l.AccountId, l => l.DebitAmount, l => l.CreditAmount);
        var wantNet = NetBy(wanted, l => l.AccountId, l => l.DebitAmount, l => l.CreditAmount);

        // ⚠️ ห้ามใช้ ToDictionary ตรง ๆ — JE ปกติมี "บัญชีเดียวกันหลายบรรทัด"
        // ได้เสมอ (เช่น ใบเสร็จ 2 รายการห้องพัก → ขา Cr 41110 สองบรรทัด)
        // ⇒ duplicate key ⇒ ArgumentException ภาษาอังกฤษ ถูก middleware ปิดบัง
        // เป็น "ข้อมูลที่ส่งมาไม่ถูกต้อง" — ผู้ใช้กดบันทึกแผงปรับปรุงไม่ได้เลย
        // ทั้งที่ตัวเลขถูกทุกอย่าง (defect class เดียวกับกฎ "อ่านขาที่ลงจริง")
        var origCodes = original.Lines
            .GroupBy(l => l.AccountId)
            .ToDictionary(g => g.Key, g => g.First().Account);

        // บัญชีคุม (ลูกหนี้/เจ้าหนี้/ภาษี/มัดจำ/WHT) — เดิม **บล็อก** การขยับยอด
        // สุทธิ ผู้ใช้ขอเปิดให้แก้ได้ทั้งหมด (รวมยอด) โดยเหลือ hard rule แค่
        // "ยอดรวมแต่ละฝั่งต้องตรงกับเอกสาร" (บังคับด้วย wantDr == origDr ข้างบน
        // + Dr = Cr) จึงเปลี่ยนจากบล็อก → **บันทึกร่องรอยเข้ม**: จดทุกบัญชีคุม
        // ที่ยอดสุทธิเปลี่ยนลง audit (ก่อน→หลัง) เพราะรายงานที่อ่านบัญชีพวกนี้
        // (ภ.พ.30 / ภ.ง.ด. / อายุหนี้ / วงจรมัดจำ) จะเห็นยอดต่างจาก GL — เครื่องมือ
        // กระทบยอด GL↔ภาษี มีไว้จับ drift แบบนี้ และเอกสารที่อยู่ในแบบยื่นแล้ว/
        // ส่ง e-Tax แล้ว ถูก gate ระดับเอกสารกันไว้ก่อนถึงจุดนี้อยู่แล้ว
        var controlMoved = new List<object>();
        foreach (var id in origNet.Keys.Union(wantNet.Keys))
        {
            var code = origCodes.TryGetValue(id, out var a) ? a.AccountCode
                : accounts.TryGetValue(id, out var b) ? b.AccountCode : null;
            if (!IsReclassifyProtectedAccount(code)) continue;
            var before = Math.Round(origNet.GetValueOrDefault(id), 2, R);
            var after = Math.Round(wantNet.GetValueOrDefault(id), 2, R);
            if (before != after)
                controlMoved.Add(new { account = code, before, after });
        }

        // ผลต่างที่ต้องลงจริง — บวก = ต้อง Dr เพิ่ม, ลบ = ต้อง Cr
        var deltas = origNet.Keys.Union(wantNet.Keys)
            .Select(id => (Id: id, Amount: Math.Round(
                wantNet.GetValueOrDefault(id) - origNet.GetValueOrDefault(id), 2, R)))
            .Where(d => d.Amount != 0m)
            .OrderByDescending(d => Math.Abs(d.Amount))
            .ToList();
        if (deltas.Count == 0)
            throw new InvalidOperationException("ไม่มีอะไรเปลี่ยน — ผังบัญชีและยอดเหมือนเดิมทุกบรรทัด");

        var entryDate = (request.EntryDate?.Date ?? original.EntryDate.Date);
        var period = await _db.FiscalPeriods.AsNoTracking().FirstOrDefaultAsync(f =>
            f.CompanyId == companyId && f.StartDate <= entryDate && f.EndDate >= entryDate);
        if (period != null && period.Status != FiscalPeriodStatus.Open)
            throw new InvalidOperationException(
                $"งวด {period.Name} ปิดแล้ว — เลือกวันที่ในงวดที่ยังเปิดอยู่");

        var nameById = new Dictionary<Guid, string>();
        foreach (var (id, acc) in origCodes) nameById[id] = $"{acc.AccountCode} — {acc.AccountName}";
        foreach (var (id, acc) in accounts) nameById[id] = $"{acc.AccountCode} — {acc.AccountName}";

        await using var tx = await _db.Database.BeginTransactionAsync();
        try
        {
            var desc = $"ปรับปรุงผังบัญชีของ {original.EntryNumber} ({doc.DocumentNumber})"
                + (string.IsNullOrWhiteSpace(request.Reason) ? "" : $" • {request.Reason}");
            var builder = Journal.JournalEntryBuilder
                .For(_db, companyId, entryDate)
                .Type(original.JournalType)
                .Description(desc)
                .Reference(doc.DocumentNumber)
                .SourceDocument(doc.Id)
                .Project(doc.ProjectId);
            foreach (var d in deltas)
            {
                var label = nameById.GetValueOrDefault(d.Id, "");
                if (d.Amount > 0) builder = builder.Debit(d.Id, d.Amount, $"Dr {label} (ปรับปรุง)");
                else builder = builder.Credit(d.Id, -d.Amount, $"Cr {label} (ปรับปรุง)");
            }
            await builder.PostAsync(actor);

            _db.AuditLogs.Add(new AuditLog
            {
                CompanyId = companyId,
                Action = AuditAction.Update,
                EntityType = "JournalEntry",
                EntityId = journalEntryId.ToString(),
                NewValues = System.Text.Json.JsonSerializer.Serialize(new
                {
                    action = "AdjustDocumentJournalEntry",
                    documentNumber = doc.DocumentNumber,
                    originalEntry = original.EntryNumber,
                    entryDate,
                    reason = request.Reason,
                    // บัญชีคุมที่ยอดสุทธิถูกขยับ (ก่อน→หลัง) — ร่องรอยเข้มแทน
                    // การบล็อกเดิม ผู้ตรวจ/เครื่องมือกระทบยอดใช้ไล่หา drift ได้
                    controlAccountsMoved = controlMoved,
                    deltas = deltas.Select(d => new
                    {
                        account = nameById.GetValueOrDefault(d.Id, d.Id.ToString()),
                        amount = d.Amount,
                    }),
                    actor,
                }),
                Timestamp = DateTime.UtcNow,
            });

            await _db.SaveChangesAsync();
            await tx.CommitAsync();
        }
        catch
        {
            await tx.RollbackAsync();
            throw;
        }

        _logger.LogInformation(
            "AdjustDocumentJournalEntry: {Doc} / {Entry} — {Count} บัญชีถูกย้าย โดย {Actor}",
            doc.DocumentNumber, original.EntryNumber, deltas.Count, actor);

        return await GetDocumentJournalEntriesAsync(companyId, documentId);
    }

    public async Task<DocumentResponse> ReclassifyLineAccountAsync(
        Guid companyId, Guid documentId, Guid lineId,
        Guid newAccountId, string? reason, string actor)
    {
        var doc = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        // เดิมอนุญาตเฉพาะฝั่งซื้อ/จ่าย โดยอ้าง §86/4 ว่าใบกำกับแก้ไม่ได้ — อ้างผิด
        // มาตรา: §86/4 บังคับ **สิ่งที่พิมพ์บนใบกำกับ** (ชื่อ/เลขผู้เสียภาษี/รายการ/
        // จำนวน/ราคา/VAT) ซึ่ง **ไม่มีรหัสผังบัญชีอยู่บนเอกสารเลย** การย้ายรายได้
        // จาก 41100 → 41200 ไม่แตะตัวเลขบนใบ ไม่แตะยอด VAT ไม่แตะ ภ.พ.30 —
        // เป็นการจัดประเภททางบัญชีภายในล้วน ๆ. ผลของการห้ามคือใบขายที่ลงผังผิด
        // "ไม่มีทางแก้เลย" ต้องยกเลิกใบกำกับที่ออกไปแล้วทั้งใบ ซึ่งอันตรายกว่ามาก
        // (ที่มา: ผู้ใช้เปิดใบขายที่รับเงินแล้ว — ไม่มีปุ่มแก้ผังบัญชีให้เลย)
        var allowedTypes = new[] {
            DocumentType.PurchaseInvoice, DocumentType.Expense, DocumentType.PaymentVoucher,
            DocumentType.Invoice, DocumentType.TaxInvoice, DocumentType.Receipt,
            DocumentType.CreditNote, DocumentType.DebitNote,
        };
        if (!allowedTypes.Contains(doc.DocumentType))
            throw new InvalidOperationException(
                $"เอกสารประเภท {doc.DocumentType} ยังไม่รองรับการเปลี่ยนผังบัญชีรายบรรทัด — " +
                "ยกเลิกแล้วออกใบใหม่แทน");

        // มัดจำมี lifecycle ผูกกับบัญชีของตัวเอง (217xx/21913 → realize/refund/apply)
        // ย้ายผังบรรทัดจะทำให้ยอดคงเหลือมัดจำกับ GL ไม่ตรงกัน
        if (doc.IsDeposit)
            throw new InvalidOperationException(
                "ใบมัดจำมีวงจรของตัวเอง (รับ → ตัด/คืน) — เปลี่ยนผังบัญชีรายบรรทัดไม่ได้ " +
                "ให้ใช้การคืน/ตัดมัดจำตามปกติ");

        // ⚠️ WaitingApproval ต้องอยู่ในลิสต์ด้วย — ใบที่รออนุมัติ **ยังไม่มี JE**
        // ถ้าปล่อยผ่าน: reclassify ลง JE คู่ (Dr ผังใหม่/Cr ผังเก่า) + เปลี่ยน
        // line.AccountId → พออนุมัติ AutoPost ลง Dr ผังใหม่อีกรอบ ⇒ ค่าใช้จ่าย
        // เบิ้ล 2 เท่า และผังเก่าติดลบ โดย Dr=Cr ยังสมดุลจึงไม่มี guard ตัวไหนจับ
        // (UI ใช้ whitelist Approved/Sent/PartiallyPaid/Paid อยู่แล้ว — ช่องนี้
        //  เปิดเฉพาะทาง API; defect class "guard UI ไม่ตรง server")
        if (doc.Status is DocumentStatus.Draft or DocumentStatus.Voided
                       or DocumentStatus.Rejected or DocumentStatus.WaitingApproval)
            throw new InvalidOperationException(
                $"เอกสาร Status={doc.Status} ไม่อยู่ในขั้นที่ reclassify ได้ " +
                "(Draft/รออนุมัติ = แก้ผ่านฟอร์มปกติ, Voided/Rejected = สร้างใหม่)");

        var period = await _db.FiscalPeriods.FirstOrDefaultAsync(p =>
            p.CompanyId == companyId
            && p.StartDate <= doc.DocumentDate && p.EndDate >= doc.DocumentDate);
        if (period != null && period.Status != FiscalPeriodStatus.Open)
            throw new InvalidOperationException(
                $"วันที่เอกสารอยู่ในงวด '{period.Name}' ที่ปิดแล้ว ({period.Status}) — " +
                "ผังบัญชีของงวดที่ปิดแก้ไม่ได้ (กัน trial balance ย้อนหลังพัง)");

        // ใบเสร็จหลักฐานการรับชำระ (IsSettlementReceipt) เป็นเอกสาร **evidence-only**
        // ไม่ลง JE ไม่ตัดหนี้ซ้ำ — ไม่มีอะไรใน GL ให้ขัดกับการย้ายผัง จึงไม่นับ
        // เป็น "เอกสารปลายทาง" (ไม่งั้นใบขายที่รับเงินแล้วทุกใบจะถูกล็อกอัตโนมัติ)
        var hasDownstream = await _db.Documents.AsNoTracking().AnyAsync(d =>
            d.CompanyId == companyId && d.RelatedDocumentId == documentId
            && d.Status != DocumentStatus.Voided && !d.IsDeleted
            && !d.IsSettlementReceipt);
        if (hasDownstream)
            throw new InvalidOperationException(
                "มีเอกสารปลายทาง (เช่น ใบสำคัญจ่าย/ใบลดหนี้) อ้างเอกสารนี้แล้ว — " +
                "ยกเลิกเอกสารปลายทางก่อน หรือใช้วิธี void+ออกใบใหม่แทน");

        // หมายเหตุ: เดิมบล็อกเมื่อ "มีการรับ/จ่ายชำระแล้ว" — ไม่จำเป็นและทำให้ใบที่
        // เก็บเงินแล้วแก้ผังไม่ได้เลย. JE ของการชำระเงินแตะเฉพาะ เงินสด/ธนาคาร ↔
        // ลูกหนี้/เจ้าหนี้ ซึ่งไม่ใช่ผังของ "บรรทัดสินค้า/บริการ" ที่เครื่องมือนี้ย้าย
        // (ย้าย Dr ผังใหม่ / Cr ผังเก่า เท่ายอดฐานก่อน VAT) ⇒ ยอดค้างชำระ อายุหนี้
        // และการกระทบยอดธนาคารไม่เปลี่ยน. การเปลี่ยน "แหล่งเงิน" ที่กระทบการชำระ
        // จริง ๆ อยู่ที่ ReclassifyPaymentSourceAsync ซึ่งมี gate ของตัวเอง

        var inSubmittedReport = await _db.TaxReportLines.AsNoTracking().AnyAsync(l =>
            l.DocumentId == documentId
            && l.TaxReport.CompanyId == companyId
            && (l.TaxReport.Status == TaxReportStatus.Submitted
                || l.TaxReport.Status == TaxReportStatus.Filed));
        if (inSubmittedReport)
            throw new InvalidOperationException(
                "เอกสารอยู่ในรายงานภาษีที่ยื่นสรรพากรแล้ว — แก้ไม่ได้ " +
                "(ต้องออก ภพ.30 เพิ่มเติม/แก้ไขผ่าน amended return)");

        var hasSubmittedEtax = await _db.EtaxInvoices.AsNoTracking().AnyAsync(e =>
            e.DocumentId == documentId && e.SubmittedAt != null);
        if (hasSubmittedEtax)
            throw new InvalidOperationException(
                "เอกสารนี้ส่ง e-Tax XML ไปสรรพากรแล้ว — แก้ไม่ได้");

        var line = doc.Lines.FirstOrDefault(l => l.Id == lineId)
            ?? throw new KeyNotFoundException("ไม่พบบรรทัดในเอกสาร");
        if (!line.AccountId.HasValue)
            throw new InvalidOperationException(
                "บรรทัดนี้ไม่มีผังบัญชีเดิม — กรอกผัง + reapprove แทน");
        if (line.AccountId.Value == newAccountId)
            return await GetDocumentAsync(companyId, documentId);   // no-op

        var newAccount = await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
            a.Id == newAccountId && a.CompanyId == companyId && a.IsActive)
            ?? throw new InvalidOperationException("ผังบัญชีใหม่ไม่มีในระบบหรือถูกปิดใช้");
        var oldAccount = await _db.ChartOfAccounts.AsNoTracking()
            .FirstOrDefaultAsync(a => a.Id == line.AccountId.Value)
            ?? throw new InvalidOperationException("ไม่พบผังบัญชีเดิม");

        // บัญชีคุมที่ระบบอื่นยึดเป็นความจริง — ย้ายเข้า/ออกแล้วรายงานจะเพี้ยนเงียบ ๆ
        // (ภาษีซื้อ/ขาย → ภ.พ.30 · ลูกหนี้/เจ้าหนี้ → อายุหนี้/ยอดค้าง · มัดจำ →
        // ยอดคงเหลือมัดจำ) การแก้ที่ถูกของบัญชีพวกนี้คือแก้ที่เอกสาร/เครื่องมือเฉพาะ
        if (IsReclassifyProtectedAccount(oldAccount.AccountCode))
            throw new InvalidOperationException(
                $"บรรทัดนี้ลงบัญชีคุม {oldAccount.AccountCode} {oldAccount.AccountName} — " +
                "ย้ายด้วยเครื่องมือนี้ไม่ได้ (กระทบรายงานภาษี/ยอดค้างชำระ)");
        if (IsReclassifyProtectedAccount(newAccount.AccountCode))
            throw new InvalidOperationException(
                $"ห้ามย้ายเข้าบัญชีคุม {newAccount.AccountCode} {newAccount.AccountName} — " +
                "บัญชีภาษี/ลูกหนี้/เจ้าหนี้/มัดจำ ระบบลงให้เองตามเอกสาร");

        // ยอดที่บรรทัดนี้ "ลงไว้จริง" ในแยกประเภท — ไม่ใช่ฐานก่อน VAT เสมอ (P-6)
        var amount = await ResolveLinePostedGlAmountAsync(companyId, doc, line);
        if (amount <= 0.005m)
        {
            // line ที่ Amount=0 ไม่กระทบ GL — แค่อัปเดต field ก็พอ
            line.AccountId = newAccountId;
            await _db.SaveChangesAsync();
            return await GetDocumentAsync(companyId, documentId);
        }

        // ทิศของ JE ย้ายบัญชีต้อง **กลับด้านที่ลงไว้จริง** ไม่ใช่สมมติว่าเป็นค่าใช้จ่าย
        // เสมอ: บรรทัดค่าใช้จ่ายเดิมลง Dr ⇒ ย้าย = Dr ใหม่ / Cr เก่า · บรรทัดรายได้
        // เดิมลง Cr ⇒ ย้าย = Dr เก่า / Cr ใหม่. ถ้าใช้สูตรเดียวกันทั้งคู่ ใบขายจะกลาย
        // เป็นรายได้เดิมเพิ่มเป็นสองเท่าและบัญชีใหม่ติดลบ (ที่มา: หลัก "อ่านขาที่ลง
        // จริงใน GL แล้วกลับตามนั้น" เหมือน drives รอบ 57 — ห้ามเดาจากชนิดเอกสาร)
        var oldSide = await _db.JournalEntryLines.AsNoTracking()
            .Where(l => l.AccountId == oldAccount.Id
                && l.JournalEntry.CompanyId == companyId
                && l.JournalEntry.SourceDocumentId == documentId
                && l.JournalEntry.Status == JournalEntryStatus.Posted
                && !l.JournalEntry.IsDeleted)
            .GroupBy(l => 1)
            .Select(g => new { Debit = g.Sum(x => x.DebitAmount), Credit = g.Sum(x => x.CreditAmount) })
            .FirstOrDefaultAsync();

        // หา JE ไม่เจอ (ใบเก่า/ลงผ่าน integration) → ตกกลับใช้ธรรมชาติของผังบัญชี
        var oldWasCredited = oldSide != null
            ? oldSide.Credit > oldSide.Debit
            : oldAccount.AccountType is AccountType.Revenue or AccountType.Liability or AccountType.Equity;

        await using var tx = await _db.Database.BeginTransactionAsync();
        try
        {
            // Strangler Fig: migrated to JournalEntryBuilder
            // (เดิม construct JournalEntry + 2 lines + balance check manual)
            var desc = $"Reclassify ผังบัญชี — {doc.DocumentNumber} " +
                       $"'{line.Description}' ({oldAccount.AccountCode} → {newAccount.AccountCode})" +
                       (string.IsNullOrWhiteSpace(reason) ? "" : $" • {reason}");
            var builder = Journal.JournalEntryBuilder
                .For(_db, companyId, doc.DocumentDate)
                .Description(desc)
                .Reference(doc.DocumentNumber)
                .SourceDocument(doc.Id)
                .Project(doc.ProjectId);
            builder = oldWasCredited
                // เดิมลงฝั่ง Cr (รายได้/หนี้สิน) → ล้างด้วย Dr ผังเก่า แล้ว Cr ผังใหม่
                ? builder
                    .Debit(oldAccount.Id, amount, $"Dr {oldAccount.AccountCode} — {oldAccount.AccountName} (reclassify)")
                    .Credit(newAccount.Id, amount, $"Cr {newAccount.AccountCode} — {newAccount.AccountName}")
                // เดิมลงฝั่ง Dr (ค่าใช้จ่าย/สินทรัพย์) → Dr ผังใหม่ / Cr ผังเก่า
                : builder
                    .Debit(newAccount.Id, amount, $"Dr {newAccount.AccountCode} — {newAccount.AccountName}")
                    .Credit(oldAccount.Id, amount, $"Cr {oldAccount.AccountCode} — {oldAccount.AccountName} (reclassify)");
            await builder.PostAsync(actor);

            line.AccountId = newAccountId;
            doc.UpdatedAt = DateTime.UtcNow;
            doc.UpdatedBy = actor;
            await _db.SaveChangesAsync();
            await tx.CommitAsync();
        }
        catch
        {
            await tx.RollbackAsync();
            throw;
        }

        _logger.LogInformation(
            "Reclassified line {LineId} of {DocNumber}: {OldCode} → {NewCode} by {Actor}",
            lineId, doc.DocumentNumber, oldAccount.AccountCode, newAccount.AccountCode, actor);

        return await GetDocumentAsync(companyId, documentId);
    }

    /// <summary>
    /// เปลี่ยน "แหล่งเงิน" (บัญชี Cr เงินสด/ธนาคาร) ของเอกสารจ่าย/รับสดที่
    /// <summary>ย้าย "ฝั่ง" ของใบลดหนี้/ใบเพิ่มหนี้ (ซื้อ ↔ ขาย) หลังอนุมัติแล้ว
    ///
    /// <para><b>ทำไมต้องมี:</b> CN/DN ที่อ้างเลขใบกำกับนอกระบบ (ผู้ขายพิมพ์เลขของ
    /// เขามาในช่อง "อ้างอิง") อาจถูกจัดฝั่งผิดตั้งแต่ตอนอนุมัติ → JE ลง Dr 21911
    /// (ลดภาษีขาย) แทน Cr 11610 (ลดภาษีซื้อ). รายงาน ภ.พ.30 <b>ยึด GL เป็นความจริง</b>
    /// จึงตามไปแสดงในรายงานภาษีขายด้วย และการกด "สร้างรายงานใหม่" ไม่ช่วย เพราะ
    /// รายงานไม่ได้ผิด — GL ต่างหากที่ผิด</para>
    ///
    /// <para><b>วิธีแก้ที่ถูก:</b> กลับ JE เดิมทั้งใบ → ตั้งค่า override → ลง JE ใหม่
    /// ให้ถูกฝั่ง. ผลคือ GL กับรายงานตรงกันเสมอ (ถ้าย้ายแต่ตัวเลขในรายงาน งบการเงิน
    /// กับแบบยื่นภาษีจะขัดกันเอง ตรวจสอบย้อนหลังไม่ได้ — ห้ามทำ)</para>
    ///
    /// ผ่าน gate ชุดเดียวกับ reclassify อื่น: งวดบัญชียังเปิด, ไม่มีเอกสารปลายทาง,
    /// ยังไม่อยู่ในรายงานภาษีที่ยื่นแล้ว, ยังไม่ได้ส่ง e-Tax
    /// </summary>
    /// <summary>
    /// **ติ๊ก/ปลดติ๊ก "ซื้อบริการจากต่างประเทศ (ภ.พ.36 §83/6)" ของเอกสารที่อนุมัติไปแล้ว**
    /// — กลับ JE เดิมทั้งหมดแล้วลงใหม่ผ่าน <c>AutoPostToJournalAsync</c> ตัวเดิม
    /// (ไม่ใช่ปะตัวเลขในรายงาน — ไม่งั้น GL กับแบบยื่นภาษีจะขัดกันเอง)
    ///
    /// <para>ที่มา (ผู้ใช้ส่งภาพ 2026-09-21): ใบสำคัญจ่ายค่าคอมมิชชั่น Booking.com
    /// สองใบของคู่ค้าเดียวกัน ใบหนึ่งติ๊ก ใบหนึ่งไม่ติ๊ก ⇒ ใบที่ไม่ติ๊ก**ไม่มี
    /// <c>Cr 21912</c>** และเครดิตผู้รับเงินด้วยยอดรวม VAT · วันนี้ระบบ**ไม่มีทาง
    /// แก้เลย**: <c>UpdateDocumentAsync</c> แก้ได้เฉพาะก่อนอนุมัติ · เส้น §86/4
    /// (<c>CompleteSupplierTaxInvoiceAsync</c>) ปิดอยู่เพราะผู้ขายต่างประเทศไม่มี
    /// เลขภาษีไทย · เส้นปลดล็อก ภ.พ.36 อ่าน <c>IsForeignService</c> ซึ่งยังเป็น false
    /// ⇒ ภาษีซื้อค้าง 11640 จนงาน §82/3 โยนเป็นค่าใช้จ่ายเมื่อครบ 6 เดือน</para>
    ///
    /// <para>ใช้ gate ชุดเดียวกับ <see cref="ReclassifyCnDnSideAsync"/> ทุกข้อ เพราะ
    /// เป็น operation ทรงเดียวกัน (กลับ JE ทั้งใบ → ลงใหม่) · เพิ่มเฉพาะเงื่อนไข
    /// ของ §83/6 เอง: ต้องมี VAT · ห้ามโหมดราคารวมภาษี · และห้ามทำหลังจาก
    /// ภาษีซื้อของใบนี้ถูกย้ายออกจาก 11640 ไปแล้ว (เคลมแล้ว/หมดอายุแล้ว) ซึ่ง
    /// การลง JE ใหม่จะทำให้ 11640 กับ 11610 เพี้ยนทั้งคู่</para>
    /// </summary>
    public async Task<DocumentResponse> ReclassifyForeignServiceAsync(
        Guid companyId, Guid documentId, bool toForeignService, string? reason, string actor)
    {
        var doc = await _db.Documents.Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        // ชนิดที่ `IsForeignService` มีความหมาย — ตรงกับชนิดที่ `AutoPostToJournalAsync`
        // เดิน `ForeignServiceVat.SplitCredit` จริง (สาย PI/Expense และสาย PV)
        if (doc.DocumentType is not (DocumentType.PurchaseInvoice
            or DocumentType.Expense or DocumentType.PaymentVoucher))
            throw new InvalidOperationException(
                "ตั้งเป็นบริการต่างประเทศได้เฉพาะใบแจ้งหนี้ซื้อ · ค่าใช้จ่าย · ใบสำคัญจ่าย");

        if (doc.IsForeignService == toForeignService)
            throw new InvalidOperationException(
                $"เอกสารนี้{(toForeignService ? "เป็นบริการต่างประเทศ" : "ไม่ได้เป็นบริการต่างประเทศ")}อยู่แล้ว");

        if (doc.Status is DocumentStatus.Draft or DocumentStatus.Voided
                       or DocumentStatus.Rejected or DocumentStatus.WaitingApproval)
            throw new InvalidOperationException(
                $"เอกสารสถานะ {doc.Status} ยังไม่ได้ลงบัญชี — ติ๊กช่อง \"ซื้อบริการจากต่างประเทศ\" "
                + "ที่ฟอร์มปกติแล้วค่อยอนุมัติ (ไม่ต้องใช้เมนูนี้)");

        // ── เงื่อนไขเฉพาะของ §83/6 (ตรงกับด่านตอนอนุมัติ ไม่ใช่กติกาชุดที่สอง) ──
        if (toForeignService && doc.VatAmount <= 0)
            throw new InvalidOperationException(
                "ใบนี้ไม่มี VAT — ภ.พ.36 ต้องประเมิน VAT 7% จากยอดจ่ายเสมอ "
                + "(ผู้ขายต่างประเทศไม่คิด VAT มา เราประเมินเองเพื่อนำส่ง). "
                + "ใบที่ไม่มี VAT ต้องยกเลิกแล้วออกใหม่พร้อม VAT 7%");
        if (toForeignService && doc.PricesIncludeVat)
            throw new InvalidOperationException(
                "ใบนี้ใช้โหมด \"ราคารวมภาษี\" ซึ่งใช้กับใบบริการต่างประเทศไม่ได้ — "
                + "ยอดที่จ่ายผู้ขายต่างประเทศไม่มี VAT ไทยปนอยู่ ต้องยกเลิกใบแล้วออกใหม่"
                + "โดยปลดโหมดราคารวมภาษี");

        // ภาษีซื้อของใบนี้ถูกย้ายออกจากที่พักไปแล้ว — ลง JE ใหม่จะทำให้ทั้ง 11640
        // และปลายทาง (11610 หรือค่าใช้จ่าย) เพี้ยนพร้อมกัน เพราะ AutoPost ลงเฉพาะ
        // JE ของใบหลัก ไม่รู้จัก JE ปรับปรุงที่เกิดทีหลัง
        if (doc.InputVatBecameClaimableAt.HasValue)
            throw new InvalidOperationException(
                "ภาษีซื้อของใบนี้ถูกย้ายไปเป็น \"เคลมได้\" (11610) แล้ว — ต้องกลับรายการ"
                + "การเคลมก่อน แล้วค่อยเปลี่ยนเป็นบริการต่างประเทศ");
        if (doc.InputVatExpiredAt.HasValue)
            throw new InvalidOperationException(
                "ภาษีซื้อของใบนี้พ้น 6 เดือน (§82/3) และถูกโยนเป็นค่าใช้จ่ายไปแล้ว — "
                + "เปลี่ยนเป็นบริการต่างประเทศย้อนหลังไม่ได้ ต้องปรับด้วยใบสำคัญทั่วไป");

        // ===== gate ชุดเดียวกับ ReclassifyCnDnSideAsync ทุกข้อ =====
        var period = await _db.FiscalPeriods.FirstOrDefaultAsync(p =>
            p.CompanyId == companyId
            && p.StartDate <= doc.DocumentDate && p.EndDate >= doc.DocumentDate);
        if (period != null && period.Status != FiscalPeriodStatus.Open)
            throw new InvalidOperationException(
                $"วันที่เอกสารอยู่ในงวด '{period.Name}' ที่ปิดแล้ว ({period.Status}) — แก้ไม่ได้");

        var hasDownstream = await _db.Documents.AsNoTracking().AnyAsync(d =>
            d.CompanyId == companyId && d.RelatedDocumentId == documentId
            && d.Status != DocumentStatus.Voided && !d.IsDeleted);
        if (hasDownstream)
            throw new InvalidOperationException(
                "มีเอกสารปลายทางอ้างเอกสารนี้แล้ว — ยกเลิกเอกสารปลายทางก่อน");

        // ขั้นที่ 1 กลับ "ทุก JE ที่ผูกเอกสารนี้" ซึ่งรวม **JE การชำระเงิน** แต่
        // ขั้นที่ 2 (AutoPost) ลงคืนเฉพาะ JE ใบหลัก ⇒ เงินที่จ่ายจริงหายจาก GL
        // (เหตุผลเดียวกับ ReclassifyCnDnSide/ReclassifyPaymentSource)
        var hasPayments = await _db.Payments.AsNoTracking().AnyAsync(p =>
            p.CompanyId == companyId && p.DocumentId == documentId && !p.IsDeleted);
        if (hasPayments)
            throw new InvalidOperationException(
                "เอกสารนี้มีรายการจ่ายชำระแยกอยู่ — เปลี่ยนแล้วรายการชำระจะหายจากบัญชี "
                + "กรุณายกเลิกการชำระก่อน แล้วค่อยเปลี่ยน");

        var inSubmittedReport = await _db.TaxReportLines.AsNoTracking().AnyAsync(l =>
            l.DocumentId == documentId && l.TaxReport.CompanyId == companyId
            && (l.TaxReport.Status == TaxReportStatus.Submitted
                || l.TaxReport.Status == TaxReportStatus.Filed));
        if (inSubmittedReport)
            throw new InvalidOperationException(
                "เอกสารอยู่ในรายงานภาษีที่ยื่นสรรพากรแล้ว — ต้องยื่นแบบเพิ่มเติมแทนการแก้ใบ");

        var hasSubmittedEtax = await _db.EtaxInvoices.AsNoTracking().AnyAsync(e =>
            e.DocumentId == documentId && e.SubmittedAt != null);
        if (hasSubmittedEtax)
            throw new InvalidOperationException("เอกสารนี้ส่ง e-Tax XML ไปสรรพากรแล้ว — แก้ไม่ได้");

        var label = toForeignService ? "บริการต่างประเทศ (ภ.พ.36 §83/6)" : "ซื้อในประเทศ";

        using var txn = await _db.Database.BeginTransactionAsync();
        try
        {
            var postedJeIds = await _db.JournalEntries
                .Where(j => j.CompanyId == companyId && j.SourceDocumentId == documentId
                    && !j.IsDeleted && j.Status == JournalEntryStatus.Posted
                    && j.OriginalEntryId == null && j.ReversedByEntryId == null)
                .Select(j => j.Id).ToListAsync();
            foreach (var jeId in postedJeIds)
                // วันที่ตัวกลับ = **วันที่เอกสารเอง** ให้ตรงกับ JE ใหม่ที่ AutoPost
                // จะลงที่ `doc.DocumentDate` (ถ้าตกวันนี้ งวดของเอกสารจะมีทั้งเก่า
                // และใหม่พร้อมกัน และงวดปัจจุบันมียอดกลับลอย)
                await _accountingService.ReverseJournalEntryAsync(companyId, jeId,
                    reversalDate: doc.DocumentDate.Date,
                    description: $"เปลี่ยนการลงบัญชี {doc.DocumentNumber} → {label}",
                    systemTriggered: true);

            doc.IsForeignService = toForeignService;
            // ภาษีซื้อของ ภ.พ.36 บังคับพักที่ 11640 เสมอ — override ที่ผู้ใช้เคยปัก
            // ไว้เองต้องถูกล้าง ไม่งั้น AutoPost จะลงตามค่าที่ปักแทนกติกา §83/6
            // (ในภาพของผู้ใช้ ใบที่ผิดมี override = "11640" ซึ่งบังเอิญตรงผัง แต่
            //  เป็นคนละเหตุผล และถ้าปักเป็นผังอื่นไว้จะลงผิดทันที)
            if (toForeignService) doc.InputVatAccountCodeOverride = null;
            await _db.SaveChangesAsync();
            await AutoPostToJournalAsync(companyId, doc, actor);
            await _db.SaveChangesAsync();

            _db.AuditLogs.Add(new AuditLog
            {
                CompanyId = companyId,
                Action = AuditAction.Update,
                EntityType = "Document",
                EntityId = documentId.ToString(),
                NewValues = System.Text.Json.JsonSerializer.Serialize(new
                {
                    action = "ReclassifyForeignService",
                    documentNumber = doc.DocumentNumber,
                    toForeignService,
                    ruleCode = Accounting.Helpers.ForeignServiceEvidence.RuleCode,
                    legalReference = Accounting.Helpers.ForeignServiceEvidence.LegalReference,
                    vatAmount = doc.VatAmount,
                    reason,
                    actor,
                }),
                Timestamp = DateTime.UtcNow,
            });
            await _db.SaveChangesAsync();
            await txn.CommitAsync();
        }
        catch
        {
            await txn.RollbackAsync();
            throw;
        }

        _logger.LogInformation("เอกสาร {Doc} เปลี่ยนเป็น {Label} โดย {Actor}",
            doc.DocumentNumber, label, actor);
        return await GetDocumentAsync(companyId, documentId);
    }

    public async Task<DocumentResponse> ReclassifyCnDnSideAsync(
        Guid companyId, Guid documentId, bool toPurchaseSide, string? reason, string actor)
    {
        var doc = await _db.Documents.Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        if (doc.DocumentType is not (DocumentType.CreditNote or DocumentType.DebitNote))
            throw new InvalidOperationException("ย้ายฝั่งได้เฉพาะใบลดหนี้/ใบเพิ่มหนี้");

        if (doc.Status is DocumentStatus.Draft or DocumentStatus.Voided
                       or DocumentStatus.Rejected or DocumentStatus.WaitingApproval)
            throw new InvalidOperationException(
                $"เอกสารสถานะ {doc.Status} ยังไม่ได้ลงบัญชี — แก้ที่ฟอร์มปกติ (เลือกใบต้นทางให้ถูก) แล้วค่อยอนุมัติ");

        // ===== gate ชุดเดียวกับ reclassify แหล่งเงิน/ผังบัญชี =====
        var period = await _db.FiscalPeriods.FirstOrDefaultAsync(p =>
            p.CompanyId == companyId
            && p.StartDate <= doc.DocumentDate && p.EndDate >= doc.DocumentDate);
        if (period != null && period.Status != FiscalPeriodStatus.Open)
            throw new InvalidOperationException(
                $"วันที่เอกสารอยู่ในงวด '{period.Name}' ที่ปิดแล้ว ({period.Status}) — ย้ายฝั่งไม่ได้");

        var hasDownstream = await _db.Documents.AsNoTracking().AnyAsync(d =>
            d.CompanyId == companyId && d.RelatedDocumentId == documentId
            && d.Status != DocumentStatus.Voided && !d.IsDeleted);
        if (hasDownstream)
            throw new InvalidOperationException(
                "มีเอกสารปลายทางอ้างเอกสารนี้แล้ว — ยกเลิกเอกสารปลายทางก่อน");

        // ⚠️ ใบที่รับ/จ่ายชำระแล้ว: ขั้นที่ 1 ด้านล่างกลับ "ทุก JE ที่ผูกเอกสารนี้"
        // ซึ่งรวม **JE การชำระเงิน** (SourceDocumentId = doc, OriginalEntryId = null)
        // แต่ขั้นที่ 2 (AutoPost) ลงคืนเฉพาะ JE ใบหลัก ⇒ เงินที่รับ/จ่ายจริงหาย
        // จาก GL ถาวร ขณะที่ Payment row + PaidAmount ยังอยู่เต็ม (subledger ว่า
        // จ่ายแล้ว / GL ว่ายังค้าง). ใช้ guard เดียวกับ ReclassifyPaymentSourceAsync
        var hasPayments = await _db.Payments.AsNoTracking().AnyAsync(p =>
            p.CompanyId == companyId && p.DocumentId == documentId && !p.IsDeleted);
        if (hasPayments)
            throw new InvalidOperationException(
                "เอกสารนี้มีการรับ/จ่ายชำระแล้ว — ย้ายฝั่งจะทำให้รายการชำระหายจากบัญชี " +
                "กรุณายกเลิกการชำระก่อน แล้วค่อยย้ายฝั่ง");

        var inSubmittedReport = await _db.TaxReportLines.AsNoTracking().AnyAsync(l =>
            l.DocumentId == documentId && l.TaxReport.CompanyId == companyId
            && (l.TaxReport.Status == TaxReportStatus.Submitted
                || l.TaxReport.Status == TaxReportStatus.Filed));
        if (inSubmittedReport)
            throw new InvalidOperationException(
                "เอกสารอยู่ในรายงานภาษีที่ยื่นสรรพากรแล้ว — ต้องยื่นแบบเพิ่มเติมแทนการย้ายฝั่ง");

        var hasSubmittedEtax = await _db.EtaxInvoices.AsNoTracking().AnyAsync(e =>
            e.DocumentId == documentId && e.SubmittedAt != null);
        if (hasSubmittedEtax)
            throw new InvalidOperationException("เอกสารนี้ส่ง e-Tax XML ไปสรรพากรแล้ว — ย้ายฝั่งไม่ได้");

        if (doc.CnDnPurchaseSideOverride == toPurchaseSide)
            throw new InvalidOperationException(
                $"เอกสารนี้ถูกกำหนดเป็นฝั่ง{(toPurchaseSide ? "ซื้อ" : "ขาย")}อยู่แล้ว");

        var sideLabel = toPurchaseSide ? "ซื้อ (ลดภาษีซื้อ)" : "ขาย (ลดภาษีขาย)";

        using var txn = await _db.Database.BeginTransactionAsync();
        try
        {
            // 1) กลับ JE เดิมของเอกสารนี้ทั้งหมด (เฉพาะตัวจริง ไม่ใช่ตัว reversal)
            var postedJeIds = await _db.JournalEntries
                .Where(j => j.SourceDocumentId == documentId && j.CompanyId == companyId
                    && j.Status == JournalEntryStatus.Posted
                    && j.OriginalEntryId == null && j.ReversedByEntryId == null)
                .Select(j => j.Id).ToListAsync();
            foreach (var jeId in postedJeIds)
            {
                // วันที่ตัวกลับต้องเป็น **วันที่เอกสารเอง** ไม่ใช่วันที่กด — ขั้นที่ 2
                // ลง JE ใหม่ที่ doc.DocumentDate เสมอ (AutoPost) ถ้าตัวกลับไปตกวันนี้
                // งวดของเอกสารจะมีทั้ง JE เก่าและใหม่พร้อมกัน (ผิด +ยอดทั้งใบ) และ
                // งวดปัจจุบันมียอดกลับลอย (ผิด −ยอดทั้งใบ) — บทเรียนรอบ 60 ที่
                // VoidDocumentAsync แก้ไปแล้ว แต่เส้นนี้เขียนทีหลังและพลาดซ้ำ
                await _accountingService.ReverseJournalEntryAsync(companyId, jeId,
                    reversalDate: doc.DocumentDate.Date,
                    description: $"ย้ายฝั่งใบลดหนี้/เพิ่มหนี้ {doc.DocumentNumber} → ฝั่ง{sideLabel}",
                    systemTriggered: true);
            }

            // 2) ตั้ง override แล้วลง JE ใหม่ให้ถูกฝั่ง (AutoPost อ่าน override เป็นชั้นแรก)
            doc.CnDnPurchaseSideOverride = toPurchaseSide;
            await _db.SaveChangesAsync();
            await AutoPostToJournalAsync(companyId, doc, actor);
            await _db.SaveChangesAsync();

            // 3) audit — append-only ตาม cross-cutting invariant (CLAUDE.md §M)
            _db.AuditLogs.Add(new AuditLog
            {
                CompanyId = companyId,
                Action = AuditAction.Update,
                EntityType = "Document",
                EntityId = documentId.ToString(),
                NewValues = System.Text.Json.JsonSerializer.Serialize(new
                {
                    action = "ReclassifyCnDnSide",
                    documentNumber = doc.DocumentNumber,
                    toPurchaseSide,
                    sideLabel,
                    reason,
                    actor,
                }),
                Timestamp = DateTime.UtcNow,
            });
            await _db.SaveChangesAsync();
            await txn.CommitAsync();
        }
        catch
        {
            await txn.RollbackAsync();
            throw;
        }

        _logger.LogInformation("CN/DN {Doc} ย้ายฝั่งเป็น {Side} โดย {Actor}",
            doc.DocumentNumber, sideLabel, actor);
        return await GetDocumentAsync(companyId, documentId);
    }

    /// approve แล้ว — คู่กับ ReclassifyLineAccountAsync (ที่แก้ฝั่ง Dr). ใช้แก้
    /// เคส OCR/auto-create เลือกธนาคารผิด (กรุงไทย → กสิกร) โดยไม่ต้อง void.
    /// ระบบ post correcting-JE: Dr {ผังเก่า} / Cr {ผังใหม่} ขนาด = PaidAmount
    /// (เงินสดที่จ่ายจริง = ยอดที่ลง Cr บัญชีแหล่งเงินเดิม) → เงินกลับเข้าบัญชี
    /// เก่า + ออกจากบัญชีใหม่. trial balance ก่อน-หลังตรง. ผ่าน gate เดียวกับ
    /// reclassify-line (FiscalPeriod=Open, ไม่มีเอกสารปลายทาง, ไม่มี Payment
    /// แยก, ไม่อยู่ TaxReport=Submitted, ไม่ได้ส่ง e-Tax).
    ///
    /// แหล่งเงินใหม่ระบุได้ทางใดทางหนึ่ง: newBankAccountId (บัญชีธนาคาร →
    /// ใช้ LinkedAccountId เป็น Cr GL) หรือ newPaymentAccountId (ChartOfAccount
    /// ตรง ๆ เช่นเงินสด 1111 / เงินทดรองกรรมการ).
    /// </summary>
    public async Task<DocumentResponse> ReclassifyPaymentSourceAsync(
        Guid companyId, Guid documentId,
        Guid? newBankAccountId, Guid? newPaymentAccountId,
        string? reason, string actor)
    {
        var doc = await _db.Documents
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        if (!newBankAccountId.HasValue && !newPaymentAccountId.HasValue)
            throw new InvalidOperationException("กรุณาเลือกแหล่งเงินใหม่ (บัญชีธนาคารหรือบัญชีเงินสด)");

        // เฉพาะเอกสารที่ "มีแหล่งเงิน" อยู่แล้ว (จ่าย/รับสด). เอกสาร A/P-A/R
        // ที่ Cr เป็นเจ้าหนี้/ลูกหนี้ ไม่มีแหล่งเงินให้แก้ตรงนี้ (เงินไหลตอน
        // PV/Receipt ปลายทาง) → แก้ที่เอกสารปลายทางแทน.
        if (!doc.BankAccountId.HasValue && !doc.PaymentAccountId.HasValue)
            throw new InvalidOperationException(
                "เอกสารนี้ไม่มีแหล่งเงิน (บัญชี Cr เงินสด/ธนาคาร) ที่ระบุไว้ — " +
                "ถ้าเป็นใบตั้งหนี้ เงินจะไหลตอนสร้างใบสำคัญจ่าย ให้แก้แหล่งเงินที่ใบนั้น");

        // WaitingApproval เช่นกัน — ยังไม่มี JE ให้แก้ (ดูเหตุผลเต็มที่ reclassify-line)
        if (doc.Status is DocumentStatus.Draft or DocumentStatus.Voided
                       or DocumentStatus.Rejected or DocumentStatus.WaitingApproval)
            throw new InvalidOperationException(
                $"เอกสาร Status={doc.Status} ไม่อยู่ในขั้นที่แก้แหล่งเงินแบบ reclassify ได้ " +
                "(Draft/รออนุมัติ = แก้ผ่านฟอร์มปกติ, Voided/Rejected = สร้างใหม่)");

        // ===== gate compliance เดียวกับ reclassify-line =====
        var period = await _db.FiscalPeriods.FirstOrDefaultAsync(p =>
            p.CompanyId == companyId
            && p.StartDate <= doc.DocumentDate && p.EndDate >= doc.DocumentDate);
        if (period != null && period.Status != FiscalPeriodStatus.Open)
            throw new InvalidOperationException(
                $"วันที่เอกสารอยู่ในงวด '{period.Name}' ที่ปิดแล้ว ({period.Status}) — แก้แหล่งเงินไม่ได้");

        var hasDownstream = await _db.Documents.AsNoTracking().AnyAsync(d =>
            d.CompanyId == companyId && d.RelatedDocumentId == documentId
            && d.Status != DocumentStatus.Voided && !d.IsDeleted);
        if (hasDownstream)
            throw new InvalidOperationException(
                "มีเอกสารปลายทางอ้างเอกสารนี้แล้ว — ยกเลิกเอกสารปลายทางก่อน หรือ void+ออกใหม่");

        // มี Payment แยก = เงินไหลผ่าน JE ของ Payment ไม่ใช่ JE ของเอกสารนี้ →
        // แก้แหล่งเงินต้องไปแก้ที่ Payment แทน (กัน JE คู่ใหม่ไม่ตรงของจริง).
        var hasPayments = await _db.Payments.AsNoTracking().AnyAsync(p =>
            p.CompanyId == companyId && p.DocumentId == documentId && !p.IsDeleted);
        if (hasPayments)
            throw new InvalidOperationException(
                "เอกสารนี้มีรายการชำระเงินแยก — กรุณาแก้แหล่งเงินที่รายการชำระนั้น");

        var inSubmittedReport = await _db.TaxReportLines.AsNoTracking().AnyAsync(l =>
            l.DocumentId == documentId && l.TaxReport.CompanyId == companyId
            && (l.TaxReport.Status == TaxReportStatus.Submitted
                || l.TaxReport.Status == TaxReportStatus.Filed));
        if (inSubmittedReport)
            throw new InvalidOperationException(
                "เอกสารอยู่ในรายงานภาษีที่ยื่นสรรพากรแล้ว — แก้ไม่ได้");

        var hasSubmittedEtax = await _db.EtaxInvoices.AsNoTracking().AnyAsync(e =>
            e.DocumentId == documentId && e.SubmittedAt != null);
        if (hasSubmittedEtax)
            throw new InvalidOperationException("เอกสารนี้ส่ง e-Tax XML ไปสรรพากรแล้ว — แก้ไม่ได้");

        // ── Resolve Cr GL เดิม + ใหม่ ──
        // BankAccount → LinkedAccountId เป็น GL; PaymentAccountId เป็น GL ตรง.
        async Task<(Guid Id, string Code, string Name)> ResolveCreditGlAsync(
            Guid? bankAccountId, Guid? paymentAccountId, string side)
        {
            Guid? glId = paymentAccountId;
            if (!glId.HasValue && bankAccountId.HasValue)
            {
                glId = await _db.BankAccounts.AsNoTracking()
                    .Where(b => b.Id == bankAccountId.Value && b.CompanyId == companyId)
                    .Select(b => b.LinkedAccountId)
                    .FirstOrDefaultAsync();
                if (!glId.HasValue)
                    throw new InvalidOperationException(
                        $"บัญชีธนาคาร ({side}) ยังไม่ได้ผูกผังบัญชี (LinkedAccountId) — ตั้งค่าก่อน");
            }
            if (!glId.HasValue)
                throw new InvalidOperationException($"หาแหล่งเงิน ({side}) ไม่เจอ");
            var acct = await _db.ChartOfAccounts.AsNoTracking()
                .Where(a => a.Id == glId.Value && a.CompanyId == companyId)
                .Select(a => new { a.Id, a.AccountCode, a.AccountName })
                .FirstOrDefaultAsync()
                ?? throw new InvalidOperationException($"ไม่พบผังบัญชีแหล่งเงิน ({side})");
            return (acct.Id, acct.AccountCode, acct.AccountName);
        }

        var oldGl = await ResolveCreditGlAsync(doc.BankAccountId, doc.PaymentAccountId, "เดิม");
        var newGl = await ResolveCreditGlAsync(newBankAccountId, newPaymentAccountId, "ใหม่");

        if (oldGl.Id == newGl.Id)
        {
            // GL ปลายทางเดียวกัน (เช่นสลับบัญชีธนาคารที่ผูก GL เดียวกัน) →
            // ไม่ต้อง post JE แค่อัปเดต field อ้างอิง.
            doc.BankAccountId = newBankAccountId;
            doc.PaymentAccountId = newPaymentAccountId;
            doc.UpdatedAt = DateTime.UtcNow;
            doc.UpdatedBy = actor;
            await _db.SaveChangesAsync();
            return await GetDocumentAsync(companyId, documentId);
        }

        // เงินที่ลง Cr บัญชีแหล่งเงินเดิม = เงินสดจ่ายจริง = PaidAmount.
        var amount = doc.PaidAmount;
        if (amount <= 0.005m)
        {
            // ยังไม่ได้จ่ายจริง (ไม่กระทบ GL แหล่งเงิน) → แค่อัปเดต field.
            doc.BankAccountId = newBankAccountId;
            doc.PaymentAccountId = newPaymentAccountId;
            doc.UpdatedAt = DateTime.UtcNow;
            doc.UpdatedBy = actor;
            await _db.SaveChangesAsync();
            return await GetDocumentAsync(companyId, documentId);
        }

        await using var tx = await _db.Database.BeginTransactionAsync();
        try
        {
            // Correcting JE: Dr {old} / Cr {new} — เงินกลับเข้าบัญชีเก่า +
            // ออกจากบัญชีใหม่. (กลับทิศกับ reclassify-line เพราะแก้ฝั่ง Cr).
            var desc = $"เปลี่ยนแหล่งเงิน — {doc.DocumentNumber} " +
                       $"({oldGl.Code} → {newGl.Code})" +
                       (string.IsNullOrWhiteSpace(reason) ? "" : $" • {reason}");
            await Journal.JournalEntryBuilder
                .For(_db, companyId, doc.DocumentDate)
                .Description(desc)
                .Reference(doc.DocumentNumber)
                .SourceDocument(doc.Id)
                .Project(doc.ProjectId)
                .Debit(oldGl.Id, amount, $"Dr {oldGl.Code} — {oldGl.Name} (คืนแหล่งเงินเดิม)")
                .Credit(newGl.Id, amount, $"Cr {newGl.Code} — {newGl.Name} (แหล่งเงินใหม่)")
                .PostAsync(actor);

            doc.BankAccountId = newBankAccountId;
            doc.PaymentAccountId = newPaymentAccountId;
            doc.UpdatedAt = DateTime.UtcNow;
            doc.UpdatedBy = actor;
            await _db.SaveChangesAsync();
            await tx.CommitAsync();
        }
        catch
        {
            await tx.RollbackAsync();
            throw;
        }

        // ── ปลดการกระทบยอดของบัญชีเดิม (M-8) ────────────────────────────────
        // เงินย้ายไปออกจากอีกบัญชีแล้ว แต่รายการเดินบัญชีของ**บัญชีเดิม**ที่เคย
        // จับคู่กับ JE ของเอกสารนี้ยังขึ้นสถานะ "กระทบยอดแล้ว" ⇒ งบกระทบยอด
        // ของบัญชีเดิมยังนับเงินก้อนที่ GL บอกว่าไม่เคยออกจากบัญชีนั้น และผู้ทำ
        // บัญชีจะจับคู่รายการจริงของบัญชีใหม่ไม่ได้. ปลดให้กลับไป Unmatched
        // เพื่อบังคับให้กระทบยอดใหม่กับบัญชีที่ถูก (defect class เดียวกับ M-2)
        try
        {
            var docJeIds = await _db.JournalEntries.AsNoTracking()
                .Where(j => j.CompanyId == companyId && j.SourceDocumentId == documentId && !j.IsDeleted)
                .Select(j => j.Id)
                .ToListAsync();
            if (docJeIds.Count > 0)
            {
                var staleTxnIds = await _db.BankTransactions
                    .Where(t => t.CompanyId == companyId
                        && t.MatchedJournalEntryId.HasValue
                        && docJeIds.Contains(t.MatchedJournalEntryId!.Value))
                    .Select(t => t.Id)
                    .ToListAsync();
                if (staleTxnIds.Count > 0)
                {
                    await _db.BankTransactions
                        .Where(t => staleTxnIds.Contains(t.Id))
                        .ExecuteUpdateAsync(s => s
                            .SetProperty(t => t.MatchedJournalEntryId, (Guid?)null)
                            .SetProperty(t => t.ReconciliationStatus, ReconciliationStatus.Unmatched)
                            .SetProperty(t => t.ReconciledAt, (DateTime?)null));
                    _logger.LogInformation(
                        "ปลดการกระทบยอด {Count} รายการของ {DocNumber} หลังเปลี่ยนแหล่งเงิน — ต้องจับคู่ใหม่กับบัญชี {NewCode}",
                        staleTxnIds.Count, doc.DocumentNumber, newGl.Code);
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex,
                "ปลดการกระทบยอดหลังเปลี่ยนแหล่งเงินของ {DocNumber} ไม่สำเร็จ — " +
                "ตรวจรายการเดินบัญชีของบัญชีเดิมด้วยมือ", doc.DocumentNumber);
        }

        _logger.LogInformation(
            "Reclassified payment source of {DocNumber}: {OldCode} → {NewCode} (amount {Amount}) by {Actor}",
            doc.DocumentNumber, oldGl.Code, newGl.Code, amount, actor);

        return await GetDocumentAsync(companyId, documentId);
    }

    // ===== Adjusting Journal Lines (Option 1) =====

    public async Task<List<DocumentAdjustingJournalLine>> ListAdjustingJournalLinesAsync(
        Guid companyId, Guid documentId)
    {
        var docExists = await _db.Documents.AsNoTracking()
            .AnyAsync(d => d.Id == documentId && d.CompanyId == companyId && !d.IsDeleted);
        if (!docExists) throw new KeyNotFoundException("ไม่พบเอกสาร");

        return await _db.Set<DocumentAdjustingJournalLine>()
            .AsNoTracking()
            .Where(a => a.DocumentId == documentId && !a.IsDeleted)
            .OrderBy(a => a.LineOrder)
            .ToListAsync();
    }

    public async Task<DocumentResponse> SaveAdjustingJournalLinesAsync(Guid companyId, Guid documentId,
        IEnumerable<(Guid AccountId, decimal DebitAmount, decimal CreditAmount,
            string? Description, Guid? ProjectId, string? Reason)> lines, string actor)
    {
        var doc = await _db.Documents
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId && !d.IsDeleted)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        // เฉพาะ Draft — หลัง approve JE ถูก post แล้ว ห้ามแก้ผ่าน flow นี้
        // (ใช้ ReclassifyLineAccountAsync หรือ manual JE แทน)
        if (doc.Status != DocumentStatus.Draft)
            throw new InvalidOperationException(
                $"เอกสารต้องเป็นฉบับร่าง (Draft) ถึงจะแก้ adjusting lines ได้ — " +
                $"สถานะปัจจุบัน: {doc.Status}. หลัง approve ใช้ Reclassify หรือ Manual JE.");

        var list = lines.ToList();

        // Validate ทุก line + load account ids ของบริษัทเพื่อ validate FK
        var companyAccountIds = await _db.ChartOfAccounts
            .Where(a => a.CompanyId == companyId && a.IsActive && !a.IsDeleted)
            .Select(a => a.Id)
            .ToListAsync();

        foreach (var l in list)
        {
            if (!companyAccountIds.Contains(l.AccountId))
                throw new InvalidOperationException(
                    $"ไม่พบบัญชี {l.AccountId} ในผังบัญชีของบริษัท หรือถูกปิดใช้");
            if (l.DebitAmount < 0 || l.CreditAmount < 0)
                throw new InvalidOperationException("ยอดเดบิตและเครดิตต้องไม่ติดลบ");
            if (l.DebitAmount > 0 && l.CreditAmount > 0)
                throw new InvalidOperationException("แต่ละรายการต้องเลือก Dr หรือ Cr ด้านเดียว");
            if (l.DebitAmount == 0 && l.CreditAmount == 0)
                throw new InvalidOperationException("รายการต้องมียอด Dr หรือ Cr อย่างน้อยด้านเดียว");
        }

        // Balance check — Dr รวม = Cr รวม (ของ adjusting). ระบบไม่ block
        // ตอน save (user อาจกำลังเขียนค้าง) แต่ AutoPost ตรวจตอน approve.
        // ที่นี่แค่เตือนใน log; การ block จริงอยู่ที่ AutoPost.

        // Replace all — ลบเก่าทิ้ง insert ใหม่ (full sync)
        var existing = await _db.Set<DocumentAdjustingJournalLine>()
            .Where(a => a.DocumentId == documentId)
            .ToListAsync();
        _db.Set<DocumentAdjustingJournalLine>().RemoveRange(existing);

        var order = 1;
        foreach (var l in list)
        {
            _db.Set<DocumentAdjustingJournalLine>().Add(new DocumentAdjustingJournalLine
            {
                DocumentId = documentId,
                LineOrder = order++,
                AccountId = l.AccountId,
                DebitAmount = l.DebitAmount,
                CreditAmount = l.CreditAmount,
                Description = l.Description,
                ProjectId = l.ProjectId,
                Reason = l.Reason,
                CreatedBy = actor,
            });
        }

        doc.UpdatedAt = DateTime.UtcNow;
        doc.UpdatedBy = actor;
        await _db.SaveChangesAsync();

        _logger.LogInformation(
            "Saved {Count} adjusting JE lines for document {DocNumber} by {Actor}",
            list.Count, doc.DocumentNumber, actor);

        return await GetDocumentAsync(companyId, documentId);
    }

    /// <summary>
    /// ยกเลิกเอกสาร — เก็บเอกสารต้นฉบับไว้ + สร้าง reversal JE ตามมาตรฐานบัญชีไทย
    /// (กลับรายการ Dr↔Cr, link OriginalEntryId↔ReversedByEntryId).
    /// Cascade: void linked Payments (with their JE reversals) + void linked EtaxInvoice.
    /// ไม่ลบข้อมูลออกจากฐานข้อมูล — เพื่อรักษา audit trail และตรวจสอบทางภาษี.
    /// </summary>
    /// <summary>ย้ายวันที่ JE "กลับรายการ" ของเอกสารที่ยกเลิกไปแล้ว ให้ไปอยู่
    /// งวดที่ถูกต้อง — ใช้แก้ใบที่ถูกยกเลิกตอนระบบยังตั้งวันที่กลับรายการเป็น
    /// "วันที่กด" (รายการจึงข้ามเดือน: เดือนเก่ายังค้างยอด เดือนใหม่มียอดลบ)
    ///
    /// ทำอะไร: ย้ายเฉพาะ <b>ตัวกลับ</b> (JE ที่ <c>OriginalEntryId != null</c>) ของ
    /// เอกสารนี้ — ไม่แตะ JE ต้นฉบับ ไม่สร้าง/ลบรายการใด ๆ ⇒ ยอดสุทธิเท่าเดิม
    /// เปลี่ยนแค่ "อยู่งวดไหน" (และ FiscalPeriodId ให้ตรงกัน)
    ///
    /// เงื่อนไขความปลอดภัย:
    ///   • งวดปลายทางต้องเปิดอยู่ (ห้ามยัดเข้างวดปิด)
    ///   • งวดต้นทาง (ที่ JE อยู่ตอนนี้) ต้องเปิดอยู่ด้วย — ย้ายออกจากงวดที่ปิด
    ///     แล้วเท่ากับแก้งบที่ปิดไปแล้ว
    ///   • เอกสารต้องอยู่สถานะยกเลิกจริง
    /// </summary>
    public async Task<int> RedateVoidReversalAsync(
        Guid companyId, Guid documentId, DateTime newDate, string actor,
        IReadOnlyList<RedateEntryDate>? entryDates = null)
    {
        var doc = await _db.Documents.AsNoTracking()
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");
        if (doc.Status != DocumentStatus.Voided)
            throw new InvalidOperationException(
                "เอกสารนี้ยังไม่ถูกยกเลิก — เครื่องมือนี้ใช้แก้วันที่ของ 'รายการกลับบัญชี' เท่านั้น");

        // ⚠️ งวดบัญชีเปิดอยู่ ≠ ยื่นภาษีได้ — ย้ายตัวกลับเข้าเดือนที่ ภ.พ.30/ภ.ง.ด.
        // ยื่นไปแล้วทำให้ GL ของเดือนนั้นไม่ตรงกับแบบที่ยื่น (และเดือนต้นทางเหลือ
        // ยอดลอยที่ไม่มีแถวรองรับ) — เพี้ยนสองเดือนพร้อมกัน. เครื่องมือพี่น้อง
        // (Void / Adjust / ReclassifyLine) เช็คข้อนี้ครบแล้ว เส้นนี้ตกหล่น
        if (_taxService != null && await _taxService.IsDocumentFilingLockedAsync(companyId, documentId))
            throw new InvalidOperationException(
                "เอกสารนี้อยู่ในรายงานภาษีที่ยื่นสรรพากรแล้ว — ย้ายวันที่รายการกลับบัญชีไม่ได้ " +
                "(GL จะไม่ตรงกับแบบที่ยื่น) ถ้าจำเป็นต้องแก้ ให้ยื่นแบบเพิ่มเติม/ปรับปรุงแทน");

        // ตัวกลับของเอกสารนี้ (Posted เท่านั้น — ตัวที่ยังมีผลต่อ GL)
        var reversals = await _db.JournalEntries
            .Where(j => j.CompanyId == companyId && j.SourceDocumentId == documentId
                && j.OriginalEntryId != null && j.Status == JournalEntryStatus.Posted
                && !j.IsDeleted)
            .ToListAsync();
        if (reversals.Count == 0) return 0;

        var originals = await LoadReversalOriginalsAsync(companyId, reversals);

        // วันที่ที่ผู้ใช้พิมพ์เองรายบรรทัดจากตารางในหน้าจอ — ชนะทุกค่าเริ่มต้น
        // (ห้ามรับ id ที่ไม่ใช่ตัวกลับของเอกสารนี้ ไม่งั้นกลายเป็นช่องแก้วันที่
        //  ของ JE ใบไหนก็ได้ในบริษัท)
        var explicitById = new Dictionary<Guid, DateTime>();
        foreach (var e in entryDates ?? Array.Empty<RedateEntryDate>())
        {
            if (!reversals.Any(r => r.Id == e.JournalEntryId))
                throw new InvalidOperationException(
                    "มีรายการที่ไม่ใช่ 'ตัวกลับ' ของเอกสารนี้ปนมา — โหลดหน้าใหม่แล้วลองอีกครั้ง");
            explicitById[e.JournalEntryId] = e.NewDate.Date;
        }

        var moved = 0;
        foreach (var rev in reversals)
        {
            // เอกสาร 1 ใบมักมีตัวกลับหลายใบและ **คนละวัน** (ใบซื้อ 1 ก.ค. +
            // ใบจ่ายชำระ 17 ก.ค.) — ยัดทุกใบไปวันเดียวกันคือย้ายรายการจ่ายไป
            // อยู่ผิดวัน. ลำดับการตัดสินวันที่: ผู้ใช้ระบุรายใบ → ระบุวันเดียว
            // ทั้งชุด → วันที่ของใบต้นฉบับที่ตัวเองกลับ → วันที่เอกสาร
            var target = explicitById.TryGetValue(rev.Id, out var chosen)
                ? chosen
                : ResolveRedateTarget(rev, newDate, doc.DocumentDate, originals);
            if (rev.EntryDate.Date == target) continue;

            var targetPeriod = await _db.FiscalPeriods.AsNoTracking().FirstOrDefaultAsync(f =>
                f.CompanyId == companyId && f.StartDate <= target && f.EndDate >= target);
            if (targetPeriod != null && targetPeriod.Status != FiscalPeriodStatus.Open)
                throw new InvalidOperationException(
                    $"งวด {targetPeriod.Name} ปิดแล้ว — เปิดงวดก่อน จึงจะย้ายรายการกลับบัญชีเข้าไปได้");

            var currentPeriod = await _db.FiscalPeriods.AsNoTracking().FirstOrDefaultAsync(f =>
                f.CompanyId == companyId
                && f.StartDate <= rev.EntryDate.Date && f.EndDate >= rev.EntryDate.Date);
            if (currentPeriod != null && currentPeriod.Status != FiscalPeriodStatus.Open)
                throw new InvalidOperationException(
                    $"ใบสำคัญ {rev.EntryNumber} อยู่ในงวด {currentPeriod.Name} ที่ปิดแล้ว — "
                    + "ย้ายออกไม่ได้ (ต้องเปิดงวดนั้นก่อน หรือใช้ใบปรับปรุงแทน)");

            var from = rev.EntryDate;
            rev.EntryDate = target;
            rev.FiscalPeriodId = targetPeriod?.Id;
            rev.Description = (rev.Description ?? "") +
                $" [แก้วันที่จาก {from:dd/MM/yyyy} → {target:dd/MM/yyyy} ให้อยู่งวดเดียวกับใบต้นฉบับ]";
            rev.UpdatedAt = DateTime.UtcNow;
            rev.UpdatedBy = actor;
            moved++;
        }

        if (moved > 0)
        {
            await _db.SaveChangesAsync();
            _logger.LogInformation(
                "RedateVoidReversal: ย้าย {Count} ใบสำคัญของเอกสาร {DocNo}",
                moved, doc.DocumentNumber);
        }
        return moved;
    }

    /// <summary>โหลดใบต้นฉบับของตัวกลับแต่ละใบ (เลขที่ + วันที่) — ใช้ทั้งตอน
    /// preview และตอนย้ายจริง เพื่อให้ "วันที่ที่โชว์" กับ "วันที่ที่ลงจริง"
    /// มาจากฟังก์ชันเดียวกัน (กฎเหล็ก #4 A "resolver กลาง ห้ามคำนวณเอง")</summary>
    private async Task<Dictionary<Guid, (string Number, DateTime Date)>> LoadReversalOriginalsAsync(
        Guid companyId, List<JournalEntry> reversals)
    {
        var ids = reversals.Where(r => r.OriginalEntryId.HasValue)
            .Select(r => r.OriginalEntryId!.Value).Distinct().ToList();
        if (ids.Count == 0) return new Dictionary<Guid, (string, DateTime)>();
        return await _db.JournalEntries.AsNoTracking()
            .Where(j => j.CompanyId == companyId && ids.Contains(j.Id))
            .Select(j => new { j.Id, j.EntryNumber, j.EntryDate })
            .ToDictionaryAsync(j => j.Id, j => (j.EntryNumber, j.EntryDate.Date));
    }

    /// <summary>วันที่ปลายทางของตัวกลับ 1 ใบ: ระบุมา = ใช้ตามนั้น ·
    /// ไม่ระบุ = วันที่ใบต้นฉบับ · หาใบต้นฉบับไม่เจอ = วันที่เอกสาร</summary>
    private static DateTime ResolveRedateTarget(
        JournalEntry reversal, DateTime explicitDate, DateTime documentDate,
        Dictionary<Guid, (string Number, DateTime Date)> originals)
    {
        if (explicitDate != default) return explicitDate.Date;
        if (reversal.OriginalEntryId.HasValue
            && originals.TryGetValue(reversal.OriginalEntryId.Value, out var o))
            return o.Date;
        return documentDate.Date;
    }

    /// <summary>ดูก่อนกด — เอกสาร 1 ใบมีตัวกลับได้หลายใบ ผู้ใช้ต้องเห็นว่า
    /// **ใบไหนบ้าง** จะถูกย้ายจากวันไหนไปวันไหน ก่อนยืนยัน</summary>
    public async Task<VoidReversalRedatePreview> PreviewVoidReversalRedateAsync(
        Guid companyId, Guid documentId, DateTime? newDate)
    {
        var doc = await _db.Documents.AsNoTracking()
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        var reversals = await _db.JournalEntries.AsNoTracking()
            .Where(j => j.CompanyId == companyId && j.SourceDocumentId == documentId
                && j.OriginalEntryId != null && j.Status == JournalEntryStatus.Posted
                && !j.IsDeleted)
            .OrderBy(j => j.EntryDate).ThenBy(j => j.EntryNumber)
            .ToListAsync();

        var originals = await LoadReversalOriginalsAsync(companyId, reversals);

        // งวดที่เกี่ยวข้องทั้งหมด (ต้นทาง + ปลายทาง) — โหลดรอบเดียว ไม่ยิงราย
        // บรรทัด แล้วบอกเหตุผลที่ย้ายไม่ได้ตั้งแต่หน้า preview ไม่ใช่ตอนกดยืนยัน
        var periods = await _db.FiscalPeriods.AsNoTracking()
            .Where(f => f.CompanyId == companyId)
            .Select(f => new { f.Name, f.StartDate, f.EndDate, f.Status })
            .ToListAsync();
        string? ClosedPeriodName(DateTime d)
        {
            var p = periods.FirstOrDefault(x => x.StartDate <= d && x.EndDate >= d);
            return p != null && p.Status != FiscalPeriodStatus.Open ? p.Name : null;
        }

        var rows = new List<VoidReversalRedateRow>();
        foreach (var rev in reversals)
        {
            var target = ResolveRedateTarget(rev, newDate ?? default, doc.DocumentDate, originals);
            (string Number, DateTime Date)? orig = rev.OriginalEntryId.HasValue
                && originals.TryGetValue(rev.OriginalEntryId.Value, out var o) ? o : null;

            string? block = null;
            if (rev.EntryDate.Date == target) block = "วันที่ตรงอยู่แล้ว";
            else if (ClosedPeriodName(rev.EntryDate.Date) is string cFrom)
                block = $"อยู่ในงวด {cFrom} ที่ปิดแล้ว — ย้ายออกไม่ได้";
            else if (ClosedPeriodName(target) is string cTo)
                block = $"งวดปลายทาง {cTo} ปิดแล้ว — เปิดงวดก่อน";

            rows.Add(new VoidReversalRedateRow(
                JournalEntryId: rev.Id,
                EntryNumber: rev.EntryNumber,
                JournalType: rev.JournalType.ToString(),
                CurrentDate: rev.EntryDate.Date,
                SuggestedDate: target,
                OriginalEntryNumber: orig?.Number,
                OriginalEntryDate: orig?.Date,
                Amount: rev.TotalDebit,
                WillMove: block == null,
                BlockReason: block));
        }

        return new VoidReversalRedatePreview(
            doc.Id, doc.DocumentNumber, doc.DocumentDate.Date, rows);
    }

    /// <summary>หา "วันที่ลงรายการกลับบัญชี" ที่ใช้ได้จริง — ถ้างวดของวันที่ที่
    /// ต้องการปิด/ล็อกแล้วจะลงไม่ได้ (ReverseJournalEntryAsync throw) ⇒ ตกกลับ
    /// เป็นวันนี้ พร้อมเหตุผลให้บันทึกไว้บนเอกสาร — ห้ามเงียบ เพราะนักบัญชี
    /// ต้องรู้ว่ารายการกลับไปอยู่งวดไหน</summary>
    private async Task<(DateTime Date, string? FallbackReason)> ResolveReversalDateAsync(
        Guid companyId, DateTime wanted)
    {
        var d = wanted.Date;
        var period = await _db.FiscalPeriods.AsNoTracking().FirstOrDefaultAsync(f =>
            f.CompanyId == companyId && f.StartDate <= d && f.EndDate >= d);
        if (period == null || period.Status == FiscalPeriodStatus.Open)
            return (d, null);

        var today = DateTime.UtcNow.Date;
        return (today,
            $"งวด {period.Name} ({d:dd/MM/yyyy}) ปิดแล้ว — ลงรายการกลับบัญชีที่วันที่ "
            + $"{today:dd/MM/yyyy} แทน (เปิดงวดก่อน ถ้าต้องการให้อยู่งวดเดิม)");
    }

    /// <param name="reversalDate">วันที่ลงรายการกลับบัญชี — **ค่าเริ่มต้น = วันที่
    /// ของเอกสารเอง** ไม่ใช่วันที่กดยกเลิก: ยกเลิกใบของเดือนก่อนแล้วรายการกลับ
    /// ไปโผล่เดือนปัจจุบัน ทำให้งบ/ภาษี **ผิดสองเดือนพร้อมกัน** (เดือนเก่ามียอด
    /// ค้างที่ไม่มีอยู่จริง เดือนใหม่มียอดติดลบที่ไม่มีที่มา). ส่งค่ามาเองได้เมื่อ
    /// ตั้งใจลงงวดอื่น (เช่น งวดเดิมปิดแล้ว)</param>
    public async Task VoidDocumentAsync(Guid companyId, Guid documentId, DateTime? reversalDate = null)
    {
        // Lines must be Include'd here so ApplyStockMovementsAsync (called
        // during the void transaction below) can iterate them — otherwise
        // doc.Lines is null and stock never gets restored on a void.
        var doc = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        if (doc.Status == DocumentStatus.Voided)
            throw new InvalidOperationException("เอกสารนี้ถูกยกเลิกแล้ว");

        // ใบเสร็จหลักฐานการชำระ (auto-issue ตอนบันทึกรับเงิน): ห้าม void ตรง ๆ —
        // ใบนี้ไม่เคยผ่าน Approve (ไม่มี JE ของตัวเอง) แต่ VoidDocumentAsync จะรัน
        // RevertSourceDocumentAdjustments → ลบ PaidAmount ของใบแจ้งหนี้ทั้งที่
        // Payment + JE ยังอยู่ → AR ติดลบ + เก็บเงินซ้ำได้ (audit B3). ทางถูก:
        // ยกเลิก "การชำระเงิน" (payment) → ระบบ void ใบเสร็จนี้ให้เอง (cascade ครบ)
        if (doc.IsSettlementReceipt)
            throw new InvalidOperationException(
                "ใบเสร็จนี้ออกอัตโนมัติจากการบันทึกชำระเงิน — กรุณา 'ยกเลิกการชำระเงิน' แทน " +
                "(ระบบจะยกเลิกใบเสร็จนี้และคืนยอดให้ครบอัตโนมัติ)");

        // Filing lock guard: an Approved document that's part of a TaxReport
        // already marked Filed (FilingLockedAt set) is sealed for audit —
        // the operator must Unlock the report first (admin) or use
        // RejectAndReverseTaxReportAsync to formally cancel the filing.
        if (_taxService != null && await _taxService.IsDocumentFilingLockedAsync(companyId, documentId))
            throw new InvalidOperationException(
                "เอกสารนี้อยู่ในรายงานภาษีที่ Filed แล้ว — กรุณา Unlock รายงานหรือใช้ 'Reject & Reverse' ก่อน");

        // Block void เฉพาะเมื่อ e-Tax "ได้รับตอบรับจากกรมสรรพากรแล้ว" (Accepted =
        // มีเลขตอบรับจริง) — จุด no-return ตามกฎหมายคือถูกรับเข้าระบบ RD แล้ว.
        // "Submitted" (เซ็น/คิว/ส่งแต่ยังไม่ได้ตอบรับ) ยัง "ยกเลิก + ออกใหม่" ได้
        // ก่อนนำส่ง ภ.พ.30 รายเดือน (แก้เอกสารผิดก่อนยื่นเป็นเรื่องปกติ) — เดิม
        // block ทั้ง Submitted+Accepted → ยกเลิกไม่ได้ทั้งที่ยังไม่ปิดรอบ/ยังไม่ยื่น.
        // งวดภาษีที่ Filed แล้วถูกกันด้วย filing-lock guard ด้านบนอยู่แล้ว; e-Tax
        // ที่ Submitted จะถูก cascade void พร้อมเอกสาร (ข้อ 3 ด้านล่าง).
        var lockedEtax = await _db.EtaxInvoices.FirstOrDefaultAsync(e => e.DocumentId == documentId
            && e.CompanyId == companyId
            && e.Status == EtaxStatus.Accepted);
        if (lockedEtax != null)
            throw new InvalidOperationException(
                $"ไม่สามารถยกเลิกเอกสารนี้ได้ เนื่องจาก e-Tax เลขที่ {lockedEtax.EtaxRefNumber} " +
                "ได้รับการตอบรับจากกรมสรรพากรแล้ว (Accepted) — ต้องยื่นขอยกเลิกที่กรมสรรพากรก่อน");

        // กันยกเลิกเอกสารต้นทางที่มี "เอกสารลูก" active อ้างอยู่ (แปลงไปแล้ว เช่น
        // Invoice→TaxInvoice/Receipt) — ยกเลิกต้นทางจะทำให้ลูกลอย (orphan): ภพ.30/
        // e-Tax/ลูกหนี้อ้างเอกสารที่หายไป (รวมถึงเคสลูกมี e-Tax ยื่น RD แล้ว).
        // ต้องยกเลิกลูกก่อน.
        var activeChild = await _db.Documents.AsNoTracking()
            .Where(d => d.CompanyId == companyId && d.RelatedDocumentId == documentId
                && !d.IsDeleted
                && d.Status != DocumentStatus.Voided && d.Status != DocumentStatus.Rejected)
            .Select(d => new { d.DocumentNumber, d.DocumentType })
            .FirstOrDefaultAsync();
        if (activeChild != null)
            throw new InvalidOperationException(
                $"ยกเลิกไม่ได้ — เอกสารนี้มีเอกสารลูก {activeChild.DocumentType} ({activeChild.DocumentNumber}) " +
                "อ้างอิงอยู่ (เช่นใบกำกับภาษี/ใบเสร็จที่แปลงไป). กรุณายกเลิกเอกสารลูกก่อน");

        // CN/DN legacy ที่อ้างใบนี้ด้วย "เลขที่" ในช่องอ้างอิง (text — ก่อนระบบ
        // resolve เป็น RelatedDocumentId ตอน approve) ก็ต้องกัน void เหมือนกัน —
        // ไม่งั้นใบเดิมถูกยกเลิกทั้งที่ใบลดหนี้ยัง active = ภ.พ.30 หักจากใบที่หายไป
        var docNumber = await _db.Documents.AsNoTracking()
            .Where(d => d.Id == documentId && d.CompanyId == companyId)
            .Select(d => d.DocumentNumber).FirstOrDefaultAsync();
        if (!string.IsNullOrWhiteSpace(docNumber))
        {
            var textRefChild = await _db.Documents.AsNoTracking()
                .Where(d => d.CompanyId == companyId && !d.IsDeleted
                    && (d.DocumentType == DocumentType.CreditNote || d.DocumentType == DocumentType.DebitNote)
                    && d.RelatedDocumentId == null && d.Reference == docNumber
                    && d.Status != DocumentStatus.Draft
                    && d.Status != DocumentStatus.Voided && d.Status != DocumentStatus.Rejected)
                .Select(d => new { d.DocumentNumber, d.DocumentType })
                .FirstOrDefaultAsync();
            if (textRefChild != null)
                throw new InvalidOperationException(
                    $"ยกเลิกไม่ได้ — มี{(textRefChild.DocumentType == DocumentType.CreditNote ? "ใบลดหนี้" : "ใบเพิ่มหนี้")} " +
                    $"{textRefChild.DocumentNumber} อ้างเลขที่ใบนี้อยู่ (§86/9-10) — ยกเลิกใบนั้นก่อน");
        }

        // ── วันที่ลงรายการกลับบัญชี ──
        // default = **วันที่ของเอกสารเอง** ไม่ใช่วันที่กดยกเลิก: ยกเลิกใบของเดือน
        // ก่อนแล้วรายการกลับไปโผล่เดือนปัจจุบัน ทำให้ผิด **สองเดือนพร้อมกัน**
        // (เดือนเก่าค้างยอดที่ไม่มีอยู่จริง / เดือนใหม่มียอดติดลบไม่มีที่มา)
        // และงบเปรียบเทียบรายเดือน + รายงานภาษีของทั้งคู่เพี้ยน
        var (effectiveReversalDate, reversalDateFallback) =
            await ResolveReversalDateAsync(companyId, reversalDate ?? doc.DocumentDate);
        if (reversalDateFallback != null)
            _logger.LogWarning("VoidDocument {DocNo}: {Reason}", doc.DocumentNumber, reversalDateFallback);

        var strategy = _db.Database.CreateExecutionStrategy();
        await strategy.ExecuteAsync(async () =>
        {
            await using var transaction = await _db.Database.BeginTransactionAsync();
            try
            {
                // Row lock + re-read สถานะใต้ล็อก — กัน double-void race (2 คลิกพร้อมกัน
                // → reverse JE ซ้ำ). ถ้าอีก request ยกเลิกไปแล้ว → no-op (idempotent).
                await _db.Database.ExecuteSqlRawAsync(
                    "SELECT 1 FROM \"Documents\" WHERE \"Id\" = {0} AND \"CompanyId\" = {1} FOR UPDATE",
                    documentId, companyId);
                var lockedStatus = await _db.Documents.AsNoTracking()
                    .Where(d => d.Id == documentId && d.CompanyId == companyId)
                    .Select(d => d.Status).FirstAsync();
                if (lockedStatus == DocumentStatus.Voided)
                {
                    await transaction.RollbackAsync();
                    return;
                }

                // 1) Void linked Payments first — each reverses its own JE + restores doc balance
                //    (We void *all* payments inside this transaction; the document gets voided
                //    after, so payment-balance recalculation here is intermediate only.)
                // ⚠️ ต้องหา payment ที่ผูกใบนี้ "ผ่าน PaymentAllocation" ด้วย —
                // multi-doc payment ตั้ง Payment.DocumentId = ใบแรกเท่านั้น ใบที่ 2
                // เป็นต้นไปผูกผ่าน allocation: เดิมหาไม่เจอ → ข้าม reverse → ยอด
                // ธนาคารค้างสูงถาวรทั้งที่ GL ฝั่งเอกสารถูกกลับไปแล้ว
                var allocPaymentIds = await _db.PaymentAllocations
                    .Where(a => a.DocumentId == documentId && a.CompanyId == companyId && !a.IsDeleted)
                    .Select(a => a.PaymentId)
                    .Distinct()
                    .ToListAsync();

                var payments = await _db.Payments
                    .Where(p => p.CompanyId == companyId && !p.IsDeleted
                        && (p.DocumentId == documentId || allocPaymentIds.Contains(p.Id)))
                    .ToListAsync();

                foreach (var payment in payments)
                {
                    // เงินก้อนเดียวจัดสรรหลายใบ: ยกเลิกใบเดียวแล้วแกะเงินออกบางส่วน
                    // ทำให้ยอดเช็ค/allocation ที่เหลือไม่ตรงกับเงินที่รับ-จ่ายจริง
                    // → บังคับให้ยกเลิก "การชำระเงินทั้งใบ" ก่อน แล้วค่อยจัดสรรใหม่
                    // (ทางบัญชี: เงินยังอยู่ ต้องคืนเข้ากองเงินรอจัดสรร ไม่ใช่หายไป)
                    var otherDocs = await _db.PaymentAllocations
                        .CountAsync(a => a.PaymentId == payment.Id && a.CompanyId == companyId
                            && !a.IsDeleted && a.DocumentId != documentId);
                    if (otherDocs > 0)
                        throw new InvalidOperationException(
                            $"เอกสารนี้ถูกชำระร่วมกับเอกสารอื่นในใบรับ/จ่ายเงินเดียวกัน ({payment.PaymentNumber}) — "
                            + "กรุณายกเลิกการชำระเงินใบนั้นทั้งใบก่อน แล้วจึงยกเลิกเอกสารและจัดสรรเงินใหม่");

                    var hasOwnAllocations = await _db.PaymentAllocations
                        .AnyAsync(a => a.PaymentId == payment.Id && a.CompanyId == companyId && !a.IsDeleted);
                    if (hasOwnAllocations)
                        await ReverseMultiDocPaymentInternalAsync(companyId, payment,
                            $"ยกเลิกอัตโนมัติพร้อมเอกสาร {doc.DocumentNumber}",
                            reversalDate: effectiveReversalDate);
                    else
                        await ReversePaymentInternalAsync(companyId, payment, doc,
                            $"ยกเลิกอัตโนมัติพร้อมเอกสาร {doc.DocumentNumber}",
                            reversalDate: effectiveReversalDate);
                }

                // 2) Reverse linked Posted JEs via AccountingService (proper linkage:
                //    OriginalEntryId/ReversedByEntryId, fiscal period validation, dimensions).
                // ⚠️ OriginalEntryId == null: reverse เฉพาะ JE "ต้นฉบับ" ของเอกสาร
                // ไม่รวม reversal entry. เดิมไม่กรอง → ตอน void เอกสารที่มี Payment:
                // ขั้น 1 reverse JE ของ payment สร้าง REV1 (Posted + SourceDocumentId=
                // doc) → ขั้นนี้จับ REV1 มา reverse ซ้ำ → เงินสดค้างบนบัญชี + AR ติดลบ
                // เงียบ ๆ (งบยัง balance). กรอง OriginalEntryId==null กันเคสนี้.
                var postedJournals = await _db.JournalEntries
                    .Where(j => j.SourceDocumentId == documentId && j.CompanyId == companyId
                        && j.Status == JournalEntryStatus.Posted
                        && j.OriginalEntryId == null)
                    .Select(j => new { j.Id, j.EntryDate })
                    .ToListAsync();
                foreach (var je in postedJournals)
                {
                    // ⚠️ ตัวกลับต้องตกงวดเดียวกับ "ใบที่มันกลับ" ไม่ใช่งวดของเอกสาร
                    // ทั้งก้อน (X-7): ใบสำคัญปรับปรุงผังบัญชีเลือกวันที่เองได้ (เช่น
                    // ใบเดือน ก.ค. แต่ปรับปรุงลงเดือน ส.ค.) ถ้ากลับที่วันของเอกสาร
                    // ⇒ ก.ค. มีตัวกลับที่ไม่มีคู่ (ต่ำไป) และ ส.ค. ยังมีใบปรับปรุง
                    // ค้าง (สูงไป) — ผิดสองเดือนพร้อมกัน เหมือนบทเรียน X-1
                    var perEntryDate = je.EntryDate.Date == doc.DocumentDate.Date
                        ? effectiveReversalDate
                        : (await ResolveReversalDateAsync(companyId, je.EntryDate)).Date;
                    await _accountingService.ReverseJournalEntryAsync(companyId, je.Id,
                        reversalDate: perEntryDate,
                        description: $"ยกเลิกเอกสาร {doc.DocumentNumber}",
                        systemTriggered: true);
                }

                // 2b) กลับ "JV ตัดชำระด้วยมัดจำ" (ApplyDepositToInvoiceAsync) ที่ชี้มา
                //     ใบนี้ — JV นั้น SourceDocumentId = ใบมัดจำ (ไม่ใช่ใบนี้) จึงหลุด
                //     selection ของ step 2. ถ้าไม่กลับ: Cr 113 ของ JV ค้าง (AR ติดลบ)
                //     + 217xx ถูกตัดทั้งที่มัดจำต้องกลับมาคงค้าง + subledger มัดจำ
                //     (RealizedAmount/RecognizedAt/AppliedToDocumentId) ไม่คืน →
                //     นำมัดจำไป apply ใบใหม่ไม่ได้. mirror ของ 7b (ฝั่ง void ใบมัดจำ):
                //     อ่าน "ขาจริง" จาก JV แล้วคืนตามนั้น. เคส drives (ขา reversal ฝัง
                //     ใน JE ใบเช็คเอาท์เอง ไม่มี JV) ข้าม loop นี้โดยธรรมชาติ (ไม่เจอ
                //     JE ที่มีขา Cr 113 sourced จากใบมัดจำ) → 7c จัดการตามเดิม.
                var appliedDeposits = await _db.Documents
                    .Where(d => d.CompanyId == companyId && d.IsDeposit && !d.IsDeleted
                        && d.DepositAppliedToDocumentId == documentId)
                    .ToListAsync();
                foreach (var dep in appliedDeposits)
                {
                    var applyJes = await _db.JournalEntries.Include(j => j.Lines)
                        .Where(j => j.CompanyId == companyId && j.SourceDocumentId == dep.Id
                            && j.OriginalEntryId == null && j.ReversedByEntryId == null
                            && j.Status == JournalEntryStatus.Posted && !j.IsDeleted
                            && j.Reference == doc.DocumentNumber)
                        .ToListAsync();
                    if (applyJes.Count == 0) continue;   // drives-mode → 7c จัดการ

                    var applyAcctIds = applyJes.SelectMany(j => j.Lines)
                        .Select(l => l.AccountId).Distinct().ToList();
                    var applyAcctCodes = await _db.ChartOfAccounts.AsNoTracking()
                        .Where(a => a.CompanyId == companyId && applyAcctIds.Contains(a.Id))
                        .Select(a => new { a.Id, a.AccountCode }).ToListAsync();
                    string ApplyCodeOf(Guid id) =>
                        applyAcctCodes.FirstOrDefault(a => a.Id == id)?.AccountCode ?? "";

                    decimal restoredBase = 0m, restoredGross = 0m;
                    bool had21913 = false, reversedAny = false;
                    foreach (var applyJe in applyJes)
                    {
                        // JV ตัดชำระ = ต้องมีขา Cr ลูกหนี้ (113) — กัน JE ประเภทอื่น
                        // ของใบมัดจำ (เช่น realize รายได้) ที่ Reference เลขใบเดียวกัน
                        var grossCr = applyJe.Lines.Where(l => !l.IsDeleted && l.CreditAmount > 0
                            && ApplyCodeOf(l.AccountId).StartsWith("113")).Sum(l => l.CreditAmount);
                        if (grossCr <= 0m) continue;
                        restoredBase += applyJe.Lines.Where(l => !l.IsDeleted && l.DebitAmount > 0
                                && (ApplyCodeOf(l.AccountId).StartsWith("217")
                                    || ApplyCodeOf(l.AccountId).StartsWith("215")))
                            .Sum(l => l.DebitAmount);
                        had21913 |= applyJe.Lines.Any(l => !l.IsDeleted && l.DebitAmount > 0
                            && ApplyCodeOf(l.AccountId) == "21913");
                        restoredGross += grossCr;
                        await _accountingService.ReverseJournalEntryAsync(companyId, applyJe.Id,
                            reversalDate: effectiveReversalDate,
                            description: $"ยกเลิกเอกสาร {doc.DocumentNumber} — คืนมัดจำ {dep.DocumentNumber}",
                            systemTriggered: true);
                        reversedAny = true;
                    }
                    if (!reversedAny) continue;

                    dep.DepositRealizedAmount = Math.Max(0m, dep.DepositRealizedAmount - restoredBase);
                    if (dep.SubTotal - dep.DepositRealizedAmount > 0.005m)
                        dep.DepositRealizedAt = null;    // กลับเป็น "มัดจำคงค้าง"
                    // เคลียร์ RecognizedAt เฉพาะเมื่อ JV นี้เป็นผู้ stamp จริง (มี Dr
                    // 21913) — หลักเดียวกับ 7c/audit F3 กันล้าง stamp ของ Realize รอบก่อน
                    if (had21913)
                        dep.DepositOutputVatRecognizedAt = null;
                    dep.DepositAppliedToDocumentId = null;
                    dep.UpdatedAt = DateTime.UtcNow;
                    // คืน PaidAmount ส่วนที่จ่ายด้วยมัดจำ (ใบนี้กำลัง Voided — เก็บ
                    // ตัวเลขให้ตรงจริงเพื่อรายงาน/inspection ย้อนหลัง)
                    doc.PaidAmount = Math.Max(0m, doc.PaidAmount - restoredGross);
                    doc.BalanceDue = doc.TotalAmount - doc.PaidAmount;
                }

                // 2b-JV) กลับ "JV มัดจำ raw (non-drives)" ที่ apply เข้าใบนี้ — JV ไม่ใช่
                //   Document จึงหลุด loop 2b ด้านบน (ซึ่งวน Documents เท่านั้น). apply JE:
                //   SourceDocumentId=null, Reference=docNo, IsAutoGenerated, มีทั้งขา
                //   Cr 113 + Dr 215/217. reverse "ทุกตัว" (เผื่อโดน apply ซ้ำก่อนมี guard
                //   one-shot รอบ 90) + un-mark JV ต้นทางให้ resync หักใหม่ได้.
                //   ไม่ทำ → Cr 113/Dr 21510 ของ JV ค้างใน GL หลัง void (AR + 21510 เพี้ยน)
                var voidJvGross = await ReverseOrphanJvDepositAppliesAsync(companyId, doc.DocumentNumber,
                    deleteMode: false, reversalDate: effectiveReversalDate);
                if (voidJvGross > 0m)
                {
                    doc.PaidAmount = Math.Max(0m, doc.PaidAmount - voidJvGross);
                    doc.BalanceDue = doc.TotalAmount - doc.PaidAmount;
                }

                // 3) Void linked EtaxInvoice (keep XML/PDF for audit; only flag status).
                // รวม Submitted ด้วย (ยังไม่ได้รับตอบรับ RD → ยกเลิกได้พร้อมเอกสาร);
                // Accepted ถูกกันตั้งแต่ guard ด้านบนแล้ว (มาไม่ถึงตรงนี้).
                var etaxes = await _db.EtaxInvoices
                    .Where(e => e.DocumentId == documentId && e.CompanyId == companyId
                        && e.Status != EtaxStatus.Voided && e.Status != EtaxStatus.Accepted)
                    .ToListAsync();
                foreach (var etax in etaxes)
                {
                    etax.Status = EtaxStatus.Voided;
                    etax.VoidedAt = DateTime.UtcNow;
                    etax.VoidReason = $"ยกเลิกพร้อมเอกสาร {doc.DocumentNumber}";
                    etax.UpdatedAt = DateTime.UtcNow;
                }

                // 4) Unlink BankTransactions matched to this document's journal entries
                var postedJournalIds = postedJournals.Select(j => j.Id).ToList();
                if (postedJournalIds.Any())
                {
                    await _db.BankTransactions
                        .Where(t => t.CompanyId == companyId
                            && t.MatchedJournalEntryId.HasValue
                            && postedJournalIds.Contains(t.MatchedJournalEntryId.Value))
                        .ExecuteUpdateAsync(s => s
                            .SetProperty(t => t.MatchedJournalEntryId, (Guid?)null)
                            .SetProperty(t => t.ReconciliationStatus, ReconciliationStatus.Unmatched)
                            .SetProperty(t => t.ReconciledAt, (DateTime?)null));
                }

                // 5) Restore source document's balance if this was a derivative
                //    (Receipt/CN/PaymentVoucher referencing another doc). Mirrors
                //    the adjustment applied during ApproveDocumentAsync.
                await RevertSourceDocumentAdjustmentsAsync(companyId, doc);

                // 6) Back out this document's contribution to its project's
                //    BilledAmount — mirror of the +1 applied at approval.
                //    Skip Draft docs: never approved, so never billed.
                // ใบกำกับที่ออก "แทน" ใบเสร็จ ไม่เคยบวกยอดโครงการ/ไม่เคยขยับสต๊อก
                // ตอนอนุมัติ (ApproveDocumentAsync ข้ามให้ — ใบเดิมทำไปแล้ว) ⇒
                // ตอน void ต้องข้ามการ "กลับ" ด้วย มิฉะนั้นจะได้สต๊อกผีคืนเข้าคลัง
                // และยอดวางบิลโครงการติดลบ ทั้งที่ไม่มีอะไรเคยเกิดขึ้น
                var isReplacementDoc = doc.ReplacesDocumentId.HasValue;

                if (doc.Status != DocumentStatus.Draft && !isReplacementDoc)
                    await ApplyProjectBillingAsync(companyId, doc, -1);

                // 6b) Reverse any stock movement this document caused at
                //     approval. Sign=-1 means a sale Invoice's OUT becomes IN
                //     (stock restored), a purchase Invoice's IN becomes OUT.
                //     Same Draft skip: drafts never decremented stock.
                if (doc.Status != DocumentStatus.Draft && !isReplacementDoc)
                    await ApplyStockMovementsAsync(companyId, doc, -1, "system-void");

                // 6c) Back out this document's auto-booked project cost entries
                //     — mirror of SyncProjectCostEntriesAsync at approval. Soft-
                //     deletes the PCE rows and subtracts from Project.ActualCost
                //     so a voided cost doc no longer inflates the project's
                //     actual cost. Same Draft skip: drafts never booked a PCE.
                if (doc.Status != DocumentStatus.Draft)
                    await ReverseProjectCostEntriesAsync(companyId, doc);

                // 6d) Void any auto-issued WHT certificates that point at this
                //     document. WHT certs are created at payment time (cash
                //     basis) and feed PND.3/53 monthly exports — without this
                //     cascade, voiding a PV/PI/Expense leaves the cert "Issued"
                //     and the company silently remits + pays tax for a payment
                //     that no longer exists. Best-effort + bounded: only
                //     not-already-voided certs linked to THIS doc.
                var linkedCerts = await _db.WithholdingTaxCerts
                    .Where(w => w.CompanyId == companyId && w.DocumentId == documentId
                                && w.Status != WithholdingTaxCertStatus.Voided && !w.IsDeleted)
                    .Select(w => w.Id)
                    .ToListAsync();
                foreach (var certId in linkedCerts)
                {
                    try { await _whtService.VoidAsync(companyId, certId); }
                    catch (Exception ex) { _logger.LogWarning(ex, "WHT cert {Cert} void failed during doc void {Doc}", certId, documentId); }
                }

                // 7) Finally void the document itself + clear the stale
                //    aging value. The list-row gate already suppresses the
                //    badge visually for Voided status, but cleaning the
                //    underlying field keeps reports + bulk queries honest.
                doc.Status = DocumentStatus.Voided;
                doc.AgingDays = null;
                doc.AgingLastEvaluatedAt = DateTime.UtcNow;
                doc.UpdatedAt = DateTime.UtcNow;

                // 7-supersede) ใบกำกับที่ "แทนที่" ใบแจ้งหนี้ไว้ ถูกยกเลิกเอง →
                // ปลุกใบแจ้งหนี้ต้นทางกลับมาเป็นร่าง (S-6). ถ้าไม่ทำ: ใบแจ้งหนี้
                // ถูก void ตอน supersede ไปแล้ว + ใบกำกับเพิ่ง void ⇒ **ไม่เหลือ
                // เอกสารที่รับรู้รายได้เลย** ทั้งที่ของส่งไปแล้ว และไม่มีใครเห็น
                // (ทั้งคู่หลุดจากรายการค้างรับและรายงานภาษี) จับได้ตอนกระทบยอด
                // ปลายงวดเท่านั้น. คืนเป็น Draft ไม่ใช่ Approved — ผู้ใช้ต้อง
                // ตัดสินใจเองว่าจะออกใบใหม่หรือปล่อยยกเลิกทั้งคู่ (เลข §86/4 เดิม
                // ถูกใช้ไปแล้ว การ re-approve จะคงเลขเดิมตามกฎ gap-free)
                if (doc.DocumentType == DocumentType.TaxInvoice && doc.RelatedDocumentId.HasValue)
                {
                    var supersededSrc = await _db.Documents.FirstOrDefaultAsync(d =>
                        d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId
                        && d.DocumentType == DocumentType.Invoice
                        && d.Status == DocumentStatus.Voided
                        && d.Notes != null && d.Notes.Contains($"[แทนที่ด้วยใบกำกับภาษี {doc.DocumentNumber}]"));
                    if (supersededSrc != null)
                    {
                        supersededSrc.Status = DocumentStatus.Draft;
                        supersededSrc.Notes = ((supersededSrc.Notes ?? "")
                            + $" [ใบกำกับ {doc.DocumentNumber} ถูกยกเลิก — คืนใบนี้เป็นร่าง กรุณาตรวจแล้วอนุมัติใหม่หรือยกเลิกถาวร]").Trim();
                        supersededSrc.UpdatedAt = DateTime.UtcNow;
                        supersededSrc.UpdatedBy = doc.UpdatedBy;
                        _logger.LogWarning(
                            "Void {Tax}: คืนใบแจ้งหนี้ต้นทาง {Src} เป็นร่าง — ไม่งั้นรายได้หายทั้งก้อน",
                            doc.DocumentNumber, supersededSrc.DocumentNumber);
                    }
                }

                // 7-replacement) ใบกำกับเต็มรูปที่ออก "แทน" ใบเสร็จ ถูกยกเลิกเอง →
                // ปลดตราประทับบนใบเดิม ไม่งั้นใบเดิมจะถูกกันออกจากรายงานภาษีขาย
                // ตลอดไป ทั้งที่ใบแทนไม่มีอยู่แล้ว ⇒ **ภาษีขายหายทั้งใบ** โดยยอด
                // ยังอยู่ใน GL (จับได้ตอนกระทบยอด ภ.พ.30 กับ GL เท่านั้น).
                // ใบเดิมไม่ต้องคืนสถานะ — มันไม่เคยถูก void (ต่างจาก 7-supersede)
                if (doc.ReplacesDocumentId.HasValue)
                {
                    var replacedSrc = await _db.Documents.FirstOrDefaultAsync(d =>
                        d.Id == doc.ReplacesDocumentId.Value && d.CompanyId == companyId
                        && d.ReplacedByDocumentId == documentId);
                    if (replacedSrc != null)
                    {
                        replacedSrc.ReplacedByDocumentId = null;
                        replacedSrc.ReplacedAt = null;
                        replacedSrc.InternalNotes = string.Join(" · ", new[]
                        {
                            replacedSrc.InternalNotes?.Trim(),
                            $"ใบกำกับภาษีเต็มรูป {doc.DocumentNumber} ถูกยกเลิก — "
                                + "ใบนี้กลับมาเป็นเจ้าของแถวในรายงานภาษีขายตามเดิม",
                        }.Where(s => !string.IsNullOrWhiteSpace(s)));
                        replacedSrc.UpdatedAt = DateTime.UtcNow;
                        _logger.LogWarning(
                            "Void {Tax}: ปลดตราประทับใบแทนบน {Src} — คืนใบเดิมเข้ารายงานภาษีขาย",
                            doc.DocumentNumber, replacedSrc.DocumentNumber);
                    }
                }

                // 7-asset) Cascade FixedAsset ที่ AutoRegister มาจาก doc นี้:
                //   • ยังไม่ยืนยัน (NeedsReview=true) + ไม่มี posted dep → ลบ
                //     เลย (รวม projected dep) — ถือเป็น orphan placeholder
                //     ที่ user ยังไม่ commit
                //   • ยืนยันแล้ว (NeedsReview=false) → ปล่อย + log warning
                //     ให้ user ตัดสิน dispose/write-off เองด้วย UI
                // inline delete — ไม่เรียก FixedAssetService.DeleteAsync เพราะ
                // guard ของมันจะ block (source doc.Status ใน DB ยังไม่ Voided
                // เพราะ SaveChangesAsync ยังไม่รัน)
                var ourAssets = await _db.FixedAssets
                    .Where(a => a.CompanyId == companyId && a.SourceDocumentId == documentId)
                    .ToListAsync();
                foreach (var asset in ourAssets)
                {
                    if (!asset.NeedsReview)
                    {
                        _logger.LogWarning(
                            "Doc {Doc} void: asset {Code} ยืนยันแล้ว — ไม่ลบ ผู้ใช้ต้อง dispose/write-off ด้วยตนเอง",
                            documentId, asset.AssetCode);
                        continue;
                    }
                    var hasPostedDep = await _db.AssetDepreciations
                        .AnyAsync(d => d.FixedAssetId == asset.Id && d.IsPosted && !d.IsDeleted);
                    if (hasPostedDep)
                    {
                        _logger.LogWarning(
                            "Doc {Doc} void: asset {Code} (NeedsReview) มีค่าเสื่อม posted — ไม่ลบ",
                            documentId, asset.AssetCode);
                        continue;
                    }
                    var projectedDeps = await _db.AssetDepreciations
                        .Where(d => d.FixedAssetId == asset.Id)
                        .ToListAsync();
                    _db.AssetDepreciations.RemoveRange(projectedDeps);
                    _db.FixedAssets.Remove(asset);
                }

                // 7a) Reset stateful posting flags ที่ตั้งตอน approve. ถ้าไม่ reset
                //     แล้ว user re-approve doc นี้ในอนาคต logic จะข้ามขั้นที่
                //     ควรรัน (เช่น undue VAT ถูก mark claimable ไปแล้ว → re-
                //     approve จะไม่ลง 11640 ใหม่). ทุก field reset ที่นี่จะถูก
                //     "เริ่มใหม่" ตอน re-approve เหมือนใบใหม่ผ่าน flow ปกติ.
                doc.InputVatPostedAsUndue = false;
                doc.InputVatBecameClaimableAt = null;

                // 7b) Deposit (Receipt/ReceiptVoucher IsDeposit=true): reset
                //     state realize/refund/recognize. JE reversal ใน step 2
                //     กลับยอดบัญชี 217xx/21911/21913 แล้ว แต่ field document-
                //     level เหล่านี้ถ้าไม่เคลียร์ GetDepositsAsync จะยังโชว์
                //     สถานะ "Partial/Realized" หลัง void → UI/รายงานเพี้ยน.
                if (doc.IsDeposit)
                {
                    // ถ้ามัดจำนี้เคยถูกนำไป "ตัดชำระ" ใบแจ้งหนี้ (DepositAppliedToDocumentId)
                    // → GL ลูกหนี้ถูก reverse ใน step 2 แล้ว แต่ subledger invoice.PaidAmount
                    // ต้องคืนเอง (ผูกด้วย DepositAppliedToDocumentId ไม่ใช่ RelatedDocumentId
                    // จึงหลุด RevertSourceDocumentAdjustments). ไม่งั้นใบแจ้งหนี้ค้าง PaidAmount
                    // ผี (ยอดที่จ่ายด้วยมัดจำที่ยกเลิกแล้ว). ยอด gross = เครดิตลูกหนี้ 113 ใน JE ตัดชำระ.
                    if (doc.DepositAppliedToDocumentId.HasValue)
                    {
                        var appliedGross = await _db.JournalEntryLines
                            .Where(l => l.JournalEntry.SourceDocumentId == doc.Id
                                && l.JournalEntry.CompanyId == companyId
                                && l.JournalEntry.OriginalEntryId == null
                                && l.CreditAmount > 0
                                && l.Account.AccountCode.StartsWith("113"))
                            .SumAsync(l => (decimal?)l.CreditAmount) ?? 0m;
                        if (appliedGross > 0m)
                        {
                            var inv = await _db.Documents.FirstOrDefaultAsync(d =>
                                d.Id == doc.DepositAppliedToDocumentId.Value && d.CompanyId == companyId);
                            if (inv != null && inv.Status != DocumentStatus.Voided)
                            {
                                inv.PaidAmount = Math.Max(0m, inv.PaidAmount - appliedGross);
                                inv.BalanceDue = inv.TotalAmount - inv.PaidAmount;
                                inv.Status = inv.PaidAmount <= 0.01m ? DocumentStatus.Approved
                                    : inv.BalanceDue <= 0.01m ? DocumentStatus.Paid : DocumentStatus.PartiallyPaid;
                                inv.AgingDays = null; inv.AgingLastEvaluatedAt = DateTime.UtcNow;
                                inv.UpdatedAt = DateTime.UtcNow;
                            }
                        }
                    }
                    doc.DepositRealizedAmount = 0m;
                    doc.DepositRealizedAt = null;
                    doc.DepositOutputVatRecognizedAt = null;
                    doc.DepositRefundedAmount = 0m;
                    doc.DepositRefundedAt = null;
                    doc.DepositAppliedToDocumentId = null;
                }

                // 7c) UN-realize ใบมัดจำ เมื่อ void "ใบรับเงินที่ขับ JE ด้วยมัดจำ"
                //     (depositAppliedDrivesJournal) — ใบมัดจำเองไม่ถูก void (เงิน
                //     รับจริงยังอยู่) แต่สถานะ realized ของมันถูกคุมโดย lifecycle
                //     ของใบเช็คเอาท์นี้. JE reversal (step 2) กลับ 217xx/21913 ใน GL
                //     แล้ว แต่ subledger ของใบมัดจำ (DepositRealizedAmount/At,
                //     DepositAppliedToDocumentId) ต้อง un-mark เองเพื่อให้ resync
                //     (สร้างใบใหม่อ้างมัดจำเดิม) re-realize ได้ถูกต้อง.
                if (!doc.IsDeposit && doc.DepositAppliedDrivesJournal
                    && doc.DepositAppliedAmount > 0 && !string.IsNullOrWhiteSpace(doc.DepositAppliedRef))
                {
                    await UnrealizeDrivesDepositAsync(companyId, doc);
                }

                await _db.SaveChangesAsync();
                await transaction.CommitAsync();
            }
            catch
            {
                await transaction.RollbackAsync();
                throw;
            }
        });

        // Cascade-unwind any ReconciliationGroup that referenced this Document
        // directly (ItemType=Document — for Receipt/PV operators dragged into
        // a group without going through a Payment record). JE-pathed groups
        // were already unwound during step (2) via ReverseJournalEntryAsync.
        // Runs OUTSIDE the strategy/transaction above so a bank-cleanup
        // hiccup doesn't roll back the voided document state.
        if (_bankService != null)
        {
            try { await _bankService.UnwindGroupsContainingItemAsync(companyId, ReconciliationItemType.Document, documentId); }
            catch (Exception ex) { _logger.LogWarning(ex, "Group unwind for voided document {DocId} failed", documentId); }
        }

        // บรรทัด ภ.พ.30 งวดที่ยังไม่ยื่น (Draft/อื่น) ที่อ้างใบนี้ → ติ๊กออก +
        // ป้ายเตือนอัตโนมัติ (best-effort, post-commit) — เดิม void แล้วบรรทัด
        // ยัง active จนกว่าจะมีคน regen เอง = ยื่นทั้งอย่างนั้นได้ (เคลม VAT ของ
        // ใบที่ยกเลิกแล้ว §82/5(1)); ตัวยื่น (FileTaxReportAsync) ก็ revalidate
        // ซ้ำอีกชั้น — สองชั้นกันหลุด
        try
        {
            // ครอบทุกแบบ ไม่ใช่แค่ ภ.พ.30 — บรรทัด ภ.ง.ด.3/53/54 ที่อ้างใบนี้
            // (TaxService ตั้ง DocumentId ไว้เหมือนกัน) เดิมไม่ถูกแตะเลย → ยกเลิก
            // PV/Expense ที่หักภาษีแล้ว แต่ยอดนำส่งในแบบยังอยู่ครบ = นำส่งภาษีของ
            // รายการจ่ายที่ไม่มีอยู่จริง (cert ถูก void ไปแล้วแต่รายงานไม่ตาม)
            var reportTaxTypes = new[] { TaxType.VAT, TaxType.WithholdingTax1,
                TaxType.WithholdingTax3, TaxType.WithholdingTax53, TaxType.WithholdingTax54 };
            var vatLines = await _db.TaxReportLines
                .Include(l => l.TaxReport)
                .Where(l => l.DocumentId == documentId && !l.IsExcluded
                    && l.TaxReport.CompanyId == companyId
                    && reportTaxTypes.Contains(l.TaxReport.TaxType)
                    // ★ รอบ 183 — ถอนบรรทัดได้เฉพาะรายงานที่ยังเป็นร่างจริง ๆ
                    && !Accounting.Helpers.TaxFilingLockPolicy.DeclaredOrFiledStatuses.Contains(l.TaxReport.Status))
                .ToListAsync();
            if (vatLines.Count > 0)
            {
                var touchedReports = new HashSet<Guid>();
                foreach (var vl in vatLines)
                {
                    vl.IsExcluded = true;
                    vl.Description = "⚠️ [เอกสารถูกยกเลิก] " + (vl.Description ?? "");
                    vl.UpdatedAt = DateTime.UtcNow;
                    touchedReports.Add(vl.TaxReportId);
                }
                foreach (var rid in touchedReports)
                {
                    var rep = await _db.TaxReports.Include(r => r.Lines)
                        .FirstOrDefaultAsync(r => r.Id == rid);
                    if (rep != null)
                    {
                        TaxService.RecalcVatTotals(rep);   // no-op ถ้าไม่ใช่ ภ.พ.30
                        TaxService.RecalcWhtTotals(rep);   // no-op ถ้าไม่ใช่ ภ.ง.ด.
                        rep.UpdatedAt = DateTime.UtcNow;
                    }
                }
                await _db.SaveChangesAsync();
            }
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Void {DocId}: อัปเดตบรรทัด ภ.พ.30 งวด Draft ไม่สำเร็จ", documentId);
        }

        // Fire DocumentVoided notification (best-effort, post-commit). Cascades
        // through the per-user matrix to Accounting / Owner recipients per
        // their configured channels (in-app, LINE, email).
        if (_notify != null)
        {
            try
            {
                var contactName = await _db.Contacts.Where(c => c.Id == doc.ContactId)
                    .Select(c => c.Name).FirstOrDefaultAsync() ?? "";
                await _notify.DispatchAsync(companyId, NotificationEvents.DocumentVoided, new NotificationContext
                {
                    Title = $"ยกเลิกเอกสาร {doc.DocumentNumber}",
                    Message = $"{doc.DocumentType} · {contactName} · ยอดรวม {doc.TotalAmount:N2} บาท — กลับรายการบัญชี/ชำระเงิน/e-Tax อัตโนมัติ",
                    ActionUrl = $"/pages/documents.html?id={doc.Id}",
                    EntityType = "Document", EntityId = doc.Id,
                });
            }
            catch (Exception ex) { _logger.LogWarning(ex, "DocumentVoided notification failed for {DocId}", documentId); }
        }

        // Webhook — DocumentVoided fires last so partners observe a
        // fully-settled state (linked payments already reversed, JE
        // already gone, bank-group already unwound).
        await FireWebhookAsync(companyId, "document.voided", new
        {
            documentId = doc.Id,
            documentNumber = doc.DocumentNumber,
            documentType = doc.DocumentType.ToString(),
            voidedAt = DateTime.UtcNow,
        });
    }

    /// <summary>กู้คืนเอกสารที่ยกเลิกผิด (Voided → Draft, คงเลขเดิม). ดู interface
    /// doc. ปลอดภัยเพราะ: (1) void เก็บ row ไว้ครบ (แค่ Status=Voided + reversal
    /// JE) ไม่ได้ลบ line/ยอด → คืน Draft แล้ว re-approve ได้เลย; (2) เลขไม่ใช่
    /// DRAFT- → ApproveDocumentAsync ไม่ regenerate = คงเลขเดิม; (3) reversal JE
    /// ของ void คงไว้ (Reversed↔reversal คู่ net-zero) → re-approve post JE ใหม่
    /// สุทธิถูกต้อง ไม่ double. gate ปิดเคสผิดกฎหมาย.</summary>
    public async Task<DocumentResponse> RestoreVoidedDocumentAsync(Guid companyId, Guid documentId, string actor)
    {
        var doc = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        if (doc.Status != DocumentStatus.Voided)
            throw new InvalidOperationException(
                $"กู้คืนได้เฉพาะเอกสารที่ 'ยกเลิก' แล้วเท่านั้น (สถานะปัจจุบัน: {doc.Status})");

        // Gate 1 — e-Tax ที่กรมสรรพากรตอบรับแล้ว (Accepted): ห้ามคืนชีพ เพราะ
        // เอกสารถูกนำส่ง RD ไปแล้ว (ปกติ void ก็ถูก block ตั้งแต่แรก แต่ตรวจซ้ำ
        // กันเคสประวัติศาสตร์/ข้อมูล inconsistent)
        var acceptedEtax = await _db.EtaxInvoices.AsNoTracking()
            .FirstOrDefaultAsync(e => e.DocumentId == documentId && e.CompanyId == companyId
                && e.Status == EtaxStatus.Accepted);
        if (acceptedEtax != null)
            throw new InvalidOperationException(
                $"กู้คืนไม่ได้ — e-Tax เลขที่ {acceptedEtax.EtaxRefNumber} ได้รับตอบรับจากกรมสรรพากรแล้ว " +
                "(Accepted). ต้องออกเอกสารใหม่แทน");

        // Gate 2 — เดือนภาษีของเอกสารยื่น ภ.พ.30 / ล็อกแล้ว: คืนชีพ = ยัด
        // เอกสารมี VAT กลับเข้าเดือนที่ยื่นไปแล้ว → ยอด ภ.พ.30 เพี้ยนย้อนหลัง.
        // ตรวจแบบ period-based (ไม่ใช่ line-reference) เพราะ void มักถอด doc ออก
        // จาก report line ไปแล้ว. เช็คทั้งเดือนของ TaxPoint/DocumentDate.
        var taxDate = doc.TaxPointDate ?? doc.DocumentDate;
        var vatFiled = await _db.TaxReports.AsNoTracking().AnyAsync(r =>
            r.CompanyId == companyId && !r.IsDeleted && r.TaxType == TaxType.VAT
            && r.Year == taxDate.Year && r.Month == taxDate.Month
            && (r.Status != TaxReportStatus.Draft || r.FilingLockedAt != null));
        if (vatFiled)
            throw new InvalidOperationException(
                $"กู้คืนไม่ได้ — เดือนภาษี {taxDate:MM/yyyy} ของเอกสาร {doc.DocumentNumber} ยื่น ภ.พ.30 แล้ว. " +
                "ให้ออกเอกสารใหม่ในเดือนปัจจุบันแทน");

        // Gate 3 — เลขเอกสารต้องยังว่าง (ไม่มีใบ active อื่นถือเลขนี้). ปกติ
        // voided number ไม่ถูก reuse จึง unique อยู่แล้ว — ตรวจกันเคส edge
        // (เช่นมีการ import/แก้มือ) ก่อนคืนชีพ กัน gap-free §86/4 พัง
        var numberTaken = await _db.Documents.AsNoTracking().AnyAsync(d =>
            d.CompanyId == companyId && d.Id != documentId && !d.IsDeleted
            && d.DocumentNumber == doc.DocumentNumber
            && d.Status != DocumentStatus.Voided);
        if (numberTaken)
            throw new InvalidOperationException(
                $"กู้คืนไม่ได้ — เลข {doc.DocumentNumber} ถูกใช้กับเอกสารอื่นแล้ว");

        // คืนสถานะ Draft (คงเลขเดิม). void ได้ reset posting flags (7a) +
        // deposit subledger (7b/7c) เป็น "พร้อม approve ใหม่" ไว้แล้ว → ไม่ต้อง
        // แตะ GL ที่นี่. ผู้ใช้กด 'อนุมัติ' → post JE ใหม่ + ออก e-Tax ใหม่
        // ผ่าน pipeline เดิม (verified). payment/ApplyDeposit เดิมถูก void ไป
        // แล้ว ไม่คืนอัตโนมัติ — ต้องบันทึกใหม่หลังอนุมัติ.
        doc.Status = DocumentStatus.Draft;
        doc.AgingDays = null;
        doc.AgingLastEvaluatedAt = DateTime.UtcNow;
        doc.UpdatedAt = DateTime.UtcNow;
        doc.Notes = (doc.Notes ?? "")
            + $"\n[กู้คืนจากยกเลิก] {DateTime.UtcNow:yyyy-MM-dd HH:mm} UTC โดย {actor} — "
            + "คืนเป็นฉบับร่าง เลขเดิมคงไว้; กรุณากดอนุมัติเพื่อลงบัญชี/e-Tax ใหม่";
        await _db.SaveChangesAsync();

        await FireWebhookAsync(companyId, "document.restored", new
        {
            documentId = doc.Id,
            documentNumber = doc.DocumentNumber,
            documentType = doc.DocumentType.ToString(),
            restoredAt = DateTime.UtcNow,
        });

        _logger.LogInformation("Restored voided document {DocNum} (company {Cid}) by {Actor} → Draft",
            doc.DocumentNumber, companyId, actor);
        return await GetDocumentAsync(companyId, documentId);
    }

    /// <summary>
    /// ลบเอกสารถาวร — เฉพาะเอกสารฉบับร่าง (Draft) ที่ยังไม่กระทบบัญชีและไม่มีการชำระเงินเท่านั้น
    /// เอกสารที่อนุมัติแล้วต้องใช้ "ยกเลิก" (VoidDocumentAsync) เพื่อรักษา audit trail.
    /// </summary>
    public async Task DeleteDocumentAsync(Guid companyId, Guid documentId)
    {
        var doc = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        if (doc.Status != DocumentStatus.Draft)
            throw new InvalidOperationException(
                "ไม่สามารถลบเอกสารที่อนุมัติแล้วได้ — กรุณาใช้คำสั่ง 'ยกเลิก' " +
                "เพื่อสร้างรายการกลับบัญชีตามมาตรฐาน (รักษา audit trail)");

        var hasJournal = await _db.JournalEntries.AnyAsync(j => j.SourceDocumentId == documentId
            && j.CompanyId == companyId);
        if (hasJournal)
            throw new InvalidOperationException(
                "ไม่สามารถลบเอกสารที่มีรายการบัญชีเชื่อมอยู่ได้ — กรุณาใช้ 'ยกเลิก' แทน");

        var hasPayment = await _db.Payments.AnyAsync(p => p.DocumentId == documentId
            && p.CompanyId == companyId && !p.IsDeleted);
        if (hasPayment)
            throw new InvalidOperationException(
                "ไม่สามารถลบเอกสารที่มีการชำระเงินแล้วได้ — กรุณายกเลิกการชำระเงินก่อน");

        var hasEtax = await _db.EtaxInvoices.AnyAsync(e => e.DocumentId == documentId
            && e.CompanyId == companyId && e.Status != EtaxStatus.Voided);
        if (hasEtax)
            throw new InvalidOperationException(
                "ไม่สามารถลบเอกสารที่มีใบกำกับภาษีอิเล็กทรอนิกส์ (e-Tax) เชื่อมอยู่ได้");

        await using var transaction = await _db.Database.BeginTransactionAsync();
        try
        {
            // ── ตัดตัวชี้จากสแกน OCR ก่อนลบแถวเอกสาร ─────────────────────────
            //
            // `OcrScanResult.CreatedDocumentId` เป็น `Guid?` เปล่า ๆ **ไม่มี FK**
            // ⇒ ลบเอกสารแล้วตัวชี้ค้างอยู่โดยไม่มีอะไรฟ้อง ⇒ การ์ดบนหน้า OCR ยัง
            // ติดป้าย "สร้างแล้ว" · กดแล้วเด้ง "ไม่พบเอกสาร" · แท็บ "รอตรวจสอบ"
            // ไม่เห็นสแกนใบนี้อีกเลย · และ**ด่านกันสร้างซ้ำ**ก็อ่านช่องนี้ ⇒ ผู้ใช้
            // สร้างเอกสารใหม่จากสแกนเดิมไม่ได้ ทั้งที่ของเก่าถูกลบไปแล้ว
            // (ผู้ใช้รายงาน 2026-09-18 — ตัวตัดสินอยู่ที่ Helpers/OcrCreatedDocumentLink)
            var linkedScans = await _db.Set<OcrScanResult>()
                .Where(sr => sr.CompanyId == companyId && sr.CreatedDocumentId == documentId)
                .ToListAsync();
            foreach (var sr in linkedScans)
            {
                sr.CreatedDocumentId = null;
                // ต่อท้ายเสมอ ห้ามทับ — ช่องนี้เป็นที่สะสมที่ด่านอื่นอ่านธงจากมัน
                sr.ProcessingNotes = (sr.ProcessingNotes ?? "")
                    + Accounting.Helpers.OcrCreatedDocumentLink.UnlinkNote(doc.DocumentNumber, DateTime.UtcNow);
                sr.UpdatedAt = DateTime.UtcNow;
            }

            // Hard-delete lines first (FK), then header. Use Remove (not soft-delete)
            // because Draft never reached the books — no audit obligation.
            _db.DocumentLines.RemoveRange(doc.Lines);
            _db.Documents.Remove(doc);
            await _db.SaveChangesAsync();
            await transaction.CommitAsync();

            if (linkedScans.Count > 0)
                _logger.LogInformation(
                    "ลบเอกสาร {DocNum} แล้วตัดตัวชี้จากสแกน OCR {Count} ใบ — สแกนกลับไปสถานะ 'ยังไม่ได้สร้างเอกสาร'",
                    doc.DocumentNumber, linkedScans.Count);
        }
        catch
        {
            await transaction.RollbackAsync();
            throw;
        }
    }

    /// <summary>Un-realize ใบมัดจำเมื่อใบเช็คเอาท์ (drives) ถูก void/purge —
    /// คิดยอดจาก "บรรทัด JE จริงของใบเช็คเอาท์" (audit F1-F3): apply คิดจาก GL
    /// legs 3 โหมด (gross/defer/recognized) ถ้า un-realize คิดจาก field ratio
    /// จะ drift (เคส gross: Realized ค้าง +VAT-portion ทุกรอบ apply/void) และ
    /// การเคลียร์ RecognizedAt ด้วย flag/mark อาจไปล้าง stamp ของ RealizeDeposit
    /// ครั้งก่อน → realize รอบถัดไป Dr 21913 ซ้ำ (21913 ติดลบ / 21911 เบิ้ล /
    /// ภ.พ.30 นับซ้ำ). JE ของใบเช็คเอาท์คือ mirror ที่แม่นยำของสิ่งที่ apply ทำ:
    ///   depBase จริง = Σ Dr บนบัญชีมัดจำ (215xx/217xx) ใน JE ต้นฉบับของใบนี้
    ///   ใบนี้เป็นผู้ stamp RecognizedAt จริง ⟺ JE มี Dr 21913
    /// ข้อบังคับ: purge ต้องเรียก "ก่อนลบ JE"; void เรียกได้ปกติ (JE แค่ถูก reverse
    /// — ใช้เฉพาะ JE ต้นฉบับ OriginalEntryId == null). ไม่ SaveChanges เอง.</summary>
    private async Task UnrealizeDrivesDepositAsync(Guid companyId, Document doc)
    {
        // ref อาจเป็นเลข NextAcc (DocumentNumber) หรือเลขระบบต้นทาง (Reference =
        // externalRef เช่น REC260713008 ของ TakeTime) — จับคู่เลขเราก่อน แล้วค่อย ref
        var deposit = await _db.Documents.FirstOrDefaultAsync(d =>
                d.CompanyId == companyId && d.IsDeposit && !d.IsDeleted
                && d.DocumentNumber == doc.DepositAppliedRef)
            ?? await _db.Documents.FirstOrDefaultAsync(d =>
                d.CompanyId == companyId && d.IsDeposit && !d.IsDeleted
                && d.Reference == doc.DepositAppliedRef);
        if (deposit != null)
        {
            // อ่านขา Dr จริงจาก JE ต้นฉบับของใบเช็คเอาท์ (ไม่รวม reversal)
            var coLines = await _db.JournalEntryLines.AsNoTracking()
                .Where(l => !l.IsDeleted
                    && l.JournalEntry.CompanyId == companyId
                    && l.JournalEntry.SourceDocumentId == doc.Id
                    && l.JournalEntry.OriginalEntryId == null
                    && !l.JournalEntry.IsDeleted
                    && l.DebitAmount > 0)
                .Select(l => new { l.AccountId, l.DebitAmount })
                .ToListAsync();
            var acctIds = coLines.Select(l => l.AccountId).Distinct().ToList();
            var acctCodes = await _db.ChartOfAccounts.AsNoTracking()
                .Where(a => a.CompanyId == companyId && acctIds.Contains(a.Id))
                .Select(a => new { a.Id, a.AccountCode })
                .ToListAsync();
            string CodeOf(Guid id) => acctCodes.FirstOrDefault(a => a.Id == id)?.AccountCode ?? "";

            var depBase = coLines
                .Where(l => CodeOf(l.AccountId).StartsWith("217") || CodeOf(l.AccountId).StartsWith("215"))
                .Sum(l => l.DebitAmount);
            var stamped21913 = coLines.Any(l => CodeOf(l.AccountId) == "21913");
            if (coLines.Count == 0)
            {
                // ไม่พบ JE (เคสประวัติศาสตร์/ถูกลบไปก่อน) → fallback field ratio เดิม
                var depVatRatio = deposit.TotalAmount > 0 ? deposit.VatAmount / deposit.TotalAmount : 0m;
                depBase = Math.Round(doc.DepositAppliedAmount * (1 - depVatRatio), 2, MidpointRounding.AwayFromZero);
                stamped21913 = deposit.DepositOutputVatDeferred;
            }

            deposit.DepositRealizedAmount = Math.Max(0m, deposit.DepositRealizedAmount - depBase);
            // ยังไม่ realized ครบ → เคลียร์วันปิด (กลับเป็น "มัดจำคงค้าง")
            if (deposit.SubTotal - deposit.DepositRealizedAmount > 0.005m)
                deposit.DepositRealizedAt = null;
            if (deposit.DepositAppliedToDocumentId == doc.Id)
            {
                // เคลียร์ RecognizedAt เฉพาะเมื่อ "ใบนี้เป็นผู้ stamp จริง" (มี Dr
                // 21913) — เคส net+21911 mark ก็ถูกตั้ง แต่ RecognizedAt เป็นของ
                // RealizeDeposit ครั้งก่อน ห้ามล้าง (audit F3: ล้างผิด → realize
                // ถัดไป Dr 21913 ซ้ำ)
                if (stamped21913)
                    deposit.DepositOutputVatRecognizedAt = null;
                deposit.DepositAppliedToDocumentId = null;
            }
            deposit.UpdatedAt = DateTime.UtcNow;
        }
        else
        {
            // เคส B (journal ภายนอก): un-mark guard บน JV เพื่อให้ resync
            // (สร้างใบใหม่อ้าง journal เดิม) หักได้อีกครั้ง
            var depJe = await _db.JournalEntries.FirstOrDefaultAsync(j =>
                j.CompanyId == companyId && j.EntryNumber == doc.DepositAppliedRef
                && j.DepositAppliedToDocumentId == doc.Id);
            if (depJe != null) depJe.DepositAppliedToDocumentId = null;
        }
    }

    /// <summary>กลับ/ลบ "JV มัดจำ raw (non-drives)" ทุกตัวที่ apply เข้าใบ docNumber
    /// แล้ว un-mark JV ต้นทางให้ resync ได้. JV apply = JE ที่ SourceDocumentId=null,
    /// Reference=docNumber, IsAutoGenerated, มีทั้งขา Cr ลูกหนี้ (113) และ Dr มัดจำ
    /// (215/217) — ตัด JE ประเภทอื่นที่บังเอิญ Reference ตรงออก. void → reverse (audit
    /// trail); purge → delete (สะอาดพร้อม resync). คืน gross รวมที่กลับ (ให้ caller
    /// ปรับ PaidAmount). รองรับ apply ซ้ำหลายตัว (เคสก่อนมี guard one-shot รอบ 90).</summary>
    /// <param name="reversalDate">วันที่กลับรายการ — ส่งต่อจาก VoidDocumentAsync
    /// ให้ JV มัดจำอยู่งวดเดียวกับใบที่ยกเลิก (null = วันนี้ สำหรับ purge)</param>
    private async Task<decimal> ReverseOrphanJvDepositAppliesAsync(Guid companyId, string docNumber,
        bool deleteMode, DateTime? reversalDate = null)
    {
        var applyJes = await _db.JournalEntries.Include(j => j.Lines)
            .Where(j => j.CompanyId == companyId && j.SourceDocumentId == null
                && j.IsAutoGenerated && j.Reference == docNumber
                && j.OriginalEntryId == null && j.ReversedByEntryId == null
                && j.Status == JournalEntryStatus.Posted && !j.IsDeleted)
            .ToListAsync();
        if (applyJes.Count == 0) return 0m;

        var acctIds = applyJes.SelectMany(j => j.Lines).Select(l => l.AccountId).Distinct().ToList();
        var acctCodes = await _db.ChartOfAccounts.AsNoTracking()
            .Where(a => a.CompanyId == companyId && acctIds.Contains(a.Id))
            .Select(a => new { a.Id, a.AccountCode }).ToListAsync();
        string CodeOf(Guid id) => acctCodes.FirstOrDefault(a => a.Id == id)?.AccountCode ?? "";

        decimal totalGross = 0m;
        var affectedJvNumbers = new HashSet<string>();
        foreach (var aj in applyJes)
        {
            var arCr = aj.Lines.Where(l => !l.IsDeleted && l.CreditAmount > 0
                && CodeOf(l.AccountId).StartsWith("113")).Sum(l => l.CreditAmount);
            var depDr = aj.Lines.Any(l => !l.IsDeleted && l.DebitAmount > 0
                && (CodeOf(l.AccountId).StartsWith("215") || CodeOf(l.AccountId).StartsWith("217")));
            if (arCr <= 0m || !depDr) continue;   // ไม่ใช่ JV มัดจำ apply
            totalGross += arCr;
            if (aj.Description != null)
            {
                // ดึงเลข JV ต้นทางจาก description "นำมัดจำ (JV XXX) ตัดชำระ ..."
                var m = System.Text.RegularExpressions.Regex.Match(aj.Description, @"JV\s+([A-Za-z0-9\-]+)");
                if (m.Success) affectedJvNumbers.Add(m.Groups[1].Value);
            }
            if (deleteMode)
            {
                await _db.Database.ExecuteSqlRawAsync(
                    @"DELETE FROM ""JournalEntryLines"" WHERE ""JournalEntryId"" = {0}", aj.Id);
                await _db.Database.ExecuteSqlRawAsync(
                    @"DELETE FROM ""JournalEntries"" WHERE ""Id"" = {0} AND ""CompanyId"" = {1}", aj.Id, companyId);
            }
            else
            {
                await _accountingService.ReverseJournalEntryAsync(companyId, aj.Id,
                    reversalDate: (reversalDate ?? DateTime.UtcNow).Date,
                    description: $"ยกเลิกเอกสาร {docNumber} — คืน JV มัดจำ", systemTriggered: true);
            }
        }

        // un-mark JV ต้นทาง (JournalEntry ที่มี DepositAppliedToDocumentId ชี้ใบนี้ผ่าน
        // EntryNumber ที่ดึงมา) — ให้ SearchJournalDeposits โชว์กลับมาหักใบใหม่ได้
        if (affectedJvNumbers.Count > 0)
        {
            var jvs = await _db.JournalEntries
                .Where(j => j.CompanyId == companyId && affectedJvNumbers.Contains(j.EntryNumber)
                    && j.DepositAppliedToDocumentId != null)
                .ToListAsync();
            foreach (var jv in jvs) { jv.DepositAppliedToDocumentId = null; jv.UpdatedAt = DateTime.UtcNow; }
        }
        return totalGross;
    }

    public async Task PurgeDocumentAsync(Guid companyId, Guid documentId)
    {
        await PurgeDocumentAsync(companyId, documentId, null);
    }

    public async Task PurgeDocumentAsync(Guid companyId, Guid documentId, Guid? userId)
    {
        await PurgeDocumentAsync(companyId, documentId, userId, forceOverrideRetention: false, overrideReason: null);
    }

    /// <summary>ลบเอกสารถาวร. ปกติ block เอกสารที่อยู่ในช่วงเก็บรักษา §87/3
    /// (5 ปี) — ต้องใช้ Void แทน. แต่ Owner/SystemAdmin override ได้ด้วย
    /// forceOverrideRetention=true + เหตุผล (เช่น ข้อมูลทดสอบ / สร้างผิดซ้ำ)
    /// → ระบบ log การ override ลง ErrorLog (audit) ว่าใคร/เมื่อไหร่/ทำไม
    /// เพื่อความรับผิดชอบ. ความเสี่ยงทางกฎหมายเป็นของผู้ override.</summary>
    public async Task PurgeDocumentAsync(Guid companyId, Guid documentId, Guid? userId,
        bool forceOverrideRetention, string? overrideReason)
    {
        var doc = await _db.Documents
            .IgnoreQueryFilters()
            .Include(d => d.Lines)   // ApplyStockMovementsAsync(-1) อ่านจาก Lines (mirror void)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        // Legal hold §87/3 + พ.ร.บ.บัญชี ม.10 — ห้ามลบจริงก่อนครบอายุเก็บ 5 ปี
        // (เอกสารที่ approve แล้วเท่านั้นที่มี RetentionUntil; Draft ลบได้).
        var inRetention = doc.RetentionUntil.HasValue
            && DateTime.UtcNow.Date < doc.RetentionUntil.Value.Date
            && doc.Status != DocumentStatus.Draft;
        if (inRetention && !forceOverrideRetention)
            throw new InvalidOperationException(
                $"ห้ามลบถาวร — เอกสารอยู่ในช่วงเก็บรักษาตามกฎหมาย (§87/3) ถึง {doc.RetentionUntil:dd/MM/yyyy}. " +
                "ใช้ 'ยกเลิกเอกสาร' (Void) แทนเพื่อคงหลักฐานการตรวจสอบ");

        // Override path — บันทึก audit ว่าใคร force-delete เอกสารในช่วง retention
        // ทำไม. ทำให้สรรพากร/ผู้ตรวจเห็น trail ว่าการลบเป็นการตัดสินใจที่ระบุ
        // ตัวตน + เหตุผล ไม่ใช่ลบลับ ๆ. ถ้าไม่ระบุเหตุผล → block (กันลบมั่ว).
        if (inRetention && forceOverrideRetention)
        {
            if (string.IsNullOrWhiteSpace(overrideReason))
                throw new InvalidOperationException(
                    "การลบเอกสารในช่วงเก็บรักษาตามกฎหมายต้องระบุเหตุผล (เช่น ข้อมูลทดสอบ / สร้างผิดซ้ำ)");
            // audit ผ่าน logger (forensic) — บันทึกว่าใคร force-delete เอกสารใน
            // ช่วง retention ทำไม. AuditLog hash-chain ก็จับ Delete นี้อีกชั้น
            // ผ่าน ChangeTracker (append-only).
            _logger.LogWarning(
                "RETENTION-OVERRIDE: user {UserId} force-deleted {DocNum} ({DocType}, retain until {Until:yyyy-MM-dd}). Reason: {Reason}",
                userId, doc.DocumentNumber, doc.DocumentType, doc.RetentionUntil, overrideReason);
        }

        var auditSnapshot = System.Text.Json.JsonSerializer.Serialize(new
        {
            doc.DocumentNumber, doc.DocumentType, doc.Status,
            doc.TotalAmount, doc.ContactId, doc.DocumentDate
        });

        // เก็บ id ไว้ unwind ReconciliationGroup หลัง commit (rows ถูกลบไปแล้ว
        // แต่ GroupItems ยังอ้าง id ค้าง — unwind ตามหลังได้)
        var purgedPaymentIds = new List<Guid>();
        var purgedJournalIds = new List<Guid>();

        await using var transaction = await _db.Database.BeginTransactionAsync();
        try
        {
            // 0. un-mark มัดจำภายนอก (JV) ที่เอกสารนี้เคยหักไว้ (drives) — กันมัดจำ
            //    stuck ชี้ ghost หลัง purge → เช็คเอาท์ใหม่หักมัดจำเดิมได้ (ไม่ throw
            //    "ถูกนำไปหักกับเอกสารอื่น"). self-heal guard ก็ครอบให้ แต่ล้างเชิงรุก
            //    เพื่อข้อมูลสะอาด (raw UPDATE — ตรงสไตล์ purge, atomic ใน transaction)
            await _db.Database.ExecuteSqlRawAsync(
                @"UPDATE ""JournalEntries"" SET ""DepositAppliedToDocumentId"" = NULL
                  WHERE ""DepositAppliedToDocumentId"" = {0} AND ""CompanyId"" = {1}",
                documentId, companyId);

            // 0b. un-realize ใบมัดจำ (Document) ที่ใบนี้หักแบบ drives (audit F7) —
            //     ต้องทำ "ก่อนลบ JE" เพราะคิดยอดจากบรรทัด JE จริง. เดิม purge คืน
            //     GL (ลบ JE) แต่ subledger มัดจำค้าง (Realized/AppliedTo ghost) →
            //     หน้ามัดจำโชว์ "รับรู้ครบ" ทั้งที่ GL มีหนี้สินคงค้าง + ภ.พ.30
            //     ข้ามใบมัดจำตลอดไป (AppliedTo ชี้ doc ที่หายไปแล้ว)
            if (!doc.IsDeposit && doc.DepositAppliedDrivesJournal
                && doc.DepositAppliedAmount > 0 && !string.IsNullOrWhiteSpace(doc.DepositAppliedRef))
            {
                await UnrealizeDrivesDepositAsync(companyId, doc);
                await _db.SaveChangesAsync();   // persist subledger ก่อนขั้น raw-SQL ลบ JE
            }

            // 0c. คืนมัดจำที่ถูก "ตัดชำระด้วย JV" (ApplyDepositToInvoiceAsync — เส้น
            //     non-drives) — mirror ของ VoidDocumentAsync step 2b. JV นั้น
            //     SourceDocumentId = ใบมัดจำ (ไม่ใช่ใบนี้) จึงหลุด step 1 → ถ้าไม่คืน:
            //     Dr 217xx/21913 ของ JV ค้าง (มัดจำถูกตัดถาวร) + subledger ไม่คืน →
            //     recreate ทับ → 21510 สะสมติดลบ (root cause ที่ TakeTime เจอ −934.58).
            //     purge = ลบ JV ทิ้ง (lines+entry) + คืน subledger (ก่อนลบ JE ของใบนี้).
            var purgeAppliedDeposits = await _db.Documents
                .Where(d => d.CompanyId == companyId && d.IsDeposit && !d.IsDeleted
                    && d.DepositAppliedToDocumentId == documentId)
                .ToListAsync();
            foreach (var dep in purgeAppliedDeposits)
            {
                var applyJes = await _db.JournalEntries.Include(j => j.Lines)
                    .Where(j => j.CompanyId == companyId && j.SourceDocumentId == dep.Id
                        && j.OriginalEntryId == null && !j.IsDeleted
                        && j.Reference == doc.DocumentNumber)
                    .ToListAsync();
                if (applyJes.Count == 0) continue;   // drives-mode → 0b จัดการแล้ว

                var acctIds = applyJes.SelectMany(j => j.Lines).Select(l => l.AccountId).Distinct().ToList();
                var acctCodes = await _db.ChartOfAccounts.AsNoTracking()
                    .Where(a => a.CompanyId == companyId && acctIds.Contains(a.Id))
                    .Select(a => new { a.Id, a.AccountCode }).ToListAsync();
                string CodeOf(Guid id) => acctCodes.FirstOrDefault(a => a.Id == id)?.AccountCode ?? "";

                decimal restoredBase = 0m; bool had21913 = false, restoredAny = false;
                foreach (var applyJe in applyJes)
                {
                    // JV ตัดชำระ = มีขา Cr ลูกหนี้ (113) — กัน JE อื่นของใบมัดจำที่ Reference ตรง
                    var grossCr = applyJe.Lines.Where(l => !l.IsDeleted && l.CreditAmount > 0
                        && CodeOf(l.AccountId).StartsWith("113")).Sum(l => l.CreditAmount);
                    if (grossCr <= 0m) continue;
                    restoredBase += applyJe.Lines.Where(l => !l.IsDeleted && l.DebitAmount > 0
                            && (CodeOf(l.AccountId).StartsWith("217") || CodeOf(l.AccountId).StartsWith("215")))
                        .Sum(l => l.DebitAmount);
                    had21913 |= applyJe.Lines.Any(l => !l.IsDeleted && l.DebitAmount > 0
                        && CodeOf(l.AccountId) == "21913");
                    // ลบ JV ทิ้ง (lines + entry) — purge style
                    await _db.Database.ExecuteSqlRawAsync(
                        @"DELETE FROM ""JournalEntryLines"" WHERE ""JournalEntryId"" = {0}", applyJe.Id);
                    await _db.Database.ExecuteSqlRawAsync(
                        @"DELETE FROM ""JournalEntries"" WHERE ""Id"" = {0} AND ""CompanyId"" = {1}",
                        applyJe.Id, companyId);
                    restoredAny = true;
                }
                if (!restoredAny) continue;
                dep.DepositRealizedAmount = System.Math.Max(0m, dep.DepositRealizedAmount - restoredBase);
                if (dep.SubTotal - dep.DepositRealizedAmount > 0.005m)
                    dep.DepositRealizedAt = null;
                if (had21913)
                    dep.DepositOutputVatRecognizedAt = null;
                dep.DepositAppliedToDocumentId = null;
                dep.UpdatedAt = DateTime.UtcNow;
            }

            // 0c-JV) ลบ "JV มัดจำ raw (non-drives)" ที่ apply เข้าใบนี้ + un-mark JV
            //   ต้นทาง — เหมือน void 2b-JV แต่ delete แทน reverse (purge style). ไม่ทำ →
            //   3 JV apply (Dr 21510/Cr 113) ค้างเป็น orphan หลังลบใบ + JV mark ค้าง
            //   (นำไป apply ใบใหม่ไม่ได้) = เคสจริงที่หัก JV ซ้ำ 3 ครั้ง
            await ReverseOrphanJvDepositAppliesAsync(companyId, doc.DocumentNumber, deleteMode: true);

            if (purgeAppliedDeposits.Count > 0)
                await _db.SaveChangesAsync();

            // 0d. กลับ "ผลข้างเคียงนอก GL" ของการ approve — mirror VoidDocumentAsync
            //     (เดิม purge ลบแค่ JE/Payment → สต๊อกค้างตัดของเอกสารผี, ยอดใบต้นทาง
            //     ที่ถูกใบนี้ตัดชำระไม่คืน, project billed/cost ค้าง → resync สร้างใหม่
            //     = ตัดซ้ำ/เบิ้ลทุกตัว). ข้าม Draft (ไม่เคย post) และ Voided (void
            //     กลับให้ครบแล้วตอนยกเลิก — ทำซ้ำ = คืนเกิน)
            var wasPosted = doc.Status != DocumentStatus.Draft && doc.Status != DocumentStatus.Voided;
            if (wasPosted)
            {
                await RevertSourceDocumentAdjustmentsAsync(companyId, doc);          // คืนยอดใบต้นทาง (ใบเสร็จ/CN/PV ที่ตัดยอด)
                await ApplyProjectBillingAsync(companyId, doc, -1);                  // คืน BilledAmount โครงการ
                await ApplyStockMovementsAsync(companyId, doc, -1, "system-purge");  // คืนสต๊อก (OUT→IN / IN→OUT)
                await ReverseProjectCostEntriesAsync(companyId, doc);                // คืน ActualCost โครงการ
                await _db.SaveChangesAsync();
            }

            // ลบแถว stock movement ของใบนี้ทิ้ง (ต้นฉบับ + ตัวคืนจาก -1 ซึ่ง net ศูนย์
            // กันแล้ว) — ไม่งั้น stock card โชว์รายการอ้างเอกสารผี + resync เบิ้ลแถว
            await _db.StockMovements.IgnoreQueryFilters()
                .Where(m => m.CompanyId == companyId && m.DocumentId == documentId)
                .ExecuteDeleteAsync();

            // 0e. FixedAsset ที่ AutoRegister จากใบนี้ — mirror void 7-asset:
            //     ยังไม่ยืนยัน + ไม่มีค่าเสื่อม posted → ลบ (orphan placeholder);
            //     นอกนั้นเก็บไว้แต่ตัด link กันชี้เอกสารผี (ผู้ใช้ dispose เองผ่าน UI)
            var purgeAssets = await _db.FixedAssets
                .Where(a => a.CompanyId == companyId && a.SourceDocumentId == documentId)
                .ToListAsync();
            foreach (var asset in purgeAssets)
            {
                var hasPostedDep = await _db.AssetDepreciations
                    .AnyAsync(d => d.FixedAssetId == asset.Id && d.IsPosted && !d.IsDeleted);
                if (asset.NeedsReview && !hasPostedDep)
                {
                    var deps = await _db.AssetDepreciations
                        .Where(d => d.FixedAssetId == asset.Id).ToListAsync();
                    _db.AssetDepreciations.RemoveRange(deps);
                    _db.FixedAssets.Remove(asset);
                }
                else
                {
                    asset.SourceDocumentId = null;
                    asset.UpdatedAt = DateTime.UtcNow;
                    _logger.LogWarning(
                        "Purge {Doc}: asset {Code} ยืนยันแล้ว/มีค่าเสื่อม — คงไว้แต่ตัด link เอกสาร (dispose เองผ่าน UI)",
                        doc.DocumentNumber, asset.AssetCode);
                }
            }
            if (purgeAssets.Count > 0)
                await _db.SaveChangesAsync();

            // 1. Delete JournalLineDimensions → JournalEntryLines → JournalEntries
            var journalIds = await _db.JournalEntries
                .IgnoreQueryFilters()
                .Where(j => j.SourceDocumentId == documentId && j.CompanyId == companyId)
                .Select(j => j.Id)
                .ToListAsync();

            // Also include reversal entries (linked via OriginalEntryId or ReversedByEntryId)
            if (journalIds.Any())
            {
                var reversalIds = await _db.JournalEntries
                    .IgnoreQueryFilters()
                    .Where(j => j.CompanyId == companyId &&
                        (journalIds.Contains(j.OriginalEntryId ?? Guid.Empty) ||
                         journalIds.Contains(j.ReversedByEntryId ?? Guid.Empty)))
                    .Select(j => j.Id)
                    .ToListAsync();
                journalIds = journalIds.Union(reversalIds).Distinct().ToList();
            }

            if (journalIds.Any())
            {
                var lineIds = await _db.JournalEntryLines
                    .IgnoreQueryFilters()
                    .Where(l => journalIds.Contains(l.JournalEntryId))
                    .Select(l => l.Id)
                    .ToListAsync();

                if (lineIds.Any())
                {
                    await _db.Database.ExecuteSqlRawAsync(
                        @"DELETE FROM ""JournalLineDimensions"" WHERE ""JournalEntryLineId"" = ANY({0})",
                        lineIds);
                    await _db.Database.ExecuteSqlRawAsync(
                        @"DELETE FROM ""JournalEntryLines"" WHERE ""Id"" = ANY({0})",
                        lineIds);
                }

                // ปลด bank match ที่ชี้ JE พวกนี้ — ต้อง reset สถานะกลับ Unmatched ด้วย
                // (เดิม null แค่ id → แถวค้างสถานะ Matched ทั้งที่คู่ match หายไปแล้ว
                // = จับคู่ใหม่ไม่ได้ตลอดไป). mirror VoidDocumentAsync step 4
                await _db.BankTransactions
                    .Where(t => t.CompanyId == companyId
                        && t.MatchedJournalEntryId.HasValue
                        && journalIds.Contains(t.MatchedJournalEntryId.Value))
                    .ExecuteUpdateAsync(s => s
                        .SetProperty(t => t.MatchedJournalEntryId, (Guid?)null)
                        .SetProperty(t => t.ReconciliationStatus, ReconciliationStatus.Unmatched)
                        .SetProperty(t => t.ReconciledAt, (DateTime?)null));

                await _db.Database.ExecuteSqlRawAsync(
                    @"DELETE FROM ""JournalEntries"" WHERE ""Id"" = ANY({0})",
                    journalIds);
                purgedJournalIds.AddRange(journalIds);
            }

            // 2. Delete Payments — ปลด bank match ที่ชี้ payment พวกนี้ก่อน
            //    (เดิมลบ raw ทิ้ง MatchedPaymentId ค้างชี้ payment ผี + สถานะ
            //    Matched ค้าง → กระทบยอดธนาคารจับคู่ใหม่ไม่ได้)
            purgedPaymentIds = await _db.Payments.IgnoreQueryFilters()
                .Where(p => p.DocumentId == documentId && p.CompanyId == companyId)
                .Select(p => p.Id)
                .ToListAsync();
            if (purgedPaymentIds.Count > 0)
            {
                await _db.BankTransactions
                    .Where(t => t.CompanyId == companyId
                        && t.MatchedPaymentId.HasValue
                        && purgedPaymentIds.Contains(t.MatchedPaymentId.Value))
                    .ExecuteUpdateAsync(s => s
                        .SetProperty(t => t.MatchedPaymentId, (Guid?)null)
                        .SetProperty(t => t.ReconciliationStatus, ReconciliationStatus.Unmatched)
                        .SetProperty(t => t.ReconciledAt, (DateTime?)null));
            }
            await _db.Database.ExecuteSqlRawAsync(
                @"DELETE FROM ""Payments"" WHERE ""DocumentId"" = {0} AND ""CompanyId"" = {1}",
                documentId, companyId);

            // 3. Delete WHT certificates + lines linked to this document
            var whtIds = await _db.WithholdingTaxCerts
                .IgnoreQueryFilters()
                .Where(w => w.DocumentId == documentId && w.CompanyId == companyId)
                .Select(w => w.Id)
                .ToListAsync();

            if (whtIds.Any())
            {
                await _db.Database.ExecuteSqlRawAsync(
                    @"DELETE FROM ""WithholdingTaxCertLines"" WHERE ""WithholdingTaxCertId"" = ANY({0})",
                    whtIds);
                await _db.Database.ExecuteSqlRawAsync(
                    @"DELETE FROM ""WithholdingTaxCerts"" WHERE ""Id"" = ANY({0})",
                    whtIds);
            }

            // 4. Delete EtaxInvoices
            await _db.Database.ExecuteSqlRawAsync(
                @"DELETE FROM ""EtaxInvoices"" WHERE ""DocumentId"" = {0} AND ""CompanyId"" = {1}",
                documentId, companyId);

            // 5. Null out DocumentEmailLogs (FK is SetNull but we force-clean)
            await _db.Database.ExecuteSqlRawAsync(
                @"UPDATE ""DocumentEmailLogs"" SET ""DocumentId"" = NULL WHERE ""DocumentId"" = {0}",
                documentId);

            // 6. Delete DocumentApprovals & DocumentSignatures
            await _db.Database.ExecuteSqlRawAsync(
                @"DELETE FROM ""DocumentApprovals"" WHERE ""DocumentId"" = {0}",
                documentId);
            await _db.Database.ExecuteSqlRawAsync(
                @"DELETE FROM ""DocumentSignatures"" WHERE ""DocumentId"" = {0}",
                documentId);

            // 6c. ลบ "ใบเสร็จหลักฐานรับเงิน" (settlement receipt) ที่ผูกกับเอกสารนี้
            //     ทิ้งพร้อมกัน — ใบพวกนี้เป็น artifact ของการชำระ (payment ถูกลบใน
            //     step 2, JE ถูกลบ step 1) ไม่มี JE ของตัวเอง. เดิม step 7 แค่ NULL
            //     RelatedDocumentId → ใบเสร็จลอยค้างใน list (ผู้ใช้เห็น "ใบเสร็จงอก
            //     เยอะ" หลังลบใบกำกับ). ลบ recursive (เผื่อมี e-Tax/line) ผ่าน purge
            //     ตัวเอง เพื่อข้อมูลสะอาดพร้อม resync ใหม่.
            var settlementChildIds = await _db.Documents.IgnoreQueryFilters()
                .Where(d => d.CompanyId == companyId && d.RelatedDocumentId == documentId
                    && d.IsSettlementReceipt)
                .Select(d => d.Id)
                .ToListAsync();
            foreach (var recId in settlementChildIds)
            {
                await _db.Database.ExecuteSqlRawAsync(
                    @"DELETE FROM ""EtaxInvoices"" WHERE ""DocumentId"" = {0} AND ""CompanyId"" = {1}",
                    recId, companyId);
                await _db.Database.ExecuteSqlRawAsync(
                    @"DELETE FROM ""DocumentLines"" WHERE ""DocumentId"" = {0}", recId);
                await _db.Database.ExecuteSqlRawAsync(
                    @"DELETE FROM ""Documents"" WHERE ""Id"" = {0} AND ""CompanyId"" = {1}",
                    recId, companyId);
            }

            // 7. Null out references from other documents (RelatedDocumentId) —
            //    settlement receipts ถูกลบใน 6c แล้ว เหลือ ref อื่น (convert chain ฯลฯ)
            await _db.Database.ExecuteSqlRawAsync(
                @"UPDATE ""Documents"" SET ""RelatedDocumentId"" = NULL WHERE ""RelatedDocumentId"" = {0}",
                documentId);

            // 7b. ตัด link จาก OCR scan ที่เคยสร้างใบนี้ — คืนสถานะ scan เป็น "ยัง
            //     ไม่สร้างเอกสาร" (สร้างใหม่/resync ได้ ไม่ค้างชี้เอกสารผี; ไฟล์แนบ
            //     ของ scan คงอยู่ — FileAttachment ผูกกับ scan ไม่ใช่เอกสาร)
            await _db.Set<OcrScanResult>()
                .Where(s => s.CompanyId == companyId && s.CreatedDocumentId == documentId)
                .ExecuteUpdateAsync(s => s.SetProperty(x => x.CreatedDocumentId, (Guid?)null));

            // 8. Delete DocumentLines → Document
            await _db.Database.ExecuteSqlRawAsync(
                @"DELETE FROM ""DocumentLines"" WHERE ""DocumentId"" = {0}",
                documentId);
            await _db.Database.ExecuteSqlRawAsync(
                @"DELETE FROM ""Documents"" WHERE ""Id"" = {0} AND ""CompanyId"" = {1}",
                documentId, companyId);

            if (userId.HasValue)
            {
                _db.AuditLogs.Add(new AuditLog
                {
                    CompanyId = companyId,
                    UserId = userId,
                    Action = AuditAction.Delete,
                    EntityType = "Document",
                    EntityId = documentId.ToString(),
                    OldValues = auditSnapshot,
                    Timestamp = DateTime.UtcNow
                });
                await _db.SaveChangesAsync();
            }

            await transaction.CommitAsync();
        }
        catch
        {
            await transaction.RollbackAsync();
            throw;
        }
        finally
        {
            _db.ChangeTracker.Clear();
        }

        // ปลด ReconciliationGroup ที่อ้าง document/payment/JE ที่เพิ่งถูกลบ —
        // GroupItems เก็บ id ไว้แม้แถวจริงตายแล้ว → group ค้างอ้างผี + bank txn
        // ในกลุ่มติดสถานะ Matched ถาวร. ทำหลัง commit แบบ best-effort
        // (mirror VoidPaymentAsync/VoidDocumentAsync)
        if (_bankService != null)
        {
            try
            {
                await _bankService.UnwindGroupsContainingItemAsync(companyId, ReconciliationItemType.Document, documentId);
                foreach (var pid in purgedPaymentIds)
                    await _bankService.UnwindGroupsContainingItemAsync(companyId, ReconciliationItemType.Payment, pid);
                foreach (var jid in purgedJournalIds)
                    await _bankService.UnwindGroupsContainingItemAsync(companyId, ReconciliationItemType.JournalEntry, jid);
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "Purge {DocId}: unwind reconciliation groups ไม่สำเร็จ (non-fatal)", documentId);
            }
        }
    }

    /// <summary>
    /// ยกเลิกการชำระเงิน — กลับรายการ JE ของการชำระ + คืนยอดให้เอกสารต้นทาง.
    /// ใช้ทั้งจาก endpoint โดยตรง และจาก VoidDocumentAsync (cascade).
    /// </summary>
    public async Task VoidPaymentAsync(Guid companyId, Guid paymentId)
    {
        var payment = await _db.Payments.FirstOrDefaultAsync(p => p.Id == paymentId
            && p.CompanyId == companyId && !p.IsDeleted)
            ?? throw new KeyNotFoundException("ไม่พบรายการชำระเงิน");

        var doc = await _db.Documents.FirstOrDefaultAsync(d => d.Id == payment.DocumentId
            && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสารต้นทาง");

        var strategy = _db.Database.CreateExecutionStrategy();
        await strategy.ExecuteAsync(async () =>
        {
            await using var tx = await _db.Database.BeginTransactionAsync();
            try
            {
                // Lock the payment row INSIDE the transaction เพื่อกัน void ซ้อน
                // (two concurrent voids ต่างอ่าน IsDeleted=false แล้ว reverse ทั้งคู่
                //  → bank balance/PaidAmount ถูกกลับสองรอบ). Re-read สถานะหลัง lock:
                //  ถ้าถูก void ไปแล้ว = no-op idempotent.
                var locked = await _db.Payments
                    .FromSqlRaw(
                        """SELECT * FROM "Payments" WHERE "Id" = {0} AND "CompanyId" = {1} FOR UPDATE""",
                        paymentId, companyId)
                    .FirstOrDefaultAsync();
                if (locked == null || locked.IsDeleted)
                {
                    await tx.RollbackAsync();
                    return;
                }

                // Multi-doc payment (เงินก้อนเดียวจัดสรรหลายใบ) ต้องใช้ path เฉพาะ:
                // JE ใช้ Reference "{PayNo}/{i}" และยอดต้องคืนรายใบตาม allocation —
                // เดิมวิ่งเข้า path ใบเดียวแล้วหา JE ไม่เจอ → throw หรือหักยอดใบแรก
                // ด้วยยอดเช็คทั้งใบ
                var hasAllocations = await _db.PaymentAllocations
                    .AnyAsync(a => a.PaymentId == locked.Id && a.CompanyId == companyId && !a.IsDeleted);
                if (hasAllocations)
                    await ReverseMultiDocPaymentInternalAsync(companyId, locked, "ยกเลิกการชำระเงิน");
                else
                    await ReversePaymentInternalAsync(companyId, locked, doc, "ยกเลิกการชำระเงิน");
                await _db.SaveChangesAsync();
                await tx.CommitAsync();
            }
            catch
            {
                await tx.RollbackAsync();
                throw;
            }
        });

        // Cascade-unwind any ReconciliationGroup that referenced this Payment
        // directly (ItemType=Payment). JE-pathed groups were unwound by
        // ReversePaymentInternalAsync → ReverseJournalEntryAsync → bank cleanup.
        if (_bankService != null)
        {
            try { await _bankService.UnwindGroupsContainingItemAsync(companyId, ReconciliationItemType.Payment, paymentId); }
            catch (Exception ex) { _logger.LogWarning(ex, "Group unwind for voided payment {PayId} failed", paymentId); }
        }

        // ── ปลดการจับคู่แบบ 1:1 ที่ไม่ได้อยู่ในกลุ่ม (M-2) ─────────────────
        // `MatchAsync` (จับคู่รายการเดินบัญชี ↔ การชำระเงิน) ตั้ง MatchedPaymentId
        // + สถานะ Matched โดย **ไม่สร้าง ReconciliationGroup** ⇒ unwind ข้างบน
        // ไม่แตะ. ผลเมื่อยกเลิกการชำระ: รายการเดินบัญชียังขึ้นว่า "กระทบยอดแล้ว"
        // กับเงินที่ถูกกลับรายการไปแล้ว และจับคู่ใหม่กับการชำระที่แก้แล้วไม่ได้เลย
        // (auto-match ตัด payment ที่ถูก match ไปแล้วทิ้ง + txn ไม่ได้อยู่สถานะ
        // Unmatched) — เส้น purge เอกสารทำถูกอยู่แล้ว ขาดแค่เส้นยกเลิกการชำระ
        try
        {
            await _db.BankTransactions
                .Where(t => t.CompanyId == companyId && t.MatchedPaymentId == paymentId)
                .ExecuteUpdateAsync(s => s
                    .SetProperty(t => t.MatchedPaymentId, (Guid?)null)
                    .SetProperty(t => t.ReconciliationStatus, ReconciliationStatus.Unmatched)
                    .SetProperty(t => t.ReconciledAt, (DateTime?)null));
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex,
                "ปลดการจับคู่ธนาคารของการชำระที่ยกเลิก {PayId} ไม่สำเร็จ — " +
                "ตรวจรายการเดินบัญชีที่ยังค้างสถานะกระทบยอดด้วยมือ", paymentId);
        }
    }

    /// <summary>
    /// ตัดหนี้สูญ — เมื่อลูกหนี้ผิดนัดและมั่นใจว่าจะไม่ได้รับเงิน
    /// JE: Dr หนี้สูญ (64xxx), Cr ลูกหนี้การค้า (113)
    /// อัพเดต source.PaidAmount = TotalAmount, BalanceDue = 0, Status = Paid (เคลียร์)
    /// </summary>
    public async Task<DocumentResponse> WriteOffBadDebtAsync(Guid companyId, Guid documentId, string writtenOffBy, string? reason = null)
    {
        var doc = await _db.Documents.FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        // Only AR documents with outstanding balance can be written off
        var arTypes = new[] {
            DocumentType.Invoice, DocumentType.TaxInvoice, DocumentType.DebitNote
        };
        if (!arTypes.Contains(doc.DocumentType))
            throw new InvalidOperationException(
                "ตัดหนี้สูญได้เฉพาะใบแจ้งหนี้ / ใบกำกับภาษี / ใบเพิ่มหนี้ ที่ยังคงค้างเท่านั้น");

        if (doc.Status != DocumentStatus.Approved
            && doc.Status != DocumentStatus.PartiallyPaid
            && doc.Status != DocumentStatus.Sent
            && doc.Status != DocumentStatus.Overdue)
            throw new InvalidOperationException(
                "ตัดหนี้สูญได้เฉพาะเอกสารที่อนุมัติแล้วและยังคงค้าง");

        if (doc.BalanceDue <= 0.01m)
            throw new InvalidOperationException("เอกสารนี้ไม่มียอดคงค้าง — ไม่ต้องตัดหนี้สูญ");

        // Find or fall back to bad-debt expense account
        var badDebtAcc = await FindAccountAsync(companyId, "64000")
            ?? await FindAccountAsync(companyId, "55000")
            ?? await _db.ChartOfAccounts
                .Where(a => a.CompanyId == companyId
                    && a.AccountType == AccountType.Expense
                    && a.AccountName!.Contains("หนี้สูญ")
                    && a.IsActive)
                .OrderBy(a => a.AccountCode)
                .FirstOrDefaultAsync();
        if (badDebtAcc == null)
            throw new InvalidOperationException(
                "ไม่พบบัญชี 'หนี้สูญ' (64000) ในผังบัญชี กรุณาเพิ่มบัญชีก่อน");

        var arAcc = await FindAccountAsync(companyId, "113", doc.Contact)
            ?? throw new InvalidOperationException("ไม่พบบัญชี 'ลูกหนี้การค้า' (113) ในผังบัญชี");

        var writeOffAmount = doc.BalanceDue;

        var strategy = _db.Database.CreateExecutionStrategy();
        await strategy.ExecuteAsync(async () =>
        {
            await using var tx = await _db.Database.BeginTransactionAsync();
            try
            {
                // Resolve fiscal period
                var period = await _db.FiscalPeriods.FirstOrDefaultAsync(f =>
                    f.CompanyId == companyId &&
                    f.StartDate <= DateTime.UtcNow.Date &&
                    f.EndDate >= DateTime.UtcNow.Date);
                if (period != null && period.Status != FiscalPeriodStatus.Open)
                    throw new InvalidOperationException(
                        $"ไม่สามารถตัดหนี้สูญในงวด {period.Name} ได้ เนื่องจากงวดถูกปิดแล้ว");

                var entryNumber = await GetNextJournalEntryNumberAsync(companyId, "JV");
                var je = new JournalEntry
                {
                    CompanyId = companyId,
                    EntryNumber = entryNumber,
                    EntryDate = DateTime.UtcNow.Date,
                    JournalType = JournalType.General,
                    Description = $"ตัดหนี้สูญ - {doc.DocumentNumber}" + (reason != null ? $" ({reason})" : ""),
                    Reference = doc.DocumentNumber,
                    Status = JournalEntryStatus.Posted,
                    TotalDebit = writeOffAmount,
                    TotalCredit = writeOffAmount,
                    CreatedBy = writtenOffBy,
                    IsAutoGenerated = true,
                    SourceDocumentId = doc.Id,
                    FiscalPeriodId = period?.Id,
                    ProjectId = doc.ProjectId
                };
                _db.JournalEntries.Add(je);
                _db.JournalEntryLines.Add(new JournalEntryLine
                {
                    JournalEntryId = je.Id,
                    AccountId = badDebtAcc.Id,
                    DebitAmount = writeOffAmount,
                    CreditAmount = 0,
                    Description = $"หนี้สูญ - {doc.DocumentNumber}",
                    LineOrder = 1,
                    ProjectId = doc.ProjectId
                });
                _db.JournalEntryLines.Add(new JournalEntryLine
                {
                    JournalEntryId = je.Id,
                    AccountId = arAcc.Id,
                    DebitAmount = 0,
                    CreditAmount = writeOffAmount,
                    Description = $"ตัดลูกหนี้ - {doc.DocumentNumber}",
                    LineOrder = 2,
                    ProjectId = doc.ProjectId
                });

                // Clear the source document
                doc.PaidAmount = doc.TotalAmount;
                doc.BalanceDue = 0;
                doc.Status = DocumentStatus.Paid;
                doc.AgingDays = null;
                doc.AgingLastEvaluatedAt = DateTime.UtcNow;
                doc.UpdatedBy = writtenOffBy;
                doc.UpdatedAt = DateTime.UtcNow;
                AppendInternalNote(doc,
                    $"ตัดหนี้สูญ {DateTime.UtcNow.ToString("yyyy-MM-dd", System.Globalization.CultureInfo.InvariantCulture)}: {reason ?? ""}");

                await _db.SaveChangesAsync();
                await tx.CommitAsync();
            }
            catch
            {
                await tx.RollbackAsync();
                throw;
            }
        });

        return await GetDocumentAsync(companyId, documentId);
    }

    /// <summary>
    /// Internal: reverses a single payment within an existing transaction.
    /// - Creates JE reversal (via AccountingService) for the payment's posted JE
    /// - Soft-deletes the payment (IsDeleted=true) — keeps record for audit
    /// - Restores doc.PaidAmount and doc.BalanceDue
    /// - Recalculates doc.Status (Paid → PartiallyPaid → Approved)
    /// Caller is responsible for transaction + final SaveChangesAsync.
    /// </summary>
    /// <param name="reversalDate">วันที่กลับรายการ (null = วันนี้) — void ส่ง
    /// วันที่เอกสารมาให้ JE รับชำระกลับอยู่งวดเดียวกับที่บันทึกรับเงินไว้</param>
    private async Task ReversePaymentInternalAsync(Guid companyId, Payment payment, Document doc, string reason,
        DateTime? reversalDate = null)
    {
        // Reverse linked JEs created from this payment.
        // Payment JEs are linked via SourceDocumentId = doc.Id with a Reference matching payment.PaymentNumber.
        // รองรับ Reference แบบมี suffix "{PayNo}/{i}" ด้วย — ข้อมูลเก่าที่เคยเป็น
        // multi-doc payment แล้ว allocation ถูกลบไปแล้วยังเหลือ JE รูปแบบนั้นอยู่
        var paymentJournals = await _db.JournalEntries
            .Where(j => j.SourceDocumentId == doc.Id
                && j.CompanyId == companyId
                && j.Status == JournalEntryStatus.Posted
                && j.OriginalEntryId == null
                && j.Reference != null
                && (j.Reference == payment.PaymentNumber
                    || j.Reference.StartsWith(payment.PaymentNumber + "/")))
            .Select(j => j.Id)
            .ToListAsync();

        // Fail loud if the payment posted to GL but we can't find the JE to
        // reverse — silently skipping leaves Cash/AR overstated. The most
        // common cause is a Reference-format drift (whitespace, case). Log
        // the discrepancy and surface a clear error so the operator can
        // reverse the orphan JE manually instead of corrupting GL silently.
        if (paymentJournals.Count == 0)
        {
            var anyJeForDoc = await _db.JournalEntries
                .AnyAsync(j => j.SourceDocumentId == doc.Id
                    && j.CompanyId == companyId
                    && j.Status == JournalEntryStatus.Posted);
            if (anyJeForDoc)
                throw new InvalidOperationException(
                    $"ไม่พบ JE ที่ผูกกับใบรับเงิน {payment.PaymentNumber} (อาจถูกแก้ Reference ภายหลัง) — " +
                    "กรุณากลับรายการ JE ด้วยมือก่อนทำการ Reverse Payment เพื่อไม่ให้ยอด Cash/AR ใน GL คลาดเคลื่อน");
        }

        foreach (var jeId in paymentJournals)
        {
            await _accountingService.ReverseJournalEntryAsync(companyId, jeId,
                reversalDate: (reversalDate ?? DateTime.UtcNow).Date,
                description: $"{reason} - {payment.PaymentNumber}",
                systemTriggered: true);
        }

        // Reverse bank balance — payment.Amount is in the document's currency;
        // BankAccount.CurrentBalance is in THB, so apply the document's FX rate
        // before adjusting. Mirrors the conversion in CreatePaymentJournalAsync.
        if (payment.BankAccountId.HasValue)
        {
            var isInflow = await IsCashInflowDocAsync(companyId, doc);
            // ใช้ rate เดียวกับตอนบันทึกรับ/จ่าย (settlement rate ถ้ามี) —
            // มิฉะนั้นยอดธนาคารกลับไม่เท่าที่บวกไว้
            var reverseFx = payment.ExchangeRate ?? doc.ExchangeRate;
            var thbAmount = reverseFx == 1m
                ? payment.Amount
                : Math.Round(payment.Amount * reverseFx, 2, MidpointRounding.AwayFromZero);
            var delta = isInflow ? -thbAmount : thbAmount;
            await _db.BankAccounts
                .Where(b => b.Id == payment.BankAccountId.Value && b.CompanyId == companyId)
                .ExecuteUpdateAsync(s => s.SetProperty(b => b.CurrentBalance, b => b.CurrentBalance + delta));
        }

        // Soft-delete the payment record (keep for audit; mirrors how Reverse keeps original JE)
        payment.IsDeleted = true;
        payment.UpdatedAt = DateTime.UtcNow;

        // void ใบเสร็จรับเงินหลักฐานที่ออกคู่กับการชำระนี้ (ถ้ามี) — ไม่มี JE ให้กลับ
        // (evidence-only) แค่ mark Voided + soft-delete ไม่ให้ค้างในรายการ/พิมพ์ได้
        if (payment.ReceiptDocumentId.HasValue)
        {
            var rcpt = await _db.Documents.FirstOrDefaultAsync(d =>
                d.Id == payment.ReceiptDocumentId.Value && d.CompanyId == companyId);
            if (rcpt is { IsSettlementReceipt: true })
            {
                rcpt.Status = DocumentStatus.Voided;
                rcpt.IsDeleted = true;
                rcpt.UpdatedAt = DateTime.UtcNow;
            }
        }

        // Restore document balance (รวมค่าธรรมเนียมที่เคยล้างเอกสารด้วย)
        // + หนี้ที่เคยปิดด้วยบรรทัดปรับ (รอบ 193 — ขา JE ถูกกลับพร้อม JE การชำระข้างบนแล้ว)
        doc.PaidAmount = Math.Max(0m, doc.PaidAmount - payment.Amount - payment.FeeAmount - payment.SettlementAdjustmentAmount);
        doc.BalanceDue = doc.TotalAmount - doc.PaidAmount;
        if (doc.Status != DocumentStatus.Voided)
        {
            doc.Status = doc.PaidAmount <= 0 ? DocumentStatus.Approved
                : doc.BalanceDue <= 0 ? DocumentStatus.Paid
                : DocumentStatus.PartiallyPaid;
        }
        doc.UpdatedAt = DateTime.UtcNow;

        // ── กลับ "ภาษีขายถึงกำหนด" เมื่อไม่เหลือการรับชำระแล้ว (M-6) ──────────
        // TryReclassifyUndueOutputVatAsync ย้าย VAT ทั้งก้อน 21913 → 21911 ตอน
        // รับเงินงวดแรก (tax point §78/1) แต่ JE ตัวนั้นใช้ Reference = เลขเอกสาร
        // ไม่ใช่เลข Payment ⇒ ตัวเลือก JE ด้านบนไม่แตะ ⇒ void การชำระแล้ว VAT
        // ยังค้างที่ 21911 + OutputVatDueAt ยังตั้ง ⇒ ภ.พ.30 งวดนั้นเก็บภาษีขาย
        // ของเงินที่ไม่เคยได้รับ และรับชำระใหม่ก็ถูก idempotent guard บล็อกถาวร
        if (doc.PaidAmount <= 0.005m && doc.OutputVatDueAt != null)
            await TryUndoUndueOutputVatReclassAsync(companyId, doc, reason);

        // ── ทะเบียนเครดิตภาษีถูกหัก ณ ที่จ่ายฝั่งขาย 11910 (M-4) ─────────────
        // SyncWhtCreditReceivedAsync อ่านจาก GL จริงและลบแถวเองเมื่อยอดเป็น 0
        // — ถ้าไม่เรียกหลัง void แถวเครดิตจะค้างเข้า ภ.ง.ด.50 ทั้งที่ JE ถูกกลับ
        // ไปแล้ว (ขอเครดิตภาษีที่ไม่เคยถูกหักจริง)
        try { await SyncWhtCreditReceivedAsync(companyId, doc); }
        catch (Exception ex)
        {
            _logger.LogWarning(ex,
                "sync ทะเบียนเครดิต WHT หลังยกเลิกการชำระ {Doc} ไม่สำเร็จ", doc.DocumentNumber);
        }

        // 50 ทวิ ที่ auto-สร้างตอนบันทึกจ่าย (audit B5): ยกเลิก payment แล้วเอกสาร
        // กลับเป็นยังไม่จ่าย → cert Draft ของใบนี้ต้อง void ด้วย ไม่งั้นค้างเข้า
        // ภ.ง.ด.3/53 ทั้งที่การจ่ายไม่มีแล้ว. เฉพาะตอนไม่เหลือ payment อื่น (partial
        // อื่นยังจ่ายอยู่ = cert ยังมีมูล). Issued cert → เตือนใน log ให้ยกเลิกมือ
        // (ออกให้ผู้ถูกหักไปแล้ว ห้าม void เงียบ)
        // ⚠️ M-5: cert ที่ผูก "งวดจ่ายนั้น ๆ" (SourcePaymentId) ต้องยกเลิกเสมอ
        // ไม่ว่าเอกสารจะยังเหลือยอดจ่ายอื่นหรือไม่ — เดิมทั้งบล็อกถูกข้ามเมื่อ
        // PaidAmount > 0 ⇒ ยกเลิกงวดกลางแล้ว 50 ทวิ ของงวดนั้นยังเข้า ภ.ง.ด.
        // (นำส่งเกิน). เงื่อนไข PaidAmount <= 0 ยังใช้กับ cert ระดับ "ทั้งใบ"
        // (SourcePaymentId = null) ที่ยังมีมูลตราบใดที่ยังมีการจ่ายเหลืออยู่
        if (doc.WithholdingTaxAmount > 0)
        {
            var certs = await _db.WithholdingTaxCerts
                .Where(w => w.CompanyId == companyId && w.DocumentId == doc.Id
                    && w.Status != WithholdingTaxCertStatus.Voided
                    && (w.SourcePaymentId == payment.Id
                        || (w.SourcePaymentId == null && doc.PaidAmount <= 0.005m)))
                .ToListAsync();
            foreach (var cert in certs)
            {
                if (cert.Status == WithholdingTaxCertStatus.Draft)
                {
                    cert.Status = WithholdingTaxCertStatus.Voided;
                    cert.UpdatedAt = DateTime.UtcNow;
                }
                else
                {
                    _logger.LogWarning(
                        "VoidPayment {Doc}: หนังสือรับรอง 50 ทวิ {Cert} สถานะ {Status} ยังไม่ถูกยกเลิก — ออกให้ผู้ถูกหักแล้ว กรุณายกเลิก/ออกใหม่ด้วยตนเอง",
                        doc.DocumentNumber, cert.CertificateNumber, cert.Status);
                }
            }
        }
    }

    /// <summary>
    /// Internal: กลับรายการ "ใบรับ/จ่ายเงินที่จัดสรรหลายเอกสาร" (multi-doc payment)
    /// ภายใน transaction ที่เปิดไว้แล้ว — ต่างจาก <see cref="ReversePaymentInternalAsync"/>
    /// ตรงที่เงิน 1 ก้อนผูกหลายใบผ่าน <c>PaymentAllocation</c>:
    /// <list type="bullet">
    /// <item>JE ของแต่ละ allocation ใช้ Reference <c>{PaymentNumber}/{index}</c> และ JE
    /// เงินส่วนเกินใช้ <c>{PaymentNumber}</c> เปล่า — ต้องกลับทั้งสองแบบ</item>
    /// <item>คืนยอด <c>PaidAmount</c> ให้แต่ละเอกสาร "ตามยอด allocation ของใบนั้น"
    /// ไม่ใช่ยอดเช็คทั้งใบ</item>
    /// <item>คืนยอดธนาคารครั้งเดียวด้วยยอด THB รวม (คำนวณด้วยสูตรเดียวกับตอนสร้าง)</item>
    /// </list>
    /// Caller รับผิดชอบ transaction + SaveChangesAsync.
    /// </summary>
    /// <param name="reversalDate">วันที่กลับรายการ (null = วันนี้)</param>
    private async Task ReverseMultiDocPaymentInternalAsync(Guid companyId, Payment payment, string reason,
        DateTime? reversalDate = null)
    {
        var allocations = await _db.PaymentAllocations
            .Where(a => a.PaymentId == payment.Id && a.CompanyId == companyId && !a.IsDeleted)
            .ToListAsync();

        var docIds = allocations.Select(a => a.DocumentId).Distinct().ToList();
        var docs = await _db.Documents
            .Where(d => docIds.Contains(d.Id) && d.CompanyId == companyId)
            .ToListAsync();
        var docMap = docs.ToDictionary(d => d.Id);

        // 1) กลับ JE ทุกใบของ payment นี้ — ทั้งราย allocation ({PayNo}/{i})
        //    และ JE เงินส่วนเกินยังไม่จัดสรร ({PayNo} เปล่า ซึ่งไม่มี SourceDocumentId
        //    จึงหลุด selection ที่กรองด้วย SourceDocumentId). กรอง OriginalEntryId
        //    == null กันการกลับ "รายการกลับ" ซ้ำ
        var pn = payment.PaymentNumber;
        var journalIds = await _db.JournalEntries
            .Where(j => j.CompanyId == companyId
                && j.Status == JournalEntryStatus.Posted
                && j.OriginalEntryId == null
                && j.Reference != null
                && (j.Reference == pn || j.Reference.StartsWith(pn + "/")))
            .Select(j => j.Id)
            .ToListAsync();

        foreach (var jeId in journalIds)
        {
            await _accountingService.ReverseJournalEntryAsync(companyId, jeId,
                reversalDate: (reversalDate ?? DateTime.UtcNow).Date,
                description: $"{reason} - {pn}",
                systemTriggered: true);
        }

        // 2) คืนยอดธนาคาร — ยอด THB รวมคำนวณด้วยสูตรเดียวกับ CreateMultiDocPaymentAsync
        //    (แปลง FX ราย allocation แล้วบวกส่วนเกินที่ยังไม่จัดสรร) มิฉะนั้นยอด
        //    ธนาคารกลับไม่เท่าที่บวกไว้ตอนรับ/จ่าย
        if (payment.BankAccountId.HasValue && docs.Count > 0)
        {
            decimal thbMoved = 0m;
            decimal allocSum = 0m;
            foreach (var alloc in allocations)
            {
                if (!docMap.TryGetValue(alloc.DocumentId, out var ad)) continue;
                var fx = payment.ExchangeRate ?? ad.ExchangeRate;
                thbMoved += fx == 1m
                    ? alloc.AllocatedAmount
                    : Math.Round(alloc.AllocatedAmount * fx, 2, MidpointRounding.AwayFromZero);
                allocSum += alloc.AllocatedAmount;
            }
            var unapplied = payment.Amount - allocSum;
            if (unapplied > 0.005m)
            {
                var upFx = payment.ExchangeRate ?? docs[0].ExchangeRate;
                thbMoved += upFx == 1m
                    ? unapplied
                    : Math.Round(unapplied * upFx, 2, MidpointRounding.AwayFromZero);
            }

            var isInflow = await IsCashInflowDocAsync(companyId, docs[0]);
            var delta = isInflow ? -thbMoved : thbMoved;
            await _db.BankAccounts
                .Where(b => b.Id == payment.BankAccountId.Value && b.CompanyId == companyId)
                .ExecuteUpdateAsync(s => s.SetProperty(b => b.CurrentBalance, b => b.CurrentBalance + delta));
        }

        // 3) คืนยอดค้างชำระ "ตามยอด allocation ของแต่ละใบ"
        foreach (var alloc in allocations)
        {
            if (!docMap.TryGetValue(alloc.DocumentId, out var ad)) continue;
            ad.PaidAmount = Math.Max(0m, ad.PaidAmount - alloc.AllocatedAmount);
            ad.BalanceDue = ad.TotalAmount - ad.PaidAmount;
            if (ad.Status != DocumentStatus.Voided)
            {
                ad.Status = ad.PaidAmount <= 0 ? DocumentStatus.Approved
                    : ad.BalanceDue <= 0 ? DocumentStatus.Paid
                    : DocumentStatus.PartiallyPaid;
            }
            ad.UpdatedAt = DateTime.UtcNow;
            alloc.IsDeleted = true;
            alloc.UpdatedAt = DateTime.UtcNow;
        }

        // 4) ใบเสร็จหลักฐานที่ออกคู่กับการชำระ (evidence-only ไม่มี JE)
        if (payment.ReceiptDocumentId.HasValue)
        {
            var rcpt = await _db.Documents.FirstOrDefaultAsync(d =>
                d.Id == payment.ReceiptDocumentId.Value && d.CompanyId == companyId);
            if (rcpt is { IsSettlementReceipt: true })
            {
                rcpt.Status = DocumentStatus.Voided;
                rcpt.IsDeleted = true;
                rcpt.UpdatedAt = DateTime.UtcNow;
            }
        }

        // 5) 50 ทวิ ที่ auto-สร้างจากการจ่ายนี้ — Draft ยกเลิกได้, Issued ต้องแจ้ง
        if (payment.WithholdingTaxAmount > 0)
        {
            // ⚠️ ต้องจำกัดที่ "cert ของการจ่ายก้อนนี้" เท่านั้น — เดิมกวาดทุก cert
            // ของทุกใบใน allocation ⇒ ยกเลิกใบ 50 ทวิ ของงวดอื่นที่ยังจ่ายจริงอยู่
            // ทิ้งไปด้วย (ทิศตรงข้ามกับบั๊กของ single-doc: ตัวนั้นยกเลิกไม่พอ
            // ตัวนี้ยกเลิกเกิน — คีย์ที่ถูกคือ SourcePaymentId ทั้งคู่)
            var certs = await _db.WithholdingTaxCerts
                .Where(w => w.CompanyId == companyId && w.DocumentId != null
                    && docIds.Contains(w.DocumentId.Value)
                    && w.Status != WithholdingTaxCertStatus.Voided
                    && w.SourcePaymentId == payment.Id)
                .ToListAsync();
            foreach (var cert in certs)
            {
                if (cert.Status == WithholdingTaxCertStatus.Draft)
                {
                    cert.Status = WithholdingTaxCertStatus.Voided;
                    cert.UpdatedAt = DateTime.UtcNow;
                }
                else
                {
                    _logger.LogWarning(
                        "VoidPayment {PayNo}: หนังสือรับรอง 50 ทวิ {Cert} สถานะ {Status} ยังไม่ถูกยกเลิก — ออกให้ผู้ถูกหักแล้ว กรุณายกเลิก/ออกใหม่ด้วยตนเอง",
                        pn, cert.CertificateNumber, cert.Status);
                }
            }
        }

        payment.IsDeleted = true;
        payment.UpdatedAt = DateTime.UtcNow;
    }

    /// <summary>
    /// Updates a source document's balance/status when a derivative (Receipt, CN, DN,
    /// PaymentVoucher) referencing it is approved. This keeps AR/AP aging and per-document
    /// status consistent with the GL.
    ///
    /// Rules (Thai accounting practice):
    /// - Receipt/ReceiptVoucher with ref → settlement: source.PaidAmount += amount
    /// - PaymentVoucher with ref → AP settlement: source.PaidAmount += amount
    /// - CreditNote with ref → AR offset: source.PaidAmount += amount (treats as offset)
    /// - DebitNote with ref → no source mutation (DN is a NEW AR, not adjustment)
    ///
    /// Validation: refuses if cumulative adjustments would exceed the source's TotalAmount
    /// (i.e. you cannot refund/credit more than the customer owes).
    ///
    /// Caller is responsible for transaction + SaveChangesAsync.
    /// </summary>
    private async Task ApplySourceDocumentAdjustmentsAsync(Guid companyId, Document doc)
    {
        if (!doc.RelatedDocumentId.HasValue) return;

        var isSettlement = doc.DocumentType == DocumentType.Receipt
            || doc.DocumentType == DocumentType.ReceiptVoucher
            || doc.DocumentType == DocumentType.PaymentVoucher
            // CIL ที่อ้างเอกสารตั้งหนี้ = การจ่ายจริง (settlement JE ตัด AP)
            || doc.DocumentType == DocumentType.CertificateInLieu;
        var isCreditNote = doc.DocumentType == DocumentType.CreditNote;
        var isDebitNote = doc.DocumentType == DocumentType.DebitNote;
        if (!isSettlement && !isCreditNote && !isDebitNote) return;

        // Lock source row to prevent concurrent balance modifications (FOR UPDATE)
        await _db.Database.ExecuteSqlRawAsync(
            "SELECT 1 FROM \"Documents\" WHERE \"Id\" = {0} AND \"CompanyId\" = {1} FOR UPDATE",
            doc.RelatedDocumentId.Value, companyId);

        var source = await _db.Documents.FirstOrDefaultAsync(d =>
            d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId);
        if (source == null) return;

        if (isSettlement)
        {
            // Settlement (Receipt/ReceiptVoucher/PaymentVoucher): strict cap.
            // Cannot collect/pay more than the outstanding balance.
            if (doc.TotalAmount > source.BalanceDue + 0.01m)
                throw new InvalidOperationException(
                    $"จำนวนเงินรับ/จ่าย ({doc.TotalAmount:N2}) มากกว่ายอดคงค้างของเอกสารต้นทาง " +
                    $"{source.DocumentNumber} (คงค้าง {source.BalanceDue:N2})");

            // Cumulative WHT cap — without this, operators using the
            // manual Receipt-conversion flow could over-withhold by issuing
            // sibling Receipts whose WHT sum exceeds the source Invoice's
            // total WHT, producing WHT-Asset / WHT-Payable balances that
            // don't reconcile with ภ.ง.ด.3/53. The CreatePaymentAsync (modal
            // flow) already enforces this; this branch is the missing twin.
            // Sums BOTH paths so mixing modal + manual Receipt still caps.
            if (doc.WithholdingTaxAmount > 0m && source.WithholdingTaxAmount > 0m)
            {
                var siblingTypes = new[] { DocumentType.Receipt, DocumentType.ReceiptVoucher, DocumentType.PaymentVoucher, DocumentType.CertificateInLieu };
                var withheldViaReceipts = await _db.Documents.AsNoTracking()
                    .Where(r => r.RelatedDocumentId == source.Id
                        && r.Id != doc.Id   // exclude self (we're approving it now)
                        && siblingTypes.Contains(r.DocumentType)
                        && r.Status != DocumentStatus.Voided
                        && r.Status != DocumentStatus.Draft
                        && r.Status != DocumentStatus.Rejected
                        && !r.IsDeleted)
                    .SumAsync(r => (decimal?)r.WithholdingTaxAmount) ?? 0m;
                var withheldViaPayments = await _db.Payments.AsNoTracking()
                    .Where(p => p.DocumentId == source.Id && !p.IsDeleted)
                    .SumAsync(p => (decimal?)p.WithholdingTaxAmount) ?? 0m;
                var cumulative = withheldViaReceipts + withheldViaPayments + doc.WithholdingTaxAmount;
                if (cumulative > source.WithholdingTaxAmount + 0.01m)
                    throw new InvalidOperationException(
                        $"WHT รวมจากใบเสร็จ/ใบสำคัญทั้งหมด ({cumulative:N2}) เกินยอด WHT " +
                        $"ของเอกสารต้นทาง {source.DocumentNumber} ({source.WithholdingTaxAmount:N2}) " +
                        "— โปรดแก้ไข WHT บนเอกสารฉบับนี้ก่อนอนุมัติ");
            }

            // ===== กัน "ลูกหนี้ค้างเพราะ WHT หาย" (เกณฑ์ Cash เท่านั้น) =====
            //
            // เกณฑ์ Cash: ใบต้นทางตั้งลูกหนี้ไว้ **gross** (TotalAmount + WHT)
            // แล้ว JE ใบเสร็จ Cr AR = TotalAmount ของใบเสร็จ + WHT ของใบเสร็จ
            // ⇒ ถ้าใบเสร็จปิดยอดใบต้นทางจนหมด (BalanceDue→0) แต่ WHT สะสมไม่ครบ
            // ตามที่ใบต้นทางระบุ จะเหลือลูกหนี้ค้างใน GL เท่ากับส่วนที่ขาด —
            // ขณะที่ระดับเอกสารขึ้นว่า "ชำระครบ" (BalanceDue คิดจาก TotalAmount
            // ที่หัก WHT ไปแล้ว) ⇒ งบดุลกับสถานะเอกสารขัดกันเงียบ ๆ และเครดิต
            // ภาษี (11910) ที่ควรได้ก็หายไปด้วย ใช้ใน ภ.ง.ด.50 ไม่ได้
            //
            // เคสจริงที่เจอ: ใบแจ้งหนี้ 3,600 หัก 3% → ตัวเติมอัตโนมัติของใบเสร็จ
            // ใส่ยอด 3,492 + WHT 0% ⇒ Cr AR แค่ 3,492 เหลือค้าง 108 ถาวร
            if (source.WithholdingTaxAmount > 0m
                && await IsWhtCashBasisAsync(companyId)
                && source.PaidAmount + doc.TotalAmount >= source.TotalAmount - 0.01m)
            {
                var siblingTypes2 = new[] { DocumentType.Receipt, DocumentType.ReceiptVoucher, DocumentType.PaymentVoucher, DocumentType.CertificateInLieu };
                var whtDocs = await _db.Documents.AsNoTracking()
                    .Where(r => r.RelatedDocumentId == source.Id && r.Id != doc.Id
                        && siblingTypes2.Contains(r.DocumentType)
                        && r.Status != DocumentStatus.Voided && r.Status != DocumentStatus.Draft
                        && r.Status != DocumentStatus.Rejected && !r.IsDeleted)
                    .SumAsync(r => (decimal?)r.WithholdingTaxAmount) ?? 0m;
                var whtPays = await _db.Payments.AsNoTracking()
                    .Where(p => p.DocumentId == source.Id && !p.IsDeleted)
                    .SumAsync(p => (decimal?)p.WithholdingTaxAmount) ?? 0m;
                var whtTotal = whtDocs + whtPays + doc.WithholdingTaxAmount;
                var missing = source.WithholdingTaxAmount - whtTotal;
                if (missing > 0.01m)
                    throw new InvalidOperationException(
                        $"ใบนี้จะปิดยอด {source.DocumentNumber} จนหมด แต่ภาษีหัก ณ ที่จ่ายที่บันทึกไว้รวม "
                        + $"{whtTotal:N2} บาท ขาดไป {missing:N2} บาท จากที่เอกสารต้นทางระบุ "
                        + $"({source.WithholdingTaxAmount:N2} บาท) — อนุมัติแบบนี้จะเหลือ**ลูกหนี้ค้างใน GL "
                        + $"{missing:N2} บาท** ทั้งที่เอกสารขึ้นว่าชำระครบ และเสียเครดิตภาษีใน ภ.ง.ด.50 ไปด้วย"
                        + "\n👉 ต้องทำ: แก้ช่อง \"หัก ณ ที่จ่าย %\" ในบรรทัดของใบนี้ให้ได้ยอด "
                        + $"{missing:N2} บาท (ยอดบรรทัดต้องเป็นยอดก่อนหักภาษี ไม่ใช่ยอดเงินที่รับจริง)"
                        + $"\n• ถ้าลูกค้าไม่ได้หักภาษีจริง ให้แก้ WHT ที่ใบต้นทาง {source.DocumentNumber} เป็น 0 ก่อน");
            }

            source.PaidAmount += doc.TotalAmount;
        }
        else if (isCreditNote)
        {
            // §86/10: SUM(ใบลดหนี้ทั้งหมดที่อ้างใบเดิม) ≤ ยอดใบกำกับต้นฉบับ — กัน
            // ลดหนี้เกินยอดเดิม (โดยเฉพาะโหมดคืนเงินสดตอนใบเดิมชำระครบ ซึ่งเดิม
            // ไม่มี cap เลย → ออก CN ทับกันเกินยอดขายได้).
            var cnSiblingSum = await _db.Documents.AsNoTracking()
                .Where(c => c.RelatedDocumentId == source.Id && c.Id != doc.Id
                    && c.DocumentType == DocumentType.CreditNote
                    && c.Status != DocumentStatus.Voided && c.Status != DocumentStatus.Rejected
                    && c.Status != DocumentStatus.Draft && !c.IsDeleted)
                .SumAsync(c => (decimal?)c.TotalAmount) ?? 0m;
            if (cnSiblingSum + doc.TotalAmount > source.TotalAmount + 0.01m)
                throw new InvalidOperationException(
                    $"ยอดใบลดหนี้รวม ({cnSiblingSum + doc.TotalAmount:N2}) เกินยอดเอกสารต้นฉบับ " +
                    $"{source.DocumentNumber} ({source.TotalAmount:N2}) — §86/10 ลดหนี้เกินยอดเดิมไม่ได้");

            // CN: validation depends on source state.
            // - If source still has BalanceDue > 0: CN reduces AR/AP, capped by BalanceDue
            // - If source fully paid (BalanceDue = 0): CN becomes cash refund — JE
            //   handles the cash flow. Source state stays at Paid (PaidAmount unchanged).
            if (source.BalanceDue > 0.01m)
            {
                if (doc.TotalAmount > source.BalanceDue + 0.01m)
                    throw new InvalidOperationException(
                        $"จำนวนใบลดหนี้ ({doc.TotalAmount:N2}) มากกว่ายอดคงค้างของเอกสารต้นทาง " +
                        $"{source.DocumentNumber} (คงค้าง {source.BalanceDue:N2}) " +
                        $"— หากต้องการคืนเงินเกินกว่ายอดคงค้าง กรุณาแยกเป็นใบลดหนี้หลายใบ");

                source.PaidAmount += doc.TotalAmount;
            }
            // else: cash refund mode — source.PaidAmount stays at TotalAmount,
            // BalanceDue stays at 0, Status stays at Paid. JE Cr Cash handles it.
        }
        else if (isDebitNote)
        {
            // DN: increases the obligation (customer owes more / we owe more)
            // - If source has BalanceDue > 0: DN adds to BalanceDue (effectively
            //   reduces source.PaidAmount accumulation; we model it as TotalAmount += DN)
            //   Actually simpler: leave source untouched — DN is a separate AR/AP doc itself.
            // - If source fully paid: DN creates a new debt that needs to be collected
            //   separately. The DN itself acts as the new AR.
            //
            // For both cases: do NOT mutate source. The DN is a separate document
            // and shows up in AR/AP aging on its own merit.
            //
            // (User can still link via RelatedDocumentId for traceability.)
            return;
        }

        source.BalanceDue = source.TotalAmount - source.PaidAmount;
        if (source.Status != DocumentStatus.Voided)
        {
            source.Status = source.BalanceDue <= 0.01m
                ? DocumentStatus.Paid
                : DocumentStatus.PartiallyPaid;
            // Settle stale aging on the source the same instant the
            // settlement flips it to Paid (Receipt/PaymentVoucher converted
            // path). Without this the source invoice keeps showing "⏳ 30+d"
            // until the background job runs hours later.
            if (source.Status == DocumentStatus.Paid)
            {
                source.AgingDays = null;
                source.AgingLastEvaluatedAt = DateTime.UtcNow;
            }
        }
        source.UpdatedAt = DateTime.UtcNow;
    }

    /// <summary>
    /// Reverse of ApplySourceDocumentAdjustmentsAsync — called from VoidDocumentAsync
    /// when a derivative document is voided, to restore the source's balance.
    /// </summary>
    private async Task RevertSourceDocumentAdjustmentsAsync(Guid companyId, Document doc)
    {
        if (!doc.RelatedDocumentId.HasValue) return;

        var typeAffectsSource = doc.DocumentType == DocumentType.Receipt
            || doc.DocumentType == DocumentType.ReceiptVoucher
            || doc.DocumentType == DocumentType.PaymentVoucher
            || doc.DocumentType == DocumentType.CertificateInLieu
            || doc.DocumentType == DocumentType.CreditNote;
        if (!typeAffectsSource) return;

        var source = await _db.Documents.FirstOrDefaultAsync(d =>
            d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId);
        if (source == null) return;

        // CreditNote: revert ลด PaidAmount ได้เฉพาะเมื่อตอน apply เคย "เพิ่ม" —
        // คือ AR-mode (ออก CN ตอน source ยังค้าง → Cr ลูกหนี้ 113). ถ้าเป็น
        // cash-refund mode (source จ่ายครบแล้ว → JE Cr เงินสด 111, ไม่แตะ
        // PaidAmount) แล้ว revert ไปลด PaidAmount = สร้าง "ลูกหนี้ผี" (ลูกค้าค้าง
        // เงินที่จ่ายไปแล้ว). ดูจาก JE ต้นฉบับของ CN ว่าเครดิตบัญชีลูกหนี้ (113) ไหม.
        if (doc.DocumentType == DocumentType.CreditNote)
        {
            // ฝั่งขาย: CN AR-mode เครดิต 113; ฝั่งซื้อ (audit F3): CN AP-mode
            // "เดบิต" AP (212xx) — เดิมเช็คแค่ Cr 113 → CN ซื้อถูกมองเป็น cash-
            // refund เสมอ → void แล้วไม่คืน PaidAmount ของ PI (ค้างเป็นยอดผี)
            var cnAdjustedSource = await _db.JournalEntryLines.AnyAsync(l =>
                l.JournalEntry.SourceDocumentId == doc.Id
                && l.JournalEntry.CompanyId == companyId
                && l.JournalEntry.OriginalEntryId == null
                && ((l.CreditAmount > 0 && l.Account.AccountCode.StartsWith("113"))
                    || (l.DebitAmount > 0 && l.Account.AccountCode.StartsWith("212"))));
            if (!cnAdjustedSource) return;   // cash-refund mode → ไม่แตะ source
        }

        source.PaidAmount = Math.Max(0m, source.PaidAmount - doc.TotalAmount);
        source.BalanceDue = source.TotalAmount - source.PaidAmount;
        if (source.Status != DocumentStatus.Voided)
        {
            source.Status = source.PaidAmount <= 0.01m
                ? DocumentStatus.Approved
                : source.BalanceDue <= 0.01m
                    ? DocumentStatus.Paid
                    : DocumentStatus.PartiallyPaid;
            // Whatever the new status is, the aging counter is now stale —
            // either the source went back to having a balance (aging
            // restarts from DocumentDate, computed by the background job)
            // or the source stayed Paid because of other settlements
            // (aging is null). Null in either case; the cron repopulates.
            // Without this, voiding a Receipt left the now-unpaid source
            // Invoice still showing "⏳ 30+d" until the 6h job ran.
            source.AgingDays = null;
            source.AgingLastEvaluatedAt = DateTime.UtcNow;
        }
        source.UpdatedAt = DateTime.UtcNow;
    }

    /// <summary>
    /// Roll an approved customer-billing document's value into its linked
    /// project's BilledAmount — the Documents → Project data flow that was
    /// missing, leaving project profitability reports showing zero billed.
    /// <paramref name="sign"/> is +1 on approval, -1 when the document is
    /// voided. Only Invoice / TaxInvoice / DebitNote count as billing;
    /// Receipts and purchase-side documents do not represent new billing.
    /// Caller owns the transaction + SaveChangesAsync.
    /// </summary>
    private async Task ApplyProjectBillingAsync(Guid companyId, Document doc, int sign)
    {
        if (!doc.ProjectId.HasValue) return;

        var billingTypes = new[] {
            DocumentType.Invoice, DocumentType.TaxInvoice, DocumentType.DebitNote
        };
        if (!billingTypes.Contains(doc.DocumentType)) return;

        var project = await _db.Projects
            .FirstOrDefaultAsync(p => p.Id == doc.ProjectId.Value && p.CompanyId == companyId);
        if (project == null) return;

        project.BilledAmount = Math.Max(0m, project.BilledAmount + sign * doc.TotalAmount);
        project.UpdatedAt = DateTime.UtcNow;
    }

    /// <summary>
    /// Valid document conversions per Thai accounting workflow.
    /// Each entry: source type → list of allowed target types.
    /// Anything not listed is rejected to prevent illogical flows like
    /// Quotation→CreditNote (CN must reference Invoice/TaxInvoice/sale).
    /// </summary>
    // ⚠️ มี MIRROR ฝั่ง frontend: documents.html `_validConversions` (ใช้ตัดสิน
    // ว่าจะโชว์ปุ่ม/ตัวเลือก "แปลงเอกสาร") — แก้ตารางนี้ต้องแก้ที่นั่นคู่กัน
    private static readonly Dictionary<DocumentType, DocumentType[]> ValidConversions = new()
    {
        // Sales side
        [DocumentType.Quotation] = new[]
        {
            DocumentType.Invoice, DocumentType.TaxInvoice,
            DocumentType.BillingNote, DocumentType.DeliveryNote,
            DocumentType.Receipt
        },
        [DocumentType.BillingNote] = new[]
        {
            DocumentType.Invoice, DocumentType.TaxInvoice, DocumentType.Receipt
        },
        [DocumentType.DeliveryNote] = new[]
        {
            DocumentType.Invoice, DocumentType.TaxInvoice
        },
        [DocumentType.Invoice] = new[]
        {
            DocumentType.TaxInvoice, DocumentType.Receipt, DocumentType.ReceiptVoucher
        },
        [DocumentType.TaxInvoice] = new[]
        {
            DocumentType.Receipt, DocumentType.ReceiptVoucher,
            DocumentType.CreditNote, DocumentType.DebitNote
        },
        [DocumentType.DebitNote] = new[]
        {
            DocumentType.Receipt, DocumentType.ReceiptVoucher
        },
        // Purchase side — full PR → PO → GRN → Invoice → Payment chain.
        // GRN inserted between PO and PurchaseInvoice so partial receipts
        // are tracked + 3-way match can validate billing against actual
        // receipt quantities.
        // Role separation (หลักบัญชีไทย): the PR→PO→GRN trade chain is backed
        // by the supplier's invoice and lands on ใบแจ้งหนี้ซื้อ (เจ้าหนี้การค้า
        // 21210) ONLY. ใบบันทึกค่าใช้จ่าย is the non-trade expense claim
        // (เจ้าหนี้อื่น 21220) and is never part of the PO chain — keeping the
        // two payable ledgers reconcilable independently.
        [DocumentType.PurchaseRequisition] = new[] { DocumentType.PurchaseOrder },
        [DocumentType.PurchaseOrder] = new[]
        {
            DocumentType.GoodsReceiptNote,        // partial GRN against PO
            DocumentType.PurchaseInvoice,         // skip GRN when buying services
        },
        [DocumentType.GoodsReceiptNote] = new[]
        {
            // From GRN, AP creates the bill. SourceLineId on the new
            // invoice line points back to the GRN line so 3-way match
            // can verify "billed qty ≤ received qty".
            DocumentType.PurchaseInvoice,
        },
        [DocumentType.PurchaseInvoice] = new[]
        {
            DocumentType.PaymentVoucher,
            // Adjustments from supplier — supplier issues us CN/DN.
            // Posting auto-detects purchase-side via RelatedDocumentId.
            DocumentType.CreditNote, DocumentType.DebitNote
        },
        [DocumentType.Expense] = new[]
        {
            DocumentType.PaymentVoucher,
            DocumentType.CreditNote, DocumentType.DebitNote,
            DocumentType.CertificateInLieu
        },
        [DocumentType.CertificateInLieu] = new[]
        {
            DocumentType.PaymentVoucher
        },
        // PV "จ่ายทันที" standalone = ตั้งหนี้+จ่ายในใบเดียว (ไม่มี PI/Expense ให้
        // CN อ้าง) — ผู้ขายส่งของพร้อมใบลดหนี้/เพิ่มหนี้ทีหลังต้องอ้าง PV ได้
        // (ValidateConversionAsync กัน PV แบบ settlement ที่อ้าง PI/Expense —
        // เคสนั้นต้องออก CN อ้างเอกสารตั้งหนี้แทน)
        [DocumentType.PaymentVoucher] = new[]
        {
            DocumentType.CreditNote, DocumentType.DebitNote
        },
        // ใบเสร็จที่ "เป็นใบกำกับภาษีในตัว" (ขายสด standalone Cr 21911 เอง /
        // settlement ถือ VAT §78/1 ที่เป็นเจ้าของแถว ภ.พ.30) — §86/9-10 บังคับ
        // CN/DN อ้าง "กระดาษใบกำกับจริง" ซึ่งเคสพวกนี้คือใบเสร็จ ไม่ใช่ใบแจ้งหนี้
        // (ValidateConversionAsync กันใบเสร็จหลักฐานรับเงินเปล่า/ใบมัดจำ)
        [DocumentType.Receipt] = new[]
        {
            DocumentType.CreditNote, DocumentType.DebitNote
        },
        [DocumentType.ReceiptVoucher] = new[]
        {
            DocumentType.CreditNote, DocumentType.DebitNote
        }
        // Terminal types (no further conversion): CreditNote
    };

    /// <summary>Public accessor used by API endpoint to surface valid targets to UI.</summary>
    public static IReadOnlyList<DocumentType> GetValidConversionTargets(DocumentType source) =>
        ValidConversions.TryGetValue(source, out var targets) ? targets : Array.Empty<DocumentType>();

    /// <summary>ด้านกลับของ <see cref="ValidConversions"/>: เอกสารชนิดไหน "แปลงมาเป็น" <paramref name="target"/> ได้
    /// — คือชนิดที่สแกนใบใหม่ควรไปหา "ใบต้นทาง" ในระบบ (PO/GRN ของใบซื้อ · ใบเสนอราคา/ใบวางบิล/ใบส่งของ
    /// ของใบแจ้งหนี้ · ใบแจ้งหนี้/ใบกำกับของใบเสร็จ ฯลฯ). คำนวณจากตารางเดียว ไม่พิมพ์ซ้ำ</summary>
    public static IReadOnlyList<DocumentType> GetPredecessorTypes(DocumentType target) =>
        ValidConversions.Where(kv => kv.Value.Contains(target)).Select(kv => kv.Key).Distinct().ToList();

    /// <summary>เกณฑ์รับรู้ WHT เป็นแบบ Cash หรือไม่ (ค่าเริ่มต้นของระบบ = Cash)
    ///
    /// <para>Cash = ใบแจ้งหนี้ตั้งลูกหนี้ไว้ <b>gross</b> (ยังไม่แตะ 11910) แล้วรับรู้
    /// WHT ตอนรับเงินจริง ⇒ ใบเสร็จต้องตัดลูกหนี้ที่ยอด gross ไม่ใช่ยอดเงินที่รับ</para></summary>
    private async Task<bool> IsWhtCashBasisAsync(Guid companyId) =>
        (await _db.CompanySettings.AsNoTracking()
            .Where(c => c.CompanyId == companyId && !c.IsDeleted)
            .Select(c => (Models.Enums.WhtRecognitionBasis?)c.WhtRecognitionBasis)
            .FirstOrDefaultAsync() ?? Models.Enums.WhtRecognitionBasis.Cash)
        == Models.Enums.WhtRecognitionBasis.Cash;

    /// <summary>บริษัทนี้จดทะเบียน VAT อยู่หรือไม่ — <see cref="Accounting.Helpers.CompanyVatStatus"/> ตัวเดียว
    /// (ไม่มีแถวค่าตั้ง = ธงบริษัท · เดิม "ถือว่าจด" เสมอ — S-01)</summary>
    private Task<bool> IsCompanyVatRegisteredAsync(Guid companyId) =>
        Accounting.Helpers.CompanyVatStatus.IsRegisteredAsync(_db, companyId);

    /// <summary>รายการชนิดปลายทางที่แปลงได้ **จริง** สำหรับบริษัทนี้ — กรองชนิดที่
    /// ติดข้อจำกัดระดับบริษัทออก (ตอนนี้: ใบกำกับภาษีเมื่อยังไม่จด VAT §90/2)
    /// เพื่อให้กล่อง "แปลงเอกสาร" ไม่โชว์ตัวเลือกที่กดแล้วต้องเจอ error</summary>
    public async Task<IReadOnlyList<DocumentType>> GetValidConversionTargetsAsync(
        Guid companyId, DocumentType source)
    {
        var targets = GetValidConversionTargets(source);
        if (targets.Contains(DocumentType.TaxInvoice)
            && !await IsCompanyVatRegisteredAsync(companyId))
            return targets.Where(t => t != DocumentType.TaxInvoice).ToList();
        return targets;
    }

    // ===================================================================
    // Flexible / partial document composition
    //
    // A source document line may be carried forward into MANY child lines
    // across MANY documents. Conversion tracks "how much is left" along two
    // independent fulfilment axes:
    //   • Delivery — consumed by DeliveryNote
    //   • Billing  — consumed by Invoice / TaxInvoice / BillingNote /
    //                PurchaseInvoice / Expense / PurchaseOrder
    // Conversions to other types (Receipt, CreditNote, ...) settle by
    // amount, not quantity, and keep the legacy whole-document behaviour.
    // ===================================================================

    private enum FulfillmentAxis { None, Delivery, Billing }

    private static FulfillmentAxis GetFulfillmentAxis(DocumentType type) => type switch
    {
        // Delivery-axis children — track "how much was physically moved":
        //   • DeliveryNote on the sales side.
        //   • GoodsReceiptNote on the purchase side (received qty from
        //     the PO; multiple partial GRNs are normal).
        DocumentType.DeliveryNote or DocumentType.GoodsReceiptNote
            => FulfillmentAxis.Delivery,
        // Billing-axis children — track "how much was invoiced":
        DocumentType.Invoice or DocumentType.TaxInvoice or DocumentType.BillingNote
            or DocumentType.PurchaseInvoice or DocumentType.Expense
            or DocumentType.PurchaseOrder => FulfillmentAxis.Billing,
        _ => FulfillmentAxis.None
    };

    private static string AxisLabel(FulfillmentAxis axis) => axis switch
    {
        FulfillmentAxis.Delivery => "ส่งมอบ",
        FulfillmentAxis.Billing => "วางบิล/แจ้งหนี้",
        _ => ""
    };

    private const decimal QtyEpsilon = 0.0001m;

    /// <summary>How much of each given source line has already been carried
    /// forward into child documents, split per fulfilment axis. Voided /
    /// Rejected / deleted child documents do not count.</summary>
    private async Task<Dictionary<Guid, (decimal Delivery, decimal Billing)>> ComputeConsumptionAsync(
        Guid companyId, List<Guid> sourceLineIds)
    {
        var result = sourceLineIds.ToDictionary(id => id, _ => (Delivery: 0m, Billing: 0m));
        if (sourceLineIds.Count == 0) return result;

        var children = await (
            from cl in _db.DocumentLines
            join cd in _db.Documents on cl.DocumentId equals cd.Id
            where cl.SourceLineId != null && sourceLineIds.Contains(cl.SourceLineId.Value)
                  && cd.CompanyId == companyId
                  && cd.Status != DocumentStatus.Voided && cd.Status != DocumentStatus.Rejected
            select new { SourceLineId = cl.SourceLineId!.Value, cl.Quantity, cd.DocumentType })
            .ToListAsync();

        foreach (var c in children)
        {
            var axis = GetFulfillmentAxis(c.DocumentType);
            var cur = result[c.SourceLineId];
            result[c.SourceLineId] = axis switch
            {
                FulfillmentAxis.Delivery => (cur.Delivery + c.Quantity, cur.Billing),
                FulfillmentAxis.Billing => (cur.Delivery, cur.Billing + c.Quantity),
                _ => cur
            };
        }
        return result;
    }

    /// <summary>Shared validation for both whole-document and partial
    /// conversion — throws on any rule violation.</summary>
    private async Task ValidateConversionAsync(Document source, DocumentType targetType, Guid companyId)
    {
        // Block converting from Voided/Rejected source — they no longer reflect
        // the customer's true position; new derivative would carry stale data.
        if (source.Status == DocumentStatus.Voided)
            throw new InvalidOperationException(
                $"เอกสาร {source.DocumentNumber} ถูกยกเลิกแล้ว ไม่สามารถแปลงเป็นเอกสารใหม่ได้");
        if (source.Status == DocumentStatus.Rejected)
            throw new InvalidOperationException(
                $"เอกสาร {source.DocumentNumber} ถูกปฏิเสธ ไม่สามารถแปลงเป็นเอกสารใหม่ได้");

        // Block converting to self (no-op)
        if (source.DocumentType == targetType)
            throw new InvalidOperationException(
                $"ไม่สามารถแปลงเป็นเอกสารประเภทเดิม ({targetType})");

        // Block invalid type-to-type conversion (e.g. Quotation→CreditNote)
        var allowedTargets = GetValidConversionTargets(source.DocumentType);
        if (!allowedTargets.Contains(targetType))
        {
            var allowedNames = string.Join(", ", allowedTargets);
            throw new InvalidOperationException(
                $"ไม่สามารถแปลง {source.DocumentType} → {targetType} ได้ตามมาตรฐานบัญชี " +
                $"(แปลงได้เฉพาะ: {(allowedNames.Length > 0 ? allowedNames : "ไม่มี — เอกสารนี้เป็นปลายทาง")})");
        }

        // ===== §90/2 — บริษัทไม่จด VAT แปลงเป็น "ใบกำกับภาษี" ไม่ได้ =====
        // ตัวใบกำกับภาษีคือการออกเอกสารเรียกเก็บ VAT โดยตรง ผู้ไม่จดทะเบียนออก
        // ไม่ได้เลย (มีโทษตาม §90/2). เดิมบล็อกไว้ที่ approve อย่างเดียว ⇒ ผู้ใช้
        // แปลงเป็น Draft ได้ กรอกครบ แล้วไปเจอ error ตอนกดอนุมัติ (เสียงานเปล่า
        // + ฟอร์มสร้างเอกสารปิดตัวเลือกนี้ไว้แล้ว แต่ทางแปลงเอกสารยังเปิดอยู่)
        if (targetType == DocumentType.TaxInvoice
            && !await IsCompanyVatRegisteredAsync(companyId))
            throw new InvalidOperationException(
                "บริษัทยังไม่ได้จดทะเบียนภาษีมูลค่าเพิ่ม — ออกใบกำกับภาษีไม่ได้ (§90/2) "
                + "· แปลงเป็น \"ใบแจ้งหนี้\" หรือ \"ใบเสร็จรับเงิน\" แทน "
                + "· ถ้าจด VAT แล้ว เปิดที่ ตั้งค่า → ภาษี → จดทะเบียนภาษีมูลค่าเพิ่ม");

        // Receipt/RV → CN/DN เปิดเฉพาะใบเสร็จที่ "เป็นใบกำกับภาษีในตัว":
        //   • ใบมัดจำ → ใช้เมนู "คืนมัดจำ" (RefundDepositAsync ออกใบลดหนี้ + กลับ
        //     VAT ตาม deposit lifecycle) — convert ตรงจะข้าม DepositRefunded*
        //   • ใบเสร็จหลักฐานรับเงินเปล่า (VAT=0 + อ้างเอกสารต้นทาง) ไม่ใช่ใบกำกับ
        //     — §86/9-10 ต้องออก CN/DN อ้างใบกำกับ/เอกสารตั้งหนี้ตัวจริงแทน
        if ((source.DocumentType == DocumentType.Receipt || source.DocumentType == DocumentType.ReceiptVoucher)
            && (targetType == DocumentType.CreditNote || targetType == DocumentType.DebitNote))
        {
            if (source.IsDeposit)
                throw new InvalidOperationException(
                    $"{source.DocumentNumber} เป็นใบมัดจำ/รับล่วงหน้า — การคืนเงิน/ลดยอดให้ใช้เมนู "
                    + "\"คืนมัดจำ\" ในหน้ารายละเอียดเอกสาร (ระบบออกใบลดหนี้ + ปรับ VAT ตามวงจรมัดจำให้ถูกต้อง)");
            if (source.VatAmount <= 0.005m && source.RelatedDocumentId.HasValue)
            {
                var rcptSrcNo = await _db.Documents.AsNoTracking()
                    .Where(d => d.Id == source.RelatedDocumentId.Value && d.CompanyId == companyId)
                    .Select(d => d.DocumentNumber)
                    .FirstOrDefaultAsync();
                throw new InvalidOperationException(
                    $"{source.DocumentNumber} เป็นใบเสร็จหลักฐานรับเงิน (ไม่ใช่ใบกำกับภาษี — VAT อยู่ที่เอกสารต้นทาง) "
                    + $"— ใบลดหนี้/ใบเพิ่มหนี้ตาม §86/9-10 ต้องอ้างใบกำกับ/เอกสารตั้งหนี้ตัวจริง"
                    + (rcptSrcNo != null ? $" ({rcptSrcNo})" : "") + " แทน");
            }
        }

        // PV → CN/DN เปิดเฉพาะ PV standalone (จ่ายทันที = ตั้งหนี้+จ่ายในใบเดียว).
        // PV แบบ settlement (อ้าง PI/Expense/CIL) ไม่ใช่เอกสารตั้งหนี้ — ใบลดหนี้
        // ของผู้ขายต้องอ้าง "ใบตั้งหนี้/ใบกำกับ" (§86/10) ไม่ใช่เอกสารจ่ายเงินของเรา
        if (source.DocumentType == DocumentType.PaymentVoucher
            && (targetType == DocumentType.CreditNote || targetType == DocumentType.DebitNote)
            && source.RelatedDocumentId.HasValue)
        {
            var pvSrc = await _db.Documents.AsNoTracking()
                .Where(d => d.Id == source.RelatedDocumentId.Value && d.CompanyId == companyId)
                .Select(d => new { d.DocumentNumber, d.DocumentType })
                .FirstOrDefaultAsync();
            if (pvSrc != null && pvSrc.DocumentType is DocumentType.PurchaseInvoice
                or DocumentType.Expense or DocumentType.CertificateInLieu)
                throw new InvalidOperationException(
                    $"ใบสำคัญจ่ายนี้เป็นการจ่ายชำระ {pvSrc.DocumentNumber} — ใบลดหนี้/ใบเพิ่มหนี้"
                    + $"จากผู้ขายต้องออกโดยอ้าง {pvSrc.DocumentNumber} (เอกสารตั้งหนี้) โดยตรง"
                    + " ไม่ใช่ใบสำคัญจ่าย (§86/10 ใบลดหนี้อ้างใบกำกับ/ใบตั้งหนี้เดิม)");
        }

        // Cycle detection — fetch entire ancestry chain in a single recursive CTE
        // instead of N round-trips (one per ancestor level).
        if (source.RelatedDocumentId.HasValue)
        {
            var startId = source.RelatedDocumentId.Value;
            var ancestorMatch = await _db.Database
                .SqlQuery<AncestorRow>($@"
                    WITH RECURSIVE ancestry AS (
                        SELECT ""Id"", ""DocumentNumber"", ""DocumentType"", ""RelatedDocumentId"", 1 AS depth
                        FROM ""Documents""
                        WHERE ""Id"" = {startId} AND ""CompanyId"" = {companyId} AND ""IsDeleted"" = false
                        UNION ALL
                        SELECT d.""Id"", d.""DocumentNumber"", d.""DocumentType"", d.""RelatedDocumentId"", a.depth + 1
                        FROM ""Documents"" d
                        INNER JOIN ancestry a ON d.""Id"" = a.""RelatedDocumentId""
                        WHERE d.""CompanyId"" = {companyId} AND d.""IsDeleted"" = false AND a.depth < 20
                    )
                    SELECT ""Id"", ""DocumentNumber"", ""DocumentType"" FROM ancestry
                    WHERE ""DocumentType"" = {(int)targetType} LIMIT 1")
                .FirstOrDefaultAsync();

            if (ancestorMatch != null)
                throw new InvalidOperationException(
                    $"ตรวจพบวงกลมการแปลง: เอกสาร {ancestorMatch.DocumentNumber} ({(DocumentType)ancestorMatch.DocumentType}) เป็นบรรพบุรุษของเอกสารต้นทางอยู่แล้ว");
        }

        // กันแปลงซ้ำเป็นเอกสารรับรู้รายได้ (Invoice/TaxInvoice) — 1 ต้นทางออกใบ
        // รับรู้รายได้ได้ใบเดียว (เดิมไม่กัน → Invoice→TaxInvoice 2 ครั้ง = รายได้
        // + ภาษีขายซ้ำ 2 เท่า, ภพ.30 นับซ้ำ). ยกเว้นใบที่ถูกยกเลิก/ปฏิเสธไปแล้ว.
        // (audit F3) แหล่ง QT/BN: Receipt/RV ลูกก็ "รับรู้รายได้เอง" (standalone
        // cash-sale JE — ไม่ใช่ settlement เพราะ QT/BN ไม่ตั้งหนี้) → ต้องนับเป็น
        // revenue-child เดียวกับ Invoice/TaxInvoice. เดิม guard เช็คเฉพาะ
        // Invoice/TaxInvoice → QT→Invoice แล้ว QT→Receipt (หรือสลับลำดับ) ผ่านได้
        // ทั้งคู่ = รายได้ + ภาษีขาย 2 เท่าจากการขายครั้งเดียว
        var sourceIsPreRevenue = source.DocumentType is DocumentType.Quotation or DocumentType.BillingNote;
        var targetPostsRevenue = targetType is DocumentType.Invoice or DocumentType.TaxInvoice
            || (sourceIsPreRevenue && targetType is DocumentType.Receipt or DocumentType.ReceiptVoucher);
        if (targetPostsRevenue)
        {
            var revenueChildTypes = sourceIsPreRevenue
                ? new[] { DocumentType.Invoice, DocumentType.TaxInvoice, DocumentType.Receipt, DocumentType.ReceiptVoucher }
                : new[] { DocumentType.Invoice, DocumentType.TaxInvoice };
            var existingRevenueChild = await _db.Documents.AsNoTracking()
                .Where(d => d.CompanyId == companyId && d.RelatedDocumentId == source.Id
                    && !d.IsDeleted
                    && revenueChildTypes.Contains(d.DocumentType)
                    && d.Status != DocumentStatus.Voided && d.Status != DocumentStatus.Rejected)
                .Select(d => new { d.DocumentNumber, d.DocumentType })
                .FirstOrDefaultAsync();
            if (existingRevenueChild != null)
                throw new InvalidOperationException(
                    $"เอกสารต้นทาง {source.DocumentNumber} แปลงเป็น {existingRevenueChild.DocumentType} " +
                    $"({existingRevenueChild.DocumentNumber}) ไปแล้ว — แปลงซ้ำจะรับรู้รายได้/ภาษีขายซ้ำ. " +
                    "ถ้าต้องการออกใหม่ ให้ยกเลิกใบเดิมก่อน");
        }

        // For derivative types that adjust source's balance, source must be approved
        // and have outstanding balance.
        var derivativeTypes = new[] {
            DocumentType.Receipt, DocumentType.ReceiptVoucher,
            DocumentType.CreditNote, DocumentType.PaymentVoucher
        };
        if (derivativeTypes.Contains(targetType))
        {
            if (source.Status == DocumentStatus.Draft)
                throw new InvalidOperationException(
                    $"เอกสารต้นทาง {source.DocumentNumber} ยังเป็นฉบับร่าง — กรุณาอนุมัติก่อนแปลง");
            if (source.BalanceDue <= 0.01m && targetType != DocumentType.CreditNote
                && targetType != DocumentType.DebitNote)
                throw new InvalidOperationException(
                    $"เอกสาร {source.DocumentNumber} ไม่มียอดคงค้าง — ไม่สามารถแปลงเป็น {targetType}");
        }

        // เอกสาร settle จาก convert = "เต็มใบ" เสมอ (copy ทุกบรรทัด) — ต้นทางที่
        // รับ/จ่าย "บางส่วน" ไปแล้ว แปลงต่อไม่ได้ (ยอดใบ settle จะเกินคงค้าง →
        // เดิมปล่อยแปลงแล้วไป throw ตอนอนุมัติ = ผู้ใช้งงว่าผิดตรงไหน). บอกทาง
        // ที่ถูกตั้งแต่ตอนกดแปลง: งวดบางส่วน/งวดที่เหลือใช้ "บันทึกชำระเงิน"
        // (partial ได้หลายงวด + หักยอด/แสดงคงค้าง + ออกใบเสร็จหลักฐานต่องวด)
        var settlementTargets = new[] { DocumentType.Receipt, DocumentType.ReceiptVoucher,
            DocumentType.PaymentVoucher, DocumentType.CertificateInLieu };
        if (settlementTargets.Contains(targetType) && source.PaidAmount > 0.01m)
            throw new InvalidOperationException(
                $"เอกสาร {source.DocumentNumber} รับ/จ่ายชำระบางส่วนแล้ว ({source.PaidAmount:N2} จาก {source.TotalAmount:N2} บาท) — " +
                "การแปลงจะออกเอกสารยอดเต็มใบซึ่งเกินยอดคงค้าง. สำหรับงวดที่เหลือให้ใช้ปุ่ม '💰 บันทึกชำระเงิน' แทน " +
                "(รองรับจ่ายบางส่วนหลายงวดจนครบ + ออกใบเสร็จหลักฐานให้ทุกงวดอัตโนมัติ)");
    }

    /// <summary>Create the child document from a chosen set of (source line,
    /// quantity) pairs, link it back to the source, stamp SourceLineId on
    /// every new line, and cascade metadata + attachments.</summary>
    private async Task<DocumentResponse> ConvertCoreAsync(
        Document source, DocumentType targetType,
        List<(DocumentLine Line, decimal Qty)> spec, string createdBy,
        DateTime? documentDate = null, DateTime? dueDate = null,
        bool isFullTaxInvoiceReplacement = false)
    {
        var companyId = source.CompanyId;

        // PO ที่รับของผ่านใบรับสินค้า (GRN) แล้ว ต้องออกใบแจ้งหนี้ซื้อ **จาก GRN** — แปลง
        // PO→PI ตรงจะได้ PI ที่ RelatedDocumentId เป็น PO ⇒ GetReceivedViaGrnAccrualAccountAsync
        // คืน null ⇒ สต๊อกเข้า **รอบที่สอง** + Dr 11500 ซ้ำ + 21240 (GR-NI) ไม่มีใครล้าง
        // ตลอดกาล ทั้งที่แกน Delivery/Billing แยกกันจึงไม่มีด่านไหนจับ (ERP_REVIEW E-05)
        if (source.DocumentType == DocumentType.PurchaseOrder && targetType == DocumentType.PurchaseInvoice)
        {
            var grnNumber = await _db.Documents.AsNoTracking()
                .Where(d => d.CompanyId == companyId && d.RelatedDocumentId == source.Id && !d.IsDeleted
                    && d.DocumentType == DocumentType.GoodsReceiptNote
                    && d.Status != DocumentStatus.Voided && d.Status != DocumentStatus.Rejected)
                .OrderBy(d => d.CreatedAt)
                .Select(d => d.DocumentNumber)
                .FirstOrDefaultAsync();
            if (grnNumber != null)
                throw new InvalidOperationException(
                    $"ใบสั่งซื้อนี้รับของผ่านใบรับสินค้า {grnNumber} แล้ว — ให้เปิดใบรับสินค้านั้นแล้วแปลงเป็นใบแจ้งหนี้ซื้อ " +
                    "(3-way match) แทนการแปลงจากใบสั่งซื้อตรง ไม่งั้นสต๊อกและบัญชีสินค้าคงเหลือจะลงซ้ำสองรอบ");
        }

        // ยอดภาษีของใบปลายทางต้อง **ตรงกับใบต้นทางเป๊ะทุกสตางค์** — ลูกค้าถือ
        // ใบแจ้งหนี้อยู่แล้ว ใบกำกับที่แปลงมาแล้วยอดขยับ 0.01 = เอกสารสองใบของ
        // รายการเดียวกันไม่ตรงกัน (ตรวจสอบภาษี/กระทบยอดกับลูกค้าพัง)
        // ที่มา: ใบที่มาจาก OCR/integration เก็บ VAT รายบรรทัดที่ปัดมาแล้ว
        // (Σ = 44,942.29) แต่การแปลงคิดใหม่จากอัตรา + กระทบยอดรายกลุ่ม
        // (round(642,032.64 × 7%) = 44,942.28) ⇒ ต่างกัน 1 สตางค์
        // วิธีแก้: ยก VAT ที่บันทึกไว้จริงไปเป็น VatAmountOverride เมื่อยกทั้ง
        // บรรทัด (ComputeLineAmounts honor ตรง ๆ และ ReconcileTaxRounding ข้าม)
        // ยกเว้นโหมด "ราคารวม VAT + ส่วนลดท้ายบิล" ที่การ back-out ทำให้ net
        // ของใบลูกไม่ตรงกับต้นทางอยู่ดี — เคสนั้นคงพฤติกรรมเดิม (คิดใหม่)
        var carryStoredVat = !(source.PricesIncludeVat
            && (source.BillDiscountPercent > 0 || source.BillDiscountAmount > 0));

        // SourceLineId travels through the DTO so CreateDocumentAsync stamps
        // it inside its own transaction — every new line is linked 1:1 to the
        // source line it was carried forward from.
        var lines = spec.Select(s => new DocumentLineRequest(
            s.Line.Description, s.Qty, s.Line.Unit, s.Line.UnitPrice,
            s.Line.DiscountPercent, s.Line.VatRate, s.Line.WithholdingTaxRate, s.Line.AccountId,
            ProjectId: s.Line.ProjectId,
            ProductCode: s.Line.ProductCode,
            SourceLineId: s.Line.Id,
            // ส่วนลดบาทรายบรรทัด + ธงภาษีซื้อต้องห้าม ต้องตามไปด้วย (audit F1/D1) —
            // เดิมหาย → ใบปลายทางแพงกว่าต้นทาง + VAT ต้องห้ามกลับเคลมได้
            IsVatClaimable: s.Line.IsVatClaimable,
            DiscountAmount: s.Line.DiscountAmount > 0
                ? (s.Qty >= s.Line.Quantity ? s.Line.DiscountAmount
                    // partial convert: ส่วนลดบาทเฉลี่ยตามสัดส่วน qty ที่ยกไป
                    : Math.Round(s.Line.DiscountAmount * (s.Line.Quantity > 0 ? s.Qty / s.Line.Quantity : 1m), 2))
                : null,
            // ยกทั้งบรรทัด → ใช้ VAT ที่บันทึกไว้จริง (ตรงเป๊ะ) · ยกบางส่วน →
            // ปล่อยคิดใหม่ + กระทบยอดรายกลุ่มตามปกติ (การเฉลี่ย VAT ตามสัดส่วน
            // จะสร้างเศษของตัวเองและทำให้ผลรวมของใบย่อยหลายใบไม่ตรงต้นทางอยู่ดี)
            VatAmountOverride: carryStoredVat && s.Qty >= s.Line.Quantity && s.Line.VatRate > 0
                ? s.Line.VatAmount
                : null)).ToList();

        var newDoc = await CreateDocumentAsync(companyId, new CreateDocumentRequest(
            targetType, documentDate ?? DateTime.UtcNow, dueDate ?? source.DueDate, source.ContactId,
            source.DocumentNumber, source.Notes, lines,
            ProjectId: source.ProjectId,
            BankAccountId: source.BankAccountId,
            PaymentAccountId: source.PaymentAccountId,
            ExpenseCategoryId: source.ExpenseCategoryId,
            // คงสกุลเงิน + เรตของเอกสารต้นทาง (เดิมไม่ส่ง → default THB ทำให้เอกสาร
            // ต่างสกุลเงินแปลงแล้วกลายเป็นบาท)
            Currency: source.Currency,
            ExchangeRate: source.ExchangeRate,
            // pricing semantics ของต้นทางต้องตามไปครบ (audit F1): เดิมหาย →
            // ใบปลายทางคิด VAT บนฐานไม่หักส่วนลดท้ายบิล / ราคารวม VAT ถูกบวก
            // VAT ซ้ำ (+7%) → ยอดสูงกว่าที่ตกลงกับลูกค้า + ภาษีขายเกินจริง
            PricesIncludeVat: source.PricesIncludeVat,
            BrandId: source.BrandId,   // เอกสารลูกใช้แบรนด์เดียวกับต้นทางเสมอ
            // และออกจากสถานประกอบการเดียวกัน — ใบแจ้งหนี้ออกจากสาขาเชียงใหม่
            // แล้วใบกำกับกลับเป็นสำนักงานใหญ่ = รายงานภาษีขายเข้าผิดสาขา §87
            BranchId: source.BranchId,
            DocumentTemplateId: source.DocumentTemplateId,   // และรูปแบบเดียวกัน
            BillDiscountPercent: source.BillDiscountPercent > 0 ? source.BillDiscountPercent : null,
            // โหมดยอดบาท + partial convert: เฉลี่ยส่วนลดตามสัดส่วน "ฐาน ex-VAT"
            // ที่ยกไป — line.Amount เป็น ex-VAT หลังส่วนลด (สัดส่วนตรงกับฐานก่อน
            // หักท้ายบิลเพราะ allocation เป็น pro-rata เชิงเส้น). เดิมตัวเศษใช้
            // qty×UnitPrice (gross รวม VAT เมื่อ PricesIncludeVat + ไม่หักส่วนลด
            // บาท) หารด้วยฐาน ex-VAT → ยกส่วนลดเกินสัดส่วน ~7% ทุกครั้ง →
            // Σส่วนลดใบลูก > ต้นทาง + ฐานภาษีใบลูกต่ำเกินจริง
            BillDiscountAmount: source.BillDiscountPercent <= 0 && source.BillDiscountAmount > 0
                ? Math.Round(source.BillDiscountAmount * Math.Min(1m,
                    source.SubTotal > 0
                        ? spec.Sum(s => s.Line.Amount
                            * (s.Line.Quantity > 0 ? s.Qty / s.Line.Quantity : 1m))
                          / source.SubTotal
                        : 1m), 2)
                : null,
            // ลิงก์ต้นทางต้องเข้าไปตั้งแต่ create — PV ที่ settle ใบแจ้งหนี้ซื้อ
            // ต้องไม่โดน auto-approve แบบ standalone cash ก่อนมีลิงก์
            RelatedDocumentId: source.Id), createdBy,
            isFullTaxInvoiceReplacement: isFullTaxInvoiceReplacement);

        // Link new document to source + propagate appendix/contract metadata
        var created = await _db.Documents.FindAsync(newDoc.Id);
        if (created != null)
        {
            created.RelatedDocumentId = source.Id;
            // ภาษาที่ตรึงกับใบต้นทางต้องตามไปทั้งสาย (QT en → INV → REC) —
            // ลูกค้าต่างชาติที่ได้ใบเสนอราคาอังกฤษ ต้องได้ใบแจ้งหนี้/ใบเสร็จ
            // อังกฤษด้วยโดยไม่ต้องตั้งซ้ำทุกใบ (null = ตามค่าบริษัท ก็คงเป็น null)
            created.DocumentLanguage = source.DocumentLanguage;
            created.CustomAppendix = source.CustomAppendix;
            created.CustomFooterNotes = source.CustomFooterNotes;
            created.CustomTermsAndConditions = source.CustomTermsAndConditions;
            created.RevenueContractId = source.RevenueContractId;
            created.PerformanceObligationId = source.PerformanceObligationId;
            created.CertificateReason = source.CertificateReason;
            created.CertifierName = source.CertifierName;
            created.CertifierPosition = source.CertifierPosition;
            created.WitnessName = source.WitnessName;
            created.WitnessPosition = source.WitnessPosition;
            created.PaymentDate = source.PaymentDate;
            await _db.SaveChangesAsync();
        }

        // Cascade file attachments — copy reference rows so child doc shares
        // the same physical files.
        await CascadeAttachmentsAsync(companyId, source.Id, newDoc.Id, createdBy);

        return await GetDocumentAsync(companyId, newDoc.Id);
    }

    public async Task<DocumentResponse> ConvertDocumentAsync(Guid companyId, Guid documentId, DocumentType targetType, string createdBy)
    {
        var source = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        await ValidateConversionAsync(source, targetType, companyId);

        var axis = GetFulfillmentAxis(targetType);
        var orderedLines = source.Lines.OrderBy(l => l.LineOrder).ToList();
        List<(DocumentLine Line, decimal Qty)> spec;

        // Invoice → TaxInvoice = "อัปเกรดชนิดเอกสารรับรู้รายได้ใบเดียวกัน" (ทั้งฉบับ)
        // ไม่ใช่ "วางบิลบางส่วน" → ต้องคัดลอกทุกบรรทัดเต็ม. เดิมวิ่งผ่าน billing-axis
        // gate (Invoice กับ TaxInvoice อยู่ axis เดียวกัน) → ถ้าบรรทัดใดถูกมองว่า
        // "บิลแล้ว" (consumption ≥ qty จาก child เก่า/งวดก่อน) จะถูกตัดทิ้งเงียบ →
        // ใบกำกับ/ใบเสร็จยอดขาดไม่ตรงใบแจ้งหนี้ (bug ที่พบ). การแปลงซ้ำถูกกันด้วย
        // ValidateConversionAsync (double revenue) อยู่แล้ว จึงคัดลอกเต็มปลอดภัย.
        var wholeDocRevenueUpgrade = source.DocumentType == DocumentType.Invoice
            && targetType == DocumentType.TaxInvoice;

        if (axis == FulfillmentAxis.None || wholeDocRevenueUpgrade)
        {
            // Settlement / adjustment target หรือ upgrade ทั้งฉบับ — copy every line verbatim.
            spec = orderedLines.Select(l => (l, l.Quantity)).ToList();
        }
        else
        {
            // Quantity-tracked target — carry forward only what is still
            // un-converted on this axis, so a second convert never duplicates.
            var consumption = await ComputeConsumptionAsync(companyId, orderedLines.Select(l => l.Id).ToList());
            spec = new List<(DocumentLine, decimal)>();
            foreach (var l in orderedLines)
            {
                var used = axis == FulfillmentAxis.Delivery ? consumption[l.Id].Delivery : consumption[l.Id].Billing;
                var remaining = l.Quantity - used;
                if (remaining > QtyEpsilon)
                    spec.Add((l, remaining));
            }
            if (spec.Count == 0)
                throw new InvalidOperationException(
                    $"เอกสาร {source.DocumentNumber} ถูกแปลงเพื่อ{AxisLabel(axis)}ครบทุกรายการแล้ว " +
                    $"— ไม่มีจำนวนคงเหลือให้แปลง");
        }

        return await ConvertCoreAsync(source, targetType, spec, createdBy);
    }

    // ══════════════════════════════════════════════════════════════════
    //  ออก "ใบกำกับภาษีเต็มรูป" แทนใบเสร็จ/ใบกำกับอย่างย่อ (§86/6 → §86/4)
    //
    //  ที่มา (ผู้ใช้ถาม 2026-09-03): ลูกค้ารับใบเสร็จ/ใบกำกับอย่างย่อไปแล้ว
    //  ภายหลังขอเต็มรูปเพื่อเคลมภาษีซื้อ (อย่างย่อเคลมไม่ได้ §82/5(2)) —
    //  เดิม ValidConversions[Receipt] มีแค่ CN/DN จึงทำไม่ได้เลย
    //
    //  ⚠️ ทำไมไม่ใส่ TaxInvoice ลง ValidConversions เฉย ๆ: ใบเสร็จที่มี VAT
    //  **นับเป็นภาษีขายเข้า ภ.พ.30 ไปแล้ว** (tax point = วันรับเงิน §78/1 —
    //  TaxService branch "Receipt/ReceiptVoucher standalone") ⇒ การแปลงปกติ
    //  จะได้ใบที่สองที่ AutoPost รายได้/ภาษีขายซ้ำ **และ**ถูกนับใน ภ.พ.30
    //  อีกรอบ. การขายครั้งเดียวมีใบกำกับได้ใบเดียว → ออกแบบเป็น "ใบแทน":
    //    • ใบใหม่ใช้ **วันที่ของใบเดิม** (tax point เกิดไปแล้ว ย้ายงวดไม่ได้)
    //    • ผูกสองทาง ReplacesDocumentId / ReplacedByDocumentId
    //    • อนุมัติแล้ว **ไม่ post JE / ไม่ขยับสต๊อก / ไม่แตะยอดใบต้นทาง**
    //      (เงิน+รายได้+ภาษีขายลงไปครบตั้งแต่ใบเดิม — เปลี่ยนแค่ "กระดาษ")
    //    • รายงานภาษีขายนับใบแทน และข้ามใบที่ถูกแทน ⇒ ยอด VAT รวมไม่ขยับ
    // ══════════════════════════════════════════════════════════════════

    /// <summary>ตรวจสิทธิ์ออกใบแทน — ใช้ร่วมกันทั้งตอนกดจริงและตอนตอบ
    /// <c>DocumentResponse</c> ให้ UI ตัดสินว่าจะโชว์ปุ่มไหม (ห้ามให้หน้าเว็บ
    /// เขียนกติกาสำเนาที่สอง — defect class "สำเนามือฝั่ง JS")</summary>
    private async Task<Accounting.Helpers.FullTaxInvoiceEligibility> EvaluateFullTaxInvoiceReplacementAsync(
        Guid companyId, Document src)
    {
        await _db.HydrateContactAsync(companyId, src);

        // "เป็นใบกำกับเต็มรูปอยู่แล้วไหม" ตัดสินจาก **หัวที่จะพิมพ์จริง** ผ่าน
        // resolver ตัวเดียวกับกระดาษ ไม่ใช่ชนิดเอกสาร — ใบเสร็จที่ผู้ซื้อครบ
        // §86/4 พิมพ์ "ใบกำกับภาษี/ใบเสร็จรับเงิน" อยู่แล้ว ไม่ต้องออกใบแทน
        var missingBuyer = Tax.TaxInvoiceCompletenessChecker.MissingBuyerFields(src.Contact);
        var isFullAlready = src.DocumentType == DocumentType.TaxInvoice
            || (missingBuyer.Count == 0 && !src.BuyerDeclinedTaxInvoice
                && src.Contact is { IsWalkInCustomer: false } && src.VatAmount > 0.005m);

        return Accounting.Helpers.FullTaxInvoiceReplacement.Check(
            sourceIsIssued: src.Status is not (DocumentStatus.Draft or DocumentStatus.Voided
                or DocumentStatus.Rejected or DocumentStatus.WaitingApproval),
            sourceIsFullTaxInvoice: isFullAlready,
            sourceVatAmount: src.VatAmount,
            alreadyReplaced: src.ReplacedByDocumentId.HasValue,
            companyIsVatRegistered: await IsCompanyVatRegisteredAsync(companyId),
            missingBuyerFields: missingBuyer);
    }

    public async Task<DocumentResponse> IssueFullTaxInvoiceForReceiptAsync(
        Guid companyId, Guid receiptId, string? reason, string actor)
    {
        var src = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == receiptId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        if (src.DocumentType is not (DocumentType.Receipt or DocumentType.ReceiptVoucher))
            throw new Accounting.Helpers.BusinessRuleException(
                "ออกใบกำกับภาษีเต็มรูปแทนได้เฉพาะใบเสร็จรับเงิน/ใบกำกับภาษีอย่างย่อ",
                "RD-86/4-REPLACE-SOURCE-TYPE");

        var eligibility = await EvaluateFullTaxInvoiceReplacementAsync(companyId, src);
        if (!eligibility.Allowed)
            throw new Accounting.Helpers.BusinessRuleException(
                eligibility.Message ?? "ออกใบกำกับภาษีเต็มรูปแทนใบนี้ไม่ได้",
                $"RD-86/4-REPLACE-{eligibility.Reason}");

        // คัดลอกทุกบรรทัดเต็มจำนวน — ใบแทนต้องเป็น "ใบเดียวกัน" ทุกสตางค์
        // (ConvertCoreAsync ยก VatAmountOverride ให้เมื่อยกทั้งบรรทัด ⇒ VAT
        // ตรงเป๊ะ ไม่คลาดกัน 0.01 จากการคิดใหม่)
        var spec = src.Lines.OrderBy(l => l.LineOrder).Select(l => (l, l.Quantity)).ToList();
        var created = await ConvertCoreAsync(src, DocumentType.TaxInvoice, spec, actor,
            documentDate: src.DocumentDate, dueDate: src.DocumentDate,
            isFullTaxInvoiceReplacement: true);

        var replacement = await _db.Documents.FindAsync(created.Id);
        if (replacement != null)
        {
            replacement.ReplacesDocumentId = src.Id;
            replacement.ReplacementReason = string.IsNullOrWhiteSpace(reason) ? null : reason!.Trim();
            // หมายเหตุอ้างใบเดิม **ต้องพิมพ์ลงกระดาษ** — ผู้ซื้อและผู้สอบบัญชี
            // ต้องเห็นว่าใบนี้แทนใบไหน (จึงลง Notes ไม่ใช่ InternalNotes)
            replacement.Notes = string.Join(" · ", new[]
            {
                src.Notes?.Trim(),
                Accounting.Helpers.FullTaxInvoiceReplacement.ReplacementNote(src.DocumentNumber, src.DocumentDate),
            }.Where(s => !string.IsNullOrWhiteSpace(s)));
            // เงินรับครบตั้งแต่ใบเดิม — ใบแทนต้องไม่ไปโผล่ในรายการค้างรับ
            replacement.PaymentType = src.PaymentType;
            await _db.SaveChangesAsync();
        }

        // อนุมัติทันที: ใบแทนไม่มีอะไรให้ตรวจเพิ่ม (ยอด/วันที่/ผู้ซื้อ ยกมาจาก
        // ใบที่อนุมัติแล้วทั้งหมด) และถ้าค้าง Draft ไว้ ใบเดิมจะยังอยู่ในรายงาน
        // (ตราประทับ ReplacedByDocumentId ลงตอน approve) = สภาพครึ่ง ๆ ที่ผู้ใช้
        // ไม่มีทางรู้. ผู้เรียกต้องเช็คสิทธิ์อนุมัติมาก่อน (ดู controller)
        try
        {
            await ApproveDocumentAsync(companyId, created.Id, actor, acknowledgeWarnings: true);
        }
        catch (Exception ex) when (ex is not KeyNotFoundException)
        {
            // อนุมัติไม่ผ่าน (งวดบัญชีปิด · กฎอนุมัติของบริษัท · ฯลฯ) — ใบแทนยัง
            // ค้างเป็น **ร่าง** และใบเดิมยัง **ไม่ถูกประทับ** (ตราประทับลงตอน
            // approve เท่านั้น) ⇒ รายงานภาษีขายยังถูกต้องทุกประการ. บอกผู้ใช้ตรง ๆ
            // ว่าอยู่ตรงไหนและต้องทำอะไรต่อ — ห้ามปล่อยให้เจอ error ดิบแล้วเดาเอง
            // ว่าใบที่โผล่มาในรายการร่างคืออะไร
            throw new Accounting.Helpers.BusinessRuleException(
                $"สร้างใบกำกับภาษีเต็มรูป (ร่าง) แล้ว แต่อนุมัติอัตโนมัติไม่ผ่าน: {ex.Message} "
                + "— ใบเดิมยังอยู่ในรายงานภาษีขายตามปกติ · แก้ตามข้อความข้างต้นแล้ว"
                + "กด \"อนุมัติ\" ที่ใบร่างนั้นเพื่อให้การแทนที่มีผล",
                "RD-86/4-REPLACE-APPROVE-FAILED");
        }
        return await GetDocumentAsync(companyId, created.Id);
    }

    public async Task<DocumentResponse> ConvertDocumentPartialAsync(
        Guid companyId, Guid documentId, DocumentType targetType,
        PartialConvertRequest request, string createdBy)
    {
        var source = await _db.Documents
            .Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        await ValidateConversionAsync(source, targetType, companyId);

        var axis = GetFulfillmentAxis(targetType);
        if (axis == FulfillmentAxis.None)
            throw new InvalidOperationException(
                $"การแปลงเป็น {targetType} ไม่รองรับการเลือกบางรายการ — กรุณาใช้การแปลงทั้งฉบับ");

        if (request.Lines == null || request.Lines.Count == 0)
            throw new InvalidOperationException("กรุณาเลือกรายการที่ต้องการแปลงอย่างน้อย 1 รายการ");

        var consumption = await ComputeConsumptionAsync(
            companyId, source.Lines.Select(l => l.Id).ToList());
        var byId = source.Lines.ToDictionary(l => l.Id);

        // Preserve source line order in the new document.
        var spec = new List<(DocumentLine Line, decimal Qty)>();
        foreach (var req in request.Lines.Where(r => r.Quantity > QtyEpsilon)
                     .OrderBy(r => byId.TryGetValue(r.SourceLineId, out var sl) ? sl.LineOrder : int.MaxValue))
        {
            if (!byId.TryGetValue(req.SourceLineId, out var srcLine))
                throw new InvalidOperationException("ไม่พบรายการต้นทางที่เลือก ในเอกสารนี้");
            var used = axis == FulfillmentAxis.Delivery
                ? consumption[srcLine.Id].Delivery : consumption[srcLine.Id].Billing;
            var remaining = srcLine.Quantity - used;
            if (req.Quantity > remaining + QtyEpsilon)
                throw new InvalidOperationException(
                    $"รายการ '{srcLine.Description}' ขอแปลง {req.Quantity:0.##} " +
                    $"แต่คงเหลือให้{AxisLabel(axis)}เพียง {remaining:0.##} {srcLine.Unit}");
            spec.Add((srcLine, req.Quantity));
        }
        if (spec.Count == 0)
            throw new InvalidOperationException("ไม่มีรายการที่จะแปลง — จำนวนต้องมากกว่า 0");

        return await ConvertCoreAsync(source, targetType, spec, createdBy,
            request.DocumentDate, request.DueDate);
    }

    public async Task<DocumentFulfillmentResponse> GetDocumentFulfillmentAsync(Guid companyId, Guid documentId)
    {
        var source = await _db.Documents
            .Include(d => d.Lines)
            .AsNoTracking()
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        var orderedLines = source.Lines.OrderBy(l => l.LineOrder).ToList();
        var consumption = await ComputeConsumptionAsync(companyId, orderedLines.Select(l => l.Id).ToList());

        // Which axes make sense for this source — based on what it can convert into.
        var targets = GetValidConversionTargets(source.DocumentType);
        var supportsDelivery = targets.Any(t => GetFulfillmentAxis(t) == FulfillmentAxis.Delivery);
        var supportsBilling = targets.Any(t => GetFulfillmentAxis(t) == FulfillmentAxis.Billing);

        var lines = orderedLines.Select(l =>
        {
            var c = consumption[l.Id];
            return new DocumentLineFulfillmentResponse(
                l.Id, l.LineOrder, l.Description, l.Unit,
                OrderedQuantity: l.Quantity,
                DeliveredQuantity: c.Delivery,
                DeliveryRemaining: Math.Max(0m, l.Quantity - c.Delivery),
                BilledQuantity: c.Billing,
                BillingRemaining: Math.Max(0m, l.Quantity - c.Billing),
                UnitPrice: l.UnitPrice,
                DiscountPercent: l.DiscountPercent,
                VatRate: l.VatRate,
                WithholdingTaxRate: l.WithholdingTaxRate,
                AccountId: l.AccountId,
                ProjectId: l.ProjectId,
                ProductCode: l.ProductCode);
        }).ToList();

        return new DocumentFulfillmentResponse(
            source.Id, source.DocumentNumber, source.DocumentType,
            supportsDelivery, supportsBilling, lines);
    }

    private async Task CascadeAttachmentsAsync(Guid companyId, Guid sourceDocId, Guid targetDocId, string createdBy)
    {
        var sourceAttachments = await _db.FileAttachments
            .AsNoTracking()
            .Where(f => f.CompanyId == companyId && f.EntityType == "Document" && f.EntityId == sourceDocId)
            .ToListAsync();

        if (sourceAttachments.Count == 0) return;

        // Plan the copy: compute new paths and create DB rows pointing at them FIRST.
        // The physical file copy then runs ASYNCHRONOUSLY so we don't block the request
        // while a 50MB file is being copied. If copy fails, the row's StoragePath still
        // points at the parent file — degrades gracefully but never loses the reference.
        var copyPlan = new List<(string Source, string Target)>(sourceAttachments.Count);

        foreach (var src in sourceAttachments)
        {
            var newStoragePath = src.StoragePath;
            if (!string.IsNullOrEmpty(src.StoragePath))
            {
                var dir = Path.GetDirectoryName(src.StoragePath) ?? "";
                var ext = Path.GetExtension(src.StoragePath);
                newStoragePath = Path.Combine(dir, $"{Guid.NewGuid()}{ext}");
                copyPlan.Add((src.StoragePath, newStoragePath));
            }

            _db.FileAttachments.Add(new FileAttachment
            {
                CompanyId = companyId,
                EntityType = "Document",
                EntityId = targetDocId,
                FileName = Path.GetFileName(newStoragePath),
                OriginalFileName = src.OriginalFileName,
                ContentType = src.ContentType,
                FileSize = src.FileSize,
                StoragePath = newStoragePath,
                UploadedByUserId = src.UploadedByUserId,
                CreatedBy = createdBy,
            });
        }

        await _db.SaveChangesAsync();

        // Fire-and-forget physical file copy — caller doesn't wait. If copy fails,
        // the new attachment row's StoragePath simply points at the parent file
        // (which still works as long as parent isn't purged).
        if (copyPlan.Count > 0)
        {
            _ = Task.Run(async () =>
            {
                foreach (var (source, target) in copyPlan)
                {
                    try
                    {
                        if (System.IO.File.Exists(source) && !System.IO.File.Exists(target))
                        {
                            await using var srcStream = System.IO.File.OpenRead(source);
                            await using var dstStream = System.IO.File.Create(target);
                            await srcStream.CopyToAsync(dstStream);
                        }
                    }
                    catch (Exception ex)
                    {
                        _logger.LogWarning(ex, "Cascade file copy failed: {Source} -> {Target}", source, target);
                    }
                }
            });
        }
    }

    public async Task<List<DocumentResponse>> BatchConvertDocumentsAsync(
        Guid companyId, List<Guid> documentIds, DocumentType targetType, string createdBy)
    {
        // Run conversions sequentially within a single DbContext — EF Core DbContext
        // is NOT thread-safe so we cannot parallelize at the per-document level here
        // without provisioning fresh contexts. Instead we batch-fetch sources first
        // (avoiding N round-trips just to load them) and then loop.
        //
        // For true parallelism, the controller should fan out to N HTTP requests
        // or we'd need IServiceScopeFactory to spawn fresh DbContexts per worker.
        // Going with the safer optimization here: pre-fetch + sequential conversion
        // still saves ~30-50% on a 100-doc batch via reduced DB chatter.

        var distinctIds = documentIds.Distinct().ToList();
        var results = new List<DocumentResponse>(distinctIds.Count);
        var errors = new List<string>();

        // Pre-fetch all sources once; ConvertDocumentAsync will re-load from tracker but
        // EF caches the entity, avoiding a second DB hit.
        await _db.Documents
            .Include(d => d.Lines)
            .Where(d => documentIds.Contains(d.Id) && d.CompanyId == companyId)
            .LoadAsync();

        foreach (var id in distinctIds)
        {
            try
            {
                var converted = await ConvertDocumentAsync(companyId, id, targetType, createdBy);
                results.Add(converted);
            }
            catch (Exception ex)
            {
                errors.Add($"{id}: {ex.Message}");
                _logger.LogWarning(ex, "Batch convert: failed to convert document {DocId}", id);
            }
        }

        if (results.Count == 0 && errors.Count > 0)
            throw new InvalidOperationException("ไม่สามารถแปลงเอกสารได้: " + string.Join("; ", errors));

        return results;
    }

    public async Task<DocumentResponse> CreateInvoiceFromObligationAsync(
        Guid companyId, Guid performanceObligationId, string createdBy)
    {
        // Lock obligation row + contract row to prevent two parallel invoice-creations
        // from both seeing IsSatisfied=false and creating duplicate invoices for the
        // same milestone.
        using var tx = await _db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);
        try
        {
            var obligation = await _db.Set<PerformanceObligation>()
                .Include(o => o.Contract)
                .FirstOrDefaultAsync(o => o.Id == performanceObligationId && o.CompanyId == companyId)
                ?? throw new KeyNotFoundException("ไม่พบ Performance Obligation");

            if (obligation.IsSatisfied)
                throw new InvalidOperationException("ภาระงานนี้รับรู้รายได้ครบแล้ว — ไม่สามารถออกใบแจ้งหนี้ซ้ำ");

            var unbilled = obligation.AllocatedPrice - obligation.RecognizedRevenue;
            if (unbilled <= 0.01m)
                throw new InvalidOperationException("ไม่มียอดคงเหลือสำหรับออกใบแจ้งหนี้");

            var contract = obligation.Contract
                ?? throw new InvalidOperationException("ไม่พบสัญญารายได้ของภาระงานนี้");

            var lineDescription = string.IsNullOrEmpty(obligation.Description)
                ? obligation.Name
                : $"{obligation.Name} — {obligation.Description}";

            var invoice = await CreateDocumentAsync(companyId, new CreateDocumentRequest(
                DocumentType.Invoice,
                DateTime.UtcNow,
                DueDate: DateTime.UtcNow.AddDays(30),
                ContactId: contract.ContactId,
                Reference: contract.ContractNumber,
                Notes: $"จากสัญญา {contract.ContractNumber}: {contract.Name}",
                Lines: new List<DocumentLineRequest>
                {
                    new(lineDescription, 1m, "งวด", unbilled, 0m, 7m, 0m, AccountId: null),
                },
                ProjectId: contract.ProjectId,
                RevenueContractId: contract.Id,
                PerformanceObligationId: obligation.Id), createdBy);

            // Update obligation state — invoice covers the unbilled portion
            obligation.RecognizedRevenue = obligation.AllocatedPrice;
            obligation.CompletionPercent = 100m;
            obligation.IsSatisfied = true;
            obligation.SatisfiedDate = DateTime.UtcNow;

            // Cascade-mark contract complete if all obligations are satisfied
            var allObligationsForContract = await _db.Set<PerformanceObligation>()
                .Where(o => o.RevenueContractId == contract.Id && o.Id != obligation.Id)
                .ToListAsync();
            if (allObligationsForContract.All(o => o.IsSatisfied))
            {
                contract.Status = "Completed";
            }

            await _db.SaveChangesAsync();
            await tx.CommitAsync();

            return invoice;
        }
        catch
        {
            await tx.RollbackAsync();
            throw;
        }
    }

    // ==================== Contacts ====================

    /// <summary>normalize เลขผู้เสียภาษีเหลือตัวเลขล้วน — จุด match ทุกที่ต้องใช้
    /// ตัวนี้ (เดิมเทียบ == ตรง ๆ → "0-2735-63000-92-0" ไม่เจอ "0273563000920"
    /// → OCR/API สร้างผู้ติดต่อซ้ำทุกครั้งที่สแกน).</summary>
    internal static string NormalizeTaxDigits(string? taxId)
        => new string((taxId ?? "").Where(char.IsDigit).ToArray());

    internal static string NormalizeBranchCode(string? branch)
    {
        var d = new string((branch ?? "").Where(char.IsDigit).ToArray());
        return d.Length == 0 ? "00000" : d.PadLeft(5, '0');
    }

    /// <summary>หา contact เดิมที่ "ซ้ำ" กับข้อมูลที่ส่งมา — คีย์หลัก = เลขภาษี 13
    /// หลัก (normalize) + สาขา (00000 = สำนักงานใหญ่; เลขภาษีเดียวกันคนละสาขา =
    /// คนละ record ถูกต้องตามกฎหมาย). ไม่มีเลขภาษี → ไม่ตัดสินว่าซ้ำ (ชื่อคนซ้ำ
    /// กันได้จริง — ให้เครื่องมือ merge จัดการ).</summary>
    public async Task<Contact?> FindDuplicateContactAsync(Guid companyId, string? taxId, string? branchCode)
    {
        var tax = NormalizeTaxDigits(taxId);
        if (tax.Length != 13) return null;
        var branch = NormalizeBranchCode(branchCode);
        // เทียบ normalize ใน memory (EF แปล digit-strip เป็น SQL ไม่ได้) — โหลด
        // เฉพาะ candidate ที่มี TaxId (โปรเจกต์จริงหลักร้อย/พันแถว รับได้)
        var candidates = await _db.Contacts.AsNoTracking()
            .Where(c => c.CompanyId == companyId && !c.IsDeleted
                && c.TaxId != null && c.TaxId != "")
            .Select(c => new { c.Id, c.TaxId, c.BranchCode })
            .ToListAsync();
        var hit = candidates.FirstOrDefault(c =>
            NormalizeTaxDigits(c.TaxId) == tax && NormalizeBranchCode(c.BranchCode) == branch);
        return hit == null ? null
            : await _db.Contacts.FirstOrDefaultAsync(c => c.Id == hit.Id);
    }

    /// <summary>หากลุ่มผู้ติดต่อซ้ำ — คีย์: เลขภาษี 13 หลัก (normalize) + สาขา.
    /// เสริมด้วยกลุ่มชื่อเหมือนกันเป๊ะที่ไม่มีเลขภาษี (แนะนำอย่างเดียว).</summary>
    public async Task<List<object>> GetDuplicateContactGroupsAsync(Guid companyId)
    {
        var all = await _db.Contacts.AsNoTracking()
            .Where(c => c.CompanyId == companyId && !c.IsDeleted)
            .Select(c => new { c.Id, c.Name, c.TaxId, c.BranchCode, c.Address, c.Email, c.Phone, c.CreatedAt, c.IsCustomer, c.IsSupplier })
            .ToListAsync();

        var groups = new List<object>();
        // กลุ่มตามเลขภาษี+สาขา
        foreach (var g in all
            .Where(c => NormalizeTaxDigits(c.TaxId).Length == 13)
            .GroupBy(c => NormalizeTaxDigits(c.TaxId) + "|" + NormalizeBranchCode(c.BranchCode))
            .Where(g => g.Count() > 1))
        {
            // แนะนำ "ตัวเก็บ": ข้อมูลครบสุด (ที่อยู่/อีเมล/โทร) แล้วเก่าสุด (เลขอ้าง
            // ในเอกสารเดิมมักชี้ตัวแรก)
            var ordered = g
                .OrderByDescending(c => (string.IsNullOrWhiteSpace(c.Address) ? 0 : 1)
                    + (string.IsNullOrWhiteSpace(c.Email) ? 0 : 1)
                    + (string.IsNullOrWhiteSpace(c.Phone) ? 0 : 1))
                .ThenBy(c => c.CreatedAt)
                .ToList();
            groups.Add(new
            {
                key = g.Key,
                matchBy = "taxId",
                taxId = NormalizeTaxDigits(ordered[0].TaxId),
                suggestedKeepId = ordered[0].Id,
                contacts = ordered.Select(c => new
                {
                    c.Id, c.Name, c.TaxId, c.BranchCode, c.Address, c.Email, c.Phone,
                    c.CreatedAt, c.IsCustomer, c.IsSupplier
                }).ToList()
            });
        }
        // กลุ่มชื่อซ้ำเป๊ะ (ไม่มีเลขภาษีทั้งคู่) — แสดงให้ตัดสินใจเอง
        foreach (var g in all
            .Where(c => NormalizeTaxDigits(c.TaxId).Length != 13)
            .GroupBy(c => (c.Name ?? "").Trim().ToLowerInvariant())
            .Where(g => g.Key.Length > 0 && g.Count() > 1))
        {
            var ordered = g.OrderBy(c => c.CreatedAt).ToList();
            groups.Add(new
            {
                key = "name|" + g.Key,
                matchBy = "name",
                taxId = (string?)null,
                suggestedKeepId = ordered[0].Id,
                contacts = ordered.Select(c => new
                {
                    c.Id, c.Name, c.TaxId, c.BranchCode, c.Address, c.Email, c.Phone,
                    c.CreatedAt, c.IsCustomer, c.IsSupplier
                }).ToList()
            });
        }
        return groups;
    }

    /// <summary>รวมผู้ติดต่อซ้ำ: repoint FK ทุกตาราง/คอลัมน์ที่ชี้ Contact (อ่านจาก
    /// information_schema — generic ไม่หลุดตารางใหม่ในอนาคต) → เติม field ที่ตัวเก็บ
    /// ยังว่างจากตัวที่ถูกรวม → soft-delete ตัวที่ถูกรวม + audit. เอกสาร/ประวัติ
    /// ทั้งหมดย้ายมาอยู่ใต้ contact เดียว.</summary>
    public async Task<int> MergeContactsAsync(Guid companyId, Guid keepId, List<Guid> mergeIds, string performedBy)
    {
        mergeIds = mergeIds.Where(id => id != keepId).Distinct().ToList();
        if (mergeIds.Count == 0) throw new InvalidOperationException("ไม่มีรายการให้รวม");

        var keep = await _db.Contacts.FirstOrDefaultAsync(c => c.Id == keepId && c.CompanyId == companyId && !c.IsDeleted)
            ?? throw new KeyNotFoundException("ไม่พบผู้ติดต่อตัวเก็บ (keep)");
        var losers = await _db.Contacts
            .Where(c => mergeIds.Contains(c.Id) && c.CompanyId == companyId && !c.IsDeleted)
            .ToListAsync();
        if (losers.Count != mergeIds.Count)
            throw new InvalidOperationException("บางรายการไม่พบ/ถูกลบแล้ว — โหลดรายการซ้ำใหม่อีกครั้ง");

        // 🛡️ ตาข่ายกันรวม "คนละราย" (ป้องกันเอกสารเก่าเปลี่ยนคู่ค้ายกชุด) —
        // ถ้าทั้งสองฝั่งมีเลขภาษี 13 หลักที่ valid และ "ต่างกัน" = คนละนิติบุคคล/
        // บุคคลแน่นอน ห้ามรวมไม่ว่า UI จะส่งอะไรมา (กลุ่ม dedup ผิด/กดพลาด/
        // เรียก API ตรง). เคสชื่อคล้ายกันแต่คนละเลขภาษีเป็นเรื่องปกติมาก
        var keepTaxDigits = NormalizeTaxDigits(keep.TaxId);
        foreach (var l in losers)
        {
            var loserTaxDigits = NormalizeTaxDigits(l.TaxId);
            if (keepTaxDigits.Length == 13 && loserTaxDigits.Length == 13
                && keepTaxDigits != loserTaxDigits)
                throw new InvalidOperationException(
                    $"รวมไม่ได้ — \"{keep.Name}\" (เลขภาษี {keepTaxDigits}) กับ \"{l.Name}\" "
                    + $"(เลขภาษี {loserTaxDigits}) เป็นคนละราย. การรวมจะทำให้เอกสารเก่าของทั้งสองราย"
                    + "เปลี่ยนคู่ค้าและรายงานภาษีผิด — ถ้าเลขภาษีรายใดผิด ให้แก้ที่ข้อมูลผู้ติดต่อก่อน");
        }

        // เก็บ "ก่อนแก้" ไว้ใน audit ให้ย้อนได้จริง: เอกสารที่กำลังจะถูกย้าย +
        // ตัวตนเดิมของ contact ที่ถูกยุบ (เดิมบันทึกแค่จำนวนแถว = ตรวจย้อนไม่ได้)
        var affectedDocs = await _db.Documents.AsNoTracking()
            .Where(d => d.CompanyId == companyId && mergeIds.Contains(d.ContactId))
            .Select(d => new { d.Id, d.DocumentNumber, d.ContactId })
            .Take(1000)
            .ToListAsync();

        // เติมข้อมูลที่ตัวเก็บยังว่างจากตัวที่ถูกรวม (ไม่ overwrite ของเดิม)
        foreach (var l in losers)
        {
            if (string.IsNullOrWhiteSpace(keep.TaxId) && !string.IsNullOrWhiteSpace(l.TaxId)) keep.TaxId = l.TaxId;
            if (string.IsNullOrWhiteSpace(keep.Address) && !string.IsNullOrWhiteSpace(l.Address)) keep.Address = l.Address;
            if (string.IsNullOrWhiteSpace(keep.Email) && !string.IsNullOrWhiteSpace(l.Email)) keep.Email = l.Email;
            if (string.IsNullOrWhiteSpace(keep.Phone) && !string.IsNullOrWhiteSpace(l.Phone)) keep.Phone = l.Phone;
            if (l.IsCustomer) keep.IsCustomer = true;
            if (l.IsSupplier) keep.IsSupplier = true;
        }

        // repoint FK ทุกคอลัมน์ที่ชี้ Contact — generic จาก information_schema
        // (ContactId + ชื่อ *ContactId ทุกแบบ: PayeeContactId, LinkedContactId,
        // MatchedContactId, ...) ยกเว้นตาราง Contacts เอง. Guid ไม่ชนข้าม tenant.
        var fkCols = await _db.Database.SqlQuery<FkColRow>($@"
            SELECT c.table_name AS ""TableName"", c.column_name AS ""ColumnName""
            FROM information_schema.columns c
            JOIN information_schema.tables t
              ON t.table_name = c.table_name AND t.table_schema = c.table_schema
            WHERE c.table_schema = 'public'
              AND t.table_type = 'BASE TABLE'
              AND c.table_name <> 'Contacts'
              AND (c.column_name = 'ContactId' OR c.column_name LIKE '%ContactId')
              AND c.data_type = 'uuid'")
            .ToListAsync();

        var strategy = _db.Database.CreateExecutionStrategy();
        var repointed = 0;
        await strategy.ExecuteAsync(async () =>
        {
            await using var tx = await _db.Database.BeginTransactionAsync();
            foreach (var loser in losers)
            {
                foreach (var col in fkCols)
                {
                    // table/column มาจาก information_schema (trusted) — quote กัน case
                    var sql = $"UPDATE \"{col.TableName}\" SET \"{col.ColumnName}\" = {{0}} WHERE \"{col.ColumnName}\" = {{1}}";
                    repointed += await _db.Database.ExecuteSqlRawAsync(sql, keepId, loser.Id);
                }
                // ร่องรอยการ merge เก็บใน AuditLog "ContactMerge" ด้านล่าง
                // (Contact ไม่มี field โน้ตอิสระให้เขียน)
                loser.IsDeleted = true;
                loser.IsActive = false;
                loser.UpdatedAt = DateTime.UtcNow;
                loser.UpdatedBy = performedBy;
            }
            keep.UpdatedAt = DateTime.UtcNow;
            keep.UpdatedBy = performedBy;
            _db.AuditLogs.Add(new AuditLog
            {
                CompanyId = companyId,
                UserId = Guid.TryParse(performedBy, out var uid) ? uid : null,
                Action = AuditAction.Update,
                EntityType = "ContactMerge",
                EntityId = keepId.ToString(),
                // "ก่อนแก้" — ตัวตนเดิมของ contact ที่ถูกยุบ + เอกสารที่ผูกอยู่
                // (ใช้ย้อนกลับได้จริงถ้ารวมผิด: UPDATE ContactId กลับตามรายการนี้)
                OldValues = System.Text.Json.JsonSerializer.Serialize(new
                {
                    losers = losers.Select(l => new { l.Id, l.Name, l.TaxId, l.BranchCode }),
                    documents = affectedDocs.Select(d => new { d.Id, d.DocumentNumber, previousContactId = d.ContactId }),
                }),
                NewValues = System.Text.Json.JsonSerializer.Serialize(new
                {
                    keepId, keepName = keep.Name, keepTaxId = keep.TaxId,
                    merged = mergeIds, rowsRepointed = repointed,
                    documentsMoved = affectedDocs.Count,
                }),
                Timestamp = DateTime.UtcNow
            });
            await _db.SaveChangesAsync();
            await tx.CommitAsync();
        });

        _logger.LogInformation("Merged {N} contacts into {Keep} ({Name}) — repointed {Rows} rows",
            losers.Count, keepId, keep.Name, repointed);
        return repointed;
    }

    private sealed class FkColRow
    {
        public string TableName { get; set; } = "";
        public string ColumnName { get; set; } = "";
    }

    public async Task<ContactResponse> CreateContactAsync(Guid companyId, CreateContactRequest request)
    {
        // ── กันสร้างซ้ำที่ "ศูนย์กลาง" (ครอบทุกเส้น: UI สร้างใหม่ / quick-sale /
        // OCR / import) — เลขภาษี+สาขาเดียวกัน = record เดียว: คืนตัวเดิมแบบ
        // idempotent + เติม field ที่ตัวเดิมยังว่างจากข้อมูลใหม่ (ไม่ overwrite
        // ของที่มีอยู่). เดิมไม่มี guard เลย → ผู้ติดต่อซ้ำ 3-4 รายการต่อ vendor
        var dup = await FindDuplicateContactAsync(companyId, request.TaxId, request.BranchCode);
        if (dup != null)
        {
            var enriched = false;
            void Fill(Func<string?> get, Action<string> set, string? val)
            { if (string.IsNullOrWhiteSpace(get()) && !string.IsNullOrWhiteSpace(val)) { set(val!); enriched = true; } }
            Fill(() => dup.Phone, v => dup.Phone = v, request.Phone);
            Fill(() => dup.Email, v => dup.Email = v, request.Email);
            Fill(() => dup.Address, v => dup.Address = v, request.Address);
            Fill(() => dup.ContactPerson, v => dup.ContactPerson = v, request.ContactPerson);
            // ⚠️ ต้องผ่านด่านเดียวกับเส้นสร้างใหม่/แก้ไข — เส้น dedup นี้คือเส้นที่
            // **API/import ใช้บ่อยที่สุด** (ยิงซ้ำด้วยเลขภาษีเดิม) ⇒ ถ้าเขียนดิบ
            // ค่าที่ตารางไม่รู้จัก ("Herr"/"คุณ") จะไหลไปลง Col12 ของไฟล์ ภ.ง.ด.3
            // = "ด่านที่ครอบแค่ทางเดียว คือด่านที่ไม่มี" ในทรงที่ซ่อนดีที่สุด
            // (อยู่ในเมธอดเดียวกับด่าน ห่างกัน 20 บรรทัด)
            Fill(() => dup.TitleTh, v => dup.TitleTh = v, NormalizeContactTitle(request.TitleTh));
            if (request.IsCustomer && !dup.IsCustomer) { dup.IsCustomer = true; enriched = true; }
            if (request.IsSupplier && !dup.IsSupplier) { dup.IsSupplier = true; enriched = true; }
            if (enriched) { dup.UpdatedAt = DateTime.UtcNow; await _db.SaveChangesAsync(); }
            _logger.LogInformation("CreateContact dedup: reuse {Id} ({Name}) for TaxId {Tax}",
                dup.Id, dup.Name, NormalizeTaxDigits(request.TaxId));
            return MapContactToResponse(dup);
        }

        // If structured fields are missing but free-text Address is provided,
        // attempt to auto-parse so e-Tax XML has the data it needs.
        var parsed = NeedsAutoParse(request) && !string.IsNullOrWhiteSpace(request.Address)
            ? ThaiAddressParser.Parse(request.Address)
            : null;

        // คำนำหน้า: ค่าที่ผู้ใช้กรอกชนะเสมอ · ไม่ได้กรอก = แยกจากชื่อให้
        // (ตัวแยกมีด่านกันตัดชื่อกิจการอย่าง "นายช่างการไฟฟ้า" อยู่แล้ว)
        // ⚠️ ต้องผ่านด่านก่อน — ค่านี้ไหลตรงไปคอลัมน์ที่ 12 ของไฟล์ที่อัปโหลด
        // เข้าเว็บกรมสรรพากร (ภ.ง.ด.3) และไฟล์ สปส.1-10 ซึ่งปฏิเสธทั้งแถวเมื่อ
        // คำนำหน้าไม่อยู่ในชุดที่รับ. หน้าจอเป็น dropdown แต่ API/import ส่งอะไร
        // มาก็ได้ ⇒ ด่านต้องอยู่ที่ service ไม่ใช่ที่หน้าจอ
        var titleTh = NormalizeContactTitle(request.TitleTh)
            ?? Accounting.Helpers.ThaiTitleHelper.Split(request.Name).Title;

        var contact = new Contact
        {
            CompanyId = companyId,
            TitleTh = titleTh,
            Name = request.Name,
            TaxId = request.TaxId,
            BranchCode = request.BranchCode,
            BranchName = request.BranchName,
            ContactType = request.ContactType ?? InferContactType(request.TaxId, request.BranchCode),
            IsCustomer = request.IsCustomer,
            IsSupplier = request.IsSupplier,
            BuildingNumber = request.BuildingNumber ?? parsed?.BuildingNumber,
            BuildingName = request.BuildingName ?? parsed?.BuildingName,
            Moo = request.Moo ?? parsed?.Moo,
            StreetName = request.StreetName ?? parsed?.StreetName,
            SubDistrict = request.SubDistrict ?? parsed?.SubDistrict,
            District = request.District ?? parsed?.District,
            Province = request.Province ?? parsed?.Province,
            PostalCode = request.PostalCode ?? parsed?.PostalCode,
            CountryCode = request.CountryCode ?? "TH",
            Phone = request.Phone,
            Email = request.Email,
            ContactPerson = request.ContactPerson,
            // Per-contact GL overrides — null = use system default.
            DefaultArAccountId = request.DefaultArAccountId,
            DefaultApAccountId = request.DefaultApAccountId,
            DefaultIrGrAccountId = request.DefaultIrGrAccountId,
            CreditLimit = request.CreditLimit,
            DefaultIssueTaxInvoice = request.DefaultIssueTaxInvoice,
            PaymentDueDays = request.PaymentDueDays,
            PaymentTerms = request.PaymentTerms,
            // กรองเหลือ th/en เท่านั้น — ค่าขยะจาก API ภายนอกกลายเป็น null
            DocumentLanguage = request.DocumentLanguage?.Trim().ToLowerInvariant() is "th" or "en"
                ? request.DocumentLanguage!.Trim().ToLowerInvariant() : null,
            // ข้อมูลภาษาอังกฤษ — ว่าง = null (ให้ระบบใช้ไทย/ถอดอักษรให้)
            NameEn = string.IsNullOrWhiteSpace(request.NameEn) ? null : request.NameEn.Trim(),
            AddressEn = string.IsNullOrWhiteSpace(request.AddressEn) ? null : request.AddressEn.Trim(),
        };

        contact.Address = request.Address ?? ComposeAddress(contact);

        _db.Contacts.Add(contact);
        await _db.SaveChangesAsync();

        return MapContactToResponse(contact);
    }

    /// <summary>ประกอบ Contact.Address (free-text) จาก structured fields — ค่านี้
    /// ถูก "บันทึกลงฐาน" และไหลไปทุกเอกสาร/รายงาน/e-Tax ต่อ จึงต้องมีคำนำหน้า
    /// ต./อ./จ. (หรือ แขวง/เขต สำหรับ กทม.) ตั้งแต่ตอนเขียน — เดิม join ด้วย
    /// ช่องว่างเปล่า ๆ ทำให้ที่อยู่ไม่มีคำนำหน้าถูกฝังลงฐานถาวร แล้วโผล่บน
    /// หนังสือรับรองหัก ณ ที่จ่าย / ใบกำกับภาษี ผิดข้อกำหนดเอกสารราชการ</summary>
    private static string? ComposeAddress(Contact c)
    {
        var joined = ThaiAddressFormatter.Format(
            null, c.BuildingNumber, c.BuildingName, c.Moo, c.StreetName,
            c.SubDistrict, c.District, c.Province, c.PostalCode);
        return string.IsNullOrWhiteSpace(joined) ? null : joined;
    }

    private static bool NeedsAutoParse(CreateContactRequest r) =>
        string.IsNullOrEmpty(r.BuildingNumber) && string.IsNullOrEmpty(r.SubDistrict)
        && string.IsNullOrEmpty(r.District) && string.IsNullOrEmpty(r.Province)
        && string.IsNullOrEmpty(r.PostalCode);

    public async Task<ContactResponse> GetContactAsync(Guid companyId, Guid contactId)
    {
        var contact = await _db.Contacts
            // Include GL-override nav properties so the UI can show the
            // account codes/names alongside the FKs.
            .Include(c => c.DefaultArAccount)
            .Include(c => c.DefaultApAccount)
            .Include(c => c.DefaultIrGrAccount)
            .FirstOrDefaultAsync(c => c.Id == contactId && c.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบผู้ติดต่อ");
        // Lazy backfill: contact เก่า / ที่ OCR เติมแต่ free-text Address (ก่อน
        // แก้ enrichment) มี structured fields ว่าง → ฟอร์มแก้ผู้ติดต่อขึ้นที่อยู่
        // ว่าง. เมื่อเปิดดู ให้ parse free-text เป็น structured ครั้งเดียวแล้ว
        // persist — ผู้ใช้ไม่ต้องกด "ดึงข้อมูล" เองอีก. ทำเฉพาะ single-get
        // (ฟอร์มแก้) ไม่ทำใน list เพื่อเลี่ยง write ก้อนใหญ่.
        if (BackfillContactStructuredAddress(contact))
            await _db.SaveChangesAsync();
        return MapContactToResponse(contact);
    }

    /// <summary>เติม structured address fields (บ้านเลขที่/หมู่/ถนน/ตำบล/อำเภอ/
    /// จังหวัด/ไปรษณีย์) จาก free-text <c>Address</c> เมื่อ locality ว่างทั้งหมด.
    /// ใช้ ThaiAddressParser ตัวเดียวกับฟอร์ม + OCR. เติมเฉพาะ field ที่ว่าง
    /// (ไม่ทับค่าที่มีอยู่). คืน true เมื่อมีการเปลี่ยนแปลง.</summary>
    private static bool BackfillContactStructuredAddress(Contact c)
    {
        if (string.IsNullOrWhiteSpace(c.Address)) return false;
        // มี locality อยู่แล้ว — ไม่ต้องทำ
        if (!string.IsNullOrWhiteSpace(c.SubDistrict)
            || !string.IsNullOrWhiteSpace(c.District)
            || !string.IsNullOrWhiteSpace(c.Province)) return false;

        var p = ThaiAddressParser.Parse(c.Address);
        if (string.IsNullOrWhiteSpace(p.Province)
            && string.IsNullOrWhiteSpace(p.SubDistrict)
            && string.IsNullOrWhiteSpace(p.District)) return false;

        bool changed = false;
        void Set(string? cur, string? val, Action<string> set)
        { if (string.IsNullOrWhiteSpace(cur) && !string.IsNullOrWhiteSpace(val)) { set(val!); changed = true; } }
        Set(c.BuildingNumber, p.BuildingNumber, v => c.BuildingNumber = v);
        Set(c.Moo, p.Moo, v => c.Moo = v);
        // เก็บส่วนหัวเต็ม (ห้อง/ชั้น/อาคาร/ซอย/ถนน) ไม่ใช่แค่ชื่อถนนสั้น เพื่อไม่ให้
        // รายละเอียดหายตอน render เป็น structured address.
        Set(c.StreetName, ThaiAddressParser.ExtractStreetHead(c.Address, p.BuildingNumber, p.Moo), v => c.StreetName = v);
        Set(c.SubDistrict, p.SubDistrict, v => c.SubDistrict = v);
        Set(c.District, p.District, v => c.District = v);
        Set(c.Province, p.Province, v => c.Province = v);
        Set(c.PostalCode, p.PostalCode, v => c.PostalCode = v);
        return changed;
    }

    public async Task<PagedResponse<ContactResponse>> GetContactsAsync(Guid companyId, bool? isCustomer = null, bool? isSupplier = null, string? search = null, PagedRequest? paging = null)
    {
        var query = _db.Contacts.Where(c => c.CompanyId == companyId);
        if (isCustomer.HasValue) query = query.Where(c => c.IsCustomer == isCustomer.Value);
        if (isSupplier.HasValue) query = query.Where(c => c.IsSupplier == isSupplier.Value);
        if (!string.IsNullOrWhiteSpace(search))
        {
            var s = search.Trim().ToLower();
            query = query.Where(c => c.Name.ToLower().Contains(s)
                || (c.TaxId != null && c.TaxId.Contains(s))
                || (c.Email != null && c.Email.ToLower().Contains(s))
                || (c.Phone != null && c.Phone.Contains(s)));
        }

        var totalCount = await query.CountAsync();
        var page = paging?.Page ?? 1;
        var pageSize = paging?.PageSize ?? 50;
        var contacts = await query.OrderBy(c => c.Name)
            .Skip((page - 1) * pageSize)
            .Take(pageSize)
            .ToListAsync();
        var totalPages = (int)Math.Ceiling((double)totalCount / pageSize);
        return new PagedResponse<ContactResponse>(
            contacts.Select(MapContactToResponse).ToList(),
            totalCount, page, pageSize, totalPages);
    }

    public async Task<ContactDeleteResult> DeleteContactAsync(Guid companyId, Guid contactId)
    {
        var contact = await _db.Contacts.FirstOrDefaultAsync(c => c.Id == contactId && c.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบผู้ติดต่อ");
        var docCount = await _db.Documents.CountAsync(d => d.ContactId == contactId && d.CompanyId == companyId && !d.IsDeleted);
        var whtCount = await _db.WithholdingTaxCerts.CountAsync(w => w.PayeeContactId == contactId && w.CompanyId == companyId && !w.IsDeleted);
        if (docCount > 0 || whtCount > 0)
        {
            contact.IsActive = false;
            await _db.SaveChangesAsync();
            return new ContactDeleteResult(
                Deleted: false,
                Deactivated: true,
                LinkedDocumentsCount: docCount,
                LinkedWhtCount: whtCount,
                Message: $"ผู้ติดต่อมีเอกสาร {docCount} รายการ และใบหัก ณ ที่จ่าย {whtCount} รายการ — " +
                         $"ระบบปิดการใช้งานแทนการลบเพื่อรักษาข้อมูลทางบัญชี");
        }
        _db.Contacts.Remove(contact);
        await _db.SaveChangesAsync();
        return new ContactDeleteResult(
            Deleted: true,
            Deactivated: false,
            LinkedDocumentsCount: 0,
            LinkedWhtCount: 0,
            Message: "ลบผู้ติดต่อสำเร็จ");
    }

    public async Task<ContactResponse> UpdateContactAsync(Guid companyId, Guid contactId, UpdateContactRequest request)
    {
        var contact = await _db.Contacts.FirstOrDefaultAsync(c => c.Id == contactId && c.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบผู้ติดต่อ");

        // ⚠️ ชื่อ/เลขภาษี = "ตัวตน" ของคู่ค้า ไม่ใช่ข้อมูลติดต่อธรรมดา: รายงาน
        // ภาษีซื้อ/ขายถ่าย snapshot จาก contact ตอน generate ดังนั้นการแก้ 2 field
        // นี้ทำให้ "เอกสารเก่าทุกใบ" ของรายนี้เปลี่ยนชื่อ/เลขภาษีตามย้อนหลัง และ
        // รายงานที่ regenerate ใหม่จะไม่ตรงกับกระดาษที่ยื่นไปแล้ว (§87). เดิมแก้
        // ได้เงียบ ๆ ไม่มีร่องรอย → สอบสวนย้อนหลังไม่ได้ว่าใครเปลี่ยนเมื่อไร
        var identityBefore = new { contact.Name, contact.TaxId, contact.BranchCode };
        var identityChanged =
            (request.Name != null && request.Name != contact.Name)
            || (request.TaxId != null && NormalizeTaxDigits(request.TaxId) != NormalizeTaxDigits(contact.TaxId))
            || (request.BranchCode != null && NormalizeBranchCode(request.BranchCode) != NormalizeBranchCode(contact.BranchCode));

        if (request.Name != null) contact.Name = request.Name;
        // "" = ผู้ใช้ตั้งใจล้างค่า (นิติบุคคลไม่มีคำนำหน้า) — ต้องล้างได้จริง
        if (request.TitleTh != null) contact.TitleTh = NormalizeContactTitle(request.TitleTh) ?? "";
        if (request.TaxId != null) contact.TaxId = request.TaxId;
        if (request.BranchCode != null) contact.BranchCode = request.BranchCode;
        if (request.BranchName != null) contact.BranchName = request.BranchName;
        if (request.ContactType.HasValue) contact.ContactType = request.ContactType.Value;
        else if (request.TaxId != null || request.BranchCode != null)
            contact.ContactType = InferContactType(request.TaxId ?? contact.TaxId, request.BranchCode ?? contact.BranchCode);
        if (request.IsCustomer.HasValue) contact.IsCustomer = request.IsCustomer.Value;
        if (request.IsSupplier.HasValue) contact.IsSupplier = request.IsSupplier.Value;
        if (request.BuildingNumber != null) contact.BuildingNumber = request.BuildingNumber;
        if (request.BuildingName != null) contact.BuildingName = request.BuildingName;
        if (request.Moo != null) contact.Moo = request.Moo;
        if (request.StreetName != null) contact.StreetName = request.StreetName;
        if (request.SubDistrict != null) contact.SubDistrict = request.SubDistrict;
        if (request.District != null) contact.District = request.District;
        if (request.Province != null) contact.Province = request.Province;
        if (request.PostalCode != null) contact.PostalCode = request.PostalCode;
        if (request.CountryCode != null) contact.CountryCode = request.CountryCode;
        contact.Address = request.Address ?? ComposeAddress(contact);
        // Phone/Email/ContactPerson: ผู้ใช้ "ลบจนว่าง" ต้องล้างค่าได้ — frontend
        // ส่ง "" เมื่อ cleared. normalize ""/whitespace → null (เก็บ null สะอาด
        // กว่า ""). null ที่แท้จริง (omit) = ไม่เปลี่ยน; "" = ล้าง.
        if (request.Phone != null) contact.Phone = string.IsNullOrWhiteSpace(request.Phone) ? null : request.Phone.Trim();
        if (request.Email != null) contact.Email = string.IsNullOrWhiteSpace(request.Email) ? null : request.Email.Trim();
        if (request.ContactPerson != null) contact.ContactPerson = string.IsNullOrWhiteSpace(request.ContactPerson) ? null : request.ContactPerson.Trim();
        if (request.IsActive.HasValue) contact.IsActive = request.IsActive.Value;
        // Per-contact GL overrides — record.Nullable<Guid> can't tell
        // "unset" from "explicitly clear to default", so we treat null
        // as "no change". To clear an override the UI POSTs
        // Guid.Empty which we map back to null below.
        if (request.DefaultArAccountId.HasValue)
            contact.DefaultArAccountId = request.DefaultArAccountId == Guid.Empty ? null : request.DefaultArAccountId;
        if (request.DefaultApAccountId.HasValue)
            contact.DefaultApAccountId = request.DefaultApAccountId == Guid.Empty ? null : request.DefaultApAccountId;
        if (request.DefaultIrGrAccountId.HasValue)
            contact.DefaultIrGrAccountId = request.DefaultIrGrAccountId == Guid.Empty ? null : request.DefaultIrGrAccountId;
        if (request.CreditLimit.HasValue)
            contact.CreditLimit = request.CreditLimit.Value <= 0 ? null : request.CreditLimit.Value;
        if (request.DefaultIssueTaxInvoice.HasValue)
            contact.DefaultIssueTaxInvoice = request.DefaultIssueTaxInvoice.Value;
        if (request.PaymentDueDays.HasValue)
            contact.PaymentDueDays = request.PaymentDueDays.Value < 0 ? null : request.PaymentDueDays.Value;
        if (request.PaymentTerms != null)
            contact.PaymentTerms = string.IsNullOrWhiteSpace(request.PaymentTerms) ? null : request.PaymentTerms.Trim();
        if (request.DocumentLanguage != null)
        {
            // "" = ล้างกลับเป็น "ตามค่าบริษัท" · th/en = ตั้ง · ค่าอื่น = null (กันขยะ)
            var cl = request.DocumentLanguage.Trim().ToLowerInvariant();
            contact.DocumentLanguage = cl is "th" or "en" ? cl : null;
        }

        // ข้อมูลภาษาอังกฤษ — semantics เดียวกับ field อื่นของ update:
        // null = ไม่แตะ · "" = ล้างค่า (กลับไปใช้ไทย / ถอดอักษรอัตโนมัติ)
        if (request.NameEn != null)
            contact.NameEn = string.IsNullOrWhiteSpace(request.NameEn) ? null : request.NameEn.Trim();
        if (request.AddressEn != null)
            contact.AddressEn = string.IsNullOrWhiteSpace(request.AddressEn) ? null : request.AddressEn.Trim();

        // ร่องรอยการเปลี่ยน "ตัวตน" — append-only ตาม cross-cutting invariant
        // (ดู CLAUDE.md §M) พร้อมจำนวนเอกสารที่ได้รับผลกระทบย้อนหลัง
        if (identityChanged)
        {
            var affected = await _db.Documents.AsNoTracking()
                .CountAsync(d => d.CompanyId == companyId && d.ContactId == contactId && !d.IsDeleted);
            _db.AuditLogs.Add(new AuditLog
            {
                CompanyId = companyId,
                Action = AuditAction.Update,
                EntityType = "ContactIdentity",
                EntityId = contactId.ToString(),
                OldValues = System.Text.Json.JsonSerializer.Serialize(identityBefore),
                NewValues = System.Text.Json.JsonSerializer.Serialize(new
                { contact.Name, contact.TaxId, contact.BranchCode, documentsAffected = affected }),
                Timestamp = DateTime.UtcNow,
            });
            _logger.LogWarning("Contact identity changed {Id}: '{OldName}'/{OldTax} → '{NewName}'/{NewTax} "
                + "— กระทบเอกสารย้อนหลัง {N} ใบ",
                contactId, identityBefore.Name, identityBefore.TaxId, contact.Name, contact.TaxId, affected);
        }

        await _db.SaveChangesAsync();
        // Reload with nav properties so MapContactToResponse can emit
        // the AR/AP/IR-GR account codes for the UI labels.
        return await GetContactAsync(companyId, contactId);
    }

    public async Task<ContactSmartDefaults> GetContactSmartDefaultsAsync(Guid companyId, Guid contactId)
    {
        var contact = await _db.Contacts.FirstOrDefaultAsync(c => c.Id == contactId && c.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบผู้ติดต่อ");
        return GetSmartDefaults(contact);
    }

    // ==================== Payments ====================

    /// <summary>ประเภทเอกสาร "ตั้งหนี้" ที่รับ/จ่ายชำระตรงได้ — ฝั่งขาย Dr AR
    /// ตอนอนุมัติ (Invoice/TaxInvoice/DebitNote ฝั่งขาย), ฝั่งซื้อ Cr AP
    /// (PurchaseInvoice/Expense/DebitNote ฝั่งซื้อ). ประเภทอื่นห้ามชำระตรง:
    /// เอกสาร operational ไม่มี JE, เอกสารเงินสด (Receipt/RV/PV/CIL) เงิน
    /// เข้า-ออกจริงไปแล้วตอนอนุมัติ</summary>
    private static readonly DocumentType[] PayableDocumentTypes =
    {
        DocumentType.Invoice, DocumentType.TaxInvoice, DocumentType.DebitNote,
        DocumentType.PurchaseInvoice, DocumentType.Expense,
    };

    /// <summary>ผังกำไร/ขาดทุนจากอัตราแลกเปลี่ยน — รองรับทั้ง 2 convention
    /// ที่มีในระบบ (template ใหม่ 42600/54950, FxRevaluationService เดิม
    /// 4901/5901) + fallback ค้นตามชื่อ + ข้ามฝั่ง (contra) เป็นทางเลือกสุดท้าย</summary>
    private async Task<ChartOfAccount?> ResolveFxGainLossAccountAsync(Guid companyId, bool isGain)
    {
        if (isGain)
            return await FindAccountAsync(companyId, "42600")
                ?? await FindAccountAsync(companyId, "4901")
                ?? await _db.ChartOfAccounts.FirstOrDefaultAsync(a => a.CompanyId == companyId
                    && a.IsActive && !a.IsDeleted && a.AccountName.Contains("กำไรจากอัตราแลกเปลี่ยน"))
                ?? await FindAccountAsync(companyId, "54950")
                ?? await FindAccountAsync(companyId, "5901");
        return await FindAccountAsync(companyId, "54950")
            ?? await FindAccountAsync(companyId, "5901")
            ?? await _db.ChartOfAccounts.FirstOrDefaultAsync(a => a.CompanyId == companyId
                && a.IsActive && !a.IsDeleted && a.AccountName.Contains("ขาดทุนจากอัตราแลกเปลี่ยน"))
            ?? await FindAccountAsync(companyId, "42600")
            ?? await FindAccountAsync(companyId, "4901");
    }

    /// <summary>เงินของการชำระเอกสารนี้ "เข้า" (ลูกค้าจ่ายเรา) หรือ "ออก"
    /// (เราจ่าย vendor) — DebitNote ต้องดูฝั่งจากเอกสารต้นทาง: ฝั่งซื้อ
    /// (source = PI/Expense/CIL) คือเงินออก ไม่ใช่เงินเข้า</summary>
    private async Task<bool> IsCashInflowDocAsync(Guid companyId, Document doc)
    {
        var inflow = doc.DocumentType is DocumentType.Invoice or DocumentType.TaxInvoice
            or DocumentType.Receipt or DocumentType.ReceiptVoucher
            or DocumentType.DebitNote or DocumentType.BillingNote;
        if (inflow && doc.DocumentType == DocumentType.DebitNote && doc.RelatedDocumentId.HasValue)
        {
            var srcType = await _db.Documents.AsNoTracking()
                .Where(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId)
                .Select(d => (DocumentType?)d.DocumentType)
                .FirstOrDefaultAsync();
            if (srcType is DocumentType.PurchaseInvoice or DocumentType.Expense
                or DocumentType.CertificateInLieu)
                inflow = false;
        }
        return inflow;
    }

    /// <summary>ออก "ใบเสร็จรับเงิน" (Document) เป็นหลักฐานคู่กับ Payment ที่เพิ่ง
    /// บันทึก — ลงวันที่รับเงินจริง, อ้างใบกำกับ/ใบแจ้งหนี้ต้นทาง. **ไม่ post JE**
    /// (Payment ลง Dr เงินสด/Cr ลูกหนี้ ให้แล้ว) และ **ไม่คิด VAT ซ้ำ** (VAT อยู่ที่
    /// ใบกำกับ) → VatAmount=0. สร้างตรงเป็น Status=Paid ไม่ผ่าน ApproveDocumentAsync
    /// จึงไม่ตัดหนี้ซ้ำผ่าน ApplySourceDocumentAdjustments. หัวพิมพ์ = "ใบเสร็จรับเงิน"
    /// (Receipt + VAT=0 ไม่ upgrade เป็นใบกำกับ).</summary>
    private async Task<Document> CreateSettlementReceiptAsync(
        Guid companyId, Document invoice, Payment payment, string createdBy,
        bool issueApproved = true, bool carryVatFromSource = false)
    {
        // carryVatFromSource (เคส ข): ใบแจ้งหนี้บริการ (VAT พัก 21913) รับครบงวด
        // เดียว → ใบเสร็จนี้ทำหน้าที่ "ใบกำกับภาษี ณ วันรับเงิน" (§78/1) — copy
        // บรรทัด + Sub/VAT/WHT/Total จากใบแจ้งหนี้ (เหมือนผลแปลงใบแจ้งหนี้→ใบเสร็จ)
        // → หัวพิมพ์ "ใบกำกับภาษี/ใบเสร็จรับเงิน". ยังไม่ post JE/ไม่นับ ภ.พ.30 ที่
        // ใบนี้ (VAT รายงานที่ใบแจ้งหนี้ผ่าน OutputVatDueAt — settlement ถูก exclude
        // อยู่แล้ว กระดาษกับ GL ไม่ซ้ำ)
        List<DocumentLine>? srcLines = null;
        if (carryVatFromSource)
        {
            srcLines = await _db.DocumentLines.AsNoTracking()
                .Where(l => l.DocumentId == invoice.Id && !l.IsDeleted)
                .OrderBy(l => l.LineOrder)
                .ToListAsync();
            if (srcLines.Count == 0) { carryVatFromSource = false; srcLines = null; }
        }
        // issueApproved: ผู้กดบันทึกมีสิทธิ์อนุมัติ → ใบสมบูรณ์ทันที (เลขจริง)
        // ไม่มีสิทธิ์ → Draft (เลข placeholder — เลขจริงออกตอนผู้มีสิทธิ์อนุมัติ
        // ผ่าน ApproveDocumentAsync ซึ่ง skip การลงบัญชีให้แล้วสำหรับใบ settlement)
        // ── เลขชุดไหน: ตัดสินจากบทบาททางกฎหมาย ไม่ใช่ชนิดข้อมูล ──
        // เส้นนี้ออกเลขเองไม่ผ่าน ApproveDocumentAsync ⇒ ต้องใช้กติกาเดียวกัน
        // (Helpers/TaxInvoiceSeriesPolicy) มิฉะนั้นใบเสร็จที่เป็น "ใบกำกับภาษี ณ
        // วันรับเงิน §78/1" จะยังตกไปอยู่เล่ม REC เหมือนเดิม ซึ่งเป็นเคสที่ทำให้
        // ผู้ใช้เห็น "เดี๋ยว TIV เดี๋ยว REC" มากที่สุด
        // carryVatFromSource = true ⇒ ใบนี้ถือ VAT + หัวพิมพ์คำว่าใบกำกับ
        var carriesTaxInvoiceRole = carryVatFromSource;
        var seriesTypeForReceipt = DocumentType.Receipt;
        if (carriesTaxInvoiceRole)
        {
            var unifySeries = Accounting.Helpers.TaxInvoiceSeriesPolicy.IsUnifiedSeriesEnabled(
                await _db.CompanySettings.AsNoTracking()
                    .Where(s => s.CompanyId == companyId)
                    .Select(s => s.UnifyTaxInvoiceNumberSeries)
                    .FirstOrDefaultAsync());
            if (unifySeries) seriesTypeForReceipt = DocumentType.TaxInvoice;
        }
        var number = issueApproved
            ? await Accounting.Helpers.DocumentNumberGenerator.NextAsync(
                _db, companyId, seriesTypeForReceipt, payment.PaymentDate)
            : $"DRAFT-{Guid.NewGuid():N}".Substring(0, 14);
        var srcLabel = invoice.DocumentType == DocumentType.TaxInvoice ? "ใบกำกับภาษี"
            : invoice.DocumentType == DocumentType.DebitNote ? "ใบเพิ่มหนี้" : "ใบแจ้งหนี้";
        var receipt = new Document
        {
            CompanyId = companyId,
            DocumentNumber = number,
            DocumentType = DocumentType.Receipt,
            DocumentDate = payment.PaymentDate,
            ContactId = invoice.ContactId,
            RelatedDocumentId = invoice.Id,
            IsSettlementReceipt = true,
            SettlementPaymentId = payment.Id,
            Reference = invoice.DocumentNumber,
            // ตรึงบทบาททางกฎหมายพร้อมเลขที่ (เหมือนเส้น approve) — ใบเสร็จที่ถือ
            // VAT มาจากใบแจ้งหนี้คือใบกำกับ ณ วันรับเงิน §78/1, นอกนั้นเป็นใบเสร็จเปล่า
            IsTaxInvoiceByLaw = carriesTaxInvoiceRole,
            Status = issueApproved ? DocumentStatus.Paid : DocumentStatus.Draft,
            // ลายเซ็น "ผู้มีอำนาจลงนาม" = ผู้กดบันทึกรับเงิน (ResolveSignersAsync
            // ใช้ UpdatedBy เป็น approver เมื่อไม่มี approval trail — เดิมว่าง →
            // fallback ลายเซ็น Owner ทุกใบ)
            UpdatedBy = issueApproved ? createdBy : null,
            PaymentType = Models.Enums.PaymentType.Cash,
            Currency = invoice.Currency,
            ExchangeRate = invoice.ExchangeRate,
            // ใบเสร็จอัตโนมัติออกให้ลูกค้าคนเดียวกับใบกำกับต้นทาง — ภาษาต้องตามใบ
            // ต้นทาง (ใบแจ้งหนี้อังกฤษ → ใบเสร็จอังกฤษ โดยผู้ใช้ไม่ต้องทำอะไร)
            DocumentLanguage = invoice.DocumentLanguage,
            // ใบเสร็จรับชำระต้องหน้าตาเดียวกับใบแจ้งหนี้/ใบกำกับต้นทาง —
            // เดิมตกทั้งสอง field ⇒ ลูกค้าได้ใบเสร็จหน้าตาบริษัทเปล่าหลังรับใบแบรนด์
            // (ผลตรวจ P3 / ข้อ 7)
            BrandId = invoice.BrandId,
            BranchId = invoice.BranchId,   // และสาขาที่ออกใบกำกับต้นทาง (§87)
            DocumentTemplateId = invoice.DocumentTemplateId,
            ProjectId = invoice.ProjectId,
            SubTotal = carryVatFromSource ? invoice.SubTotal : payment.Amount,
            DiscountAmount = carryVatFromSource ? invoice.DiscountAmount : 0m,
            // ปกติ: VAT อยู่ที่ใบกำกับต้นทางแล้ว — ไม่คิดซ้ำ (VAT=0)
            // carryVat: ใบนี้คือใบกำกับ ณ วันรับเงิน → ถือ VAT ของใบแจ้งหนี้
            VatAmount = carryVatFromSource ? invoice.VatAmount : 0m,
            WithholdingTaxAmount = carryVatFromSource ? invoice.WithholdingTaxAmount : 0m,
            TotalAmount = carryVatFromSource ? invoice.TotalAmount : payment.Amount,
            PaidAmount = carryVatFromSource ? invoice.TotalAmount : payment.Amount,
            BalanceDue = 0m,
            BankAccountId = payment.BankAccountId,
            Notes = $"รับชำระเงินตาม{srcLabel}เลขที่ {invoice.DocumentNumber} " +
                    $"(วันที่รับ {payment.PaymentDate:dd/MM/yyyy}, {payment.PaymentMethod})" +
                    (carryVatFromSource ? " — ทำหน้าที่ใบกำกับภาษี ณ วันรับเงิน (§78/1)" : ""),
            CreatedBy = createdBy,
        };
        _db.Documents.Add(receipt);
        if (carryVatFromSource && srcLines != null)
        {
            var ln = 1;
            foreach (var sl in srcLines)
            {
                _db.DocumentLines.Add(new DocumentLine
                {
                    DocumentId = receipt.Id,
                    LineOrder = ln++,
                    ProductCode = sl.ProductCode,
                    Description = sl.Description,
                    Quantity = sl.Quantity,
                    Unit = sl.Unit,
                    UnitPrice = sl.UnitPrice,
                    DiscountPercent = sl.DiscountPercent,
                    DiscountAmount = sl.DiscountAmount,
                    Amount = sl.Amount,
                    VatRate = sl.VatRate,
                    VatAmount = sl.VatAmount,
                    AccountId = sl.AccountId,
                    ProjectId = sl.ProjectId,
                });
            }
        }
        else
        {
            _db.DocumentLines.Add(new DocumentLine
            {
                DocumentId = receipt.Id,
                LineOrder = 1,
                Description = $"รับชำระเงินตาม{srcLabel}เลขที่ {invoice.DocumentNumber}",
                Quantity = 1m,
                Unit = "รายการ",
                UnitPrice = payment.Amount,
                Amount = payment.Amount,
                VatRate = 0m,
                VatAmount = 0m,
            });
        }
        return receipt;
    }

    /// <summary>ออกใบเสร็จรับเงินให้ <b>การรับชำระที่บันทึกไปแล้ว</b> (ย้อนหลัง)
    ///
    /// <para>═══ ที่มา (ผู้ใช้รายงาน 2026-09-11) ═══ ก่อนด่าน "ใบเสร็จต้องลงวันที่
    /// รับเงินจริง" (ม.105) เส้น <c>CreatePaymentAsync</c> ยอมให้ใบกำกับ<b>ยกหัว</b>
    /// เป็นใบเสร็จเองเมื่อรับครบงวดเดียว แล้ว<b>ไม่ออก REC แยก</b>. พอด่านมา หัวก็
    /// กลับเป็น "ใบกำกับภาษี" ถูกต้องตามกฎหมาย — แต่แถวที่บันทึกไว้แล้วกลายเป็น
    /// <b>มี JE รับเงิน มีเงินเข้าบัญชี แต่ไม่มีกระดาษใบรับให้ลูกค้าเลย</b>
    /// (เคสจริง: PAY-202609-0010 · JE RV-202609-0006 · ใบ TIV-20260805-0005)</para>
    ///
    /// <para>กติกา "ด่านที่ปิดทางต้องมีทางไปต่อ" (กฎเหล็ก #4) — การแก้โค้ดอย่างเดียว
    /// ไม่พอเมื่อของเสียถูก persist ไว้แล้ว. **แต่ห้ามเขียน migration ไล่สร้างเอกสาร
    /// ย้อนหลังเอง** เพราะเลขที่ §86/4 ต้องออกตอนคนตัดสินใจ (gap-free + ตรวจสอบได้)
    /// → เปิดเป็นปุ่มให้ผู้ใช้กดทีละใบแทน</para>
    ///
    /// <para>ใบที่ได้เป็นตัวเดียวกับที่เส้นบันทึกชำระออกให้ (<see cref="CreateSettlementReceiptAsync"/>)
    /// — ลงวันที่ <c>payment.PaymentDate</c> · ไม่ลง JE ซ้ำ · ไม่คิด VAT ซ้ำ</para></summary>
    public async Task<IssuedReceiptResult> IssueReceiptForPaymentAsync(
        Guid companyId, Guid paymentId, string createdBy)
    {
        var strategy = _db.Database.CreateExecutionStrategy();
        return await strategy.ExecuteAsync(async () =>
        {
        await using var tx = await _db.Database.BeginTransactionAsync();
        try
        {
            // ล็อกแถว payment ในธุรกรรม — กันกดสองครั้งแล้วได้ใบเสร็จสองใบ
            // (ซ้ำรอยบทเรียน VoidPaymentAsync: FOR UPDATE ต้องอยู่ใน transaction
            //  ไม่งั้น lock ถูกปล่อยทันทีใน autocommit)
            var payment = await _db.Payments
                .FromSqlRaw(
                    """SELECT * FROM "Payments" WHERE "Id" = {0} AND "CompanyId" = {1} FOR UPDATE""",
                    paymentId, companyId)
                .FirstOrDefaultAsync()
                ?? throw new KeyNotFoundException("ไม่พบการชำระเงิน");


            // มีใบเสร็จอยู่แล้ว → คืนใบเดิม ไม่สร้างซ้ำ (idempotent). เช็ค **สองทาง**
            // เพราะข้อมูลเก่าอาจมีใบอยู่จริงแต่ FK บน payment ว่าง
            var existing = await _db.Documents
                .FirstOrDefaultAsync(r => r.CompanyId == companyId && !r.IsDeleted
                    && r.Status != DocumentStatus.Voided && r.Status != DocumentStatus.Rejected
                    && (r.Id == payment.ReceiptDocumentId || r.SettlementPaymentId == paymentId));
            if (existing != null)
            {
                // ซ่อมสายที่ขาดไปด้วยเลย — ครั้งหน้าปุ่มจะไม่โผล่มาให้กดอีก
                if (payment.ReceiptDocumentId != existing.Id)
                {
                    payment.ReceiptDocumentId = existing.Id;
                    await _db.SaveChangesAsync();
                }
                await tx.CommitAsync();
                return new IssuedReceiptResult(existing.Id, existing.DocumentNumber,
                    existing.DocumentDate, existing.Status == DocumentStatus.Draft, AlreadyExisted: true);
            }

            // เงินก้อนเดียวกระจายหลายใบ — ใบเสร็จ settlement เป็น 1 payment : 1 ใบ
            // ต้นทาง จึงตัดสินยอดต่อใบเองไม่ได้ ("ไม่รู้ = บอกว่าไม่รู้")
            var allocCount = await _db.PaymentAllocations.CountAsync(
                a => a.PaymentId == paymentId && a.CompanyId == companyId && !a.IsDeleted);
            var doc = await _db.Documents.FirstOrDefaultAsync(
                d => d.Id == payment.DocumentId && d.CompanyId == companyId && !d.IsDeleted)
                ?? throw new KeyNotFoundException("ไม่พบเอกสารต้นทางของการชำระนี้");

            // ใบต้นทางเป็น "ใบกำกับภาษี/ใบเสร็จรับเงิน" ของการรับเงินก้อนนี้อยู่แล้ว
            // ไหม — ตัวตัดสินตัวเดียวกับที่หน้าจอ/PDF ใช้ (ComputeServedAsReceipt)
            // ห้ามเขียนเกณฑ์ใหม่ตรงนี้. เทียบวันที่ของ **การชำระรายการนี้** ด้วย
            // เพราะใบที่ผ่อนหลายงวดแล้วงวดสุดท้ายตรงวันที่ใบ ยังต้องออกใบเสร็จให้
            // งวดก่อนหน้าที่รับเงินคนละวัน
            var servedByDoc = ComputeServedAsReceipt(doc,
                (await LoadDocIdsWithSeparateReceiptAsync(_db, companyId, new[] { doc.Id })).Contains(doc.Id),
                await GetReceiptIssueModeAsync(companyId),
                (await LoadSettlementDatesAsync(_db, companyId, new[] { doc.Id }))
                    .TryGetValue(doc.Id, out var settledOnSrc) ? settledOnSrc : null);
            var sourceServesAsReceipt = Accounting.Helpers.ReceiptIssuePolicy.CoversPayment(
                servedByDoc, doc.DocumentDate, payment.PaymentDate);

            // ด่านทั้งหมดอยู่ที่ Helpers/SettlementReceiptPolicy ตัวเดียว — คืนเหตุผล
            // เป็นข้อความไทยที่เอาไปโชว์ได้ ไม่ใช่ bool ให้หน้าจอแต่งคำเอง
            var why = Accounting.Helpers.SettlementReceiptPolicy.WhyCannotIssue(
                payment.IsDeleted, doc.DocumentType, doc.Status, allocCount, sourceServesAsReceipt);
            if (why != null) throw new InvalidOperationException(why);

            // เกณฑ์ "ใบเสร็จนี้คือใบกำกับภาษี ณ วันรับเงิน (§78/1)" มาจาก helper
            // ตัวเดียวกับเส้นบันทึกรับชำระ ("งวดเดียว" ที่นี่ = เป็นรายการชำระ
            // รายการเดียวของใบ และยอดคงเหลือเป็นศูนย์)
            var paymentCount = await _db.Payments.CountAsync(
                pm => pm.DocumentId == doc.Id && pm.CompanyId == companyId && !pm.IsDeleted);
            var carryVat = Accounting.Helpers.SettlementReceiptPolicy.CarriesTaxInvoiceRole(
                doc.DocumentType, doc.VatAmount, doc.BalanceDue <= 0.005m && paymentCount == 1);

            // สิทธิ์อนุมัติของ "ผู้กดออกใบ" → ใบสมบูรณ์ทันที (เลขจริง) หรือ Draft
            // รอผู้มีสิทธิ์อนุมัติ — กติกาเดียวกับตอนบันทึกรับชำระ
            var canApprove = true;
            if (_permissionService != null && Guid.TryParse(createdBy, out var uid))
                canApprove = await Accounting.Helpers.DocumentPermissionHelper
                    .CanApproveAsync(_permissionService, companyId, uid, DocumentType.Receipt);

            var receipt = await CreateSettlementReceiptAsync(
                companyId, doc, payment, createdBy, canApprove, carryVat);
            await _db.SaveChangesAsync();
            payment.ReceiptDocumentId = receipt.Id;
            await _db.SaveChangesAsync();
            await tx.CommitAsync();
            // ★ รอบ 193 ฝ่ายค้าน C-3 — ใบเสร็จที่ถือ VAT = ใบกำกับ ณ วันรับเงิน (§78/1) เกิดเป็น Paid ไม่ผ่าน
            // ApproveDocumentAsync ⇒ เดิมไม่เคยได้ e-Tax อัตโนมัติ · hook ตัดสินขอบเขตเอง (ใบเสร็จเปล่า/ร่าง = ข้าม)
            // เรียกหลัง commit · ล้ม = ป้ายบนเอกสาร ไม่ย้อนการออกใบ
            await _issuedHooks.RunAsync(companyId, receipt);
            return new IssuedReceiptResult(receipt.Id, receipt.DocumentNumber,
                receipt.DocumentDate, receipt.Status == DocumentStatus.Draft, AlreadyExisted: false);
        }
        catch
        {
            await tx.RollbackAsync();
            throw;
        }
        });
    }

    public async Task<PaymentResponse> CreatePaymentAsync(Guid companyId, CreatePaymentRequest request, string createdBy)
    {
        // Validate Amount > 0
        if (request.Amount <= 0)
            throw new InvalidOperationException("จำนวนเงินชำระต้องมากกว่า 0");

        // Validate PaymentDate is not in the future
        if (request.PaymentDate > DateTime.UtcNow.Date.AddDays(1))
            throw new InvalidOperationException("วันที่ชำระเงินต้องไม่เป็นวันที่ในอนาคต");

        if (request.ExchangeRate is <= 0)
            throw new InvalidOperationException("อัตราแลกเปลี่ยน ณ วันชำระต้องมากกว่า 0");
        if (request.FeeAmount is < 0)
            throw new InvalidOperationException("ค่าธรรมเนียมต้องไม่ติดลบ");

        var strategy = _db.Database.CreateExecutionStrategy();
        return await strategy.ExecuteAsync(async () =>
        {
        // ⚠️ เปิด transaction "ก่อน" FOR UPDATE — lock จะถือไว้จนจบ transaction
        // เท่านั้น. เดิมเปิด tx ทีหลัง → FOR UPDATE รันใน autocommit → ปล่อย lock
        // ทันที → ชำระพร้อมกัน 2 รายการ ผ่าน balance check ทั้งคู่ → ตัด AR ซ้ำ
        // (over-relief). await using = rollback อัตโนมัติถ้า throw ก่อน commit.
        await using var transaction = await _db.Database.BeginTransactionAsync();
        // ใบเสร็จ settlement ที่ออกในรอบนี้ — ส่งให้ผลข้างเคียงหลังออกเอกสาร **หลัง commit** (C-3)
        // (reset ทุกรอบของ execution strategy — รอบที่ rollback ต้องไม่ค้างค่า)
        Document? issuedSettlementReceipt = null;
        // Lock document row to prevent concurrent overpayment
        var doc = await _db.Documents
            .FromSqlRaw("SELECT * FROM \"Documents\" WHERE \"Id\" = {0} AND \"CompanyId\" = {1} FOR UPDATE", request.DocumentId, companyId)
            .FirstOrDefaultAsync()
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");

        // Validate document status allows payment
        if (doc.Status != DocumentStatus.Approved && doc.Status != DocumentStatus.PartiallyPaid && doc.Status != DocumentStatus.Sent && doc.Status != DocumentStatus.Overdue)
            throw new InvalidOperationException("สามารถชำระเงินได้เฉพาะเอกสารที่อนุมัติแล้ว, ชำระบางส่วน, ส่งแล้ว หรือเกินกำหนดเท่านั้น");

        // เฉพาะเอกสาร "ตั้งหนี้" เท่านั้นที่รับ/จ่ายชำระได้ — เอกสารอื่นทำ GL พัง:
        //   • ใบวางบิล/ใบเสนอราคา/PO ฯลฯ ไม่ลง JE ตอนอนุมัติ → ชำระแล้ว Cr AR
        //     ที่ไม่เคยถูก Dr (AR ติดลบ) หรือเข้า branch ผิดฝั่ง
        //   • ใบเสร็จ/ใบสำคัญรับ/ใบสำคัญจ่าย/ใบรับรองแทนใบเสร็จ = เงินเข้า/ออก
        //     จริงไปแล้วตอนอนุมัติ → ชำระซ้ำ = เงินสดเบิ้ล
        if (!PayableDocumentTypes.Contains(doc.DocumentType))
            throw new InvalidOperationException(
                $"เอกสารประเภท {doc.DocumentType} รับ/จ่ายชำระตรง ๆ ไม่ได้ — " +
                "ใบวางบิล/ใบเสนอราคาให้แปลงเป็นใบแจ้งหนี้/ใบกำกับ/ใบเสร็จก่อน; " +
                "ใบเสร็จ/ใบสำคัญรับ-จ่ายคือหลักฐานเงินเข้า-ออกที่เกิดแล้ว ไม่ต้องชำระซ้ำ");

        var paymentFee = request.FeeAmount ?? 0m;
        if (paymentFee > 0)
        {
            // ค่าธรรมเนียมหักจากยอดโอนใช้กับฝั่งรับเท่านั้น (marketplace/gateway
            // หักก่อนโอน) — ฝั่งจ่ายบันทึกค่าธรรมเนียมเป็นค่าใช้จ่ายแยกเอง
            var feeAllowedTypes = new[] { DocumentType.Invoice, DocumentType.TaxInvoice, DocumentType.DebitNote };
            if (!feeAllowedTypes.Contains(doc.DocumentType))
                throw new InvalidOperationException(
                    "ค่าธรรมเนียมหักจากยอดโอน ใช้ได้เฉพาะเอกสารฝั่งขาย (ใบแจ้งหนี้/ใบกำกับ/ใบเพิ่มหนี้)");
        }
        // ── รอบ 193 (คำตัดสินเจ้าของข้อ 1/3): บรรทัดปรับส่วนต่าง "ยอดหนี้ตามใบ ↔ เงินที่จ่ายจริง" ──
        // ใบกำกับซื้อ 536 (ยอดตั้งหนี้ห้ามแก้) · จ่ายจริง 438 · ค่าส่ง +37 → 51120 · คูปอง −135 → 51150 ⇒ ปิดหนี้ 536
        // ตัวตรวจ Helpers/PaymentSettlementAdjustment (pure + เทสต์) · ไม่มีบรรทัดปรับ = พฤติกรรมเดิมทุกประการ
        var settleLines = (request.SettlementAdjustments ?? new List<PaymentSettlementAdjustmentRequest>())
            .Select(a => new Accounting.Helpers.SettlementAdjustmentLine(
                (a.AccountCode ?? "").Trim(), Math.Round(a.Amount, 2, MidpointRounding.AwayFromZero),
                string.IsNullOrWhiteSpace(a.Reason) ? null : a.Reason.Trim()))
            .ToList();
        decimal settleNet = 0m;
        var settleAccounts = new List<(Guid AccountId, decimal Amount, string? Reason, string Code)>();
        if (settleLines.Count > 0)
        {
            if (doc.DocumentType is not (DocumentType.PurchaseInvoice or DocumentType.Expense))
                throw new Accounting.Helpers.BusinessRuleException(
                    "บรรทัดปรับส่วนต่างยอดชำระใช้ได้กับเอกสารตั้งหนี้ฝั่งซื้อ (ใบแจ้งหนี้ซื้อ/ค่าใช้จ่าย) เท่านั้น — "
                    + "ฝั่งขายที่ถูกหักค่าธรรมเนียมจากยอดโอนให้ใช้ช่อง \"ค่าธรรมเนียม\" · ใบสำคัญจ่ายที่จ่ายในตัวให้ใช้ช่อง "
                    + "\"ยอดชำระจริง\" + ปรับปรุงรายการบัญชีของเอกสาร",
                    Accounting.Helpers.PaymentSettlementAdjustment.RuleCode);
            if (doc.ExchangeRate != 1m)
                throw new Accounting.Helpers.BusinessRuleException(
                    "บรรทัดปรับส่วนต่างยอดชำระยังรองรับเฉพาะเอกสารสกุลบาท — เอกสารสกุลต่างประเทศให้บันทึกส่วนต่างด้วยสมุดรายวันทั่วไป",
                    Accounting.Helpers.PaymentSettlementAdjustment.RuleCode);
            var settleCheck = Accounting.Helpers.PaymentSettlementAdjustment.Check(request.Amount, doc.BalanceDue, settleLines);
            if (!settleCheck.Ok)
                throw new Accounting.Helpers.BusinessRuleException(settleCheck.Error!, Accounting.Helpers.PaymentSettlementAdjustment.RuleCode);
            settleNet = settleCheck.AdjustmentNet;
            foreach (var sl in settleLines)
            {
                var slAccountId = await _db.ChartOfAccounts.AsNoTracking()
                    .Where(a => a.CompanyId == companyId && a.AccountCode == sl.AccountCode && a.IsActive && !a.IsDeleted)
                    .Select(a => (Guid?)a.Id).FirstOrDefaultAsync()
                    ?? throw new Accounting.Helpers.BusinessRuleException(
                        $"ไม่พบผังบัญชี {sl.AccountCode} ในผังของบริษัท (หรือถูกปิดใช้) — เพิ่ม/เปิดผังนี้ก่อน หรือเลือกผังอื่นในบรรทัดปรับ",
                        Accounting.Helpers.PaymentSettlementAdjustment.RuleCode);
                settleAccounts.Add((slAccountId, sl.Amount, sl.Reason, sl.AccountCode));
            }
        }

        // ด่านจ่ายเกิน — เกณฑ์เดียวกับทุกทางเข้า (Integration/นำเข้าไฟล์) ผ่าน
        // `DocumentSettlementState.WouldOverpay` (ผลตรวจ D4-3: เดิมเว็บใช้ 0.01
        // · integration ใช้ 0.005 · นำเข้าไฟล์ไม่มีด่านเลย) · มีบรรทัดปรับ = ตรวจยอดที่ปิดจริงใน Check ข้างบนแล้ว
        if (settleLines.Count == 0 && Accounting.Helpers.DocumentSettlementState.WouldOverpay(
                doc.BalanceDue, request.Amount + paymentFee))
            throw new InvalidOperationException(
                $"เงินสุทธิ ({request.Amount:N2}) + ค่าธรรมเนียม ({paymentFee:N2}) มากกว่ายอดค้างชำระ ({doc.BalanceDue:N2})");

        // Installment WHT — for cash-basis WHT recognition (or when the
        // source carries any WHT at all), each installment recognises its
        // own slice of the WHT-Asset / WHT-Payable line. Default split is
        // proportional to the amount being paid this round; operator can
        // override (e.g. customer's withholding certificate shows the full
        // WHT on installment 1). Cumulative WHT across all settled payments
        // can't exceed source.WithholdingTaxAmount — that's the legal cap.
        decimal paymentWht = 0m;
        if (doc.WithholdingTaxAmount > 0m)
        {
            // Sum WHT from BOTH Payment rows AND Receipt-document children
            // referencing this Invoice via RelatedDocumentId — operators can
            // mix the modal flow with the manual Receipt-conversion flow,
            // and only counting one path lets cumulative exceed the cap
            // when both are used. Excludes Draft/Voided/Rejected on both
            // sides so in-flight or cancelled rows don't reserve slots.
            var withheldViaPayments = await _db.Payments.AsNoTracking()
                .Where(p => p.DocumentId == doc.Id && !p.IsDeleted)
                .SumAsync(p => (decimal?)p.WithholdingTaxAmount) ?? 0m;
            var settlementTypes = new[] { DocumentType.Receipt, DocumentType.ReceiptVoucher, DocumentType.PaymentVoucher };
            var withheldViaReceipts = await _db.Documents.AsNoTracking()
                .Where(r => r.RelatedDocumentId == doc.Id
                    && settlementTypes.Contains(r.DocumentType)
                    && r.Status != DocumentStatus.Voided
                    && r.Status != DocumentStatus.Draft
                    && r.Status != DocumentStatus.Rejected
                    && !r.IsDeleted)
                .SumAsync(r => (decimal?)r.WithholdingTaxAmount) ?? 0m;
            var alreadyWithheld = withheldViaPayments + withheldViaReceipts;
            var remainingCap = Math.Max(0m, doc.WithholdingTaxAmount - alreadyWithheld);

            // Final-installment detection — if this payment closes the
            // outstanding balance, assign whatever WHT slice is still
            // unspent so cumulative lands exactly on doc.WithholdingTaxAmount.
            // Without this, proportional rounding leaves a satang-level gap
            // (115.38 + 115.38 + 69.23 = 299.99 ≠ 300.00) and the WHT cert
            // numbers don't reconcile with ภ.ง.ด.3/53 filings.
            // settleNet (รอบ 193) = หนี้ที่ปิดด้วยบรรทัดปรับ — นับเป็นการปิดหนี้ของงวดนี้ด้วย
            var isFinalPayment = request.Amount + paymentFee + settleNet + 0.01m >= doc.BalanceDue;

            if (request.WithholdingTaxAmount.HasValue)
            {
                paymentWht = Math.Round(request.WithholdingTaxAmount.Value, 2, MidpointRounding.AwayFromZero);
                if (paymentWht < 0m)
                    throw new InvalidOperationException("WHT ของงวดนี้ต้องไม่ติดลบ");
                if (paymentWht > remainingCap + 0.01m)
                    throw new InvalidOperationException(
                        $"WHT งวดนี้ ({paymentWht:N2}) + ที่หักไปแล้ว ({alreadyWithheld:N2}) " +
                        $"เกินยอด WHT ทั้งหมดของเอกสาร ({doc.WithholdingTaxAmount:N2})");
            }
            else if (isFinalPayment)
            {
                // Closing payment: consume the remaining slice exactly so
                // rounding can't drift below the legal total.
                paymentWht = remainingCap;
            }
            else
            {
                // Proportional default: this installment's share of the
                // total WHT. Capped at the remaining slice so rounding can't
                // overshoot on the last payment.
                var proportional = doc.TotalAmount > 0m
                    ? Math.Round((request.Amount + settleNet) * doc.WithholdingTaxAmount / doc.TotalAmount, 2, MidpointRounding.AwayFromZero)
                    : 0m;
                paymentWht = Math.Min(proportional, remainingCap);
            }
        }

        // (transaction เปิดไว้ก่อน FOR UPDATE ด้านบนแล้ว)
        try
        {
            var payYearMonth = DateTime.UtcNow.ToString("yyyyMM");
            var payPrefix = $"PAY-{payYearMonth}-";
            var maxPayNum = await _db.Payments
                .IgnoreQueryFilters()
                .Where(p => p.CompanyId == companyId && p.PaymentNumber.StartsWith(payPrefix))
                .Select(p => p.PaymentNumber)
                .MaxAsync() as string;
            var paySeq = 1;
            if (maxPayNum != null)
            {
                var lastPart = maxPayNum.Substring(payPrefix.Length);
                if (int.TryParse(lastPart, out var parsed)) paySeq = parsed + 1;
            }
            var payment = new Payment
            {
                CompanyId = companyId,
                PaymentNumber = $"{payPrefix}{paySeq:D4}",
                DocumentId = request.DocumentId,
                PaymentDate = request.PaymentDate,
                Amount = request.Amount,
                PaymentMethod = request.PaymentMethod,
                Reference = request.Reference,
                BankAccount = request.BankAccount,
                // Honour the per-payment override when supplied. This is the
                // "ลูกค้าจ่ายเข้าบัญชี Kasikorn แทน Bangkok Bank" case —
                // operator records the actual landing bank so the GL +
                // bank-balance adjustment hit the right place. Falls back
                // to doc.BankAccountId when not provided.
                BankAccountId = request.OverrideBankAccountId ?? doc.BankAccountId,
                OverrideBankAccountId = request.OverrideBankAccountId,
                OverridePaymentAccountId = request.OverridePaymentAccountId,
                WithholdingTaxAmount = paymentWht,
                // Per-payment ProjectId override — when null, the JE
                // posting still falls back to doc.ProjectId so the
                // common case "all of an invoice's payments hit one
                // project" needs no extra input.
                ProjectId = request.ProjectId,
                Notes = request.Notes,
                // Optional per-request payer signature override (for service
                // accounts / API callers whose user has no signature on file).
                // Validation: cap size to ~512 KB base64 (~384 KB raw image)
                // so a buggy caller can't inflate a Payment row.
                PayerSignatureBase64 = TrimSignature(request.PayerSignatureBase64),
                PayerSignatureName = request.PayerSignatureName,
                // rate วันชำระ — เก็บเฉพาะเอกสาร FX (THB rate=1 ไม่มีความหมาย)
                ExchangeRate = doc.ExchangeRate != 1m ? request.ExchangeRate : null,
                FeeAmount = paymentFee,
                FeeAccountId = request.FeeAccountId,
                // รอบ 193: หนี้ที่ปิดด้วยบรรทัดปรับ + บรรทัดทั้งชุด (ขา JE อยู่ใน CreatePaymentJournalAsync)
                SettlementAdjustmentAmount = settleNet,
                SettlementAdjustmentsJson = settleLines.Count == 0 ? null
                    : System.Text.Json.JsonSerializer.Serialize(settleLines),
                CreatedBy = createdBy
            };

            _db.Payments.Add(payment);

            doc.PaidAmount += request.Amount + paymentFee + settleNet;
            var paySettle = Accounting.Helpers.DocumentSettlementState.Apply(
                doc.TotalAmount, doc.PaidAmount, doc.Status);
            doc.BalanceDue = paySettle.BalanceDue;
            doc.Status = paySettle.Status;
            // Clear stale aging immediately when the doc settles — otherwise
            // the list view keeps showing "⏳ 30+d" on a paid invoice until
            // DocumentAgingBackgroundService runs (every 6h). PartiallyPaid
            // docs keep their aging since they still have an outstanding
            // balance.
            if (doc.Status == DocumentStatus.Paid)
            {
                doc.AgingDays = null;
                doc.AgingLastEvaluatedAt = DateTime.UtcNow;
            }

            await _db.SaveChangesAsync();

            // Create journal entry for payment (+ บรรทัดปรับส่วนต่าง รอบ 193)
            await CreatePaymentJournalAsync(companyId, doc, payment, createdBy,
                settleAccounts.Count == 0 ? null
                    : settleAccounts.Select(a => (a.AccountId, a.Amount, a.Reason)).ToList());

            await _db.SaveChangesAsync();

            // เกณฑ์เงินสด: WHT ถูกรับรู้ตอนรับเงินจริง (ไม่ใช่ตอนออกใบ) →
            // ต้อง sync ทะเบียนเครดิตอีกครั้งหลังลง JE ของการรับชำระ
            await SyncWhtCreditReceivedAsync(companyId, doc);

            // ออกใบเสร็จรับเงิน "หลักฐาน" คู่กับการชำระ (default เปิด) — เฉพาะฝั่งขาย
            // (ลูกค้าจ่ายเรา). Payment ลง JE/ตัด AR แล้ว → ใบนี้ evidence-only ไม่ลง JE
            // ซ้ำ ไม่คิด VAT ซ้ำ (VAT อยู่ที่ใบกำกับ) ลงวันที่รับเงินจริง. รองรับผ่อน
            // หลายงวด (1 Payment = 1 ใบเสร็จ).
            // รับครบใน "งวดเดียว" (ไม่มีชำระก่อนหน้า + งวดนี้ปิดยอด) — ตัวตัดสิน
            // ทั้งเคส 3-in-1 (A) และใบเสร็จถือ VAT (B) ข้างล่าง
            var priorPaidBefore = doc.PaidAmount - payment.Amount - payment.WithholdingTaxAmount;
            var singleShotFull = doc.BalanceDue <= 0.005m && priorPaidBefore <= 0.05m;

            // (A) ใบรวม "ใบแจ้งหนี้/ใบกำกับภาษี" + ติ๊กรับเงินครบงวดเดียว → ตัวใบรวม
            // ทำหน้าที่ใบเสร็จเอง (ServedAsReceipt → หัวพิมพ์ 3-in-1 "ใบแจ้งหนี้/
            // ใบกำกับภาษี/ใบเสร็จรับเงิน") — ไม่ออกใบเสร็จแยกซ้ำ กระดาษใบเดียวจบ.
            // ผ่อนหลายงวดยังออกใบเสร็จหลักฐานต่องวดตามเดิม (ใบรวมแทนใบเสร็จ
            // ของหลายงวดไม่ได้ → หัวคง 2 หน้าที่)
            // นโยบายบริษัท (Helpers/ReceiptIssuePolicy) เป็นตัวตั้ง default และ
            // เป็นตัว "บังคับ" ในโหมดแยกใบ:
            //   • ค่าที่ client ส่งมาชนะ default — ยกเว้นโหมดแยกใบที่บังคับออกเสมอ
            //     (ไม่งั้นพนักงานเผลอปลดติ๊กครั้งเดียว = ใบกำกับใบนั้นยกหัวเป็น
            //     ใบเสร็จในตัวไม่ได้ด้วย (ถูก suppress) ⇒ ลูกค้าไม่มีใบเสร็จเลย)
            //   • โหมดแยกใบยังปิด "ใบรวมทำหน้าที่ใบเสร็จเอง" ด้วย — ไม่งั้นใบ
            //     combined จะเป็นข้อยกเว้นที่หลุดนโยบายเงียบ ๆ
            //   • และรับเงิน**วันเดียวกับวันที่บนใบ**เท่านั้น (ขายสด/รับหน้างาน) —
            //     ผู้ใช้รายงาน 2026-09-10: กดบันทึกรับเงินบนใบลงวันที่ 5 ส.ค. โดยเงิน
            //     เข้าคนละวัน แล้ว "ใบเดิม" เปลี่ยนหัวเป็นใบเสร็จ ⇒ ใบรับลงวันที่เท็จ
            //     (ม.105 ใบรับต้องลงวันที่ที่รับเงินจริง) และไม่ตรงกับ 50 ทวิ ของผู้จ่าย.
            //     คนละวัน → เดินเส้นเดียวกับ "แปลงเอกสารเป็นใบเสร็จรับเงิน" คือออก
            //     REC แยกลงวันที่รับเงิน (CreateSettlementReceiptAsync ข้างล่าง)
            var receiptMode = await GetReceiptIssueModeAsync(companyId);
            var forceSeparate = Accounting.Helpers.ReceiptIssuePolicy.ForcesSeparateReceipt(receiptMode);
            var notCombinedReason = Accounting.Helpers.ReceiptIssuePolicy
                .WhyNotCombined(receiptMode, doc.DocumentDate, payment.PaymentDate);
            var combinedSelfReceipt = notCombinedReason == null
                && doc.DocumentType == DocumentType.TaxInvoice
                && doc.CombinedInvoiceTaxInvoice && singleShotFull;
            if (notCombinedReason != null && doc.DocumentType == DocumentType.TaxInvoice
                && doc.CombinedInvoiceTaxInvoice && singleShotFull)
                _logger.LogInformation(
                    "ใบ {Doc} ไม่ยกหัวเป็นใบเสร็จในตัว — {Reason}", doc.DocumentNumber, notCombinedReason);

            var wantReceipt = (forceSeparate
                    || (request.IssueReceiptDocument
                        ?? Accounting.Helpers.ReceiptIssuePolicy.DefaultIssueSeparateReceipt(receiptMode)))
                && !combinedSelfReceipt
                && doc.DocumentType is DocumentType.Invoice or DocumentType.TaxInvoice or DocumentType.DebitNote;
            if (wantReceipt)
            {
                // การชำระ (JE/ตัด AR) คือแกนสำคัญ — ถ้าออกใบเสร็จหลักฐานพลาด ห้าม
                // ล้มการชำระที่สำเร็จแล้ว. ล้มเหลว → ข้ามใบเสร็จ (ผู้ใช้ออกทีหลังได้)
                try
                {
                    // สิทธิ์ของ "ผู้กดบันทึกรับเงิน": มีสิทธิ์อนุมัติ Receipt → ออกใบ
                    // เสร็จสมบูรณ์ทันที + ลายเซ็นผู้มีอำนาจ = คนกดบันทึก (ไม่ใช่ Owner
                    // fallback แบบเดิม). ไม่มีสิทธิ์ → ใบเสร็จเป็น Draft รอผู้มีสิทธิ์
                    // อนุมัติ/เซ็น (เลขจริงออกตอนอนุมัติ — gap-free §86/4).
                    // fail-open เมื่อ permission service ไม่มี/createdBy ไม่ใช่ user
                    // (integration/system) = พฤติกรรมเดิม
                    var recorderCanApprove = true;
                    if (_permissionService != null && Guid.TryParse(createdBy, out var recorderUid))
                        recorderCanApprove = await Accounting.Helpers.DocumentPermissionHelper
                            .CanApproveAsync(_permissionService, companyId, recorderUid, DocumentType.Receipt);
                    // (B) ใบแจ้งหนี้ (VAT undue model) รับครบงวดเดียว → ใบเสร็จนี้คือ
                    // "ใบกำกับภาษี" ที่กฎหมายบังคับออก ณ วันรับเงิน (§78/1) → ถือ
                    // VAT/บรรทัดจากใบแจ้งหนี้ (หัวพิมพ์ "ใบกำกับภาษี/ใบเสร็จรับเงิน")
                    // — เหมือนผล convert ใบแจ้งหนี้→ใบเสร็จทุกประการ
                    // กติกาเดียวกับเส้นออกใบย้อนหลัง (Helpers/SettlementReceiptPolicy)
                    // — ห้ามเขียนเงื่อนไขซ้ำสองที่ ไม่งั้นใบเดียวกันถือ VAT หรือไม่ถือ
                    // ขึ้นกับว่าผู้ใช้กดปุ่มไหน
                    var carryVat = Accounting.Helpers.SettlementReceiptPolicy
                        .CarriesTaxInvoiceRole(doc.DocumentType, doc.VatAmount, singleShotFull);
                    var receiptDoc = await CreateSettlementReceiptAsync(companyId, doc, payment, createdBy, recorderCanApprove, carryVat);
                    payment.ReceiptDocumentId = receiptDoc.Id;
                    await _db.SaveChangesAsync();
                    issuedSettlementReceipt = receiptDoc;
                }
                catch (Exception ex)
                {
                    _logger.LogWarning(ex, "ออกใบเสร็จรับเงินหลักฐานไม่สำเร็จ (payment {PaymentNumber}) — ข้ามไปก่อน", payment.PaymentNumber);
                }
            }

            // Sync BankAccount.CurrentBalance — convert from doc currency to THB
            // at the document's captured FX rate (BankAccount.CurrentBalance is
            // always THB in this iteration). Same conversion as the GL posting.
            if (payment.BankAccountId.HasValue)
            {
                var isInflow = await IsCashInflowDocAsync(companyId, doc);
                var bankFx = payment.ExchangeRate ?? doc.ExchangeRate;
                var thbAmount = bankFx == 1m
                    ? payment.Amount
                    : Math.Round(payment.Amount * bankFx, 2, MidpointRounding.AwayFromZero);
                var delta = isInflow ? thbAmount : -thbAmount;
                await _db.BankAccounts
                    .Where(b => b.Id == payment.BankAccountId.Value && b.CompanyId == companyId)
                    .ExecuteUpdateAsync(s => s.SetProperty(b => b.CurrentBalance, b => b.CurrentBalance + delta));
            }

            // Auto-generate WHT cert for purchase documents with WHT on first payment
            if (doc.WithholdingTaxAmount > 0
                && (doc.DocumentType == DocumentType.PurchaseInvoice
                    || doc.DocumentType == DocumentType.Expense
                    || doc.DocumentType == DocumentType.PaymentVoucher
                    || doc.DocumentType == DocumentType.CertificateInLieu))
            {
                try
                {
                    // ส่งวันจ่ายจริง (audit F13): ภ.ง.ด.3/53 เป็น cash basis — cert
                    // ต้องลงเดือนที่จ่าย ไม่ใช่เดือนวันที่เอกสารตั้งหนี้.
                    // ส่ง paymentId + ยอด WHT ของ "งวดนี้" ด้วย (คำนวณ pro-rata ไว้
                    // แล้วที่ payment.WithholdingTaxAmount) — เดิมออกใบด้วยยอดเต็ม
                    // ทั้งเอกสารตั้งแต่งวดแรก แล้ว guard กันซ้ำทำให้งวดถัดไปไม่ออกอีก
                    // → นำส่งเกินในเดือนแรกและขาดในเดือนที่จ่ายส่วนที่เหลือ
                    // รอบ 170: ออกเป็น Issued ทันที (ไม่ใช่ Draft) — ดูหมายเหตุที่ hook ตอน approve
                    await _whtService.AutoGenerateFromDocumentAsync(
                        companyId, doc.Id, autoIssue: true, createdBy, payment.PaymentDate,
                        sourcePaymentId: payment.Id,
                        paymentWhtAmount: payment.WithholdingTaxAmount > 0
                            ? payment.WithholdingTaxAmount : null);
                }
                catch (Exception ex)
                {
                    // Cert may already exist or other non-critical error — don't fail payment
                    _logger.LogWarning(ex, "Auto-gen 50 ทวิ จากการชำระ {Doc} ไม่สำเร็จ (ไม่ block การชำระ)", doc.DocumentNumber);
                }
            }

            // tax point §78/1: รับชำระใบแจ้งหนี้บริการ (modal ชำระเงิน) → VAT ที่พัก
            // 21913 ถึงกำหนด → reclass Dr 21913 / Cr 21911 + stamp เข้า ภ.พ.30
            // งวดที่รับเงิน (GL-driven; no-op สำหรับใบเก่า/ใบสินค้า/reclass แล้ว)
            if (doc.DocumentType == DocumentType.Invoice)
                await TryReclassifyUndueOutputVatAsync(companyId, doc.Id, payment.PaymentDate, createdBy);

            await transaction.CommitAsync();

            // ★ รอบ 193 ฝ่ายค้าน C-3 — ใบเสร็จที่เป็นใบกำกับ ณ วันรับเงิน (§78/1) ได้ e-Tax อัตโนมัติเหมือนเส้นอนุมัติ
            // (hook ไม่ throw · ใบเสร็จเปล่า/ร่าง = ข้ามในตัว hook)
            if (issuedSettlementReceipt != null)
                await _issuedHooks.RunAsync(companyId, issuedSettlementReceipt);

            try
            {
                await _lineNotify.NotifyPaymentReceivedAsync(companyId, doc.DocumentNumber, payment.Amount);
            }
            catch { /* best-effort notification */ }

            // Webhooks — payment.received (always) + document.paid
            // (when BalanceDue is now zero). Both fire outside the
            // commit so partners get a settled view + a slow webhook
            // delivery never blocks the API return.
            await FireWebhookAsync(companyId, "payment.received", new
            {
                paymentId = payment.Id,
                paymentNumber = payment.PaymentNumber,
                documentId = payment.DocumentId,
                documentNumber = doc.DocumentNumber,
                amount = payment.Amount,
                method = payment.PaymentMethod.ToString(),
                paymentDate = payment.PaymentDate,
            });
            if (doc.BalanceDue <= 0.01m)
            {
                await FireWebhookAsync(companyId, "document.paid", new
                {
                    documentId = doc.Id,
                    documentNumber = doc.DocumentNumber,
                    documentType = doc.DocumentType.ToString(),
                    totalAmount = doc.TotalAmount,
                    paidAt = DateTime.UtcNow,
                });
            }

            return new PaymentResponse(
                payment.Id, payment.PaymentNumber, payment.DocumentId,
                payment.PaymentDate, payment.Amount, payment.PaymentMethod,
                payment.Reference, payment.BankAccount, payment.BankAccountId,
                payment.Notes, payment.CreatedAt,
                HasPayerSignature: !string.IsNullOrWhiteSpace(payment.PayerSignatureBase64),
                PayerSignatureName: payment.PayerSignatureName);
        }
        catch
        {
            await transaction.RollbackAsync();
            throw;
        }
        }); // end ExecutionStrategy
    }

    /// <summary>Multi-document payment — one Payment row settles many
    /// Documents pro-rata to caller-specified AllocatedAmount per row.
    /// Each allocation triggers the same per-doc settlement (PaidAmount
    /// roll, status flip, WHT slice, per-doc JE) the legacy
    /// single-doc path uses, so existing accounting invariants stay
    /// intact. Bank balance is updated ONCE at the total.
    ///
    /// Validation:
    ///   • Every allocation amount must be ≤ that doc's BalanceDue
    ///   • SUM(allocations) ≤ Amount; the remainder is reported as
    ///     UnappliedCredit (operator can attach later via PUT)
    ///   • All target docs must be Approved / PartiallyPaid / Sent
    ///   • Documents must share the same Contact (mixing customers in
    ///     one cheque is almost always a data-entry error)
    ///   • Multiple bank accounts across docs are tolerated — the bank
    ///     balance hits the OverrideBankAccountId or the FIRST doc's
    ///     BankAccountId in that order.
    /// </summary>
    public async Task<PaymentResponse> CreateMultiDocPaymentAsync(Guid companyId, CreatePaymentRequest request, string createdBy)
    {
        if (request.Allocations == null || request.Allocations.Count == 0)
            throw new InvalidOperationException("Allocations ต้องมีอย่างน้อย 1 รายการ");
        // รอบ 193: บรรทัดปรับส่วนต่างผูกกับ "หนี้ใบเดียว" — ห้ามหายเงียบเมื่อส่งมากับการชำระหลายใบ (ห้าม silent no-op)
        if (request.SettlementAdjustments is { Count: > 0 })
            throw new Accounting.Helpers.BusinessRuleException(
                "บรรทัดปรับส่วนต่างยอดชำระใช้ได้กับการชำระเอกสารทีละใบ — แยกบันทึกการชำระใบที่มีคูปอง/ค่าส่งออกมา",
                Accounting.Helpers.PaymentSettlementAdjustment.RuleCode);
        if (request.Amount <= 0)
            throw new InvalidOperationException("จำนวนเงินชำระต้องมากกว่า 0");
        if (request.ExchangeRate is <= 0)
            throw new InvalidOperationException("อัตราแลกเปลี่ยน ณ วันชำระต้องมากกว่า 0");
        if (request.PaymentDate > DateTime.UtcNow.Date.AddDays(1))
            throw new InvalidOperationException("วันที่ชำระเงินต้องไม่เป็นวันที่ในอนาคต");

        var allocSum = request.Allocations.Sum(a => a.AllocatedAmount);
        if (request.Allocations.Any(a => a.AllocatedAmount <= 0))
            throw new InvalidOperationException("AllocatedAmount ของทุกแถวต้องมากกว่า 0");
        if (allocSum > request.Amount + 0.01m)
            throw new InvalidOperationException(
                $"รวม allocation ({allocSum:N2}) เกินจำนวนเงินชำระ ({request.Amount:N2})");

        var docIds = request.Allocations.Select(a => a.DocumentId).Distinct().ToList();
        if (docIds.Count != request.Allocations.Count)
            throw new InvalidOperationException("แต่ละ Document จัดสรรได้แค่ครั้งเดียวต่อ payment");

        var strategy = _db.Database.CreateExecutionStrategy();
        return await strategy.ExecuteAsync(async () =>
        {
            // ⚠️ เปิด transaction ก่อน FOR UPDATE — lock ต้องอยู่ใน tx ถึงจะถือไว้จน
            // จบ (เดิมเปิด tx ทีหลัง → lock ปล่อยทันที → ชำระพร้อมกันตัด AR ซ้ำ).
            await using var transaction = await _db.Database.BeginTransactionAsync();
            // Lock all target docs in one go — sort by Id to avoid deadlock
            // when two concurrent multi-doc payments overlap on the same
            // docs in different orders.
            var docs = await _db.Documents
                .FromSqlRaw("SELECT * FROM \"Documents\" WHERE \"Id\" = ANY({0}) AND \"CompanyId\" = {1} ORDER BY \"Id\" FOR UPDATE",
                    docIds.ToArray(), companyId)
                .ToListAsync();
            if (docs.Count != docIds.Count)
                throw new KeyNotFoundException("ไม่พบเอกสารบางรายการ");

            var contacts = docs.Select(d => d.ContactId).Distinct().ToList();
            if (contacts.Count > 1)
                throw new InvalidOperationException(
                    "เอกสารทั้งหมดในการชำระครั้งเดียวต้องเป็นของลูกค้า/ผู้ขายรายเดียวกัน");

            var docMap = docs.ToDictionary(d => d.Id);
            foreach (var alloc in request.Allocations)
            {
                var d = docMap[alloc.DocumentId];
                if (d.Status != DocumentStatus.Approved && d.Status != DocumentStatus.PartiallyPaid && d.Status != DocumentStatus.Sent && d.Status != DocumentStatus.Overdue)
                    throw new InvalidOperationException(
                        $"เอกสาร {d.DocumentNumber} สถานะ {d.Status} ไม่สามารถชำระได้");
                if (!PayableDocumentTypes.Contains(d.DocumentType))
                    throw new InvalidOperationException(
                        $"เอกสาร {d.DocumentNumber} ({d.DocumentType}) รับ/จ่ายชำระตรง ๆ ไม่ได้ — " +
                        "แปลงเป็นใบแจ้งหนี้/ใบกำกับก่อน หรือชำระที่เอกสารตั้งหนี้ต้นทาง");
                if (alloc.AllocatedAmount > d.BalanceDue + 0.01m)
                    throw new InvalidOperationException(
                        $"จัดสรร {alloc.AllocatedAmount:N2} ของ {d.DocumentNumber} เกินยอดค้าง ({d.BalanceDue:N2})");
            }

            // (transaction เปิดไว้ก่อน FOR UPDATE ด้านบนแล้ว)
            try
            {
                // ===== Create the parent Payment =====
                var payYearMonth = DateTime.UtcNow.ToString("yyyyMM");
                var payPrefix = $"PAY-{payYearMonth}-";
                var maxPayNum = await _db.Payments
                    .IgnoreQueryFilters()
                    .Where(p => p.CompanyId == companyId && p.PaymentNumber.StartsWith(payPrefix))
                    .Select(p => p.PaymentNumber)
                    .MaxAsync() as string;
                var paySeq = 1;
                if (maxPayNum != null && int.TryParse(maxPayNum.Substring(payPrefix.Length), out var parsed))
                    paySeq = parsed + 1;

                var firstDoc = docMap[request.Allocations[0].DocumentId];
                var payment = new Payment
                {
                    CompanyId = companyId,
                    PaymentNumber = $"{payPrefix}{paySeq:D4}",
                    // Primary DocumentId = first allocation's doc (back-compat).
                    DocumentId = firstDoc.Id,
                    PaymentDate = request.PaymentDate,
                    Amount = request.Amount,
                    PaymentMethod = request.PaymentMethod,
                    Reference = request.Reference,
                    BankAccount = request.BankAccount,
                    BankAccountId = request.OverrideBankAccountId ?? firstDoc.BankAccountId,
                    OverrideBankAccountId = request.OverrideBankAccountId,
                    WithholdingTaxAmount = 0,  // accumulated below from allocations
                    ProjectId = request.ProjectId,
                    Notes = request.Notes,
                    PayerSignatureBase64 = TrimSignature(request.PayerSignatureBase64),
                    PayerSignatureName = request.PayerSignatureName,
                    ExchangeRate = request.ExchangeRate,
                    CreatedBy = createdBy,
                };
                _db.Payments.Add(payment);
                await _db.SaveChangesAsync();

                // ===== Per-doc settlement + WHT split + JE =====
                decimal totalWht = 0;
                decimal thbCashMoved = 0;   // เงินสด THB ที่ลง GL จริง (รวม FX แปลงแล้ว)
                var allocIndex = 0;
                // ยอด WHT ที่หักจริง "ต่อเอกสาร" ในการโอนครั้งนี้ — ใช้ออก 50 ทวิ
                // รายงวดหลัง commit (ก่อนหน้านี้เส้น multi-doc ออกใบด้วยยอดเต็ม
                // ทั้งเอกสารตั้งแต่งวดแรก → นำส่งเกินเดือนแรก/ขาดเดือนหลัง)
                var whtByDoc = new Dictionary<Guid, decimal>();
                foreach (var alloc in request.Allocations)
                {
                    allocIndex++;
                    var d = docMap[alloc.DocumentId];

                    // WHT slice — explicit override per allocation OR
                    // proportional to AllocatedAmount / d.TotalAmount.
                    decimal whtSlice = 0;
                    if (d.WithholdingTaxAmount > 0)
                    {
                        if (alloc.WithholdingTaxAmount.HasValue)
                        {
                            whtSlice = Math.Round(alloc.WithholdingTaxAmount.Value, 2, MidpointRounding.AwayFromZero);
                        }
                        else
                        {
                            var alreadyWht = await _db.Payments.AsNoTracking()
                                .Where(p => p.DocumentId == d.Id && !p.IsDeleted && p.Id != payment.Id)
                                .SumAsync(p => (decimal?)p.WithholdingTaxAmount) ?? 0m;
                            var remainingCap = Math.Max(0m, d.WithholdingTaxAmount - alreadyWht);
                            var isFinal = alloc.AllocatedAmount + 0.01m >= d.BalanceDue;
                            whtSlice = isFinal
                                ? remainingCap
                                : Math.Min(remainingCap,
                                    d.TotalAmount > 0
                                        ? Math.Round(alloc.AllocatedAmount * d.WithholdingTaxAmount / d.TotalAmount,
                                            2, MidpointRounding.AwayFromZero)
                                        : 0);
                        }
                    }

                    _db.PaymentAllocations.Add(new PaymentAllocation
                    {
                        CompanyId = companyId,
                        PaymentId = payment.Id,
                        DocumentId = d.Id,
                        AllocatedAmount = alloc.AllocatedAmount,
                        WithholdingTaxAmount = whtSlice,
                        Note = alloc.Note,
                        CreatedBy = createdBy,
                    });
                    totalWht += whtSlice;
                    whtByDoc[d.Id] = whtByDoc.GetValueOrDefault(d.Id) + whtSlice;

                    // Settle the document
                    d.PaidAmount += alloc.AllocatedAmount;
                    var allocSettle = Accounting.Helpers.DocumentSettlementState.Apply(
                        d.TotalAmount, d.PaidAmount, d.Status);
                    d.BalanceDue = allocSettle.BalanceDue;
                    d.Status = allocSettle.Status;
                    if (d.Status == DocumentStatus.Paid)
                    {
                        d.AgingDays = null;
                        d.AgingLastEvaluatedAt = DateTime.UtcNow;
                    }

                    // Per-doc journal — synthesize a non-tracked Payment
                    // scoped to this allocation row. CreatePaymentJournalAsync
                    // reads only Amount / WithholdingTaxAmount / PaymentNumber
                    // / PaymentDate / ProjectId off the param; never
                    // touches Id and never adds to DbContext. Allocation-
                    // specific PaymentNumber tag lets the JE Reference
                    // distinguish multiple JEs from the same parent payment.
                    var virtualPayment = new Payment
                    {
                        CompanyId = companyId,
                        PaymentNumber = $"{payment.PaymentNumber}/{allocIndex}",
                        DocumentId = d.Id,
                        PaymentDate = payment.PaymentDate,
                        Amount = alloc.AllocatedAmount,
                        PaymentMethod = payment.PaymentMethod,
                        Reference = payment.Reference,
                        BankAccount = payment.BankAccount,
                        BankAccountId = payment.BankAccountId,
                        OverrideBankAccountId = payment.OverrideBankAccountId,
                        WithholdingTaxAmount = whtSlice,
                        ProjectId = payment.ProjectId,
                        Notes = payment.Notes,
                        ExchangeRate = request.ExchangeRate,
                        CreatedBy = createdBy,
                    };
                    await CreatePaymentJournalAsync(companyId, d, virtualPayment, createdBy);
                    // สะสมเงินสด THB ที่ลง GL จริง (แปลงตาม rate ของแต่ละเอกสาร
                    // — สอดคล้องกับ CreatePaymentJournalAsync ที่แปลงต่อเอกสาร)
                    var allocFx = request.ExchangeRate ?? d.ExchangeRate;
                    thbCashMoved += allocFx == 1m
                        ? alloc.AllocatedAmount
                        : Math.Round(alloc.AllocatedAmount * allocFx, 2, MidpointRounding.AwayFromZero);
                }

                payment.WithholdingTaxAmount = totalWht;
                await _db.SaveChangesAsync();

                // ===== เงินส่วนเกินที่ยังไม่จัดสรร (UnappliedCredit) — ต้องลง GL =====
                // เงินเข้าธนาคารจริงเต็ม request.Amount แต่ JE รายเอกสารลงแค่ allocSum
                // ถ้าไม่ book ส่วนต่าง GL เงินสดจะน้อยกว่ายอดธนาคารถาวร:
                //   ฝั่งรับ → Dr เงินสด/ธนาคาร  Cr เงินรับล่วงหน้าจากลูกค้า (217xx)
                //   ฝั่งจ่าย → Dr เงินจ่ายล่วงหน้า (114xx)  Cr เงินสด/ธนาคาร
                var isInflowDoc = await IsCashInflowDocAsync(companyId, firstDoc);
                var unapplied = request.Amount - allocSum;
                if (unapplied > 0.005m)
                {
                    var unappliedFx = request.ExchangeRate ?? firstDoc.ExchangeRate;
                    var thbUnapplied = unappliedFx == 1m
                        ? unapplied
                        : Math.Round(unapplied * unappliedFx, 2, MidpointRounding.AwayFromZero);
                    var cashAcc = await ResolvePaymentCashAccountAsync(companyId, payment);
                    var suspenseAcc = isInflowDoc
                        ? (await FindAccountAsync(companyId, "21710") ?? await FindAccountAsync(companyId, "217"))
                        : (await FindAccountAsync(companyId, "11470") ?? await FindAccountAsync(companyId, "114"));
                    if (cashAcc != null && suspenseAcc != null)
                    {
                        var upPeriod = await RequireOpenFiscalPeriodAsync(companyId, payment.PaymentDate, "รายการรับ-จ่ายเงิน");
                        var upNumber = await GetNextJournalEntryNumberAsync(companyId, isInflowDoc ? "RV" : "PV");
                        var upJe = new JournalEntry
                        {
                            CompanyId = companyId,
                            EntryNumber = upNumber,
                            EntryDate = payment.PaymentDate,
                            JournalType = isInflowDoc ? JournalType.CashReceipts : JournalType.CashPayments,
                            Description = $"เงินส่วนเกินยังไม่จัดสรร - {payment.PaymentNumber}",
                            Reference = payment.PaymentNumber,
                            Status = JournalEntryStatus.Posted,
                            TotalDebit = thbUnapplied,
                            TotalCredit = thbUnapplied,
                            CreatedBy = createdBy,
                            IsAutoGenerated = true,
                            FiscalPeriodId = upPeriod?.Id,
                        };
                        _db.JournalEntries.Add(upJe);
                        _db.JournalEntryLines.Add(new JournalEntryLine
                        {
                            JournalEntryId = upJe.Id,
                            AccountId = isInflowDoc ? cashAcc.Id : suspenseAcc.Id,
                            DebitAmount = thbUnapplied, CreditAmount = 0,
                            Description = isInflowDoc ? "เงินรับส่วนเกิน (รอจัดสรร)" : "เงินจ่ายล่วงหน้า (รอจัดสรร)",
                            LineOrder = 1,
                        });
                        _db.JournalEntryLines.Add(new JournalEntryLine
                        {
                            JournalEntryId = upJe.Id,
                            AccountId = isInflowDoc ? suspenseAcc.Id : cashAcc.Id,
                            DebitAmount = 0, CreditAmount = thbUnapplied,
                            Description = isInflowDoc ? "เงินรับล่วงหน้าจากลูกค้า" : "จ่ายผ่านธนาคาร (ส่วนเกิน)",
                            LineOrder = 2,
                        });
                        await _db.SaveChangesAsync();
                    }
                    else
                    {
                        _logger.LogWarning(
                            "Multi-doc payment {PayNo}: unapplied {Amt:N2} ไม่ถูก book GL (ไม่พบผัง 217xx/114xx) — GL เงินสดจะต่างจากยอดธนาคาร",
                            payment.PaymentNumber, thbUnapplied);
                    }
                    thbCashMoved += thbUnapplied;
                }

                // ===== Bank-balance sync (once at total) =====
                // ใช้ยอด THB ที่แปลง FX แล้ว (เดิมใช้ request.Amount ดิบ — เอกสาร
                // สกุลต่างประเทศทำยอดธนาคาร THB เพี้ยนเท่าส่วนต่างอัตราแลกเปลี่ยน)
                if (payment.BankAccountId.HasValue)
                {
                    var delta = isInflowDoc ? thbCashMoved : -thbCashMoved;
                    await _db.BankAccounts
                        .Where(b => b.Id == payment.BankAccountId.Value && b.CompanyId == companyId)
                        .ExecuteUpdateAsync(s => s.SetProperty(b => b.CurrentBalance, b => b.CurrentBalance + delta));
                }

                await transaction.CommitAsync();

                // ── side-effect หลังชำระ ที่เส้น single-doc มีแต่เส้นนี้เคยขาด (M-3) ──
                // multi-doc เขียนทีหลังโดยลอกเฉพาะแกน "settle + JE" ⇒ ปิดใบ
                // ด้วยการโอนก้อนเดียวแล้ว VAT ที่พัก 21913 ไม่ถูกย้ายไป 21911
                // ⇒ ใบหายจาก ภ.พ.30 ถาวร (นำส่งภาษีขายขาด) และฝั่งซื้อไม่มี
                // 50 ทวิ ออกเลย. ทำนอก transaction (commit แล้ว) แบบ best-effort
                // ทีละใบ — ล้มใบใดใบหนึ่งต้องไม่ทำให้การรับเงินที่สำเร็จแล้วพัง
                foreach (var allocDocId in docMap.Keys)
                {
                    try
                    {
                        await TryReclassifyUndueOutputVatAsync(
                            companyId, allocDocId, payment.PaymentDate, createdBy);
                        await SyncWhtCreditReceivedAsync(companyId, docMap[allocDocId]);
                        // 50 ทวิ ของ "งวดนี้ ใบนี้" — ผูก payment id + ยอดที่หักจริง
                        // ของใบนั้น เหมือนเส้น single-doc (ท.ป.4/2528 cash basis)
                        // เฉพาะฝั่งซื้อ — ฝั่งขายเราเป็น "ผู้ถูกหัก" ลูกค้าเป็นคนออกใบให้
                        // (เส้น single-doc กรองชนิดเอกสารอยู่แล้ว เส้นนี้เคยไม่กรอง)
                        var allocType = docMap[allocDocId].DocumentType;
                        if (_whtService != null && whtByDoc.GetValueOrDefault(allocDocId) > 0.005m
                            && allocType is DocumentType.PurchaseInvoice or DocumentType.Expense
                                or DocumentType.PaymentVoucher or DocumentType.CertificateInLieu)
                            await _whtService.AutoGenerateFromDocumentAsync(
                                companyId, allocDocId, autoIssue: true, createdBy, payment.PaymentDate,
                                sourcePaymentId: payment.Id,
                                paymentWhtAmount: whtByDoc[allocDocId]);
                    }
                    catch (Exception ex)
                    {
                        _logger.LogWarning(ex,
                            "side-effect หลังรับ/จ่ายชำระหลายใบ (เอกสาร {DocId}) ไม่สำเร็จ — " +
                            "ตรวจ tax point / 50 ทวิ / เครดิต WHT ของใบนี้ด้วยมือ", allocDocId);
                    }
                }

                // Re-load PaymentAllocation rows to pick up generated Ids,
                // then enrich with the docMap (resolved client-side).
                var rawAllocs = await _db.PaymentAllocations
                    .Where(pa => pa.PaymentId == payment.Id && !pa.IsDeleted)
                    .Select(pa => new { pa.Id, pa.PaymentId, pa.DocumentId,
                        pa.AllocatedAmount, pa.WithholdingTaxAmount, pa.Note })
                    .ToListAsync();
                var persistedAllocs = rawAllocs.Select(pa => new PaymentAllocationResponse(
                    pa.Id, pa.PaymentId, pa.DocumentId,
                    docMap[pa.DocumentId].DocumentNumber,
                    docMap[pa.DocumentId].DocumentType,
                    pa.AllocatedAmount, pa.WithholdingTaxAmount, pa.Note)).ToList();

                return new PaymentResponse(
                    payment.Id, payment.PaymentNumber, payment.DocumentId,
                    payment.PaymentDate, payment.Amount, payment.PaymentMethod,
                    payment.Reference, payment.BankAccount, payment.BankAccountId,
                    payment.Notes, payment.CreatedAt,
                    persistedAllocs, request.Amount - allocSum,
                    HasPayerSignature: !string.IsNullOrWhiteSpace(payment.PayerSignatureBase64),
                    PayerSignatureName: payment.PayerSignatureName);
            }
            catch
            {
                await transaction.RollbackAsync();
                throw;
            }
        });
    }

    public async Task<List<PaymentResponse>> GetPaymentsAsync(Guid companyId, Guid? documentId = null)
    {
        var query = _db.Payments.Where(p => p.CompanyId == companyId);
        if (documentId.HasValue) query = query.Where(p => p.DocumentId == documentId.Value);

        var payments = await query.OrderByDescending(p => p.PaymentDate).ToListAsync();

        // ใบเสร็จ (REC) ที่ออกคู่กับแต่ละการรับชำระ — batch เดียว ไม่ใช่ N+1.
        // ค้น **สองทาง** (FK บน payment · SettlementPaymentId บนใบเสร็จ) เพราะแถว
        // เก่าบางแถวมีใบอยู่จริงแต่ FK ว่าง ⇒ ถ้าดูทางเดียวจะโชว์ปุ่ม "ออกใบเสร็จ"
        // ให้ใบที่มีอยู่แล้ว = ชวนให้ผู้ใช้ออกใบซ้ำ
        var payIds = payments.Select(p => p.Id).ToList();
        var receiptFkIds = payments.Where(p => p.ReceiptDocumentId.HasValue)
            .Select(p => p.ReceiptDocumentId!.Value).ToList();
        // ⚠️ ห้ามใช้ ternary คร่อมสองสาขาที่เป็น tuple — ถ้า**ชื่อสมาชิกไม่ตรงกัน**
        // ทุกตัว C# จะหา common type แล้ว **ทิ้งชื่อที่ไม่ตรง** ⇒ `(Guid Id, string,
        // Guid?)` แล้วฟ้อง CS1061 ที่จุดที่เรียกชื่อนั้นทีหลัง (เจอจริง build ฝั่งผู้ใช้)
        // → ประกาศชนิดไว้ตรง ๆ แล้วเติมทีหลัง ชัดเจนกว่าและไม่มีทางเพี้ยน
        var receiptByPayment = new Dictionary<Guid, (Guid Id, string Number)>();
        var receiptById = new Dictionary<Guid, string>();
        if (payIds.Count > 0)
        {
            var receiptDocs = await _db.Documents.AsNoTracking()
                .Where(r => r.CompanyId == companyId && !r.IsDeleted
                    && r.Status != DocumentStatus.Voided && r.Status != DocumentStatus.Rejected
                    && ((r.SettlementPaymentId != null && payIds.Contains(r.SettlementPaymentId.Value))
                        || receiptFkIds.Contains(r.Id)))
                .Select(r => new { r.Id, r.DocumentNumber, r.SettlementPaymentId })
                .ToListAsync();
            foreach (var r in receiptDocs)
            {
                receiptById[r.Id] = r.DocumentNumber;
                if (r.SettlementPaymentId.HasValue)
                    receiptByPayment.TryAdd(r.SettlementPaymentId.Value, (r.Id, r.DocumentNumber));
            }
        }

        // ใบต้นทางทำหน้าที่ "ใบกำกับภาษี/ใบเสร็จรับเงิน" ของการรับเงินแถวนี้อยู่แล้ว
        // ไหม — ถ้าใช่ หน้าจอต้อง**ไม่**เสนอปุ่ม "ออกใบเสร็จ" (ผู้ใช้รายงาน
        // 2026-09-11: ปุ่มโผล่บนใบที่หัวเป็นใบเสร็จอยู่แล้ว ⇒ ชวนออกใบรับซ้ำ).
        // คำนวณที่เซิร์ฟเวอร์ด้วยตัวตัดสินตัวเดียวกับหัวกระดาษ — ห้ามให้ JS เดาเอง
        // (defect class "สำเนามือฝั่ง JS ที่ตามหลังอยู่ไม่กี่ธง")
        var srcDocIds = payments.Select(p => p.DocumentId).Distinct().ToList();
        var srcDocs = srcDocIds.Count == 0
            ? new List<Document>()
            : await _db.Documents.AsNoTracking()
                .Where(d => d.CompanyId == companyId && srcDocIds.Contains(d.Id))
                .ToListAsync();
        var srcWithReceipt = await LoadDocIdsWithSeparateReceiptAsync(_db, companyId, srcDocIds);
        var srcSettled = await LoadSettlementDatesAsync(_db, companyId, srcDocIds);
        var srcMode = await GetReceiptIssueModeAsync(companyId);
        var servedByDoc = new Dictionary<Guid, (bool Served, DateTime DocDate)>();
        foreach (var d in srcDocs)
            servedByDoc[d.Id] = (
                ComputeServedAsReceipt(d, srcWithReceipt.Contains(d.Id), srcMode,
                    srcSettled.TryGetValue(d.Id, out var srcPaidOn) ? srcPaidOn : null),
                d.DocumentDate);

        // การชำระ "รายการนี้" ถูกคุมด้วยหัวใบต้นทางไหม — ต้องเทียบวันที่ของรายการ
        // ด้วย เพราะใบที่ผ่อนหลายงวดแล้วงวดสุดท้ายตรงวันที่ใบ ยังต้องออกใบเสร็จให้
        // งวดก่อนหน้าที่รับเงินคนละวัน
        bool ServedFor(Payment p) => servedByDoc.TryGetValue(p.DocumentId, out var sv)
            && Accounting.Helpers.ReceiptIssuePolicy.CoversPayment(sv.Served, sv.DocDate, p.PaymentDate);

        (Guid? Id, string? Number) ReceiptOf(Payment p)
        {
            if (receiptByPayment.TryGetValue(p.Id, out var byPay)) return (byPay.Id, byPay.Number);
            if (p.ReceiptDocumentId.HasValue && receiptById.TryGetValue(p.ReceiptDocumentId.Value, out var num))
                return (p.ReceiptDocumentId, num);
            return (null, null);
        }

        var rows = payments.Select(p =>
        {
            var rec = ReceiptOf(p);   // คำนวณครั้งเดียวต่อแถว
            return new PaymentResponse(
                p.Id, p.PaymentNumber, p.DocumentId,
                p.PaymentDate, p.Amount, p.PaymentMethod,
                p.Reference, p.BankAccount, p.BankAccountId,
                p.Notes, p.CreatedAt,
                HasPayerSignature: !string.IsNullOrWhiteSpace(p.PayerSignatureBase64),
                PayerSignatureName: p.PayerSignatureName,
                ReceiptDocumentId: rec.Id,
                ReceiptDocumentNumber: rec.Number,
                SourceServesAsReceipt: ServedFor(p),
                SettlementAdjustmentAmount: p.SettlementAdjustmentAmount,
                SettlementAdjustmentsJson: p.SettlementAdjustmentsJson);
        }).ToList();

        // ── รวมเอกสาร settle จากเส้น "แปลงเอกสาร" (ไม่มี Payment row) ──
        // หลัก: สองเส้นทางชำระ (แปลง vs บันทึกชำระ) ต้องเห็นประวัติเหมือนกัน.
        // ใบ IsSettlementReceipt ข้าม — เกิดคู่ Payment row อยู่แล้ว (modal/
        // integration) กันแถวซ้ำ. read-only projection ไม่กระทบยอด/GL ใด ๆ.
        var settleTypes = new[] { DocumentType.Receipt, DocumentType.ReceiptVoucher,
            DocumentType.PaymentVoucher, DocumentType.CertificateInLieu };
        var settleDocsQ = _db.Documents.AsNoTracking()
            .Where(d => d.CompanyId == companyId
                && d.RelatedDocumentId != null
                && settleTypes.Contains(d.DocumentType)
                && !d.IsSettlementReceipt
                && !d.IsDeleted
                && d.Status != DocumentStatus.Voided
                && d.Status != DocumentStatus.Draft
                && d.Status != DocumentStatus.Rejected
                && d.Status != DocumentStatus.WaitingApproval);
        if (documentId.HasValue)
            settleDocsQ = settleDocsQ.Where(d => d.RelatedDocumentId == documentId.Value);
        var settleDocs = await settleDocsQ.ToListAsync();
        rows.AddRange(settleDocs.Select(d => new PaymentResponse(
            d.Id, d.DocumentNumber, d.RelatedDocumentId!.Value,
            d.DocumentDate, d.TotalAmount, PaymentMethod.Other,
            "ชำระผ่านการแปลงเอกสาร", null, d.BankAccountId,
            d.Notes, d.CreatedAt,
            Source: "document")));

        return rows.OrderByDescending(r => r.PaymentDate).ToList();
    }

    // ==================== Private ====================

    /// <summary>
    /// ค้นหาบัญชีจากรหัส — exact match ก่อน แล้ว prefix match (level 4)
    /// เช่น "113" จะ match "11310" (ลูกหนี้การค้า).
    /// When contactOverride is set the contact's per-contact GL pin
    /// wins (e.g. ลูกหนี้พนักงาน vs ลูกหนี้การค้า depending on contact).
    /// codePrefix selects which override applies: "113" → AR, "212"
    /// → AP, "212305" → IR/GR clearing.
    /// </summary>
    /// <summary>Resolve the WHT-payable account by the counterparty's entity
    /// type, so the withheld tax lands in the right ภ.ง.ด. liability for the
    /// half-yearly reconciliation:
    ///   Individual (บุคคลธรรมดา)      → 21916 (ภ.ง.ด.3)
    ///   JuristicPerson (นิติบุคคล)    → 21917 (ภ.ง.ด.53)
    /// Falls back to whichever account exists when the preferred one is
    /// missing (so a half-configured chart still posts).</summary>
    private async Task<ChartOfAccount?> ResolveWhtPayableAccountAsync(Guid companyId, Contact? contact,
        bool isForeignService = false)
    {
        // จ่ายต่างประเทศ (ม.70) → หนี้ WHT เข้า 21918 (ภ.ง.ด.54) — คนละแบบ/คนละ
        // กำหนดยื่นกับ ภงด.3/53. เดิมไม่มีทางเลือกนี้เลย: WHT ของ PV ต่างประเทศ
        // ตกไป 21916/17 → หน้านำส่งนับปนใน ภงด.3/53 (ยื่นผิดแบบ) ขณะที่ 21918
        // ว่างตลอด. ตัดสินจาก doc.IsForeignService (ผู้ใช้ติ๊กเอง — ชัดกว่าเดา
        // จาก CountryCode ของ contact ที่มักไม่ได้กรอก)
        // ⚠️ ต้องใช้ตัวตัดสินตัวเดียวกับทะเบียน 50 ทวิ / รายงาน / หน้านำส่ง —
        // เดิมที่นี่ดู `IsForeignService` อย่างเดียว (พลาดเคส ม.70 ที่กรอก
        // CountryCode แต่ไม่ได้ติ๊ก §83/6 เช่นค่าสิทธิ/ดอกเบี้ย) และแยก 3/53 ด้วย
        // `ContactType` **ดิบ ๆ** ซึ่ง default = Individual และมี 4 ทางเข้าที่ไม่เคย
        // ตั้งค่า (API v1 · import · OCR) ⇒ "บริษัท ก จำกัด" ที่เลขภาษีขึ้นต้น 0
        // ตั้งหนี้ที่ **21916** แต่ทุกจอจัดเป็น ภ.ง.ด.53 ⇒ ตอนกดนำส่งจะ Dr **21917
        // ที่ไม่มียอด** ⇒ 21917 ติดลบ · 21916 ค้างถาวร ล้างไม่ได้ตลอดกาล
        // ⚠️ ลำดับรหัสมาจาก `Helpers/WhtPayableAccount` **ตัวเดียว** — เดิมเขียน
        // "21917/21916" ไว้ที่นี่ และมีสำเนาอีก 3 ชุด (พรีวิว GL · integration ×2)
        // ที่ตัดสินด้วยกติกาคนละแบบและ **ไม่รู้จัก 21918 เลย** (ผลตรวจรอบ 180)
        foreach (var code in Accounting.Helpers.WhtPayableAccount.CodeChain(
                     isForeignService, contact?.CountryCode, contact?.TaxId,
                     contact?.ContactType ?? ContactType.Individual, contact?.Name))
        {
            var acct = await FindAccountAsync(companyId, code);
            if (acct != null) return acct;
        }
        return null;
    }

    /// <summary>Get (creating once if absent) the "goods received not
    /// invoiced" accrual account (21240) used by the 3-way-match GRN flow.
    /// Auto-creating it means the feature works for existing companies whose
    /// chart predates it — it appears as a standard liability under 212.</summary>
    private async Task<ChartOfAccount?> EnsureGrNiAccountAsync(Guid companyId)
    {
        var existing = await FindAccountAsync(companyId, "21240");
        if (existing != null) return existing;

        var parentId = await _db.ChartOfAccounts.AsNoTracking()
            .Where(a => a.CompanyId == companyId && a.AccountCode == "212")
            .Select(a => (Guid?)a.Id)
            .FirstOrDefaultAsync();

        var acct = new ChartOfAccount
        {
            CompanyId = companyId,
            AccountCode = "21240",
            AccountName = "เจ้าหนี้-รับสินค้ายังไม่วางบิล",
            AccountNameEn = "Goods Received Not Invoiced",
            AccountType = AccountType.Liability,
            ParentAccountId = parentId,
            Level = 4,
            IsActive = true,
            IsSystemAccount = true,
            Description = "ตั้งพักเจ้าหนี้สำหรับสินค้าที่รับแล้วแต่ยังไม่ได้รับใบกำกับ (3-way match)",
        };
        _db.ChartOfAccounts.Add(acct);
        await _db.SaveChangesAsync();
        return acct;
    }

    /// <summary>When a PurchaseInvoice was billed against a GoodsReceiptNote
    /// that already accrued the goods (posted a Dr Expense / Cr GR-NI entry),
    /// return that GR-NI account so the PI can clear the accrual instead of
    /// re-debiting expense + re-moving stock. Returns null for a standalone
    /// PI or a GRN that hasn't posted (so the caller falls back to the normal
    /// expense + stock path).</summary>
    private async Task<ChartOfAccount?> GetReceivedViaGrnAccrualAccountAsync(Guid companyId, Document doc)
    {
        if (doc.RelatedDocumentId == null) return null;
        var srcType = await _db.Documents.AsNoTracking()
            .Where(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId)
            .Select(d => (DocumentType?)d.DocumentType)
            .FirstOrDefaultAsync();
        if (srcType != DocumentType.GoodsReceiptNote) return null;

        var grnPosted = await _db.JournalEntries.AsNoTracking()
            .AnyAsync(j => j.SourceDocumentId == doc.RelatedDocumentId.Value
                && j.CompanyId == companyId && j.Status == JournalEntryStatus.Posted);
        if (!grnPosted) return null;

        return await FindAccountAsync(companyId, "21240");
    }

    /// <summary>Resolve the PAYABLE account by document role — the heart of
    /// the trade-vs-non-trade separation (หลักบัญชีไทย):
    ///   • ใบแจ้งหนี้ซื้อ (PurchaseInvoice) = trade purchase backed by the
    ///     supplier's invoice → เจ้าหนี้การค้า (21210 / "212" family).
    ///   • ใบบันทึกค่าใช้จ่าย (Expense) = internal expense request / claim
    ///     with no supplier trade invoice → เจ้าหนี้อื่น (21220), so trade
    ///     payables stay clean for supplier statement reconciliation.
    /// The contact's pinned DefaultApAccount still wins for both (the user
    /// explicitly chose where that vendor's balance lives). Falls back to the
    /// 212 family when 21220 doesn't exist in a custom chart.</summary>
    private async Task<ChartOfAccount?> ResolvePayableAccountAsync(
        Guid companyId, DocumentType sourceType, Contact? contact)
    {
        if (sourceType == DocumentType.Expense)
        {
            // Pinned per-contact AP override wins (same rule as FindAccountAsync).
            if (contact?.DefaultApAccountId is Guid pinnedId)
            {
                var pinned = await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
                    a.Id == pinnedId && a.CompanyId == companyId && a.IsActive);
                if (pinned != null) return pinned;
            }
            var other = await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
                a.CompanyId == companyId && a.AccountCode == "21220" && a.IsActive);
            if (other != null) return other;
        }
        return await FindAccountAsync(companyId, "212", contact);
    }

    /// <summary>Per-instance cache สำหรับ FindAccountAsync — ApproveDocument
    /// / Post payroll หา default account ซ้ำๆ (113, 212, 116, 21914...
    /// ราว 8-15 ครั้งต่อ post). DocumentService เป็น scoped ต่อ request →
    /// cache ตามอายุ request เท่านั้น ไม่มี stale-data risk ข้าม request.
    /// Key เป็น (codePrefix, contactDefaultId) — pinned contact overrides
    /// ใช้ key ต่าง ให้ cache แยก hit.</summary>
    private readonly Dictionary<(string CodePrefix, Guid? ContactDefault), ChartOfAccount?> _findAccountCache = new();

    private async Task<ChartOfAccount?> FindAccountAsync(
        Guid companyId, string codePrefix, Contact? contactOverride = null)
    {
        Guid? overrideId = contactOverride == null ? null : codePrefix switch
        {
            "113" => contactOverride.DefaultArAccountId,
            "212" => contactOverride.DefaultApAccountId,
            "212305" => contactOverride.DefaultIrGrAccountId,
            _ => null,
        };
        var cacheKey = (codePrefix, overrideId);
        if (_findAccountCache.TryGetValue(cacheKey, out var cached)) return cached;

        if (overrideId.HasValue)
        {
            var pinned = await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
                a.Id == overrideId.Value && a.CompanyId == companyId && a.IsActive);
            if (pinned != null) { _findAccountCache[cacheKey] = pinned; return pinned; }
            // The override points at a deleted/inactive account —
            // fall through to the system default rather than throw.
        }
        // exact-match ต้องเป็นบัญชี postable (Level >= 4) เท่านั้น — chart มาตรฐาน
        // มี header ระดับ 3 ชื่อรหัสสั้น ("116", "212") ถ้า exact จับ header จะ
        // ลงบัญชีลงกลุ่มแทนบัญชีจริง (audit F2: CN ซื้อเครดิต "116" header →
        // 11610 ค้างสูงถาวร) → header หลุดไป prefix-search ที่กรอง Level >= 4 อยู่แล้ว
        var found = await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
                a.CompanyId == companyId && a.AccountCode == codePrefix && a.Level >= 4 && a.IsActive)
            ?? await _db.ChartOfAccounts
                .Where(a => a.CompanyId == companyId && a.AccountCode.StartsWith(codePrefix) && a.Level >= 4 && a.IsActive)
                .OrderBy(a => a.AccountCode)
                .FirstOrDefaultAsync();
        _findAccountCache[cacheKey] = found;
        return found;
    }

    /// <summary>เลือกผังบัญชีปลายทางของภาษีซื้อ ตาม priority:
    ///   1) <c>doc.InputVatAccountCodeOverride</c> set → ใช้ค่านั้น (treat as
    ///      §82/5 ถ้าไม่ใช่ 116xx — ลง expense เต็มจำนวน, ไม่เข้า ภ.พ.30)
    ///   2) Completeness §86/4 ครบ → 11610 "ภาษีซื้อ ภ.พ.30"
    ///   3) ไม่ครบ → 11640 "ภาษีซื้อยังไม่ถึงกำหนด" (§82/3 รอใบครบ)
    /// Fallback ถ้าไม่พบ 11640 (chart เก่าไม่มี): 11630 (Deferred) → 116 parent.
    /// คืน <c>postedAsUndue=true</c> เฉพาะ path (3) เพื่อ track ว่าต้อง reclassify
    /// ตอน user มาเติมใบกำกับครบ.</summary>
    private async Task<(ChartOfAccount Account, bool PostedAsUndue)> ResolveInputVatAccountAsync(
        Guid companyId, Document doc)
    {
        // (1) Override — user เลือกผังอื่น (เช่น 51000 ลงต้นทุนขาย)
        if (!string.IsNullOrWhiteSpace(doc.InputVatAccountCodeOverride))
        {
            var overrideAcc = await FindAccountAsync(companyId, doc.InputVatAccountCodeOverride!);
            if (overrideAcc != null) return (overrideAcc, PostedAsUndue: false);
            // override ชี้บัญชีที่ลบไป → fall through ใช้ default (กัน JE พัง)
        }

        // (2)/(3) Completeness check — pure function
        var completeness = TaxInvoiceCompletenessChecker.Evaluate(doc, doc.Contact);

        if (completeness.IsClaimable)
        {
            var claimable = await FindAccountAsync(companyId, "11610")
                ?? await FindAccountAsync(companyId, "116")
                ?? throw new InvalidOperationException(
                    "ไม่พบบัญชีภาษีซื้อ (11610 หรือ 116) ในผังบัญชี — กรุณาเพิ่มก่อนอนุมัติเอกสารซื้อที่มี VAT");
            return (claimable, PostedAsUndue: false);
        }

        // ใบไม่ครบ → suspense 11640
        var undue = await FindAccountAsync(companyId, "11640")
            ?? await FindAccountAsync(companyId, "11630")  // Deferred Input VAT — fallback
            ?? await FindAccountAsync(companyId, "116")
            ?? throw new InvalidOperationException(
                "ไม่พบบัญชี 11640 'ภาษีซื้อยังไม่ถึงกำหนด' ในผังบัญชี — กรุณาเพิ่มก่อนอนุมัติเอกสารซื้อที่ใบกำกับยังไม่ครบ");
        return (undue, PostedAsUndue: true);
    }

    /// <summary>หลัง user แก้เอกสารให้ใบกำกับครบ §86/4 — ตรวจว่าเดิม VAT
    /// post ไป 11640 ไหม ถ้าใช่ generate adjusting JE: Dr 11610 / Cr 11640
    /// (ย้ายมาเป็นภาษีซื้อเคลมได้). Idempotent — ถ้าครบอยู่แล้วหรือไม่เคย
    /// suspend จะ no-op. เรียกก่อน SaveChanges ใน CompleteSupplierTaxInvoiceAsync.
    /// คืน true ถ้า reclassify จริง (มีการสร้าง JE).</summary>
    private async Task<bool> ReclassifyUndueInputVatAsync(Guid companyId, Document doc, string actor)
    {
        // ไม่เคย suspend → ไม่ต้องทำอะไร
        if (!doc.InputVatPostedAsUndue) return false;
        // §83/6 บริการต่างประเทศ: ภาษีซื้อพักที่ 11640 ด้วยเหตุ "ยังไม่นำส่ง ภ.พ.36"
        // (ไม่ใช่ใบกำกับ §86/4 ไม่ครบ) — เคลมผ่าน RecognizePp36InputVatAsync เท่านั้น
        // (หลังนำส่ง+ใบเสร็จ RD §77/2). ห้ามย้ายผ่านเส้น §86/4 นี้ (ผู้ขาย ตปท.
        // ไม่มีเลขภาษีไทย → completeness ก็ fail อยู่แล้ว แต่กันชัด ๆ)
        if (doc.IsForeignService) return false;
        // เคย reclassify ไปแล้ว → ไม่ทำซ้ำ (idempotent)
        if (doc.InputVatBecameClaimableAt.HasValue) return false;
        // job §82/3 ล้างเป็นค่าใช้จ่ายไปแล้ว (พ้น 6 เดือน) — ห้ามย้ายเข้า 11610
        // อีก ไม่งั้น 11640 ติดลบ + เคลม ภ.พ.30 หลังหมดสิทธิ์ + ค่าใช้จ่ายเบิ้ล
        if (doc.InputVatExpiredAt.HasValue) return false;
        // §82/3: กรอบ 6 เดือนนับจากเดือนภาษีของใบกำกับ (สูตรเดียวกับ expiry job)
        // — เกินแล้วห้ามย้ายเข้า 11610 แม้ใบจะครบ §86/4 ทีหลัง; ผลต้องไม่ขึ้นกับ
        // ว่า nightly job หรือ user มาถึงก่อน
        var claimBaseDate = doc.SupplierTaxInvoiceDate ?? doc.DocumentDate;
        var claimWindowEnd = new DateTime(claimBaseDate.Year, claimBaseDate.Month, 1)
            .AddMonths(7).AddDays(-1);
        if (DateTime.UtcNow.AddHours(7).Date > claimWindowEnd) return false;
        // มี override → user ตั้งใจไม่เคลม VAT → ไม่ reclassify
        if (!string.IsNullOrWhiteSpace(doc.InputVatAccountCodeOverride)) return false;
        // ต้องเป็นเอกสารที่ approved แล้ว (Draft ไม่มี JE ให้ adjust)
        if (doc.Status == DocumentStatus.Draft || doc.Status == DocumentStatus.Voided) return false;

        // Reload contact ถ้ายังไม่ track (UpdateDocumentAsync อาจไม่ Include)
        if (doc.Contact == null)
            doc.Contact = await _db.Contacts.FirstOrDefaultAsync(c =>
                c.Id == doc.ContactId && c.CompanyId == companyId) ?? doc.Contact!;

        var completeness = TaxInvoiceCompletenessChecker.Evaluate(doc, doc.Contact);
        if (!completeness.IsClaimable) return false;   // ยังไม่ครบ → คงอยู่ 11640

        // หา VAT amount ที่เคยลงไป (= sum line.VatAmount ของบรรทัด claimable)
        if (doc.Lines == null || doc.Lines.Count == 0)
            doc.Lines = await _db.DocumentLines
                .Where(l => l.DocumentId == doc.Id).ToListAsync();
        // แปลงเป็นหน่วย GL ก่อนเสมอ — ยอดบนบรรทัดเป็นสกุลเอกสาร (P-2)
        var vatAmount = ToGlAmount(doc, doc.Lines.Where(l => l.IsVatClaimable).Sum(l => l.VatAmount));
        if (vatAmount <= 0) return false;

        var claimableAcc = await FindAccountAsync(companyId, "11610")
            ?? await FindAccountAsync(companyId, "116");
        var undueAcc = await FindAccountAsync(companyId, "11640")
            ?? await FindAccountAsync(companyId, "11630");
        if (claimableAcc == null || undueAcc == null) return false;

        var now = DateTime.UtcNow;
        var entryNumber = await GetNextJournalEntryNumberAsync(companyId, "JV");
        // ป้ายต้องตรงกับสิ่งที่ทำจริง — ผู้ใช้อ่านข้อความนี้เพื่อรู้ว่าต้องเปิดงวดไหน
        // ทำอะไร (เดิมเขียน "รายการตัดหนี้สูญ" ทั้งที่เมธอดนี้คือย้ายภาษีซื้อรอเคลม
        // 11640 → 11610 · ผลตรวจทีม C · C-06)
        var period = await RequireOpenFiscalPeriodAsync(companyId, now, "รายการย้ายภาษีซื้อรอเคลมเป็นภาษีซื้อขอคืนได้");
        var je = new JournalEntry
        {
            CompanyId = companyId,
            EntryNumber = entryNumber,
            EntryDate = now,
            JournalType = JournalType.General,
            Description = $"ภาษีซื้อถึงกำหนด (ใบกำกับครบ §86/4) - {doc.DocumentNumber}",
            Reference = doc.DocumentNumber,
            Status = JournalEntryStatus.Posted,
            TotalDebit = vatAmount,
            TotalCredit = vatAmount,
            CreatedBy = actor,
            IsAutoGenerated = true,
            SourceDocumentId = doc.Id,
            FiscalPeriodId = period?.Id,
            ProjectId = doc.ProjectId,
        };
        _db.JournalEntries.Add(je);
        _db.JournalEntryLines.Add(new JournalEntryLine
        {
            JournalEntryId = je.Id, AccountId = claimableAcc.Id,
            DebitAmount = vatAmount, CreditAmount = 0,
            Description = "ภาษีซื้อ (เคลม ภ.พ.30 ได้แล้ว)", LineOrder = 1,
        });
        _db.JournalEntryLines.Add(new JournalEntryLine
        {
            JournalEntryId = je.Id, AccountId = undueAcc.Id,
            DebitAmount = 0, CreditAmount = vatAmount,
            Description = "กลับรายการภาษีซื้อยังไม่ถึงกำหนด", LineOrder = 2,
        });

        doc.InputVatBecameClaimableAt = now;
        // InputVatPostedAsUndue คงไว้ true เป็น historical marker —
        // ใช้คู่ BecameClaimableAt เพื่อบอก ภ.พ.30 ว่าใช้ period ของ
        // BecameClaimableAt (ไม่ใช่ DocumentDate) เป็น tax point
        // PV: เปิดธง "ใช้งานใบกำกับภาษี" ให้ ภ.พ.30 นับแถวด้วย — ข้อมูลใบกำกับ
        // ครบ §86/4 แล้วโดยนิยาม. ไม่งั้น GL มี Dr 11610 แต่รายงานไม่มีแถว
        // (branch ฝั่ง input รับ PV เฉพาะ HasTaxInvoiceReference) = ไม่ reconcile
        if (doc.DocumentType == DocumentType.PaymentVoucher)
            doc.HasTaxInvoiceReference = true;
        return true;
    }

    /// <summary>§82/3: ภาษีซื้อที่ค้าง 11640 พ้น 6 เดือนโดยใบกำกับไม่ครบ → เคลม
    /// ไม่ได้แล้ว ต้อง reclassify เป็นค่าใช้จ่าย (Dr ค่าใช้จ่าย "ภาษีซื้อขอคืนไม่ได้" /
    /// Cr 11640) ล้าง 11640 ที่ค้างเป็น asset ลอย. Idempotent (ตั้ง InputVatExpiredAt).
    /// เรียกจาก endpoint / nightly job. คืนจำนวนเอกสารที่จัดการ.</summary>
    /// <summary>คีย์ล็อกของงาน §82/3 — <b>ผูกกับบริษัท</b>
    ///
    /// เดิมเป็นค่าคงที่ <c>828_003L</c> ทั้งระบบ ⇒ ผู้ใช้บริษัท A กดปุ่ม
    /// "ล้างภาษีซื้อหมดสิทธิ์" แล้วสแกนนานเป็นสิบวินาที ผู้ใช้**บริษัทอื่น**ที่กด
    /// ปุ่มเดียวกันต้องรอจนเสร็จ ทั้งที่ทำงานคนละชุดข้อมูลโดยสิ้นเชิง
    /// (head-of-line blocking ข้าม tenant — จุดเดียวในเรพที่เป็นแบบนี้)
    ///
    /// การผูก companyId ยัง<b>กันสิ่งที่ต้องกันได้ครบเหมือนเดิม</b>: ปุ่มกับ job
    /// ของ<i>บริษัทเดียวกัน</i>ยังชนกันไม่ได้ ซึ่งคือเจตนาจริงของล็อกนี้
    /// (กัน JE ซ้ำจาก read-then-write ยาวของ <c>InputVatExpiredAt</c>)</summary>
    internal static long UndueVatExpiryLockKeyFor(Guid companyId)
        => Accounting.Helpers.AdvisoryLockKey.For(companyId, Accounting.Helpers.AdvisoryLockKey.UndueVatExpiry, "reclassify");

    public async Task<int> ReclassifyExpiredUndueInputVatAsync(Guid companyId, string actor)
    {
        // ⚠️ ล็อกอยู่ในเมธอด ไม่ใช่ในตัว job —
        // เดิม `UndueInputVatExpiryJob` ขอ `pg_advisory_xact_lock(828003)` ไว้
        // รอบตัวมันเอง แต่ปุ่ม "ล้างภาษีซื้อหมดสิทธิ์" ใน DocumentController
        // เรียกเมธอดนี้ **ตรง ๆ ไม่มี lock ไม่มี transaction** ⇒ ล็อกที่ job
        // อุตส่าห์ใส่ไว้ไม่มีผลใด ๆ กับ path ที่สอง
        // idempotency ของเมธอดคือ `InputVatExpiredAt == null` แบบ read-then-write
        // ยาว (อ่านที่ต้นเมธอด เซ็ตท้ายสุด) ⇒ กดปุ่มตอน job ตื่นพอดี หรือกด
        // สองครั้ง = post JE `Dr ค่าใช้จ่ายภาษีซื้อขอคืนไม่ได้ / Cr 11640`
        // **สองรอบ** ⇒ ค่าใช้จ่ายเกินจริง + บัญชี 11640 ติดลบ
        // ย้ายล็อกมาไว้ในนี้ = ทุกผู้เรียกได้รับการป้องกันเท่ากันโดยอัตโนมัติ
        var ownsTransaction = _db.Database.CurrentTransaction == null;
        var tx = ownsTransaction ? await _db.Database.BeginTransactionAsync() : null;
        try
        {
            await _db.Database.ExecuteSqlRawAsync(
                "SELECT pg_advisory_xact_lock({0})", new object[] { UndueVatExpiryLockKeyFor(companyId) });
            var n = await ReclassifyExpiredUndueInputVatCoreAsync(companyId, actor);
            if (tx != null) await tx.CommitAsync();
            return n;
        }
        catch
        {
            if (tx != null) await tx.RollbackAsync();
            throw;
        }
        finally
        {
            if (tx != null) await tx.DisposeAsync();
        }
    }

    private async Task<int> ReclassifyExpiredUndueInputVatCoreAsync(Guid companyId, string actor)
    {
        var today = DateTime.UtcNow.Date;
        var rows = await _db.Documents.Include(d => d.Lines)
            .Where(d => d.CompanyId == companyId && d.InputVatPostedAsUndue
                && d.InputVatBecameClaimableAt == null && d.InputVatExpiredAt == null
                && (d.InputVatAccountCodeOverride == null || d.InputVatAccountCodeOverride == "")
                // ภ.พ.36 (§83/6): พัก 11640 ด้วยเหตุ "รอนำส่ง" ไม่ใช่ใบกำกับไม่ครบ
                // — วงจรหมดสิทธิ์คนละเหตุ ห้ามล้างเป็นค่าใช้จ่ายด้วยกรอบ §82/3 นี้
                // (ล้างแล้ว RecognizePp36 ทีหลังจะ Dr 11610 ซ้อน → 11640 ติดลบ)
                && !d.IsForeignService
                && d.Status != DocumentStatus.Draft && d.Status != DocumentStatus.Voided)
            .ToListAsync();

        var undueAcc = await FindAccountAsync(companyId, "11640") ?? await FindAccountAsync(companyId, "11630");
        if (undueAcc == null) return 0;
        // fallback ระดับบริษัท เมื่อ resolve ตามก้อนเงินรายใบไม่ได้ — ผังชื่อ
        // "ภาษีซื้อ/ขอคืนไม่ได้" ก่อน แล้วค่อยผังค่าใช้จ่ายใดก็ได้. **ห้าม**
        // fallback ตามเลขนำหน้า 53 (เคยได้ 53120 ค่าโฆษณา — คนละความหมาย)
        var companyFallbackAcc = await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
                a.CompanyId == companyId && a.IsActive && !a.IsDeleted && a.Level >= 4
                && a.AccountCode.StartsWith("5")
                && (a.AccountName.Contains("ภาษีซื้อ") || a.AccountName.Contains("ขอคืนไม่ได้")))
            ?? await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
                a.CompanyId == companyId && a.IsActive && !a.IsDeleted && a.Level >= 4
                && a.AccountType == AccountType.Expense);

        var count = 0;
        foreach (var doc in rows)
        {
            var baseDate = doc.SupplierTaxInvoiceDate ?? doc.DocumentDate;
            var windowEnd = new DateTime(baseDate.Year, baseDate.Month, 1).AddMonths(7).AddDays(-1);
            if (today <= windowEnd) continue;   // ยังไม่หมดสิทธิ์
            var vatAmount = ToGlAmount(doc, doc.Lines.Where(l => l.IsVatClaimable).Sum(l => l.VatAmount));
            if (vatAmount <= 0) { doc.InputVatExpiredAt = DateTime.UtcNow; count++; continue; }

            // VAT หมดสิทธิ์เคลม = ต้นทุนของก้อนเงินเดิม (ตามบัญชีบรรทัด) —
            // ใช้ fallback ระดับบริษัทเฉพาะใบที่บรรทัดไม่มีผัง (job ห้ามล้มทั้งชุด)
            var expenseAcc = await ResolveNonClaimableVatExpenseAccountAsync(companyId, doc)
                ?? companyFallbackAcc;
            if (expenseAcc == null) continue;

            var now = DateTime.UtcNow;
            var je = new JournalEntry
            {
                CompanyId = companyId,
                EntryNumber = await GetNextJournalEntryNumberAsync(companyId, "JV"),
                EntryDate = now, JournalType = JournalType.General,
                Description = $"ภาษีซื้อขอคืนไม่ได้ (§82/3 พ้น 6 เดือน) - {doc.DocumentNumber}",
                Reference = doc.DocumentNumber, Status = JournalEntryStatus.Posted,
                TotalDebit = vatAmount, TotalCredit = vatAmount, CreatedBy = actor,
                IsAutoGenerated = true, SourceDocumentId = doc.Id,
                FiscalPeriodId = (await ResolveFiscalPeriodAsync(companyId, now))?.Id,
                ProjectId = doc.ProjectId,
            };
            _db.JournalEntries.Add(je);
            _db.JournalEntryLines.Add(new JournalEntryLine { JournalEntryId = je.Id,
                AccountId = expenseAcc.Id, DebitAmount = vatAmount, CreditAmount = 0,
                Description = "ภาษีซื้อขอคืนไม่ได้ (พ้น 6 เดือน §82/3)", LineOrder = 1 });
            _db.JournalEntryLines.Add(new JournalEntryLine { JournalEntryId = je.Id,
                AccountId = undueAcc.Id, DebitAmount = 0, CreditAmount = vatAmount,
                Description = "ล้างภาษีซื้อยังไม่ถึงกำหนด (หมดสิทธิ์เคลม)", LineOrder = 2 });
            doc.InputVatExpiredAt = now;
            count++;
        }
        if (count > 0) await _db.SaveChangesAsync();
        _logger.LogInformation("Reclassified {Count} expired undue input-VAT docs → expense (§82/3), company {Cid}", count, companyId);
        return count;
    }

    /// <summary>Resolve AccountCode → AccountId ใน CoA ของบริษัท. คืน null ถ้า
    /// ไม่พบ / inactive (ป้องกัน AI hallucinate ผังที่ไม่มีจริง). cache
    /// ใน-call ผ่าน lookup map ที่ caller เตรียมไว้.</summary>
    private async Task<Guid?> ResolveAccountCodeAsync(Guid companyId, string? code,
        IDictionary<string, Guid?>? cache = null)
    {
        if (string.IsNullOrWhiteSpace(code)) return null;
        if (cache != null && cache.TryGetValue(code, out var cached)) return cached;
        var id = await _db.ChartOfAccounts.AsNoTracking()
            .Where(a => a.CompanyId == companyId && a.AccountCode == code && a.IsActive)
            .Select(a => (Guid?)a.Id)
            .FirstOrDefaultAsync();
        if (cache != null) cache[code] = id;
        return id;
    }

    /// <summary>ปิดลูปการสอน local distillation model ตามกฎเหล็ก #1:
    /// สำหรับทุกบรรทัดที่มี GlAccountAiFeedbackId + AccountId — เปรียบ
    /// AccountCode ของ user choice กับ AiPrimaryAnswer แล้วเรียก
    /// RecordUserChoiceAsync (acceptedAi=true ถ้าตรง, false ถ้าแก้). ทนต่อ
    /// recorder/FX ปิด (graceful degradation เงียบ).</summary>
    /// <summary>อัปเดตแถวสแกนต้นทางให้ตรงกับ "เอกสารที่อนุมัติแล้ว"
    /// (สถาปัตยกรรมเป้าหมาย D3 · กฎเหล็ก #1 ขั้น CAPTURE)
    ///
    /// <para>ทำไม: นักเรียนทุกตัวที่เรียนจากไปป์ไลน์ OCR
    /// (<c>OcrFullReviewDistillationModel</c> · <c>LineSplitDistillationModel</c> ·
    /// ตัวเรียนรู้ผู้ขาย/หมวดรายจ่าย) mine จาก <c>OcrScanResult</c> ที่
    /// <c>CreatedDocumentId != null</c> — ซึ่งเป็นค่า ณ ตอน<b>กดสร้าง</b> (ยัง Draft)
    /// ผู้ใช้ที่เปิด Draft แล้วแก้ก่อนอนุมัติจึงไม่เคยถูกนับเป็นการสอนเลย</para>
    ///
    /// <para>ตัวตัดสินว่า "ช่องไหนควรเปลี่ยน" อยู่ใน <c>Helpers/OcrPostedTruth</c>
    /// (pure + มีเทสต์) — ห้ามเขียนกติกาเทียบค่าเองที่นี่ · best-effort เสมอ
    /// (ล้มแล้วต้องไม่ทำให้การอนุมัติล้ม)</para></summary>
    private async Task SyncScanToPostedDocumentAsync(
        Guid companyId, Document doc, List<DocumentLine> approvedLines)
    {
        try
        {
            var scan = await _db.Set<OcrScanResult>()
                .FirstOrDefaultAsync(s => s.CompanyId == companyId
                    && s.CreatedDocumentId == doc.Id && !s.IsDeleted);
            if (scan == null) return;

            // ชนิดกำกวม (CN/DN/ใบส่งของ) ต้องดูฝั่งที่ระบบตัดสินไว้แล้วก่อน —
            // เรียก `IsPurchase(type)` เปล่า ๆ จะได้ "ฝั่งซื้อ" สำหรับใบลดหนี้ฝั่งขาย
            // (กติกาเดียวกับ TaxService — ตามล้างรูปแบบเดิมให้ครบตอนแก้ D1-B2)
            var isPurchase = doc.CnDnPurchaseSideOverride
                ?? Accounting.Helpers.DocumentSide.IsPurchase(doc.DocumentType);
            var contact = doc.ContactId != Guid.Empty
                ? await _db.Contacts.AsNoTracking()
                    .Where(c => c.Id == doc.ContactId && c.CompanyId == companyId)
                    .Select(c => new { c.Name, c.TaxId })
                    .FirstOrDefaultAsync()
                : null;

            var current = new Accounting.Helpers.OcrPostedSnapshot(
                VendorName: scan.ExtractedVendorName,
                VendorTaxId: scan.ExtractedVendorTaxId,
                VendorBranchCode: scan.VendorBranchCode,
                DocumentNumber: scan.ExtractedDocumentNumber,
                DocumentDate: scan.ExtractedDate,
                SubTotal: scan.ExtractedSubTotal,
                VatAmount: scan.ExtractedVatAmount,
                TotalAmount: scan.ExtractedTotalAmount,
                TargetDocumentType: scan.TargetDocumentType);

            // ยอด 0 บนเอกสารแปลว่า "ไม่ได้กรอก" มากกว่า "เป็นศูนย์จริง" ⇒ ส่ง null
            // ให้ helper แปลว่าไม่แตะ (ห้ามล้างค่าที่สแกนอ่านมาได้ด้วยศูนย์)
            var posted = new Accounting.Helpers.OcrPostedSnapshot(
                VendorName: contact?.Name,
                VendorTaxId: contact?.TaxId,
                // รหัสสาขา/เลขใบกำกับของผู้ขาย มีความหมายเฉพาะฝั่งซื้อ
                VendorBranchCode: isPurchase ? doc.SupplierBranchCode : null,
                DocumentNumber: isPurchase ? doc.SupplierInvoiceNumber : null,
                DocumentDate: doc.DocumentDate,
                SubTotal: doc.SubTotal > 0m ? doc.SubTotal : null,
                VatAmount: doc.VatAmount > 0m ? doc.VatAmount : null,
                TotalAmount: doc.TotalAmount > 0m ? doc.TotalAmount : null,
                TargetDocumentType: doc.DocumentType.ToString());

            var change = Accounting.Helpers.OcrPostedTruth.Diff(current, posted);
            var linesJson = BuildScanItemsJsonFromLines(approvedLines);
            var linesChanged = linesJson != null && linesJson != scan.ExtractedItemsJson;
            if (!change.HasChanges && !linesChanged) return;

            if (change.VendorName != null) scan.ExtractedVendorName = change.VendorName;
            if (change.VendorTaxId != null) scan.ExtractedVendorTaxId = change.VendorTaxId;
            if (change.VendorBranchCode != null) scan.VendorBranchCode = change.VendorBranchCode;
            if (change.DocumentNumber != null) scan.ExtractedDocumentNumber = change.DocumentNumber;
            if (change.DocumentDate != null) scan.ExtractedDate = change.DocumentDate;
            if (change.SubTotal != null) scan.ExtractedSubTotal = change.SubTotal;
            if (change.VatAmount != null) scan.ExtractedVatAmount = change.VatAmount;
            if (change.TotalAmount != null) scan.ExtractedTotalAmount = change.TotalAmount;
            if (change.TargetDocumentType != null) scan.TargetDocumentType = change.TargetDocumentType;
            if (linesChanged) scan.ExtractedItemsJson = linesJson;

            // ★ ตัวชี้วัดคุณภาพ (D4): การแก้ Draft ก่อนอนุมัติก็คือ "ผู้ใช้ต้องแก้"
            // เหมือนกับการแก้ในหน้า review — ไม่งั้น first-pass accept rate จะสูงเกินจริง
            var touched = new List<string>();
            if (change.VendorName != null) touched.Add("VendorName");
            if (change.VendorTaxId != null) touched.Add("VendorTaxId");
            if (change.VendorBranchCode != null) touched.Add("VendorBranchCode");
            if (change.DocumentNumber != null) touched.Add("DocumentNumber");
            if (change.DocumentDate != null) touched.Add("DocumentDate");
            if (change.SubTotal != null) touched.Add("SubTotal");
            if (change.VatAmount != null) touched.Add("VatAmount");
            if (change.TotalAmount != null) touched.Add("TotalAmount");
            if (change.TargetDocumentType != null) touched.Add("TargetDocumentType");
            if (linesChanged) touched.Add("Lines");
            if (touched.Count > 0)
            {
                scan.UserCorrectedAt ??= DateTime.UtcNow;
                scan.UserCorrectedFields = Accounting.Helpers.OcrCorrectedFieldList.Merge(
                    scan.UserCorrectedFields, touched);
            }

            await _db.SaveChangesAsync();
            _logger.LogInformation(
                "ปิดลูปสอนจากเอกสารที่อนุมัติ {Doc} → sync สแกน {Scan} (ผู้ใช้แก้ก่อนอนุมัติ)",
                doc.DocumentNumber, scan.Id);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "sync สแกนกับเอกสารที่อนุมัติไม่สำเร็จ (doc {DocId})", doc.Id);
        }
    }

    /// <summary>แปลงบรรทัดของเอกสารที่อนุมัติแล้วกลับเป็นรูป
    /// <c>OcrScanResult.ExtractedItemsJson</c> เพื่อให้นักเรียนแตกบรรทัดเรียนจาก
    /// ชุดบรรทัดที่ <b>ลงบัญชีจริง</b> · คืน <c>null</c> เมื่อไม่มีบรรทัด</summary>
    private static string? BuildScanItemsJsonFromLines(List<DocumentLine> lines)
    {
        var usable = lines
            .Where(l => !string.IsNullOrWhiteSpace(l.Description))
            .OrderBy(l => l.LineOrder)
            .ToList();
        if (usable.Count == 0) return null;
        return System.Text.Json.JsonSerializer.Serialize(usable.Select(l => new
        {
            Description = l.Description,
            Quantity = l.Quantity,
            Unit = l.Unit,
            UnitPrice = l.UnitPrice,
            Amount = l.Amount,
            VatRate = l.VatRate,
        }));
    }

    private async Task RecordLineAccountFeedbackAsync(IEnumerable<DocumentLine> lines, CancellationToken ct = default)
    {
        if (_feedbackRecorder == null) return;
        var pending = lines.Where(l => l.GlAccountAiFeedbackId.HasValue && l.AccountId.HasValue).ToList();
        if (pending.Count == 0) return;
        var feedbackIds = pending.Select(l => l.GlAccountAiFeedbackId!.Value).Distinct().ToList();
        var accountIds = pending.Select(l => l.AccountId!.Value).Distinct().ToList();
        // batch load AI's original answer + chosen account code
        var aiAnswers = await _db.AiSuggestionFeedbacks.AsNoTracking()
            .Where(f => feedbackIds.Contains(f.Id))
            .Select(f => new { f.Id, f.AiPrimaryAnswer, f.UserChosenAnswer })
            .ToListAsync(ct);
        var aiAnswerMap = aiAnswers.ToDictionary(a => a.Id);
        var codeMap = await _db.ChartOfAccounts.AsNoTracking()
            .Where(a => accountIds.Contains(a.Id))
            .ToDictionaryAsync(a => a.Id, a => a.AccountCode, ct);

        foreach (var line in pending)
        {
            var fid = line.GlAccountAiFeedbackId!.Value;
            if (!aiAnswerMap.TryGetValue(fid, out var ai)) continue;
            // ถ้าผู้ใช้เลือกแล้ว (UserChosenAnswer != null) ก่อนหน้านี้ ไม่ทำซ้ำ
            // (ลด noise + ป้องกัน flap จากการ save หลายครั้ง). retrain job ใช้
            // record แรกที่ผู้ใช้ confirm เป็นหลักอยู่แล้ว.
            if (!string.IsNullOrEmpty(ai.UserChosenAnswer)) continue;
            if (!codeMap.TryGetValue(line.AccountId!.Value, out var chosenCode)) continue;
            var accepted = string.Equals(chosenCode, ai.AiPrimaryAnswer, StringComparison.OrdinalIgnoreCase);
            try
            {
                // ⚠️ **Implicit เสมอ** — เส้นนี้ยิงตอน**อนุมัติเอกสาร** ทุกบรรทัดที่มี
                // feedbackId โดยไม่รู้ว่าผู้ใช้เคยมองช่องผังบัญชีนั้นหรือไม่
                // (`accepted` = ค่าที่ระบบเติมให้ยังไม่ถูกเปลี่ยน) ⇒ ผู้ใช้ที่กด
                // "อนุมัติ" รัว ๆ จะกลายเป็นผู้ยืนยันวันละหลายสิบแถว แล้วดัน Wilson
                // ทะลุเกณฑ์จนไม่มีครูมาขัดอีกเลย (ทีม T3 รอบ 177 §3.1)
                await _feedbackRecorder.RecordUserChoiceAsync(fid, chosenCode, accepted, ct,
                    Accounting.Models.Enums.UserChoiceSource.Implicit);
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "Record GL feedback failed (feedbackId={Fid})", fid);
            }
        }
    }

    /// <summary>คำนวณ §65 ตรี รายจ่ายต้องห้าม → เก็บ NonDeductibleAmount +
    /// RuleJson บนเอกสาร (ไหลเข้า ภ.ง.ด.50 worksheet). hard-block กรณีไม่ระบุ
    /// ผู้รับเงิน. NeedsConfirmation (เช่น capex) เป็นแค่ warning ไม่ block.</summary>
    private async Task ApplySection65TerAsync(Guid companyId, Document doc)
    {
        // เตรียม account map (Id → code/name) สำหรับตรวจชนิดบัญชี
        var accIds = doc.Lines.Where(l => l.AccountId.HasValue)
            .Select(l => l.AccountId!.Value).Distinct().ToList();
        var accInfo = accIds.Count == 0
            ? new Dictionary<Guid, (string, string)>()
            : (await _db.ChartOfAccounts.AsNoTracking()
                .Where(a => accIds.Contains(a.Id))
                .Select(a => new { a.Id, a.AccountCode, a.AccountName })
                .ToListAsync())
                .ToDictionary(a => a.Id, a => (a.AccountCode, a.AccountName));

        // context: รายได้ทั้งปี + ทุนจดทะเบียน (สำหรับ cap ค่ารับรอง)
        var company = await _db.Companies.AsNoTracking()
            .FirstOrDefaultAsync(c => c.Id == companyId);
        var yearStart = new DateTime(doc.DocumentDate.Year, 1, 1);
        var yearEnd = yearStart.AddYears(1);
        var annualRevenue = await _db.Documents.AsNoTracking()
            .Where(d => d.CompanyId == companyId
                && (d.DocumentType == DocumentType.Invoice || d.DocumentType == DocumentType.TaxInvoice
                    || d.DocumentType == DocumentType.Receipt)
                && d.Status != DocumentStatus.Draft && d.Status != DocumentStatus.Voided
                && d.DocumentDate >= yearStart && d.DocumentDate < yearEnd)
            .SumAsync(d => (decimal?)d.SubTotal) ?? 0m;

        // §65 ตรี(4) cap เป็น "per fiscal year" — รวมยอดค่ารับรอง YTD ของ
        // เอกสารซื้อ/ค่าใช้จ่ายที่อนุมัติแล้วในรอบเดียวกัน (description มี
        // "รับรอง"/"entertain") เพื่อให้ excess คำนวณตาม YTD จริง ไม่ใช่
        // เฉพาะใบนี้. exclude doc ปัจจุบัน (re-approve / ก่อน approve)
        // "ออกแล้ว" = ทุกสถานะที่ไม่ใช่ร่าง/รออนุมัติ/ตีกลับ/ยกเลิก — PV/PI ที่จ่ายแล้ว
        // เป็น Paid ตั้งแต่ approve ⇒ `== Approved` เป๊ะ ๆ ทำให้ค่ารับรองที่จ่ายไปแล้ว
        // ทั้งปีหลุดจาก YTD → cap 0.3% ถูกใช้ซ้ำ (ERP_REVIEW A-01 · CLAUDE.md "== Approved มักผิด")
        var priorEntertainment = await _db.DocumentLines.AsNoTracking()
            .Where(l => l.Document.CompanyId == companyId
                && l.Document.Id != doc.Id
                && !DocumentStatusRules.NotIssued.Contains(l.Document.Status)
                && l.Document.Status != DocumentStatus.Voided
                && l.Document.DocumentDate >= yearStart && l.Document.DocumentDate < yearEnd
                && (l.Document.DocumentType == DocumentType.PurchaseInvoice
                    || l.Document.DocumentType == DocumentType.Expense
                    || l.Document.DocumentType == DocumentType.PaymentVoucher
                    || l.Document.DocumentType == DocumentType.CertificateInLieu)
                && (l.Description.Contains("รับรอง") || l.Description.Contains("entertain")
                    || l.Description.Contains("เลี้ยงรับรอง")))
            .SumAsync(l => (decimal?)(l.Amount + l.VatAmount)) ?? 0m;

        // context เพิ่มสำหรับอนุมาตราที่เพิ่งเปิดใช้ — ส่งเฉพาะที่รู้จริง
        // (null = ไม่ตรวจ) เพื่อไม่ให้เตือนจากการเดา
        //   (9)  มีเอกสารต้นฉบับไหม — ฝั่งซื้อดูจากเลขใบกำกับผู้ขาย หรือไฟล์แนบ
        //   (10) รอบบัญชีปัจจุบันเริ่มเมื่อไร (yearStart คำนวณไว้แล้วข้างบน)
        //   (13) เลขผู้เสียภาษีของบริษัทเอง — จับเคสจ่ายค่าเช่าให้ตัวเอง
        //   (19) รายจ่ายต่างประเทศเชื่อมกิจการไทยไหม — ยังไม่มี field เก็บ
        //        เจตนาผู้ใช้ จึงส่ง null (ไม่ตรวจ) จนกว่าจะเพิ่มช่องบนฟอร์ม
        // FileAttachment ผูกแบบ polymorphic (EntityType/EntityId) ไม่ใช่ FK ตรง
        var hasAttachment = await _db.FileAttachments.AsNoTracking()
            .AnyAsync(a => a.CompanyId == companyId
                && a.EntityType == "Document" && a.EntityId == doc.Id && !a.IsDeleted);
        var isPurchaseSide = doc.DocumentType is DocumentType.PurchaseInvoice
            or DocumentType.Expense or DocumentType.PaymentVoucher or DocumentType.CertificateInLieu;
        bool? hasSourceDoc = isPurchaseSide
            ? (!string.IsNullOrWhiteSpace(doc.SupplierInvoiceNumber) || hasAttachment)
            : null;

        var ctx = new Section65TerValidator.Context(
            annualRevenue, company?.PaidUpCapital, priorEntertainment,
            CurrentFiscalYearStart: yearStart,
            CompanyTaxId: company?.TaxId,
            HasSourceDocument: hasSourceDoc);
        var payeeName = doc.Contact?.Name;
        var payeeTaxId = doc.Contact?.TaxId;

        var result = Section65TerValidator.Evaluate(doc, accInfo, payeeName, payeeTaxId, ctx);

        if (result.HasHardBlock)
            throw new InvalidOperationException(result.FirstBlockMessage
                ?? "รายจ่ายต้องห้าม §65 ตรี — ข้อมูลไม่ครบ");

        doc.NonDeductibleAmount = result.TotalAddBack;
        doc.NonDeductibleRuleJson = result.Findings.Count > 0 ? result.ToJson() : null;
    }

    /// <summary>บังคับลงทะเบียนสินทรัพย์ถาวร — บรรทัดเอกสารฝั่งซื้อที่ลงผัง PPE
    /// (12xxx) ต้องมีทะเบียนสินทรัพย์ + ตารางค่าเสื่อม (TFRS บทที่ 10).
    /// auto-create ด้วยค่า default ตามประเภท (อายุใช้งาน/วิธี/ผังค่าเสื่อม),
    /// NeedsReview=true ให้ผู้ใช้ตรวจ. dedupe ด้วย SourceDocumentLineId (re-approve
    /// ไม่สร้างซ้ำ). PostAcquisitionJournalEntry=false เพราะเอกสารลง Dr asset แล้ว.</summary>
    private async Task AutoRegisterFixedAssetsAsync(Guid companyId, Document doc, string actor)
    {
        if (_fixedAssets == null) return;   // service ไม่ inject (เช่น test) → ข้าม
        // ตรรกะรายบรรทัด (planner · ผังค่าเสื่อม · dedupe) อยู่ที่ FixedAssetService
        // ตัวเดียว — ปุ่ม “ขึ้นทะเบียนจากบรรทัดนี้” บนหน้าเอกสารเรียกตัวเดียวกัน
        // (เดิมอยู่ที่นี่เป็น private ⇒ on-demand ต้องเขียนสำเนาที่สอง)
        try
        {
            await _fixedAssets.RegisterFromDocumentAsync(companyId, doc, onlyLineId: null, actor,
                skipIfScanRegistered: true);
        }
        catch (Exception ex)
        {
            // ไม่ให้ asset registration ล้มทำ approve พัง — log ไว้ (หน้าเอกสารมีปุ่มขึ้นทะเบียนซ่อมทีหลัง)
            _logger.LogWarning(ex, "Auto-register fixed assets failed (doc {Doc})", doc.DocumentNumber);
        }
    }

    /// <summary>หา FiscalPeriod ของวันที่นี้ — <b>ไม่ดูสถานะ</b> (ใช้กับงานอ่านอย่างเดียว)</summary>
    private async Task<FiscalPeriod?> ResolveFiscalPeriodAsync(Guid companyId, DateTime date)
        => await _db.FiscalPeriods.FirstOrDefaultAsync(p =>
            p.CompanyId == companyId && p.StartDate <= date && p.EndDate >= date);

    /// <summary>
    /// หา FiscalPeriod สำหรับ **การลงบัญชี** — งวดที่ปิดแล้วต้องล้มดัง
    ///
    /// ═══ ที่มา (ผลตรวจ C-T04) ═══
    /// <c>ResolveFiscalPeriodAsync</c> ไม่เคยดู <c>Status</c> เลย ⇒ 7 เส้นที่โพสต์
    /// JE (ล้าง/คืนภาษีซื้อ · รับรู้-คืนมัดจำ · ใช้มัดจำ · ตัดชำระ) ยัด JE เข้า
    /// **งวดที่ปิดและยื่นแบบไปแล้ว**ได้เงียบ ๆ ⇒ งบที่ยื่นกับ GL ไม่ตรงกันถาวร
    /// และไม่มีใครรู้จนกว่าจะพิมพ์งบเทียบ — ขณะที่ <c>AccountingService</c>
    /// (เส้นลง JE ด้วยมือ) ตรวจอยู่แล้วมาตั้งแต่ต้น = กติกาเดียวกันสองมาตรฐาน
    ///
    /// <para>ไม่มีงวดครอบวันนี้เลย → คืน <c>null</c> ตามเดิม (บริษัทที่ยังไม่ได้
    /// ตั้งงวดบัญชียังทำงานได้ — JE ไม่ผูกงวด ซึ่งเป็นพฤติกรรมเดิม)</para>
    /// </summary>
    private async Task<FiscalPeriod?> RequireOpenFiscalPeriodAsync(
        Guid companyId, DateTime date, string what)
    {
        var period = await ResolveFiscalPeriodAsync(companyId, date);
        if (period != null && period.Status != FiscalPeriodStatus.Open)
            throw new Accounting.Helpers.BusinessRuleException(
                $"ลง{what}เข้างวด “{period.Name}” ไม่ได้ — งวดนี้ปิดแล้ว "
                + $"(วันที่รายการ {date:yyyy-MM-dd}). "
                + "ทางแก้: เปิดงวดที่หน้า “งวดบัญชี” แล้วทำรายการใหม่ "
                + "หรือแก้วันที่รายการให้อยู่ในงวดที่ยังเปิด — "
                + "การลงย้อนเข้างวดที่ยื่นแบบไปแล้วทำให้งบที่ยื่นกับบัญชีไม่ตรงกัน");
        return period;
    }

    /// <summary>
    /// บันทึกบัญชีอัตโนมัติเมื่ออนุมัติเอกสาร — สร้าง JournalEntry + Lines โดยตรงผ่าน DbContext
    /// (อยู่ภายใน transaction เดียวกับ ApproveDocumentAsync เพื่อความ atomic ตามหลักบัญชี)
    ///
    /// กฎการ post ตามมาตรฐาน TFRS / ประมวลรัษฎากร §86, §82/10:
    ///
    /// ฝั่งขาย (SV - สมุดรายวันขาย):
    ///   Invoice/TaxInvoice/DebitNote: Dr ลูกหนี้ + Dr ภาษีถูกหัก, Cr รายได้ + Cr ภาษีขาย
    ///   CreditNote (ใบลดหนี้): กลับด้าน — Cr ลูกหนี้ + Cr ภาษีถูกหัก, Dr รายได้ + Dr ภาษีขาย
    ///
    /// ฝั่งซื้อ (UV - สมุดรายวันซื้อ):
    ///   PurchaseInvoice/Expense: Dr ค่าใช้จ่าย + Dr ภาษีซื้อ, Cr เจ้าหนี้ + Cr ภาษีหัก ณ ที่จ่ายค้างจ่าย
    ///
    /// รับเงิน (RV - สมุดรายวันรับ):
    ///   Receipt/ReceiptVoucher (link to Invoice): Dr เงินสด + Dr WHT Asset, Cr ลูกหนี้
    ///   Receipt/ReceiptVoucher (cash sale, ไม่ link): Dr เงินสด + Dr WHT Asset, Cr รายได้ + Cr ภาษีขาย
    ///
    /// จ่ายเงิน (PV - สมุดรายวันจ่าย):
    ///   PaymentVoucher (link to PurchaseInvoice): Dr เจ้าหนี้, Cr เงินสด + Cr WHT Payable
    ///   PaymentVoucher (direct cash purchase): Dr ค่าใช้จ่าย + Dr ภาษีซื้อ, Cr เงินสด + Cr WHT Payable
    /// </summary>
    /// <summary>Cascade product stock movements when a goods document is
    /// approved (sign=+1) or voided (sign=-1). The sign on the document
    /// type decides direction: sale Invoice / TaxInvoice = OUT (negative
    /// stock movement), purchase PurchaseInvoice = IN, sales CreditNote
    /// = IN (goods returned by customer). Documents that don't move goods
    /// (Quotation, Receipt, PaymentVoucher, DeliveryNote alone, Debit Note
    /// price-adjustment, etc.) return a zero direction and are skipped.
    ///
    /// Lines are matched to Products by (CompanyId, ProductCode). Lines
    /// with no ProductCode, free-text descriptions, or matching a product
    /// where TrackStock=false are skipped silently.
    ///
    /// Runs inside the approval/void transaction so a SaveChanges failure
    /// rolls back both the document state and the stock delta. Without
    /// this, sale Invoices left stock untouched and reconciling inventory
    /// to GL revenue required manual stock adjustments every period.</summary>
    /// <summary>เมื่อ TaxInvoice ที่แปลงมาจากใบแจ้งหนี้ (Invoice) ถูกอนุมัติ →
    /// supersede ใบแจ้งหนี้ต้นทาง: reverse JE + คืน stock + กลับ project billing +
    /// set Voided กัน GL/รายได้/สต๊อกซ้ำ. เฉพาะใบแจ้งหนี้ approved + ยังไม่ชำระ +
    /// ไม่มีลูก active อื่น. ทำใน transaction ของ ApproveDocumentAsync (reversal
    /// ambient-safe). ภพ.30 นับเฉพาะ TaxInvoice อยู่แล้ว → ไม่กระทบ.</summary>
    private async Task SupersedeSourceInvoiceAsync(Guid companyId, Document taxInvoice, string actor)
    {
        var src = await _db.Documents.Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == taxInvoice.RelatedDocumentId!.Value && d.CompanyId == companyId);
        if (src == null || src.DocumentType != DocumentType.Invoice) return;
        // ต้นทางยกเลิก/ปฏิเสธแล้ว → ไม่มีอะไรต้อง supersede
        if (src.Status == DocumentStatus.Voided || src.Status == DocumentStatus.Rejected) return;

        // ต้นทางยังไม่ลงบัญชี (Draft/รออนุมัติ) → ยังไม่เคยรับรู้รายได้ → TaxInvoice
        // ลงได้เดี่ยว ๆ ไม่ซ้ำ. แต่ต้อง void ใบแจ้งหนี้เดิม กันเผลอไปอนุมัติภายหลัง
        // แล้วลงรายได้/ภาษีขายเป็นครั้งที่ 2. (ไม่มี JE ให้ reverse)
        if (src.Status == DocumentStatus.Draft || src.Status == DocumentStatus.WaitingApproval)
        {
            src.Status = DocumentStatus.Voided;
            src.Notes = ((src.Notes ?? "") + $" [แทนที่ด้วยใบกำกับภาษี {taxInvoice.DocumentNumber}]").Trim();
            src.UpdatedAt = DateTime.UtcNow; src.UpdatedBy = actor;
            _logger.LogInformation("Voided draft Invoice {Src} superseded by TaxInvoice {Tax}",
                src.DocumentNumber, taxInvoice.DocumentNumber);
            return;
        }

        // ต้นทางลงบัญชีแล้ว (Approved/Sent/PartiallyPaid/Paid) — TaxInvoice นี้ลง
        // รายได้/ภาษีขาย/สต๊อกเต็มจำนวนไปแล้ว (ก่อนหน้าใน AutoPostToJournal) ดังนั้น
        // ต้อง "กลับรายการใบแจ้งหนี้เดิม" เท่านั้นถึงจะไม่ซ้ำ. ถ้ากลับรายการไม่ได้
        // (ชำระแล้วบางส่วน/ครบ หรือมีเอกสารลูกอื่น) → **ห้ามลงบัญชีซ้ำ** → block การ
        // อนุมัติ (throw ใน transaction → rollback JE ของ TaxInvoice ทั้งหมด).
        //
        // กันยอดไม่เท่ากัน (เคสจริง: INV 97,500 → TIV 75,000 เพราะบรรทัดราคาหลุด
        // เป็น 0 / partial convert / แก้ draft ก่อนอนุมัติ): supersede reverse ใบ
        // แจ้งหนี้ "ทั้งใบ" — ถ้าใบกำกับคุมยอดไม่ครบ ส่วนต่างจะหายจาก GL/ภาษีเงียบ ๆ
        if (Math.Abs(taxInvoice.TotalAmount - src.TotalAmount) > 0.01m)
            throw new InvalidOperationException(
                $"ยอดใบกำกับภาษี ({taxInvoice.TotalAmount:N2}) ไม่เท่ากับใบแจ้งหนี้ต้นทาง {src.DocumentNumber} ({src.TotalAmount:N2}) — " +
                "การแทนที่ต้องยอดตรงกันทั้งใบ (ตรวจราคาต่อบรรทัดของใบกำกับ: พบเคสราคาหลุดเป็น 0). " +
                "ถ้าต้องการออกใบกำกับบางส่วน ให้ยกเลิกใบแจ้งหนี้เดิมแล้วออกใบแจ้งหนี้ใหม่ตามยอดจริงก่อน");
        if (src.PaidAmount > 0.01m)
        {
            // ยอดที่ปิดไปอาจมาจาก "หักมัดจำ" ซึ่งไม่มี Payment row ให้ยกเลิก —
            // ข้อความเดิมบอกให้ "ยกเลิกการชำระ" ทำให้ผู้ใช้หาปุ่มไม่เจอ (S-4)
            var srcFromDeposit = src.DepositAppliedAmount > 0.01m;
            throw new InvalidOperationException(
                $"ใบแจ้งหนี้ต้นทาง {src.DocumentNumber} ปิดยอดไปแล้ว ({src.PaidAmount:N2} บาท" +
                (srcFromDeposit ? $" — มาจากการหักมัดจำ {src.DepositAppliedAmount:N2}" : "") + ") — " +
                "การแปลงเป็นใบกำกับภาษีแล้วอนุมัติจะลงรายได้/ภาษีขายซ้ำกับใบแจ้งหนี้เดิม. " +
                (srcFromDeposit
                    ? "ให้ยกเลิกการหักมัดจำที่ใบมัดจำต้นทางก่อน (ไม่ใช่ที่ 'บันทึกชำระเงิน' — ใบนี้ไม่มีรายการรับเงิน) "
                    : "ให้ยกเลิกการชำระก่อน ") +
                "หรือออกใบกำกับภาษีจาก 'ใบเสร็จรับเงิน' ที่รับชำระแทน");
        }
        var otherActiveChild = await _db.Documents.AsNoTracking().AnyAsync(d =>
            d.CompanyId == companyId && d.RelatedDocumentId == src.Id && d.Id != taxInvoice.Id
            && !d.IsDeleted && d.Status != DocumentStatus.Voided && d.Status != DocumentStatus.Rejected);
        if (otherActiveChild)
            throw new InvalidOperationException(
                $"ใบแจ้งหนี้ต้นทาง {src.DocumentNumber} มีเอกสารลูกอื่นอ้างอิงอยู่ (เช่น ใบเสร็จ/ใบลดหนี้) — " +
                "การแปลงเป็นใบกำกับภาษีแล้วอนุมัติจะลงบัญชีซ้ำ. กรุณายกเลิกเอกสารลูกอื่นก่อน หรือออกใบกำกับด้วยวิธีอื่น");

        var jeIds = await _db.JournalEntries
            .Where(j => j.SourceDocumentId == src.Id && j.CompanyId == companyId
                && j.Status == JournalEntryStatus.Posted && j.OriginalEntryId == null)
            .Select(j => j.Id).ToListAsync();
        foreach (var jeId in jeIds)
            await _accountingService.ReverseJournalEntryAsync(companyId, jeId,
                reversalDate: taxInvoice.DocumentDate.Date,
                description: $"แทนที่ด้วยใบกำกับภาษี {taxInvoice.DocumentNumber}", systemTriggered: true);
        // กลับ stock (sale OUT → คืนเข้า) + project billing (ลด)
        await ApplyStockMovementsAsync(companyId, src, -1, actor);
        await ApplyProjectBillingAsync(companyId, src, -1);

        src.Status = DocumentStatus.Voided;
        src.Notes = ((src.Notes ?? "") + $" [แทนที่ด้วยใบกำกับภาษี {taxInvoice.DocumentNumber}]").Trim();
        src.UpdatedAt = DateTime.UtcNow;
        src.UpdatedBy = actor;
        _logger.LogInformation("Superseded Invoice {Src} by TaxInvoice {Tax} (reverse JE+stock+project)",
            src.DocumentNumber, taxInvoice.DocumentNumber);
    }

    /// <summary>ใบแจ้งหนี้บริการที่ VAT พักไว้ 21913 (ภาษีขายรอเรียกเก็บ) — เมื่อ
    /// รับชำระ tax point เกิด (§78/1) → ออก adjusting JE: Dr 21913 / Cr 21911
    /// เต็มยอดคงเหลือ + stamp OutputVatDueAt → ใบเข้า ภ.พ.30 งวดที่รับเงิน.
    ///
    /// GL-driven: อ่านยอดคงเหลือจริงจากขา 21913 ใน JE ของใบ (Cr−Dr) — ใบเก่า/
    /// ใบมีสินค้าที่ลง 21911 ตรง = net 0 → no-op (พฤติกรรมเดิมไม่กระทบ).
    /// full-on-first-settlement: รับชำระงวดแรก (แม้บางส่วน) ถือว่า tax point
    /// เกิดทั้งใบ — ผู้ขายมีหน้าที่ออกใบกำกับเต็มยอด ณ วันรับเงินแรกตามปฏิบัติ
    /// (กันภ.พ.30 กระจายหลายงวดจาก partial จนตามยาก). idempotent ผ่าน
    /// OutputVatDueAt. best-effort — ห้าม throw ทำ settlement พัง.</summary>
    /// <summary>แปลงยอดที่เก็บบนเอกสาร (สกุลเอกสาร) → หน่วยเดียวกับแยกประเภท (บาท)
    ///
    /// ที่มา (P-2): JE ปรับปรุงทุกตัว (ย้ายภาษีซื้อพัก→เคลม, §82/3 พ้น 6 เดือน,
    /// ย้ายผังรายบรรทัด) อ่านยอดจาก DocumentLine ตรง ๆ แล้วเขียนลง GL — ถูกเฉพาะ
    /// ใบสกุลบาท. ใบ USD@35: AutoPost ลง 11640 = 2,450 บาท แต่ตัวย้ายลงแค่ 70
    /// ⇒ 11640 ค้าง 2,380 ตลอดกาล + เคลมภาษีซื้อขาด 97% และธง BecameClaimableAt
    /// ถูกตั้งแล้วจึงแก้ซ้ำไม่ได้ (idempotent guard ปิดทางถาวร)
    ///
    /// ใช้สูตรเดียวกับ Conv() ใน AutoPostToJournalAsync — ปัด 2 ตำแหน่ง away-from-zero</summary>
    /// <summary>บรรทัดที่ส่งมา "ต่างจากที่พิมพ์บนใบเดิม" หรือไม่ — ใช้กับด่าน
    /// §86/4 ของใบที่กู้คืนจากการยกเลิก (ยังถือเลขจริงเดิม).
    ///
    /// <para>เทียบเฉพาะ <b>สิ่งที่ปรากฏบนใบกำกับ</b> ตาม §86/4: รายการ · จำนวน ·
    /// หน่วย · ราคา/หน่วย · ส่วนลด · อัตรา VAT · อัตราหัก ณ ที่จ่าย
    /// — <b>ไม่นับผังบัญชี</b> เพราะรหัสผังไม่เคยพิมพ์อยู่บนเอกสาร การจัดประเภท
    /// ทางบัญชีภายในจึงไม่ใช่การ "แก้ใบกำกับ" (หลักเดียวกับที่เปิดให้
    /// ReclassifyLineAccountAsync ทำได้บนใบที่อนุมัติแล้ว)</para>
    ///
    /// <para>ค่าที่ส่งมาเป็น null = "ไม่ระบุ" → ไม่ถือว่าแก้ (เช่น Unit ที่ฟอร์ม
    /// บางทางไม่ได้ส่ง). ปัดทศนิยม 4 ตำแหน่งก่อนเทียบ กัน noise จากการ
    /// round-trip JSON ทำให้ฟ้องว่าแก้ทั้งที่ตัวเลขเท่าเดิม</para></summary>
    private static bool PrintedLinesChanged(
        IReadOnlyList<DocumentLineRequest> incoming, ICollection<DocumentLine> stored)
    {
        var current = stored.Where(l => !l.IsDeleted).OrderBy(l => l.LineOrder).ToList();
        if (incoming.Count != current.Count) return true;

        static decimal R(decimal v) => Math.Round(v, 4, MidpointRounding.AwayFromZero);

        for (var i = 0; i < current.Count; i++)
        {
            var a = incoming[i];
            var b = current[i];
            if ((a.Description ?? "").Trim() != (b.Description ?? "").Trim()) return true;
            if (R(a.Quantity) != R(b.Quantity)) return true;
            if (R(a.UnitPrice) != R(b.UnitPrice)) return true;
            if (R(a.DiscountPercent) != R(b.DiscountPercent)) return true;
            if (R(a.VatRate) != R(b.VatRate)) return true;
            if (R(a.WithholdingTaxRate) != R(b.WithholdingTaxRate)) return true;
            if (a.Unit != null && a.Unit.Trim() != (b.Unit ?? "").Trim()) return true;
        }
        return false;
    }

    private static decimal ToGlAmount(Document doc, decimal docAmount)
    {
        var fx = doc.ExchangeRate <= 0m ? 1m : doc.ExchangeRate;
        return fx == 1m ? docAmount
            : Math.Round(docAmount * fx, 2, MidpointRounding.AwayFromZero);
    }

    /// <summary>ยอดที่ "บรรทัดนี้" ลงไว้จริงบนผังบัญชีของตัวเองในแยกประเภท (บาท) —
    /// ตัวย้ายผังบัญชีต้องย้ายเท่านี้เป๊ะ ๆ ไม่ใช่ฐานก่อน VAT เสมอ.
    /// <para>ที่มา (P-6): AutoPost ฝั่งซื้อลง <c>Dr = Amount + VatAmount</c> เมื่อ
    /// บรรทัดเป็นภาษีซื้อต้องห้าม (§82/5 — VAT รวมเป็นต้นทุน) การย้ายแค่ฐานทำให้
    /// VAT ค้างอยู่ผังเก่า **ถาวร** โดย Dr=Cr ยังสมดุลจึงไม่มี guard ตัวไหนจับ.</para>
    /// <para>ทางกลับกัน ใบซื้อที่อ้างใบรับของ (GRN) ฐานไปตัด GR-NI ไปแล้ว บรรทัด
    /// เหลือขา Dr แค่ VAT ต้องห้าม — ย้ายทั้งฐานจะเกินจริงเท่าฐานทั้งก้อน.</para>
    /// <para>ใบสำคัญจ่ายที่แปลงมาจากใบตั้งหนี้ = settlement (Dr เจ้าหนี้ / Cr เงินสด)
    /// บรรทัดไม่มีขา Dr เลย → คืน 0 ให้ผู้เรียกแค่เปลี่ยน AccountId ไม่ต้องลง JE.</para>
    /// หลักเดียวกับ "อ่านขาที่ลงจริงแล้วกลับตามนั้น" — สูตรนี้ต้องเดินคู่กับ
    /// <c>AutoPostToJournalAsync</c> เสมอ ถ้าที่นั่นเปลี่ยนสูตร Dr ต้องแก้ที่นี่ด้วย</summary>
    private async Task<decimal> ResolveLinePostedGlAmountAsync(
        Guid companyId, Document doc, DocumentLine line)
    {
        var purchaseSide = doc.DocumentType is DocumentType.PurchaseInvoice
            or DocumentType.Expense or DocumentType.PaymentVoucher;
        if (!purchaseSide) return ToGlAmount(doc, line.Amount);

        // ใบสำคัญจ่ายที่ตัดใบตั้งหนี้ต้นทาง — บรรทัดไม่ได้ลง GL
        if (doc.DocumentType == DocumentType.PaymentVoucher && doc.RelatedDocumentId.HasValue)
            return 0m;

        // ใบซื้อ/ค่าใช้จ่ายที่อ้างใบรับของ — ฐานตัด GR-NI, บรรทัดเหลือแค่ VAT ต้องห้าม
        if (await GetReceivedViaGrnAccrualAccountAsync(companyId, doc) != null)
            return line.IsVatClaimable ? 0m : ToGlAmount(doc, line.VatAmount);

        return ToGlAmount(doc, line.IsVatClaimable ? line.Amount : line.Amount + line.VatAmount);
    }

    /// <summary>กลับรายการ "ภาษีขายถึงกำหนด" เมื่อการรับชำระถูกยกเลิกจนไม่เหลือ
    /// เงินรับเลย — คู่ตรงข้ามของ <see cref="TryReclassifyUndueOutputVatAsync"/>
    ///
    /// ทำอะไร: กลับ JE ที่ย้าย 21913 → 21911 (เลือกด้วย SourceDocumentId + ขา
    /// Dr 21913 จริง ไม่ใช่เดาจาก description) แล้วล้าง OutputVatDueAt เพื่อให้
    /// รับชำระครั้งใหม่ทำ tax point ได้อีก (idempotent guard จะได้ไม่บล็อกถาวร)
    ///
    /// best-effort — ห้าม throw ทำการยกเลิกการชำระพัง แต่ต้อง log ให้ตามได้</summary>
    private async Task TryUndoUndueOutputVatReclassAsync(Guid companyId, Document inv, string reason)
    {
        try
        {
            // JE ที่ต้องกลับ = JE ของใบนี้ที่มีขา **Dr 21913** (ตัดภาษีขายรอเรียกเก็บ)
            // และยังไม่ถูกกลับ — อ่านจาก GL จริงตามหลัก "ห้ามเดาจากข้อความ"
            var reclassJeIds = await (
                from j in _db.JournalEntries
                join l in _db.JournalEntryLines on j.Id equals l.JournalEntryId
                join a in _db.ChartOfAccounts on l.AccountId equals a.Id
                where j.CompanyId == companyId && j.SourceDocumentId == inv.Id
                      && j.Status == JournalEntryStatus.Posted
                      && j.OriginalEntryId == null && j.ReversedByEntryId == null
                      && !j.IsDeleted && !l.IsDeleted
                      && a.AccountCode == "21913" && l.DebitAmount > 0
                select j.Id).Distinct().ToListAsync();

            foreach (var jeId in reclassJeIds)
                await _accountingService.ReverseJournalEntryAsync(companyId, jeId,
                    reversalDate: inv.DocumentDate.Date,
                    description: $"กลับภาษีขายถึงกำหนด (ยกเลิกการรับชำระ) - {inv.DocumentNumber}",
                    systemTriggered: true);

            if (reclassJeIds.Count > 0)
            {
                inv.OutputVatDueAt = null;   // เปิดทางให้ tax point เกิดใหม่ตอนรับเงินครั้งหน้า
                // CN/DN ลูกที่ถูกประทับพร้อมใบเดิม (C-01) ต้องกลับเป็น "ยังพัก" ด้วยกัน
                var stampedChildren = await _db.Documents
                    .Where(d => d.CompanyId == companyId && d.RelatedDocumentId == inv.Id && !d.IsDeleted
                        && (d.DocumentType == DocumentType.CreditNote || d.DocumentType == DocumentType.DebitNote)
                        && d.OutputVatDueAt != null)
                    .ToListAsync();
                foreach (var child in stampedChildren) child.OutputVatDueAt = null;
                _logger.LogInformation(
                    "กลับภาษีขายถึงกำหนดของ {Doc} ({Count} ใบสำคัญ) เพราะ {Reason}",
                    inv.DocumentNumber, reclassJeIds.Count, reason);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "กลับภาษีขายถึงกำหนดของ {Doc} ไม่สำเร็จ — VAT อาจค้างที่ 21911 " +
                "ทั้งที่ยกเลิกการรับชำระแล้ว (ตรวจด้วยเครื่องมือกระทบยอด GL ↔ ภาษี)",
                inv.DocumentNumber);
        }
    }

    private async Task TryReclassifyUndueOutputVatAsync(Guid companyId, Guid invoiceId, DateTime when, string actor)
    {
        try
        {
            var inv = await _db.Documents
                .FirstOrDefaultAsync(d => d.Id == invoiceId && d.CompanyId == companyId
                    && d.DocumentType == DocumentType.Invoice && !d.IsDeleted);
            if (inv == null) return;
            if (inv.OutputVatDueAt != null) return;   // reclass ไปแล้ว
            if (inv.Status is DocumentStatus.Voided or DocumentStatus.Rejected) return;

            // CN/DN ที่อ้างใบแจ้งหนี้บริการใบนี้ ลง VAT ไว้ที่ 21913 ด้วย (AutoPost เลือก
            // vatCode 21913 เมื่อใบเดิมยังพัก) ภายใต้ SourceDocumentId **ของตัวเอง** ⇒ เดิม
            // reclass รวมแค่ JE ของใบแจ้งหนี้ ⇒ VAT ของ DN ค้าง 21913 ถาวร และ ภ.พ.30
            // ไม่เห็น DN เลย (ถูก IsExcluded ตอนใบเดิมยังพัก · เดือนถัดไปหลุด query เพราะ
            // OutputVatDueAt ของ DN เป็น null) · CN ทำให้ยอดที่ย้ายเกินจริง (ERP_REVIEW C-01)
            var childAdjustments = await _db.Documents
                .Where(d => d.CompanyId == companyId && d.RelatedDocumentId == invoiceId && !d.IsDeleted
                    && (d.DocumentType == DocumentType.CreditNote || d.DocumentType == DocumentType.DebitNote)
                    && d.OutputVatDueAt == null
                    && !DocumentStatusRules.NotIssued.Contains(d.Status)
                    && d.Status != DocumentStatus.Voided)
                .ToListAsync();
            var undueSourceIds = new List<Guid> { invoiceId };
            undueSourceIds.AddRange(childAdjustments.Select(c => c.Id));

            var net21913 = await _db.JournalEntryLines
                .Where(l => !l.IsDeleted
                    && l.JournalEntry.CompanyId == companyId
                    && l.JournalEntry.SourceDocumentId != null
                    && undueSourceIds.Contains(l.JournalEntry.SourceDocumentId.Value)
                    && !l.JournalEntry.IsDeleted
                    && (l.JournalEntry.Status == JournalEntryStatus.Posted
                        || l.JournalEntry.Status == JournalEntryStatus.Reversed)
                    && l.Account.AccountCode == "21913")
                .SumAsync(l => (decimal?)(l.CreditAmount - l.DebitAmount)) ?? 0m;
            if (net21913 <= 0.005m) return;   // ไม่มี VAT พักค้าง (ใบเก่า/ลง 21911 ตรง)

            var undueAcc = await FindAccountAsync(companyId, "21913");
            var dueAcc = await FindAccountAsync(companyId, "21911");
            if (undueAcc == null || dueAcc == null)
            {
                _logger.LogWarning(
                    "Reclassify VAT ใบแจ้งหนี้ {Doc}: ผังไม่มี 21913/21911 — VAT {Vat:N2} ค้าง 21913 และยังไม่เข้า ภ.พ.30",
                    inv.DocumentNumber, net21913);
                return;
            }

            var entryNumber = await GetNextJournalEntryNumberAsync(companyId, "JV");
            var period = await ResolveFiscalPeriodAsync(companyId, when);
            // ⚠️ ผลตรวจทีม C · C-03: เดิมใช้ `ResolveFiscalPeriodAsync` เปล่า ๆ
            // (ไม่ดู `Status`) ⇒ ย้าย VAT 21913 → 21911 เข้างวดที่ **ปิดและยื่น
            // ภ.พ.30 ไปแล้ว** ได้ ⇒ งบที่ยื่นกับบัญชีไม่ตรงกันถาวร ขณะที่เส้นลง JE
            // ด้วยมือตรวจอยู่แล้ว = สองมาตรฐานกับข้อมูลชุดเดียวกัน
            //
            // ที่นี่ **ห้าม throw** เพราะเมธอดนี้ถูกเรียกหลังรับชำระเงินสำเร็จแล้ว
            // (การรับเงินเกิดขึ้นจริง ล้มทั้งรายการ = ทิ้งข้อมูลของผู้ใช้) — แต่
            // ก็ห้ามเงียบ: บอกบนตัวเอกสารที่ผู้ใช้เปิดดู + log + คงสถานะพัก
            // เอาไว้ให้ retry ได้เมื่อเปิดงวด (กติกา "ดังใน 3 ที่")
            if (period != null && period.Status != FiscalPeriodStatus.Open)
            {
                var msg = $"[VAT-RECLASS-BLOCKED] ภาษีขาย {net21913:N2} บาทถึงกำหนดวันที่ "
                    + $"{when:yyyy-MM-dd} แต่งวด “{period.Name}” ปิดแล้ว — ยังค้างที่ 21913 "
                    + "และยังไม่เข้า ภ.พ.30 · เปิดงวดแล้วกด “ย้ายภาษีขายถึงกำหนด” อีกครั้ง";
                AppendInternalNote(inv, msg);
                _logger.LogWarning(
                    "Reclassify VAT ใบแจ้งหนี้ {Doc}: งวด {Period} ปิดแล้ว — VAT {Vat:N2} ค้าง 21913",
                    inv.DocumentNumber, period.Name, net21913);
                await _db.SaveChangesAsync();
                return;
            }
            var je = new JournalEntry
            {
                CompanyId = companyId,
                EntryNumber = entryNumber,
                EntryDate = when,
                JournalType = JournalType.General,
                Description = $"ภาษีขายถึงกำหนด (รับชำระ) - {inv.DocumentNumber}",
                Reference = inv.DocumentNumber,
                Status = JournalEntryStatus.Posted,
                TotalDebit = net21913,
                TotalCredit = net21913,
                CreatedBy = actor,
                IsAutoGenerated = true,
                SourceDocumentId = inv.Id,
                FiscalPeriodId = period?.Id,
                ProjectId = inv.ProjectId,
            };
            _db.JournalEntries.Add(je);
            _db.JournalEntryLines.Add(new JournalEntryLine
            {
                JournalEntryId = je.Id, AccountId = undueAcc.Id,
                DebitAmount = net21913, CreditAmount = 0,
                Description = "ตัดภาษีขายรอเรียกเก็บ (tax point เกิด §78/1)", LineOrder = 1,
            });
            _db.JournalEntryLines.Add(new JournalEntryLine
            {
                JournalEntryId = je.Id, AccountId = dueAcc.Id,
                DebitAmount = 0, CreditAmount = net21913,
                Description = "ภาษีขาย ภ.พ.30 (รับชำระใบแจ้งหนี้)", LineOrder = 2,
            });

            inv.OutputVatDueAt = when;   // ภ.พ.30 include งวดนี้
            inv.UpdatedAt = DateTime.UtcNow;
            foreach (var child in childAdjustments)
            {
                child.OutputVatDueAt = when;   // CN/DN เข้า ภ.พ.30 งวดเดียวกับใบเดิม
                child.UpdatedAt = DateTime.UtcNow;
            }
            await _db.SaveChangesAsync();
            _logger.LogInformation(
                "Reclassified undue output VAT {Vat:N2} → 21911 for Invoice {Doc} (+{Children} CN/DN, tax point {When:yyyy-MM-dd})",
                net21913, inv.DocumentNumber, childAdjustments.Count, when);
        }
        catch (Exception ex)
        {
            // settlement ต้องไม่พังเพราะ reclass — VAT จะยังค้าง 21913 และไม่เข้า
            // ภ.พ.30 จนกว่าจะ retry สำเร็จ (เห็นได้จากงบทดลอง 21913 ค้าง)
            _logger.LogError(ex, "TryReclassifyUndueOutputVatAsync ล้มเหลว invoice {Id}", invoiceId);
        }
    }

    /// <summary>ต่อข้อความลง <c>Document.InternalNotes</c> — **ห้ามใช้ `Notes`**
    /// เพราะ `PdfGenerationService.SanitizeNotesForPrint` พิมพ์ `Notes` ลงกระดาษจริง
    /// ⇒ หมายเหตุภายในจะไปโผล่บนใบที่ส่งให้ลูกค้า (บทเรียนใน CLAUDE.md)</summary>
    private static void AppendInternalNote(Document doc, string note)
    {
        if (string.IsNullOrWhiteSpace(note)) return;
        doc.InternalNotes = string.IsNullOrWhiteSpace(doc.InternalNotes)
            ? note
            : doc.InternalNotes.TrimEnd() + "\n\n" + note;
    }

    /// <summary>นโยบายสต๊อกของใบเสร็จ standalone ของบริษัท — อ่านจาก CompanySettings (ไม่มีแถว = ค่า default
    /// ของ entity = MoveStockAndCogs) · กติกาการใช้อยู่ที่ Helpers/CashSaleStockRules</summary>
    private async Task<Models.Enums.CashSaleStockPolicy> GetCashSaleStockPolicyAsync(Guid companyId)
        => await _db.CompanySettings.AsNoTracking()
            .Where(s => s.CompanyId == companyId)
            .Select(s => (Models.Enums.CashSaleStockPolicy?)s.CashSaleStockPolicy)
            .FirstOrDefaultAsync() ?? Models.Enums.CashSaleStockPolicy.MoveStockAndCogs;

    /// <summary>นโยบาย Block: ใบเสร็จ/ใบสำคัญรับ standalone ที่มีบรรทัดสินค้าคงคลัง (TrackStock)
    /// อนุมัติไม่ได้ — บอกทางไปต่อ (ออกใบกำกับภาษี/ใบแจ้งหนี้แทน) · ทำก่อนออกเลข §86/4</summary>
    private async Task EnsureCashSaleStockPolicyAllowsAsync(Guid companyId, Document doc)
    {
        if (!CashSaleStockRules.AppliesTo(doc) || doc.Lines == null) return;
        var policy = await GetCashSaleStockPolicyAsync(companyId);
        if (!CashSaleStockRules.BlocksApproval(policy)) return;
        var codes = doc.Lines.Where(l => !l.IsDeleted && !string.IsNullOrWhiteSpace(l.ProductCode))
            .Select(l => l.ProductCode!).Distinct().ToList();
        if (codes.Count == 0) return;
        var tracked = await _db.Products.AsNoTracking()
            .Where(p => p.CompanyId == companyId && codes.Contains(p.Code) && !p.IsDeleted && p.TrackStock)
            .Select(p => p.Code).ToListAsync();
        if (tracked.Count == 0) return;
        throw new BusinessRuleException(
            $"นโยบายบริษัทไม่ให้ขายสินค้าคงคลัง ({string.Join(", ", tracked.Take(3))}) ด้วยใบเสร็จ/ใบสำคัญรับโดยตรง — "
            + "ให้ออกใบกำกับภาษี (หรือใบแจ้งหนี้แล้วรับชำระ) แทน เพื่อให้สต๊อกและต้นทุนขายถูกตัดครบ · "
            + "เปลี่ยนนโยบายได้ที่ ตั้งค่า → เอกสาร → ใบเสร็จที่ขายสินค้าคงคลัง",
            "CASH-SALE-STOCK-BLOCK");
    }

    private async Task ApplyStockMovementsAsync(Guid companyId, Document doc, int sign, string actor)
    {
        if (sign == 0) return;
        var now = DateTime.UtcNow;

        // ห้ามขยับสต็อกเองอีก (กฎ IStockLedger) · null = DI ไม่ครบ (เทสต์เก่า) →
        // ต้องดังตามกฎ "ห้าม silent no-op": เขียนบนตัวเอกสารที่ผู้ใช้เปิดดู ไม่ใช่ log เฉย ๆ
        if (_stock == null)
        {
            _logger.LogError("ไม่มี IStockLedger — ข้ามการขยับสต็อกของ {Doc}", doc.DocumentNumber);
            AppendInternalNote(doc, $"⚠️ ไม่ได้ขยับสต็อกให้เอกสารนี้ (ระบบสต็อกไม่พร้อม) — ตรวจสอบและปรับสต็อกเอง");
            return;
        }
        // เอกสารผูก **สาขา** ไม่ได้ผูกคลัง — แปลงผ่านตัวกลางตัวเดียว
        var docWarehouseId = await _stock.ResolveWarehouseIdAsync(companyId, doc.BranchId);

        // ===== ขา void (sign<0): กลับตาม movement ที่ "เกิดจริง" =====
        // ไม่ recompute ทิศทางจากกติกาปัจจุบัน — เอกสารเก่าที่เคยขยับสต๊อกด้วย
        // กติกาเดิม (เช่น purchase-CN ที่เคย IN ผิดทิศ, มัดจำที่เคยตัดสต๊อก)
        // จะถูกกลับด้วยยอด/ต้นทุนจริงของมันเสมอ; และ idempotent — reversal
        // movement ผูก DocumentId เดียวกัน ทำให้ net หลัง void = 0 → void ซ้ำ
        // เป็น no-op
        if (sign < 0)
        {
            // ดึง row ดิบแล้ว group ใน memory — GroupBy + First() projection
            // EF Core แปลเป็น SQL ไม่ได้ (movement ต่อเอกสารมีน้อย ไม่หนัก)
            var rows = await _db.StockMovements.AsNoTracking()
                .Where(m => m.CompanyId == companyId && m.DocumentId == doc.Id)
                .Select(m => new { m.ProductId, m.WarehouseId, m.Quantity, m.UnitCost, m.MovementDate })
                .ToListAsync();
            // group ต่อ (สินค้า, คลัง) — ของที่ออกจากคลังไหนต้องคืนเข้าคลังนั้น
            // (group ต่อสินค้าเฉย ๆ จะคืนของทั้งก้อนเข้าคลังเดียวเมื่อใบเดียวแตะหลายคลัง)
            var nets = rows
                .GroupBy(r => new { r.ProductId, r.WarehouseId })
                .Select(g => new
                {
                    g.Key.ProductId,
                    g.Key.WarehouseId,
                    NetQty = g.Sum(x => x.Quantity),
                    OrigCost = g.OrderBy(x => x.MovementDate).First().UnitCost,
                })
                .ToList();
            foreach (var n in nets)
            {
                if (n.NetQty == 0) continue;
                var product = await _db.Products.FirstOrDefaultAsync(
                    p => p.Id == n.ProductId && p.CompanyId == companyId);
                if (product == null) continue;

                var qtyDelta = -n.NetQty;
                await _stock.MoveAsync(new StockMoveRequest(
                    CompanyId: companyId,
                    ProductId: product.Id,
                    Quantity: qtyDelta,
                    MovementType: qtyDelta > 0 ? "IN" : "OUT",
                    Reference: doc.DocumentNumber,
                    // คลังเดียวกับที่ movement ต้นทางลง — เอกสารเดิมผูกสาขาไว้แล้ว
                    WarehouseId: n.WarehouseId ?? docWarehouseId,
                    DocumentId: doc.Id,
                    MovementDate: now,
                    // ต้นทุนเดิมของ movement ต้นทาง — กลับรายการมูลค่าเท่ากันพอดี
                    UnitCostOverride: n.OrigCost,
                    Notes: $"กลับรายการจากการยกเลิก {doc.DocumentType} เลขที่ {doc.DocumentNumber}",
                    CreatedBy: actor,
                    // การกลับรายการต้องผ่านด่านสต็อกติดลบเสมอ — ไม่ใช่การตัดสินใจใหม่
                    // แต่คือการลบสิ่งที่เคยลงไว้ · ถ้าบล็อก ใบซื้อที่ของถูกขายออกไปแล้ว
                    // จะยกเลิกไม่ได้ตลอดกาล = ด่านที่ไม่มีทางไปต่อ (D5-6)
                    AllowNegativeOverride: true));

                // WAC ต้อง rebuild หลัง void ซื้อ (audit A5): เดิมปรับแค่ CurrentStock
                // → avg ค้างค่าที่รวมล็อตที่ยกเลิกแล้ว → COGS ขายถัดไปผิด + 11500
                // ไม่ตรงของจริง. rebuild เดินจาก movement ทั้งหมด (รวม reversal นี้)
                if (_inventoryCosting != null
                    && product.CostingMethod == Models.Enums.CostingMethod.WeightedAverage)
                {
                    try { await _inventoryCosting.RebuildAverageCostAsync(product.Id); }
                    catch (Exception ex)
                    {
                        _logger.LogWarning(ex, "Rebuild WAC หลัง void {Doc} ล้มเหลว (product {Product})",
                            doc.DocumentNumber, product.Code);
                    }
                }
            }
            return;
        }

        // ===== ขาไปข้างหน้า (sign>0) =====
        // DeliveryNote intentionally NOT triggered here — when a tenant uses
        // the full Quotation → SO → DN → Invoice chain, the Invoice is the
        // financial recognition and triggers the stock move. Issuing the DN
        // alone shouldn't double-count if the Invoice follows.
        int direction = doc.DocumentType switch
        {
            DocumentType.Invoice or DocumentType.TaxInvoice => -1,  // sale OUT
            // Goods physically arrive at the GRN (3-way match) — stock moves
            // IN there. A PurchaseInvoice raised against that GRN must NOT
            // move stock again (handled below); a STANDALONE PurchaseInvoice
            // (no GRN) still moves stock IN itself.
            DocumentType.GoodsReceiptNote => +1,
            DocumentType.PurchaseInvoice => +1,                     // purchase IN
            // CreditNote only restocks when reason = Return (goods physically
            // came back). Discount / Adjustment / Writeoff are pure financial
            // adjustments — sticks were never returned and inventory must
            // stay flat. The CreditNoteReason field is required by Create
            // for CN; older grandfathered rows with NULL fall to 0 (no move).
            DocumentType.CreditNote when doc.CreditNoteReason == Models.Enums.CreditNoteReason.Return => +1,
            // ใบเพิ่มหนี้ขยับสต๊อกเฉพาะเหตุผล "ส่งสินค้า/บริการเกินกว่าที่ตกลง"
            // (ของเคลื่อนจริง) — สมมาตรกับ CN Return. ราคาเพิ่ม/ค่าใช้จ่ายเพิ่ม/
            // ปรับยอด เป็นการปรับตัวเงินล้วน ของไม่ได้ขยับ สต๊อกต้องนิ่ง.
            // ใบเก่าที่ยังไม่มีเหตุผล (NULL) ตกที่ 0 → พฤติกรรมเดิมไม่เปลี่ยน
            DocumentType.DebitNote when doc.DebitNoteReason == Models.Enums.DebitNoteReason.ExtraGoods => -1,
            _ => 0,
        };
        // ⚠️ ทิศของ CN/DN ข้างบนเขียนจากมุม **ฝั่งขาย** — CN Return = ลูกค้าคืนของ
        // เข้ามา (+1) · DN ExtraGoods = เราส่งของเพิ่มออกไป (−1) · แต่ CN/DN เป็น
        // ชนิด `BothSides` (`Helpers/DocumentSide`) และเส้น JE อ่าน
        // `CnDnPurchaseSideOverride` อยู่แล้ว **ส่วนเส้นสต๊อกไม่เคยอ่านเลย**
        // (ผลตรวจทีม C · C-04) ⇒ ใบลดหนี้ที่เรา**คืนของให้ผู้ขาย** กลับ
        // **เพิ่ม**สต๊อกแทนที่จะลด และใบเพิ่มหนี้ที่ผู้ขาย**ส่งของเพิ่มมาให้เรา**
        // กลับ**ลด**สต๊อก ⇒ ยอดคงเหลือเพี้ยนสองเท่าของจำนวนที่คืน/รับเพิ่ม
        if (direction != 0
            && doc.DocumentType is DocumentType.CreditNote or DocumentType.DebitNote
            && doc.CnDnPurchaseSideOverride == true)
            direction = -direction;
        // ใบเสร็จ/ใบสำคัญรับ standalone ที่ขายสินค้าคงคลังโดยตรง — ตามนโยบายบริษัท
        // (CashSaleStockPolicy) เดิมตกที่ `_ => 0` เสมอ ⇒ ลงรายได้แต่สต๊อกไม่ลด (ERP_REVIEW A-06)
        if (direction == 0 && CashSaleStockRules.AppliesTo(doc))
            direction = CashSaleStockRules.StockDirection(await GetCashSaleStockPolicyAsync(companyId));
        if (direction == 0) return;

        // ใบเพิ่มหนี้ "ฝั่งซื้อ" แบบผู้ขายส่งของเกิน (source = PI/Expense/CIL):
        // ของเข้าสต๊อกเราเพิ่ม (+1) ตรงข้ามกับฝั่งขายที่ของออก (−1).
        // อ้าง PV/Receipt/RV → ไม่แตะสต๊อก (ไม่มีขาแรกให้ต่อ เหมือนกติกาของ CN)
        if (doc.DocumentType == DocumentType.DebitNote && doc.RelatedDocumentId.HasValue)
        {
            var dnSrcType = await _db.Documents.AsNoTracking()
                .Where(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId)
                .Select(d => (DocumentType?)d.DocumentType)
                .FirstOrDefaultAsync();
            if (dnSrcType is DocumentType.PurchaseInvoice or DocumentType.Expense
                or DocumentType.CertificateInLieu)
                direction = +1;
            else if (dnSrcType is DocumentType.PaymentVoucher
                or DocumentType.Receipt or DocumentType.ReceiptVoucher)
                direction = 0;
            if (direction == 0) return;
        }

        // ใบลดหนี้ "ฝั่งซื้อ" แบบรับคืน (source = PI/Expense/CIL):
        // เราคืนของให้ vendor → ของออกจากสต๊อกเรา (−1) ไม่ใช่รับเข้า (+1).
        // ยกเว้น source = PV standalone: PV ไม่เคยรับของเข้าสต๊อก (IN มีแค่
        // GRN/PI) → CN ห้ามตัดออก ไม่งั้นสต๊อกติดลบโดยไม่มีขารับ (JE/VAT
        // ยังลงฝั่งซื้อครบตาม AutoPost — แค่ไม่แตะ stock)
        if (doc.DocumentType == DocumentType.CreditNote && doc.RelatedDocumentId.HasValue)
        {
            var srcType = await _db.Documents.AsNoTracking()
                .Where(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId)
                .Select(d => (DocumentType?)d.DocumentType)
                .FirstOrDefaultAsync();
            if (srcType is DocumentType.PurchaseInvoice or DocumentType.Expense
                or DocumentType.CertificateInLieu)
                direction = -1;
            // PV/Receipt/RV ไม่เคยขยับสต๊อกตอนซื้อ/ขาย (IN มีแค่ GRN/PI,
            // OUT มีแค่ Invoice/TaxInvoice) → CN ที่อ้างห้าม restock (+1)
            // และห้ามตัดออก (−1) — ไม่มีขาแรกให้กลับ. เดิม comment บอก
            // "ไม่แตะ stock" แต่โค้ดปล่อย +1 จาก switch ค้างไว้ → CN Return
            // ที่อ้าง PV เพิ่มสต๊อกผี
            else if (srcType is DocumentType.PaymentVoucher
                or DocumentType.Receipt or DocumentType.ReceiptVoucher)
                direction = 0;
        }
        // CN ที่ "ไม่มีใบต้นทางเลย" แต่คู่ค้าเป็น supplier อย่างเดียว
        // (= ฝั่งซื้อแน่นอน ตามชั้นสุดท้ายของ AutoPost): ห้าม +1 รับของเข้า
        // (เราคืนของให้ผู้ขาย ไม่ใช่รับคืนจากลูกค้า) และห้าม −1 ด้วย —
        // ไม่มีขา IN ในระบบให้กลับ (ของอาจไม่เคยเข้าสต๊อกผ่านระบบ)
        // → ไม่แตะสต๊อก; JE/VAT ยังลงฝั่งซื้อครบตาม AutoPost
        else if (doc.DocumentType == DocumentType.CreditNote)
        {
            var supplierOnly = await _db.Contacts.AsNoTracking()
                .Where(c => c.Id == doc.ContactId)
                .Select(c => (bool?)(c.IsSupplier && !c.IsCustomer))
                .FirstOrDefaultAsync() ?? false;
            if (supplierOnly) direction = 0;
        }
        if (direction == 0) return;

        // มัดจำ (IsDeposit): เงินรับล่วงหน้า — ยังไม่ส่งมอบสินค้า → สต๊อกต้อง
        // ไม่ขยับ (สอดคล้องกับ COGS ที่ข้าม IsDeposit ใน AutoPostToJournalAsync
        // — ใบส่งมอบจริงที่ตามมาเป็นผู้ตัดสต๊อก + ลง COGS)
        if (doc.IsDeposit) return;

        // PurchaseInvoice billed against an accrued GRN → goods already
        // stocked at receipt; don't double-count them now.
        if (doc.DocumentType == DocumentType.PurchaseInvoice
            && await GetReceivedViaGrnAccrualAccountAsync(companyId, doc) != null)
            return;
        if (doc.Lines == null) return;

        // Pre-load the full set of products this document touches in one
        // query — avoids N+1 on long invoices.
        var codes = doc.Lines
            .Where(l => !string.IsNullOrWhiteSpace(l.ProductCode))
            .Select(l => l.ProductCode!)
            .Distinct()
            .ToList();
        if (codes.Count == 0) return;

        var products = await _db.Products
            .Where(p => p.CompanyId == companyId && codes.Contains(p.Code) && !p.IsDeleted)
            .ToDictionaryAsync(p => p.Code);

        // Landed cost (PI/GRN): บรรทัด IsLandedCost (ค่าขนส่ง/อากร/ประกัน)
        // เกลี่ยเข้าต้นทุนบรรทัดสินค้า TrackStock ถ่วงตามมูลค่า line —
        // TFRS NPAEs บทที่ 8: cost of purchase รวมต้นทุนจัดหาจนพร้อมขาย
        var landedTotal = 0m;
        var stockLineBase = 0m;
        if (doc.DocumentType is DocumentType.PurchaseInvoice or DocumentType.GoodsReceiptNote)
        {
            landedTotal = doc.Lines.Where(l => l.IsLandedCost).Sum(l => l.Amount);
            stockLineBase = doc.Lines
                .Where(l => !l.IsLandedCost && !string.IsNullOrWhiteSpace(l.ProductCode)
                    && products.TryGetValue(l.ProductCode!, out var pp) && pp.TrackStock)
                .Sum(l => l.Amount);
        }

        foreach (var line in doc.Lines)
        {
            if (line.IsLandedCost) continue;   // ไม่ใช่สินค้า — มูลค่าถูกเกลี่ยแล้ว
            if (string.IsNullOrWhiteSpace(line.ProductCode)) continue;
            if (!products.TryGetValue(line.ProductCode!, out var product)) continue;
            if (!product.TrackStock) continue;

            var qtyDelta = direction * line.Quantity;

            // ต้นทุนต่อหน่วยของ movement (TFRS NPAEs บทที่ 8 — ตาม CostingMethod):
            //   • ซื้อเข้า (PI/GRN IN) → ต้นทุนจริงที่จ่าย (line net ต่อหน่วย)
            //     + อัปเดต WAC running average ก่อน stock เพิ่ม
            //   • ขายออก / รับคืน / คืน vendor → WAC ปัจจุบัน (EffectiveUnitCost)
            decimal unitCost;
            if (qtyDelta > 0 && doc.DocumentType is DocumentType.PurchaseInvoice or DocumentType.GoodsReceiptNote)
            {
                // เกลี่ย landed cost ตามสัดส่วนมูลค่า line ของบรรทัดนี้
                var landedShare = (landedTotal > 0 && stockLineBase > 0)
                    ? landedTotal * (line.Amount / stockLineBase)
                    : 0m;
                var receiptCost = line.Quantity > 0
                    ? Math.Round((line.Amount + landedShare) / line.Quantity, 4, MidpointRounding.AwayFromZero)
                    : line.UnitPrice;
                // ค่าเฉลี่ยถัวน้ำหนักปรับที่ ledger (สูตรกลาง `WeightedAverageCost`) —
                // เดิมคำนวณซ้ำ inline ที่นี่ = สำเนาสูตรชุดที่สาม
                unitCost = receiptCost > 0 ? receiptCost : product.CostPrice;
            }
            else
            {
                // ขายออก → FIFO layer / WAC ตาม CostingMethod; รับคืน (IN
                // ที่ไม่ใช่ซื้อ) → WAC ปัจจุบัน
                unitCost = qtyDelta < 0
                    ? await ResolveOutboundUnitCostAsync(product, -qtyDelta)
                    : EffectiveUnitCost(product);
            }

            await _stock.MoveAsync(new StockMoveRequest(
                CompanyId: companyId,
                ProductId: product.Id,
                Quantity: qtyDelta,
                // MovementType is informational for reports — we tag based on
                // direction so "IN" / "OUT" reads naturally even on a void.
                MovementType: qtyDelta > 0 ? "IN" : "OUT",
                Reference: doc.DocumentNumber,
                WarehouseId: docWarehouseId,
                DocumentId: doc.Id,
                MovementDate: now,
                UnitCostOverride: unitCost,
                Notes: $"จาก {doc.DocumentType} เลขที่ {doc.DocumentNumber}",
                CreatedBy: actor));
        }
    }

    /// <summary>Commitment control: ต่อบัญชีใน PO นี้ — actual (GL Dr−Cr
    /// ปีงบ) + committed (PO Approved/Sent อื่นที่ยังเปิด) + ใบนี้ เทียบ
    /// budget (Budget.IsActive ของปี, company-wide). คืน null = ไม่เกิน,
    /// มิฉะนั้นข้อความรายบัญชีที่เกิน</summary>
    private async Task<string?> CheckBudgetCommitmentAsync(Guid companyId, Document doc)
    {
        var year = doc.DocumentDate.Year;
        var budget = await _db.Budgets.AsNoTracking()
            .Include(b => b.Lines)
            .Where(b => b.CompanyId == companyId && b.IsActive
                && b.FiscalYear == year && b.ProjectId == null)
            .OrderByDescending(b => b.CreatedAt)
            .FirstOrDefaultAsync();
        if (budget == null || doc.Lines == null) return null;
        var budgetByAccount = budget.Lines
            .GroupBy(l => l.AccountId)
            .ToDictionary(g => g.Key, g => g.Sum(l => l.TotalBudget));

        var accIds = doc.Lines
            .Where(l => l.AccountId.HasValue && budgetByAccount.ContainsKey(l.AccountId.Value))
            .Select(l => l.AccountId!.Value).Distinct().ToList();
        if (accIds.Count == 0) return null;

        var yearStart = new DateTime(year, 1, 1);
        var yearEnd = new DateTime(year, 12, 31);
        var actuals = await _db.JournalEntryLines.AsNoTracking()
            .Where(l => l.JournalEntry.CompanyId == companyId
                && l.JournalEntry.Status == JournalEntryStatus.Posted
                && l.JournalEntry.EntryDate >= yearStart && l.JournalEntry.EntryDate <= yearEnd
                && accIds.Contains(l.AccountId))
            .GroupBy(l => l.AccountId)
            .Select(g => new { AccountId = g.Key, Amount = g.Sum(x => x.DebitAmount - x.CreditAmount) })
            .ToListAsync();
        var actualBy = actuals.ToDictionary(a => a.AccountId, a => a.Amount);

        // committed = PO เปิดค้างใบอื่น (Approved/Sent) ปีเดียวกัน — v1 นับ
        // เต็ม line (ยังไม่หักส่วนที่แปลงเป็น PI แล้ว — conservative)
        var committedRows = await _db.DocumentLines.AsNoTracking()
            .Where(l => l.Document.CompanyId == companyId
                && l.Document.DocumentType == DocumentType.PurchaseOrder
                && (l.Document.Status == DocumentStatus.Approved || l.Document.Status == DocumentStatus.Sent)
                && !l.Document.IsDeleted
                && l.Document.DocumentDate >= yearStart && l.Document.DocumentDate <= yearEnd
                && l.Document.Id != doc.Id
                && l.AccountId != null && accIds.Contains(l.AccountId.Value))
            .GroupBy(l => l.AccountId!.Value)
            .Select(g => new { AccountId = g.Key, Amount = g.Sum(x => x.Amount) })
            .ToListAsync();
        var committedBy = committedRows.ToDictionary(a => a.AccountId, a => a.Amount);

        var over = new List<string>();
        foreach (var accId in accIds)
        {
            var cap = budgetByAccount[accId];
            if (cap <= 0) continue;
            var thisPo = doc.Lines.Where(l => l.AccountId == accId).Sum(l => l.Amount);
            var used = actualBy.GetValueOrDefault(accId)
                + committedBy.GetValueOrDefault(accId) + thisPo;
            if (used > cap)
            {
                var accLabel = await _db.ChartOfAccounts.AsNoTracking()
                    .Where(a => a.Id == accId)
                    .Select(a => a.AccountCode + " " + a.AccountName)
                    .FirstOrDefaultAsync() ?? accId.ToString();
                over.Add($"{accLabel}: ใช้จริง+ผูกพัน {used:N2} เกินงบ {cap:N2}");
            }
        }
        return over.Count == 0 ? null
            : "เกินวงเงินงบประมาณ (commitment control): " + string.Join("; ", over);
    }

    /// <summary>ต้นทุนต่อหน่วยตาม CostingMethod (คู่กับ helper เดียวกันฝั่ง POS):
    /// WeightedAverage → running average, อื่น ๆ → CostPrice</summary>
    private static decimal EffectiveUnitCost(Product p) =>
        p.CostingMethod == Models.Enums.CostingMethod.WeightedAverage && p.AverageUnitCost > 0
            ? p.AverageUnitCost : p.CostPrice;

    /// <summary>ต้นทุนขายออกต่อหน่วย — FIFO เดิน layer จริงผ่าน
    /// InventoryCostingService (คำนวณ "ก่อน" movement ของเอกสารนี้ถูก insert
    /// → COGS JE กับ movement stamp ได้ค่าเดียวกัน deterministic)
    ///
    /// <para>⚠️ คอมเมนต์เดิมเขียนว่า "negative-stock guard ของ service ถูก catch →
    /// ไม่ block การอนุมัติ" — <b>ไม่จริงอีกแล้ว</b> ตั้งแต่ D5-6: ด่านสต็อกติดลบย้ายไป
    /// อยู่ที่ <c>StockLedger.MoveAsync</c> (รันทุกกรณี บล็อกจริง) · เมธอดนี้เหลือหน้าที่
    /// เดียวคือ "ต้นทุนเท่าไร" และ <c>catch</c> ข้างล่างกันเฉพาะ error ของการคิดต้นทุน
    /// แล้ว fallback เป็น WAC/CostPrice</para></summary>
    private async Task<decimal> ResolveOutboundUnitCostAsync(Product product, decimal qty)
    {
        if (product.CostingMethod == Models.Enums.CostingMethod.Fifo
            && _inventoryCosting != null && qty > 0)
        {
            try
            {
                var fifoCost = await _inventoryCosting.ResolveOutboundCostAsync(product.Id, qty);
                if (fifoCost > 0) return fifoCost;
            }
            catch (InvalidOperationException ex)
            {
                _logger.LogWarning(ex,
                    "FIFO outbound cost fallback for product {Code} qty {Qty} — ใช้ WAC/CostPrice แทน",
                    product.Code, qty);
            }
        }
        return EffectiveUnitCost(product);
    }

    /// <summary>Perpetual inventory ฝั่งซื้อ: บรรทัดสินค้า TrackStock ที่ user
    /// ไม่ได้เลือกบัญชีเอง default เข้า "สินค้าคงเหลือ" (Product.InventoryAccountId
    /// → 11500/115) แทนค่าใช้จ่าย — สมมาตรกับ COGS ที่ Cr 11500 ตอนขาย
    /// (ไม่งั้นซื้อลง expense + ขายลง COGS = ต้นทุนเข้า P&L สองรอบ และ 11500
    /// มีแต่ฝั่ง Cr จนติดลบ). line ที่ user เลือกบัญชีเองชนะเสมอ; สินค้าที่ไม่
    /// track stock / บริการ ใช้ default ค่าใช้จ่ายตามเดิม</summary>
    private async Task<Func<DocumentLine, Guid?>> BuildPurchaseLineAccountResolverAsync(
        Guid companyId, Document doc, Guid? defaultExpenseId)
    {
        var codes = doc.Lines?
            .Where(l => !string.IsNullOrWhiteSpace(l.ProductCode))
            .Select(l => l.ProductCode!)
            .Distinct()
            .ToList() ?? new List<string>();

        var tracked = new Dictionary<string, Product>();
        if (codes.Count > 0)
            tracked = await _db.Products.AsNoTracking()
                .Where(p => p.CompanyId == companyId && codes.Contains(p.Code)
                    && !p.IsDeleted && p.TrackStock)
                .ToDictionaryAsync(p => p.Code);

        Guid? invDefaultId = null;
        Guid? suppliesDefaultId = null;
        if (tracked.Count > 0)
        {
            invDefaultId = (await FindAccountAsync(companyId, "11500")
                ?? await FindAccountAsync(companyId, "115"))?.Id;
            // ★ D5-2: บัญชีคุม "วัสดุสิ้นเปลือง" — โหลดเฉพาะเมื่อมีบรรทัดที่เป็น
            // Supplies จริง (ไม่งั้นเป็น query ที่ไม่มีใครใช้ทุกใบ)
            if (tracked.Values.Any(p => p.ProductType == Models.Enums.ProductType.Supplies))
                suppliesDefaultId = (await FindAccountAsync(companyId,
                    Accounting.Helpers.InventoryControlAccount.DefaultAccountPrefix(
                        Models.Enums.ProductType.Supplies)))?.Id;
        }

        // landed cost ต้องเข้า 115 ด้วย (มูลค่าถูกเกลี่ยเข้าต้นทุนสินค้าแล้ว
        // — ถ้าลงเป็นค่าใช้จ่ายจะ double: expense + COGS ที่แพงขึ้น)
        Guid? invForLanded = invDefaultId;
        if (invForLanded == null && doc.Lines?.Any(l => l.IsLandedCost) == true)
            invForLanded = (await FindAccountAsync(companyId, "11500")
                ?? await FindAccountAsync(companyId, "115"))?.Id;

        return line =>
        {
            if (line.AccountId.HasValue) return line.AccountId;
            if (line.IsLandedCost)
                return invForLanded ?? defaultExpenseId;
            if (!string.IsNullOrWhiteSpace(line.ProductCode)
                && tracked.TryGetValue(line.ProductCode!, out var prod))
                // ★ D5-2: ฝั่งซื้อกับฝั่งเบิกใช้ต้องถามผังจาก**ตัวตัดสินเดียวกัน**
                // เดิมซื้อวัสดุสิ้นเปลืองลง Dr 11500 (สินค้าคงเหลือ) แต่ตอนเบิกใช้
                // Cr 118xx (วัสดุ) ⇒ สองบัญชีไม่มีวันหักล้าง 11500 บวมถาวร
                return Accounting.Helpers.InventoryControlAccount.Resolve(
                    prod.ProductType, prod.InventoryAccountId, prod.SuppliesAccountId,
                    invDefaultId, suppliesDefaultId) ?? defaultExpenseId;
            return defaultExpenseId;
        };
    }

    /// <summary>รวมต้นทุนขาย (THB) ของบรรทัดสินค้า TrackStock ในเอกสาร —
    /// ใช้ EffectiveUnitCost ให้ตรงกับ UnitCost ที่ stock movement stamp
    /// เพื่อให้ COGS JE กับมูลค่าสต๊อกที่ตัดหักล้างกันพอดี</summary>
    private async Task<decimal> ComputeSalesCogsAsync(Guid companyId, Document doc, bool outbound = true)
    {
        if (doc.Lines == null) return 0m;
        var codes = doc.Lines
            .Where(l => !string.IsNullOrWhiteSpace(l.ProductCode))
            .Select(l => l.ProductCode!)
            .Distinct()
            .ToList();
        if (codes.Count == 0) return 0m;

        var products = await _db.Products.AsNoTracking()
            .Where(p => p.CompanyId == companyId && codes.Contains(p.Code)
                && !p.IsDeleted && p.TrackStock)
            .ToDictionaryAsync(p => p.Code);

        decimal total = 0m;
        foreach (var line in doc.Lines)
        {
            if (string.IsNullOrWhiteSpace(line.ProductCode)) continue;
            if (!products.TryGetValue(line.ProductCode!, out var product)) continue;
            // FIFO/WAC — resolver เดียวกับ movement stamp เพื่อให้ COGS JE
            // หักล้างมูลค่าสต๊อกพอดี; ขารับคืน (CN Return) เป็น IN → WAC
            var lineUnitCost = outbound
                ? await ResolveOutboundUnitCostAsync(product, line.Quantity)
                : EffectiveUnitCost(product);
            total += lineUnitCost * line.Quantity;
        }
        return Math.Round(total, 2, MidpointRounding.AwayFromZero);
    }

    private async Task AutoPostToJournalAsync(Guid companyId, Document doc, string createdBy)
    {
        // Multi-currency: every Baht amount that hits the GL must be converted
        // from the document's currency at the rate captured on Create. Validate
        // the rate is sane (positive, finite, non-zero) — corrupt FX = corrupt GL.
        if (doc.ExchangeRate <= 0m)
            throw new InvalidOperationException(
                $"อัตราแลกเปลี่ยนไม่ถูกต้อง ({doc.ExchangeRate}) — กรุณาแก้ไขเอกสารและระบุอัตราที่ถูกต้องก่อนอนุมัติ");
        if (!string.Equals(doc.Currency, "THB", StringComparison.OrdinalIgnoreCase) && doc.ExchangeRate == 1m)
            throw new InvalidOperationException(
                $"เอกสารสกุลเงิน {doc.Currency} ต้องระบุอัตราแลกเปลี่ยนก่อนอนุมัติ (พบ ExchangeRate = 1)");

        // WHT recognition basis (per CompanySettings):
        //   Cash    = recognize at Receipt / PaymentVoucher (strict §50/§52)
        //   Accrual = recognize at Invoice / PurchaseInvoice approval
        // Default for new tenants is Cash. Existing tenants stay Accrual to
        // keep their historical GL consistent. Cash-side documents (cash
        // sale Receipt without RelatedDoc) always post WHT here either way
        // because there's no later cash event.
        var whtSettings = await _db.CompanySettings.AsNoTracking()
            .FirstOrDefaultAsync(s => s.CompanyId == companyId);
        var whtBasis = whtSettings?.WhtRecognitionBasis ?? Models.Enums.WhtRecognitionBasis.Cash;

        // Resolve default fallback accounts up front — used when document lines
        // have no explicit AccountId (the UI doesn't expose per-line account selection yet).
        // The default Thai chart uses 41000 (sales) / 42000 (service) at level 4;
        // industry templates may override (e.g. hospitality uses 411xx). Pick the first
        // posting-level (Level >= 4) Revenue/Expense account by code as a safe default.
        var defaultRevenue = await FindAccountAsync(companyId, "41000")
            ?? await FindAccountAsync(companyId, "42000")
            ?? await _db.ChartOfAccounts
                .Where(a => a.CompanyId == companyId && a.AccountType == AccountType.Revenue && a.Level >= 4 && a.IsActive)
                .OrderBy(a => a.AccountCode)
                .FirstOrDefaultAsync();

        // Safety net ขา Cr รายได้: บรรทัดที่ผูกผังหมวด "ค่าใช้จ่าย" มาแต่เดิม
        // (เอกสารเก่าก่อนมี guard ตอนบันทึก หรือลอก AccountId มาตอนแปลงเอกสาร)
        // ห้ามรับรายได้เข้า 5xxxx — ตกกลับบัญชีรายได้มาตรฐาน + log ให้ตามแก้.
        // ใช้เฉพาะจุดที่ลงขา "รายได้" (ฝั่งขาย) — ขาค่าใช้จ่ายฝั่งซื้อไม่แตะ
        var docLineAcctIds = doc.Lines.Where(l => l.AccountId.HasValue)
            .Select(l => l.AccountId!.Value).Distinct().ToList();
        var expenseTypedLineAccts = docLineAcctIds.Count == 0
            ? new HashSet<Guid>()
            : (await _db.ChartOfAccounts.AsNoTracking()
                .Where(a => a.CompanyId == companyId && docLineAcctIds.Contains(a.Id)
                    && a.AccountType == AccountType.Expense)
                .Select(a => a.Id).ToListAsync()).ToHashSet();
        Guid? RevenueLegAccountId(DocumentLine l)
        {
            if (l.AccountId.HasValue && expenseTypedLineAccts.Contains(l.AccountId.Value))
            {
                _logger.LogWarning(
                    "เอกสาร {DocNo} บรรทัด '{Desc}' ผูกผังหมวดค่าใช้จ่ายไว้บนขารายได้ — ตกกลับบัญชีรายได้มาตรฐานแทน",
                    doc.DocumentNumber, l.Description);
                return defaultRevenue?.Id;
            }
            return l.AccountId ?? defaultRevenue?.Id;
        }

        // Use document-level expense category if specified, otherwise fallback to default
        ChartOfAccount? defaultExpense = null;
        if (doc.ExpenseCategoryId.HasValue)
        {
            defaultExpense = await _db.ChartOfAccounts
                .FirstOrDefaultAsync(a => a.Id == doc.ExpenseCategoryId.Value && a.CompanyId == companyId);
        }
        defaultExpense ??= await FindAccountAsync(companyId, "51110")
            ?? await FindAccountAsync(companyId, "52110")
            ?? await _db.ChartOfAccounts
                .Where(a => a.CompanyId == companyId && a.AccountType == AccountType.Expense && a.Level >= 4 && a.IsActive)
                .OrderBy(a => a.AccountCode)
                .FirstOrDefaultAsync();

        // Resolve money account for cash/bank movement entries.
        // Priority: PaymentAccountId (direct GL) > BankAccountId (bank's linked GL) > Cash 111
        ChartOfAccount? moneyAccount = null;
        if (doc.PaymentAccountId.HasValue)
        {
            moneyAccount = await _db.ChartOfAccounts
                .FirstOrDefaultAsync(a => a.Id == doc.PaymentAccountId.Value && a.CompanyId == companyId);
        }
        if (moneyAccount == null && doc.BankAccountId.HasValue)
        {
            var bankAcc = await _db.BankAccounts
                .Include(b => b.LinkedAccount)
                .FirstOrDefaultAsync(b => b.Id == doc.BankAccountId.Value && b.CompanyId == companyId);
            moneyAccount = bankAcc?.LinkedAccount;
        }
        moneyAccount ??= await FindAccountAsync(companyId, "111");

        // Validate critical accounts exist — fail fast with clear error
        var isSalesDoc = doc.DocumentType is DocumentType.Invoice or DocumentType.TaxInvoice
            or DocumentType.DebitNote or DocumentType.CreditNote
            or DocumentType.Receipt or DocumentType.ReceiptVoucher;
        if (isSalesDoc && defaultRevenue == null)
            throw new InvalidOperationException(
                "ไม่พบบัญชีรายได้ (41000/42000) ในผังบัญชี — กรุณาเพิ่มบัญชีรายได้ก่อนอนุมัติเอกสารขาย");
        if (!isSalesDoc && defaultExpense == null)
            throw new InvalidOperationException(
                "ไม่พบบัญชีค่าใช้จ่าย (51110/52110) ในผังบัญชี — กรุณาเพิ่มบัญชีค่าใช้จ่ายก่อนอนุมัติเอกสารซื้อ");

        var pendingLines = new List<(Guid AccountId, decimal Debit, decimal Credit, string? Description)>();
        JournalType journalType;
        // ProjectId map: each pendingLines index → resolved project. System-generated
        // lines (AR/VAT/Cash/AP/WHT) inherit doc.ProjectId; per-line revenue/expense
        // can override via docLine.ProjectId.
        var lineProjects = new List<Guid?>();
        // Multi-currency: every amount fed into AddLine is in the document's
        // currency. Convert to THB (base) at the captured rate; AwayFromZero
        // to match the system-wide rounding convention.
        var fx = doc.ExchangeRate;
        decimal Conv(decimal amount) => fx == 1m ? amount : Math.Round(amount * fx, 2, MidpointRounding.AwayFromZero);
        void AddLine(Guid accountId, decimal debit, decimal credit, string? desc, Guid? proj = null)
        {
            pendingLines.Add((accountId, Conv(debit), Conv(credit), desc));
            lineProjects.Add(proj ?? doc.ProjectId);
        }

        // ============================================================
        // SALES SIDE: Invoice / TaxInvoice (full sale on credit)
        // ============================================================
        if ((doc.DocumentType == DocumentType.Invoice
             || doc.DocumentType == DocumentType.TaxInvoice)
            && !doc.IssuedAsCashReceipt)   // cash-sale TaxInvoice ลงแบบเงินสด (branch ล่าง) ไม่ตั้งลูกหนี้
        {
            journalType = JournalType.Sales;

            // Dr: ลูกหนี้การค้า (113). On Accrual basis the AR balance is NET
            // of WHT (gross - WHT) so the WHT-Asset can be booked alongside.
            // On Cash basis the AR balance is GROSS (full amount) and WHT
            // isn't recognized here — it's recognized when the customer
            // actually pays and withholds (Receipt path below).
            var arAccount = await FindAccountAsync(companyId, "113", doc.Contact);
            var arAmountAtInvoice = whtBasis == Models.Enums.WhtRecognitionBasis.Cash
                ? doc.TotalAmount + doc.WithholdingTaxAmount
                : doc.TotalAmount;
            if (arAccount != null)
                AddLine(arAccount.Id, arAmountAtInvoice, 0, $"ลูกหนี้การค้า - {doc.DocumentNumber}");

            // Dr: ภาษีถูกหัก ณ ที่จ่าย (11910). Only fires on Accrual basis
            // — Cash basis defers this to the Receipt that actually collects.
            if (whtBasis == Models.Enums.WhtRecognitionBasis.Accrual && doc.WithholdingTaxAmount > 0)
            {
                var whtAccount = await FindAccountAsync(companyId, "11910");
                if (whtAccount != null)
                    AddLine(whtAccount.Id, doc.WithholdingTaxAmount, 0, "ภาษีหัก ณ ที่จ่าย (ถูกหัก)");
            }

            // Cr: บัญชีรายได้ตามแต่ละบรรทัด (default = 411) — ผังหมวดค่าใช้จ่าย
            // ที่หลงมาบนขานี้ถูกกรองตกกลับ default โดย RevenueLegAccountId
            foreach (var docLine in doc.Lines)
            {
                var revenueAccountId = RevenueLegAccountId(docLine);
                if (revenueAccountId.HasValue)
                    AddLine(revenueAccountId.Value, 0, docLine.Amount, docLine.Description, docLine.ProjectId);
            }

            // Cr: ภาษีขาย — แยกตาม tax point (§78/§78/1):
            //   • ใบแจ้งหนี้ "งานบริการล้วน" (ไม่มีบรรทัดสินค้า TrackStock): ใบแจ้งหนี้
            //     ไม่ใช่ใบกำกับภาษี + ยังไม่รับเงิน → tax point ยังไม่เกิด → พัก 21913
            //     "ภาษีขายรอเรียกเก็บ" (ไม่เข้า ภ.พ.30) แล้ว reclass → 21911 เมื่อรับ
            //     ชำระ (TryReclassifyUndueOutputVatAsync) / เมื่อออกใบกำกับ (supersede
            //     reverse JE นี้ทั้งใบ ใบกำกับลง 21911 เอง)
            //   • ใบที่มีบรรทัดสินค้า TrackStock: อนุมัติ = ตัดสต๊อก = ส่งมอบของ →
            //     tax point เกิดแล้ว (§78) → 21911 ทันทีเหมือนเดิม
            //   • TaxInvoice = ใบกำกับภาษี → 21911 เสมอ
            // ผังไม่มี 21913 → fallback 21911 + log (graceful, พฤติกรรมเดิม)
            if (doc.VatAmount > 0)
            {
                var useUndueOutputVat = false;
                if (doc.DocumentType == DocumentType.Invoice && !doc.IsDeposit)
                {
                    // ตัวตัดสิน "มีสินค้าไหม" อยู่ที่ InvoiceHasTrackedGoodsAsync
                    // ตัวเดียว — warning §86 ตอนอนุมัติใช้เกณฑ์เดียวกันเป๊ะ
                    // (สองที่ใช้คนละเกณฑ์ = กฎสองข้อที่เถียงกันเองต่อหน้าผู้ใช้)
                    useUndueOutputVat = !await InvoiceHasTrackedGoodsAsync(companyId, doc);
                }

                ChartOfAccount? vatAccount = null;
                if (useUndueOutputVat)
                {
                    vatAccount = await FindAccountAsync(companyId, "21913");
                    if (vatAccount == null)
                    {
                        _logger.LogWarning(
                            "ผังบัญชีไม่มี 21913 (ภาษีขายรอเรียกเก็บ) — ใบแจ้งหนี้ {Doc} ลง VAT ที่ 21911 ถึงกำหนดทันที",
                            doc.DocumentNumber);
                        useUndueOutputVat = false;
                    }
                }
                vatAccount ??= await FindAccountAsync(companyId, "21911")
                    ?? throw new InvalidOperationException("ไม่พบบัญชีภาษีขาย (21911) ในผังบัญชี — กรุณาเพิ่มก่อนอนุมัติเอกสารที่มี VAT");
                AddLine(vatAccount.Id, 0, doc.VatAmount,
                    useUndueOutputVat ? "ภาษีขายรอเรียกเก็บ (tax point ยังไม่เกิด §78/1)" : "ภาษีขาย");
            }

            // COGS perpetual: Dr ต้นทุนขาย / Cr สินค้าคงเหลือ — นโยบายเดียวกับ POS
            // เพื่อให้กำไรขั้นต้นถูกต้องต่อบิลทุกช่องทาง (เดิมฝั่งใบแจ้งหนี้เป็น
            // periodic — ไม่ลง COGS ตอนขาย ทำให้ P&L ระหว่างช่องทางไม่สอดคล้อง)
            // เฉพาะบรรทัดสินค้าที่ TrackStock; มัดจำ (IsDeposit) ยังไม่ส่งมอบของ
            // → ไม่ลง COGS. ต้นทุน = WAC-aware (EffectiveUnitCost) ตรงกับ
            // ApplyStockMovementsAsync. ไม่ผ่าน Conv() เพราะต้นทุนเป็น THB อยู่แล้ว
            if (!doc.IsDeposit)
            {
                var cogsTotal = await ComputeSalesCogsAsync(companyId, doc);
                if (cogsTotal > 0)
                {
                    var cogsAcc = await FindAccountAsync(companyId, "51110") ?? await FindAccountAsync(companyId, "511");
                    var invAcc = await FindAccountAsync(companyId, "11500") ?? await FindAccountAsync(companyId, "115");
                    if (cogsAcc != null && invAcc != null)
                    {
                        pendingLines.Add((cogsAcc.Id, cogsTotal, 0m, $"ต้นทุนขาย - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                        pendingLines.Add((invAcc.Id, 0m, cogsTotal, $"ตัดสินค้าคงเหลือ - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                    }
                    else
                    {
                        _logger.LogWarning(
                            "ไม่พบผังต้นทุนขาย (511xx) หรือสินค้าคงเหลือ (115xx) — ข้ามการลง COGS ของ {DocNo}",
                            doc.DocumentNumber);
                    }
                }
            }
        }
        // ============================================================
        // ADJUSTMENT NOTES: CreditNote / DebitNote (polymorphic by source)
        //
        // Determines whether this is a sales-side adjustment (we issue to customer)
        // or a purchase-side adjustment (supplier issues to us, we return goods)
        // by inspecting the source document's type via RelatedDocumentId.
        //
        // Also detects "cash refund" mode: when source is fully paid (BalanceDue=0),
        // the counter-account is Cash instead of AR/AP — money actually moves.
        //
        // Standard cases per Revenue Code §82/10 (sales) and equivalent purchase
        // return treatment:
        //   Sales CN  AR-mode:    Cr AR,    Dr Revenue, Dr Output VAT, Cr WHT-Asset
        //   Sales CN  Cash-mode:  Cr Cash,  Dr Revenue, Dr Output VAT, Cr WHT-Asset
        //   Sales DN  AR-mode:    Dr AR,    Cr Revenue, Cr Output VAT, Dr WHT-Asset
        //   Sales DN  Cash-mode:  Dr Cash,  Cr Revenue, Cr Output VAT, Dr WHT-Asset
        //   Purch CN  AP-mode:    Dr AP,    Cr Expense, Cr Input VAT,  Dr WHT-Payable
        //   Purch CN  Cash-mode:  Dr Cash,  Cr Expense, Cr Input VAT,  Dr WHT-Payable
        //   Purch DN  AP-mode:    Cr AP,    Dr Expense, Dr Input VAT,  Cr WHT-Payable
        //   Purch DN  Cash-mode:  Cr Cash,  Dr Expense, Dr Input VAT,  Cr WHT-Payable
        // ============================================================
        else if (doc.DocumentType == DocumentType.CreditNote
                 || doc.DocumentType == DocumentType.DebitNote)
        {
            // Resolve the source side by inspecting RelatedDocumentId. Default is
            // sales-side (most common case + back-compat with previous behavior).
            Document? source = null;
            // เลขใบเดิมที่กรอกเป็น text (ช่อง "อ้างอิง") — ถ้าตรงกับเลขเอกสารจริงใน
            // tenant ให้ resolve เป็น RelatedDocumentId ก่อนลงบัญชี. ไม่งั้น CN ที่
            // อ้างด้วย text จะหลุดทุก guard: cap §86/10, void-protection, ฝั่ง
            // ภ.พ.30, FOR UPDATE — ลดหนี้เกินยอด/void ใบเดิมทั้งที่ CN ค้างได้
            if (!doc.RelatedDocumentId.HasValue && !string.IsNullOrWhiteSpace(doc.Reference))
            {
                var refNo = doc.Reference.Trim();
                var refMatchId = await _db.Documents
                    .Where(d => d.CompanyId == companyId && d.DocumentNumber == refNo
                        && d.Id != doc.Id && !d.IsDeleted)
                    .Select(d => (Guid?)d.Id)
                    .FirstOrDefaultAsync();
                // ไม่ตรงเลขเอกสารของเรา → ลอง **เลขใบกำกับของผู้ขาย**
                // (SupplierInvoiceNumber บนใบซื้อ) — พฤติกรรมจริงของผู้ใช้:
                // CN คืนของให้ supplier จะกรอกช่องอ้างอิงเป็นเลขใบของผู้ขาย
                // (เช่น RT69/00013) เพราะนั่นคือเลขบนกระดาษที่ถืออยู่ ไม่ใช่
                // เลข PI-xxxx ของเรา. เดิม resolver เทียบ DocumentNumber
                // อย่างเดียว → หาไม่เจอ → default ฝั่งขาย → JE ลง Dr 21911
                // แทน Cr 11610 และ ภ.พ.30 ตามผิดทั้งเส้น (เคสจริง
                // CN-20260721-0002). จำกัดที่คู่ค้าเดียวกัน — เลขใบผู้ขาย
                // ซ้ำข้าม supplier ได้ (ต่างคนต่างรันเลขของตัวเอง)
                var refNoLower = refNo.ToLower();
                if (!refMatchId.HasValue)
                    refMatchId = await _db.Documents
                        .Where(d => d.CompanyId == companyId && d.Id != doc.Id && !d.IsDeleted
                            && d.ContactId == doc.ContactId
                            && d.SupplierInvoiceNumber != null
                            // เทียบแบบไม่สนตัวพิมพ์ — ผู้ใช้พิมพ์ rt69/00013
                            // ขณะที่ใบซื้อเก็บ RT69/00013 ต้องยังจับคู่ได้
                            && d.SupplierInvoiceNumber.ToLower() == refNoLower
                            && (d.DocumentType == DocumentType.PurchaseInvoice
                                || d.DocumentType == DocumentType.Expense
                                || d.DocumentType == DocumentType.PaymentVoucher
                                || d.DocumentType == DocumentType.CertificateInLieu))
                        .OrderByDescending(d => d.DocumentDate)
                        .Select(d => (Guid?)d.Id)
                        .FirstOrDefaultAsync();
                if (refMatchId.HasValue) doc.RelatedDocumentId = refMatchId;
            }
            if (doc.RelatedDocumentId.HasValue)
            {
                source = await _db.Documents
                    .AsNoTracking()
                    .FirstOrDefaultAsync(d => d.Id == doc.RelatedDocumentId.Value
                        && d.CompanyId == companyId);
            }

            // §86/9-10: ห้ามออก CN/DN อ้างใบที่ถูกยกเลิกแล้ว (audit F9) — JE ของใบ
            // เดิมถูก reverse ไปแล้ว การ Cr AR/Dr AP ซ้ำ = ยอดติดลบ
            if (source != null && source.Status == DocumentStatus.Voided)
                throw new InvalidOperationException(
                    $"ไม่สามารถออก{(doc.DocumentType == DocumentType.CreditNote ? "ใบลดหนี้" : "ใบเพิ่มหนี้")}อ้างอิง {source.DocumentNumber} ได้ — เอกสารต้นทางถูกยกเลิกแล้ว (§86/9-10)");

            // §86/9-10: CN/DN ต้องเป็นคู่ค้าเดียวกับใบเดิม — คนละคู่ค้า = ลดหนี้
            // ผิดราย (AR/AP ของอีกรายโดนตัด + ภ.พ.30 รายงานผิดคน). convert flow
            // copy contact มาให้อยู่แล้ว guard นี้กันเคสสร้างตรง/API/แก้ contact ทีหลัง
            if (source != null && source.ContactId != doc.ContactId)
                throw new InvalidOperationException(
                    $"คู่ค้าบน{(doc.DocumentType == DocumentType.CreditNote ? "ใบลดหนี้" : "ใบเพิ่มหนี้")}ไม่ตรงกับเอกสารต้นฉบับ {source.DocumentNumber} — §86/9-10 ต้องออกให้คู่ค้ารายเดียวกับใบเดิม");

            // Guard เส้น "สร้างตรง" (ไม่ผ่าน ValidateConversionAsync) — กติกา
            // เดียวกับตอน convert: มัดจำ → เมนูคืนมัดจำ; ใบเสร็จหลักฐานรับเงิน
            // เปล่า (ไม่ใช่ใบกำกับ) / PV settlement → ต้องอ้างเอกสารตั้งหนี้จริง
            if (source != null && (source.DocumentType == DocumentType.Receipt
                || source.DocumentType == DocumentType.ReceiptVoucher))
            {
                if (source.IsDeposit)
                    throw new InvalidOperationException(
                        $"{source.DocumentNumber} เป็นใบมัดจำ/รับล่วงหน้า — ใช้เมนู \"คืนมัดจำ\" แทน "
                        + "(ระบบออกใบลดหนี้ + ปรับ VAT ตามวงจรมัดจำให้ถูกต้อง)");
                if (source.VatAmount <= 0.005m && source.RelatedDocumentId.HasValue)
                    throw new InvalidOperationException(
                        $"{source.DocumentNumber} เป็นใบเสร็จหลักฐานรับเงิน (ไม่ใช่ใบกำกับภาษี — VAT อยู่ที่เอกสาร"
                        + "ต้นทาง) — ใบลดหนี้/ใบเพิ่มหนี้ต้องอ้างใบกำกับ/เอกสารตั้งหนี้ตัวจริง (§86/9-10)");
            }
            if (source != null && source.DocumentType == DocumentType.PaymentVoucher
                && source.RelatedDocumentId.HasValue)
            {
                var pvSettles = await _db.Documents.AsNoTracking()
                    .Where(d => d.Id == source.RelatedDocumentId.Value && d.CompanyId == companyId)
                    .Select(d => new { d.DocumentNumber, d.DocumentType })
                    .FirstOrDefaultAsync();
                if (pvSettles != null && pvSettles.DocumentType is DocumentType.PurchaseInvoice
                    or DocumentType.Expense or DocumentType.CertificateInLieu)
                    throw new InvalidOperationException(
                        $"{source.DocumentNumber} เป็นใบสำคัญจ่ายที่จ่ายชำระ {pvSettles.DocumentNumber} — "
                        + $"ใบลดหนี้/ใบเพิ่มหนี้จากผู้ขายต้องอ้าง {pvSettles.DocumentNumber} (เอกสารตั้งหนี้) โดยตรง (§86/10)");
            }

            // GRN ไม่ใช่เอกสารตั้งหนี้/ใบกำกับ (แค่รับของ) — CN/DN ต้องอ้าง PI ที่
            // ออกจาก GRN นั้นแทน. ปล่อยผ่านจะตกฝั่งขาย (Cr ลูกหนี้/Dr รายได้) +
            // restock ผิดทิศ + ภ.พ.30 ลดภาษีขาย — ผิดทุกงบ
            if (source != null && source.DocumentType == DocumentType.GoodsReceiptNote)
                throw new InvalidOperationException(
                    $"{source.DocumentNumber} เป็นใบรับสินค้า (GRN) ไม่ใช่เอกสารตั้งหนี้ — "
                    + "ใบลดหนี้/ใบเพิ่มหนี้จากผู้ขายต้องอ้างใบแจ้งหนี้ซื้อ (PI) ที่ออกจาก GRN นี้แทน (§86/10)");

            // CN Return: กันคืนของเกินจำนวนที่ซื้อ/ขายจริง + กันสินค้านอกใบเดิม —
            // cap §86/10 คุมแค่ยอดเงิน แต่ stock/COGS เดินตาม qty บนบรรทัด CN
            if (doc.DocumentType == DocumentType.CreditNote
                && doc.CreditNoteReason == Models.Enums.CreditNoteReason.Return
                // `doc.Lines` เป็น ICollection ที่ initialize ไว้แล้ว ไม่มีทางเป็น null
                // — เช็ค `!= null` ตรงนี้เคยทำให้คอมไพเลอร์ถือว่า "อาจ null" ไปทั้ง
                // เมธอด แล้วไปฟ้อง CS8602 ที่ `foreach (var docLine in doc.Lines)`
                // ด้านล่างอีกที (เตือนผิดจุดจนหาต้นตอไม่เจอ)
                && source != null)
            {
                var cnStockLines = doc.Lines
                    .Where(l => !string.IsNullOrWhiteSpace(l.ProductCode))
                    .GroupBy(l => l.ProductCode!.Trim())
                    .ToDictionary(g => g.Key, g => g.Sum(l => l.Quantity));
                if (cnStockLines.Count > 0)
                {
                    var srcQty = await _db.DocumentLines.AsNoTracking()
                        .Where(l => l.DocumentId == source.Id && l.ProductCode != null)
                        .GroupBy(l => l.ProductCode!)
                        .Select(g => new { Code = g.Key, Qty = g.Sum(l => l.Quantity) })
                        .ToListAsync();
                    var srcQtyMap = srcQty.ToDictionary(x => x.Code.Trim(), x => x.Qty);
                    var siblingQty = await _db.DocumentLines.AsNoTracking()
                        .Where(l => l.Document.CompanyId == companyId
                            && l.Document.RelatedDocumentId == source.Id
                            && l.Document.Id != doc.Id
                            && l.Document.DocumentType == DocumentType.CreditNote
                            && l.Document.CreditNoteReason == Models.Enums.CreditNoteReason.Return
                            && l.Document.Status != DocumentStatus.Voided
                            && l.Document.Status != DocumentStatus.Draft
                            && l.Document.Status != DocumentStatus.Rejected
                            && !l.Document.IsDeleted
                            && l.ProductCode != null)
                        .GroupBy(l => l.ProductCode!)
                        .Select(g => new { Code = g.Key, Qty = g.Sum(l => l.Quantity) })
                        .ToListAsync();
                    var siblingMap = siblingQty.ToDictionary(x => x.Code.Trim(), x => x.Qty);
                    foreach (var (code, qty) in cnStockLines)
                    {
                        if (!srcQtyMap.TryGetValue(code, out var soldQty))
                            throw new InvalidOperationException(
                                $"ใบลดหนี้คืนสินค้า \"{code}\" ซึ่งไม่อยู่ในเอกสารต้นฉบับ {source.DocumentNumber} — "
                                + "คืนได้เฉพาะสินค้าที่ซื้อ/ขายในใบเดิม (§86/10)");
                        var cumulative = qty + siblingMap.GetValueOrDefault(code, 0m);
                        if (cumulative > soldQty + 0.0001m)
                            throw new InvalidOperationException(
                                $"คืนสินค้า \"{code}\" รวม {cumulative:N2} เกินจำนวนในใบเดิม {source.DocumentNumber} "
                                + $"({soldQty:N2}) — สต๊อก/ต้นทุนขายจะคลาดเกินจริง");
                    }
                }
            }

            // PaymentVoucher = PV standalone จ่ายทันที (ตั้งหนี้+จ่ายในใบเดียว) —
            // CN/DN ที่อ้างต้องลงฝั่งซื้อเหมือน PI/Expense (เดิมไม่อยู่ใน list →
            // ตกไปฝั่งขาย: Cr ลูกหนี้/Dr รายได้ ทั้งที่เป็นการซื้อ)
            var isPurchaseSide = source != null && (
                source.DocumentType == DocumentType.PurchaseInvoice
                || source.DocumentType == DocumentType.Expense
                || source.DocumentType == DocumentType.CertificateInLieu
                || source.DocumentType == DocumentType.PaymentVoucher);
            // ผู้ใช้สั่งย้ายฝั่งเอง (ReclassifyCnDnSideAsync) → ชนะทุกการเดา
            // ต้องอยู่ก่อน fallback ทุกชั้น ไม่งั้นระบบเดาทับเจตนาผู้ใช้
            if (doc.CnDnPurchaseSideOverride.HasValue)
                isPurchaseSide = doc.CnDnPurchaseSideOverride.Value;
            // ไม่มีใบต้นทางให้ดูเลย (FK ก็ไม่มี text ref ก็ resolve ไม่ติด) —
            // เดิม default ฝั่งขายเงียบ ๆ เสมอ ทำให้ CN คืนของ supplier ที่อ้าง
            // เลขนอกระบบ ลง Dr 21911 (ลดภาษีขาย) แทน Cr 11610 (ลดภาษีซื้อ)
            // = นำส่งภาษีขายขาด + เคลมภาษีซื้อเกิน พร้อมกัน. ใช้บทบาทคู่ค้า
            // เป็นสัญญาณสุดท้าย: คู่ค้าที่เป็น "ผู้ขายอย่างเดียว" (supplier
            // ไม่ใช่ลูกค้า) → CN/DN ใบนี้คือฝั่งซื้อแน่นอน — เราไม่มีทางออก
            // ใบลดหนี้ "การขาย" ให้คนที่ไม่เคยเป็นลูกค้า
            if (!isPurchaseSide && source == null && !doc.CnDnPurchaseSideOverride.HasValue)
            {
                var contactRole = await _db.Contacts.AsNoTracking()
                    .Where(c => c.Id == doc.ContactId)
                    .Select(c => new { c.IsSupplier, c.IsCustomer })
                    .FirstOrDefaultAsync();
                if (contactRole is { IsSupplier: true, IsCustomer: false })
                {
                    isPurchaseSide = true;
                    _logger.LogInformation(
                        "CN/DN {Doc} ไม่มีใบต้นทาง — จัดฝั่งซื้อจากบทบาทคู่ค้า (supplier-only)",
                        doc.DocumentNumber);
                }
            }
            var isCashSettlement = source != null && source.BalanceDue <= 0.01m;
            var isCreditNote = doc.DocumentType == DocumentType.CreditNote;

            journalType = isPurchaseSide ? JournalType.Purchase : JournalType.Sales;
            var typeLabel = isCreditNote ? "ใบลดหนี้" : "ใบเพิ่มหนี้";

            // === Counter-account: AR/AP/Cash depending on mode ===
            // For CN: counter-account is on the credit side (sales) / debit side (purchase)
            // For DN: counter-account is on the debit side (sales) / credit side (purchase)
            string counterAccCode;
            if (isPurchaseSide)
                counterAccCode = isCashSettlement ? "111" : "212"; // Cash or AP
            else
                counterAccCode = isCashSettlement ? "111" : "113"; // Cash or AR

            // ⚠️ ต้องส่ง `doc.Contact` เหมือนทุกเส้นอื่นในไฟล์นี้ (`:3984` `:4200` `:4349`
            // `:8272` `:13407` `:14181` `:15294`) — `FindAccountAsync` อ่าน
            // `Contact.DefaultArAccountId`/`DefaultApAccountId` จากพารามิเตอร์นี้เท่านั้น
            // เดิมไม่ส่ง ⇒ คู่ค้าที่ปักผังลูกหนี้/เจ้าหนี้เฉพาะรายไว้ ถูกใบลดหนี้/เพิ่มหนี้
            // ลงเข้าผังกลางแทน ⇒ ผังเฉพาะรายค้างยอดถาวรเพราะใบตั้งหนี้กับใบปรับปรุง
            // อยู่คนละบัญชี (ยอดคงเหลือรายคู่ค้าไม่มีวันเป็นศูนย์)
            var counterAcc = await FindAccountAsync(companyId, counterAccCode, doc.Contact);
            var counterDesc = $"{typeLabel} - {doc.DocumentNumber}" +
                (isCashSettlement ? " (เงินสด)" : "");

            // CN reduces the receivable/increases payable for purchase return; DN opposite.
            // Sales side:    CN→Cr counter, DN→Dr counter
            // Purchase side: CN→Dr counter, DN→Cr counter
            var counterIsDebit = isPurchaseSide ? isCreditNote : !isCreditNote;
            // WHT basis = Cash (audit F2): ใบกำกับ/PI ต้นทางลง AR/AP แบบ "gross"
            // (Total + WHT) โดยไม่แตะ 11910/2191x จนกว่าจะรับ/จ่ายเงินจริง →
            // CN/DN โหมด AR/AP ต้อง mirror gross แบบเดียวกันและ "ไม่ลงขา WHT"
            // — เดิมลงแบบ accrual เสมอ → AR ค้าง +WHT ถาวร / 11910 ติดลบ
            var cnDnGrossWht = whtBasis == Models.Enums.WhtRecognitionBasis.Cash
                && !isCashSettlement && doc.WithholdingTaxAmount > 0;
            var counterAmt = cnDnGrossWht
                ? doc.TotalAmount + doc.WithholdingTaxAmount
                : doc.TotalAmount;
            if (counterAcc != null)
            {
                AddLine(counterAcc.Id,
                    counterIsDebit ? counterAmt : 0,
                    counterIsDebit ? 0 : counterAmt,
                    counterDesc);
            }

            // === Revenue / Expense lines ===
            // Sales CN reverses revenue (Dr); Sales DN adds revenue (Cr)
            // Purchase CN reverses expense (Cr); Purchase DN adds expense (Dr)
            // ฝั่งซื้อ: บรรทัดสินค้า TrackStock default เข้าสินค้าคงเหลือ
            // (perpetual) — CN คืนของ = Cr ลดมูลค่าสต๊อก, DN ค่าใช้จ่ายเพิ่ม
            // จาก vendor = Dr เพิ่มมูลค่าสต๊อก — สมมาตรกับ JE ของ PI/GRN
            var resolveCnDnLineAcc = isPurchaseSide
                ? await BuildPurchaseLineAccountResolverAsync(companyId, doc, defaultExpense?.Id)
                : null;
            foreach (var docLine in doc.Lines)
            {
                Guid? lineAccId;
                if (isPurchaseSide)
                    lineAccId = resolveCnDnLineAcc!(docLine);
                else
                    // ขา revenue ของ CN/DN ฝั่งขาย — ผังหมวดค่าใช้จ่ายที่หลงมา
                    // ตกกลับบัญชีรายได้มาตรฐาน (safety net เดียวกับใบแจ้งหนี้)
                    lineAccId = RevenueLegAccountId(docLine);

                if (!lineAccId.HasValue) continue;

                // Determine Dr or Cr direction:
                //   Sales CN  → Dr revenue (reverse)
                //   Sales DN  → Cr revenue (add)
                //   Purch CN  → Cr expense (reverse)
                //   Purch DN  → Dr expense (add)
                var lineIsDebit = isPurchaseSide ? !isCreditNote : isCreditNote;
                // ⚠️ ภาษีซื้อต้องห้าม §82/5 (ผลตรวจทีม C · C-02): ฝั่งซื้อ บรรทัดที่
                // `IsVatClaimable = false` ตอนตั้งหนี้ **รวม VAT เป็นต้นทุน** ไม่เคย
                // ลง 11610 ⇒ CN/DN ที่กลับรายการต้องกลับ "ต้นทุนรวม VAT" ให้ตรงกัน
                // ไม่งั้น 11610 ติดลบทั้งที่ไม่เคยถูก Dr และค่าใช้จ่ายกลับไม่ครบ
                // (เส้น PI/PV ทำแบบนี้อยู่แล้ว — ที่นี่คือจุดที่ตกหล่น)
                var lineAmt = isPurchaseSide && !docLine.IsVatClaimable
                    ? docLine.Amount + docLine.VatAmount
                    : docLine.Amount;
                AddLine(lineAccId.Value,
                    lineIsDebit ? lineAmt : 0,
                    lineIsDebit ? 0 : lineAmt,
                    $"{typeLabel} - {docLine.Description}"
                        + (isPurchaseSide && !docLine.IsVatClaimable ? " (รวมภาษีซื้อต้องห้าม §82/5)" : ""),
                    docLine.ProjectId);
            }

            // === VAT line ===
            // ฝั่งซื้อคิดเฉพาะส่วนที่ **เคลมได้** — ส่วนที่ต้องห้ามถูกพับเข้าบรรทัด
            // ค่าใช้จ่ายข้างบนแล้ว (ตรงกับที่ใบตั้งหนี้ทำตอน Dr)
            var cnDnVatAmount = isPurchaseSide
                ? doc.Lines.Where(l => l.IsVatClaimable).Sum(l => l.VatAmount)
                : doc.VatAmount;
            if (cnDnVatAmount > 0)
            {
                // Sales: Output VAT 21911 (liability), Purchase: Input VAT 116 (asset)
                // ⚠️ เคส VAT ใบเดิมยัง "พัก" อยู่บัญชีรอ (undue): CN/DN ต้องกลับ
                // รายการที่บัญชีเดียวกับที่ใบเดิมพักไว้ — ไม่งั้นบัญชีจริง (21911/
                // 11610) ติดลบทั้งที่ไม่เคยถูกลง และบัญชีพัก (21913/11640) ค้างเกิน
                var vatCode = isPurchaseSide ? "11610" : "21911";
                if (isPurchaseSide && source != null
                    && source.InputVatPostedAsUndue && source.InputVatBecameClaimableAt == null)
                {
                    vatCode = "11640";   // PI/Expense/PV ยังพักภาษีซื้อรอใบกำกับครบ
                }
                else if (!isPurchaseSide && source != null
                    && source.DocumentType == DocumentType.Invoice
                    && source.OutputVatDueAt == null)
                {
                    // ใบแจ้งหนี้บริการที่ VAT ยังพัก 21913 (ยังไม่รับเงิน §78/1) —
                    // ตัดสิน GL-driven: ยอด Cr สุทธิบน 21913 ของ JE ใบเดิม > 0
                    var src21913Net = await (from l in _db.JournalEntryLines.AsNoTracking()
                                             join j in _db.JournalEntries.AsNoTracking() on l.JournalEntryId equals j.Id
                                             join a in _db.ChartOfAccounts.AsNoTracking() on l.AccountId equals a.Id
                                             where j.CompanyId == companyId && j.SourceDocumentId == source.Id
                                                   && !j.IsDeleted && !l.IsDeleted
                                                   && j.Status == JournalEntryStatus.Posted
                                                   && a.AccountCode == "21913"
                                             select (decimal?)(l.CreditAmount - l.DebitAmount))
                        .SumAsync() ?? 0m;
                    if (src21913Net > 0.005m) vatCode = "21913";
                }
                var vatAcc = await FindAccountAsync(companyId, vatCode)
                    ?? (vatCode == "11640" ? await FindAccountAsync(companyId, "11630") : null)
                    ?? await FindAccountAsync(companyId, isPurchaseSide ? "116" : "21911");
                if (vatAcc != null)
                {
                    // Same direction rule as revenue/expense lines
                    var vatIsDebit = isPurchaseSide ? !isCreditNote : isCreditNote;
                    AddLine(vatAcc.Id,
                        vatIsDebit ? cnDnVatAmount : 0,
                        vatIsDebit ? 0 : cnDnVatAmount,
                        $"{typeLabel} ภาษี{(isPurchaseSide ? "ซื้อ" : "ขาย")}"
                        + (vatCode is "21913" or "11640" ? " (กลับรายการบัญชีพัก undue)" : ""));
                }
            }

            // === WHT line ===
            // (ข้ามเมื่อ basis Cash โหมด AR/AP — counter ลง gross แทน, ดู cnDnGrossWht)
            if (doc.WithholdingTaxAmount > 0 && !cnDnGrossWht)
            {
                // Sales: WHT-Asset 11910 (we got withheld); Purchase: WHT-Payable
                // by counterparty type (Individual→ภ.ง.ด.3 21916, Juristic→ภ.ง.ด.53 21917).
                var whtAcc = isPurchaseSide
                    ? await ResolveWhtPayableAccountAsync(companyId, doc.Contact, doc.IsForeignService)
                    : await FindAccountAsync(companyId, "11910");
                if (whtAcc != null)
                {
                    // WHT-Asset behaves like revenue (sales) — opposite for purchase
                    // Sales CN→Cr WHT (reverse claim), DN→Dr WHT (add claim)
                    // Purch CN→Dr WHT-Payable (reverse), DN→Cr WHT-Payable (add)
                    var whtIsDebit = isPurchaseSide ? isCreditNote : !isCreditNote;
                    AddLine(whtAcc.Id,
                        whtIsDebit ? doc.WithholdingTaxAmount : 0,
                        whtIsDebit ? 0 : doc.WithholdingTaxAmount,
                        $"{typeLabel} ภาษีหัก ณ ที่จ่าย");
                }
            }

            // === COGS reversal — เฉพาะใบลดหนี้ฝั่งขายแบบ "รับคืนสินค้า" ===
            // ของกลับเข้าสต๊อกจริง (ApplyStockMovementsAsync IN เมื่อ Reason=Return)
            // → กลับต้นทุนขายด้วย: Dr สินค้าคงเหลือ / Cr ต้นทุนขาย ที่ WAC ปัจจุบัน
            // (ค่าเดียวกับที่ movement restock stamp) — คู่กับ COGS perpetual ฝั่งขาย
            if (isCreditNote && !isPurchaseSide
                && doc.CreditNoteReason == Models.Enums.CreditNoteReason.Return)
            {
                var cogsBack = await ComputeSalesCogsAsync(companyId, doc, outbound: false);
                if (cogsBack > 0)
                {
                    var cogsAcc = await FindAccountAsync(companyId, "51110") ?? await FindAccountAsync(companyId, "511");
                    var invAcc = await FindAccountAsync(companyId, "11500") ?? await FindAccountAsync(companyId, "115");
                    if (cogsAcc != null && invAcc != null)
                    {
                        pendingLines.Add((invAcc.Id, cogsBack, 0m, $"รับคืนสินค้าเข้าสต๊อก - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                        pendingLines.Add((cogsAcc.Id, 0m, cogsBack, $"กลับต้นทุนขาย (รับคืน) - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                    }
                }
            }
        }
        // ============================================================
        // PURCHASE SIDE: PurchaseInvoice / Expense / CertificateInLieu (on credit)
        // ============================================================
        else if (doc.DocumentType == DocumentType.CertificateInLieu)
        {
            // ใบรับรองแทนใบเสร็จ — used when the payee can't issue a tax
            // invoice/receipt (street vendor, taxi, ...). Per Revenue Code
            // §82/4 the buyer CANNOT claim input VAT without a valid tax
            // invoice, so VAT is NOT posted to ภาษีซื้อ (116); any VAT amount
            // is folded into the expense as part of its (non-recoverable)
            // cost. It is a cash payment, so the credit side hits Cash/Bank,
            // never Accounts Payable.
            journalType = JournalType.Purchase;

            // แปลงมาจากเอกสารตั้งหนี้ (Expense) → CIL ทำหน้าที่ "จ่ายจริง"
            // เหมือน PV settlement: Dr เจ้าหนี้ / Cr เงินสด — ห้าม Dr ค่าใช้จ่าย
            // ซ้ำ (ต้นทางลงไปแล้ว = ค่าใช้จ่ายเบิ้ล + เจ้าหนี้ค้างตลอดกาล)
            DocumentType? cilSrcType = null;
            if (doc.RelatedDocumentId.HasValue)
                cilSrcType = await _db.Documents.AsNoTracking()
                    .Where(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId)
                    .Select(d => (DocumentType?)d.DocumentType)
                    .FirstOrDefaultAsync();

            if (cilSrcType is DocumentType.Expense or DocumentType.PurchaseInvoice)
            {
                journalType = JournalType.CashPayments;
                var apAccount = await ResolvePayableAccountAsync(companyId, cilSrcType.Value, doc.Contact);
                if (whtBasis == Models.Enums.WhtRecognitionBasis.Cash)
                {
                    // Cash basis: ต้นทางตั้ง AP ที่ gross — ตัด AP gross,
                    // จ่ายเงินสุทธิ, รับรู้ WHT ค้างจ่ายของงวดนี้
                    var thisWht = doc.WithholdingTaxAmount;
                    if (apAccount != null)
                        AddLine(apAccount.Id, doc.TotalAmount + thisWht, 0, $"ตัดเจ้าหนี้ - {doc.DocumentNumber}");
                    if (moneyAccount != null)
                        AddLine(moneyAccount.Id, 0, doc.TotalAmount,
                            $"{(doc.BankAccountId.HasValue ? "จ่ายจากบัญชี" : "จ่ายเงินสด")} - {doc.DocumentNumber}");
                    if (thisWht > 0)
                    {
                        var whtAcc = await ResolveWhtPayableAccountAsync(companyId, doc.Contact, doc.IsForeignService);
                        if (whtAcc != null)
                            AddLine(whtAcc.Id, 0, thisWht, "ภาษีหัก ณ ที่จ่ายค้างจ่าย (ภ.ง.ด.)");
                    }
                }
                else
                {
                    // Accrual: AP ต้นทาง net of WHT แล้ว — แค่ย้ายเงินสุทธิ
                    if (apAccount != null)
                        AddLine(apAccount.Id, doc.TotalAmount, 0, $"ตัดเจ้าหนี้ - {doc.DocumentNumber}");
                    if (moneyAccount != null)
                        AddLine(moneyAccount.Id, 0, doc.TotalAmount,
                            $"{(doc.BankAccountId.HasValue ? "จ่ายจากบัญชี" : "จ่ายเงินสด")} - {doc.DocumentNumber}");
                }
            }
            else
            {
            // VAT เคลมไม่ได้ (§82/4) → รวมเป็นต้นทุนของ **บรรทัดนั้น ๆ** ไม่ใช่
            // กองรวมที่บัญชีค่าใช้จ่ายทั่วไป (P-7): CIL หลายบรรทัดคนละผัง (ค่าเดินทาง
            // + ค่าที่พัก) จะได้ต้นทุนเพี้ยนทั้งสองผัง และถ้าบริษัทไม่มี defaultExpense
            // เลย ขา Dr จะขาดเท่ายอด VAT ทั้งก้อน = JE ไม่สมดุล (โดนตีกลับทั้งใบ)
            decimal cilVatAssigned = 0m;
            Guid? cilFirstAccount = null;
            foreach (var docLine in doc.Lines)
            {
                var expenseAccountId = docLine.AccountId ?? defaultExpense?.Id;
                if (!expenseAccountId.HasValue) continue;
                cilFirstAccount ??= expenseAccountId.Value;
                var cilLineVat = docLine.VatAmount;
                cilVatAssigned += cilLineVat;
                AddLine(expenseAccountId.Value, docLine.Amount + cilLineVat, 0,
                    cilLineVat > 0
                        ? $"{docLine.Description} (รวมภาษีซื้อที่เคลมไม่ได้)"
                        : docLine.Description,
                    docLine.ProjectId);
            }
            // เศษที่หัวเอกสารมีแต่บรรทัดไม่มี (ใบเก่า/กรอก VAT ที่หัวใบ) — ต้องลง
            // ให้ครบ ไม่งั้น JE ขาด Dr เท่าเศษนั้น
            var cilVatResidual = Math.Round(doc.VatAmount - cilVatAssigned, 2, MidpointRounding.AwayFromZero);
            if (cilVatResidual > 0.005m && (cilFirstAccount ?? defaultExpense?.Id) is Guid cilResidualAccount)
                AddLine(cilResidualAccount, cilVatResidual, 0,
                    "ภาษีซื้อที่เคลมไม่ได้ (รวมเป็นต้นทุน) - ใบรับรองแทนใบเสร็จ");

            if (moneyAccount != null)
                AddLine(moneyAccount.Id, 0, doc.TotalAmount,
                    $"{(doc.BankAccountId.HasValue ? "จ่ายจากบัญชี" : "จ่ายเงินสด")} - {doc.DocumentNumber}");

            if (doc.WithholdingTaxAmount > 0)
            {
                var whtAcc = await ResolveWhtPayableAccountAsync(companyId, doc.Contact, doc.IsForeignService);
                if (whtAcc != null)
                    AddLine(whtAcc.Id, 0, doc.WithholdingTaxAmount, "ภาษีหัก ณ ที่จ่ายค้างจ่าย");
            }
            }
        }
        else if (doc.DocumentType == DocumentType.PurchaseInvoice
                 || doc.DocumentType == DocumentType.Expense)
        {
            journalType = JournalType.Purchase;

            // 3-way match: if this invoice was billed against a Goods Receipt
            // Note that ALREADY accrued the goods (Dr Expense / Cr GR-NI when
            // received), the expense is already in the books — so here we just
            // CLEAR the GR-NI accrual (Dr GR-NI) instead of debiting expense
            // again, then claim VAT + set up the payable. Otherwise (standalone
            // PI) we debit expense as normal.
            var grNiAccount = await GetReceivedViaGrnAccrualAccountAsync(companyId, doc);
            if (grNiAccount != null)
            {
                // Dr: เจ้าหนี้-รับสินค้ายังไม่วางบิล (GR-NI) — clear the accrual
                // for the invoiced (ex-VAT) value. Partial invoices clear only
                // their portion; the rest of the GR-NI stays for later bills.
                AddLine(grNiAccount.Id, doc.SubTotal, 0, $"ตัดเจ้าหนี้รับของยังไม่วางบิล - {doc.DocumentNumber}");
                // VAT ต้องห้าม (§82/5) บนใบที่อ้าง GRN (audit F1-purchase): GRN
                // ตั้ง accrual แค่ฐาน ex-VAT → VAT ต้องห้ามยังไม่มีขา Dr ที่ไหน
                // (ขา 116 ด้านล่างรวมเฉพาะ claimable) → JE ขาด Dr เท่ายอด VAT
                // ต้องห้าม = ไม่สมดุล/ถูกยัดใส่บรรทัดใหญ่สุดเงียบ ๆ. ลงเป็นต้นทุน
                // ตามบรรทัด (VAT เคลมไม่ได้ = ส่วนหนึ่งของต้นทุนสินค้า/ค่าใช้จ่าย)
                var grnNonClaimResolver = await BuildPurchaseLineAccountResolverAsync(
                    companyId, doc, defaultExpense?.Id);
                foreach (var ncLine in doc.Lines.Where(l => !l.IsVatClaimable && l.VatAmount > 0))
                {
                    var ncAccId = grnNonClaimResolver(ncLine);
                    if (!ncAccId.HasValue) continue;
                    AddLine(ncAccId.Value, ncLine.VatAmount, 0,
                        $"VAT ต้องห้ามรวมเป็นต้นทุน - {ncLine.Description}", ncLine.ProjectId);
                }
            }
            else
            {
                // Dr: ค่าใช้จ่าย/สินค้า ตามรายการ (standalone purchase).
                // ภาษีซื้อต้องห้าม (§82/5): บรรทัดที่ IsVatClaimable=false →
                // รวม VAT เข้าค่าใช้จ่าย (Dr expense = Amount + VatAmount).
                // บรรทัด claimable → Dr expense net of VAT ปกติ + รวม VAT
                // ไปเข้าบัญชีภาษีซื้อ 116 ด้านล่าง.
                // บรรทัดสินค้า TrackStock ที่ไม่ได้เลือกบัญชีเอง → Dr สินค้า
                // คงเหลือ (perpetual — สมมาตรกับ COGS ตอนขาย)
                var resolvePiLineAcc = await BuildPurchaseLineAccountResolverAsync(
                    companyId, doc, defaultExpense?.Id);
                foreach (var docLine in doc.Lines)
                {
                    var expenseAccountId = resolvePiLineAcc(docLine);
                    if (!expenseAccountId.HasValue) continue;
                    var debitAmount = docLine.IsVatClaimable
                        ? docLine.Amount
                        : docLine.Amount + docLine.VatAmount;
                    var desc = docLine.IsVatClaimable
                        ? docLine.Description
                        : $"{docLine.Description} (รวม VAT ต้องห้าม{(string.IsNullOrWhiteSpace(docLine.VatNonClaimableReason) ? "" : " - " + docLine.VatNonClaimableReason)})";
                    AddLine(expenseAccountId.Value, debitAmount, 0, desc, docLine.ProjectId);
                }
            }

            // Dr: ภาษีซื้อ — บัญชีปลายทางขึ้นกับ completeness §86/4 + override:
            //   1) มี override → ใช้ user-pick (เช่น 51000 ต้นทุนขาย ตาม §82/5)
            //   2) ใบกำกับครบ §86/4 → 11610 "ภาษีซื้อ ภ.พ.30" (เคลมได้ทันที)
            //   3) ใบกำกับยังไม่ครบ → 11640 "ภาษีซื้อยังไม่ถึงกำหนด" (§82/3 รอ
            //      ใบครบ; CompleteSupplierTaxInvoiceAsync จะ gen adjusting JE 11640→11610
            //      ตอน user มาเติมข้อมูลครบ + filter ภ.พ.30 ใช้ BecameClaimableAt)
            var claimableVatPi = doc.Lines.Where(l => l.IsVatClaimable).Sum(l => l.VatAmount);
            if (claimableVatPi > 0)
            {
                // §83/6 บริการต่างประเทศ: VAT เคลมได้เฉพาะ "เดือนที่นำส่ง ภ.พ.36 +
                // ได้ใบเสร็จ RD" (§77/2) — บังคับพักที่ 11640 เสมอ (ไม่ดู completeness
                // เพราะไม่มีใบกำกับไทย) → RecognizePp36 จะย้าย 11640→11610 ทีหลัง
                var (vatInputAccount, postedAsUndue) = doc.IsForeignService
                    ? ((await FindAccountAsync(companyId, ForeignServiceVat.Pp36InputVatCode)
                            ?? await FindAccountAsync(companyId, "11630")
                        ?? throw new InvalidOperationException("ไม่พบผังบัญชี 11640 (ภาษีซื้อยังไม่ถึงกำหนด) สำหรับ ภ.พ.36")), true)
                    : await ResolveInputVatAccountAsync(companyId, doc);
                AddLine(vatInputAccount.Id, claimableVatPi, 0,
                    doc.IsForeignService ? "ภาษีซื้อยังไม่ถึงกำหนด (ภ.พ.36 §83/6 — รอนำส่ง+ใบเสร็จ RD)"
                    : postedAsUndue ? "ภาษีซื้อยังไม่ถึงกำหนด (ใบกำกับไม่ครบ §86/4)"
                                  : (doc.InputVatAccountCodeOverride != null
                                        ? $"VAT → {vatInputAccount.AccountCode} {vatInputAccount.AccountName} (override)"
                                        : "ภาษีซื้อ (เคลมได้)"));
                doc.InputVatPostedAsUndue = postedAsUndue;
                // ใบที่ลงเป็น undue (พัก 11640) — งวดเคลมถูกกำหนดโดย flow
                // "เติมใบกำกับครบ §86/4" เท่านั้น: "เจตนางวดเคลม" ที่ผู้ใช้
                // ตั้งไว้ตอนสร้าง (BecameClaimableAt) ต้องล้างทิ้ง มิฉะนั้น
                // รายงานจะมองว่า "ถึงกำหนดแล้ว" ทั้งที่ใบกำกับยังไม่ครบ
                // = เคลมภาษีซื้อที่ยังไม่มีสิทธิ์ (ลำดับชนะ: flow 11640 >
                // เจตนาบนเอกสาร)
                if (postedAsUndue) doc.InputVatBecameClaimableAt = null;
            }

            // Cr: payable — role-separated (หลักบัญชีไทย):
            //   PurchaseInvoice → เจ้าหนี้การค้า (21210) — supplier trade invoice.
            //   Expense         → เจ้าหนี้อื่น (21220) — internal expense claim,
            //                     no trade invoice; keeps 21210 reconcilable
            //                     against supplier statements.
            // On Accrual the payable carries NET of WHT (we'll withhold when we
            // pay). On Cash it carries GROSS (full amount owed before deducting
            // the WHT we'll withhold when actually paying).
            //
            // §83/6 (reverse charge): ผู้ขายต่างประเทศ "ไม่เก็บ VAT ไทย" — เจ้าหนี้
            // ผู้ขายต้องเป็น "ฐาน" เท่านั้น ส่วน VAT ที่ประเมินเองตั้งเป็นหนี้ต่อ
            // สรรพากร (Cr 21912 เจ้าหนี้ ภ.พ.36) แยกต่างหาก — เดิม Cr เจ้าหนี้รวม
            // VAT = ตั้งหนี้/จ่ายผู้ขายเกินยอดจริง + งบไม่มีหนี้ ภ.พ.36
            var apAccount = await ResolvePayableAccountAsync(companyId, doc.DocumentType, doc.Contact);
            // การแยกขาเครดิตอยู่ที่ ForeignServiceVat ที่เดียว — พรีวิว GL ก่อนอนุมัติ
            // ใช้ตัวเดียวกัน (เดิมพรีวิวไม่รู้จักกฎนี้ ⇒ โชว์ Cr เจ้าหนี้รวม VAT)
            var pp36Split = ForeignServiceVat.SplitCredit(doc.IsForeignService,
                whtBasis == Models.Enums.WhtRecognitionBasis.Cash
                    ? doc.TotalAmount + doc.WithholdingTaxAmount
                    : doc.TotalAmount,
                doc.VatAmount);
            var pp36Vat = pp36Split.Pp36Credit;
            var apAmountAtInvoice = pp36Split.PayeeCredit;
            if (apAccount != null)
                AddLine(apAccount.Id, 0, apAmountAtInvoice,
                    $"{(doc.DocumentType == DocumentType.Expense ? "เจ้าหนี้อื่น (ตั้งหนี้ค่าใช้จ่าย)" : "เจ้าหนี้การค้า")} - {doc.DocumentNumber}"
                    + (pp36Vat > 0 ? " (ฐาน ไม่รวม VAT ประเมินเอง §83/6)" : ""));
            if (pp36Vat > 0)
            {
                var pp36Acc = await FindAccountAsync(companyId, ForeignServiceVat.Pp36PayableCode)
                    ?? throw new InvalidOperationException("ไม่พบผังบัญชี 21912 (ภาษีขาย ภ.พ.36) — สร้างก่อนบันทึกบริการต่างประเทศ");
                AddLine(pp36Acc.Id, 0, pp36Vat, $"เจ้าหนี้ ภ.พ.36 (VAT ประเมินเอง §83/6) - {doc.DocumentNumber}");
            }

            // Cr: ภาษีหัก ณ ที่จ่ายค้างจ่าย (21916 ภ.ง.ด.3 / 21917 ภ.ง.ด.53).
            // Accrual only — Cash basis defers to the PaymentVoucher path.
            if (whtBasis == Models.Enums.WhtRecognitionBasis.Accrual && doc.WithholdingTaxAmount > 0)
            {
                var whtAccount = await ResolveWhtPayableAccountAsync(companyId, doc.Contact, doc.IsForeignService);
                if (whtAccount != null)
                {
                    // Group WHT by rate for clear audit trail
                    var whtByRate = doc.Lines
                        .Where(l => l.WithholdingTaxAmount > 0)
                        .GroupBy(l => l.WithholdingTaxRate)
                        .Select(g => new { Rate = g.Key, Amount = g.Sum(l => l.WithholdingTaxAmount) })
                        .ToList();
                    if (whtByRate.Count > 1)
                    {
                        foreach (var g in whtByRate)
                            AddLine(whtAccount.Id, 0, g.Amount, $"ภาษีหัก ณ ที่จ่าย {g.Rate}%");
                    }
                    else
                    {
                        AddLine(whtAccount.Id, 0, doc.WithholdingTaxAmount, "ภาษีหัก ณ ที่จ่ายค้างจ่าย");
                    }
                }
            }
        }
        // ============================================================
        // CASH RECEIPTS: Receipt / ReceiptVoucher
        // - Linked to existing Invoice (RelatedDocumentId): collection
        // - Standalone (no link): direct cash sale
        // ============================================================
        else if (doc.DocumentType == DocumentType.Receipt
                 || doc.DocumentType == DocumentType.ReceiptVoucher
                 // ขายเงินสด B2B (integration isCashSale): TaxInvoice ที่รับเงินจบในตัว
                 // ลงเป็น "ขายเงินสด" (Dr เงินสด/Cr รายได้+VAT + กลับมัดจำ) ไม่ตั้งลูกหนี้
                 // → JE สะอาดใบเดียว, e-Tax T03. reuse เส้น driveDeposit ที่ verified
                 || (doc.DocumentType == DocumentType.TaxInvoice && doc.IssuedAsCashReceipt))
        {
            journalType = JournalType.CashReceipts;

            // Settlement mode เฉพาะเมื่อเอกสารต้นทาง "ตั้งลูกหนี้จริง" (Invoice/
            // TaxInvoice/DebitNote — Dr 113 ตอนอนุมัติ) เท่านั้น. ใบเสร็จที่แปลง
            // มาจาก Quotation/BillingNote (เอกสาร operational ไม่มี JE) ต้องลง
            // แบบ standalone: Dr เงินสด / Cr รายได้ + VAT — มิฉะนั้นจะ Cr ลูกหนี้
            // ที่ไม่เคยถูก Dr (AR ติดลบ) และรายได้ไม่ถูกบันทึกเลย
            var receiptSettlesAr = false;
            var srcFx = doc.ExchangeRate;   // rate ของเอกสารต้นทาง (AR ตั้งที่ rate นี้)
            if (doc.RelatedDocumentId.HasValue)
            {
                var recSrc = await _db.Documents.AsNoTracking()
                    .Where(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId)
                    .Select(d => new { d.DocumentType, d.ExchangeRate })
                    .FirstOrDefaultAsync();
                receiptSettlesAr = recSrc?.DocumentType is DocumentType.Invoice
                    or DocumentType.TaxInvoice or DocumentType.DebitNote;
                if (recSrc != null) srcFx = recSrc.ExchangeRate;
            }
            // ขายเงินสด (isCashSale) ไม่เคยตั้งลูกหนี้มาก่อน — บังคับ standalone
            // เสมอ (กันเคสมี RelatedDocumentId หลุดมาแล้วไป settle AR ที่ไม่มีจริง)
            if (doc.IssuedAsCashReceipt) receiptSettlesAr = false;

            if (receiptSettlesAr)
            {
                // Cash basis: the source Invoice posted AR at GROSS (incl. WHT)
                // and skipped the WHT-Asset line. We now book WHT-Asset for
                // the withheld portion and clear AR at GROSS so the books
                // balance. Pull the WHT amount from the source so we always
                // match what was actually withheld, not whatever the operator
                // typed on the Receipt.
                //
                // FX cross-rate: เงินสดรับที่ rate วันรับ (Conv ของใบเสร็จ) แต่
                // AR/WHT ตัดที่ rate ของเอกสารต้นทาง (มูลค่าที่ตั้งไว้ใน GL) —
                // ผลต่าง → กำไร/ขาดทุนอัตราแลกเปลี่ยน realized (bypass Conv
                // สำหรับบรรทัด AR/WHT/FX โดย add ตรงเข้า pendingLines)
                decimal SrcThb(decimal amt) => srcFx == 1m ? amt
                    : Math.Round(amt * srcFx, 2, MidpointRounding.AwayFromZero);
                var arAccount = await FindAccountAsync(companyId, "113", doc.Contact);
                var cashThb = Conv(doc.TotalAmount);
                decimal arThb, whtThb = 0m;
                if (whtBasis == Models.Enums.WhtRecognitionBasis.Cash)
                {
                    var thisWht = doc.WithholdingTaxAmount;
                    // ⚠️ สองลิสต์นี้ต้องยาวเท่ากันและเรียงตรงกันเสมอ (บรรทัดที่ i
                    // ของ pendingLines คู่กับ lineProjects[i]) — เดิม `if` ไม่มี
                    // ปีกกา ⇒ ตอน moneyAccount เป็น null จะได้ lineProjects เกินมา
                    // หนึ่งช่อง แล้ว **ป้ายโครงการของทุกบรรทัดที่เหลือเลื่อนไปหมด**
                    // (ผลตรวจทีม C · C-08)
                    if (moneyAccount != null)
                    {
                        pendingLines.Add((moneyAccount.Id, cashThb, 0m, $"รับชำระ - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                    }
                    if (thisWht > 0)
                    {
                        var whtAccount = await FindAccountAsync(companyId, "11910");
                        if (whtAccount != null)
                        {
                            whtThb = SrcThb(thisWht);
                            pendingLines.Add((whtAccount.Id, whtThb, 0m, "ภาษีหัก ณ ที่จ่าย (ลูกค้าหัก)"));
                            lineProjects.Add(doc.ProjectId);
                        }
                    }
                    arThb = SrcThb(doc.TotalAmount + thisWht);
                    if (arAccount != null)
                    {
                        pendingLines.Add((arAccount.Id, 0m, arThb, $"ตัดลูกหนี้ - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                    }
                }
                else
                {
                    // Accrual: AR was already net of WHT at Invoice time, so
                    // Receipt just moves the net cash from AR to Cash.
                    // ⚠️ สองลิสต์นี้ต้องยาวเท่ากันและเรียงตรงกันเสมอ (บรรทัดที่ i
                    // ของ pendingLines คู่กับ lineProjects[i]) — เดิม `if` ไม่มี
                    // ปีกกา ⇒ ตอน moneyAccount เป็น null จะได้ lineProjects เกินมา
                    // หนึ่งช่อง แล้ว **ป้ายโครงการของทุกบรรทัดที่เหลือเลื่อนไปหมด**
                    // (ผลตรวจทีม C · C-08)
                    if (moneyAccount != null)
                    {
                        pendingLines.Add((moneyAccount.Id, cashThb, 0m, $"รับชำระ - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                    }
                    arThb = SrcThb(doc.TotalAmount);
                    if (arAccount != null)
                    {
                        pendingLines.Add((arAccount.Id, 0m, arThb, $"ตัดลูกหนี้ - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                    }
                }
                // Realized FX: Dr รวม (cash+wht) เทียบ Cr AR ที่ rate ต้นทาง
                var recFxDiff = cashThb + whtThb - arThb;
                if (recFxDiff != 0m && srcFx != doc.ExchangeRate)
                {
                    var fxAcc = await ResolveFxGainLossAccountAsync(companyId, isGain: recFxDiff > 0);
                    if (fxAcc != null)
                    {
                        pendingLines.Add(recFxDiff > 0
                            ? (fxAcc.Id, 0m, recFxDiff, $"กำไรจากอัตราแลกเปลี่ยน (realized) - {doc.DocumentNumber}")
                            : (fxAcc.Id, -recFxDiff, 0m, $"ขาดทุนจากอัตราแลกเปลี่ยน (realized) - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                    }
                }
            }
            else
            {
                // นำมัดจำมาหักแบบขับ JE (opt-in): Dr เงินสด "สุทธิ" (Total−Applied)
                // + กลับบัญชี deferred ของใบมัดจำที่อ้าง → JE self-contained ในใบเดียว
                // (ไม่ต้องมี JV แยก). กัน double-reverse: mark ใบมัดจำ realized +
                // DepositAppliedToDocumentId. เฉพาะใบที่ไม่ใช่มัดจำเอง (รับรู้รายได้เต็ม)
                var driveDeposit = doc.DepositAppliedAmount > 0 && doc.DepositAppliedDrivesJournal
                    && !doc.IsDeposit && !string.IsNullOrWhiteSpace(doc.DepositAppliedRef);
                var cashAmt = driveDeposit ? doc.TotalAmount - doc.DepositAppliedAmount : doc.TotalAmount;

                if (moneyAccount != null && cashAmt != 0m)
                    AddLine(moneyAccount.Id, cashAmt, 0,
                        $"{(doc.BankAccountId.HasValue ? "รับเงินเข้าบัญชี" : "รับเงินสด")}{(driveDeposit ? " (สุทธิหลังหักมัดจำ)" : "")} - {doc.DocumentNumber}");

                // COGS perpetual สำหรับใบเสร็จ standalone ที่ขายสินค้าคงคลัง — ตามนโยบาย
                // CashSaleStockPolicy เดียวกับที่ ApplyStockMovementsAsync ใช้ตัดสต๊อก (สองที่นี้
                // ต้องตอบตรงกันเสมอ ไม่งั้นสต๊อกลดแต่ GL 11500 ไม่ลด หรือกลับกัน) · สูตร/บัญชี
                // เดียวกับสาขา Invoice/TaxInvoice (Dr 51110 / Cr 11500) — ERP_REVIEW A-06
                if (CashSaleStockRules.AppliesTo(doc)
                    && CashSaleStockRules.PostsCogs(await GetCashSaleStockPolicyAsync(companyId)))
                {
                    var rcCogs = await ComputeSalesCogsAsync(companyId, doc);
                    if (rcCogs > 0)
                    {
                        var rcCogsAcc = await FindAccountAsync(companyId, "51110") ?? await FindAccountAsync(companyId, "511");
                        var rcInvAcc = await FindAccountAsync(companyId, "11500") ?? await FindAccountAsync(companyId, "115");
                        if (rcCogsAcc != null && rcInvAcc != null)
                        {
                            AddLine(rcCogsAcc.Id, rcCogs, 0, $"ต้นทุนขาย - {doc.DocumentNumber}");
                            AddLine(rcInvAcc.Id, 0, rcCogs, $"ตัดสินค้าคงเหลือ - {doc.DocumentNumber}");
                        }
                        else
                        {
                            _logger.LogWarning(
                                "ไม่พบผังต้นทุนขาย (511xx) หรือสินค้าคงเหลือ (115xx) — ข้ามการลง COGS ของใบเสร็จ {DocNo}",
                                doc.DocumentNumber);
                            AppendInternalNote(doc, "⚠️ ไม่ได้ลงต้นทุนขายให้ใบเสร็จนี้ (ผังไม่มี 511xx/115xx) — ตรวจผังบัญชีแล้วลง JE ปรับปรุงเอง");
                        }
                    }
                }

                if (driveDeposit)
                {
                    // ── มัดจำหลายใบ (spec TakeTime hotel): depositAppliedRef คั่นจุลภาค ──
                    // resolve + reverse **ทุกใบเต็มยอดคงเหลือ** (GL-driven ต่อใบ — Dr บัญชี
                    // 215xx/217xx + 21913/21911 ที่แต่ละใบ Cr ไว้จริง). ผลรวม Dr ต้อง =
                    // doc.DepositAppliedAmount (ยอดรวมที่ TakeTime ส่ง) → cashAmt (คิดไว้
                    // ข้างบน = Total − DepositAppliedAmount) + ผลรวมนี้ = สมดุลพอดี;
                    // ไม่ตรง → AutoPost balance check throw → degrade เป็นตั้งหนี้ (ปลอดภัย).
                    // (เลขเดียว → else ด้านล่าง = logic เดิม ไม่แตะ เพื่อ zero regression)
                    var _depRefs = DepositReversalMath.ParseDepositRefs(doc.DepositAppliedRef);
                    if (_depRefs.Length > 1)
                    {
                        // กันเลขมัดจำซ้ำในลิสต์ ("REC-9, REC-9") → reverse ใบเดียวกันเบิ้ล
                        // (one-shot guard ผ่านเพราะ AppliedTo==doc.Id ตัวเอง) — dedup ตาม id
                        var _seenDeps = new HashSet<Guid>();
                        foreach (var depRef in _depRefs)
                        {
                            // ref = เลข NextAcc หรือเลขระบบต้นทาง (Reference/externalRef)
                            var mDepId = await _db.Documents.AsNoTracking()
                                .Where(d => d.CompanyId == companyId && d.IsDeposit && !d.IsDeleted
                                    && d.DocumentNumber == depRef)
                                .Select(d => (Guid?)d.Id).FirstOrDefaultAsync()
                                ?? await _db.Documents.AsNoTracking()
                                    .Where(d => d.CompanyId == companyId && d.IsDeposit && !d.IsDeleted
                                        && d.Reference == depRef)
                                    .Select(d => (Guid?)d.Id).FirstOrDefaultAsync();
                            if (!mDepId.HasValue)
                                throw new InvalidOperationException(
                                    $"หักมัดจำหลายใบ: ไม่พบใบมัดจำ {depRef} (IsDeposit — เทียบทั้งเลขเอกสารและ external ref) — ตรวจ depositAppliedRef");
                            if (!_seenDeps.Add(mDepId.Value)) continue;   // ใบนี้หักไปแล้วในรอบนี้ → ข้าม
                            // row-lock กัน race เหมือนใบเดียว
                            await _db.Database.ExecuteSqlRawAsync(
                                @"SELECT ""Id"" FROM ""Documents"" WHERE ""Id"" = {0} AND ""CompanyId"" = {1} FOR UPDATE",
                                mDepId.Value, companyId);
                            var mDeposit = await _db.Documents.FirstOrDefaultAsync(
                                d => d.Id == mDepId.Value && d.CompanyId == companyId);
                            if (mDeposit == null) continue;
                            // one-shot guard ต่อใบ (self-heal ถ้าใบที่หักถูก void/ลบ → มาร์คโมฆะ)
                            if (mDeposit.DepositAppliedToDocumentId.HasValue
                                && mDeposit.DepositAppliedToDocumentId.Value != doc.Id)
                            {
                                var mPrior = await _db.Documents.AsNoTracking().FirstOrDefaultAsync(d =>
                                    d.Id == mDeposit.DepositAppliedToDocumentId.Value && d.CompanyId == companyId);
                                if (mPrior != null && mPrior.Status != DocumentStatus.Voided)
                                    throw new InvalidOperationException(
                                        $"หักมัดจำหลายใบ: มัดจำ {mDeposit.DocumentNumber} ถูกนำไปหักกับ {mPrior.DocumentNumber} แล้ว");
                            }
                            // อ่านขา Cr จริงของใบมัดจำ → กลับ "เต็มยอดคงเหลือ" (net GL)
                            var mGl = await _db.JournalEntryLines
                                .Where(l => !l.IsDeleted && l.JournalEntry.CompanyId == companyId
                                    && l.JournalEntry.SourceDocumentId == mDeposit.Id && !l.JournalEntry.IsDeleted
                                    && (l.JournalEntry.Status == JournalEntryStatus.Posted
                                        || l.JournalEntry.Status == JournalEntryStatus.Reversed))
                                .Select(l => new { l.AccountId, l.CreditAmount, l.DebitAmount })
                                .ToListAsync();
                            var mAcctIds = mGl.Select(l => l.AccountId).Distinct().ToList();
                            var mCodes = await _db.ChartOfAccounts.AsNoTracking()
                                .Where(a => a.CompanyId == companyId && mAcctIds.Contains(a.Id))
                                .Select(a => new { a.Id, a.AccountCode }).ToListAsync();
                            string MCode(Guid id) => mCodes.FirstOrDefault(a => a.Id == id)?.AccountCode ?? "";
                            var mDef = mGl.Where(l => MCode(l.AccountId).StartsWith("217") || MCode(l.AccountId).StartsWith("215"))
                                .GroupBy(l => l.AccountId)
                                .Select(g => new { AccountId = g.Key, Net = g.Sum(x => x.CreditAmount - x.DebitAmount) })
                                .Where(x => x.Net > 0.005m).OrderByDescending(x => x.Net).FirstOrDefault();
                            var mV13 = mGl.Where(l => MCode(l.AccountId) == "21913")
                                .GroupBy(l => l.AccountId).Select(g => new { AccountId = g.Key, Net = g.Sum(x => x.CreditAmount - x.DebitAmount) })
                                .FirstOrDefault(x => x.Net > 0.005m);
                            var mV11 = mGl.Where(l => MCode(l.AccountId) == "21911")
                                .GroupBy(l => l.AccountId).Select(g => new { AccountId = g.Key, Net = g.Sum(x => x.CreditAmount - x.DebitAmount) })
                                .FirstOrDefault(x => x.Net > 0.005m);
                            var mVat = mV13 ?? mV11;
                            // P0-3 รอบ 193 — มัดจำที่ออกใบกำกับแล้ว (Cr 21911 จริง) ห้ามหักเต็มจำนวนเข้าใบที่คิด VAT เต็ม
                            if (Accounting.Helpers.DepositPolicyResolver.GrossApplyBlocked(mV11?.Net ?? 0m, depositVatPending: mV13 != null))
                                throw new Accounting.Helpers.BusinessRuleException(
                                    Accounting.Helpers.DepositPolicyResolver.GrossApplyBlockedMessage(mDeposit.DocumentNumber),
                                    Accounting.Helpers.DepositPolicyResolver.ImmediateVatGrossApplyRuleCode);
                            if (mDef == null && mVat == null)
                                throw new InvalidOperationException(
                                    $"หักมัดจำหลายใบ: ใบมัดจำ {mDeposit.DocumentNumber} ไม่มียอดรับล่วงหน้าคงเหลือใน GL (ถูกรับรู้/หักไปแล้ว)");
                            if (mDef != null && mDef.Net != 0m)
                                AddLine(mDef.AccountId, mDef.Net, 0,
                                    $"ตัดขายรอรับรู้ (นำมัดจำ {mDeposit.DocumentNumber} มาหักเต็มใบ)", doc.ProjectId);
                            if (mVat != null && mVat.Net > 0)
                                AddLine(mVat.AccountId, mVat.Net, 0,
                                    mV13 != null ? $"ตัดภาษีขายรอเรียกเก็บ (มัดจำ {mDeposit.DocumentNumber} → ใบกำกับ)"
                                                 : $"ล้าง VAT มัดจำ {mDeposit.DocumentNumber}", doc.ProjectId);
                            // mark ใบมัดจำใช้เต็ม (กันรับรู้/หักซ้ำ)
                            mDeposit.DepositRealizedAmount = mDeposit.SubTotal;
                            mDeposit.DepositRealizedAt = doc.DocumentDate;
                            if (mV13 != null) mDeposit.DepositOutputVatRecognizedAt = doc.DocumentDate;
                            mDeposit.DepositAppliedToDocumentId = doc.Id;
                        }
                    }
                    else
                    {
                    // row-lock ใบมัดจำก่อนอ่าน (audit F9B): approve 2 ใบพร้อมกันที่หัก
                    // มัดจำใบเดียว = read-modify-write race บน DepositRealizedAmount/
                    // AppliedToDocumentId (Document ไม่มี concurrency token) → lost
                    // update + Dr เบิ้ล. lock ใน transaction ของ approve ให้ serialize
                    // ref = เลข NextAcc (DocumentNumber) หรือเลขระบบต้นทาง (Reference =
                    // externalRef เช่น REC260713008 ของ TakeTime) — เดิมจับคู่แค่เลขเรา
                    // → TakeTime ส่งเลขเขา → หาไม่เจอ → degrade เป็นตั้งหนี้เสมอ
                    var depIdForLock = await _db.Documents.AsNoTracking()
                        .Where(d => d.CompanyId == companyId && d.IsDeposit && !d.IsDeleted
                            && d.DocumentNumber == doc.DepositAppliedRef)
                        .Select(d => (Guid?)d.Id).FirstOrDefaultAsync()
                        ?? await _db.Documents.AsNoTracking()
                            .Where(d => d.CompanyId == companyId && d.IsDeposit && !d.IsDeleted
                                && d.Reference == doc.DepositAppliedRef)
                            .Select(d => (Guid?)d.Id).FirstOrDefaultAsync();
                    if (depIdForLock.HasValue)
                        await _db.Database.ExecuteSqlRawAsync(
                            @"SELECT ""Id"" FROM ""Documents"" WHERE ""Id"" = {0} AND ""CompanyId"" = {1} FOR UPDATE",
                            depIdForLock.Value, companyId);
                    var deposit = depIdForLock.HasValue
                        ? await _db.Documents.FirstOrDefaultAsync(d => d.Id == depIdForLock.Value)
                        : null;
                    if (deposit != null)
                    {
                        // ── เคส A: มัดจำเป็น "ใบมัดจำ" (Document) ในระบบ (เช่น REC-) ──
                        // guards (audit F4 — เดิมเคส A ไม่มี guard เลย):
                        // (1) one-shot + self-heal เหมือนเคส B: มัดจำถูกหักโดยใบอื่นที่
                        //     ยัง "มีชีวิต" → block; ใบนั้นถูก void/ลบ → มาร์คโมฆะ
                        if (deposit.DepositAppliedToDocumentId.HasValue
                            && deposit.DepositAppliedToDocumentId.Value != doc.Id)
                        {
                            var priorCo = await _db.Documents.AsNoTracking().FirstOrDefaultAsync(d =>
                                d.Id == deposit.DepositAppliedToDocumentId.Value && d.CompanyId == companyId);
                            if (priorCo != null && priorCo.Status != DocumentStatus.Voided)
                                throw new InvalidOperationException(
                                    $"หักมัดจำแบบขับ JE: มัดจำ {deposit.DocumentNumber} ถูกนำไปหักกับ {priorCo.DocumentNumber} แล้ว (กัน reverse ซ้ำ)");
                        }
                        // หลักเดียวกับเคส B: อ่าน "ขา Cr จริง" จาก JE ของใบมัดจำ แล้วกลับ
                        // ตามนั้น — ห้าม assume โหมดจาก field/flag/setting เพราะเอกสารอยู่
                        // ในมือแล้ว (TakeTime §5):
                        //   gross (Cr 217xx เต็ม ไม่มีขา VAT)  → Dr 217xx เต็มยอดที่หัก
                        //   net + Cr 21913 (defer)             → Dr 217xx + Dr 21913 (Cr 21911 ใบเช็คเอาท์เต็ม)
                        //   net + Cr 21911 (รับรู้แล้ว)         → Dr 217xx + Dr 21911 (net กับ Cr 21911 ใบเช็คเอาท์)
                        // fallback เมื่อไม่พบ JE ผูกใบมัดจำ (โพสต์นอกระบบ): field เอกสาร + flag
                        var depGlLines = await _db.JournalEntryLines
                            .Where(l => !l.IsDeleted
                                && l.JournalEntry.CompanyId == companyId
                                && l.JournalEntry.SourceDocumentId == deposit.Id
                                && !l.JournalEntry.IsDeleted
                                && (l.JournalEntry.Status == JournalEntryStatus.Posted
                                    || l.JournalEntry.Status == JournalEntryStatus.Reversed))
                            .Select(l => new { l.AccountId, l.CreditAmount, l.DebitAmount })
                            .ToListAsync();
                        var depGlAcctIds = depGlLines.Select(l => l.AccountId).Distinct().ToList();
                        var depGlAccts = await _db.ChartOfAccounts.AsNoTracking()
                            .Where(a => a.CompanyId == companyId && depGlAcctIds.Contains(a.Id))
                            .Select(a => new { a.Id, a.AccountCode })
                            .ToListAsync();
                        string DepCodeOf(Guid id) => depGlAccts.FirstOrDefault(a => a.Id == id)?.AccountCode ?? "";
                        var glDeferred = depGlLines
                            .Where(l => DepCodeOf(l.AccountId).StartsWith("217") || DepCodeOf(l.AccountId).StartsWith("215"))
                            .GroupBy(l => l.AccountId)
                            .Select(g => new { AccountId = g.Key, Net = g.Sum(x => x.CreditAmount - x.DebitAmount) })
                            .Where(x => x.Net > 0.005m)
                            .OrderByDescending(x => x.Net)
                            .FirstOrDefault();
                        var glVat13 = depGlLines.Where(l => DepCodeOf(l.AccountId) == "21913")
                            .GroupBy(l => l.AccountId)
                            .Select(g => new { AccountId = g.Key, Net = g.Sum(x => x.CreditAmount - x.DebitAmount) })
                            .FirstOrDefault(x => x.Net > 0.005m);
                        var glVat11 = depGlLines.Where(l => DepCodeOf(l.AccountId) == "21911")
                            .GroupBy(l => l.AccountId)
                            .Select(g => new { AccountId = g.Key, Net = g.Sum(x => x.CreditAmount - x.DebitAmount) })
                            .FirstOrDefault(x => x.Net > 0.005m);

                        decimal depBase, depVat;
                        Guid? deferredAcctId, vatAcctId;
                        bool depVatDeferredPending;
                        if (glDeferred != null)
                        {
                            // GL-driven: สัดส่วนฐาน/VAT จากขา Cr จริง — gross ไม่มีขา VAT
                            // → ratio 0 → Dr 217xx เต็ม. กลับ "บัญชีเดิมที่ถูกเครดิต" ไม่เดาผัง
                            var glVat = glVat13 ?? glVat11;
                            (depBase, depVat) = DepositReversalMath.SplitBaseVat(
                                doc.DepositAppliedAmount, glDeferred.Net, glVat?.Net ?? 0m);
                            deferredAcctId = glDeferred.AccountId;
                            vatAcctId = glVat?.AccountId;
                            depVatDeferredPending = glVat13 != null && depVat > 0;
                        }
                        else
                        {
                            // fallback: JE มัดจำไม่ผูก SourceDocumentId → field เอกสาร + flag
                            // (deferredCr = ฐาน = SubTotal ; vatCr = VatAmount → ratio = VAT/Total)
                            (depBase, depVat) = DepositReversalMath.SplitBaseVat(
                                doc.DepositAppliedAmount, deposit.TotalAmount - deposit.VatAmount, deposit.VatAmount);
                            var depDeferredAcc = await FindAccountAsync(companyId, deposit.DepositDeferredAccountCode ?? "21712")
                                ?? await FindAccountAsync(companyId, "217");
                            deferredAcctId = depDeferredAcc?.Id;
                            depVatDeferredPending = depVat > 0 && deposit.DepositOutputVatDeferred
                                && deposit.DepositOutputVatRecognizedAt == null;
                            var depVatAcc = depVat > 0
                                ? await FindAccountAsync(companyId, depVatDeferredPending ? "21913" : "21911")
                                : null;
                            vatAcctId = depVatAcc?.Id;
                        }

                        // P0-3 รอบ 193 — มัดจำที่ออกใบกำกับแล้ว ห้ามหักเต็มจำนวนเข้าใบที่คิด VAT เต็ม (ด่านเดียวกับปุ่มหักมัดจำ)
                        if (Accounting.Helpers.DepositPolicyResolver.GrossApplyBlocked(depVat, depVatDeferredPending))
                            throw new Accounting.Helpers.BusinessRuleException(
                                Accounting.Helpers.DepositPolicyResolver.GrossApplyBlockedMessage(deposit.DocumentNumber),
                                Accounting.Helpers.DepositPolicyResolver.ImmediateVatGrossApplyRuleCode);

                        // (2) over-apply guard (audit F4): ห้ามหักเกิน "มัดจำคงเหลือจริง"
                        //     GL-driven → เทียบ net คงเหลือใน GL ของใบมัดจำเอง (Realize/
                        //     Apply เดิม Dr ลด net นี้แล้ว; drives รอบก่อนกันด้วย one-shot)
                        //     fallback → เทียบ subledger (SubTotal − Realized − คืนแล้ว)
                        //     ครอบเคส "มัดจำถูก realize หมดแล้ว" ที่เดิมหลุดผ่าน fallback
                        var fbVatPortion = deposit.TotalAmount > 0 ? deposit.VatAmount / deposit.TotalAmount : 0m;
                        var availableBase = glDeferred != null
                            ? glDeferred.Net
                            : deposit.SubTotal - deposit.DepositRealizedAmount
                              - Math.Round(deposit.DepositRefundedAmount * (1 - fbVatPortion), 2, MidpointRounding.AwayFromZero);
                        if (depBase > availableBase + 0.005m)
                            throw new InvalidOperationException(
                                $"หักมัดจำแบบขับ JE: ยอดที่หัก (ฐาน {depBase:N2}) เกินมัดจำ {deposit.DocumentNumber} " +
                                $"คงเหลือ ({Math.Max(0, availableBase):N2}) — มัดจำอาจถูกรับรู้/ตัดชำระ/คืนไปแล้ว");

                        // Dr กลับ "ขายรอรับรู้" (217xx/215xx) ของใบมัดจำ
                        if (deferredAcctId.HasValue && depBase != 0m)
                            AddLine(deferredAcctId.Value, depBase, 0, $"ตัดขายรอรับรู้ (นำมัดจำ {deposit.DocumentNumber} มาหัก)", doc.ProjectId);
                        // Dr กลับ VAT ของใบมัดจำ (ถ้ามีขา VAT): 21913 (defer) หรือ 21911
                        if (depVat > 0 && vatAcctId.HasValue)
                            AddLine(vatAcctId.Value, depVat, 0,
                                depVatDeferredPending ? "ตัดภาษีขายรอเรียกเก็บ (มัดจำ→ใบกำกับ)" : "ล้าง VAT มัดจำ",
                                doc.ProjectId);

                        // mark ใบมัดจำถูกใช้ (กันรับรู้ซ้ำจากช่องทางอื่น)
                        deposit.DepositRealizedAmount += depBase;
                        if (deposit.SubTotal - deposit.DepositRealizedAmount <= 0.005m)
                            deposit.DepositRealizedAt = doc.DocumentDate;
                        if (depVatDeferredPending)
                            deposit.DepositOutputVatRecognizedAt = doc.DocumentDate;
                        deposit.DepositAppliedToDocumentId = doc.Id;
                    }
                    else
                    {
                        // ── เคส B: มัดจำเป็น "สมุดรายวันภายนอก" (เช่น JV-INT ที่ระบบ
                        //    integration ลง Cr 217xx/21913 เอง ไม่มีใบมัดจำใน NextAcc) ──
                        //    resolve DepositAppliedRef เป็น JournalEntry.EntryNumber แล้ว
                        //    กลับ deferred ของ journal นั้น → net JE self-contained ใบเดียว
                        //    (TakeTime point 2: "drives รับ journal ref").
                        // resolve จาก EntryNumber — รับทั้ง Posted และ Reversed เพราะ
                        // เมื่อ JV ถูก reverse สถานะเปลี่ยนเป็น Reversed แต่บรรทัด **ยังอยู่
                        // ใน GL** (offset ด้วย reversal — ตรงกับ GetGeneralLedger/TrialBalance
                        // ที่นับ Posted||Reversed). ถ้ากรองแค่ Posted → หลัง reverse หา
                        // original ไม่เจอ. net-balance guard ด้านล่างเป็นตัวตัดสินว่า live/ตัด
                        var depJe = await _db.JournalEntries.Include(j => j.Lines)
                            .FirstOrDefaultAsync(j => j.CompanyId == companyId
                                && j.EntryNumber == doc.DepositAppliedRef
                                && (j.Status == JournalEntryStatus.Posted
                                    || j.Status == JournalEntryStatus.Reversed));
                        if (depJe == null)
                            throw new InvalidOperationException(
                                $"หักมัดจำแบบขับ JE: ไม่พบใบมัดจำหรือสมุดรายวันเลขที่ {doc.DepositAppliedRef} — ตรวจสอบ depositAppliedRef");
                        // row-lock JV + re-read mark หลังได้ lock (audit F9B): 2 checkout
                        // approve พร้อมกันอ้าง JV เดียว → ทั้งคู่อ่าน mark=null ก่อนใคร
                        // เขียน → ผ่าน guard ทั้งคู่ → Dr เบิ้ล. serialize ด้วย FOR UPDATE
                        await _db.Database.ExecuteSqlRawAsync(
                            @"SELECT ""Id"" FROM ""JournalEntries"" WHERE ""Id"" = {0} AND ""CompanyId"" = {1} FOR UPDATE", depJe.Id, companyId);
                        await _db.Entry(depJe).ReloadAsync();
                        // กัน double-reverse: journal เดียวถูกนำไปหักได้ครั้งเดียว —
                        // แต่ **มาร์คต้องยังมีชีวิต**: ถ้าเอกสารที่อ้าง (เช็คเอาท์เดิม) ถูก
                        // ลบ/void ไปแล้ว มาร์คเป็นโมฆะ → อนุญาตหักซ้ำ (self-heal). กัน
                        // เคส delete เอกสารเช็คเอาท์แล้วมัดจำค้าง stuck ("ถูกนำไปหักกับ
                        // เอกสารอื่นแล้ว") ทั้งที่เอกสารนั้นไม่มีอยู่จริงแล้ว.
                        // _db.Documents มี query filter !IsDeleted → doc ที่ถูกลบ = null
                        if (depJe.DepositAppliedToDocumentId.HasValue && depJe.DepositAppliedToDocumentId.Value != doc.Id)
                        {
                            var priorDoc = await _db.Documents.AsNoTracking()
                                .FirstOrDefaultAsync(d => d.Id == depJe.DepositAppliedToDocumentId.Value
                                    && d.CompanyId == companyId);
                            var priorAlive = priorDoc != null && priorDoc.Status != DocumentStatus.Voided;
                            if (priorAlive)
                                throw new InvalidOperationException(
                                    $"หักมัดจำแบบขับ JE: สมุดรายวัน {doc.DepositAppliedRef} ถูกนำไปหักกับเอกสารอื่นแล้ว (กัน reverse ซ้ำ)");
                            // มาร์คเก่าชี้เอกสารที่ลบ/void แล้ว → ล้าง แล้วหักใหม่ (จะ set
                            // = doc.Id ด้านล่าง) — net-balance guard ด้านล่างยังคุมยอดจริง
                        }

                        // ระบุบัญชี deferred (217xx/215xx) + VAT (21913/21911) จากบรรทัด
                        // Cr ของ journal จริง — กลับ "บัญชีเดิมที่ถูกเครดิต" ไม่เดาผัง
                        var lineAcctIds = depJe.Lines.Select(l => l.AccountId).Distinct().ToList();
                        var lineAccts = await _db.ChartOfAccounts.AsNoTracking()
                            .Where(a => a.CompanyId == companyId && lineAcctIds.Contains(a.Id))
                            .Select(a => new { a.Id, a.AccountCode })
                            .ToListAsync();
                        string CodeOf(Guid id) => lineAccts.FirstOrDefault(a => a.Id == id)?.AccountCode ?? "";

                        var deferredLine = depJe.Lines.FirstOrDefault(l => l.CreditAmount > 0
                            && (CodeOf(l.AccountId).StartsWith("217") || CodeOf(l.AccountId).StartsWith("215")));
                        if (deferredLine == null)
                            throw new InvalidOperationException(
                                $"หักมัดจำแบบขับ JE: สมุดรายวัน {doc.DepositAppliedRef} ไม่มีบรรทัดเครดิตบัญชีมัดจำ (215xx/217xx) — ตรวจ mapping ฝั่ง integration");
                        var vatLine = depJe.Lines.FirstOrDefault(l => l.CreditAmount > 0
                            && (CodeOf(l.AccountId) == "21913" || CodeOf(l.AccountId) == "21911"));

                        // ── NET-BALANCE guard (ครอบคลุมทุกกลไก un-reverse) ──
                        //    "มัดจำยังไม่ consume" = **ยอด Cr สุทธิจริงใน GL** ของบัญชีมัดจำ
                        //    ก้อนนี้ ไม่ใช่ธง ReversedByEntryId. คำนวณจาก Σ(Cr−Dr) บนบัญชี
                        //    deferred ของ **ทั้ง reverse-family** (transitive closure ตาม
                        //    OriginalEntryId ทุกชั้น) นับเฉพาะ Posted + ไม่ถูกลบ:
                        //      original(+Cr) → reversal(−Cr) → reversal-of-reversal(+Cr) ...
                        //    telescope เป็น net จริงเสมอ ไม่ว่า un-reverse ด้วยวิธีใด:
                        //      • reversal-of-reversal (post กลับ) → ชั้นใหม่ +Cr → net live
                        //      • void reversal ตรง ๆ (Status≠Posted) → หลุด → net live
                        //      • delete reversal (IsDeleted) → หลุด → net live
                        //      • reversal ยัง active → −Cr → net 0 (ตัด ไม่ให้หัก)
                        //    ไม่พึ่ง flag ReversedByEntryId เลย → partner un-reverse ด้วย
                        //    กลไกใดก็ได้ ขอแค่สะท้อนใน GL (JE posted/void/delete) ที่ NextAcc.
                        var family = new HashSet<Guid> { depJe.Id };
                        var frontier = new List<Guid> { depJe.Id };
                        for (var depth = 0; depth < 20 && frontier.Count > 0; depth++)
                        {
                            // นับทั้ง Posted + Reversed (ยังอยู่ใน GL); ตัด Voided/Draft/
                            // Rejected (ไม่แตะ GL) → net = ยอด GL จริง. reversal ที่ถูก void
                            // (un-reverse แบบ void) จึงหลุด → net กลับมา live
                            var children = await _db.JournalEntries
                                .Where(j => j.CompanyId == companyId && j.OriginalEntryId != null
                                    && frontier.Contains(j.OriginalEntryId.Value)
                                    && (j.Status == JournalEntryStatus.Posted
                                        || j.Status == JournalEntryStatus.Reversed) && !j.IsDeleted)
                                .Select(j => j.Id).ToListAsync();
                            frontier = children.Where(id => family.Add(id)).ToList();
                        }
                        var familyIds = family.ToList();
                        var liveNet = await _db.JournalEntryLines
                            .Where(l => !l.IsDeleted && familyIds.Contains(l.JournalEntryId)
                                && l.AccountId == deferredLine.AccountId)
                            .SumAsync(l => (decimal?)(l.CreditAmount - l.DebitAmount)) ?? 0m;
                        if (liveNet <= 0.005m)
                            throw new InvalidOperationException(
                                $"หักมัดจำแบบขับ JE: มัดจำ JV {doc.DepositAppliedRef} ถูกกลับรายการ/ใช้หมดแล้ว (ยอดคงค้างสุทธิ {liveNet:N2}) — ไม่มีมัดจำให้หัก");

                        // สัดส่วน VAT = VAT / (ฐาน+VAT) จากยอด Cr จริงของ journal
                        var jeBaseCr = deferredLine.CreditAmount;
                        var jeVatCr = vatLine?.CreditAmount ?? 0m;
                        var (depBase, depVat) = DepositReversalMath.SplitBaseVat(
                            doc.DepositAppliedAmount, jeBaseCr, jeVatCr);

                        // Dr กลับ "บัญชีเดิม" ที่ journal เครดิตไว้ (ตรงบัญชี ไม่เดา)
                        if (depBase != 0m)
                            AddLine(deferredLine.AccountId, depBase, 0,
                                $"ตัดขายรอรับรู้ (นำมัดจำ JV {depJe.EntryNumber} มาหัก)", doc.ProjectId);
                        if (depVat > 0 && vatLine != null)
                            AddLine(vatLine.AccountId, depVat, 0,
                                $"ตัด VAT มัดจำ (JV {depJe.EntryNumber} → ใบกำกับ)", doc.ProjectId);

                        // mark journal ว่าถูกนำไปหักแล้ว (กัน double-reverse)
                        depJe.DepositAppliedToDocumentId = doc.Id;
                    }
                    }   // ปิด else (มัดจำใบเดียว — logic เดิม)
                }

                if (doc.WithholdingTaxAmount > 0)
                {
                    var whtAccount = await FindAccountAsync(companyId, "11910");
                    if (whtAccount != null)
                        AddLine(whtAccount.Id, doc.WithholdingTaxAmount, 0, "ภาษีหัก ณ ที่จ่าย (ถูกหัก)");
                }

                // เงินมัดจำ/รับล่วงหน้า: Cr "ขายรอรับรู้" (217xx — หนี้สิน) แทน
                // บัญชีรายได้ เพราะยังไม่รับรู้รายได้จนกว่าจะส่งมอบ (RealizeDeposit
                // ตัด 217xx → รายได้ภายหลัง). VAT ยังถึงกำหนดทันที (ด้านล่าง).
                ChartOfAccount? deferredAcc = null;
                if (doc.IsDeposit)
                {
                    // เลือกผัง deferred: snapshot บนเอกสาร > line account (ถ้าชี้ 217xx)
                    // > default 21712 (ค่าสินค้ารับล่วงหน้า) → 217 parent.
                    deferredAcc = await FindAccountAsync(companyId,
                            doc.DepositDeferredAccountCode ?? "21712")
                        ?? await FindAccountAsync(companyId, "217");
                    if (deferredAcc != null)
                        doc.DepositDeferredAccountCode = deferredAcc.AccountCode;  // snapshot
                }

                foreach (var docLine in doc.Lines)
                {
                    // มัดจำ → ขายรอรับรู้; ปกติ → รายได้ (line account หรือ default)
                    // — ผังหมวดค่าใช้จ่ายที่หลงมาบนขานี้ตกกลับ default (safety net)
                    var creditAccountId = doc.IsDeposit
                        ? (deferredAcc?.Id ?? RevenueLegAccountId(docLine))
                        : RevenueLegAccountId(docLine);
                    if (creditAccountId.HasValue)
                        AddLine(creditAccountId.Value, 0, docLine.Amount,
                            doc.IsDeposit ? $"รับมัดจำ/รับล่วงหน้า - {docLine.Description}" : docLine.Description,
                            docLine.ProjectId);
                }

                if (doc.VatAmount > 0)
                {
                    // มัดจำเคส Deferred (tax point ยังไม่เกิด) → Cr "ภาษีขายรอเรียก
                    // เก็บ" 21913 (ยังไม่เข้า ภ.พ.30); เคส Immediate / ขายปกติ →
                    // Cr "ภาษีขาย ภ.พ.30" 21911 (เข้า ภ.พ.30 ทันที). เมื่อ tax point
                    // ของเคส deferred เกิดจริง RealizeDeposit จะย้าย 21913 → 21911.
                    var useDeferredVat = doc.IsDeposit && doc.DepositOutputVatDeferred;
                    var vatAccount = useDeferredVat
                        ? (await FindAccountAsync(companyId, "21913")
                           ?? await FindAccountAsync(companyId, "21911"))
                        : await FindAccountAsync(companyId, "21911");
                    if (vatAccount != null)
                        AddLine(vatAccount.Id, 0, doc.VatAmount,
                            useDeferredVat ? "ภาษีขายรอเรียกเก็บ (ยังไม่ถึงกำหนด §78)" : "ภาษีขาย");
                }
            }
        }
        // ============================================================
        // CASH PAYMENTS: PaymentVoucher
        // - Linked to existing PurchaseInvoice: settlement
        // - Standalone: direct cash purchase
        // ⚠️ mirror: PdfGenerationService.BuildProjectedGlAsync มีพรีวิว
        //   ("ประมาณการ — ก่อนอนุมัติ") ของ branch settlement นี้แยกต่างหาก —
        //   เปลี่ยนโครง JE ที่นี่ (ขา/บัญชี/basis) ต้องแก้พรีวิวให้ตรงด้วย
        //   (เคยหลุด: พรีวิวโชว์ Dr ค่าใช้จ่ายซ้ำ + WHT เข้า 21510 บัญชีมัดจำ)
        // ============================================================
        else if (doc.DocumentType == DocumentType.PaymentVoucher)
        {
            journalType = JournalType.CashPayments;

            if (doc.RelatedDocumentId.HasValue)
            {
                // Settlement must CLEAR the same payable account the source
                // document CREDITED — an Expense booked เจ้าหนี้อื่น (21220),
                // a PurchaseInvoice booked เจ้าหนี้การค้า (21210). Resolve by
                // the source doc's type so the liability nets to zero on the
                // right account.
                //
                // FX cross-rate: AP ตัดที่ rate ของเอกสารต้นทาง เงินสดจ่ายที่
                // rate ของ PV (วันจ่ายจริง) — ผลต่าง → FX realized G/L
                var pvSrc = await _db.Documents.AsNoTracking()
                    .Where(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId)
                    .Select(d => new { d.DocumentType, d.ExchangeRate })
                    .FirstOrDefaultAsync();
                var sourceType = pvSrc?.DocumentType ?? DocumentType.PurchaseInvoice;
                var pvSrcFx = pvSrc?.ExchangeRate ?? doc.ExchangeRate;
                decimal PvSrcThb(decimal amt) => pvSrcFx == 1m ? amt
                    : Math.Round(amt * pvSrcFx, 2, MidpointRounding.AwayFromZero);
                var apAccount = await ResolvePayableAccountAsync(companyId, sourceType, doc.Contact);
                var pvCashThb = Conv(doc.TotalAmount);
                decimal apThb, pvWhtThb = 0m;
                if (whtBasis == Models.Enums.WhtRecognitionBasis.Cash)
                {
                    // Cash basis: PI booked AP at GROSS, skipped the WHT
                    // payable. Here we clear AP at gross, pay net cash, and
                    // recognize WHT-Payable for the withheld portion. Use
                    // THIS voucher's WHT (per-installment) so cumulative
                    // matches the source PI's total over multiple PVs.
                    var thisWht = doc.WithholdingTaxAmount;
                    apThb = PvSrcThb(doc.TotalAmount + thisWht);
                    if (apAccount != null)
                    {
                        pendingLines.Add((apAccount.Id, apThb, 0m, $"ตัดเจ้าหนี้ - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                    }
                    if (moneyAccount != null)
                    {
                        pendingLines.Add((moneyAccount.Id, 0m, pvCashThb,
                            $"{(doc.BankAccountId.HasValue ? "จ่ายจากบัญชี" : "จ่ายเงิน")} - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                    }
                    if (thisWht > 0)
                    {
                        var whtAccount = await ResolveWhtPayableAccountAsync(companyId, doc.Contact, doc.IsForeignService);
                        if (whtAccount != null)
                        {
                            pvWhtThb = PvSrcThb(thisWht);
                            pendingLines.Add((whtAccount.Id, 0m, pvWhtThb, "ภาษีหัก ณ ที่จ่ายค้างจ่าย (ภ.ง.ด.)"));
                            lineProjects.Add(doc.ProjectId);
                        }
                    }
                }
                else
                {
                    // Accrual: AP at PI was already net of WHT, so PV just
                    // moves net cash from AP to Cash/Bank.
                    apThb = PvSrcThb(doc.TotalAmount);
                    if (apAccount != null)
                    {
                        pendingLines.Add((apAccount.Id, apThb, 0m, $"ตัดเจ้าหนี้ - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                    }
                    if (moneyAccount != null)
                    {
                        pendingLines.Add((moneyAccount.Id, 0m, pvCashThb,
                            $"{(doc.BankAccountId.HasValue ? "จ่ายจากบัญชี" : "จ่ายเงิน")} - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                    }
                }
                // Realized FX ฝั่งจ่าย: จ่าย THB มากกว่า AP ที่ตั้ง = ขาดทุน (Dr)
                var pvFxDiff = pvCashThb + pvWhtThb - apThb;
                if (pvFxDiff != 0m && pvSrcFx != doc.ExchangeRate)
                {
                    var fxAcc = await ResolveFxGainLossAccountAsync(companyId, isGain: pvFxDiff < 0);
                    if (fxAcc != null)
                    {
                        pendingLines.Add(pvFxDiff > 0
                            ? (fxAcc.Id, pvFxDiff, 0m, $"ขาดทุนจากอัตราแลกเปลี่ยน (realized) - {doc.DocumentNumber}")
                            : (fxAcc.Id, 0m, -pvFxDiff, $"กำไรจากอัตราแลกเปลี่ยน (realized) - {doc.DocumentNumber}"));
                        lineProjects.Add(doc.ProjectId);
                    }
                }
            }
            else
            {
                // PaymentVoucher standalone: เหมือน PI ทุกประการ แต่ Cr =
                // Cash/Bank โดยตรง. ภาษีซื้อต้องห้าม (§82/5) แยก per-line
                // เหมือนกัน — บรรทัด IsVatClaimable=false → Dr expense รวม
                // VAT, claimable → Dr expense net + รวม VAT เข้า 116.
                foreach (var docLine in doc.Lines)
                {
                    var expenseAccountId = docLine.AccountId ?? defaultExpense?.Id;
                    if (!expenseAccountId.HasValue) continue;
                    var debitAmount = docLine.IsVatClaimable
                        ? docLine.Amount
                        : docLine.Amount + docLine.VatAmount;
                    var desc = docLine.IsVatClaimable
                        ? docLine.Description
                        : $"{docLine.Description} (รวม VAT ต้องห้าม{(string.IsNullOrWhiteSpace(docLine.VatNonClaimableReason) ? "" : " - " + docLine.VatNonClaimableReason)})";
                    AddLine(expenseAccountId.Value, debitAmount, 0, desc, docLine.ProjectId);
                }

                var claimableVatPv = doc.Lines.Where(l => l.IsVatClaimable).Sum(l => l.VatAmount);
                if (claimableVatPv > 0)
                {
                    // เหมือน PI — เลือก 11610/11640/override ตาม completeness §86/4.
                    // §83/6 บริการต่างประเทศ → บังคับ 11640 เสมอ (เคลมได้หลังนำส่ง
                    // ภ.พ.36 + ได้ใบเสร็จ RD §77/2 — RecognizePp36 ย้ายให้ทีหลัง)
                    var (vatInputAccount, postedAsUndue) = doc.IsForeignService
                        ? ((await FindAccountAsync(companyId, ForeignServiceVat.Pp36InputVatCode)
                                ?? await FindAccountAsync(companyId, "11630")
                            ?? throw new InvalidOperationException("ไม่พบผังบัญชี 11640 (ภาษีซื้อยังไม่ถึงกำหนด) สำหรับ ภ.พ.36")), true)
                        : await ResolveInputVatAccountAsync(companyId, doc);
                    AddLine(vatInputAccount.Id, claimableVatPv, 0,
                        doc.IsForeignService ? "ภาษีซื้อยังไม่ถึงกำหนด (ภ.พ.36 §83/6 — รอนำส่ง+ใบเสร็จ RD)"
                        : postedAsUndue ? "ภาษีซื้อยังไม่ถึงกำหนด (ใบกำกับไม่ครบ §86/4)"
                                      : (doc.InputVatAccountCodeOverride != null
                                            ? $"VAT → {vatInputAccount.AccountCode} {vatInputAccount.AccountName} (override)"
                                            : "ภาษีซื้อ (เคลมได้)"));
                    doc.InputVatPostedAsUndue = postedAsUndue;
                }

                // §83/6: VAT ประเมินเอง → Cr เจ้าหนี้ ภ.พ.36 (21912); เงินที่จ่าย
                // ผู้ขายจริง = ฐานเท่านั้น (ผู้ขาย ตปท. ไม่เก็บ VAT ไทย — เดิม Cr
                // เงินสดรวม VAT = จ่ายเกิน 7%)
                var pp36SplitPv = ForeignServiceVat.SplitCredit(
                    doc.IsForeignService, doc.TotalAmount, doc.VatAmount);
                var pp36VatPv = pp36SplitPv.Pp36Credit;
                if (pp36VatPv > 0)
                {
                    var pp36AccPv = await FindAccountAsync(companyId, ForeignServiceVat.Pp36PayableCode)
                        ?? throw new InvalidOperationException("ไม่พบผังบัญชี 21912 (ภาษีขาย ภ.พ.36) — สร้างก่อนบันทึกบริการต่างประเทศ");
                    AddLine(pp36AccPv.Id, 0, pp36VatPv, $"เจ้าหนี้ ภ.พ.36 (VAT ประเมินเอง §83/6) - {doc.DocumentNumber}");
                }

                // Credit side depends on the settlement basis:
                //   Credit (เครดิต) → book a liability to Accounts Payable (212);
                //     the voucher carries an outstanding balance + due date and
                //     ages until a later payment settles it.
                //   Cash (จ่ายทันที) → money leaves now, credit Cash/Bank
                //     directly — never touches AP.
                if (doc.PaymentType == Models.Enums.PaymentType.Credit)
                {
                    // Role separation now BLOCKS this combination on create/
                    // edit (PV is real disbursement; ตั้งหนี้ belongs on an
                    // Expense). Path is kept for legacy approval/re-post of
                    // documents created before the rule landed — route them
                    // to the SAME payable the matching Expense would use
                    // (เจ้าหนี้อื่น 21220) so AP reports stay consistent.
                    var apAccount = await ResolvePayableAccountAsync(companyId, DocumentType.Expense, doc.Contact);
                    if (apAccount != null)
                        AddLine(apAccount.Id, 0, pp36SplitPv.PayeeCredit,
                            $"เจ้าหนี้ - {doc.DocumentNumber}");
                }
                else if (moneyAccount != null)
                {
                    AddLine(moneyAccount.Id, 0, pp36SplitPv.PayeeCredit,
                        $"{(doc.BankAccountId.HasValue ? "จ่ายจากบัญชี" : "จ่ายเงินสด")} - {doc.DocumentNumber}"
                        + (pp36VatPv > 0 ? " (ฐาน — VAT ตั้งหนี้ ภ.พ.36)" : ""));
                }

                if (doc.WithholdingTaxAmount > 0)
                {
                    var whtAccount = await ResolveWhtPayableAccountAsync(companyId, doc.Contact, doc.IsForeignService);
                    if (whtAccount != null)
                        AddLine(whtAccount.Id, 0, doc.WithholdingTaxAmount, "ภาษีหัก ณ ที่จ่ายค้างจ่าย");
                }
            }
        }
        else if (doc.DocumentType == DocumentType.GoodsReceiptNote)
        {
            // 3-way match — accrue goods received but not yet invoiced.
            //   Dr ค่าใช้จ่าย/สินค้า (per line, ex-VAT)   = goods value
            //   Cr เจ้าหนี้-รับสินค้ายังไม่วางบิล (GR-NI)  = goods value
            // No VAT/WHT here — those belong to the supplier's tax invoice,
            // booked when the PurchaseInvoice is raised against this GRN
            // (which then Dr GR-NI to clear this accrual). VAT/WHT entered on
            // a GRN line is ignored for posting (the goods value = SubTotal).
            journalType = JournalType.Purchase;
            var grNi = await EnsureGrNiAccountAsync(companyId);
            if (grNi == null)
                // เดิม return เงียบ ๆ → JE ไม่ลง แต่ ApplyStockMovements (เรียกหลังจากนี้
                // ใน transaction เดียวกัน) ยังเพิ่มสต๊อก → GL กับ subledger แยกทางกัน
                // ตรวจ TB ไม่เจอจนกว่าจะ reconcile มือ. บล็อกการอนุมัติแทน (เหมือน
                // guard pendingLines<2 ด้านล่าง) — JE throw ก่อน stock move → rollback ทั้งคู่.
                throw new InvalidOperationException(
                    "ไม่สามารถบันทึกบัญชีรับสินค้า (GR-NI) ได้: สร้างบัญชี 21240 เจ้าหนี้-รับสินค้ายังไม่วางบิล ไม่สำเร็จ. " +
                    "กรุณาตรวจสอบผังบัญชีก่อนอนุมัติใบรับสินค้า");

            // บรรทัดสินค้า TrackStock → Dr สินค้าคงเหลือ (perpetual) เหมือน PI
            var resolveGrnLineAcc = await BuildPurchaseLineAccountResolverAsync(
                companyId, doc, defaultExpense?.Id);
            foreach (var docLine in doc.Lines)
            {
                var expenseAccountId = resolveGrnLineAcc(docLine);
                if (expenseAccountId.HasValue)
                    AddLine(expenseAccountId.Value, docLine.Amount, 0, docLine.Description, docLine.ProjectId);
            }
            if (doc.SubTotal > 0)
                AddLine(grNi.Id, 0, doc.SubTotal, $"รับสินค้ายังไม่วางบิล - {doc.DocumentNumber}");
        }
        else
        {
            // Operational documents (Quotation, DeliveryNote, BillingNote, PR, PO) → no JE
            return;
        }

        if (pendingLines.Count < 2)
        {
            // Fail fast — silently skipping the JE while marking the document
            // Approved makes the GL miss revenue/expense for days/weeks until
            // someone runs a TB reconciliation. Better to block the approval
            // and force the operator to seed the missing COA accounts.
            throw new InvalidOperationException(
                "ไม่สามารถบันทึกบัญชีอัตโนมัติได้: ผังบัญชี (COA) ที่ใช้สำหรับเอกสารประเภทนี้ยังไม่ครบ. " +
                "กรุณาเปิดเมนู ตั้งค่าผังบัญชี เพื่อ seed บัญชีที่จำเป็น (รายได้ / ค่าใช้จ่าย / VAT / AR / AP / เงินสด) ก่อนอนุมัติ");
        }

        // Adjusting JE lines (Option 1) — user เพิ่ม Dr/Cr ลอย ๆ ที่ผูกเอกสาร
        // (เช่น ค่าธรรมเนียมโอน, สำรอง). รวมเข้า pendingLines ก่อน balance check.
        // user รับผิดชอบให้ adjusting Dr รวม = adjusting Cr รวม (net-zero) →
        // auto-gen ที่ balance อยู่แล้ว + adjusting net-zero = JE ยัง balance.
        var adjustingLines = await _db.Set<DocumentAdjustingJournalLine>()
            .AsNoTracking()
            .Where(a => a.DocumentId == doc.Id && !a.IsDeleted)
            .OrderBy(a => a.LineOrder)
            .ToListAsync();
        // ── รอบ 193 (คำตัดสินเจ้าของข้อ 1/4): ใบสำคัญจ่ายที่ "ยอดชำระจริง" ≠ ยอดเอกสาร ──
        // ใบกำกับ (ยอดเอกสาร) 536 · จ่ายจริง 438 ⇒ ขาเงินสดข้างบนลง 536 แล้ว ⇒ Dr เงินสดกลับ 98 · ส่วนต่างต้องถูกอธิบายด้วย
        // adjusting lines (ค่าส่ง Dr 51120 +37 · คูปอง Cr 51150 −135) — ตัวตัดสิน Helpers/PaymentSettlementAdjustment
        // ส่วนต่าง 0 (ไม่ได้ระบุยอดชำระจริง/ชนิดอื่น) = กติกาเดิม "adjusting lines ต้อง net-zero" ทุกประการ
        var settlementCashDelta = Accounting.Helpers.PaymentSettlementAdjustment.DocumentCashDelta(
            doc.DocumentType, doc.PaymentType, doc.IsForeignService, doc.TotalAmount, doc.ActualPaidAmount);
        if (adjustingLines.Count == 0 && settlementCashDelta != 0m
            && Accounting.Helpers.PaymentSettlementAdjustment.CheckDocumentLines(
                settlementCashDelta, 0m, 0m, doc.TotalAmount, doc.ActualPaidAmount) is string noAdjMsg)
            throw new Accounting.Helpers.BusinessRuleException(noAdjMsg, Accounting.Helpers.PaymentSettlementAdjustment.RuleCode);
        if (adjustingLines.Count > 0)
        {
            var adjDr = adjustingLines.Sum(a => a.DebitAmount);
            var adjCr = adjustingLines.Sum(a => a.CreditAmount);
            if (Accounting.Helpers.PaymentSettlementAdjustment.CheckDocumentLines(
                    settlementCashDelta, adjDr, adjCr, doc.TotalAmount, doc.ActualPaidAmount) is string adjMsg)
                throw new InvalidOperationException(adjMsg);
            // ห้าม adjusting line มีทั้ง Dr และ Cr ในบรรทัดเดียวกัน
            foreach (var a in adjustingLines)
            {
                if (a.DebitAmount > 0 && a.CreditAmount > 0)
                    throw new InvalidOperationException(
                        $"⛔ Adjusting line '{a.Description}' มีทั้ง Dr และ Cr — ต้องเลือกด้านเดียว");
                if (a.DebitAmount < 0 || a.CreditAmount < 0)
                    throw new InvalidOperationException(
                        $"⛔ Adjusting line '{a.Description}' มียอดติดลบ");
            }
            foreach (var a in adjustingLines)
            {
                AddLine(a.AccountId, a.DebitAmount, a.CreditAmount,
                    string.IsNullOrWhiteSpace(a.Description)
                        ? $"ปรับปรุง — {doc.DocumentNumber}"
                        : $"ปรับปรุง: {a.Description}",
                    a.ProjectId);
            }
        }
        if (settlementCashDelta != 0m)
        {
            // ขาเงินสดตามยอดชำระจริง: เงินสดที่ลงไว้ตามยอดเอกสาร ปรับด้วยส่วนต่าง (ผังเดียวกับขาเงินสดข้างบน — moneyAccount)
            if (moneyAccount == null)
                throw new InvalidOperationException(
                    "ไม่พบบัญชีเงินสด/ธนาคารของเอกสาร — ลงส่วนต่างยอดชำระจริงไม่ได้ (เลือกแหล่งเงินก่อนอนุมัติ)");
            var (deltaDr, deltaCr) = Accounting.Helpers.PaymentSettlementAdjustment.JournalSide(settlementCashDelta);
            AddLine(moneyAccount.Id, deltaDr, deltaCr,
                $"ส่วนต่างยอดชำระจริง {doc.ActualPaidAmount:N2} (ยอดเอกสาร {doc.TotalAmount:N2}) - {doc.DocumentNumber}");
        }

        // ── รอบ 193 (คำตัดสินเจ้าของข้อ 8): ผลต่างจากการปัดเศษ ──
        // สัญญา SubTotal = Σ บรรทัด + RoundingAdjustment ⇒ ขาที่ลงตามยอดบรรทัดกับขาที่ลงตามยอดรวมต่างกันเท่าผลต่างนี้พอดี
        // ⇒ ลงส่วนนั้นที่ผัง Helpers/DocumentRounding.AccountCode ในทิศที่ปิดสมดุล · ต่างไม่เท่าที่ประกาศ = ไม่ลง (ด่านสมดุลข้างล่างฟ้อง)
        if (doc.RoundingAdjustment != 0m)
        {
            var roundingJe = Accounting.Helpers.DocumentRounding.JournalLine(
                pendingLines.Sum(l => l.Debit) - pendingLines.Sum(l => l.Credit), Conv(doc.RoundingAdjustment));
            if (roundingJe is { } roundingSide)
            {
                var (rDr, rCr) = roundingSide;
                var roundingAccount = await FindAccountAsync(companyId, Accounting.Helpers.DocumentRounding.AccountCode)
                    ?? throw new Accounting.Helpers.BusinessRuleException(
                        $"ไม่พบผังบัญชี {Accounting.Helpers.DocumentRounding.AccountCode} "
                        + $"\"{Accounting.Helpers.DocumentRounding.AccountName}\" — เพิ่มผังนี้ที่หน้าผังบัญชี "
                        + $"(ใช้ลงผลต่างปัดเศษ {doc.RoundingAdjustment:N2} ของเอกสารนี้) แล้วอนุมัติอีกครั้ง",
                        Accounting.Helpers.DocumentRounding.RuleCode);
                // pendingLines เป็นยอดบาทแล้ว (Conv) — เพิ่มตรง ไม่ผ่าน AddLine ที่จะแปลงสกุลซ้ำ
                pendingLines.Add((roundingAccount.Id, rDr, rCr, $"{Accounting.Helpers.DocumentRounding.AccountName} - {doc.DocumentNumber}"));
                lineProjects.Add(doc.ProjectId);
            }
        }

        // Validate double-entry balance per Thai accounting standards (TAS 1)
        var totalDebit = pendingLines.Sum(l => l.Debit);
        var totalCredit = pendingLines.Sum(l => l.Credit);

        // FX rounding squeeze: Conv() ปัดเศษราย "บรรทัด" อิสระ → ผลรวม Dr/Cr ของ
        // เอกสารต่างสกุลเงินอาจต่างกันไม่กี่สตางค์แม้สมดุลในสกุลเงินตัวเอง (เช่น
        // round(Total×fx) ≠ Σ round(line×fx)). ดูดผลต่าง "เล็กระดับปัดเศษ" เข้า
        // บรรทัดยอดสูงสุด (มักเป็นลูกหนี้/เงินสด) กัน throw "ไม่สมดุล" จากการปัดเศษ.
        // ผลต่างใหญ่เกิน tolerance = imbalance จริง → ปล่อย throw ด้านล่าง.
        var balDiff = Math.Round(totalDebit - totalCredit, 2, MidpointRounding.AwayFromZero);
        // เปิด squeeze เฉพาะเอกสารต่างสกุลเงิน — เอกสาร THB (fx=1) Conv() ไม่ปัด
        // อะไรเลย ผลต่างที่เจอ = template ผิดจริง ต้อง throw ไม่ใช่ดูดเข้าลูกหนี้
        var fxSqueezeEligible = doc.ExchangeRate != 1m
            && !string.IsNullOrEmpty(doc.Currency) && doc.Currency != "THB";
        var roundingTol = fxSqueezeEligible ? 0.01m * pendingLines.Count + 0.01m : 0m;
        if (balDiff != 0m && Math.Abs(balDiff) <= roundingTol && pendingLines.Count > 0)
        {
            int idx = 0; decimal maxMag = -1m;
            for (int i = 0; i < pendingLines.Count; i++)
            {
                var mag = pendingLines[i].Debit + pendingLines[i].Credit;
                if (mag > maxMag) { maxMag = mag; idx = i; }
            }
            var pl = pendingLines[idx];
            // balDiff > 0 = เดบิตเกิน → ลดเดบิต (บรรทัดเดบิต) หรือเพิ่มเครดิต (บรรทัดเครดิต)
            pendingLines[idx] = pl.Debit >= pl.Credit
                ? (pl.AccountId, pl.Debit - balDiff, pl.Credit, pl.Description)
                : (pl.AccountId, pl.Debit, pl.Credit + balDiff, pl.Description);
            totalDebit = pendingLines.Sum(l => l.Debit);
            totalCredit = pendingLines.Sum(l => l.Credit);
        }

        if (Math.Round(totalDebit, 2, MidpointRounding.AwayFromZero) != Math.Round(totalCredit, 2, MidpointRounding.AwayFromZero))
            // ส่วนต่าง = ยอด VAT พอดี → บอกสาเหตุ + ทางแก้ ไม่ใช่โยนตัวเลขทิ้งไว้
            // เฉย ๆ (ผู้ใช้เจอข้อความเดิมแล้วทำอะไรต่อไม่ได้เลย — เคส IKEA/OCR)
            throw new InvalidOperationException(
                DocumentLineVatConvention.ExplainImbalance(totalDebit, totalCredit, doc.VatAmount)
                ?? $"การบันทึกบัญชีอัตโนมัติไม่สมดุล: เดบิต {totalDebit:N2} ≠ เครดิต {totalCredit:N2}");

        // ── ด่านตรวจโครงสร้าง JE ก่อนบันทึก (JournalPostingGuard) ──────────
        // สมดุลอย่างเดียวไม่พอ: เคยมี JE ที่ Dr=Cr เป๊ะแต่เครดิตทั้งใบลงบัญชี
        // WHT (ไม่มีขาเจ้าหนี้เลย) — ตรวจว่าเงินไปลงถูกกลุ่มบัญชี: WHT ≤ 15%
        // ของฐาน, VAT ไม่เกินเอกสาร, ฝั่งซื้อมีขาเครดิตเจ้าหนี้/เงินครบยอด.
        // Error = โยนทิ้งก่อน save (approve ล้มดัง ๆ ดีกว่าแยกประเภทผิดเงียบ ๆ)
        {
            var guardAcctIds = pendingLines.Select(l => l.AccountId).Distinct().ToList();
            var guardAccts = await _db.ChartOfAccounts.AsNoTracking()
                .Where(a => guardAcctIds.Contains(a.Id))
                .Select(a => new { a.Id, a.AccountCode, a.AccountType })
                .ToDictionaryAsync(a => a.Id);
            var guardLines = pendingLines
                .Where(l => guardAccts.ContainsKey(l.AccountId))
                .Select(l => new JournalPostingGuard.LineFacts(
                    guardAccts[l.AccountId].AccountCode, guardAccts[l.AccountId].AccountType,
                    l.Debit, l.Credit))
                .ToList();
            // ยอดบนเอกสารเป็น "สกุลเอกสาร" แต่ pendingLines ผ่าน Conv() เป็นบาทแล้ว
            // ⇒ ต้องบอกเรทให้ guard แปลงก่อนเทียบ ไม่งั้นใบ USD@35 จะ block ทุกใบ
            var guardFindings = JournalPostingGuard.Validate(guardLines,
                new JournalPostingGuard.DocFacts(
                    doc.DocumentType, doc.SubTotal, doc.VatAmount,
                    doc.WithholdingTaxAmount, doc.TotalAmount, doc.IsDeposit,
                    ExchangeRate: doc.ExchangeRate <= 0m ? 1m : doc.ExchangeRate));
            var guardError = JournalPostingGuard.ErrorSummary(guardFindings, doc.DocumentNumber);
            if (guardError != null)
                throw new InvalidOperationException(guardError);
            foreach (var w in guardFindings.Where(f => !f.IsError))
                _logger.LogWarning("JE guard เตือน {Doc}: [{Rule}] {Msg}",
                    doc.DocumentNumber, w.RuleCode, w.Message);
        }

        // Resolve fiscal period — block posting to closed/locked periods per
        // Thai accounting standard (TAS 1: closed period is immutable). If the
        // document falls within a closed period, the user must reopen it first
        // or re-date the document.
        var period = await _db.FiscalPeriods.FirstOrDefaultAsync(f =>
            f.CompanyId == companyId &&
            f.StartDate <= doc.DocumentDate &&
            f.EndDate >= doc.DocumentDate);
        if (period != null && period.Status != FiscalPeriodStatus.Open)
        {
            throw new InvalidOperationException(
                $"ไม่สามารถบันทึกบัญชีในงวด {period.Name} ได้ เนื่องจากงวดถูกปิดแล้ว " +
                $"กรุณาเปลี่ยนวันที่เอกสารเป็นงวดที่เปิดอยู่ หรือขอเปิดงวดก่อน");
        }

        // Generate entry number
        var prefix = journalType switch
        {
            JournalType.Sales => "SV",
            JournalType.Purchase => "UV",
            JournalType.CashReceipts => "RV",
            JournalType.CashPayments => "PV",
            _ => "JV"
        };
        var entryNumber = await GetNextJournalEntryNumberAsync(companyId, prefix);

        var entry = new JournalEntry
        {
            CompanyId = companyId,
            EntryNumber = entryNumber,
            EntryDate = doc.DocumentDate,
            JournalType = journalType,
            Description = $"Auto-post จาก {doc.DocumentNumber}",
            Reference = doc.DocumentNumber,
            Status = JournalEntryStatus.Posted,
            TotalDebit = totalDebit,
            TotalCredit = totalCredit,
            CreatedBy = createdBy,
            IsAutoGenerated = true,
            SourceDocumentId = doc.Id,
            FiscalPeriodId = period?.Id,
            // Header-level Project: enables filtering JE lookups by project even on
            // system-generated lines that inherit. ProjectAccountingService queries
            // (l.ProjectId == projectId || l.JournalEntry.ProjectId == projectId).
            ProjectId = doc.ProjectId,
            // Cost center / มิติ — ไหลจากเอกสารลง JE ให้รายงาน P&L ต่อสาขา/แผนก
            // มีข้อมูลจากเอกสารซื้อ-ขายจริง (เดิมได้เฉพาะ manual JE)
            DimensionId = doc.DimensionId
        };

        _db.JournalEntries.Add(entry);

        var order = 1;
        for (int i = 0; i < pendingLines.Count; i++)
        {
            var line = pendingLines[i];
            _db.JournalEntryLines.Add(new JournalEntryLine
            {
                JournalEntryId = entry.Id,
                AccountId = line.AccountId,
                DebitAmount = line.Debit,
                CreditAmount = line.Credit,
                Description = line.Description,
                LineOrder = order++,
                ProjectId = lineProjects[i]
            });
        }
    }

    /// <summary>โพสต์ JE "ขายเงินสด" (integration isCashSale) ผ่าน AutoPostToJournalAsync
    /// — TaxInvoice ที่ IssuedAsCashReceipt=true ลงแบบเงินสด: Dr เงินสด(paymentAccountId)
    /// + กลับมัดจำ 217xx/21913 (ถ้า DepositAppliedDrivesJournal) / Cr รายได้(ราย line)
    /// + Cr 21911 — **ไม่มีลูกหนี้การค้า** ใบเดียวจบ (reuse เส้น driveDeposit ที่ verified).
    /// AutoPost ไม่ SaveChanges เอง → wrapper นี้ save + คืน JE id. ถ้าล้ม → detach
    /// JE/line ที่ค้างใน context + rethrow (กัน pollution ให้ผู้เรียก fallback สะอาด).</summary>
    public async Task<Guid?> PostCashSaleJournalAsync(Guid companyId, Guid documentId)
    {
        var doc = await _db.Documents.Include(d => d.Lines)
            .FirstOrDefaultAsync(d => d.Id == documentId && d.CompanyId == companyId)
            ?? throw new KeyNotFoundException("ไม่พบเอกสาร");
        await _db.HydrateContactAsync(companyId, doc);   // กัน INNER JOIN ตัดใบที่ contact ถูกลบ
        try
        {
            await AutoPostToJournalAsync(companyId, doc, "integration-cashsale");
            await _db.SaveChangesAsync();
        }
        catch
        {
            // ล้าง in-memory changes ทั้งหมดที่ AutoPost ทำค้างไว้ (save ไม่สำเร็จ) เพื่อ
            // ไม่ให้ SaveChanges รอบถัดไปของผู้เรียก (degrade path) flush ค้าง/ซ้ำ:
            //  • JE/line ที่ Added → detach
            //  • Document/JE ที่ Modified (เช่น driveDeposit แก้ subledger ใบมัดจำ
            //    DepositRealizedAmount / case B แก้ depJe) → Reload คืนค่า DB
            //    (กัน "มัดจำถูกมาร์ค realized แต่ไม่มี JE reversal")
            foreach (var e in _db.ChangeTracker.Entries().ToList())
            {
                if (e.State == EntityState.Added
                    && (e.Entity is JournalEntry || e.Entity is JournalEntryLine))
                    e.State = EntityState.Detached;
                else if (e.State == EntityState.Modified
                    && (e.Entity is Document || e.Entity is JournalEntry))
                {
                    try { await e.ReloadAsync(); }
                    catch { e.State = EntityState.Unchanged; }
                }
            }
            throw;
        }
        return await _db.JournalEntries.AsNoTracking()
            .Where(j => j.CompanyId == companyId && j.SourceDocumentId == documentId
                && j.OriginalEntryId == null && j.Status == JournalEntryStatus.Posted && !j.IsDeleted)
            .OrderByDescending(j => j.CreatedAt)
            .Select(j => (Guid?)j.Id).FirstOrDefaultAsync();
    }

    /// <summary>เลขสมุดรายวันถัดไปของ prefix นั้น (SV/UV/RV/PV/JV) ต่อเดือน
    ///
    /// ⚠️ เดิมที่นี่มี **ตัวออกเลขของตัวเอง** ซ้ำกับ
    /// <c>JournalEntryBuilder.NextJournalNumberAsync</c> ทั้งที่เขียนลง number
    /// space เดียวกัน และล็อกด้วย <c>HashCode.Combine</c> ซึ่ง<b>สุ่ม seed ต่อ
    /// process</b> ⇒ คนละคีย์กับตัวกลาง ⇒ สองผู้ออกเลขไม่บล็อกกัน (ทั้งข้าม
    /// instance และข้ามผู้ออก) ⇒ ชน unique (CompanyId, EntryNumber) =
    /// "อนุมัติไม่สำเร็จ" แบบสุ่ม. อีกทั้งตัวเดิมเรียงด้วย string ⇒ พังที่เลข
    /// 5 หลัก (JV-202608-10000 เรียงต่ำกว่า …-9999)
    /// → ยุบทิ้ง ใช้ตัวกลางตัวเดียว (กฎ "resolver กลาง ห้ามคำนวณเอง")</summary>
    private Task<string> GetNextJournalEntryNumberAsync(Guid companyId, string prefix)
        => Journal.JournalEntryBuilder.NextJournalNumberAsync(_db, companyId, prefix, DateTime.UtcNow);

    /// <summary>Cap payer signature payload size — reject anything bigger
    /// than ~512 KB base64 (~384 KB raw image). Real signatures rendered at
    /// PDF DPI are well under 50 KB; if a caller posts a multi-megabyte
    /// blob it's a bug or abuse. Returns null for blank input so EF skips
    /// the column.</summary>
    private static string? TrimSignature(string? value)
    {
        if (string.IsNullOrWhiteSpace(value)) return null;
        var v = value.Trim();
        if (v.Length > 512 * 1024)
            throw new InvalidOperationException("รูปลายเซ็นมีขนาดใหญ่เกิน 512 KB — กรุณาบีบอัดก่อนส่ง");
        return v;
    }

    /// <summary>
    /// สร้าง Journal Entry สำหรับการชำระเงิน — เขียน DbContext โดยตรงภายใน transaction ของ caller
    /// รับเงิน (ฝั่งขาย): Dr Cash, Cr AR → สมุดรายวันรับ (RV)
    /// จ่ายเงิน (ฝั่งซื้อ): Dr AP, Cr Cash → สมุดรายวันจ่าย (PV)
    /// </summary>
    /// <summary>Resolve ผัง GL ฝั่งเงินสด/ธนาคารของ payment — ลำดับเดียวกับ
    /// CreatePaymentJournalAsync: override → LinkedAccount ของธนาคาร → 111.</summary>
    private async Task<ChartOfAccount?> ResolvePaymentCashAccountAsync(Guid companyId, Payment payment)
    {
        ChartOfAccount? cashAccount = null;
        if (payment.OverridePaymentAccountId.HasValue)
            cashAccount = await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
                a.Id == payment.OverridePaymentAccountId.Value && a.CompanyId == companyId && !a.IsDeleted);
        if (cashAccount == null && payment.BankAccountId.HasValue)
        {
            var linkedAcctId = await _db.Set<BankAccount>().AsNoTracking()
                .Where(b => b.Id == payment.BankAccountId.Value && b.CompanyId == companyId)
                .Select(b => b.LinkedAccountId)
                .FirstOrDefaultAsync();
            if (linkedAcctId.HasValue)
                cashAccount = await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
                    a.Id == linkedAcctId.Value && a.CompanyId == companyId && !a.IsDeleted);
        }
        return cashAccount ?? await FindAccountAsync(companyId, "111");
    }

    private async Task CreatePaymentJournalAsync(Guid companyId, Document doc, Payment payment, string createdBy,
        IReadOnlyList<(Guid AccountId, decimal Amount, string? Reason)>? settlementAdjustments = null)
    {
        var revenueTypes = new[] { DocumentType.Invoice, DocumentType.TaxInvoice, DocumentType.Receipt,
            DocumentType.DebitNote, DocumentType.BillingNote, DocumentType.ReceiptVoucher };
        var isRevenue = revenueTypes.Contains(doc.DocumentType);

        // ══ ใบลดหนี้/ใบเพิ่มหนี้มีสองฝั่ง — ทิศของเงินต้องตาม "ฝั่งของใบ" ไม่ใช่ชนิดเอกสาร ══
        // บั๊กจริง (ทีมตรวจรอบ 189 B-01 · main agent เปิดไฟล์ยืนยันแล้ว): เมธอดนี้เป็น
        // **จุดเดียวใน 31 จุดทั้งเรพ** ที่ตัดสินฝั่ง CN/DN เองโดยไม่ผ่าน
        // `Helpers/AdjustmentNoteAccount` และ **ไม่อ่าน `CnDnPurchaseSideOverride`** เลย
        // ทั้งที่ทุกเส้นอื่นอ่าน (`:13890` · `:13124` · `TaxService:362,731` ·
        // `AgingReportService:91`) และฟอร์มส่งค่านี้มาทุกใบ
        // ⇒ ใบเพิ่มหนี้ฝั่งซื้อที่**ไม่มีใบต้นทางในระบบ** (เคสที่ UI แนะนำเอง) ตอนจ่ายเงิน
        //   ลง Dr เงินสด / Cr ลูกหนี้ แทน Dr เจ้าหนี้ / Cr เงินสด ⇒ เงินสดเกินจริง
        //   สองเท่าของยอด และเจ้าหนี้ไม่ถูกตัด — เงียบจนถึงวันกระทบยอดธนาคาร
        // (นี่คือ "แก้ที่หนึ่ง เหลือที่เหลือ" ของรอบ 185 ที่ grep ไม่ครบ — F2 ข้อ 1)
        //
        // คู่สมมาตรที่รอบ 185 ก็ไม่ได้ดู: **ใบลดหนี้ก็มีสองฝั่งเหมือนกัน** — ฝั่งซื้อ
        // คือผู้ขายคืนเงินให้เรา (เงิน**เข้า**) ไม่ใช่เงินออกแบบฝั่งขาย
        if (doc.DocumentType is DocumentType.DebitNote or DocumentType.CreditNote)
        {
            DocumentType? adjSrcType = null;
            if (doc.RelatedDocumentId.HasValue)
                adjSrcType = await _db.Documents.AsNoTracking()
                    .Where(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId)
                    .Select(d => (DocumentType?)d.DocumentType)
                    .FirstOrDefaultAsync();

            // ชั้นคู่ค้า (ผู้ขายอย่างเดียว) ใช้เฉพาะตอนไม่มีทั้งคำสั่งผู้ใช้และใบต้นทาง
            var supplierOnly = false;
            if (doc.Contact is { } loaded)
                supplierOnly = loaded is { IsSupplier: true, IsCustomer: false };
            else if (doc.ContactId != Guid.Empty)
                supplierOnly = await _db.Contacts.AsNoTracking()
                    .Where(c => c.Id == doc.ContactId && c.CompanyId == companyId)
                    .Select(c => c.IsSupplier && !c.IsCustomer)
                    .FirstOrDefaultAsync();

            // ใบนี้ลงบัญชีไปแล้ว ⇒ ถามแบบ "ฝั่งของใบที่ลงแล้ว" (ผู้ใช้สั่งย้ายฝั่งชนะทุกชั้น)
            var adjSide = Accounting.Helpers.AdjustmentNoteAccount.ResolvePostedSide(
                userOverride: doc.CnDnPurchaseSideOverride,
                sourceType: adjSrcType,
                glTouchedInputVat: null,
                contactIsSupplierOnly: supplierOnly);

            // "ไม่รู้" ห้ามตกเป็นค่า default เงียบ ๆ — ทิศเงินผิดมองไม่เห็นจนกระทบยอด
            // ธนาคารไม่ลง ส่วนการบล็อกเห็นทันทีและมีทางไปต่อ (G5 "ทิศที่ความเสียหาย
            // มองเห็นและแก้ทัน")
            if (adjSide.Unknown)
                throw new Accounting.Helpers.BusinessRuleException(
                    $"เอกสาร {doc.DocumentNumber} เป็น"
                    + $"{(doc.DocumentType == DocumentType.CreditNote ? "ใบลดหนี้" : "ใบเพิ่มหนี้")}"
                    + " ที่ระบบยังไม่รู้ว่าเป็นฝั่งซื้อหรือฝั่งขาย จึงลงบัญชีการรับ/จ่ายเงินให้ไม่ได้ "
                    + "(ลงผิดทิศ = เงินสดกับเจ้าหนี้/ลูกหนี้เพี้ยนโดยไม่มีอะไรฟ้อง) — "
                    + "กรุณาเปิดเอกสารแล้วเลือกฝั่งให้ถูก หรือผูกใบต้นทาง แล้วลองรับ/จ่ายเงินใหม่");

            // ฝั่งซื้อ: ใบเพิ่มหนี้ = เราจ่ายเพิ่ม (เงินออก) · ใบลดหนี้ = ผู้ขายคืนเงิน (เงินเข้า)
            // ฝั่งขาย: ใบเพิ่มหนี้ = ลูกค้าจ่ายเพิ่ม (เงินเข้า) · ใบลดหนี้ = เราคืนลูกค้า (เงินออก)
            isRevenue = adjSide.IsPurchase
                ? doc.DocumentType == DocumentType.CreditNote
                : doc.DocumentType == DocumentType.DebitNote;
        }
        var journalType = isRevenue ? JournalType.CashReceipts : JournalType.CashPayments;

        // Resolve the CASH/BANK side of the entry. Priority:
        //   1. payment.OverridePaymentAccountId — explicit GL the operator chose
        //      (เงินทดรองกรรมการ / เงินสดย่อย / clearing) — funds from non-bank.
        //   2. the chosen bank account's LinkedAccount GL — so a Bank Transfer
        //      actually hits the bank's GL, not generic cash. (BUG FIX: this
        //      line previously ALWAYS posted to 111 regardless of how the
        //      payment was made, so every bank transfer landed in Cash on Hand.)
        //   3. fall back to the default cash account "111".
        ChartOfAccount? cashAccount = null;
        if (payment.OverridePaymentAccountId.HasValue)
            cashAccount = await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
                a.Id == payment.OverridePaymentAccountId.Value && a.CompanyId == companyId && !a.IsDeleted);
        if (cashAccount == null && payment.BankAccountId.HasValue)
        {
            var linkedAcctId = await _db.Set<BankAccount>().AsNoTracking()
                .Where(b => b.Id == payment.BankAccountId.Value && b.CompanyId == companyId)
                .Select(b => b.LinkedAccountId)
                .FirstOrDefaultAsync();
            if (linkedAcctId.HasValue)
                cashAccount = await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
                    a.Id == linkedAcctId.Value && a.CompanyId == companyId && !a.IsDeleted);
        }
        cashAccount ??= await FindAccountAsync(companyId, "111");
        if (cashAccount == null) return;

        // WHT basis decides whether THIS installment's WHT gets a GL line
        // (cash basis = yes, recognised at payment time) or was already
        // recognised at invoice approval (accrual = no, skip).
        var whtSettings = await _db.CompanySettings.AsNoTracking()
            .FirstOrDefaultAsync(s => s.CompanyId == companyId);
        var whtBasis = whtSettings?.WhtRecognitionBasis ?? Models.Enums.WhtRecognitionBasis.Cash;

        var pendingLines = new List<(Guid AccountId, decimal Debit, decimal Credit, string? Description)>();
        // FX: AR/AP ตัดที่ rate เอกสาร (มูลค่าที่ตั้งไว้ใน GL) ส่วนเงินสดเข้า-ออก
        // ที่ rate วันชำระจริง (payment.ExchangeRate ถ้ามี) — ผลต่าง = กำไร/
        // ขาดทุนจากอัตราแลกเปลี่ยนที่เกิดขึ้นจริง (realized) → 42600 / 54950
        var fx = doc.ExchangeRate;
        var settleFx = payment.ExchangeRate ?? fx;
        var thbAmount = fx == 1m ? payment.Amount : Math.Round(payment.Amount * fx, 2, MidpointRounding.AwayFromZero);
        var thbCash = settleFx == fx ? thbAmount
            : Math.Round(payment.Amount * settleFx, 2, MidpointRounding.AwayFromZero);
        var thbWht = fx == 1m ? payment.WithholdingTaxAmount
            : Math.Round(payment.WithholdingTaxAmount * fx, 2, MidpointRounding.AwayFromZero);
        var postPerPaymentWht = whtBasis == Models.Enums.WhtRecognitionBasis.Cash && thbWht > 0m;
        // ผลต่าง FX ของงวดนี้ (คิดเฉพาะส่วนเงินสด — WHT ตัดที่ rate เอกสารทั้งคู่)
        var fxDiff = thbCash - thbAmount;   // >0 = ได้ THB มากขึ้น

        if (isRevenue)
        {
            // Cash actually received this installment (rate วันรับเงินจริง).
            pendingLines.Add((cashAccount.Id, thbCash, 0, $"รับชำระ - {doc.DocumentNumber} ({payment.PaymentNumber})"));
            // Cash basis: book the WHT-Asset slice now so the GL AR clears
            // at gross (cash + WHT).
            if (postPerPaymentWht)
            {
                var whtAccount = await FindAccountAsync(companyId, "11910");
                if (whtAccount != null)
                    pendingLines.Add((whtAccount.Id, thbWht, 0, $"WHT (ถูกหัก) งวด {payment.PaymentNumber}"));
            }
            // ค่าธรรมเนียม marketplace/gateway ที่ถูกหักจากยอดโอน — Dr ค่าธรรมเนียม
            var thbFee = 0m;
            if (payment.FeeAmount > 0)
            {
                thbFee = fx == 1m ? payment.FeeAmount
                    : Math.Round(payment.FeeAmount * fx, 2, MidpointRounding.AwayFromZero);
                var feeAcc = payment.FeeAccountId.HasValue
                    ? await _db.ChartOfAccounts.FirstOrDefaultAsync(a =>
                        a.Id == payment.FeeAccountId.Value && a.CompanyId == companyId && !a.IsDeleted)
                    : null;
                feeAcc ??= await FindAccountAsync(companyId, "53200")
                    ?? await _db.ChartOfAccounts.FirstOrDefaultAsync(a => a.CompanyId == companyId
                        && a.IsActive && !a.IsDeleted && a.AccountType == AccountType.Expense
                        && a.AccountName.Contains("ค่าธรรมเนียม"));
                if (feeAcc == null)
                    throw new InvalidOperationException(
                        "ไม่พบผังบัญชีค่าธรรมเนียม (53xxx) — กรุณาเพิ่มก่อนบันทึกรับเงินแบบหักค่าธรรมเนียม");
                pendingLines.Add((feeAcc.Id, thbFee, 0m, $"ค่าธรรมเนียม (หักจากยอดโอน) - {payment.PaymentNumber}"));
            }
            var arAccount = await FindAccountAsync(companyId, "113", doc.Contact);
            if (arAccount != null)
            {
                var arClear = (postPerPaymentWht ? thbAmount + thbWht : thbAmount) + thbFee;
                pendingLines.Add((arAccount.Id, 0, arClear, $"ตัดลูกหนี้ - {doc.DocumentNumber}"));
            }
            // Realized FX: รับเงินได้ THB มากกว่าที่ AR ตั้งไว้ = กำไร (Cr),
            // น้อยกว่า = ขาดทุน (Dr)
            if (fxDiff != 0m)
            {
                var fxAcc = await ResolveFxGainLossAccountAsync(companyId, isGain: fxDiff > 0);
                if (fxAcc == null)
                    throw new InvalidOperationException(
                        "ไม่พบบัญชีกำไร/ขาดทุนจากอัตราแลกเปลี่ยน (42600/54950) — กรุณาเพิ่มในผังก่อนบันทึกชำระต่างสกุลด้วย rate วันชำระ");
                pendingLines.Add(fxDiff > 0
                    ? (fxAcc.Id, 0m, fxDiff, $"กำไรจากอัตราแลกเปลี่ยน (realized) - {payment.PaymentNumber}")
                    : (fxAcc.Id, -fxDiff, 0m, $"ขาดทุนจากอัตราแลกเปลี่ยน (realized) - {payment.PaymentNumber}"));
            }
        }
        else
        {
            // Clear the payable on the SAME account the source doc credited —
            // Expense → เจ้าหนี้อื่น (21220), PI → เจ้าหนี้การค้า (21210).
            var apAccount = await ResolvePayableAccountAsync(companyId, doc.DocumentType, doc.Contact);
            if (apAccount != null)
            {
                // + หนี้ที่ปิดด้วยบรรทัดปรับ (รอบ 193 · เอกสารสกุลบาทเท่านั้น — ตรวจที่ CreatePaymentAsync)
                var apClear = (postPerPaymentWht ? thbAmount + thbWht : thbAmount) + payment.SettlementAdjustmentAmount;
                pendingLines.Add((apAccount.Id, apClear, 0, $"ตัดเจ้าหนี้ - {doc.DocumentNumber}"));
            }
            pendingLines.Add((cashAccount.Id, 0, thbCash, $"จ่ายชำระ - {doc.DocumentNumber} ({payment.PaymentNumber})"));
            // รอบ 193: บรรทัดปรับส่วนต่าง — บวก = Dr (ค่าส่งที่จ่ายเพิ่ม 51120) · ลบ = Cr (คูปอง/ส่วนลดลดต้นทุน 51150)
            foreach (var adj in settlementAdjustments ?? Array.Empty<(Guid AccountId, decimal Amount, string? Reason)>())
            {
                var (adjDr, adjCr) = Accounting.Helpers.PaymentSettlementAdjustment.JournalSide(adj.Amount);
                pendingLines.Add((adj.AccountId, adjDr, adjCr,
                    $"ปรับส่วนต่างยอดชำระ{(string.IsNullOrWhiteSpace(adj.Reason) ? "" : ": " + adj.Reason)} - {doc.DocumentNumber} ({payment.PaymentNumber})"));
            }
            // Cash basis: Cr WHT-Payable for this installment's withholding.
            if (postPerPaymentWht)
            {
                var whtAccount = await ResolveWhtPayableAccountAsync(companyId, doc.Contact, doc.IsForeignService);
                if (whtAccount != null)
                    pendingLines.Add((whtAccount.Id, 0, thbWht, $"WHT (ค้างจ่าย) งวด {payment.PaymentNumber}"));
            }
            // Realized FX ฝั่งจ่าย: จ่าย THB มากกว่าที่ AP ตั้งไว้ = ขาดทุน (Dr),
            // น้อยกว่า = กำไร (Cr)
            if (fxDiff != 0m)
            {
                var fxAcc = await ResolveFxGainLossAccountAsync(companyId, isGain: fxDiff < 0);
                if (fxAcc == null)
                    throw new InvalidOperationException(
                        "ไม่พบบัญชีกำไร/ขาดทุนจากอัตราแลกเปลี่ยน (42600/54950) — กรุณาเพิ่มในผังก่อนบันทึกชำระต่างสกุลด้วย rate วันชำระ");
                pendingLines.Add(fxDiff > 0
                    ? (fxAcc.Id, fxDiff, 0m, $"ขาดทุนจากอัตราแลกเปลี่ยน (realized) - {payment.PaymentNumber}")
                    : (fxAcc.Id, 0m, -fxDiff, $"กำไรจากอัตราแลกเปลี่ยน (realized) - {payment.PaymentNumber}"));
            }
        }

        if (pendingLines.Count < 2) return;

        var totalDebit = pendingLines.Sum(l => l.Debit);
        var totalCredit = pendingLines.Sum(l => l.Credit);
        if (Math.Round(totalDebit, 2, MidpointRounding.AwayFromZero) != Math.Round(totalCredit, 2, MidpointRounding.AwayFromZero))
            throw new InvalidOperationException(
                $"การบันทึกบัญชีชำระเงินไม่สมดุล: เดบิต {totalDebit:N2} ≠ เครดิต {totalCredit:N2}");

        var period = await _db.FiscalPeriods.FirstOrDefaultAsync(f =>
            f.CompanyId == companyId &&
            f.StartDate <= payment.PaymentDate &&
            f.EndDate >= payment.PaymentDate);
        if (period != null && period.Status != FiscalPeriodStatus.Open)
            throw new InvalidOperationException(
                $"ไม่สามารถบันทึกการชำระเงินในงวด {period.Name} ได้ เนื่องจากงวดถูกปิดแล้ว");

        var prefix = isRevenue ? "RV" : "PV";
        var entryNumber = await GetNextJournalEntryNumberAsync(companyId, prefix);

        var entry = new JournalEntry
        {
            CompanyId = companyId,
            EntryNumber = entryNumber,
            EntryDate = payment.PaymentDate,
            JournalType = journalType,
            Description = $"ชำระเงิน {payment.PaymentNumber} - {doc.DocumentNumber}",
            Reference = payment.PaymentNumber,
            Status = JournalEntryStatus.Posted,
            TotalDebit = totalDebit,
            TotalCredit = totalCredit,
            CreatedBy = createdBy,
            IsAutoGenerated = true,
            SourceDocumentId = doc.Id,
            FiscalPeriodId = period?.Id,
            // Inherit project tag — payment-level override wins so an
            // installment booked to a different project than the parent
            // invoice (advance on Project A → final on Project B) lands
            // in the right P&L. Falls back to doc.ProjectId when no
            // override.
            ProjectId = payment.ProjectId ?? doc.ProjectId,
            DimensionId = doc.DimensionId
        };

        _db.JournalEntries.Add(entry);

        var order = 1;
        foreach (var line in pendingLines)
        {
            _db.JournalEntryLines.Add(new JournalEntryLine
            {
                JournalEntryId = entry.Id,
                AccountId = line.AccountId,
                DebitAmount = line.Debit,
                CreditAmount = line.Credit,
                Description = line.Description,
                LineOrder = order++,
                ProjectId = payment.ProjectId ?? doc.ProjectId
            });
        }
    }

    /// <summary>รูปแบบการออกใบกำกับ/ใบเสร็จของบริษัท (คิวรีเดียว) — ไม่มีแถว
    /// CompanySettings = <c>Combined</c> ซึ่งเป็นพฤติกรรมเดิมทุกประการ</summary>
    private async Task<ReceiptIssueMode> GetReceiptIssueModeAsync(Guid companyId) =>
        await _db.CompanySettings.AsNoTracking()
            .Where(s => s.CompanyId == companyId)
            .Select(s => (ReceiptIssueMode?)s.ReceiptIssueMode)
            .FirstOrDefaultAsync() ?? ReceiptIssueMode.Combined;

    /// <summary>วันที่ "รับเงินจริง" ของแต่ละเอกสาร = วันที่ของรายการรับชำระ
    /// <b>ล่าสุดที่ยังไม่ถูกยกเลิก</b> (รวมเงินก้อนเดียวที่จัดสรรหลายใบผ่าน
    /// <c>PaymentAllocation</c>) — batch เดียวต่อหน้า ไม่ใช่ N+1
    ///
    /// <para>ไม่มีคีย์ในดิกชันนารี = <b>ไม่รู้ว่ารับเงินวันไหน</b> (ยอดถูกปิดด้วย
    /// การหักใบมัดจำ / ข้อมูลก่อนย้ายระบบ) ซึ่ง
    /// <c>ReceiptIssuePolicy.SettledSameDay</c> ตีเป็น "ไม่ยกหัวเป็นใบเสร็จ" —
    /// "ไม่รู้ = บอกว่าไม่รู้" และการพิมพ์ใบเสร็จเกินอันตรายกว่าการไม่พิมพ์</para></summary>
    internal static async Task<Dictionary<Guid, DateTime>> LoadSettlementDatesAsync(
        AccountingDbContext db, Guid companyId, IReadOnlyCollection<Guid> documentIds)
    {
        if (documentIds.Count == 0) return new Dictionary<Guid, DateTime>();
        var ids = documentIds.Distinct().ToList();
        var direct = await db.Payments.AsNoTracking()
            .Where(p => p.CompanyId == companyId && !p.IsDeleted && ids.Contains(p.DocumentId))
            .Select(p => new { DocId = p.DocumentId, p.PaymentDate })
            .ToListAsync();
        var allocated = await db.PaymentAllocations.AsNoTracking()
            .Where(a => a.CompanyId == companyId && !a.IsDeleted && ids.Contains(a.DocumentId)
                && !a.Payment.IsDeleted)
            .Select(a => new { DocId = a.DocumentId, a.Payment.PaymentDate })
            .ToListAsync();
        return direct.Concat(allocated)
            .GroupBy(r => r.DocId)
            .ToDictionary(g => g.Key, g => g.Max(r => r.PaymentDate));
    }

    /// <summary>เอกสารใดใน <paramref name="documentIds"/> มี <b>ใบเสร็จแยก</b>
    /// (REC/ใบสำคัญรับ) อ้างถึงอยู่ — batch เดียว ไม่ใช่ N+1
    ///
    /// <para>เงื่อนไขชุดนี้เดิมถูกคัดลอกไว้ 3 ที่ (หน้ารายการ · หน้ารายละเอียด ·
    /// เส้นออกใบเสร็จย้อนหลัง) ซึ่งเป็น defect class "สำเนามือ = drift แน่นอน" —
    /// drift ตรงนี้แปลว่า<b>หน้าจอบอกว่ายังไม่มีใบเสร็จ แต่กระดาษพิมพ์หัวว่ามีแล้ว</b>
    /// (หรือกลับกัน) จึงยุบมาไว้ที่เดียว</para>
    ///
    /// <para>นับใบ <c>Draft</c> เป็น "ยังไม่มี" เพราะใบร่างยังไม่ใช่เอกสารตามกฎหมาย
    /// (เลข <c>DRAFT-</c>) — กติกาเดียวกับตอนตัดสินหัวกระดาษ</para></summary>
    internal static async Task<HashSet<Guid>> LoadDocIdsWithSeparateReceiptAsync(
        AccountingDbContext db, Guid companyId, IReadOnlyCollection<Guid> documentIds)
    {
        if (documentIds.Count == 0) return new HashSet<Guid>();
        var ids = documentIds.Distinct().ToList();
        return (await db.Documents.AsNoTracking()
            .Where(r => r.CompanyId == companyId && !r.IsDeleted
                && r.RelatedDocumentId != null && ids.Contains(r.RelatedDocumentId.Value)
                && (r.DocumentType == DocumentType.Receipt || r.DocumentType == DocumentType.ReceiptVoucher)
                && r.Status != DocumentStatus.Voided && r.Status != DocumentStatus.Draft
                && r.Status != DocumentStatus.Rejected)
            .Select(r => r.RelatedDocumentId!.Value)
            .Distinct()
            .ToListAsync())
            .ToHashSet();
    }

    /// <summary>ใบกำกับ "ทำหน้าที่ใบเสร็จในตัว" ไหม — mirror ของกติกาใน
    /// <c>PdfGenerationService.ResolveServedAsReceiptAsync</c> (เจ้าของกฎตอน
    /// render): TaxInvoice + ยอดคงเหลือ ≈ 0 + เคยรับเงินจริง + ลงบัญชีแล้ว +
    /// ไม่มีใบเสร็จแยกอ้างถึง + <b>รับเงินวันเดียวกับวันที่บนใบ</b>. แก้ที่ใดที่หนึ่ง
    /// ต้องแก้อีกที่เสมอ ไม่งั้นป้ายบนหน้าจอจะไม่ตรงกับหัวที่พิมพ์ออกมา
    /// (defect class "สอง renderer ห้าม drift")
    ///
    /// <para><paramref name="settledOn"/> = วันที่รับเงินจริง (จาก
    /// <see cref="LoadSettlementDatesAsync"/>) — <c>null</c> = ไม่รู้ ⇒ ไม่ยกหัว</para></summary>
    internal static bool ComputeServedAsReceipt(Document d, bool hasSeparateReceipt,
        ReceiptIssueMode mode, DateTime? settledOn)
    {
        if (d.DocumentType != DocumentType.TaxInvoice) return false;
        // นโยบายบริษัท "แยกใบกำกับ–ใบเสร็จเสมอ" → ใบกำกับไม่ยกหัวเป็นใบเสร็จ
        // (กติกาเดียวกับฝั่ง render — Helpers/ReceiptIssuePolicy)
        if (!Accounting.Helpers.ReceiptIssuePolicy.AllowsCombinedReceiptHeader(mode)) return false;
        // ใบร่างที่เลือกโหมด "รับเงินครบแล้ว" → แสดง/พิมพ์หัวรวมตามเจตนา (เลข
        // DRAFT ไม่ใช่เอกสารตามกฎหมาย — หลัก "Draft PDF = Approved PDF").
        // หลังอนุมัติ ตัดสินจากการชำระจริงเท่านั้น (อนุมัติแล้วแต่ยังไม่บันทึก
        // ชำระ = ห้ามพิมพ์ "ใบเสร็จรับเงิน" — จะกลายเป็นหลักฐานรับเงินเท็จ)
        if (d.Status == DocumentStatus.Draft) return d.PaidOnIssue && !hasSeparateReceipt;
        if (d.BalanceDue > 0.01m || d.PaidAmount <= 0.005m) return false;
        if (d.Status is DocumentStatus.Voided
            or DocumentStatus.Rejected or DocumentStatus.WaitingApproval) return false;
        // ⬅ รับเงิน "คนละวันกับวันที่บนใบ" → ใบนี้ยกหัวเป็นใบเสร็จไม่ได้ ใบเสร็จ
        // ตัวจริงคือ REC ที่ลงวันที่รับเงิน (ม.105 — ดู ReceiptIssuePolicy)
        if (!Accounting.Helpers.ReceiptIssuePolicy.SettledSameDay(d.DocumentDate, settledOn)) return false;
        return !hasSeparateReceipt;
    }

    private static DocumentResponse MapDocumentToResponse(Document d, (Guid EtaxId, EtaxStatus Status)? etax = null,
        DocumentBrief? upstream = null, List<DocumentBrief>? downstream = null,
        decimal? conversionPercent = null, string? conversionStatus = null,
        bool hasPce = false, int pceCount = 0, decimal pceAmount = 0,
        List<ProjectCostBrief>? bookedProjects = null,
        Dictionary<Guid, Guid>? pceByLine = null,
        bool servedAsReceipt = false)
    {
        var (lifecycle, reason) = ComputeLifecycle(d, conversionPercent, downstream);
        // เหตุผลจริงที่ภาษีซื้อยังค้าง 11640 — คำนวณจาก checker + guard เดียวกับ
        // ReclassifyUndueInputVatAsync เพื่อให้ UI บอกผู้ใช้ตรง ๆ ว่าขาดอะไร
        // (ก่อนหน้านี้ UI เดาว่า "เลขภาษีผู้ขายไม่ถูก" เสมอ → ผู้ใช้งง)
        List<string>? undueBlockers = null;
        // แสดงเหตุผลที่ยังเคลมไม่ได้ 2 กรณี:
        //   (ก) พักอยู่ 11640 (undue) ยังไม่เคลม — เคสเดิม
        //   (ข) เอกสารซื้อที่มี VAT แต่ยัง "ไม่ได้เข้า ภ.พ.30 จริง" (BecameClaimableAt
        //       ยังว่าง) และ §86/4 ไม่ครบ — เดิมกรณีนี้ list ว่าง ทำให้ UI ขึ้น
        //       ข้อความ generic "ใบกำกับยังไม่ครบ" โดยไม่บอก field ที่ขาด (เคสผู้ใช้
        //       รายงาน: PV VAT ลง 11610 ตรง ๆ ตอนอนุมัติ ไม่ใช่ 11640)
        var isPurchaseVatDoc = (d.DocumentType is DocumentType.PurchaseInvoice
                or DocumentType.Expense or DocumentType.PaymentVoucher)
            && d.VatAmount > 0;
        var undueUnclaimed = d.InputVatPostedAsUndue && d.InputVatBecameClaimableAt == null;
        if (undueUnclaimed || (isPurchaseVatDoc && d.InputVatBecameClaimableAt == null))
        {
            undueBlockers = new List<string>();
            if (d.InputVatExpiredAt.HasValue)
                undueBlockers.Add($"พ้นกรอบ 6 เดือน §82/3 — ระบบล้างภาษีซื้อเป็นค่าใช้จ่ายแล้วเมื่อ "
                    + $"{d.InputVatExpiredAt:dd/MM/yyyy} (เคลม ภ.พ.30 ไม่ได้อีก)");
            else if (d.IsForeignService)
                undueBlockers.Add("บริการต่างประเทศ (§83/6) — เคลมผ่านหน้านำส่งภาษี ภ.พ.36 (ไม่ใช่การเติมใบกำกับ)");
            else
            {
                var cwBase = d.SupplierTaxInvoiceDate ?? d.DocumentDate;
                var cwEnd = new DateTime(cwBase.Year, cwBase.Month, 1).AddMonths(7).AddDays(-1);
                if (DateTime.UtcNow.AddHours(7).Date > cwEnd)
                    undueBlockers.Add($"ใบกำกับเกินกรอบ 6 เดือน §82/3 (หมดสิทธิ์ {cwEnd:dd/MM/yyyy}) — "
                        + "เคลม ภ.พ.30 ไม่ได้แล้ว รอระบบล้างเป็นค่าใช้จ่าย");
                var cti = TaxInvoiceCompletenessChecker.Evaluate(d, d.Contact);
                foreach (var f in cti.MissingFields) undueBlockers.Add("ขาด: " + f);
                if (!string.IsNullOrWhiteSpace(d.InputVatAccountCodeOverride)
                    && !d.InputVatAccountCodeOverride.StartsWith("116"))
                    undueBlockers.Add($"ตั้งผังภาษีซื้อ override ไว้ ({d.InputVatAccountCodeOverride}) = ตั้งใจไม่เคลม VAT — ต้องล้าง override ก่อนจึงย้ายเข้า 11610 ได้");
                var claimableVat = d.Lines.Where(l => l.IsVatClaimable).Sum(l => l.VatAmount);
                if (claimableVat <= 0)
                    undueBlockers.Add("ไม่มีบรรทัดที่เคลมภาษีซื้อได้ (ทุกบรรทัดถูกปิด \"เคลม VAT\" หรือยอด VAT = 0) — ไม่มียอดให้ย้ายเข้า 11610");
            }
            // §86/4 ครบ + ไม่มี blocker อื่น = ไม่ต้องแสดงอะไร (คืน null ให้ UI เงียบ)
            if (undueBlockers.Count == 0) undueBlockers = null;
        }
        // ===== แก้ไขแบบออก Rev ใหม่ได้ไหม =====
        // ตัดสินที่ server ด้วยกติกาเดียวกับ UpdateDocumentAsync เส้นทาง revision
        // (ชนิด → สถานะ → มีเอกสารปลายทางแล้วหรือยัง) เพื่อไม่ให้ UI ต้อง hard-code
        // รายชื่อชนิดเอง — เดิม UI เช็ค "เฉพาะ Quotation" จึงตกหล่น PO/PR/BN/DN.
        // หมายเหตุ: downstream มีเฉพาะ detail view — ใน list view (null) จะยัง
        // canRevise=true ได้แม้ถูกแปลงแล้ว ปุ่มจึงเป็นแค่ "คำใบ้" ส่วนการปฏิเสธจริง
        // อยู่ที่ UpdateDocumentAsync ซึ่งบอกเลขเอกสารปลายทางตรง ๆ
        var canRevise = false;
        string? cannotReviseReason = null;
        if (RevisableTypes.Contains(d.DocumentType))
        {
            var convertedTo = downstream?.FirstOrDefault(x => x.Status != DocumentStatus.Voided);
            if (d.Status == DocumentStatus.Draft)
                cannotReviseReason = null;   // Draft แก้ตรง ๆ ไม่ต้องออก Rev (ปุ่ม "แก้ไข" ปกติ)
            else if (d.Status is not (DocumentStatus.Approved or DocumentStatus.Sent))
                cannotReviseReason = $"{DocTypeLabel(d.DocumentType)}สถานะนี้แก้ไขไม่ได้ "
                    + "(แก้ได้เฉพาะ Draft/Approved/Sent)";
            else if (convertedTo != null)
                cannotReviseReason = $"ถูกใช้ออกเอกสาร {convertedTo.DocumentNumber} แล้ว — "
                    + "แก้ไขย้อนหลังไม่ได้ ให้ยกเลิกเอกสารปลายทางก่อน";
            else
                canRevise = true;
        }
        return new(
        d.Id, d.DocumentNumber, d.DocumentType, d.Status,
        d.DocumentDate, d.DueDate,
        new ContactBrief(d.Contact.Id, d.Contact.Name, d.Contact.TaxId, d.Contact.BranchCode),
        d.SubTotal, d.DiscountAmount, d.BillDiscountPercent, d.BillDiscountAmount,
        d.VatAmount, d.WithholdingTaxAmount,
        d.TotalAmount, d.PaidAmount, d.BalanceDue, d.Reference, d.Notes,
        d.Lines.OrderBy(l => l.LineOrder).Select(l => new DocumentLineResponse(
            l.Id, l.LineOrder, l.Description, l.Quantity, l.Unit,
            l.UnitPrice, l.DiscountPercent, l.DiscountAmount, l.Amount,
            l.VatRate, l.VatAmount, l.WithholdingTaxRate, l.WithholdingTaxAmount,
            AccountId: l.AccountId,
            ProjectId: l.ProjectId,
            ProductCode: l.ProductCode,
            SourceLineId: l.SourceLineId,
            ProjectCode: l.Project != null ? l.Project.Code : null,
            ProjectName: l.Project != null ? l.Project.Name : null,
            ProjectCostEntryId: pceByLine != null && pceByLine.TryGetValue(l.Id, out var pceId) ? pceId : (Guid?)null,
            HasProjectCostEntry: pceByLine != null && pceByLine.ContainsKey(l.Id),
            IsVatClaimable: l.IsVatClaimable,
            VatNonClaimableReason: l.VatNonClaimableReason,
            IsLandedCost: l.IsLandedCost,
            AccountCode: l.Account != null ? l.Account.AccountCode : null,
            GlAccountAiFeedbackId: l.GlAccountAiFeedbackId,
            AccountName: l.Account != null ? l.Account.AccountName : null)).ToList(),
        d.CreatedAt,
        EtaxInvoiceId: etax?.EtaxId,
        EtaxStatus: etax?.Status,
        ProjectId: d.ProjectId,
        DimensionId: d.DimensionId,
        ProjectCode: d.Project?.Code,
        ProjectName: d.Project?.Name,
        BankAccountId: d.BankAccountId,
        BankAccountName: d.BankAccount?.AccountName,
        PaymentAccountId: d.PaymentAccountId,
        PaymentAccountName: d.PaymentAccount != null ? $"{d.PaymentAccount.AccountCode} - {d.PaymentAccount.AccountName}" : null,
        ExpenseCategoryId: d.ExpenseCategoryId,
        ExpenseCategoryName: d.ExpenseCategory?.AccountName,
        CustomAppendix: d.CustomAppendix,
        CustomFooterNotes: d.CustomFooterNotes,
        CustomTermsAndConditions: d.CustomTermsAndConditions,
        RevenueContractId: d.RevenueContractId,
        PerformanceObligationId: d.PerformanceObligationId,
        RelatedDocumentId: d.RelatedDocumentId,
        CertificateReason: d.CertificateReason,
        CertifierName: d.CertifierName,
        CertifierPosition: d.CertifierPosition,
        WitnessName: d.WitnessName,
        WitnessPosition: d.WitnessPosition,
        PaymentDate: d.PaymentDate,
        // ERP upgrade fields — OCR compliance + aging
        OcrConfidenceScore: d.OcrConfidenceScore,
        RdComplianceStatus: d.RdComplianceStatus,
        RdComplianceIssuesJson: d.RdComplianceIssuesJson,
        OcrTenantMismatchFlag: d.OcrTenantMismatchFlag,
        AgingDays: d.AgingDays,
        StaleDays: ComputeStaleDays(d),
        Currency: d.Currency,
        ExchangeRate: d.ExchangeRate,
        Sensitivity: d.Sensitivity,
        CreditNoteReason: d.CreditNoteReason,
        DebitNoteReason: d.DebitNoteReason,
        SupplierInvoiceNumber: d.SupplierInvoiceNumber,
        SupplierTaxInvoiceDate: d.SupplierTaxInvoiceDate,
        HasTaxInvoiceReference: d.HasTaxInvoiceReference,
        SupplierBranchCode: d.SupplierBranchCode,
        CreditDays: d.CreditDays,
        PaymentTerms: d.PaymentTerms,
        PaymentType: d.PaymentType,
        PricesIncludeVat: d.PricesIncludeVat,
        BrandId: d.BrandId,
        BrandName: d.Brand?.Name,
        BranchId: d.BranchId,
        BranchName: d.Branch?.Name,
        IssuerBranchCode: d.IssuerBranchCode,
        DocumentTemplateId: d.DocumentTemplateId,
        IsForeignService: d.IsForeignService,
        RelatedDocument: upstream,
        CnDnPurchaseSideOverride: d.CnDnPurchaseSideOverride,
        ConvertedToDocuments: downstream,
        ConversionCompletionPercent: conversionPercent,
        ConversionStatus: conversionStatus,
        HasProjectCostEntries: hasPce,
        ProjectCostEntryCount: pceCount,
        ProjectCostBookedAmount: pceAmount,
        BookedProjects: bookedProjects,
        LifecycleStatus: lifecycle,
        LifecycleReason: reason,
        InputVatPostedAsUndue: d.InputVatPostedAsUndue,
        InputVatBecameClaimableAt: d.InputVatBecameClaimableAt,
        InputVatAccountCodeOverride: d.InputVatAccountCodeOverride,
        InputVatExpiredAt: d.InputVatExpiredAt,
        IsDeposit: d.IsDeposit,
        DepositRealizedAmount: d.DepositRealizedAmount,
        DepositRealizedAt: d.DepositRealizedAt,
        DepositDeferredAccountCode: d.DepositDeferredAccountCode,
        DepositOutputVatDeferred: d.DepositOutputVatDeferred,
        DepositOutputVatRecognizedAt: d.DepositOutputVatRecognizedAt,
        TaxPointDate: d.TaxPointDate,
        RetentionUntil: d.RetentionUntil,
        NonDeductibleAmount: d.NonDeductibleAmount,
        NonDeductibleRuleJson: d.NonDeductibleRuleJson,
        LateReason: d.LateReason,
        DeliveryDate: d.DeliveryDate,
        OwnershipTransferDate: d.OwnershipTransferDate,
        ServiceUsedDate: d.ServiceUsedDate,
        DepositRefundedAmount: d.DepositRefundedAmount,
        DepositRefundedAt: d.DepositRefundedAt,
        DepositRefundReason: d.DepositRefundReason,
        DepositAppliedToDocumentId: d.DepositAppliedToDocumentId,
        BookingNumber: d.BookingNumber,
        CombinedInvoiceTaxInvoice: d.CombinedInvoiceTaxInvoice,
        IssuedAsCashReceipt: d.IssuedAsCashReceipt,
        PaidOnIssue: d.PaidOnIssue,
        DepositAppliedAmount: d.DepositAppliedAmount,
        IsSettlementReceipt: d.IsSettlementReceipt,
        UndueInputVatBlockers: undueBlockers,
        RevisionNumber: d.RevisionNumber,
        CanRevise: canRevise,
        CannotReviseReason: cannotReviseReason,
        QuotationAcceptedAt: d.QuotationAcceptedAt,
        QuotationAcceptedBy: d.QuotationAcceptedBy,
        DeliverySignedAt: d.DeliverySignedAt,
        DeliverySignedBy: d.DeliverySignedBy,
        DocumentLanguage: d.DocumentLanguage,
        ServedAsReceipt: servedAsReceipt,
        // ── ช่องที่รับตอน Create/Update แต่เดิมไม่เคย echo กลับ ──────────
        // (ดูหมายเหตุใน DocumentResponse — "เก็บแล้วต้อง echo กลับ")
        BuyerDeclinedTaxInvoice: d.BuyerDeclinedTaxInvoice,
        // ไม่มีคอลัมน์ของตัวเอง — งวดเคลมถูกเก็บเป็น InputVatBecameClaimableAt
        // (วันที่ 1 ของเดือน) เจ้าของกฎคือ InputVatClaimPeriodRules ⇒ คำนวณ
        // ที่เดียวตรงนี้แล้วส่งเป็น "yyyy-MM" ให้ฟอร์ม ห้ามให้หน้าเว็บประกอบเอง
        // (กฎเหล็ก #4 A "Resolver กลาง ห้ามคำนวณเอง")
        InputVatClaimPeriod: ResolveInputVatClaimPeriod(d),
        PreparerName: d.PreparerName,
        PreparerSignatureBase64: d.PreparerSignatureBase64,
        DepositAppliedRef: d.DepositAppliedRef,
        DepositAppliedDrivesJournal: d.DepositAppliedDrivesJournal,
        // หมายเหตุภายใน (ไม่พิมพ์ลงกระดาษ) — ที่เก็บ "คำเตือนที่กดรับทราบแล้ว"
        // ต้อง echo กลับ ไม่งั้นร่องรอยอยู่แต่ในฐานข้อมูลกับ audit ผู้ใช้ไม่เห็น
        InternalNotes: d.InternalNotes,
        OriginModule: d.OriginModule,
        EtaxAutoFailed: Accounting.Helpers.EtaxAutoFailedNote.Has(d.InternalNotes),
        ReplacedByDocumentId: d.ReplacedByDocumentId,
        ReplacesDocumentId: d.ReplacesDocumentId,
        ReplacementReason: d.ReplacementReason,
        ReplacedAt: d.ReplacedAt,
        // รอบ 193 — เก็บแล้วต้อง echo กลับ (กฎเหล็ก #4 A)
        ActualPaidAmount: d.ActualPaidAmount,
        RoundingAdjustment: d.RoundingAdjustment);
    }

    /// <summary>งวดที่ภาษีซื้อของใบนี้จะถูกเคลมจริง เป็นสตริง "yyyy-MM" (ค.ศ.)
    ///
    /// <para>ลำดับเดียวกับ GenerateVatReport: งวดที่ตรึงไว้ (InputVatBecameClaimableAt)
    /// ชนะ · ไม่ได้ตรึง = เดือนภาษีของเอกสาร (TaxPointDate ?? DocumentDate).
    /// เอกสารฝั่งขายไม่มีภาษีซื้อให้เคลม → null (ฟอร์มจะซ่อนช่อง)</para></summary>
    private static string? ResolveInputVatClaimPeriod(Document d)
    {
        if (!InputVatClaimPeriodRules.IsPurchaseDocType(d.DocumentType)) return null;
        var basis = d.InputVatBecameClaimableAt ?? d.TaxPointDate ?? d.DocumentDate;
        return basis == default ? null : $"{basis.Year:D4}-{basis.Month:D2}";
    }

    /// <summary>Build the redacted stub returned to API consumers who lack
    /// permission to see a sensitive record. Keeps the Id, DocumentNumber, and
    /// Sensitivity so the integration target knows the record exists and what
    /// kind of access it would need; blanks out amounts / contact / notes /
    /// lines. The destination system can decide whether to skip, place-hold,
    /// or request access.</summary>
    private static DocumentResponse RedactDocumentResponse(Document d, string reason) => new(
        d.Id, d.DocumentNumber, d.DocumentType, d.Status,
        d.DocumentDate, d.DueDate,
        new ContactBrief(Guid.Empty, "[ซ่อน]", null),
        0, 0, 0, 0, 0, 0, 0, 0, 0, null, null,
        new List<DocumentLineResponse>(), d.CreatedAt,
        Sensitivity: d.Sensitivity,
        IsRedacted: true,
        RedactedReason: reason);

    /// <summary>Days a document has been parked in a non-terminal status past
    /// the stale threshold — null when fresh or in a terminal status.
    /// Terminal = Paid / Voided / Rejected.</summary>
    private const int StaleThresholdDays = 60;
    /// <summary>Derive the unified lifecycle state from the doc's
    /// status + conversion % + balance + downstream settlement docs.
    /// Per-doc-type rules so a fully-converted PO surfaces "Done"
    /// even though Status is still "Approved", and a fully-paid PI
    /// surfaces "Done" even when ConversionStatus is null. Pure
    /// function — no DB access — so it can be reused server- and
    /// client-side.</summary>
    private static (string Status, string Reason) ComputeLifecycle(
        Document d, decimal? conversionPercent, List<DocumentBrief>? downstream)
    {
        // Voided / Rejected always win — purpose terminated. The status
        // badge already says "ยกเลิก" / "ถูกปฏิเสธ"; a separate lifecycle
        // pill saying the same thing was just visual noise — return empty
        // reason so the frontend hides the duplicate.
        if (d.Status == DocumentStatus.Voided)
            return ("Cancelled", "");
        if (d.Status == DocumentStatus.Rejected)
            return ("Cancelled", "");

        // Draft / WaitingApproval — the status badge ALREADY says "ร่าง" /
        // "รออนุมัติ". A second lifecycle pill repeating the same thing is
        // visual noise (the UI showed "ร่าง" + "⏳ ฉบับร่าง" stacked on
        // mobile). Return empty so the frontend hides the lifecycle pill;
        // it appears only when lifecycle adds NEW info beyond status.
        if (d.Status == DocumentStatus.Draft || d.Status == DocumentStatus.WaitingApproval)
            return ("Open", "");

        // Per-type rules.
        switch (d.DocumentType)
        {
            // Settlement-bearing receivable / payable.
            case DocumentType.Invoice:
            case DocumentType.TaxInvoice:
            case DocumentType.BillingNote:
            case DocumentType.PurchaseInvoice:
            case DocumentType.Expense:
            {
                if (d.BalanceDue <= 0.01m) return ("Done", "✓ ชำระครบแล้ว");
                if (d.Status == DocumentStatus.PartiallyPaid)
                    return ("PartiallyDone", $"◐ ชำระบางส่วน · เหลือ {d.BalanceDue:N2}");
                if (d.Status == DocumentStatus.Overdue)
                    return ("Open", $"⚠ เกินกำหนด · ค้าง {d.BalanceDue:N2}");
                return ("Open", $"⏳ รอจ่าย/รับชำระ · {d.BalanceDue:N2}");
            }

            // Conversion-bearing — purpose fulfilled when downstream consumes it.
            case DocumentType.Quotation:
            case DocumentType.PurchaseRequisition:
            case DocumentType.PurchaseOrder:
            case DocumentType.GoodsReceiptNote:
            case DocumentType.DeliveryNote:
            {
                var nextLabel = downstream?.FirstOrDefault()?.DocumentNumber;
                if (conversionPercent.HasValue && conversionPercent.Value >= 100m)
                    return ("Done", nextLabel != null ? $"✓ แปลงเป็น {nextLabel}" : "✓ ดำเนินการครบแล้ว");
                if (conversionPercent.HasValue && conversionPercent.Value > 0m)
                    return ("PartiallyDone", $"◐ แปลงไป {conversionPercent.Value:F0}%");
                return ("Open", "⏳ รอดำเนินการต่อ");
            }

            // One-shot terminal docs (PV/Receipt/RV/CIL/CN/DN). Once
            // approved/paid, the status badge ("ชำระแล้ว" / "อนุมัติ")
            // already conveys the whole story — a second pill repeating
            // "✓ บันทึกเรียบร้อย" was duplicate visual noise. Return empty
            // reason for those statuses; only mark "✓ บันทึกเรียบร้อย" for
            // the in-between Sent state where the status badge is generic.
            case DocumentType.Receipt:
            case DocumentType.ReceiptVoucher:
            case DocumentType.PaymentVoucher:
            case DocumentType.CertificateInLieu:
            case DocumentType.CreditNote:
            case DocumentType.DebitNote:
                return d.Status == DocumentStatus.Paid
                    || d.Status == DocumentStatus.Approved
                    ? ("Done", "")
                    : ("Done", "✓ บันทึกเรียบร้อย");

            default:
                // Unknown type — fall back to status.
                return d.Status == DocumentStatus.Paid
                    ? ("Done", "✓ ชำระแล้ว")
                    : ("Open", "⏳ ดำเนินการ");
        }
    }

    private static int? ComputeStaleDays(Document d)
    {
        if (d.Status is DocumentStatus.Paid or DocumentStatus.Voided or DocumentStatus.Rejected)
            return null;
        var days = (int)(DateTime.UtcNow.Date - d.DocumentDate.Date).TotalDays;
        return days > StaleThresholdDays ? days : null;
    }

