    // ==================== Smart Defaults ====================

    /// <summary>
    /// วิเคราะห์ประเภทผู้ติดต่อจาก TaxId และ BranchCode อัตโนมัติ
    /// - มี BranchCode (ไม่ใช่ 00000) → นิติบุคคล (มีสำนักงานสาขา)
    /// - TaxId 13 หลัก ขึ้นต้นด้วย 0 → นิติบุคคล (เลขทะเบียนนิติบุคคล)
    /// - อื่นๆ → บุคคลธรรมดา
    /// </summary>
    /// <summary>ด่านคำนำหน้าชื่อของคู่ค้า — ผ่าน <c>ThaiTitleHelper.TryCanonical</c>
    /// ตัวเดียวกับที่ไฟล์ยื่นใช้ แล้วคืน "รูปเต็มภาษาไทย" เสมอ (เช่น "น.ส." →
    /// "นางสาว") · <c>null</c>/ว่าง = ไม่ระบุ (นิติบุคคลปกติไม่มีคำนำหน้า)
    ///
    /// ทำไมต้อง throw ที่นี่: ช่องนี้ไหลตรงไปคอลัมน์ที่ 12 ของไฟล์ ภ.ง.ด.3 ที่
    /// อัปโหลดเข้าเว็บกรมสรรพากร และไฟล์ สปส.1-10 ที่ปฏิเสธทั้งแถวเมื่อคำนำหน้า
    /// ไม่อยู่ในชุดที่รับ ("รหัสคำนำหน้า Mrs. ไม่ถูกต้อง") — หน้าจอเป็น dropdown
    /// อยู่แล้ว ผู้ที่จะโดนด่านนี้คือ API/import ซึ่งอ่านข้อความ error ได้และ
    /// แก้ได้ทันที (ต่างจากเส้น OCR ที่ห้ามบล็อกผู้ใช้ — เส้นนั้นไม่เซ็ตช่องนี้)</summary>
    private static string? NormalizeContactTitle(string? input)
    {
        if (input == null) return null;
        if (Accounting.Helpers.ThaiTitleHelper.TryCanonical(input, out var canonical, out var reason))
            return canonical;
        throw new Accounting.Helpers.BusinessRuleException(reason!, "CONTACT-TITLE");
    }

    public static ContactType InferContactType(string? taxId, string? branchCode)
    {
        // BranchCode ≠ null/empty/"00000" → clearly juristic (has branch offices)
        if (!string.IsNullOrWhiteSpace(branchCode) && branchCode != "00000")
            return ContactType.JuristicPerson;

        // TaxId 13 digits starting with 0 → juristic person registration number
        if (!string.IsNullOrWhiteSpace(taxId) && taxId.Length == 13 && taxId[0] == '0')
            return ContactType.JuristicPerson;

        // BranchCode "00000" (สำนักงานใหญ่) with valid TaxId → also juristic
        if (branchCode == "00000" && !string.IsNullOrWhiteSpace(taxId) && taxId.Length == 13)
            return ContactType.JuristicPerson;

        return ContactType.Individual;
    }

    /// <summary>ค่าเริ่มต้นอัตโนมัติจากข้อมูลผู้ติดต่อ</summary>
    public static ContactSmartDefaults GetSmartDefaults(Contact contact)
    {
        var contactType = contact.ContactType;

        // WHT form type: นิติบุคคล → ภ.ง.ด.53, บุคคลธรรมดา → ภ.ง.ด.3
        var taxFormType = contactType switch
        {
            ContactType.JuristicPerson => TaxType.WithholdingTax53,
            ContactType.GovernmentAgency => TaxType.WithholdingTax53,
            _ => TaxType.WithholdingTax3
        };
        var taxFormLabel = taxFormType switch
        {
            TaxType.WithholdingTax53 => "ภ.ง.ด.53",
            TaxType.WithholdingTax3 => "ภ.ง.ด.3",
            _ => taxFormType.ToString()
        };

        // Document type: supplier → ซื้อ, customer → ขาย
        DocumentType? docType = null;
        string? docTypeLabel = null;
        if (contact.IsSupplier && !contact.IsCustomer)
        {
            docType = DocumentType.PurchaseInvoice;
            docTypeLabel = "ใบกำกับซื้อ";
        }
        else if (contact.IsCustomer && !contact.IsSupplier)
        {
            docType = DocumentType.Invoice;
            docTypeLabel = "ใบแจ้งหนี้";
        }

        // WHT rate & income type: นิติบุคคล default = ค่าบริการ 3%, บุคคลธรรมดา = ค่าจ้าง 3%
        var defaultWhtRate = 3m;
        var defaultIncomeCode = contactType == ContactType.JuristicPerson ? "8" : "6";
        var defaultIncomeLabel = contactType == ContactType.JuristicPerson
            ? "ค่าบริการอื่นๆ (40(8))"
            : "ค่าวิชาชีพอิสระ (40(6))";

        var contactTypeLabel = contactType switch
        {
            ContactType.Individual => "บุคคลธรรมดา",
            ContactType.JuristicPerson => "นิติบุคคล",
            ContactType.GovernmentAgency => "หน่วยงานราชการ",
            _ => contactType.ToString()
        };

        return new ContactSmartDefaults(
            contactType, contactTypeLabel,
            taxFormType, taxFormLabel,
            docType, docTypeLabel,
            defaultWhtRate, defaultIncomeCode, defaultIncomeLabel);
    }

    // Projection type for the recursive cycle-detection CTE
    private sealed record AncestorRow(Guid Id, string DocumentNumber, int DocumentType);

    /// <summary>ใบแจ้งหนี้ใบนี้มีบรรทัด "สินค้า" (Product.TrackStock) ไหม —
    /// ตัวตัดสินตัวเดียวที่ทั้ง AutoPost (เลือก 21911 vs 21913 พัก) และ warning
    /// §86 ตอนอนุมัติใช้ร่วมกัน: มีสินค้า = tax point เกิดตอนส่งมอบ (§78)
    /// ⇒ VAT เข้า ภ.พ.30 ทันทีและผู้ขายมีหน้าที่ออกใบกำกับ ณ ตอนนั้น</summary>
    private async Task<bool> InvoiceHasTrackedGoodsAsync(Guid companyId, Document doc)
    {
        var stockCodes = doc.Lines
            .Where(l => !string.IsNullOrWhiteSpace(l.ProductCode))
            .Select(l => l.ProductCode!)
            .Distinct()
            .ToList();
        return stockCodes.Count > 0 && await _db.Products.AsNoTracking()
            .AnyAsync(p => p.CompanyId == companyId && stockCodes.Contains(p.Code)
                && !p.IsDeleted && p.TrackStock);
    }

    /// <summary>Pre-approval soft-warning collector. Returns user-facing
    /// messages for legal-but-unusual patterns that the operator should
    /// eyeball before approving. The list is empty when nothing is amiss.
    /// HARD errors continue to throw inline above — they're never returned
    /// as warnings because they'd corrupt the books on save. Examples that
    /// pass the audit but get flagged:
    ///   • document-date drifted &gt;90d in the past or &gt;30d in the future
    ///   • VAT rate other than 0 / 7
    ///   • WHT rate not in the canonical ภ.ง.ด.3 / 53 list
    ///   • TaxInvoice / Receipt without contact TaxId (e-Tax falls to
    ///     Non-VAT format silently otherwise)
    ///   • large amount (&gt;500k THB) — could be a typo
    ///   • foreign currency without an explicit FX rate update
    ///   • inventory-tracked product would go negative on this approval
    /// </summary>
    /// <summary>
    /// **คำตัดสินของคนเรื่องหัก ณ ที่จ่าย → คลังเรียนรู้** (กฎเหล็ก #1 ขั้น CAPTURE)
    ///
    /// <para>เรียกตอนเอกสารถูกอนุมัติจริงเท่านั้น — ใบที่ผู้ใช้เปิดดูแล้วปิดไป
    /// ไม่ใช่การตัดสินใจ. บันทึกทั้งสองทิศ:</para>
    /// <list type="bullet">
    /// <item>อนุมัติโดย<b>ไม่หัก</b> ⇒ คำตอบจริงคือ <c>None</c> — ถ้าโมเดลเคยตอบ
    ///   <c>None</c> ไว้ก็คือ "ยืนยันว่าถูก" (สอนให้มั่นใจขึ้น) ถ้าเคยเตือนว่าเข้าข่าย
    ///   ก็คือ "คนแย้ง" (สอนไม่ให้เตือนซ้ำกับคู่ค้ารายนี้)</item>
    /// <item>อนุมัติโดย<b>หัก</b>และระบุประเภทเงินได้ ⇒ คำตอบจริงคือรหัสนั้น</item>
    /// </list>
    ///
    /// <para>งานกลางคืน <c>AiFeedbackTrainingJob</c> จะ mine แถวที่มี
    /// <c>UserChosenAt</c> ไปเทรนนักเรียนของ <c>WhtCategoryInference</c> ⇒ ครั้งหน้า
    /// นักเรียนตอบเองได้โดยไม่ต้องจ่าย token (กฎเหล็ก #1 ขั้น DISTILL)</para>
    /// </summary>
    private async Task RecordWhtDecisionFeedbackAsync(Document doc)
    {
        if (_feedbackRecorder == null || doc.WhtAdviceAiFeedbackId is not { } fid) return;
        try
        {
            string chosen;
            // "ตั้งใจแค่ไหน" ต่างกันสองทาง (ทีม T3 รอบ 177 §3.1):
            //  • กรอกยอดหัก + เลือกประเภทเงินได้เอง = ลงมือทำจริง ⇒ Explicit
            //  • ไม่กรอกอะไรเลยแล้วกดอนุมัติ ⇒ "None" เป็นค่าตั้งต้น ไม่ใช่การตัดสินใจ
            Accounting.Models.Enums.UserChoiceSource source;
            if (doc.WithholdingTaxAmount > 0.005m)
            {
                // หักจริง — คำตอบคือประเภทเงินได้ที่ใช้ · ไม่ระบุ = สอนอะไรไม่ได้ ข้ามไป
                var code = doc.Lines?
                    .FirstOrDefault(l => !l.IsDeleted && !string.IsNullOrWhiteSpace(l.IncomeTypeCode))?.IncomeTypeCode;
                if (string.IsNullOrWhiteSpace(code)) return;
                chosen = code!;
                source = Accounting.Models.Enums.UserChoiceSource.Explicit;
            }
            else
            {
                chosen = "None";
                source = Accounting.Models.Enums.UserChoiceSource.Implicit;
            }

            await _feedbackRecorder.RecordUserChoiceAsync(fid, chosen,
                acceptedAi: string.Equals(chosen, doc.WhtAdviceAnswer, StringComparison.OrdinalIgnoreCase),
                default, source);
        }
        catch (Exception ex)
        {
            // การเรียนรู้ล้มต้องไม่ทำให้การอนุมัติล้ม
            _logger.LogWarning(ex, "บันทึกคำตัดสินหัก ณ ที่จ่ายเข้าคลังเรียนรู้ไม่สำเร็จ (ไม่กระทบการอนุมัติ)");
        }
    }

    /// <summary>
    /// **กระดาษที่สแกนมามีส่วน "หัก ณ ที่จ่าย" เขียนไว้ไหม** — ชั้นที่ 0 ของด่าน WHT
    ///
    /// <para>คำตัดสินเจ้าของโปรเจกต์ 2026-09-18: <i>"ใบกำกับภาษีที่ถูกต้อง ถ้าไม่มีเขียน
    /// ส่วนหัก ณ ที่จ่ายไว้ ยังไงก็ไม่ต้องหัก"</i> — ผู้ขายที่อยู่ในข่ายถูกหักพิมพ์บรรทัด
    /// นั้นมาบนใบเองเป็นปกติของวงการ ส่วนผู้ขายสินค้าไม่เคยพิมพ์</para>
    ///
    /// <para>คืน <c>null</c> เมื่อ<b>ไม่มีกระดาษให้ดู</b> (คีย์มือ · สร้างจากใบอื่น ·
    /// สแกนอ่านข้อความไม่ออก) — "ไม่มีกระดาษ" ≠ "กระดาษบอกว่าไม่ต้องหัก"
    /// การเหมารวมสองอย่างนี้คือการแปลง "ไม่รู้" เป็น "ไม่ต้องหัก"</para>
    /// </summary>
    /// <summary>สิ่งที่กระดาษของเอกสารนี้บอกเรื่องหัก ณ ที่จ่าย + ใบนั้นสมบูรณ์แค่ไหน
    ///
    /// <para>คืนสองค่าพร้อมกันเพราะทั้งคู่มาจาก<b>แถวสแกนแถวเดียวกัน</b> — แยกคิวรีสองรอบ
    /// จะได้คำตอบจากคนละใบเมื่อเอกสารหนึ่งมีสแกนหลายรอบ</para></summary>
    private async Task<(bool? ShowsWht, Accounting.Helpers.PaperTaxInvoiceGrade Grade, string GradeReason)>
        ScanPaperWhtEvidenceAsync(Guid companyId, Guid documentId)
    {
        var unknown = (default(bool?), Accounting.Helpers.PaperTaxInvoiceGrade.Unknown, "ไม่มีกระดาษให้ดู");

        var scan = await _db.Set<OcrScanResult>().AsNoTracking()
            .Where(r => r.CompanyId == companyId && r.CreatedDocumentId == documentId)
            .OrderByDescending(r => r.CreatedAt)
            .Select(r => new
            {
                // ⚠️ ไม่ดึง `HasWht`/`WhtRate` โดยตั้งใจ — ดูเหตุผลที่บล็อก PaperWhtReader ล่าง
                r.RawTextContent,
                r.ExtractedVendorName, r.ExtractedVendorTaxId, r.VendorAddress,
                r.BuyerName, r.BuyerAddress,
                r.ExtractedDocumentNumber, r.ExtractedDate,
                r.ExtractedSubTotal, r.ExtractedVatAmount, r.ExtractedTotalAmount,
                r.ExtractedItemsJson,
            })
            .FirstOrDefaultAsync();
        if (scan == null) return unknown;                              // เอกสารนี้ไม่ได้มาจากสแกน
        if (string.IsNullOrWhiteSpace(scan.RawTextContent)) return unknown;  // อ่านกระดาษไม่ออก

        // ความสมบูรณ์ของใบ — ตัวตัดสินตัวเดียว ห้ามนับรายการเองที่นี่
        var grade = Accounting.Helpers.PaperTaxInvoiceCompleteness.Judge(
            new Accounting.Helpers.PaperTaxInvoiceFacts(
                RawText: scan.RawTextContent,
                SellerName: scan.ExtractedVendorName,
                SellerTaxId: scan.ExtractedVendorTaxId,
                SellerAddress: scan.VendorAddress,
                BuyerName: scan.BuyerName,
                BuyerAddress: scan.BuyerAddress,
                DocumentNumber: scan.ExtractedDocumentNumber,
                DocumentDate: scan.ExtractedDate,
                LineCount: CountScanLines(scan.ExtractedItemsJson),
                SubTotal: scan.ExtractedSubTotal,
                VatAmount: scan.ExtractedVatAmount,
                TotalAmount: scan.ExtractedTotalAmount));

        // ตัวอ่านตัวเดียวของระบบ — ห้ามเขียน regex ชุดที่สองที่นี่
        // ⚠️ **ห้ามกลับมาอ่าน `scan.HasWht`/`scan.WhtRate` ที่นี่** (D3-2 รอบ 183):
        // สองช่องนั้นเคยถูกเขียนโดย `VendorIntelligenceService` จาก**ประวัติผู้ขาย**
        // ไม่ใช่จากกระดาษ ⇒ ด่านนี้เคยสรุปว่า "กระดาษประกาศเชิงบวก" จากคำตอบของระบบเอง
        // แล้ว VendorIntel ก็เรียนกลับจากผลนั้นอีกที = วงจรสอนตัวเอง (DECISION_DOCTRINE §3)
        // ฝั่งเรียนรู้ใช้ตัวอ่านตัวเดียวกันนี้แล้วเช่นกัน (`VendorIntelligenceService`)
        var paper = Accounting.Helpers.PaperWhtReader.Read(scan.RawTextContent);
        if (paper.Amount is > 0m || paper.RatePercent is > 0m) return (true, grade.Grade, grade.Reason);
        return (false, grade.Grade, grade.Reason);   // อ่านกระดาษได้ และไม่มีส่วนหัก
    }

    /// <summary>จำนวนบรรทัดที่ OCR แกะได้จากกระดาษ — JSON เสีย/ว่าง = 0 (ไม่ throw:
    /// ด่านนี้ตอบว่า "ใบไม่สมบูรณ์" ได้ แต่ห้ามทำให้การอนุมัติล้ม)</summary>
    private static int CountScanLines(string? itemsJson)
    {
        if (string.IsNullOrWhiteSpace(itemsJson)) return 0;
        try
        {
            using var doc = System.Text.Json.JsonDocument.Parse(itemsJson);
            return doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array
                ? doc.RootElement.GetArrayLength() : 0;
        }
        catch (System.Text.Json.JsonException) { return 0; }
    }

    /// <summary>ข้อเท็จจริงรายบรรทัดสำหรับ <see cref="Accounting.Helpers.WhtApplicabilityEvidence"/>
    ///
    /// <para><c>DocumentLine</c> เก็บแต่ <c>ProductCode</c> (ไม่มี FK ไปสินค้า) จึงต้อง join
    /// เอง — บรรทัดที่ไม่ได้ผูกรหัสสินค้า (เช่นบรรทัดอิสระจาก OCR) จะได้ <c>null</c>
    /// ซึ่งแปลว่า "ไม่รู้ชนิด" **ไม่ใช่** "ไม่ใช่สินค้า"</para></summary>
    private async Task<List<Accounting.Helpers.WhtLineFact>> BuildWhtLineFactsAsync(
        Guid companyId, Document doc)
    {
        var liveLines = doc.Lines.Where(l => !l.IsDeleted).ToList();
        var codes = liveLines
            .Select(l => l.ProductCode)
            .Where(c => !string.IsNullOrWhiteSpace(c))
            .Select(c => c!)
            .Distinct()
            .ToList();

        var kindByCode = codes.Count == 0
            ? new Dictionary<string, Models.Enums.ProductType>(StringComparer.OrdinalIgnoreCase)
            : (await _db.Products.AsNoTracking()
                    .Where(p => p.CompanyId == companyId && !p.IsDeleted && codes.Contains(p.Code))
                    .Select(p => new { p.Code, p.ProductType })
                    .ToListAsync())
                .GroupBy(x => x.Code, StringComparer.OrdinalIgnoreCase)
                .ToDictionary(g => g.Key, g => g.First().ProductType, StringComparer.OrdinalIgnoreCase);

        return liveLines.Select(l => new Accounting.Helpers.WhtLineFact(
            l.Description,
            l.IncomeTypeCode,
            !string.IsNullOrWhiteSpace(l.ProductCode) && kindByCode.TryGetValue(l.ProductCode!, out var k)
                ? k : null,
            l.Amount)).ToList();
    }

    /// <summary>**ตัวเขียน "ระบบเลือกเงียบ" ตัวเดียว** — ทิ้งร่องรอยสองที่เสมอ
    ///
    /// <para>การเงียบคือ<b>สถานะปลายทางที่ระบบประทับเอง</b> (หลักการข้อ 3) ⇒ ต้องตามรอยได้
    /// ว่าเงียบเพราะอะไร มิฉะนั้นผู้สอบบัญชี/สรรพากรถามว่า "ทำไมใบนี้ไม่มีคำเตือน"
    /// แล้วไม่มีอะไรตอบได้ ทั้งที่ §54 ให้<b>ผู้จ่าย</b>รับผิดในภาษีที่ไม่ได้หัก</para>
    ///
    /// <list type="bullet">
    /// <item><c>InternalNotes</c> — ผู้ใช้เปิดเอกสารแล้วเห็น แต่<b>แก้ได้</b> จึงไม่ใช่หลักฐาน</item>
    /// <item><c>AuditLog</c> — append-only + hash chain + <c>RuleCode</c>/<c>LegalReference</c>
    /// (กฎเหล็ก #2 ข้อ M) = ของที่ยกไปอ้างได้จริง</item>
    /// </list>
    ///
    /// <para>ด่านคำเตือนรัน<b>ทุกครั้งที่กดอนุมัติ</b> (รอบแรก throw 422 · รอบสองหลังยืนยัน)
    /// ⇒ ต้องกันการทบซ้ำด้วย <c>WhtAdviceNote.ShouldAppend</c> เสมอ</para></summary>
    /// <param name="advice">คำตอบของชั้นเรียนรู้ ถ้ามี — <c>null</c> = เงียบโดยไม่ได้ถามใคร</param>
    private void RecordWhtSilence(Document doc, Guid companyId, decimal paidToContactThisYear,
        string ruleCode, string reason, WhtAdvice? advice)
    {
        var note = advice is { } a
            ? Accounting.Helpers.WhtAdviceNote.Compose(a.UsedAi, a.Answer, a.Confidence)
            : Accounting.Helpers.WhtAdviceNote.ComposeNoSuspicion(reason);
        if (!Accounting.Helpers.WhtAdviceNote.ShouldAppend(doc.InternalNotes, note)) return;

        AppendInternalNote(doc, note);
        _db.AuditLogs.Add(new AuditLog
        {
            CompanyId = companyId,
            Action = AuditAction.Update,
            EntityType = "Document",
            EntityId = doc.Id.ToString(),
            NewValues = System.Text.Json.JsonSerializer.Serialize(new
            {
                action = "WhtWarningSuppressed",
                documentNumber = doc.DocumentNumber,
                documentType = doc.DocumentType.ToString(),
                contactId = doc.ContactId,
                contactName = doc.Contact?.Name,
                subTotal = doc.SubTotal,
                paidToContactThisYear,
                reason,
                answer = advice?.Answer,
                confidence = advice?.Confidence,
                usedAi = advice?.UsedAi,
                feedbackId = advice?.FeedbackId,
                ruleCode,
                legalReference = Accounting.Helpers.WhtAdviceNote.SilentLegalReference,
            }),
        });
    }

    /// <summary>ความมั่นใจขั้นต่ำที่ยอมให้คำตอบ "ไม่ต้องหัก" **ปิดคำเตือน** —
    /// ตรงกับตัวอย่างใน CLAUDE.md กฎเหล็ก #1 ที่ใช้ 0.70 เป็นด่านก่อน apply
    /// (ทิศ "เตือน" ไม่ต้องผ่านด่านนี้ เพราะเตือนเกินยังแก้ได้ แต่เงียบผิดมองไม่เห็น)</summary>
    private const decimal MinWhtSilenceConfidence = 0.70m;

    /// <summary>คำตอบของชั้น "นักเรียน → ครู" เรื่องเข้าข่ายหัก ณ ที่จ่ายไหม</summary>
    /// <param name="SaysNoWithholding">ตอบชัดว่า<b>ไม่</b>เข้าข่าย — <c>None</c> เท่านั้น
    /// (<c>Skip</c> ถูกปฏิเสธ: มันแปลว่า "ยอดสะสมยังไม่ถึง" ซึ่งขัดกับการคำนวณของเราเอง)</param>
    /// <param name="SaysWithhold">ตอบเป็นประเภทเงินได้ที่<b>มีอยู่จริงในตารางอัตรา</b></param>
    private sealed record WhtAdvice(
        bool SaysNoWithholding, bool SaysWithhold,
        string? Answer, decimal Confidence, bool UsedAi, Guid? FeedbackId);

    /// <summary>
    /// ถามชั้นเรียนรู้ว่า "ใบนี้เข้าข่ายหัก ณ ที่จ่ายไหม" เมื่อหลักฐานเชิงกำหนดตอบไม่ได้
    ///
    /// <para>ใช้ <c>AiFeatureKey.WhtCategoryInference</c> ซึ่ง<b>มีคลังคำตอบอยู่แล้ว</b>
    /// (prompt · นักเรียน <c>GenericFeedbackDistillationModel</c> · งานกลางคืน
    /// <c>AiFeedbackTrainingJob</c>) — ห้ามตั้ง feature key ใหม่สำหรับคำถามเดียวกัน
    /// เพราะจะได้ corpus สองกอง แล้วนักเรียนของทั้งสองกองโตช้าลงครึ่งหนึ่ง
    /// (กฎเหล็ก #1 ข้อ 6)</para>
    ///
    /// <para><b>ด่านกันคำตอบที่แต่งขึ้น</b>: รับเฉพาะ <c>None</c> หรือรหัส
    /// ประเภทเงินได้ที่หาเจอใน <see cref="Accounting.Helpers.ThaiWhtRateTable"/> จริง —
    /// คำตอบนอกชุดถือว่า "ตอบไม่ได้" แล้วตกกลับไปเตือนแบบเดิม (ทิศที่ปลอดภัยกว่าตาม §54)</para>
    /// </summary>
    private async Task<WhtAdvice> AdviseWhtApplicabilityAsync(
        Guid companyId, Document doc, decimal paidToContactThisYear)
    {
        var none = new WhtAdvice(false, false, null, 0m, false, null);
        if (_aiAugmenter == null) return none;

        try
        {
            // คำอธิบายที่ส่งไปถาม = บรรทัดที่มีเงินจริง เรียงตามยอด (บรรทัดยอด 0
            // อย่าง "Shipping costs 0.00" เป็นแถวฟอร์ม ไม่ใช่เนื้อหาของใบ)
            var desc = string.Join(" · ", doc.Lines
                .Where(l => !l.IsDeleted && l.Amount > 0m && !string.IsNullOrWhiteSpace(l.Description))
                .OrderByDescending(l => l.Amount)
                .Take(5)
                .Select(l => l.Description));
            if (string.IsNullOrWhiteSpace(desc)) return none;

            var suggestion = await _aiAugmenter.InferWhtCategoryAsync(
                companyId, doc.Id,
                vendorName: doc.Contact?.Name,
                vendorTaxId: doc.Contact?.TaxId,
                vendorType: doc.Contact?.ContactType.ToString(),
                lineDescription: desc,
                amount: doc.SubTotal,
                localGuess: null, localConfidence: null);

            var answer = suggestion.Answer?.Trim();
            if (string.IsNullOrWhiteSpace(answer)) return none;

            var conf = suggestion.Confidence ?? 0m;

            // ⚠️ **"Skip" ใช้ที่นี่ไม่ได้** — prompt นิยามไว้ว่า Skip แปลว่า
            // "ยอดสะสมยังไม่ถึง 1,000" แต่โค้ดจะมาถึงบรรทัดนี้ได้ก็ต่อเมื่อเรา
            // เพิ่งคำนวณเองแล้วว่า **ถึงเกณฑ์แล้ว** ⇒ รับ Skip = เอาคำตอบที่ขัดกับ
            // การคำนวณเชิงกำหนดของเราเองไปปิดคำเตือน (ฝ่ายค้านรอบ 177)
            // คลังคำตอบนี้ใช้ร่วมกับเส้นถามรายบรรทัดซึ่งตอบ Skip ได้อย่างถูกต้อง
            // ⇒ แถว Skip มีอยู่จริงในคลังและถูกเสิร์ฟกลับมาที่นี่ได้
            if (answer.Equals("Skip", StringComparison.OrdinalIgnoreCase))
            {
                _logger.LogInformation(
                    "WHT advice ตอบ Skip ทั้งที่ยอดสะสมถึงเกณฑ์แล้ว — ถือว่าตอบไม่ได้ แล้วเตือนตามเดิม");
                return none;
            }

            // "ไม่เข้าข่าย" = None (ซื้อสินค้าล้วน) เท่านั้น
            if (answer.Equals("None", StringComparison.OrdinalIgnoreCase))
            {
                // ⚠️ ด่านความมั่นใจ — คำตอบ "ไม่ต้องหัก" เป็นทิศที่ผิดแล้ว**มองไม่เห็น**
                // (§54 ให้ผู้จ่ายรับผิด) ⇒ ต้องมั่นใจพอ ไม่ใช่รับทุกคำตอบ
                // ตัวอย่างในกฎเหล็ก #1 เองก็ใช้ 0.70 เป็นเกณฑ์ก่อน apply
                if (conf < MinWhtSilenceConfidence)
                {
                    _logger.LogInformation(
                        "WHT advice ตอบ None แต่มั่นใจแค่ {Conf:P0} (ต่ำกว่า {Floor:P0}) — เตือนตามเดิม",
                        conf, MinWhtSilenceConfidence);
                    return new WhtAdvice(false, false, answer, conf, suggestion.UsedAi, suggestion.FeedbackId);
                }
                return new WhtAdvice(true, false, answer, conf, suggestion.UsedAi, suggestion.FeedbackId);
            }

            // ⬅ ด่าน: รหัสต้องมีอยู่จริงในตารางอัตรา ไม่งั้นคือคำตอบที่แต่งขึ้น
            if (Accounting.Helpers.ThaiWhtRateTable.Find(answer) != null)
                return new WhtAdvice(false, true, answer, conf, suggestion.UsedAi, suggestion.FeedbackId);

            // ตอบนอกชุด = เชื่อไม่ได้ **แต่ยังต้องเก็บ FeedbackId** — เส้นนี้คือเส้นที่
            // อยากสอนที่สุด ถ้าทิ้งไปคือจ่าย token แล้วไม่มีวันรู้คำตอบที่ถูก (ฝ่ายค้านรอบ 177)
            _logger.LogInformation(
                "WHT advice ตอบนอกชุดคำตอบ ({Answer}) — ถือว่าตอบไม่ได้ แล้วเตือนตามเดิม", answer);
            return new WhtAdvice(false, false, answer, conf, suggestion.UsedAi, suggestion.FeedbackId);
        }
        catch (Exception ex)
        {
            // ปิด provider / เกินงบ / timeout ⇒ เงียบแล้วตกกลับไปเตือนแบบเดิม
            _logger.LogWarning(ex, "WHT applicability advice failed — ใช้คำเตือนเดิมแทน");
            return none;
        }
    }

    private async Task<List<string>> CollectApprovalWarningsAsync(Guid companyId, Document doc)
    {
        var warnings = new List<string>();
        var today = DateTime.UtcNow.Date;

        // Date drift — covers backdated invoices that may have missed
        // their VAT filing window and forward-dated invoices that look
        // like a fat-finger.
        var daysPast = (today - doc.DocumentDate.Date).TotalDays;
        if (daysPast > 90)
            warnings.Add($"วันที่เอกสาร ({doc.DocumentDate:yyyy-MM-dd}) ย้อนหลัง {(int)daysPast} วัน — ตรวจรอบการยื่นภาษีก่อนอนุมัติ");
        else if (daysPast < -30)
            warnings.Add($"วันที่เอกสาร ({doc.DocumentDate:yyyy-MM-dd}) ล่วงหน้าเกิน 30 วัน — โดยปกติออกเอกสารวันจริงเท่านั้น");

        // VAT-eligible types need a contact TaxId for proper e-Tax XML and
        // ภ.พ.30 cross-matching. Without TaxId the e-Tax generator falls
        // back to Non-VAT format silently — works, but the customer can't
        // claim Input VAT on the other side.
        var vatTypes = new[] { DocumentType.TaxInvoice, DocumentType.Receipt, DocumentType.DebitNote, DocumentType.CreditNote };
        if (vatTypes.Contains(doc.DocumentType) && doc.Contact != null && string.IsNullOrWhiteSpace(doc.Contact.TaxId))
            warnings.Add($"ผู้ติดต่อ '{doc.Contact.Name}' ไม่มีเลขผู้เสียภาษี — e-Tax XML จะใช้รูปแบบ Non-VAT ผู้รับใช้เป็นหลักฐาน Input VAT ไม่ได้");

        // ── §86: เก็บ VAT แล้วต้องออกใบกำกับภาษีให้ผู้ซื้อ "ทุกครั้ง" ──
        // เอกสารที่ VAT เข้ารายงานภาษีขาย/ภ.พ.30 แต่หัวกระดาษไม่มีคำว่า
        // "ใบกำกับภาษี" ทำให้เกิดสภาพที่อธิบายกับสรรพากรลำบาก:
        //   • ฝั่งเรา — นำส่ง VAT ครบ (ภาระเกิดจาก tax point ไม่ใช่หัวกระดาษ)
        //   • ฝั่งลูกค้า — เคลมภาษีซื้อไม่ได้ (§82/5(1) ไม่ใช่ใบกำกับเต็มรูป)
        //   • และเราเองมีหน้าที่ตาม §86 ต้องออกใบกำกับทันทีที่ tax point เกิด
        //     ไม่ออก = เบี้ยปรับ 2 เท่าของภาษีตามใบ (§89(5)) + ปรับอาญา
        // เดิมระบบ "auto ติ๊กไม่ประสงค์รับใบกำกับ" ให้เงียบ ๆ เมื่อข้อมูลผู้ซื้อ
        // ไม่ครบ → ผู้ใช้ไม่มีทางรู้ว่าใบนี้ลูกค้าเอาไปใช้ไม่ได้ จึงยกขึ้นมาเตือน
        // (warning ไม่ block — ขายปลีกที่ลูกค้าไม่ขอใบกำกับเป็นเคสปกติ)
        var vatBearingSalesDoc = doc.VatAmount > 0.005m
            && doc.DocumentType is DocumentType.Receipt or DocumentType.ReceiptVoucher
                or DocumentType.TaxInvoice;
        // มัดจำที่ VAT ยังพักรอ (21913) ยังไม่เข้ารายงาน → ยังไม่ถึงเวลาต้องออกใบกำกับ
        var deferredDeposit = doc.IsDeposit && doc.DepositOutputVatDeferred
            && doc.DepositOutputVatRecognizedAt == null;
        if (vatBearingSalesDoc && !deferredDeposit && doc.Contact != null
            && !doc.Contact.IsWalkInCustomer && !doc.BuyerDeclinedTaxInvoice)
        {
            var missingBuyer = Tax.TaxInvoiceCompletenessChecker.MissingBuyerFields(doc.Contact);
            if (missingBuyer.Count > 0)
                warnings.Add(
                    $"⚠️ §86: ใบนี้เก็บ VAT {doc.VatAmount:N2} บาท และจะเข้ารายงานภาษีขาย/ภ.พ.30 "
                    + $"แต่ข้อมูลผู้ซื้อยังขาด {string.Join(", ", missingBuyer)} → หัวเอกสารจะพิมพ์ว่า "
                    + "\"ใบเสร็จรับเงิน\" ไม่ใช่ใบกำกับภาษี. **เรานำส่ง VAT ครบ แต่ลูกค้าเคลมภาษีซื้อ"
                    + "ไม่ได้** (§82/5(1)) และเรามีหน้าที่ออกใบกำกับให้ทุกครั้งที่เก็บ VAT (§86). "
                    + "เติมข้อมูลผู้ซื้อให้ครบ → หัวจะเป็น \"ใบกำกับภาษี/ใบเสร็จรับเงิน\" ใบเดียวจบ "
                    + "(ไม่ต้องออกใบกำกับแยกอีกใบ); หรือถ้าลูกค้าไม่ต้องการใบกำกับจริง ๆ "
                    + "ให้ติ๊ก \"ผู้ซื้อไม่ประสงค์รับใบกำกับภาษี\" เพื่อบันทึกเจตนาไว้เป็นหลักฐาน");
        }

        // ── §86 (เคส "ใบแจ้งหนี้" ขายสินค้า) — ใบกำกับที่ไม่มีคำว่าใบกำกับ ──
        // Invoice ที่มีบรรทัดสินค้า (Product.TrackStock): tax point เกิดตอนส่งมอบ
        // (§78) ⇒ AutoPost ลง Cr 21911 และ VAT **เข้า ภ.พ.30 งวดนี้ทันที** —
        // แต่กระดาษพิมพ์ "ใบแจ้งหนี้" ไม่ใช่ใบกำกับภาษี, ไม่ผ่านด่าน §86/4,
        // ออก e-Tax ไม่ได้ ⇒ เรานำส่ง VAT ครบแต่ลูกค้าเคลมภาษีซื้อไม่ได้ และเรามี
        // หน้าที่ออกใบกำกับ ณ ส่งมอบ (§86 — ไม่ออก = เบี้ยปรับ 2 เท่า §89(5)).
        // เดิม warning ข้างบนจำกัด Receipt/RV/TaxInvoice ⇒ เคสนี้หลุดทุกชั้น
        // ทั้งที่เป็นเคสที่ warning ตัวนั้นเขียนไว้เป๊ะ
        if (doc.DocumentType == DocumentType.Invoice && doc.VatAmount > 0.005m
            && !doc.BuyerDeclinedTaxInvoice
            && await InvoiceHasTrackedGoodsAsync(companyId, doc))
        {
            warnings.Add(
                $"⚠️ §86: ใบแจ้งหนี้ใบนี้มี \"สินค้า\" — tax point เกิดตอนส่งมอบ (§78) "
                + $"VAT {doc.VatAmount:N2} บาท จะเข้ารายงานภาษีขาย/ภ.พ.30 งวดนี้ทันที "
                + "แต่กระดาษพิมพ์ \"ใบแจ้งหนี้\" ไม่ใช่ใบกำกับภาษี → ลูกค้าเคลมภาษีซื้อไม่ได้ "
                + "(§82/5(1)) และผู้ขายมีหน้าที่ออกใบกำกับทันทีที่ส่งมอบ (§86). "
                + "ทางแก้: สร้างใหม่โดยเลือกประเภทเอกสาร \"ใบแจ้งหนี้/ใบกำกับภาษี — "
                + "ขายสินค้า/ต้องออกใบกำกับตอนนี้\" (ใบเดียวทำหน้าที่ครบ ได้เลขชุดใบกำกับ TIV) "
                + "— ใบแจ้งหนี้เปล่าเหมาะกับงานบริการที่ใบกำกับจะออกตอนรับเงิน (§78/1) เท่านั้น");
        }

        // ── ใบนี้คือ "การจ่าย/ภาระจ่ายให้คู่ค้า" ไหม — ตัวตัดสินตัวเดียวของด่านล่าง ──
        //
        // CN/DN เป็นชนิด**สองฝั่ง**: ใช้ override ที่ผู้ใช้ระบุก่อน ถ้าไม่มีให้ดูว่า
        // ใบต้นทางเป็นเอกสารฝั่งซื้อไหม (กติกาเดียวกับด่าน §86/10 ข้างล่างซึ่งเดิม
        // คำนวณค่านี้เองอยู่ที่เดียว) — ส่วนอีกสองด่านเคยถาม
        // `DocumentSide.IsPurchase(type)` **โดยไม่ส่งบทบาท** ทั้งที่ helper ตัวนั้น
        // เขียนไว้เองว่าชนิดกำกวมต้องส่ง `ourRole` ⇒ **ใบลดหนี้ฝั่งขาย**ถูกลากเข้า
        // ด่านซื้อ และ **ใบขอซื้อ/ใบสั่งซื้อ/ใบรับสินค้า** (ยังไม่มีการจ่ายเงิน)
        // ถูกลากเข้าด่านหัก ณ ที่จ่าย + ถูกเขียน audit "ระบบเลือกเงียบ" (ผลตรวจ D1-B2)
        bool? cnDnPurchaseSide = doc.CnDnPurchaseSideOverride;
        if (cnDnPurchaseSide == null
            && doc.DocumentType is DocumentType.CreditNote or DocumentType.DebitNote
            && doc.RelatedDocumentId.HasValue)
        {
            cnDnPurchaseSide = await _db.Documents.AsNoTracking().AnyAsync(x =>
                x.Id == doc.RelatedDocumentId.Value && x.CompanyId == companyId
                && (x.DocumentType == DocumentType.PurchaseInvoice
                    || x.DocumentType == DocumentType.Expense
                    || x.DocumentType == DocumentType.PaymentVoucher
                    || x.DocumentType == DocumentType.CertificateInLieu));
        }
        // ชุดชนิดเอกสารมาจาก `WhtCumulativeScope.Counts` ตัวเดียว (ชุดที่ใช้คิดยอด
        // สะสมด้วย) — ห้ามมีชุดที่สอง ไม่งั้นด่านเตือนกับยอดที่โชว์จะนับคนละใบ
        var paysCounterparty = Accounting.Helpers.WhtGateScope.Applies(
            doc.DocumentType, cnDnPurchaseSide);

        // ── §82/5(4)(6) ภาษีซื้อต้องห้าม — ครอบ **ทุกทางเข้า** ไม่ใช่แค่ OCR ──
        //
        // `ProhibitedInputVatScreener` ถูกเรียกจากที่เดียวคือสาย OCR (ผลตรวจ C-T12)
        // ⇒ ใบที่คีย์มือ / นำเข้า CSV / ยิงผ่าน API เลือกผัง "ค่ารับรอง" หรือ
        // "ค่าน้ำมัน" แล้ว**เคลมภาษีซื้อผ่านฉลุย** ⇒ ยื่น ภ.พ.30 เกินสิทธิ์
        // (โดนประเมิน + เบี้ยปรับ) — ด่านที่ครอบแค่ทางเดียวคือด่านที่ไม่มี
        //
        // ที่นี่ไม่มี raw text ของกระดาษ จึงคัดกรองจาก **ชื่อผู้ขาย + คำอธิบาย
        // รายบรรทัด** ซึ่งเป็นข้อมูลที่ผู้ใช้พิมพ์เองอยู่แล้ว · เตือน ไม่บล็อก
        // เพราะรถบางประเภทเคลมได้ (§82/5(6) ยกเว้นรถบรรทุก/กระบะตอนเดียว)
        if (paysCounterparty
            && doc.VatAmount > 0.005m
            && doc.Lines.Any(l => l.IsVatClaimable))
        {
            // ธงผู้ประกอบกิจการขาย/ให้เช่ารถ (ข้อยกเว้น §82/5(6)) เข้าตัวตัดสินตัวเดียวกับเส้น OCR —
            // เดิมมีด่านรถชุดที่สองท้ายเมธอดนี้ (ลิสต์คำคนละชุด) ที่อ่านธงนี้อยู่ตัวเดียว (รอบ 193 · S-05)
            var isVehicleDealer = await _db.CompanySettings.AsNoTracking()
                .Where(s => s.CompanyId == companyId && !s.IsDeleted)
                .Select(s => (bool?)s.IsVehicleDealer)
                .FirstOrDefaultAsync() ?? false;
            var verdict = Ocr.ProhibitedInputVatScreener.Screen(
                null, doc.Contact?.Name, doc.Lines.Select(l => l.Description), isVehicleDealer);
            if (!string.IsNullOrEmpty(verdict.Warning))
            {
                var head = verdict.Claimable == false
                    ? "⚠️ ภาษีซื้อต้องห้าม — ใบนี้ยังตั้งเป็น \"เคลมได้\""
                    : "ℹ️ ตรวจสิทธิ์เคลมภาษีซื้อ";
                warnings.Add($"{head} ({verdict.RuleCode}) {verdict.Warning}");
            }
        }

        // ── ท.ป.4/2528 ข้อ 12: ด่าน ฿1,000 **สะสมต่อคู่สัญญา** (ผลตรวจ C-T05) ──
        //
        // `ThaiWhtRateTable.ShouldWithhold` มีอยู่ในเรพพร้อมคอมเมนต์อธิบายกติกา
        // ครบถ้วน แต่ **ไม่มี call site เลย** ⇒ ระบบหักตามที่ผู้ใช้พิมพ์ล้วน ๆ
        // เคสที่หลุด: จ่ายงวดละ 800 สามงวดในสัญญาเดียวกัน — ดูทีละใบไม่ถึง 1,000
        // เลยสักใบ ⇒ ไม่หักทั้งสามงวด ทั้งที่กฎหมายให้หักตั้งแต่งวดที่ยอดสะสมถึง
        // ⇒ **ผู้จ่ายรับผิดในภาษีที่ไม่ได้หัก (§54)** ไม่ใช่ผู้รับ
        //
        // ═══ สามสถานะ ไม่ใช่สองสถานะ (ผู้ใช้รายงาน 2026-09-18) ═══
        // เดิมเงื่อนไขมีแค่ 4 ข้อ — ฝั่งซื้อ · มีคู่ค้า · ยังไม่กรอก WHT · ยอดสะสม
        // ≥ 1,000 — **ไม่มีข้อไหนถามว่าเป็นค่าสินค้าหรือค่าบริการ** ทั้งที่
        // ท.ป.4/2528 ครอบเฉพาะค่าบริการ/ค่าจ้าง/ค่าเช่า/วิชาชีพ ฯลฯ
        // **การซื้อสินค้าไม่อยู่ในข่าย** ⇒ ใบซื้อของทุกใบที่เกินพันเด้งหมด
        // ⇒ ผู้ใช้เรียนรู้ที่จะกด "ยอมรับและอนุมัติต่อ" โดยไม่อ่าน ⇒ วันที่เป็น
        // ค่าบริการจริงก็จะถูกกดผ่านไปด้วย = ปิดด่านโดยไม่ตั้งใจ (กฎเหล็ก #4)
        if (paysCounterparty
            && doc.ContactId != Guid.Empty
            && doc.WithholdingTaxAmount <= 0.005m
            && doc.SubTotal > 0m)
        {
            // ชั้นที่ 0 — **กระดาษพูดก่อน** (คำตัดสินเจ้าของโปรเจกต์ 2026-09-18)
            // ใบกำกับที่สแกนมาไม่มีส่วน "หัก ณ ที่จ่าย" ⇒ ไม่ต้องหัก
            var (paperShowsWht, paperGrade, paperGradeReason) =
                await ScanPaperWhtEvidenceAsync(companyId, doc.Id);

            // ชั้นที่ 1 — หลักฐานเชิงกำหนดจากข้อมูลที่เราถืออยู่ (pure helper + เทสต์)
            var whtLineFacts = await BuildWhtLineFactsAsync(companyId, doc);
            var whtEvidence = Accounting.Helpers.WhtApplicabilityEvidence.Judge(
                whtLineFacts, paperShowsWht, paperGrade);

            // ใบที่ "เงียบแต่ไม่สมบูรณ์" ต้องตามรอยได้ว่าทำไมความเงียบนั้นไม่ถูกนับ
            // (ไม่งั้นรอบหน้าจะมีคนถามซ้ำว่า "กระดาษไม่มีบรรทัดหัก ทำไมยังเตือน")
            if (paperShowsWht == false && paperGrade != Accounting.Helpers.PaperTaxInvoiceGrade.Complete)
                _logger.LogInformation(
                    "WHT: กระดาษของเอกสาร {DocumentId} ไม่มีส่วนหัก ณ ที่จ่าย แต่ยังไม่นับเป็นหลักฐาน — {Reason}",
                    doc.Id, paperGradeReason);

            // พิสูจน์ได้ว่าไม่อยู่ในข่าย ⇒ **เงียบสนิท** ไม่ต้องคิดยอดสะสมด้วยซ้ำ
            if (whtEvidence.Level != Accounting.Helpers.WhtApplicability.NotApplicable)
            {
                // ── ยอดจ่ายสะสมปีนี้ ──────────────────────────────────────
                // ⚠️ เดิมคิวรีนี้รวมยอดจาก **เอกสารทุกชนิด** ที่ผูกกับคู่ค้ารายนั้น
                // โดยไม่กรองฝั่ง/ชนิดเลย ⇒ ใบเสนอราคา · ใบสั่งซื้อ · **ใบขายที่เรา
                // ออกให้เขา** · และการซื้อครั้งเดียวที่มีทั้ง PO + ใบกำกับ + ใบสำคัญจ่าย
                // ถูกนับซ้ำ ⇒ ตัวเลขที่โชว์ว่า "ยอดจ่ายสะสม" ไม่ใช่ยอดจ่ายจริง
                //
                // ⚠️ และ **ห้ามใช้ ArApScope.PayableTypes** เป็นนิยามของ "ยอดจ่าย" —
                // ชุดนั้นคือ "เอกสารที่เพิ่มเจ้าหนี้" สำหรับ aging และ doc ของมันเขียนเองว่า
                // PV/CIL เป็นหลักฐานจ่าย ไม่ใช่การตั้งหนี้ ⇒ จ่ายงวดละ 800 สามงวดด้วย
                // ใบสำคัญจ่ายจะได้ยอดสะสม 0 ทุกงวด = ไม่เตือนสักงวด ซึ่งเป็นเคสที่กฎนี้
                // ถูกสร้างมาแก้โดยตรง (ฝ่ายค้านรอบ 177 จับได้หลังผมเผลอใช้ชุดนั้น)
                // → Helpers/WhtCumulativeScope: ชุด "เอกสารที่แทนการจ่าย" + กันนับซ้ำ
                //   ด้วยความสัมพันธ์ต้นทาง–ปลายทาง แทนการตัดชนิดเอกสารทิ้ง
                var yearStart = new DateTime(doc.DocumentDate.Year, 1, 1);
                var yearRows = await _db.Documents.AsNoTracking()
                    .Where(d => d.CompanyId == companyId && d.ContactId == doc.ContactId
                                && d.Id != doc.Id
                                && d.DocumentDate >= yearStart && d.DocumentDate <= doc.DocumentDate
                                && d.Status != DocumentStatus.Draft && d.Status != DocumentStatus.Voided)
                    .Select(d => new Accounting.Helpers.WhtPaymentRow(
                        d.Id, d.DocumentType, d.SubTotal, d.RelatedDocumentId, d.CnDnPurchaseSideOverride))
                    .ToListAsync();
                var paidToContactThisYear = Accounting.Helpers.WhtCumulativeScope.SumDistinct(yearRows);

                if (Accounting.Helpers.ThaiWhtRateTable.ShouldWithhold(doc.SubTotal, paidToContactThisYear))
                {
                    var cumulative = doc.SubTotal + paidToContactThisYear;
                    var head =
                        $"ยอดจ่ายสะสมให้ '{doc.Contact?.Name ?? "คู่ค้ารายนี้"}' ปีนี้เป็น {cumulative:N2} บาท "
                        + $"(ใบนี้ {doc.SubTotal:N2} + ก่อนหน้า {paidToContactThisYear:N2}) — "
                        + $"เกินเกณฑ์ {Accounting.Helpers.ThaiWhtRateTable.MinimumThresholdBaht:N0} บาท "
                        + "ซึ่งนับ**สะสมต่อคู่สัญญา ไม่ใช่ต่อใบ**";

                    if (whtEvidence.Level == Accounting.Helpers.WhtApplicability.ServiceWithholding)
                    {
                        // พิสูจน์ได้ว่าเป็นค่าบริการ — เตือนอย่างมั่นใจ
                        warnings.Add(
                            $"⚠️ ท.ป.4/2528 ข้อ 12: ใบนี้ยังไม่ได้หัก ณ ที่จ่าย — {whtEvidence.Reason}. "
                            + head + " ⇒ ต้องหักตั้งแต่งวดที่ยอดสะสมถึงเกณฑ์. "
                            + "**ภาษีที่ไม่ได้หัก ผู้จ่ายเป็นผู้รับผิด (§54)**");
                    }
                    else
                    {
                        // ── ชั้นที่ 2 — ยังไม่รู้: **เงียบ เว้นแต่มีเหตุให้สงสัย** ──
                        //
                        // คำตัดสินเจ้าของ 2026-09-18 (รอบ 179): "มีเหตุให้สงสัยว่าเป็น
                        // ค่าจ้าง หรือ ค่าบริการ ค่อยขึ้นเตือนหัก" — พลิกค่าตั้งต้นจาก
                        // "ไม่รู้ ⇒ เตือนไว้ก่อน" เป็น "ไม่รู้ ⇒ เงียบ"
                        //
                        // เหตุผล: กฎเดิมเลือกทิศปลอดภัยตาม §54 (ผู้จ่ายรับผิด) แต่ราคาของ
                        // มันคือใบที่ระบบอ่านรายการไม่ออกเด้งหมด ⇒ ผู้ใช้ชินกับการกดข้าม
                        // ⇒ วันที่เตือนถูกจริงก็ถูกกดข้ามไปด้วย = ปิดด่านโดยไม่ตั้งใจ
                        // (กฎเหล็ก #4: "คำเตือนที่ฟ้องใบถูกทุกใบ = ไม่มีด่าน")
                        //
                        // ⚠️ ข้อแลกเปลี่ยนที่ผมแจ้งเจ้าของแล้ว: ใบค่าบริการที่ไม่มีคำบ่งชี้
                        // และชั้นเรียนรู้ตอบไม่ได้ จะ**เงียบ** ⇒ ความเสี่ยง §54 ตกที่บริษัท
                        // — ชดเชยด้วยการทำให้ "เหตุ" ครอบคลุม (WhtServiceHints) และ
                        //   บันทึกทุกครั้งที่เลือกเงียบลง audit chain ให้ตามรอยได้
                        // ชนิดผู้รับเงินเป็น **ตัวลดเกณฑ์** ไม่ใช่ "เหตุ" ในตัวเอง —
                        // ต้องพิสูจน์ได้เชิงบวก (เลขบัตร 13 หลักขึ้นต้น 1–8 หรือคำนำหน้า
                        // ชื่อที่มนุษย์กรอก) ห้ามใช้ `ContactType` ดิบซึ่ง default = Individual
                        var payeeIndividual = Accounting.Helpers.WhtPayeeKind.IsProvenIndividual(
                            doc.Contact?.TaxId, doc.Contact?.Name, doc.Contact?.TitleTh);
                        var hint = Accounting.Helpers.WhtServiceHints.Scan(whtLineFacts, payeeIndividual);
                        if (!hint.Suspicious)
                        {
                            // ไม่มีเหตุ ⇒ เงียบ · ไม่ถามชั้นเรียนรู้ด้วยซ้ำ เพราะคำตอบ
                            // ไม่เปลี่ยนสิ่งที่ผู้ใช้เห็น (DECISION_DOCTRINE §2.1 ข้อ 4)
                            RecordWhtSilence(doc, companyId, paidToContactThisYear,
                                Accounting.Helpers.WhtAdviceNote.NoSuspicionRuleCode,
                                "ไม่พบเหตุให้สงสัยว่าเป็นค่าจ้าง/ค่าบริการในรายการของใบนี้",
                                advice: null);
                        }
                        else
                        {
                            // มีเหตุแล้ว — ถามชั้นเรียนรู้ว่าเป็นเงินได้ประเภทไหน
                            // (กฎเหล็ก #1) orchestrator ถาม local model ก่อนเสมอ แล้วค่อย
                            // ตกไปหา AI เมื่อนักเรียนไม่มั่นใจ · ปิด provider ทุกตัวแล้ว
                            // นักเรียนยังตอบได้
                            var advice = await AdviseWhtApplicabilityAsync(companyId, doc, paidToContactThisYear);

                            doc.WhtAdviceAiFeedbackId = advice.FeedbackId ?? doc.WhtAdviceAiFeedbackId;
                            doc.WhtAdviceAnswer = advice.Answer ?? doc.WhtAdviceAnswer;
                            doc.WhtAdviceUsedAi = advice.UsedAi;

                            var why = $"พบคำว่า \"{hint.MatchedKeyword}\" ในรายการ "
                                + $"(คิดเป็น {hint.AmountShare:P0} ของยอดใบนี้)"
                                + (payeeIndividual ? " และผู้รับเป็นบุคคลธรรมดา" : "");

                            if (advice.SaysNoWithholding)
                            {
                                // โมเดลปัดข้อสงสัยตก ⇒ เงียบ แต่ต้องตามรอยได้
                                RecordWhtSilence(doc, companyId, paidToContactThisYear,
                                    Accounting.Helpers.WhtAdviceNote.SilentRuleCode,
                                    why + " แต่ชั้นเรียนรู้ประเมินว่าไม่เข้าข่าย",
                                    advice);
                            }
                            else if (advice.SaysWithhold)
                            {
                                warnings.Add(
                                    $"🤔 ระบบสงสัยว่าใบนี้เข้าข่ายหัก ณ ที่จ่าย — โปรดตรวจสอบ. "
                                    + why + " · "
                                    + $"{(advice.UsedAi ? "🤖 AI" : "⚙️ ระบบ")}ประเมินว่าเป็นเงินได้ประเภท "
                                    + $"'{advice.Answer}' (ความมั่นใจ {advice.Confidence:P0}) และ" + head + ". "
                                    + "ถ้าเป็นค่าซื้อสินค้า กด \"ยอมรับและอนุมัติต่อ\" ได้เลย — "
                                    + "ระบบจะจำคำตอบนี้ไว้สอนตัวเองสำหรับคู่ค้ารายนี้. "
                                    + "**ภาษีที่ไม่ได้หัก ผู้จ่ายเป็นผู้รับผิด (§54)**");
                            }
                            else
                            {
                                // ชั้นเรียนรู้ตอบไม่ได้ (cold start / ปิด AI / ตอบนอกชุด)
                                // แต่**เหตุยังอยู่** ⇒ ยังต้องเตือน เพียงแต่บอกไม่ได้ว่าประเภทไหน
                                warnings.Add(
                                    $"🤔 ระบบสงสัยว่าใบนี้เข้าข่ายหัก ณ ที่จ่าย — โปรดตรวจสอบ. "
                                    + why + " และ" + head + ". "
                                    + "ถ้าเป็นค่าบริการต้องหักตั้งแต่งวดที่ยอดสะสมถึงเกณฑ์ "
                                    + "· ถ้าเป็นค่าซื้อสินค้าไม่ต้องหัก — ยืนยันเพื่ออนุมัติต่อ. "
                                    + "**ภาษีที่ไม่ได้หัก ผู้จ่ายเป็นผู้รับผิด (§54)**");
                            }
                        }
                    }
                }
            }
        }

        // §86/10 — ใบลดหนี้/ใบเพิ่มหนี้ "ฝั่งซื้อ" ที่มี VAT: รายงานภาษีซื้อต้อง
        // อ้าง **เลขที่ใบของผู้ออก (ผู้ขาย)** ไม่ใช่เลขเอกสารภายในของเรา —
        // ถ้าไม่กรอก รายงาน/ไฟล์ยื่นจะโชว์เลข CN ของระบบเราซึ่งกระทบยอดกับ
        // ผู้ขายไม่ได้และสรรพากรตรวจไม่ตรง (soft warning — ใบเก่าก่อนมีช่องนี้
        // ยังอนุมัติได้ แต่ต้องเห็นเตือน). ฝั่งขายไม่ต้อง — เลขที่ใบคือของเราเอง
        if (doc.DocumentType is DocumentType.CreditNote or DocumentType.DebitNote
            && doc.VatAmount != 0
            && string.IsNullOrWhiteSpace(doc.SupplierInvoiceNumber))
        {
            // ใช้ค่าที่ตัดสินไว้แล้วข้างบน (override → ใบต้นทาง) — เดิมคำนวณซ้ำที่นี่
            if (cnDnPurchaseSide == true)
            {
                var w = doc.DocumentType == DocumentType.CreditNote ? "ใบลดหนี้" : "ใบเพิ่มหนี้";
                warnings.Add($"⚠️ §86/10: {w}ฝั่งซื้อใบนี้มี VAT {doc.VatAmount:N2} บาท "
                    + $"แต่ยังไม่ได้กรอก \"เลขที่{w}จากผู้ขาย\" — รายงานภาษีซื้อ/ไฟล์ยื่นจะแสดง"
                    + "เลขเอกสารภายในของเราแทนเลขจริงของผู้ออก (กระทบยอดกับผู้ขายไม่ได้). "
                    + $"เปิดเอกสาร → กรอกช่อง \"เลขที่{w}จากผู้ขาย\" ก่อนยื่น ภ.พ.30");
            }
        }

        // TFRS บทที่ 8 — ใบลดหนี้ฝั่งซื้อเหตุผล "รับคืนสินค้า" ตัด **จำนวน** ออกจาก
        // สต็อกจริง (`ApplyStockMovementsAsync`) ⇒ ถ้าขา Cr ไม่ใช่บัญชีคุมสต็อกของ
        // สินค้านั้น จำนวนลดแต่มูลค่าใน GL ไม่ลด = สองความจริงที่สะสมทุกใบ
        //
        // **เป็นคำเตือน ไม่ใช่การบล็อก** โดยเจตนา: มีเคสที่ผู้ใช้ตั้งใจจริง (ของถูกขาย
        // ออกไปแล้ว ส่วนลดตามทฤษฎีเข้า COGS) ซึ่งระบบแยกจากข้อมูลบนใบไม่ได้ ·
        // ของเดิมคือ "เงียบสนิท" — รอบนี้อย่างน้อยผู้ใช้เห็นและกดยืนยันเองว่ารู้ตัว
        if (doc.DocumentType == DocumentType.CreditNote
            && cnDnPurchaseSide == true
            && doc.CreditNoteReason == Models.Enums.CreditNoteReason.Return
            && doc.Lines.Any(l => l.AccountId.HasValue && !string.IsNullOrWhiteSpace(l.ProductCode)))
        {
            var stockCodes = doc.Lines
                .Where(l => l.AccountId.HasValue && !string.IsNullOrWhiteSpace(l.ProductCode))
                .Select(l => l.ProductCode!.Trim()).Distinct().ToList();
            var stockProducts = await _db.Products.AsNoTracking()
                .Where(pr => pr.CompanyId == companyId && stockCodes.Contains(pr.Code)
                    && !pr.IsDeleted && pr.TrackStock)
                .Select(pr => new { pr.Code, pr.ProductType, pr.InventoryAccountId, pr.SuppliesAccountId })
                .ToListAsync();
            if (stockProducts.Count > 0)
            {
                var invDefault = (await FindAccountAsync(companyId, "11500")
                    ?? await FindAccountAsync(companyId, "115"))?.Id;
                Guid? supDefault = null;
                if (stockProducts.Any(pr => pr.ProductType == Models.Enums.ProductType.Supplies))
                    supDefault = (await FindAccountAsync(companyId,
                        Accounting.Helpers.InventoryControlAccount.DefaultAccountPrefix(
                            Models.Enums.ProductType.Supplies)))?.Id;
                var prodByCode = stockProducts.ToDictionary(pr => pr.Code);
                var codeIds = doc.Lines.Where(l => l.AccountId.HasValue)
                    .Select(l => l.AccountId!.Value).ToList();
                var acctCodeById = await _db.ChartOfAccounts.AsNoTracking()
                    .Where(a => a.CompanyId == companyId && codeIds.Contains(a.Id))
                    .ToDictionaryAsync(a => a.Id, a => a.AccountCode);
                foreach (var line in doc.Lines)
                {
                    if (!line.AccountId.HasValue || string.IsNullOrWhiteSpace(line.ProductCode)) continue;
                    if (!prodByCode.TryGetValue(line.ProductCode!.Trim(), out var prod)) continue;
                    var controlId = Accounting.Helpers.InventoryControlAccount.Resolve(
                        prod.ProductType, prod.InventoryAccountId, prod.SuppliesAccountId,
                        invDefault, supDefault);
                    if (!controlId.HasValue || controlId.Value == line.AccountId.Value) continue;
                    acctCodeById.TryGetValue(line.AccountId.Value, out var pickedCode);
                    var controlCode = await _db.ChartOfAccounts.AsNoTracking()
                        .Where(a => a.Id == controlId.Value && a.CompanyId == companyId)
                        .Select(a => a.AccountCode).FirstOrDefaultAsync();
                    var w = Accounting.Helpers.AdjustmentNoteAccount.StockValuationWarning(
                        isPurchaseSide: true, lineReturnsGoods: true, productTracksStock: true,
                        pickedAccountCode: pickedCode, inventoryControlAccountCode: controlCode,
                        lineDescription: line.Description);
                    if (w != null) warnings.Add(w);
                }
            }
        }

        // §83/6 — ใบซื้อที่ "น่าจะเป็นบริการต่างประเทศ" แต่ลืมติ๊ก
        // (ผู้ใช้ส่งภาพจริง 2026-09-21: ใบค่าคอมมิชชั่น Booking.com สองใบของคู่ค้า
        //  เดียวกัน ใบหนึ่งติ๊ก ใบหนึ่งไม่ติ๊ก ⇒ ใบที่ไม่ติ๊กไม่มี Cr 21912 เลย)
        // กติกาอยู่ใน `Helpers/ForeignServiceEvidence` ตัวเดียว — เป็นคำเตือน
        // ไม่ใช่การบล็อก เพราะหลักฐานที่มีตอบไม่ได้ 100% (ดู doc-comment ที่นั่น)
        if (doc.DocumentType is DocumentType.PurchaseInvoice or DocumentType.Expense
                or DocumentType.PaymentVoucher)
        {
            var fs = Accounting.Helpers.ForeignServiceEvidence.Judge(
                isForeignService: doc.IsForeignService,
                vatAmount: doc.VatAmount,
                contactCountryCode: doc.Contact?.CountryCode,
                contactTaxId: doc.Contact?.TaxId,
                inputVatParkedAsUndue: doc.InputVatPostedAsUndue
                    || doc.InputVatAccountCodeOverride == "11640");
            if (fs.Suspect) warnings.Add("⚠️ " + fs.Reason);
        }

        // §81/1 — ผู้ที่ไม่ได้จด VAT ห้ามออกใบกำกับภาษี + เก็บ VAT. ถ้าบริษัท
        // VatRegistered=false แต่กำลังออกใบกำกับ/ใบเพิ่ม-ลดหนี้ที่มี VAT → เตือน
        // (ออกใบกำกับโดยไม่จด VAT = ความผิด §90/2 + ต้องนำส่ง VAT ที่เรียกเก็บ).
        if (doc.DocumentType is DocumentType.TaxInvoice or DocumentType.DebitNote or DocumentType.CreditNote
            && doc.VatAmount > 0)
        {
            var vatRegistered = await Accounting.Helpers.CompanyVatStatus.IsRegisteredAsync(_db, companyId);
            if (!vatRegistered)
                warnings.Add("⚠️ บริษัทยังไม่ได้จดทะเบียน VAT แต่กำลังออกใบกำกับภาษีที่มี VAT — " +
                    "ผู้ไม่จด VAT ห้ามออกใบกำกับ (§90/2) และต้องนำส่ง VAT ที่เรียกเก็บ. " +
                    "ถ้ารายได้เกิน 1.8 ล้าน/ปี ต้องจด VAT ภายใน 30 วัน (§85/1)");
        }

        // §86+§78 — "ใบแจ้งหนี้" ที่มีสินค้า TrackStock: อนุมัติ = ตัดสต๊อก = ส่งมอบ
        // → tax point เกิดทันที ระบบนำส่ง VAT ให้ครบ (Cr 21911 + ภ.พ.30) แต่กระดาษ
        // "ใบแจ้งหนี้" ไม่ใช่ใบกำกับภาษี — ผู้ขายมีหน้าที่ออกใบกำกับ ณ วันส่งมอบ และ
        // ผู้ซื้อใช้ใบแจ้งหนี้เคลมภาษีซื้อไม่ได้ → เตือนให้ใช้ใบกำกับ/ใบรวมแทน.
        // (ใบแจ้งหนี้ "บริการล้วน" ไม่เตือน — tax point ยังไม่เกิด VAT พัก 21913 ถูกแล้ว)
        if (doc.DocumentType == DocumentType.Invoice && doc.VatAmount > 0)
        {
            var invGoodsCodes = doc.Lines
                .Where(l => !string.IsNullOrWhiteSpace(l.ProductCode))
                .Select(l => l.ProductCode!)
                .Distinct()
                .ToList();
            if (invGoodsCodes.Count > 0)
            {
                var invHasGoods = await _db.Products.AsNoTracking()
                    .AnyAsync(p => p.CompanyId == companyId && invGoodsCodes.Contains(p.Code)
                        && !p.IsDeleted && p.TrackStock);
                if (invHasGoods)
                    warnings.Add("ใบแจ้งหนี้นี้มีสินค้า (อนุมัติแล้วตัดสต๊อก = ส่งมอบ) — จุดความรับผิด VAT เกิดทันที (§78) " +
                        "ผู้ขายต้องออก 'ใบกำกับภาษี' ให้ผู้ซื้อ ณ วันส่งมอบ: แนะนำเปลี่ยนเป็นใบกำกับภาษี " +
                        "หรือติ๊ก 'ใบแจ้งหนี้/ใบกำกับภาษี' ใบเดียว — ใบแจ้งหนี้เปล่าผู้ซื้อเคลมภาษีซื้อไม่ได้ " +
                        "(ระบบจะนำส่ง VAT เข้า ภ.พ.30 ให้ทันทีอยู่แล้วไม่ว่าเลือกแบบไหน)");
            }
        }

        // ใบเสร็จ "อิสระ" (ไม่อ้างใบต้นทาง = ลง Dr เงินสด / Cr รายได้+VAT ใหม่ทั้งใบ)
        // ทั้งที่ลูกค้ารายนี้มีใบแจ้งหนี้/ใบกำกับค้างชำระอยู่ — ถ้าใบเสร็จนี้คือการ
        // รับชำระใบเดิม จะกลายเป็น "รายได้ + VAT ซ้ำ 2 รอบ" จากการขายครั้งเดียว
        // → เตือนให้ใช้ตัวดึงใบค้าง (หน้าเอกสาร) / แปลงจากใบเดิม / บันทึกชำระ แทน
        if (doc.DocumentType is DocumentType.Receipt or DocumentType.ReceiptVoucher
            && !doc.RelatedDocumentId.HasValue && !doc.IsDeposit && doc.ContactId != Guid.Empty)
        {
            var arOutstanding = await _db.Documents.AsNoTracking()
                .Where(d => d.CompanyId == companyId && d.ContactId == doc.ContactId
                    && d.Id != doc.Id && !d.IsDeleted
                    && (d.DocumentType == DocumentType.Invoice
                        || d.DocumentType == DocumentType.TaxInvoice
                        || d.DocumentType == DocumentType.DebitNote)
                    && (d.Status == DocumentStatus.Approved || d.Status == DocumentStatus.Sent
                        || d.Status == DocumentStatus.PartiallyPaid || d.Status == DocumentStatus.Overdue)
                    && d.BalanceDue > 0.01m)
                .Select(d => new { d.DocumentNumber, d.BalanceDue })
                .Take(3)
                .ToListAsync();
            if (arOutstanding.Count > 0)
                warnings.Add($"ลูกค้ารายนี้มีเอกสารค้างชำระอยู่ (เช่น {string.Join(", ", arOutstanding.Select(a => $"{a.DocumentNumber} คงค้าง {a.BalanceDue:N2}"))}) " +
                    "— ใบเสร็จอิสระใบนี้จะลง 'รายได้ + VAT ใหม่ทั้งใบ' ไม่ตัดยอดใบเดิม. " +
                    "ถ้าตั้งใจรับชำระใบค้าง ให้ใช้ช่อง 'รับชำระใบค้างของลูกค้า' ตอนสร้างใบเสร็จ หรือกด 'บันทึกชำระเงิน'/'แปลงเอกสาร' จากใบเดิมแทน — มิฉะนั้นรายได้และภาษีขายจะซ้ำ 2 รอบ");
        }

        // Per-line VAT + WHT rate sanity. The 0/7 hard block sits in the
        // create path; this is the "rate is technically legal but unusual"
        // shoulder (e.g. ratio that doesn't match a known ภ.ง.ด. code).
        // อัตราที่ถือว่า "มาตรฐาน" อ่านจาก `ThaiWhtRateTable.StatutoryRates` ตัวเดียว
        // (เดิมเป็นเซ็ตฝังในไฟล์นี้ซึ่งมี 1.5% ที่ตารางกลางไม่มี = ตารางกฎหมาย
        // สำเนาที่สอง — ผลตรวจ D1-3) · ข้อความก็สร้างจากตารางเดียวกัน ไม่พิมพ์ซ้ำ
        foreach (var line in doc.Lines)
        {
            if (line.WithholdingTaxRate > 0
                && !Accounting.Helpers.ThaiWhtRateTable.StatutoryRates.Contains(line.WithholdingTaxRate))
                warnings.Add($"อัตรา WHT ของ '{line.Description}' = {line.WithholdingTaxRate}% — ไม่ใช่อัตราตามกฎหมาย ("
                    + string.Join(" / ", Accounting.Helpers.ThaiWhtRateTable.StatutoryRates.Select(r => $"{r:0.##}"))
                    + "%) ตรวจ Income Type Code อีกครั้ง");
        }

        // ── ด่านหัก ณ ที่จ่าย "ชุดเก่า" ถูกถอดแล้ว (ผลตรวจ D1-B1 รอบ 181) ──
        // เดิมบล็อก §50 อีกชุดยืนอยู่ตรงนี้: `IsPureGoodsPurchaseAsync` +
        // `CheckWhtThresholdAsync` เตือนทุกใบที่บรรทัด**ไม่ได้ผูกสินค้าที่ตัดสต๊อก
        // หรือผัง 115x/51xxx** ซึ่งคือเคสเดียวกับที่ด่านใหม่ (สามสถานะ ข้างบน)
        // ตั้งใจให้ "เงียบ" แล้วเขียน audit `WhtWarningSuppressed` ไว้
        // ⇒ audit บอกว่าเงียบ แต่จอเตือน = สองความจริงบนใบเดียว
        // และด่านเก่าไม่เคยดู `paperGrade` เลย ⇒ คำตัดสิน "ใบกำกับเต็มรูปที่ครบ
        // §86/4 และไม่มีบรรทัดหัก ณ ที่จ่าย ⇒ ไม่ต้องหัก" ถูกลบล้างทุกครั้ง
        // อีกทั้งยอดสะสมของมันรวม PI+Expense+PV **ตรง ๆ** (ไม่กันนับซ้ำ) ต่างจาก
        // `WhtCumulativeScope.SumDistinct` ที่ด่านใหม่ใช้ ⇒ การซื้อครั้งเดียวที่มี
        // ทั้งใบกำกับและใบสำคัญจ่ายถูกนับสองรอบ. ด่านเดียวที่เหลือคือด่านใหม่

        // DTA bilateral treaty — เตือนเมื่อจ่ายไปต่างประเทศ + ใช้ default rate
        // (15% ม.70) แต่ payee country มี DTA ลดเหลือ 5-10% บ่อย → ผู้ใช้
        // อาจหักเกินไปเสียค่าใช้จ่ายให้ vendor เปล่าๆ
        if ((doc.DocumentType == DocumentType.PaymentVoucher
             || doc.DocumentType == DocumentType.Expense
             || doc.DocumentType == DocumentType.PurchaseInvoice)
            && doc.WithholdingTaxAmount > 0m
            && !string.IsNullOrEmpty(doc.Contact?.CountryCode)
            && !string.Equals(doc.Contact.CountryCode, "TH", StringComparison.OrdinalIgnoreCase))
        {
            var maxRate = doc.Lines?.Max(l => l.WithholdingTaxRate) ?? 0m;
            if (maxRate >= 15m)
                warnings.Add($"🌐 จ่ายต่างประเทศ ({doc.Contact.CountryCode}): WHT {maxRate}% (ม.70 default). ตรวจ DTA bilateral treaty — ส่วนใหญ่ลดเหลือ 5-10% ถ้ามี Certificate of Residence/Form TH8 ของ payee");
        }

        // Sticker-shock guard — flag invoices > 500k THB. Catches a typo
        // like 4,500,000 vs 450,000.
        if (doc.TotalAmount >= 500_000m)
            warnings.Add($"ยอดรวมเอกสาร {doc.TotalAmount:N2} {doc.Currency} — ตรวจตัวเลขก่อนยืนยัน (จำนวนเงินสูงผิดปกติ)");

        // §82/3 — ภาษีซื้อต้องเคลมภายใน 6 เดือนนับจาก tax point. ใบกำกับ
        // ที่ใบมาช้า (vendor ส่งหลัง 6 เดือน) ระบบลงให้แต่เคลมไม่ได้ใน
        // ภ.พ.30. เตือนตอน approve (ก่อนที่จะรู้ตอน end-of-month)
        if (doc.DocumentType is DocumentType.PurchaseInvoice or DocumentType.Expense
            or DocumentType.PaymentVoucher or DocumentType.CertificateInLieu)
        {
            var taxPoint = doc.TaxPointDate ?? doc.SupplierTaxInvoiceDate ?? doc.DocumentDate;
            var monthsLate = ((today.Year - taxPoint.Year) * 12) + (today.Month - taxPoint.Month);
            if (monthsLate > 6 && doc.VatAmount > 0)
            {
                if (string.IsNullOrWhiteSpace(doc.LateReason))
                    warnings.Add($"§82/3: ใบกำกับเก่ากว่า 6 เดือน ({taxPoint:yyyy-MM-dd}, {monthsLate} เดือน) — ภาษีซื้อ {doc.VatAmount:N2} เคลม ภ.พ.30 ไม่ได้แล้ว. ถ้ายังต้องการอนุมัติ ให้กรอก LateReason (เหตุผลที่ใบมาช้า) ก่อน + ระบบจะ reclassify VAT เป็นค่าใช้จ่ายอัตโนมัติ");
                else
                    warnings.Add($"§82/3: ใบกำกับเก่ากว่า 6 เดือน ({monthsLate} เดือน, LateReason: '{doc.LateReason}') — ภาษีซื้อ {doc.VatAmount:N2} จะถูก reclassify เป็นค่าใช้จ่ายแทน claim ภพ.30");
            }
            else if (monthsLate >= 1 && monthsLate <= 6 && doc.VatAmount > 0
                     && string.IsNullOrWhiteSpace(doc.LateReason))
            {
                warnings.Add($"§82/3: ใบกำกับช้า {monthsLate} เดือน (tax point {taxPoint:yyyy-MM-dd}) — กรอก LateReason เพื่อ audit trail (ภายใน 6 เดือนยังเคลมได้)");
            }
        }

        // (§82/5(6) ด่านรถชุดที่สองที่เคยอยู่ตรงนี้ — ลิสต์คำของตัวเอง "น้ำมัน"/"ค่าซ่อม"/"fuel" เดี่ยว ๆ ⇒ เตือน
        //  ค่าซ่อมแอร์/น้ำมันพืช/fuel surcharge — ถูกรวมเข้าด่าน §82/5(4)(6) ข้างบนแล้ว ซึ่งใช้ลิสต์ชุดเดียว
        //  Helpers/InputVatVehicleRule + ธง IsVehicleDealer · รอบ 193 S-05)

        // Expense ที่มี VAT แต่ไม่ติ๊ก "ใช้งานใบกำกับภาษี" (HasTaxInvoiceReference
        // =false): §86/4 ไม่ครบ → เคลม VAT ไม่ได้ เตือนผู้ใช้ก่อน approve
        if (doc.DocumentType == DocumentType.Expense
            && doc.VatAmount > 0
            && !doc.HasTaxInvoiceReference)
            warnings.Add($"เอกสารค่าใช้จ่ายมี VAT {doc.VatAmount:N2} แต่ไม่ระบุข้อมูลใบกำกับ — §86/4 ไม่ครบ ภาษีซื้อจะลง 11640 (ยังไม่ถึงกำหนด) เคลมไม่ได้จนกว่าจะเติมข้อมูลใบ");

        // ติ๊ก "มีใบกำกับภาษีซื้อ" แล้วแต่ภาษีซื้อจะถูกพัก 11640 เพราะ §86/4 ไม่ครบ —
        // ตัดสินด้วยตัวตรวจ**ตัวเดียวกับ**ตัวลงบัญชี (ResolveInputVatAccountAsync)
        // (เดิมไม่มีคำเตือนเลย — ผู้ติดต่อไม่มีที่อยู่/เลข checksum ผิด/ใบจาก API ที่ไม่มี
        // เลขที่ใบกำกับ พักเงียบ ๆ ทั้งที่ผู้ใช้ประกาศเจตนาเคลม · รอบ 190 ทีม C)
        if (doc.DocumentType is DocumentType.PurchaseInvoice or DocumentType.Expense
                or DocumentType.PaymentVoucher)
        {
            var parkCheck = TaxInvoiceCompletenessChecker.Evaluate(doc, doc.Contact);
            var parkWarn = Accounting.Helpers.InputVatParkingNotice.Build(
                isPurchaseInputVatType: true,
                isForeignService: doc.IsForeignService,
                inputVatAccountCodeOverride: doc.InputVatAccountCodeOverride,
                claimableVat: doc.Lines?.Where(l => l.IsVatClaimable).Sum(l => l.VatAmount) ?? 0m,
                claimIntentDeclared: doc.HasTaxInvoiceReference,
                missingFields: parkCheck.MissingFields,
                missingContactFields: parkCheck.MissingContactFields);
            if (parkWarn != null) warnings.Add(parkWarn);
        }

        // Foreign currency without explicit FX rate (means the rate was
        // either captured at create-time or fell back to BoT) — surface so
        // operator can override with the contracted rate before posting.
        if (!string.Equals(doc.Currency, "THB", StringComparison.OrdinalIgnoreCase))
            warnings.Add($"สกุลเงิน {doc.Currency} (เรทใช้จริง {doc.ExchangeRate:F4}) — ถ้าเป็นเรทเช่าบริการ/สัญญา ให้อัพเดทก่อนอนุมัติ");

        // Stock-going-negative warning for the AR side. Allowed (back-orders
        // are legitimate) but the operator should be told before the GL
        // commits a sale we can't actually deliver.
        if (doc.DocumentType is DocumentType.Invoice or DocumentType.TaxInvoice)
        {
            var lineCodes = (doc.Lines ?? new List<DocumentLine>())
                .Where(l => !string.IsNullOrWhiteSpace(l.ProductCode))
                .Select(l => l.ProductCode!).Distinct().ToList();
            if (lineCodes.Count > 0)
            {
                var products = await _db.Products.AsNoTracking()
                    .Where(p => p.CompanyId == companyId && lineCodes.Contains(p.Code) && p.TrackStock && !p.IsDeleted)
                    .ToDictionaryAsync(p => p.Code);
                foreach (var line in doc.Lines ?? new List<DocumentLine>())
                {
                    if (string.IsNullOrWhiteSpace(line.ProductCode)) continue;
                    if (!products.TryGetValue(line.ProductCode!, out var product)) continue;
                    if (product.CurrentStock - line.Quantity < 0)
                        warnings.Add($"สินค้า '{product.Name}' คงเหลือ {product.CurrentStock} {product.Unit} จะติดลบ {Math.Abs(product.CurrentStock - line.Quantity):N2} หลังบันทึก (back-order)");
                }
            }
        }

        // Customer carrying past-due invoices — surface so the operator
        // chases collection before booking more AR with the same party.
        if (doc.DocumentType is DocumentType.Invoice or DocumentType.TaxInvoice or DocumentType.DebitNote)
        {
            var overdue = await _db.Documents.AsNoTracking()
                .Where(d => d.CompanyId == companyId && d.ContactId == doc.ContactId
                    && d.Id != doc.Id && !d.IsDeleted
                    && (d.Status == DocumentStatus.Approved || d.Status == DocumentStatus.PartiallyPaid || d.Status == DocumentStatus.Overdue)
                    && d.AgingDays != null && d.AgingDays > 30)
                .Select(d => new { d.DocumentNumber, d.BalanceDue, d.AgingDays })
                .ToListAsync();
            if (overdue.Count > 0)
            {
                var total = overdue.Sum(d => d.BalanceDue);
                warnings.Add($"ผู้ติดต่อนี้ยังค้างชำระ {overdue.Count} ใบ รวม {total:N2} THB — ตรวจวงเงินเครดิตก่อนอนุมัติเอกสารใหม่");
            }
        }

        // ===== Thai-accounting completeness checks (RD requirements) =====

        // 1. Tax Invoice must carry the buyer's full address (ที่อยู่ผู้ซื้อ)
        //    per ป.86/4 — without it the document isn't a valid full tax
        //    invoice and the buyer can't claim input VAT.
        if (doc.DocumentType == DocumentType.TaxInvoice && doc.Contact != null)
        {
            var hasAddr = !string.IsNullOrWhiteSpace(doc.Contact.Address)
                || !string.IsNullOrWhiteSpace(doc.Contact.Province)
                || !string.IsNullOrWhiteSpace(doc.Contact.District);
            if (!hasAddr)
                warnings.Add($"ใบกำกับภาษีต้องระบุที่อยู่ผู้ซื้อ ('{doc.Contact.Name}' ยังไม่มีที่อยู่) — ตามมาตรา 86/4 ผู้ซื้อใช้เป็นหลักฐานภาษีซื้อไม่ได้");
            // Thai corporate Tax ID is exactly 13 digits.
            var tid = new string((doc.Contact.TaxId ?? "").Where(char.IsDigit).ToArray());
            if (!string.IsNullOrEmpty(tid) && tid.Length != 13)
                warnings.Add($"เลขประจำตัวผู้เสียภาษีของ '{doc.Contact.Name}' มี {tid.Length} หลัก (ต้อง 13 หลัก) — ตรวจก่อนออกใบกำกับภาษี");
        }

        // 2. When WHT is withheld, a 50 ทวิ certificate must be issued to the
        //    payee. Flag so the operator generates it (PND filing depends on it).
        if (doc.WithholdingTaxAmount > 0 && doc.DocumentType is DocumentType.PaymentVoucher or DocumentType.PurchaseInvoice or DocumentType.Expense)
            warnings.Add($"มีการหักภาษี ณ ที่จ่าย {doc.WithholdingTaxAmount:N2} THB — อย่าลืมออกหนังสือรับรองหัก ณ ที่จ่าย (50 ทวิ) ให้ผู้รับเงิน และยื่น ภ.ง.ด. ตามกำหนด");

        // 2b. A VAT PurchaseInvoice needs the SUPPLIER's own tax-invoice number
        //     + date — the input VAT must be claimed in the period of the
        //     supplier's invoice (มาตรา 82/4), which can differ from our
        //     booking date. Without them the ภ.พ.30 input-VAT trail is broken.
        if (doc.DocumentType == DocumentType.PurchaseInvoice && doc.VatAmount > 0)
        {
            if (string.IsNullOrWhiteSpace(doc.SupplierInvoiceNumber))
                warnings.Add("ใบแจ้งหนี้ซื้อที่มี VAT ยังไม่ได้ระบุเลขใบกำกับภาษีของผู้ขาย — ต้องมีเพื่อเคลมภาษีซื้อ (มาตรา 82/4)");
            if (doc.SupplierTaxInvoiceDate == null)
                warnings.Add("ใบแจ้งหนี้ซื้อที่มี VAT ยังไม่ได้ระบุวันที่ใบกำกับภาษีของผู้ขาย — ใช้กำหนดงวด ภ.พ.30 ที่เคลมภาษีซื้อ");
        }

        // 3. Credit Note should reference the original invoice it adjusts
        //    (มาตรา 86/10). CreditNoteReason is already enforced; this nudges
        //    for the source link so VAT reversal ties back to the original.
        if (doc.DocumentType == DocumentType.CreditNote && doc.RelatedDocumentId == null)
            warnings.Add("ใบลดหนี้ยังไม่ได้อ้างอิงใบกำกับภาษี/ใบแจ้งหนี้ต้นฉบับ — ตามมาตรา 86/10 ควรระบุเลขที่และวันที่เอกสารเดิมที่ลดหนี้");

        // 3b. §86/9-10: CN/DN ต้องออกในเดือนภาษีที่เกิดเหตุ (คืนของ/แก้ราคา)
        //     หรือเดือนถัดไป — อนุมัติใบที่ลงวันที่ย้อนหลังข้ามงวดโดยไม่มีเหตุผล
        //     = ภ.พ.30 งวดนั้นถูกยื่นไปแล้วโดยไม่มีแถวนี้ → ต้องยื่นเพิ่มเติม
        if (doc.DocumentType is DocumentType.CreditNote or DocumentType.DebitNote)
        {
            // เทียบ "เดือนภาษี" ต้องใช้เวลาไทย (UTC+7) — ใช้ UTC ดิบทำให้ช่วง
            // เช้ามืดวันที่ 1 (เวลาไทย) ยังนับเป็นเดือนก่อน → warning หายผิดจังหวะ
            var now = DateTime.UtcNow.AddHours(7);
            var monthsBack = (now.Year - doc.DocumentDate.Year) * 12 + (now.Month - doc.DocumentDate.Month);
            if (monthsBack > 1 && string.IsNullOrWhiteSpace(doc.LateReason))
                warnings.Add(
                    $"§86/9-10: {(doc.DocumentType == DocumentType.CreditNote ? "ใบลดหนี้" : "ใบเพิ่มหนี้")}ลงวันที่ "
                    + $"{doc.DocumentDate:yyyy-MM-dd} ย้อนหลังเกิน 1 เดือนภาษี — ตามกฎต้องออกในเดือนที่เกิดเหตุ"
                    + " (คืนของ/ลดราคา) หรือเดือนถัดไป. ถ้าจำเป็น กรอกเหตุผลความล่าช้า (LateReason) เพื่อ audit trail"
                    + " และตรวจว่าต้องยื่น ภ.พ.30 เพิ่มเติมของงวดนั้นหรือไม่");

            // 3c. CN/DN มี VAT ที่อ้าง "ใบแจ้งหนี้" (Invoice) — ใบแจ้งหนี้ไม่ใช่
            //     ใบกำกับภาษี. ถ้าการขายนั้นมีใบกำกับจริงแยก (TIV / ใบเสร็จถือ VAT
            //     ที่ออกคู่กัน) ต้องอ้างใบนั้นแทน — เลขที่บนกระดาษ CN ต้องตรงกับ
            //     เลขใบกำกับที่ลูกค้าถือ ไม่งั้นสรรพากรจับคู่ไม่ได้
            if (doc.VatAmount > 0.005m && doc.RelatedDocumentId.HasValue)
            {
                var cnRefType = await _db.Documents.AsNoTracking()
                    .Where(d => d.Id == doc.RelatedDocumentId.Value && d.CompanyId == companyId)
                    .Select(d => (DocumentType?)d.DocumentType)
                    .FirstOrDefaultAsync();
                if (cnRefType == DocumentType.Invoice)
                    warnings.Add(
                        "§86/9-10: เอกสารอ้างอิงเป็น \"ใบแจ้งหนี้\" ซึ่งไม่ใช่ใบกำกับภาษี — ถ้าการขายนี้มี"
                        + "ใบกำกับภาษีแยก (ใบกำกับ/ใบเสร็จรับเงินที่ถือ VAT ออกคู่กัน) ต้องออกใบลดหนี้/เพิ่มหนี้"
                        + "อ้างใบนั้นแทน ให้เลขที่บนกระดาษตรงกับใบกำกับที่ลูกค้าถืออยู่");
            }

            // 3d. ใบเพิ่มหนี้ต้องระบุ "สาเหตุ" บนกระดาษ (§86/9 — ราคาสินค้า/ค่าบริการ
            //     เพิ่มขึ้นเพราะอะไร) — ระบบพิมพ์จากช่องหมายเหตุ
            if (doc.DocumentType == DocumentType.DebitNote && string.IsNullOrWhiteSpace(doc.Notes))
                warnings.Add("§86/9: ใบเพิ่มหนี้ควรระบุสาเหตุการเพิ่มหนี้ในช่อง \"หมายเหตุ\" "
                    + "(เช่น ราคาสินค้าปรับขึ้น/คำนวณต่ำกว่าจริง/ค่าขนส่งเพิ่ม) — ข้อความนี้จะพิมพ์บนใบให้ลูกค้า");

            // 3e. ใบเดิม "นอกระบบ" (อ้างด้วยเลข text ที่ไม่ match เอกสารในระบบ —
            //     ถ้า match ระบบ resolve เป็น RelatedDocumentId ตอนอนุมัติแล้วเข้า
            //     cap §86/10 ปกติ): cap อัตโนมัติทำไม่ได้เพราะไม่รู้ยอดใบเดิม →
            //     เตือนยอด CN สะสมต่อเลขอ้างอิงเดียวกัน ให้นักบัญชีเทียบกับกระดาษเอง
            if (doc.DocumentType == DocumentType.CreditNote
                && doc.RelatedDocumentId == null && !string.IsNullOrWhiteSpace(doc.Reference))
            {
                var extRef = doc.Reference.Trim();
                var refMatchesInternal = await _db.Documents.AsNoTracking().AnyAsync(d =>
                    d.CompanyId == companyId && d.DocumentNumber == extRef && d.Id != doc.Id && !d.IsDeleted);
                if (!refMatchesInternal)
                {
                    var siblingSum = await _db.Documents.AsNoTracking()
                        .Where(d => d.CompanyId == companyId && d.Id != doc.Id
                            && d.DocumentType == DocumentType.CreditNote
                            && d.RelatedDocumentId == null && d.Reference == extRef
                            && d.Status != DocumentStatus.Draft && d.Status != DocumentStatus.Voided
                            && d.Status != DocumentStatus.Rejected && !d.IsDeleted)
                        .SumAsync(d => (decimal?)d.TotalAmount) ?? 0m;
                    if (siblingSum > 0)
                        warnings.Add(
                            $"§86/10: มีใบลดหนี้อื่นอ้างเลขใบกำกับนอกระบบ \"{extRef}\" อยู่แล้วรวม {siblingSum:N2} บาท "
                            + $"— รวมใบนี้เป็น {siblingSum + doc.TotalAmount:N2} บาท. ระบบตรวจ cap อัตโนมัติไม่ได้ "
                            + "(ใบเดิมอยู่นอกระบบ) กรุณาเทียบกับยอดใบกำกับจริงว่าลดหนี้รวมไม่เกินยอดเดิม");
                }
            }
        }

        // 4. Cash-settled Payment Voucher (จ่ายทันที) must NOT post to a
        //    payable (เจ้าหนี้) account — the money already left, so a 2xx
        //    liability debit/credit on a line is a modelling error. This is
        //    the consistency guard the user asked for.
        if (doc.DocumentType == DocumentType.PaymentVoucher
            && doc.PaymentType == Models.Enums.PaymentType.Cash)
        {
            var lineAccountIds = (doc.Lines ?? new List<DocumentLine>()).Where(l => l.AccountId.HasValue).Select(l => l.AccountId!.Value).Distinct().ToList();
            if (lineAccountIds.Count > 0)
            {
                var payableCodes = await _db.ChartOfAccounts.AsNoTracking()
                    .Where(a => a.CompanyId == companyId && lineAccountIds.Contains(a.Id)
                        && (a.AccountType == AccountType.Liability || a.AccountCode.StartsWith("2")))
                    .Select(a => a.AccountCode + " " + a.AccountName)
                    .ToListAsync();
                if (payableCodes.Count > 0)
                    warnings.Add($"ใบสำคัญจ่ายแบบจ่ายทันทีไม่ควรลงบัญชีเจ้าหนี้/หนี้สิน ({string.Join(", ", payableCodes)}) — ถ้าเป็นการตั้งหนี้ ให้เลือกประเภทเป็น 'เครดิต' แทน");
            }
        }

        // 5. Contact still active? A document whose counterparty was
        //    deleted/deactivated between create and approve would still post
        //    to that party's AP/AR — surface it so the operator re-checks.
        if (doc.Contact != null && (doc.Contact.IsDeleted || !doc.Contact.IsActive))
            warnings.Add($"ผู้ติดต่อ '{doc.Contact.Name}' ถูกลบหรือปิดใช้งานแล้ว — ตรวจสอบก่อนอนุมัติ (ยอดจะลงบัญชีลูกหนี้/เจ้าหนี้ของผู้ติดต่อรายนี้)");

        // 6. Possible duplicate — another non-voided document for the SAME
        //    contact + same total + within ±1 day. Catches a double-entry /
        //    double-upload before it hits the GL twice.
        var dupFrom = doc.DocumentDate.Date.AddDays(-1);
        var dupTo = doc.DocumentDate.Date.AddDays(1);
        var dup = await _db.Documents.AsNoTracking()
            .Where(d => d.CompanyId == companyId && d.Id != doc.Id && !d.IsDeleted
                && d.ContactId == doc.ContactId
                && d.DocumentType == doc.DocumentType
                && d.Status != DocumentStatus.Voided && d.Status != DocumentStatus.Draft
                && d.TotalAmount == doc.TotalAmount
                && d.DocumentDate >= dupFrom && d.DocumentDate <= dupTo)
            .Select(d => d.DocumentNumber)
            .FirstOrDefaultAsync();
        if (dup != null)
            warnings.Add($"อาจเป็นเอกสารซ้ำ — มี {dup} ของผู้ติดต่อรายนี้ ยอด {doc.TotalAmount:N2} ในช่วงวันที่เดียวกัน ตรวจสอบก่อนอนุมัติ");

        // 7. รอบ 193 (คำตัดสินเจ้าของข้อ 12): เอกสารจากสแกนที่ตอนสร้างระบบพบ "ยอดไม่ตรงกระดาษ" ([Σ-GAP]) —
        //    เว็บ/มือถือต้องกด "รับทราบ" (audit APPROVE-ACK-WARNINGS ด้านบน) · API แยกคำเตือนชุดนี้ด้วย
        //    OcrApprovalGapWarning.IsGapWarning แล้วไม่ขัดจังหวะ (DocumentsV1Controller) · ข้อความ+ตัวเลขจาก helper ตัวเดียว
        var gapScan = await _db.Set<OcrScanResult>().AsNoTracking()
            .Where(r => r.CompanyId == companyId && r.CreatedDocumentId == doc.Id)
            .OrderByDescending(r => r.CreatedAt)
            .Select(r => new { r.ProcessingNotes, r.ExtractedTotalAmount })
            .FirstOrDefaultAsync();
        if (gapScan != null)
        {
            var liveLines = doc.Lines.Where(l => !l.IsDeleted).ToList();
            warnings.AddRange(Accounting.Helpers.OcrApprovalGapWarning.Build(
                gapScan.ProcessingNotes, gapScan.ExtractedTotalAmount,
                liveLines.Sum(l => l.Amount + l.VatAmount) + doc.RoundingAdjustment));
        }

        return warnings;
    }
}

/// <summary>Thrown by ApproveDocumentAsync when the pre-approval validator
/// surfaces soft warnings AND the request didn't carry AcknowledgeWarnings.
/// Controllers catch this and return HTTP 422 with the warning list so the
/// frontend can prompt the operator and retry with the acknowledge flag.</summary>
public class DocumentApprovalWarningsException : Exception
{
    public IReadOnlyList<string> Warnings { get; }

    /// <summary>AI-enriched per-warning suggestions. NULL when AI is
    /// disabled / unreachable. Each item corresponds to Warnings[i] by
    /// index — pair them in the UI.</summary>
    public IReadOnlyList<DocumentApprovalAiHint>? AiHints { get; }

    public DocumentApprovalWarningsException(
        IReadOnlyList<string> warnings,
        IReadOnlyList<DocumentApprovalAiHint>? aiHints = null)
        : base("เอกสารมีจุดที่ต้องตรวจก่อนยืนยันการอนุมัติ (" + warnings.Count + " รายการ)")
    {
        Warnings = warnings;
        AiHints = aiHints;
    }

    /// <summary>ข้อความเหตุผลที่ "อนุมัติไม่สำเร็จ" สำหรับทางอนุมัติที่ไม่มีหน้าต่างยืนยันคำเตือน
    /// (OCR อนุมัติอัตโนมัติ → <c>[APPROVE-FAIL]</c> · ปุ่ม LINE) — ต้องบอก<b>ตัวคำเตือน</b> ไม่ใช่แค่จำนวน
    /// <para>ที่มา (ฝ่ายค้านรอบ 190): คำเตือน "ภาษีซื้อจะถูกพัก 11640" ทำให้ใบจากสแกนค้าง Draft
    /// แต่ผู้ใช้เห็นแค่ "มีจุดที่ต้องตรวจ (1 รายการ)" — ไม่รู้ว่าต้องไปแก้อะไรที่ไหน</para></summary>
    public static string DescribeForUser(Exception ex)
        => ex is DocumentApprovalWarningsException w && w.Warnings.Count > 0
            ? w.Message + ": " + string.Join(" · ", w.Warnings)
            : ex.Message;
}

/// <summary>
/// AI-generated per-warning hint. Surfaced alongside the warning text
/// in the approval-confirmation modal so the user sees "Acknowledge / Edit
/// / Block" + suggested actions per item.
/// </summary>
public sealed record DocumentApprovalAiHint(
    // "Acknowledge" | "Edit" | "Block" — **สตริงว่าง = ไม่มีใครตอบ**
    // (AI ปิด/ล่ม และนักเรียนยังไม่มีคลัง) หน้าจอต้องไม่ขึ้นป้ายและต้องไม่
    // บันทึก feedback ในกรณีนั้น · ดู Helpers/AiHintAnswer
    string Primary,
    decimal Confidence,
    string? Reasoning,
    IReadOnlyList<string> SuggestedActions,
    IReadOnlyList<string> Risks,
    IReadOnlyList<string> ComplianceFlags,
    Guid? FeedbackId,
    bool UsedAi);
